using ECommerce.Application.DTOs.Order;
using ECommerce.Domain.Entities;
using Microsoft.AspNetCore.Identity;
using Microsoft.AspNetCore.Identity.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore;
using System.Collections.Generic;

namespace ECommerce.Infrastructure.Persistence;

public class AppDbContext : IdentityDbContext<User>
{
    //database context that EF Core uses
   
        public AppDbContext(DbContextOptions<AppDbContext> options)
            : base(options)
        {
        }


    public DbSet<Product> Products => Set<Product>();
    public DbSet<Category> Categories => Set<Category>();
    public DbSet<Order> Orders => Set<Order>();
    public DbSet<CartItem> CartItems => Set<CartItem>();
    public DbSet<Publish> Publishes => Set<Publish>();
    public DbSet<WishlistItem> WishlistItems => Set<WishlistItem>();
    public DbSet<Contact> Contacts => Set<Contact>();
    public DbSet<ProductRating> ProductRatings => Set<ProductRating>();

    private static readonly DateTime SeedDate = new DateTime(2026, 10, 29, 0, 0, 0, DateTimeKind.Utc);

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        base.OnModelCreating(modelBuilder); 

        modelBuilder.Entity<Product>()
         .Property(p => p.Price)
         .HasPrecision(18, 2);

        // Catalogue indexes: default sort, category and top-rated listings, price and date filters.
        modelBuilder.Entity<Product>().HasIndex(p => p.CreatedAt).IsDescending();
        modelBuilder.Entity<Product>().HasIndex(p => new { p.CategoryId, p.CreatedAt });
        modelBuilder.Entity<Product>().HasIndex(p => new { p.TopRated, p.CreatedAt });
        modelBuilder.Entity<Product>().HasIndex(p => p.Price);
        modelBuilder.Entity<Product>().HasIndex(p => p.PublishDate);

        modelBuilder.Entity<OrderItem>()
            .Property(oi => oi.Price)
            .HasPrecision(18, 2);

        modelBuilder.Entity<CartItem>()
            .ToTable("CartItem");

        modelBuilder.Entity<CartItem>()
            .Property(c => c.Price)
            .HasPrecision(18, 2);

        // CartItem.UserId holds either a user id or a guest key ("guest:<guid>"), so it is not a foreign key.
        modelBuilder.Entity<CartItem>().Ignore(c => c.User);
        modelBuilder.Entity<CartItem>().HasIndex(c => c.UserId);

        modelBuilder.Entity<CartItem>()
            .HasOne(c => c.Product)
            .WithMany()
            .HasForeignKey(c => c.ProductId)
            .OnDelete(Microsoft.EntityFrameworkCore.DeleteBehavior.Restrict);

        modelBuilder.Entity<WishlistItem>()
            .ToTable("WishlistItem");

        modelBuilder.Entity<WishlistItem>()
            .HasOne(w => w.User)
            .WithMany()
            .HasForeignKey(w => w.UserId)
            .OnDelete(Microsoft.EntityFrameworkCore.DeleteBehavior.Cascade);

        modelBuilder.Entity<WishlistItem>()
            .HasOne(w => w.Product)
            .WithMany()
            .HasForeignKey(w => w.ProductId)
            .OnDelete(Microsoft.EntityFrameworkCore.DeleteBehavior.Restrict);

        // Map relationship explicitly (optional for guest checkout)
        modelBuilder.Entity<Order>()
            .HasOne(o => o.User)
            .WithMany()
            .HasForeignKey(o => o.UserId)
            .IsRequired(false);

        modelBuilder.Entity<Order>()
            .Property(o => o.DeliveryFee)
            .HasPrecision(18, 2);

        modelBuilder.Entity<Publish>()
            .ToTable("Publish");
        modelBuilder.Entity<Contact>()
            .ToTable("Contact");
        modelBuilder.Entity<ProductRating>(e =>
        {
            e.ToTable("ProductRating");
            e.Property(r => r.OwnerKey).HasMaxLength(80).IsRequired();
            e.HasIndex(r => new { r.ProductId, r.OwnerKey }).IsUnique(); // one rating per visitor and book
            e.HasOne(r => r.Product).WithMany().HasForeignKey(r => r.ProductId).OnDelete(DeleteBehavior.Cascade);
        });
        modelBuilder.Entity<Publish>()
            .HasOne(p => p.User)
            .WithMany()
            .HasForeignKey(p => p.UserId)
            .OnDelete(Microsoft.EntityFrameworkCore.DeleteBehavior.Cascade);

        // Catalogue seed. Ids start at 1; dates are fixed so migrations stay stable.
        // Top-rated books (ids from 1). Prices other than أرخبيل الملوك are provisional.
        modelBuilder.Entity<Category>().HasData(
            new { Id = 1, Name = "اجتماعي ودراما", CreatedAt = SeedDate },
            new { Id = 2, Name = "فانتازيا وخيال علمي", CreatedAt = SeedDate },
            new { Id = 3, Name = "جريمة وغموض وإثارة", CreatedAt = SeedDate },
            new { Id = 4, Name = "رومانسي", CreatedAt = SeedDate },
            new { Id = 5, Name = "تدريب وهوايات", CreatedAt = SeedDate },
            new { Id = 6, Name = "نفسي", CreatedAt = SeedDate },
            new { Id = 7, Name = "تاريخي وسير", CreatedAt = SeedDate },
            new { Id = 8, Name = "فكر وثقافة", CreatedAt = SeedDate },
            new { Id = 9, Name = "رعب", CreatedAt = SeedDate },
            new { Id = 10, Name = "فانتازيا فلسفية", CreatedAt = SeedDate },
            new { Id = 11, Name = "أطفال", CreatedAt = SeedDate }
        );
        modelBuilder.Entity<Product>().HasData(
            new { Id = 1, Name = "بعد فارق", Price = 250m, Stock = 10, Description = "رواية فانتازيا بأبعاد فلسفية ونفسية. بين «عبّار» و«فارق» تجد نفسك في رحلة تواجه فيها كل ما تهرب منه، بلا سبيل للفرار من الحقيقة. رحلة مليئة بالخبايا والأسرار بين الحقيقة والزيف، والتعلّق والهروب، هدفها الوصول إلى الحقيقة وحدها.", CategoryId = 10, ImageUrl = "/images/products/baad-fariq.webp", Author = "نوران بسيوني", PublishDate = SeedDate, TopRated = true, CreatedAt = SeedDate },
            new { Id = 2, Name = "أرخبيل الملوك", Price = 200m, Stock = 10, Description = "تجربة فانتازيا ليست بعيدة عن واقعنا؛ فالحياة مليئة باختبارات سهلة وصعبة، وما يبدو سهلًا قد يحمل جوهر الصعوبة. بين الاختيارات ومعرفة الحقيقة التي تتغيّر مع زيادة الوعي تتشكّل رحلتنا في «أرخبيل الملوك»: رحلة عالية المخاطر بين البقاء والتحرر، تجمع الحركة المكثفة بالأسئلة الفلسفية العميقة.", CategoryId = 2, ImageUrl = "/images/products/arkhabil-el-molouk.webp", Author = "ممدوح عماد", PublishDate = SeedDate, TopRated = true, CreatedAt = SeedDate },
            new { Id = 3, Name = "طيف نجاة", Price = 250m, Stock = 10, Description = "بين أعباء الحياة وسباتها المستمر والتوغل في أحلام الآخرين، نفقد جزءًا من أرواحنا ونغدو أحياءً بأجساد هامدة. لكن ماذا لو قررت كسر هذه الدائرة وبدأت رحلتك وفق قواعدك وأحلامك؟ رحلة تكون فيها البطل، تبحث خلالها عن معنى لحياتك وعن ذاتك الحقيقية.", CategoryId = 1, ImageUrl = "/images/products/tayf-najah.webp", Author = "آية المنشاوي", PublishDate = SeedDate, TopRated = true, CreatedAt = SeedDate },
            new { Id = 4, Name = "لوحة أخيرة", Price = 200m, Stock = 10, Description = "تنقلب حياة طبيب نفسي ناجح بعد وفاة والدته، الرسامة الشهيرة المنعزلة، حين يكتشف بالصدفة تسجيلات قديمة ودفاتر تخفي أسرارًا لم يعرفها عنها من قبل. رواية عن الفقد والذاكرة، وعمّا تخبئه اللوحات خلف ألوانها.", CategoryId = 1, ImageUrl = "/images/products/lawha-akhira.webp", Author = "علياء المنشاوي", PublishDate = SeedDate, TopRated = true, CreatedAt = SeedDate },
            new { Id = 5, Name = "حلقة الذنب", Price = 250m, Stock = 10, Description = "ليست مجموعة قصص وحسب، بل نسيج متشابك بين الدراما والفانتازيا: رحلة بخمس تجارب مختلفة مع الشعور بالذنب، حين يتحول من سؤال بريء ينم عن رغبة صاحبه في أن يصبح شخصًا أفضل إلى حلقة مفرغة لا تنتهي من شعور يأكله ببطء. ليس بالضرورة أن تدخل حلقة الذنب بقرار واعٍ.", CategoryId = 1, ImageUrl = "/images/products/halaqat-al-dhanb.webp", Author = "ممدوح عماد، نوران بسيوني، رانا رؤوف، آية المنشاوي", PublishDate = SeedDate, TopRated = true, CreatedAt = SeedDate },
            new { Id = 6, Name = "طلبك مرفوض", Price = 200m, Stock = 10, Description = "كل مرة تتعرض فيها للرفض وتنغلق على نفسك وتسألها: لماذا اخترت أن أكون في هذا المكان؟ تجد إجابة واحدة في انتظارك كل مرة. رواية عن الرفض والإصرار، وعن البحث عن مكانك الحقيقي.", CategoryId = 4, ImageUrl = "/images/products/talabak-marfoud.webp", Author = "رانا رؤوف", PublishDate = SeedDate, TopRated = true, CreatedAt = SeedDate },
            new { Id = 7, Name = "cerca trova", Price = 400m, Stock = 10, Description = "“Cerca Trova” is a gripping international thriller inspired by true stories from the world of humanitarian work. The novel follows an international delegate dedicated to Restoring Family Links, searching for relatives separated by war, disasters, and forced displacement.\n\nFrom conflict zones to fragile border crossings, each mission is a race against time, where a single document, a forgotten name, or a faint clue can reunite a family or close a chapter forever.\nCombining thrill, adventure, and deep emotional resonance, Cerca Trova transforms real humanitarian experiences into compelling fiction that is both fast-paced and profoundly human", CategoryId = 1, ImageUrl = "/images/products/9789778203295.webp", Author = "تامر أحمد", PublishDate = new DateTime(2026, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778203295", Pages = 552, Size = "14×20" },
            new { Id = 8, Name = "A fire with no spark", Price = 420m, Stock = 10, Description = "Vessels have sunk. Chaos has fallen. The rainy season has begun.\n\nAmid terrified survivors and mercenaries scrambling for escape,\nmadra is running low, and shadowed tunnels lead toward unknown fates.\n\nOne choice could save them all, or turn everything to ash.\n\nThis is not the end of the journey.\nThis is the moment of reckoning.\n\nWill Adam face the cost of his decision?\nWhat became of Rawan?\nAnd will Mike return?\n\nWho will survive… and who will be claimed by the living fire?", CategoryId = 2, ImageUrl = "/images/products/9789778203400.webp", Author = "د. خوله حمدي", PublishDate = new DateTime(2026, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778203400", Pages = 506, Size = "14×20" },
            new { Id = 9, Name = "اتنين فى واحد", Price = 260m, Stock = 10, Description = "ماذا لو تحقّقت أمنيتك المستحيلة؟\nوماذا لو اكتشفت أن تحقيقها له ثمن؟\nزوج أناني يرى الزواج عبئًا لا يُحتمل، يستيقظ ليجد حياته انقلبت بالكامل.\nزوجته التي أنهكها التعب والشكوى، تصبح فجأة زوجة مثالية.. لا تشكو.. لا تتعب.. ولا تنام!!!\nفي البداية يبدو كل شيء مثاليًا..\nثم يبدأ الغموض. صمت غير مريح.\nنظرات لا تُفهم، وتفاصيل تختفي بلا تفسير.\nالطمأنينة تتحوّل إلى خوف صامت.\nوما حدث ليس نعمة، ولا يمكن التراجع عنه بسهولة.\nكل إجابة تقوده إلى طريق أكثر خطورة، وكل تأخير يقرّبه من خسارة لا تُعوّض.\nفي النهاية، إما أن يكسر الوهم…\nأو يختار الاستمرار… حتى النهاية.", CategoryId = 1, ImageUrl = "/images/products/9789778203226.webp", Author = "معتز شرباش", PublishDate = new DateTime(2026, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778203226", Pages = 306, Size = "14×20" },
            new { Id = 10, Name = "آخر رجال الهيلمان", Price = 300m, Stock = 10, Description = "ختفى ليلة تخرجه.\nسُجِّل ميتًا.\nثم عاد.\nلا ليعيش،\nبل ليواجه.\n\nعشرون عامًا من الصمت تُخفي مهمة سرية، وخيانة، وسرًا رقميًا تخشاه منظمة أقوى من دول.\nكل خطوة محسوبة.\nكل جرح مقصود.\n\nفي الشوارع، حرب بلا شهود.\nعمليات دقيقة بلا أثر.\n\nوبينما يضيق الخناق، تتكشف خطة لا تُرى،\nونهاية لا تشبه أي توقع.\n\n«رجال الهيلمان»\nعن الثمن الحقيقي للبطولة.", CategoryId = 3, ImageUrl = "/images/products/9789778203363.webp", Author = "يحيى صفوت", PublishDate = new DateTime(2026, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778203363", Pages = 368, Size = "14×20" },
            new { Id = 11, Name = "أطلقني", Price = 330m, Stock = 10, Description = "رواية رومانسية ديستوبية من عالم سلسلة Shatter Me للكاتبة طاهرة ماڤي، ترجمة ضحى صلاح. حكاية عن حب يولد في عالم قاسٍ، وقوى خارقة تخيف أصحابها قبل الآخرين، وعن شجاعة أن تتحرر من الخوف.", CategoryId = 4, ImageUrl = "/images/products/9789778203134.webp", Author = "طاهرة ماڤي", PublishDate = new DateTime(2026, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778203134", Pages = 240, Size = "14×20" },
            new { Id = 12, Name = "أفهم كلبك", Price = 130m, Stock = 10, Description = "الكلب اللي بيعض مش دايمًا شرس، واللي بيخاف مش دايمًا ضعيف، واللي بيتجاهلك مش دايمًا عنيد\".\nالكلب قصة حقيقية أشبه بقصصنا، تجارب، وملاحظة وحياة بيعيشها بتخليه يكتسب صفاته اللي بنشوفها.", CategoryId = 5, ImageUrl = "/images/products/9786339957543.webp", Author = "محمود فادي", PublishDate = new DateTime(2026, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786339957543", Pages = 166, Size = "14×20" },
            new { Id = 13, Name = "أقرب إلى النور", Price = 240m, Stock = 10, Description = "حيث يتقاطع الحب مع الأذى، تنكشف هشاشة القلب وصلابته معًا. في تلك المساحة الرمادية بين القرب والخذلان، تبدأ الحكاية.\nبين الفوضى والهوس، تعيش امرأة ممزّقة بين مسؤوليات ثقيلة، وعلاقة تُربك صورتها عن نفسها وتعيدها مرارًا إلى الدائرة ذاتها.\nلا يأتي النضج كخلاصٍ مفاجئ، بل يتشكّل ببطء، عبر محاولات متعثّرة للفهم، وحياة يومية مليئة بالأسئلة.\n\nأقرب إلى النور..\nتغوص في المناطق الخفية للعلاقات، وتفكّك الروابط التي تصوغ اختياراتنا، حين نحب بالطريقة التي تعلّمنا بها البقاء.\n\nرواية لا تعد بالنجاة السهلة، بل بالوعي، والتصالح مع الذات، حين يصبح الألم مُعلّمًا لا سجنًا، وحين نعرف لماذا تألّمنا، لا فقط كيف؛\nلتبدأ رحلة حقيقية نحو التعافي… والاقتراب أكثر من النور.", CategoryId = 6, ImageUrl = "/images/products/9789778203110.webp", Author = "هدى عبدالمنعم", PublishDate = new DateTime(2026, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778203110", Pages = 272, Size = "14×20" },
            new { Id = 14, Name = "الأفرنجى", Price = 350m, Stock = 10, Description = "تدور الرواية في القرن الثالث عشر، بعد هزيمة الحملة الصليبية وأسر عدد من الفرنجة في مصر.\nالبطل فارس أوروبي يقع في الأسر، يُنقل بين السجون، ويذوق الإهانة والعجز، ثم تنقلب حياته حين يخرج من الأسر إلى الحرية.\nوبسبب مرض يصيبه، يجد طريقه إلى الفسطاط، حيث تستقبله أسرة مصرية مسيحية، وتبدأ مرحلة جديدة من حياته.\nليتعرّف على مدينة نابضة، تتجاور فيها الكنيسة والمسجد والمعبد، ويخالط أطباء وعلماء ورجال دين، ويرى القاهرة والفسطاط من الداخل.\nلا كأرض عدو،\nبل كعالم إنساني نابض بالحياة.", CategoryId = 7, ImageUrl = "/images/products/9789778203141.webp", Author = "أيمن رجب طاهر", PublishDate = new DateTime(2026, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778203141", Pages = 458, Size = "14×20" },
            new { Id = 15, Name = "على أوتار الباسنكوب", Price = 200m, Stock = 10, Description = "على أرض لم تعترف يومًا بالحدود.\nتدور حكاية لا تشبه ما قيل في الأخبار.\n\nفي قلب مثلث حلايب.\nحيث يعيش شعب البجا كما عاشوا دائمًا،\nبالرعي، بانتظار المطر.\nوبعلاقة قديمة مع الأرض لا تحتاج إلى خرائط.\n\nوحين يتغير المشهد، لا يتغير المكان فقط،\nبل تتولد الأسئلة. من نحن؟\nولمن ننتمي!!\n\nرواية عن الهوية حين تصبح عبئًا.\nوعن الأرض حين تطلب ثمن البقاء.\nوعن الإنسان حين يُجبر على الاختيار.\nدون أن يكون مستعدًا.\n\nحين يصبح الانتماء أصعب من الرحيل.\nوهل الوطن قرار أم قدر؟", CategoryId = 7, ImageUrl = "/images/products/9789778203370.webp", Author = "عبدالرحمن شاكر", PublishDate = new DateTime(2026, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778203370", Pages = 242, Size = "14×20" },
            new { Id = 16, Name = "عجلة الزمن : التنين العائد (مجلدين)", Price = 875m, Stock = 10, Description = "في «التنين العائد»، الرواية الثالثة من ملحمة «عجلة الزمن»، يجد راند ألثور نفسه أمام خيار واحد لا مفر منه؛ أن يواجه مصيره أو يُصاب بالجنون وهو يحاول الهروب منه.\nالشتاء أوقف الحرب… لكنه لم يوقف الموت. الرجال يموتون في كل مكان وهم يهتفون باسم «التنين»، والكل يتساءل: أين هو المخلّص؟\nيقرر راند الانطلاق وحيدًا في رحلة يائسة نحو قلعة أسطورية لم تسقط قط. هناك، خلف جدران لا تُقهر، يقبع اختبار رهيب.\nالآن، يجب على مويرين ورفاقها خوض سباق محموم ضد الزمن ووحوش الظلام للحاق به، لأن فشل راند هذه المرة لا يعني الموت فحسب… بل يعني تسليم العالم لظلام أبدي.\nالنبلاء يتآمرون، والظلال تتحرك، والعالم يحبس أنفاسه… خطوة واحدة تفصل بين المخلّص المنتظر… والمجنون الذي قد يدمّر العالم.", CategoryId = 2, ImageUrl = "/images/products/9789778203127.webp", Author = "روبرت چوردان", PublishDate = new DateTime(2026, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778203127", Pages = 982, Size = "14×20" },
            new { Id = 17, Name = "ألغاز وتسالي للكبار", Price = 120m, Stock = 10, Description = "كتاب ترفيهي للكبار يجمع الألعاب والألغاز والتحديات الذهنية، لساعات من التسلية وشحذ الذكاء والتركيز. يناسب القراءة الفردية أو قضاء وقت ممتع مع الأصدقاء والعائلة.", CategoryId = 3, ImageUrl = "/images/products/9786339957529.webp", Author = "نرمين صلاح الدين أحمد", PublishDate = new DateTime(2026, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786339957529", Pages = 125, Size = "14×20" },
            new { Id = 18, Name = "الفم", Price = 165m, Stock = 10, Description = "رواية فلسفية للكاتب الليبي إبراهيم الكوني عن حب يتحدّى قوانين القبيلة الصارمة، فلا يبقى أمام البطل إلا الطاعة والتخلّي أو السقوط في «الفم»؛ الهاوية التي تبتلع من يتمرّد على قدر الصحراء. رحلة تتداخل فيها التضحية بصمت الرمال.", CategoryId = 8, ImageUrl = "/images/products/9789778203455.webp", Author = "د. إبراهيم الكوني", PublishDate = new DateTime(2026, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778203455", Pages = 135, Size = "14×20" },
            new { Id = 19, Name = "المجاميع", Price = 180m, Stock = 10, Description = "من قرية المياسرة بدمياط إلى قلب لندن…\nحكاية رجل عادي..\nسحقه الفقر، واختبرته القسوة، وتعثر مرارًا..\nثم صعد بإرادته، وبطرق غير متساوية.\nمحمد يوسف البغدادي..\nليس استثناء، بل نموذجًا نراه كل يوم\nولا نعرف حكايته..\nرحلة عن الطموح حين يرفض الهزيمة،وعن الحياة حين ترفعك فجأة..\nثم تختبر قدرتك على البقاء..\nعن الإنسان، حين يصارع واقعه..\nويصنع مصيره بنفسه..", CategoryId = 1, ImageUrl = "/images/products/9789778203189.webp", Author = "محمد مصطفى عرفى", PublishDate = new DateTime(2026, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778203189", Pages = 184, Size = "14×20" },
            new { Id = 20, Name = "إنطفاء مصباح", Price = 180m, Stock = 10, Description = "أجلسُ بصحبةِ قلمٍ فضيٍّ شُجَّ رأسُه، وجفَّ الجرحُ.\nأريدُ أن أحكي قبل أن يفرغ حبرُه.\nأجدُ نفسي أرسمُ مجددًا.\n\nأرسمُ أعينًا، وأبوابًا، وأمواجًا.\nأرسمُ شيخًا يحمل طفلًا لم يتقبّل فكرة انتهاء مدة اللعب.\nأرسمُ شابًا تائهًا، غارقًا في ملابس البالغين الفضفاضة.\nأرسمُ فندقًا يُعجب صاحبُه بازدحامه، ولا يفهم أن الزائر يبيت بضع ليالٍ ثم يرحل بلا عودة.\nأرسمُ صاحبَ سيركٍ يُلاعب قردًا.\nأرسمُ سريرًا، تحته مقبرةٌ تُدفن فيها الأحلام الضائعة.\n\nأتأملُ ما رسمتُه، فأجدني موجودًا في كل شيء.\nأنا الطفلُ، والشابُ، والشيخ.\nأنا صاحبُ الفندق وزبونُه.\nأنا الزائرُ والمقيم.\nأنا صاحبُ السيرك والمشاهد.\nأنا القردُ والطبلة.\nأنا الذي حفرتُ المقبرة، وأنا من بكيت.\nأنا من دفنتُ الأحلام بيدي.\n\nيئستُ من تحقيقها.\nتخلّيتُ بعدما تمسّكت.\nأطفأتُ المصباح، فاستحالت الألوانُ إلى أسودَ قاتم.\nحاولتُ أن أمحو آثارَ الأحلام، لكنها كانت تعود بعد النوم.\nتدبّ فيها الحياةُ لدقائق، لتذكّرني بأيامٍ ولّت،\nوتتساءل في أسف:\nبأيِّ ذنبٍ دُفِنتُ؟", CategoryId = 6, ImageUrl = "/images/products/9789778203264.webp", Author = "أحمد عصام الدين", PublishDate = new DateTime(2026, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778203264", Pages = 172, Size = "14×20" },
            new { Id = 21, Name = "بألف طريقة مختلفة", Price = 400m, Stock = 10, Description = "تخيّل عالمًا ترى فيه الحقيقة بلا أقنعة.\nترى الناس كما هم فعلًا.\nمشاعرهم، نواياهم، أسرارهم، وحتى أكاذيبهم.\n\nمن العيش في عزلة خلف نظارات شمسية وقفازات، إلى حياة تفيض فيها الألوان بكل درجاتها، تبدأ أليس رحلة البحث عن ذات لا تذوب في الآخرين.\nرحلة شاقة نحو الفهم.\nنحو القبول.\nونحو النجاة.\n\nهذه ليست رحلة إلى الخارج، بل إلى الداخل.\nحيث المواجهة الأصعب.\n\nرواية عن رؤية ما لا يراه الآخرون.\nوعن عالم واحد… يمكن أن يُرى بألف طريقة مختلفة.", CategoryId = 6, ImageUrl = "/images/products/9789778203103.webp", Author = "سيسيليا اهيرن", PublishDate = new DateTime(2026, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778203103", Pages = 360, Size = "14×20" },
            new { Id = 22, Name = "بعض ما ورد بشأنها", Price = 230m, Stock = 10, Description = "زائرة مجهولة بفستان زفاف.\nبلاغ مرتبك عن جريمة قتل.\nواختفاء يربك كل ما يبدو واضحًا.\n\nمن شذرات متفرقة ومعطيات ناقصة، أجد نفسي مدفوعةً إلى خوض تجربتي الأولى في الكتابة.\nلا بوصفها بحثًا عن حل.\nبل كتجربة يحركها الفضول والشك.\n\nالنص لا يعد بإجابات.\nولا يمنح يقينًا.\nإنه اقتراب بطيء من لغز.\nواعتراف بأن بعض القصص لا تُحكى… بل تُعاش.\n“و.م”", CategoryId = 6, ImageUrl = "/images/products/9789778203356.webp", Author = "رامي احمد مصطفى", PublishDate = new DateTime(2026, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778203356", Pages = 248, Size = "14×20" },
            new { Id = 23, Name = "تحليق إيكاروس", Price = 400m, Stock = 10, Description = "لا تؤدّي كلُّ الطرق إلى النجاة، فأحيانًا ما تكون مجرّد بداية، كأغنيةٍ بعيدة تأتي من مكانٍ مجهول، ثم تعلو.. حتى تصير صراخًا يسكن الرأس.\nفي «تحليق إيكاروس» لا تقف الكارثة عند حدود بلدة صغيرة، بل تبدأ من داخلها؛ من رغبةٍ جارفةٍ في الخلاص، من حلمٍ بأن يصبح المرء ذو قيمة، ومن خطوةٍ واحدة نحو ضوء يبدو جميلًا، يعد بالأمل.. ويُخفي الاحتراق.\nولا تبدأ الحكاية بطفلٍ صغير يختفي دون أثر، أو بوحشٍ يخرج من الظلام، بل بشابٍّ.. يظن أن الخروج من البلدة هو النجاة، وأن الموسيقى هي الوسيلة المثلى لتحقيق هدفه.\nلكن بعض الأبواب لا تُفتح إلا لتريك ما لا ينبغي أن يُرى، وبعض الفرص تعدنا بالأمل.. وتُخفي في باطنها العذاب.\n«تحليق إيكاروس» ليست مجرّد رواية عادية، بل عمل سيترك في قلبك ندبةً لا تُرى.", CategoryId = 3, ImageUrl = "/images/products/9789778203257.webp", Author = "كيتلين شنايدرهان", PublishDate = new DateTime(2026, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778203257", Pages = 364, Size = "14×20" },
            new { Id = 24, Name = "تخيلني", Price = 455m, Stock = 10, Description = "نغوص مع وارنر وكينجي في بحر من المشاعر الجياشة والتفاني المطلق، بينما يواجهان سباقًا مع الزمن لإنقاذ جولييت والحفاظ على حياتها. تدخل جولييت في غيبوبة غامضة، تاركة خلفها فراغًا ثقيلًا يدفع وارنر وكينجي إلى مواجهة قرارات مصيرية.\n\nفي الوقت نفسه، يتصاعد التوتر مع احتجاز أندرسون لجيمس وآدم وبقية أطفال القادة العُليا كرهائن، ما يجعل التحديات أكثر تعقيدًا وخطورة. يزخر هذا الجزء بالمنعطفات المدهشة والأحداث غير المتوقعة التي تطرح أسئلة ملحّة: هل ستنجو جولييت؟ وكيف سيتمكن أصدقاؤها من تحرير الرهائن ومواجهة أندرسون؟ والأهم… هل سينجحون في الإطاحة بنظام «إعادة التأسيس» إلى الأبد؟", CategoryId = 4, ImageUrl = "/images/products/9789778202571.webp", Author = "طاهرة ماڤي", PublishDate = new DateTime(2026, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778202571", Pages = 430, Size = "14×20" },
            new { Id = 25, Name = "تماثيل الملح", Price = 200m, Stock = 10, Description = "ما خُتِمَ بالملح… لا يذوب\nفي بلدةٍ ساحليةٍ يبدو كلُّ شيءٍ مألوفًا، حتى تبدأ الأمور بالتغيّر.\nتظهر تماثيل ملح في كل مكان، على الشواطئ وفي الزوايا، بلا صانعٍ معروف، ولا سببٍ مقنع.\nيحاول الجميع التعامل معها كأسطورةٍ قديمة، أو كوسيلة دعاية جديدة، قبل أن تتطوّر الأمور، وينتشر الملح ليفرض سطوته على كل شيء، كلما ظنّ الجميع أن الأمر قد انتهى.\n\nسرعان ما يجد سليم خطّاب، كاتب الرعب الشهير، الذي يعاني من مشكلات لا يمكن لأحد تصوّرها، نفسه متورّطًا في قلب الرعب؛ ويجد نفسه محاصرًا بأسئلةٍ عليه العثور على إجابتها.\nما علاقة هذه التماثيل برواياته؟ ولماذا يبدو أن البلدة تتصرّف كمن يُخفي لعنةً قديمة؟ وهل سيحتاج للبحث عن الناجين من الأساطير المرعبة ليجد ضالته بينهم؟\n\nقبل أن يدرك أن كل إجابة تقوده إلى سؤالٍ أشدّ ظلمة، وكل خطوة تقوده نحو حقيقةٍ لا يرغب في معرفتها… حيث لا يكون الماء ماءً فقط، ولا الملح ملحًا فحسب.\n\nفي «تماثيل الملح»، تذوب الرواية بين الأسطورة القديمة، وتتداخل مع الواقع، حتى لا تعود قادرًا على الفصل بين ما تراه… وما يريدك الملح أن تراه.", CategoryId = 9, ImageUrl = "/images/products/9789778203240.webp", Author = "محمد عصمت", PublishDate = new DateTime(2026, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778203240", Pages = 198, Size = "14×20" },
            new { Id = 26, Name = "جريمة عائلية", Price = 490m, Stock = 10, Description = "ديسمبر 2003: يُعثر على زوج أم المخرج السينمائي غاي هوارد ميتًا في حديقة منزل العائلة في لندن، وتقول والدته ونصفا شقيقتيه إنهن لم يرين شيئًا. بعد سنوات يعيد مسلسل وثائقي فتح القضية فتتكشف الأسرار أمام الجميع، وتبدو الحقيقة أقرب إلى البيت مما يُتوقع. رواية جريمة وتشويق بأسلوب الرسائل والمقابلات والوثائق.", CategoryId = 3, ImageUrl = "/images/products/9789778203158.webp", Author = "كارا هانتر", PublishDate = new DateTime(2026, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778203158", Pages = 578, Size = "14×20" },
            new { Id = 27, Name = "جنينة المحروقي", Price = 260m, Stock = 10, Description = "غادر كريم بيته طفلًا في ليلة بلا تفسير وبأمر من أمه، ليقضي سنوات طويلة في الغياب محمّلًا بذنب لا يهدأ، قبل أن يعود عودة وحيدة لدفنها. يعود إلى المربع السكني الذي لم يتغير في شكله، لكن أهله لم يعودوا كما كانوا، وتظل جنينة المحروقي في المنتصف صامتة، مغلقة، ومراقَبة. يكتشف كريم جيرانًا لا يتذكرهم، وتصرفات بلا تفسير، أكياسًا سوداء، روائح بخور، مفاتيح بلا أبواب، وليلة سبت لا يُسمح له أن يبقى فيها. وحين يكتشف أنه كان حاضرًا وهو غائب، وأن وفاة أمه ليست نهاية بل بداية، يتحول الفضول إلى خوف، والخوف إلى مواجهة مع أسطورة قديمة، وروح لم تغفر لنفسها، وسكان يحمون سرًا مشتركًا بأي ثمن. إنها رواية نفسية مظلمة عن الفقد، والذنب، والأماكن التي تطالبك بأغلى ما تملك قبل أن تسمح لك بالرحيل.", CategoryId = 9, ImageUrl = "/images/products/9789778203318.webp", Author = "يحيى صفوت", PublishDate = new DateTime(2026, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778203318", Pages = 302, Size = "14×20" },
            new { Id = 28, Name = "دكستر في الظلام", Price = 435m, Stock = 10, Description = "مثَّل الراكِب المُظلِم داخله وعدًا ثابتًا؛ صوتٌ يقوده، وجوعٌ لا يضل، وظلٌّ يهبه معنى.. ولو كان معنى مُلطَّخًا بالدماء.\nثم حدث ما لا يُغتفر؛ وصمت الظلام.\nلا اندفاع، ولا همس، ولا نشوة.. فقط فراغٌ بارِد يتَّسع في صدر دكستر، كقبرٍ مفتوحٍ ينتظِر صاحبه.\nلكن الصمت لا يعني الخلاص؛ فأحيانًا.. يكون فخًا، وأحيانًا أخرى يكون إعلانًا بأن شيئًا أقدم، وأقسى، قد انتبه إليه أخيرًا.\nشيء لا يُريد منه القتل.. بل يُريده هو!\nبين صفحات هذا الكِتاب، لا يُطارِد دكستر قتلةً فحسب؛ بل سؤالًا ينهش روحه؛ ماذا يتبقّى من الوحش.. حين يُسلب منه ظلامه؟\nدكستر في الظلام ليست مُجرَّد رواية.. بل سقوطٌ بطيء في ظلامٍ دامس لا قاع له.", CategoryId = 3, ImageUrl = "/images/products/9789778203196.webp", Author = "چيف ليندسي", PublishDate = new DateTime(2026, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778203196", Pages = 420, Size = "14×20" },
            new { Id = 29, Name = "دونوس", Price = 180m, Stock = 10, Description = "بدأ كلُّ شيءٍ بصداعٍ غريب.\nظلٌّ أسود يلاحق رامي، وإحساسٌ دائم بالمراقبة.\nصرخةٌ، نزيفٌ غامض، ثم موت.\nلكن القصة لا تنتهي هنا.\n\nبعد دفنه، تصل رسائل من هاتفه.\nقبرٌ يختفي.\nوصورةٌ تكشف ظلًّا غامضًا خلفه.\nعودةٌ لم يكن ينبغي أن تحدث.\n\nحياةُ عائلةٍ تنقلب إلى لغز.\nأصدقاءُ يواجهون أسرارًا خطيرة.\nوشخصياتٌ تظهر وتختفي، بينما اسمٌ واحد يتردد في كل مكان: دونوس.\n\nمن الذي عاد فعلًا؟\nوما هو كتاب الهاشكيلا؟\nومن يقود اللعبة، ومن يحاول حماية الأرض؟\n\nروايةٌ تشويقية عن أسرارٍ قديمة،\nوصراعٍ يتجاوز الموت نفسه.", CategoryId = 9, ImageUrl = "/images/products/9789778203325.webp", Author = "حسن الحلبي", PublishDate = new DateTime(2026, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778203325", Pages = 224, Size = "14×20" },
            new { Id = 30, Name = "طه حسين الأيام المنسية", Price = 300m, Stock = 10, Description = "كتاب طه حسين: الأيام المنسية، يعيد فتح الصفحات التي لم تُكتب..\nويكمل ما توقف عنده عميد الأدب العربي طه حسين في سيرته الأشهر.\nليست سيرة تقليدية، بل كشف مباشر عبر رسائل خاصة وأوراق شخصية ونصوص لم تُنشر من قبل.\nكتاب يضعك أمام طه حسين الحقيقي\nبعقله وشكّه وإرادته التي صنعت نورًا من العتمة.", CategoryId = 7, ImageUrl = "/images/products/9789778203332.webp", Author = "إبراهيم عبدالعزيز", PublishDate = new DateTime(2026, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778203332", Pages = 372, Size = "14×20" },
            new { Id = 31, Name = "عاصفة السيوف سوفت كڤر ( النسخة العالمية)", Price = 1250m, Stock = 10, Description = "ما زالت حرب الملوك الخمسة مشتعلةً، تعاني ويلاتها جميع أنحاء الممالك السبع إلا قليلًا. على العرش الحديدي يجلس الملك الصبي الغاشم جوفري، فيما يسعى جدّه اللورد تايوين لانستر، يدُ الملك، لتأمين حكمه، ومن ثم تأمين السلطة لعائلة لانستر، مخططًا للقضاء على الملك ستانيس باراثيون الذي خرج مدحورًا من معركة الماء الأسود، وعلى الذئب الصغير روب ستارك الذي يقود حملةً في غرب البلاد رغم أنه فقد وطنه في الشمال.\n\nوفي تلك الأثناء تشقّ الملكة المنفية دينيرس تارجاريَن طريقها في قارّةٍ أخرى تُغرقها الدماء، بغية تحرير مئات الآلاف من العبيد والحصول على جيشٍ تستعيد به مملكتها، ومعها التنانين الثلاثة الحيّة الوحيدة في العالم.\n\nوفي الشمال يتحرّك جيشٌ جرّار من الهمج استعدادًا للهجوم على الجدار وغزو الممالك السبع، جيشٌ انضمّ إليه رجل حرس الليل جون سنو جاسوسًا، ولو أنّ شيئًا أسوأ منه يتقدّم من أقصى الشمال، العدوّ الحقيقي الذي ينشغل عنه الجميع تقريبًا بقتالهم، وقد لا تقدر جيوش الأرض كلّها على ردعه.", CategoryId = 2, ImageUrl = "/images/products/9789778203219.webp", Author = "چورچ ر.ر مارتن", PublishDate = new DateTime(2026, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778203219", Pages = 1534, Size = "14×20" },
            new { Id = 32, Name = "عباقرة الكتابة", Price = 250m, Stock = 10, Description = "الحكي أقدم وسيلة ترفيه وتعلّم في التاريخ، قبل المسرح، وقبل الكتابة، وقبل كل شيء. القصص ملأت الأديان، وشكّلت وعي البشر.\nلكن لماذا تنجح بعض القصص وتفشل أخرى؟ وما الذي يصنع الكاتب العظيم؟ الشغف، الالتزام، وحب المعرفة.\nصفات جمعت بين كتّاب وصلوا إلى قمة الإبداع، وأثبتوا أن اسم الكاتب يمكن أن يكون عنصر جذب لا يقل عن النجوم.\nنجيب محفوظ، كريستوفر نولان، وجي كي رولينج. عباقرة جمعوا بين الفن والنجاح الجماهيري، خاطبوا القلوب والعقول، وأتقنوا هندسة المشاعر.\nدروس يمكن تعلّمها، لكن يبقى السؤال: ما ثمن العبقرية، وكيف نصل إليها؟", CategoryId = 8, ImageUrl = "/images/products/9789778203202.webp", Author = "طاهر المعتز بالله", PublishDate = new DateTime(2026, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778203202", Pages = 312, Size = "14×20" },
            new { Id = 33, Name = "غيط النوبي", Price = 200m, Stock = 10, Description = "بحيّ الأزبكية، نهايةَ القرنِ التاسعَ عشرَ،\nواقعةٌ من أغربِ الوقائع التي شهدتها المحروسة.\nذكرها التاريخُ باسم: يوم الفرجة،\nثم محا أثرها من أوراقه.\n\nما بين خوجةٍ ريفيٍّ هرب من الماضي،\nوامرأةٍ ذات ماضٍ ملتبسٍ سحرها الشيطان،\nوجريمةِ قتلٍ بلا قتيل،\nوصعلوكٍ يمتطي طاولاتِ المقاهي،\nيُقصّ حقيقةَ يوم الفرجة،\nالتي لا يعلمها غيره.\n\nتسافر الروايةُ عبر الزمن إلى أيامِ القاهرة الخديوية،\nوتكشف خبايا ما حدث في ذلك اليوم المشؤوم،\nفي رحلةٍ اجتمع فيها الأضدادُ على حبٍّ محرَّم وسرٍّ ملعون،\nفي وثيقةٍ يرفضها التاريخ،\nولكن لا ينكرها من شهدها.", CategoryId = 3, ImageUrl = "/images/products/9789778203301.webp", Author = "محمد فوزي عبد الرحيم", PublishDate = new DateTime(2026, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778203301", Pages = 187, Size = "14×20" },
            new { Id = 34, Name = "قصر البارون", Price = 200m, Stock = 10, Description = "بلاغ عن حريق لا يترك أثرًا.\nوقصر يخفي أكثر مما يُظهر.\nتحقيق في واقعة غامضة يقود إلى لغز يتجاوز المنطق والزمن.\n\nغرفة مرايا تفتح أبوابًا غير متوقعة.\nأزمنة تتقاطع على نحو غير متوقع.\nوتاريخ يسير في مسارات لم تحدث يومًا.\nكل انتقال يكشف سرًا جديدًا.\nوكل محاولة للعودة تقود إلى زمن أكثر خطورة.\n\nرواية تمزج التحقيق بالغموض.\nوتطرح سؤالًا واحدًا يلاحق القارئ حتى النهاية.\nهل القصر شاهد على ما حدث… أم صانع له؟", CategoryId = 3, ImageUrl = "/images/products/9789778203233.webp", Author = "محمد كامل", PublishDate = new DateTime(2026, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778203233", Pages = 216, Size = "14×20" },
            new { Id = 35, Name = "كل الظلال التي نخفيها", Price = 230m, Stock = 10, Description = "على شاطئ بورتسموث، وبين غرفة ضيقة ومرافقة عجوز، تُجبر آية على مواجهة ذاتها.\nهروب من وطن موجوع، وعائلة مثقلة بالفقد، وزواج بلا صوت.\n\nصوت من الماضي، مساحة مفتوحة للاعتراف بكل ما صمتت عنه طويلًا.\nووجه من الحاضر يعيد ترتيب فوضى قلبها..\n\nإنها ليست رواية، بل سيرة وجع عربي ممتد.\nذاكرة حروب.\nمنافي أقسى من الغربة.\nونساء يحملن الهزيمة في أجسادهن، وفي أصواتهن المكبوتة.", CategoryId = 6, ImageUrl = "/images/products/9789778203349.webp", Author = "سوزان خلقي", PublishDate = new DateTime(2026, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778203349", Pages = 254, Size = "14×20" },
            new { Id = 36, Name = "لستُ الأخيرة", Price = 260m, Stock = 10, Description = "ليست كل الحكايات تُروى بصوت واحد.\nوليست كل النساء ينجون…\nفي لستُ الأخيرة\nتتقاطع حيوات نساء من أزمنة وأماكن مختلفة..\nروما في القرن السابع عشر والإسكندرية في الحاضر.\nامرأة تصنع خلاصها بيديها.\nوأخرى تحاول إنقاذ غيرها قبل أن يفوت الأوان.\nقصص عن العنف، عن النجاة، وعن الثمن الذي تدفعه النساء حين يقررن ألا يكنّ الضحية التالية..\nرواية عن قوة تُولد من العجز،وعن رحمة قد تتحول إلى حمل ثقيل، وعن سؤال يرفض أن يختفي!!\nهل تنتهي الدائرة،أم أن هناك دائمًا ضحية جديدة؟", CategoryId = 1, ImageUrl = "/images/products/9786339957536.webp", Author = "كنزي مدبولي", PublishDate = new DateTime(2026, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786339957536", Pages = 272, Size = "14×20" },
            new { Id = 37, Name = "ما وراء الإبعاد", Price = 165m, Stock = 10, Description = "في اللحظة التي تظن فيها أنك تمسك هذا الكتاب، تخبرنا الفيزياء أن هناك نسخة أخرى منك ربما اختارت ألا تقرأه، ونسخة ثالثة لم تولد من الأساس... نحن نعيش في سجن من ثلاثة جدران نسميه \"الواقع الحقيقي\"، لكن العلم من وراءها يهمس بأن هذا السجن له أحد عشر بابًا مفتوحًا لا نراها!\n\nفي هذا الكتاب، سأصطحبك معي في رحلة ذهنية مذهلة عبر فيزياء الأبعاد العلوية... رحلة تبدأ من الصفر، وتصعد بك عبر درجات المكان والزمان، لتكشف لك هندسة الكون الخفية كما لم ترها من قبل، وتجيب عن أسئلة لم تخطر ببالك...\n\nهل الزمن مجرد وهم؟ وهل الماضي والمستقبل موجودان الآن معًا في مكان ما؟ كيف يفسر العلم مفهوم \"طي الواقع\"؟ وما هي العلاقة بين \"الأكوان الموازية\" ومعضلة الاختيار والاحتمالات؟ \n\nلماذا يرانا الجن ولا نراهم؟ (الإجابة هندسية بحتة!)، وكيف تلتقي أحدث نظريات \"الأوتار الفائقة\" مع حلول أعمق الألغاز الحياتية في نقطة واحدة؟\n\nهذا ليس مجرد كتاب فيزياء تقليدي... إنه تجربة فكرية وفلسفية فريدة تحاول كسر الزجاج الذي يفصل بين عقولنا وبين الحقيقة الكبرى... وأعدك أنك بعد قراءة الصفحة الأخيرة، لن تنظر إلى العالم – أو إلى نفسك – بنفس الطريقة أبدًا...", CategoryId = 2, ImageUrl = "/images/products/9789778203387.webp", Author = "محمود علام", PublishDate = new DateTime(2026, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778203387", Pages = 156, Size = "14×20" },
            new { Id = 38, Name = "مملكة النساء", Price = 300m, Stock = 10, Description = "منذ أكثر من ثلاثة آلاف عام، وفي إحدى قرى مصر، توارث الناس حكايات عن مدينة كاملة اختفت من كتب التاريخ، مدينة عاشت زمن الاضطراب الذي شهدته البلاد في عهد الملك رمسيس الثالث، حين اجتاحت قبائل أجنبية تُدعى المشوش أطراف مصر، ونشرت الخراب والفساد بين القرى والبلدان، فذُبح رجال المدينة في معركة دامية، وتُركت نساؤها وحدهن في مواجهة الخوف والجوع والمجهول؛ لم يكنّ ملكات ولا أميرات، بل نساءً عاديات، منهن من حاولت النجاة بالفرار، ومنهن من أشعلت ثورة الجياع، ومن تشبثت بالسحر بحثًا عن طوق نجاة أخير.\n\nمملكة النساء ليست أسطورة، بل رواية مستوحاة من حكايات حقيقية ما زال أهل القرية يروونها حتى اليوم، رغم أنها لم تُذكر في أي كتاب تاريخي، رواية عن الصمود، وعن نساء واجهن وحدهن زمن الانهيار، وكتبن حكاياتهن، ثم اختفين من التاريخ.", CategoryId = 7, ImageUrl = "/images/products/9789778203271.webp", Author = "مصطفى قمري", PublishDate = new DateTime(2026, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778203271", Pages = 368, Size = "14×20" },
            new { Id = 39, Name = "نار بلا شرار", Price = 420m, Stock = 10, Description = "سفينة غارقة، وأسرار لم يعد ممكنًا إخفاؤها.\nبين سكان خائفين، ومرتزقة يبحثون عن النجاة…\nمادرا تتناقص، وأنفاق غامضة…\nقرار قد ينقذ الجميع، أو يحرق كل شيء…\nهذه ليست نهاية الرحلة… هذه لحظة الاختبار الحقيقي.\nهل يواجه آدم ثمن اختياره؟\nماذا حلّ بروان؟\nوهل يعود مايك…؟\nمن سينجو؟\nومن ستبتلعه النار؟", CategoryId = 2, ImageUrl = "/images/products/9789778203288.webp", Author = "د. خولة حمدي", PublishDate = new DateTime(2026, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778203288", Pages = 448, Size = "14×20" },
            new { Id = 40, Name = "نبضات معدنية", Price = 165m, Stock = 10, Description = "هل تسكن الأحلامُ الدوائرَ الكهربائية؟\nوهل يمكن لقلبٍ من معدنٍ أن ينبض بالحب أو الخوف؟\n\n«نبضات معدنية»\nرحلةٌ استثنائية تتجاوز حدود الخيال العلمي التقليدي،\nتدخل بنا إلى المنطقة الضبابية الفاصلة بين الإنسان والآلة.\n\nليست مجرد حكايات عن المستقبل،\nبل مرآة تعكس مخاوفنا وأحلامنا وتساؤلاتنا الوجودية.\n\nإنها دعوة لإعادة تعريف ما يعنيه أن تكون «إنسانًا» في عالمٍ تتلاشى فيه الفوارق،\nوتتحول فيه المشاعر إلى شفرات،\nوتُترجم الأحلام إلى دوائر كهربائية.", CategoryId = 2, ImageUrl = "/images/products/9789778203097.webp", Author = "احمد صلاح المهدى", PublishDate = new DateTime(2026, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778203097", Pages = 136, Size = "14×20" },
            new { Id = 41, Name = "هبوط حر", Price = 130m, Stock = 10, Description = "«هبوط حُرّ»\nعن الإنسان حين يُنزَع عنه الأمان: أمان الجسد، والذاكرة، والهوية، والاختيار.\n\nهنا لا يحدث الانهيار دفعةً واحدة، بل تدريجيًا، منطقيًا، وبهدوءٍ مرعب.\n\nالعالم لا يُدمَّر بالقنابل فقط، بل بالروتين، والطاعة، والخوف، والرغبة في النجاة الفردية.\nالناس يعتادون الرائحة الكريهة، ويعتادون العيش داخل الصَدَفة، ويعتادون أن يُدفنوا أحياء، وأن يُمحى ماضيهم، وأن يُدار وعيهم، وأن يُختزلوا إلى «وحدات».\nولا تحتاج السلطة هنا إلى قسوةٍ مباشرة دائمًا؛ يكفي أن تُقنع الناس أنه «ليس في الإمكان أبدع مما كان».\nوالإنسان لا يُهزم لأنه ضعيف، بل لأنه يوافق… ثم يُخفي عن نفسه أنه وافق.\nوالنهايات ليست صادمة بقدر ما هي كاشفة: العالم لا يسقط فجأة… بل يسقط سقوطًا حرًا، والإنسان يعتاد أن يسقط معه دون حتى أن يصرخ.", CategoryId = 1, ImageUrl = "/images/products/9789778203394.webp", Author = "حسام مصطفي ابراهيم", PublishDate = new DateTime(2026, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778203394", Pages = 112, Size = "14×20" },
            new { Id = 42, Name = "وليمة للغربان (النسخة العالمية)", Price = 990m, Stock = 10, Description = "الجزء الرابع من سلسلة «أغنية الجليد والنار» للكاتب چورچ ر.ر مارتن، رواية فانتازيا ملحمية تتشابك فيها الصراعات على العروش والتحالفات والخيانات. النسخة العالمية.", CategoryId = 2, ImageUrl = "/images/products/9789778203417.webp", Author = "چورچ ر.ر مارتن", PublishDate = new DateTime(2026, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778203417", Pages = 1098, Size = "14×20" },
            new { Id = 43, Name = "أقسى من الموت", Price = 130m, Stock = 10, Description = "ريم امرأة تعيش وحدها وتواجه الألم والفقد، إلى أن تضعها مواجهة غير متوقعة أمام أسطورة قديمة تتداولها الحكايات، فتبدأ في تتبّع خيوط الحقيقة. رواية تمزج الغموض بالخيال، بنهاية تحمل مفاجأة.", CategoryId = 1, ImageUrl = "/images/products/aqsa-min-almawt.webp", Author = "محمد عصمت", PublishDate = new DateTime(2026, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate },
            new { Id = 44, Name = "ساعة الذئب", Price = 130m, Stock = 10, Description = "ساعة الذئب هي الساعة التي تسبق الفجر، حين يبلغ الظلام أشدّه ويبدو كل شيء ممكنًا. رواية رعب وتشويق للكاتب خالد أمين، من إصدارات دار كيان للنشر.", CategoryId = 1, ImageUrl = "/images/products/saat-al-thib.webp", Author = "خالد أمين", PublishDate = new DateTime(2026, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate },
            new { Id = 45, Name = "عبور مؤجل", Price = 300m, Stock = 10, Description = "ما جرى في هذه الحكاية يقع كل يوم، عندما أقول كل يوم فإني أعني ذلك، من الساعة الرابعة فجرًا حتى السادسة مساءً، في أوقات لا يلتفت فيها العالم إلى شيءٍ سوى نفسه.\nيحدث هذا خارج نشرات الأخبار، وخارج اللغة الكبيرة. في ساعات الانتظار التي لا تُحسب من العمر لكنها تستهلكه. لهذا فما حدث في الحكاية ليست لحظة استثنائية، بل واحدة من لحظات كثيرة تتشابه إلى حدِّ التطابُق والقسوة، فيما تختلف فقط بأسماء العابرين وأيام الأسبوع.\nكل ما يرد في الحكاية مقصود ومدروس كجزء من لعبة الشاباك، إنها رواية على شكل وقوف طويل أمام بابٍ مفتوحٍ نصف فتحة، تساؤل صامت عمَّا إذا كان العبور بحثًا عن معنى، أم إضافة اسمٍ آخر إلى سجل الامتيازات؟\nحكاية تبدأ بتباطؤ مقصود؛ لأن بعض الحكايات لا تحتاج افتتاحية صاخبة، وإنما تحتاج شجاعة الاعتراف الأول بأن الدخول ليس بسيطًا، وأن الكتابة نفسها عبء، وأن حمل هذا العبء هو الشرط الوحيد للمضي قُدمًا نحو عبورٍ مؤجَّل.\nعبد الله مكسور، روائي وصحفي عربي من مواليد سوريا، صدرت له سبعة أعمال روائية وكتاب «هندسة المعنى» في الصحافة والإعلام. يعمل في الصحافة منذ عام 2007م، كما عمل في المسرح البلجيكي، ولديه خبرة طويلة تمتد لأكثر من عقدين في العمل التلفزيوني والتدريب على تقنيات الكتابة الإبداعية والفنون الصحفية، تُدرَّس أعماله ضمن مساقات الكتابة الحديثة في العديد من الجامعات.", CategoryId = 1, ImageUrl = "/images/products/9789777956000.webp", Author = "عبد الله مكسور", PublishDate = new DateTime(2026, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789777956000" },
            new { Id = 46, Name = "الارسالية", Price = 300m, Stock = 10, Description = "في رسالتها الأخيرة، ومن سريرٍ تتأرجح فوقه الأنفاس بين وداعٍ بطيء واستدعاءٍ مُلحٍّ للذاكرة، تُسطِّر ماري مجدولين، الراهبة السابقة والممرضة الأمريكية الموفدة للتبشير، اعترافها الأشد صفاءً، والأكثر وجعًا.\nعبر مرايا الاسترجاع، تُعيد تركيب رحلتها التي شقَّت بها البحر نحو سواحل الخليج والجزيرة العربية؛ إلى أرضٍ لا تُبدِّل الاتجاهات فحسب؛ بل تُعيد صياغة الإنسان من الداخل.\nهناك؛ حيث تبدو الموروثات حدودًا قاطعة، وتُختبَر الرحمة على حافة القسوة، وتشتبك الطقوس مع الأسئلة، تكتشف ماري أنَّ الغريب ليس القادم من بعيد؛ بل ذلك الذي ينهض في أعماقنا حين تُنزع الأقنعة، ويُدفَع القلب إلى مواجهة صورته بلا مواربة.\n\"الإرسالية\" ليست حكاية سفرٍ من ميناءٍ إلى ميناء؛ بل ملحمة عبورٍ داخلي، من يقينٍ مُستعار، إلى يقينٍ مُكتسَب بالألم، مِن إيمانٍ يَسكُن، إلى إيمانٍ يُفتِّش، مِن صمتٍ يُعَدُّ فضيلةً إلى صمتٍ قد يتحوَّل إلى خيانة.\nد. خالد الجابر\n-باحث وأكاديمي وأديب وروائي ومؤلف مسرحي قطري.\n-يُعد من أبرز الأصوات الفكرية في قطر والخليج.\n-شغل مناصب أكاديمية وإعلامية بارزة، منها أستاذ الاتصال السياسي بجامعة قطر، ورئيس تحرير صحيفة The Peninsula، إلى جانب قيادته لمراكز بحثية وثقافية.\n-يحمل درجة الماجستير من الولايات المتحدة، والدكتوراه من المملكة المتحدة، إضافة إلى دبلومات علمية من جامعات: جورجتاون وستانفورد وفوردهام الأمريكية.", CategoryId = 1, ImageUrl = "/images/products/9789777955973.webp", Author = "خالد الجابر", PublishDate = new DateTime(2026, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789777955973" },
            new { Id = 47, Name = "ديوان ابن عطاء", Price = 175m, Stock = 10, Description = "هذا الكتاب يُقدِّم للقارئ أشعار ابن عطاء الله السكندري، الذي عاش في القرن السابع الهجري، وتوفي مطلع القرن الثامن، وكانت أشعاره مُتفرِّقة في بعض كتبه.\nويجمع الكتاب شِعر «ابن عطاء» على وجهٍ ملائمٍ يليق بصاحب الشِّعر ومكانته، وبالأفكار التي اشتمل عليها، وبالقضايا التي يعالجها.\nوقد اجتهد مُحقِّق الكتاب في جمع شعر «ابن عطاء» من الأصول المخطوطة لبعض كتبه؛ للوقوف على حقيقة ما ورد بها من شِعر، وملابسات كل نَصٍّ منه، والتمكُّن من تحقيق تلك النصوص تحقيقًا علميًّا دقيقًا، وفق قواعد التحقيق العلمية، وضبط ألفاظ تلك النصوص، حتى تظهر الأشعار للقارئ بصورة جيدة، واستبعد المحقق الطبعات المتاحة بالأسواق لكتب «ابن عطاء» لكثرة ما ورد بها من أخطاء وتحريفات تحول بين القارئ للشعر وبين إدراك ما ورد به من أفكار بصورة صحيحة.\nوالكتاب إضافة حقيقية للمكتبة العربية، خاصة الأدب الصوفي المصري؛ إذ إنه يُعدُّ أول ديوانٍ مُحقَّقٍ لشِعر ابن عطاء الله السكندري.\n***\nد. محمد مصطفى منصور، أستاذ الأدب العربي المتفرغ بكلية دار العلوم، جامعة الفيوم. عمل محررًا وباحثًا بمجمع اللغة العربية بالقاهرة في الفترة من 1983م حتى 1991م، وشارك في تحرير مجالس المجمع ومؤتمره ومجلته. وضع الأسس الفنية لدراسة ملامح الأدب الصوفي المصري في كلية دار العلوم بجامعة الفيوم. أصدر نحو تسعة عشر كتابًا، منها: نداء المؤمنين في القرآن الكريم (1998م)، النثر الفني في عصري صدر الإسلام وبني أمية (1998م)، شرح قصيدة أبي مدين «ما لذة العيش إلا صحبة الفقرا» لابن عطاء الله السكندري (2001م)، الوقاية من العنف: قراءة تحليلية في الحديث النبوي الشريف (2021م).", CategoryId = 8, ImageUrl = "/images/products/9789777955935.webp", Author = "محمد مصطفي منصور", PublishDate = new DateTime(2026, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789777955935" },
            new { Id = 48, Name = "صفحات مطوية اعترافات ومراجعات", Price = 400m, Stock = 10, Description = "ليس سهلًا أن يعترف الإنسان بأخطائه أو سلبيات حياته، خاصة حين يكون قد حقَّق ما يضعه في مصاف المشهورين والمؤثرين في الحياة، وأضحى ملء السمع والبصر كما يُقال؛ لذلك فمجرد «التفكير» يُعد شجاعة كبيرة، أما الانتقال من منطقة الفكرة، إلى مساحة الفعل والكتابة، فهي جسارة لم يتَّسِم بها سوى قليلين.. ومن هؤلاء الجسورين الدكتور مصطفى الفقي، المفكر والكاتب والأديب والدبلوماسي والسياسي الذي طبَّقت شهرته الآفاق، ولم يكُن متحدثًا حصيفًا وراصدًا دقيقًا للأحداث فحسب، بل كثيرًا ما شارك في صناعتها، وحرَّك بفكره ورؤاه الكثير منها.\nوفي هذا الكتاب يقدم د. الفقي مادة ثرية كثراء حياته، ممتعة كطلاقة لسانه وتفرُّد أفكاره، متنوعة كتنوع خبراته وتشعُّب علاقاته، فيجد القارئ نفسه في بُستانٍ مُبهج، يتنقَّل فيه بسلاسةٍ ورشاقةٍ من الدبلوماسية إلى العمل الأكاديمي، ومن النشاط الإعلامي إلى التمثيل البرلماني، ومن الحياة الإنسانية البسيطة إلى الحياة السياسية المعقدة، فضلًا عن تناول كثير من القضايا الفكرية والإنسانية والثقافية والسياسية في مصر والوطن العربي بل والعالم، وككل كتب الدكتور مصطفى الفقي، فإن القارئ على موعد مع فيض فكري وإنساني، يمتاز برشاقة الأسلوب، وتنوع الأفكار، وبراعة الطرح والتناول.", CategoryId = 7, ImageUrl = "/images/products/9789777955898.webp", Author = "مصطفي الفقي", PublishDate = new DateTime(2026, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789777955898" },
            new { Id = 49, Name = "في غمضة عين", Price = 500m, Stock = 10, Description = "ماذا لو كان شريكك في التحقيق… ليس إنسانًا؟\nفي تجربة حكومية غير مسبوقة، تُجبر رئيسة المباحث «كات فرانك» على العمل مع «لوك»، ذكاء اصطناعي تجريبي بهيئة بشرية، لاختبار مستقبل العمل الشرطي، وذلك أثناء التحقيق في سلسلة من حالات الاختفاء الغامضة.\n«كات» تعتمد على الحدس والخبرة الإنسانية، و«لوك» لا يثق إلا في الأرقام والخوارزميات.\nلكن هذه القضية ليست عادية؛ كاميرات مراقبة متوقفة، آثار رقمية ممحوّة، وملفات بلا أي خيط واضح.\nهل هناك مَن يتلاعب بكل ما هو رقمي.. بلا أثر؟\nبينما تتقدم التحقيقات، تكتشف «كات» أن هناك قاسمًا مشتركًا واحدًا بين جميع المفقودين، قاسمًا لا تراه الخوارزميات، لكن يلتقطه حدسها فورًا: ابنها «كام».\nوعندما يختفي «كام» بدوره، يتحول التحقيق إلى سباق مع الزمن، وإلى مواجهة شخصية مع الماضي، ومع سؤال أخطر: هل يمكن للذكاء الاصطناعي أن يفهم الإنسان عندما تصبح حياته على المحك؟\n«في غمضة عين» رواية مشوقة تمزج بين الجريمة والخيال العلمي، عن الفقد والأمومة، وعن صراع الذكاء البشري مع الذكاء الاصطناعي، وعن ذلك الحد الفاصل الدقيق بين العبقرية.. والجنون.\nعن المؤلفة:\nجو كالاجان كاتبة بريطانية من برمنغهام، عملت لسنوات في مجالات القيادة والإدارة العامة، وبالتوازي اهتمت بأسئلة المستقبل وتأثير الذكاء الاصطناعي على المجتمع والعمل وهو ما ينعكس بوضوح في عالم روايتها. في عام 2024 فازت \"في غمضة عين\" بجائزة Theakston Old Peculier – Crime Novel of the Year (أفضل رواية جريمة في بريطانيا)، كما حصدت أيضًا جائزة CWA John Creasey (New Blood) Dagger لعام 2024، ووصلت إلى قوائم الترشيح لجوائز أخرى، لتصبح واحدة من أبرز الروايات البوليسية في السنوات الأخيرة.\nترجمة   :- حسام شاكر", CategoryId = 1, ImageUrl = "/images/products/9789777955850.webp", Author = "جو كالاجان", PublishDate = new DateTime(2026, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789777955850" },
            new { Id = 50, Name = "سرايات اسرة محمد على", Price = 200m, Stock = 10, Description = "سريات أسرة محمد علي\nيتناول الكتاب تاريخ إنشاء أشهر القصور المَلَكية التي شهدها أسرة محمد علي، ويفرد الكاتب لكل قصر أو سراي فصلًا خاصًّا يلقي من خلاله الضوء على ظروف نشأتها وقيمتها المعمارية والحضارية من حيث تاريخ تشييدها ومَن سكنها من أفراد الأسرة العلوية، ثم المصير الذي آلت إليه.\nولا يكتفي بتقديم وصف لهذه الآثار الفنية البديعة، وإنما يتطرّق إلى رصد الأبعاد الاجتماعية لتلك الحقبة المثيرة للجدل من خلال «حياة القصور» وما يدور فيها من أحوال الملوك والأمراء والبرنسيسات والهوانم، ومن يعاونهم من وصيفات وأغوات وخدم وطباخين وشماشرجية ومسلواتية، وغيرهم.\nعرفه عبده علي، كاتب صحفي وعضو اتحاد الكُتَّاب، نُشِر له العديد من الدراسات والمقالات بالصحف والدوريات المصرية والعربية، متخصص في تاريخ اليهود في مصر وتاريخ القاهرة ومعالمها، عمل مساعدًا لمدير مكتبة المعهد الفرنسي للآثار الشرقية بالقاهرة، اتخذت وزارة الخارجية المصرية قرارها بتعميم كتبه عن يهود مصر على كل السفارات والقنصليات المصرية بالخارج. أبرز مؤلفاته: \"تهويد عقل مصر\"و\"ملف اليهود في مصر الحديثة\" و\"قـراءة في الفكـر الإسـرائيلي المعاصر\"و\"القاهـرة في عصـر إسماعيل\" و\"الإسكندرية في عصرها الذهبي\"و\"مملكة الأقطاب والدراويش\"و\"رمضان في الزمن الجميل\"و\"حكايات مصرية من زمن العز القديم\".", CategoryId = 7, ImageUrl = "/images/products/9789777955904.webp", Author = "عرفة عبدة على", PublishDate = new DateTime(2026, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789777955904" },
            new { Id = 51, Name = "جريمة في ليلة ممطرة", Price = 235m, Stock = 10, Description = "\"جثا المحقق على ركبتيه بجوار الجثة المنكفئة على أرض المكتب يتأمّل الجرح النافذ على الجبهة والثقب الذي توسّط الصدغ والدماء المتخثرة من حولها وتساءل: \"معقولة تكون انتحار؟\".\n***\nتبدأ الرواية بجثة منكفئة وتساؤل حائر وعيون محدّقة، وتنتهي بالحقيقة.. وبين البداية والنهاية تتشابك الأحداث، ما بين  حب مستحيل، ومعاملات مالية مشبوهة، ودوافع غير أخلاقية، وقلوب معلقة بالأمل، وقاتل مجهول، ومطر كاشف!\nنهى داود كاتبة مصرية ولدت في إنجلترا عام 1975، تخرجت في قسم الاتصالات بكلية الهندسة جامعة القاهرة. وبعد أن عملت بمجال تخصصها لسنوات غمرها تيار الشغف، لتعكف على كتابة أولى رواياتها البوليسية بعد أن حصلت على دبلومة الكتابة الإبداعية من جامعة ويزليان الأمريكية، ثم تخصصت الكاتبة في أدب الجريمة. صدر لها 9 روايات منها: \"رضا\"،  و\"جثتان والثالثة عند قدمي\"، و\"دماء على السجادة الحمراء\"، و\"ذبابة زرقاء\".", CategoryId = 3, ImageUrl = "/images/products/9789777955478.webp", Author = "نهي داود", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789777955478" },
            new { Id = 52, Name = "طبقات الأطباء والحكماء", Price = 300m, Stock = 10, Description = "يُعَدُّ هذا الكِتَابُ  وَثِيقَةً مُهِمَّةً في تَارِيخ العُلُومِ وتَطَوُّرِ حَـرَكَةِ التَّألِيف والتَّرْجَمَة في القَرْنِ الرَّابِع الهجري/العاشِر الميلادي ، الذي يُعَدُّ  بحَقٍّ العَصْـرَ الذي ازْدَهَرَت فيه الحـَضَارَةُ الإسْلامِيَّـةُ ونَمَت، وبَلَغَت غَايَتَهَا من الإنْتَاجِ الوَاسِع في شَتَّى مَيَادِين العُلُوم والآدَاب. ولَعَلَّ مَيْزَةَ هذا الكِتَاب الأُولَى التي جَعَلَت له قِيمَةً عِلْمِيَّـةً خاصَّةً ونَصًّا قَدِيمًا له خَطَـرُه في تَارِيخ العِلْم ، أنَّ مُؤَلِّفَهُ يَعْتَمِدُ في ما رَجَعَ إليه من مَصَادِرَ على تَـرَاجِمَ عَـرَبِيَّـة لأصُولٍ لَاتِينِيَّـةٍ تَارِيخيَّـة.\nوالمـَوْضُوعُ الذي اخْتارَهُ مُؤَلِّفُنَا هو «طَبــَقَاتُ الأَطِبَّاء والحـُـكَمَاء» ، وهو وإنْ كان أوَّلَ أنْدَلُسِـيٍّ ألَّفَ في هذا المـَوْضُوع ، إلَّا أنَّـنـَا نَجِدُ أنَّ غَيْرَه من المـُؤَلِّفِين في المـَشْـرِقِ الإسْلَامِي قد سَبَقُوه إلى هذا النَّوْعِ من التَّألِيف ، بما أنَّ أقْدَمَ مَصْدَرٍ  بين أيْدِينَا  الآن عَرَضَ لتَـرَاجِم الأطِبَّاء  وهو «كِتَـابُ الفِهْرِسْت» الذي ألَّفَه أبو الفَـرَج محمَّد بن إسْحَاق النَّدِيم في شَعْبان سنة 377هـ/987م، أي في نفس السَّنَة التي ألَّفَ فيها ابن جُلْجُل كِتَـابَه .\nواعْتَمَدَ ابن جُلْجُل في جَمْعِ مَعْلُومَاتِه على ما تَوافَر في الأنْدَلُس من الكُتُب التي عَرَضَت لهذا المـَوْضُوع . وبِمَا أنَّ اللُّغَةَ الأصْلِيَّة لأهْلِ هذه البِلَاد هي اللُّغَة اللَّاتِينِيَّـة ، فقد تُـرْجِمَت عنها بعضُ المـُؤَلَّفات التَّارِيخِيَّة إلى العَـرَبِيَّـة في القَرْنِ الرَّابِع الهِجْرِي/العَاشِر المِيلَادِي الذي عَاشَ فيه ابن جُلْجُل، لَعَلَّ أهَمَّهَا «كِتَـابُ بَاوْلُوس أورُوسْيُوس Paulus Orosios» - الذي يَذْكُرُه ابن جُلْجُل دَائِمًا باسْم «هُـرُوشْيُوش» -  واعْتَمَدَ عليه في ما يَخُصُّ الأطباء اليونان واللاتين.\nواعْتَمَدَ كذلك على «كِتَـاب يُـرُونُم التُّـرْجُمان» واسْمُه باليُونَانِيَّة «خرُونِيقُون» والذي تُـرْجِمَ إلى العَـرَبِيَّـة باسْمِ «القَرْوَانِقَة».\nتحقيق     :- فؤاد سيد\nاعدها للنشر :- أيمن فؤاد سيد", CategoryId = 7, ImageUrl = "/images/products/9789777955775.webp", Author = "ابن جلجل", PublishDate = new DateTime(2026, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789777955775" },
            new { Id = 53, Name = "جنازة واحدة لموت كثير", Price = 220m, Stock = 10, Description = "\"لقد كان الحب هو ما كنت أحتاجه وشعرت به في هذا المنزل حين ضمّنا جميعًا\" ربما كان الخطأ الوحيد الذي ارتكبته هذه المرأة التي تمثل شريحة واسعة من نساء الوطن العربي أنها كانت تحلم بوطن بلا قهر، تحاصرها العادات والتقاليد بـ \"العريس المناسب\"، وتحرق الحرب الأهلية ما تبقى من كرامتها وكيانها، وتسرق الكيانات الإرهابية منها الأمل في غدٍ بلا وجع.\nتكشف لنا سهير السمان في روايتها عن أثر التحولات السياسية والاجتماعية على أوضاع مجموعة من النساء، وبينما تبحث كل واحدة فيهن عن نصيبها من الحب والحياة، يَعُدْنَ فيَلْتَقيْنَ خلف «جنازة واحدة لموت كثير» في وطن ممزق بالصراعات، وتديُّن زائف متشح بالسواد.\nسهير رشاد السمان، روائية وناقدة يمنية تقيم في القاهرة. حاصلة على الماجستير في النقد الأدبي من جامعة القاهرة. صدرت لها ثلاث مجموعات قصصية، هي: «موعد آخر» و«جزء من النص مفقود» و«يحدها من الشمال»، وكتاب نقدي بعنوان: «الرواية اليمنية في الألفية الثالثة.. التقنيات السردية ورؤية العالم». حاصلة على جائزة رئيس الجمهورية في القصة القصيرة باليمن.", CategoryId = 1, ImageUrl = "/images/products/9789777955249.webp", Author = "سهير السمان", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789777955249" },
            new { Id = 54, Name = "مادريجال الليل", Price = 200m, Stock = 10, Description = "راوٍ يعاني الأرق والذعر من انهيار العالم، مؤلف موسيقيّ عبقري يتحول إلى قاتل دموي في عصر النهضة، شخصياتٌ حية وأخرى تمردت على صفحات الكتب، وكلبٌ يستمع للموسيقى الكلاسيكية.. تُرى كيف يجمع ظلام الليل كل هؤلاء؟\nفي مغامرته الفنية الأكثر جرأة يصحبنا ولاء كمال في ليلتين مليئتين بالغرابة والدهشة، ليقدم لنا رؤيته للعالم والإنسان عبر ليلةٍ عجيبة يقضيها الراوي بمحطة وقود. بينما في زمنٍ آخر، وتحديدًا في إيطاليا القرن السادس عشر، نعيش أحداث ليلةٍ أخرى دامية وذات آثار مروعة، ترويها لنا محاضر التحقيقات وشهادات من عاصروها، لنخوض مع صفحات الرواية وشخوصها مغامرةً وجودية ونفسية مذهلة، ندرك خلالها أن الليل ليس فقط ما نعيشه.. ولكن ما يسكن بداخلنا.\nولاء كمال، كاتب وروائي ومترجم مصري. صدرت له عن الدار المصرية اللبنانية أربع روايات، وكتاب \"أيامي مع كايروكي: حكاية جيل أراد أن يغير العالم\". رُشحت روايتاه \"القداس الأخير\" و\"كوش كو\" لجوائز أدبية محلية وإقليمية، كما صدرت له عدة كتب مترجمة. درس الترجمة والإعلام والإخراج السينمائي، وحصل على درجة الماجستير في الأدب العربي من الجامعة الأمريكية بالقاهرة.", CategoryId = 1, ImageUrl = "/images/products/9789777955881.webp", Author = "ولاء كمال", PublishDate = new DateTime(2026, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789777955881" },
            new { Id = 55, Name = "سيدة الابدية", Price = 275m, Stock = 10, Description = "\"تنفتح بوابة السر للمرة الوحيدة في ألف عام،\nفإن دخلت المنسية لمولد النور،\nمن الدمع ولدت ومن الدم تعود،\nسُفك الدم وانبثقت الذاكرة،\nواستيقظت التي كانت من قبل الزمان\".\n***\nهناك قوى لا تستيقظ.. بل تتذكر لتطالب بحقها المسلوب.\n\"سيدة الأبدية\" رواية عن المنسيين الذين كُتب عليهم أن يحملوا كلمات المصير. تدور أحداثها في ليلة واحدة تكشف أسرارًا بعمر الكون.. من حكايات النيل إلى لعنات السماء، نخوض رحلة ملحمية تستحضر صراعات النور والظلام، في عالم يعيد كتابة تاريخه.\nشخصياتها تمضي على حافة الحقيقة، حيث لا خلاص بلا مواجهة، ولا معرفة بلا نار.\nففي النهاية.. الدم هو الذاكرة، والغضب هو البوابة.\nطارق عز.. روائي وقاص ومترجم مصري، صانع محتوى متخصص في الكتابة والقراءة. يعمل بالطيران المدني، نُشرت له قصص قصيرة في مجموعات قصصية مشتركة، مثل \"اعترافات\"، و\"اليوم الأخير\". حاصل على جائزة أفضل قصة قصيرة في مسابقة\"iRead\" لعام 2021، والقائمة القصيرة لنفس الجائزة 2022. وقد صدرت له ترجمة رواية \"ينابيع واكولا\" الحاصلة على جائزة أفضل رواية قصيرة 2013، ونالت روايته الطويلة الأولى «أسفار مريم المحرمة» استحسانًا وإقبالًا جماهيريًّا واسعًا، وتصدرت قوائم الأكثر مبيعًا، وتُعد «موت مع إيقاف التنفيذ» مجموعته القصصية الأولى، و«سيدة الأبدية» العمل الأدبي الثالث له.", CategoryId = 1, ImageUrl = "/images/products/9789777955874.webp", Author = "طارق عز", PublishDate = new DateTime(2026, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789777955874" },
            new { Id = 56, Name = "دراما كوين", Price = 275m, Stock = 10, Description = "لا أحد يعلم ماذا يحدث في الداخل، نساء يصرخن، يضحكن، يبكين، كل منهن جاءت إلى المكان من أجل شيء لا يعلمه أحد سواها، يترك العمود سيئ السمعة على أجسادهن كدمات، ويحررهن من كدمات أخرى لا يراها أحد.\nفي استوديو مخصص لرقص \"الپول\" تجتمع نساء غريبات، كل منهن جاءت لسبب مختلف عن الأخرى، لكن حياتهن جميعًا تغيرت تمامًا، فكيف يمكن لعمود أن يقلب حياتهن؟\nنهلة كرم: كاتبة وروائية مصرية، من مواليد القاهرة سنة 1989. تخرجت في كلية الإعلام جامعة القاهرة. صدرت لها ثلاث روايات: \"على فراش فرويد\"، \"المقاعد الخلفية\" الفائزة بجائزة ساويرس، و\"خدعة الفلامنجو\" التي وصلت إلى القائمة الطويلة لجائزة كتارا. كما صدرت لها مجموعتان قصصيتان: \"أن تكون معلقًا في الهواء\"، و\"الموت يريد أن أقبل اعتذاره\"، اللتان وصلتا إلى القائمة القصيرة لجائزة ساويرس.", CategoryId = 1, ImageUrl = "/images/products/9789777955713.webp", Author = "نهلة كرم", PublishDate = new DateTime(2026, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789777955713" },
            new { Id = 57, Name = "طريق الى الرواية ظواهر وقراءات وقضايا", Price = 300m, Stock = 10, Description = "يضم هذا الكتاب مجموعة من الكتابات حول فن الرواية؛ تستكشف في قطاع منها بعض الظواهر التي تناولتها أعمال روائية.. وتتوقف، في قطاع آخر، عند بعض التناولات والمعالم الجمالية لعدد من الروايات.. وتعرض، في قطاع ثالث، لمجموعة من القضايا التي طُرحت، وما زالت تُطرح، حول الرواية من حيث مسيرتها التاريخية، أو تكوينها، أو حضورها، أو تأثيرها..\n***\nيجمع بين هذه الكتابات أنها جميعًا تتصل بالنوع الروائي، وأنها كلها تُمثِّل خطوات على طريق واحد لمقاربة هذا النوع الأدبي، وأنها بأكملها صدرت عن كاتب واحد ظل يسعى إلى الإصغاء لما تقوله، وكيف تقوله، النصوص الروائية.", CategoryId = 7, ImageUrl = "/images/products/9789777955867.webp", Author = "حسين حمودة", PublishDate = new DateTime(2026, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789777955867" },
            new { Id = 58, Name = "الوارث", Price = 350m, Stock = 10, Description = "لعنةٌ تخرج من بين القبور، تصيب كل من يقترب من قبره أو يقرأ كتابه المدفون تحت تراب القاهرة الفاطمية، إنه عبد الله الحظرد، نديم الخليفة الأموي، الوليد بن عبد الملك، وأمهر سحرة العرب الذي وضع كتابه «العزيف» قبل أن يموت مقتولًا على يد أحد خلصائه من الجن، لكنه، وبينما يلفظ أنفاسه الأخيرة، استطاع قراءة تعويذة أحكمت قبضتها على «جِني الغابر» وحبسته بين دفتي الكتاب.\nفي هذه الرواية+ الأسطورة، يتأجج الصراع بين ثلاث عائلات، الكاشف، والرملي، والعاصي، تريد كل واحدة منهن العثور على كتاب «العزيف» والاستحواذ عليه، في صراع يقتات على دمٍ مسفوح لأشخاص ارتبطت أقدارهم بهذا الكتاب فلم يعد لهم إرادة في دفع قدر ملعون ولعنة أبدية.\nأحمد عثمان\nروائي وكاتب سيناريو، مواليد القاهرة 1982. تخرّج في كلية الهندسة – قسم العمارة.\nصدر له عدد من الأعمال الروائية، من بينها \"القديس\" و\"3110\"، وسلسلة حلمي مهران.\nألّف فيلم قبل الأربعين، ومسلسل روحي فيك، وحصل على جائزة القلم الذهبي لأفضل سيناريو عام 2025.", CategoryId = 1, ImageUrl = "/images/products/9789777955843.webp", Author = "احمد عثمان", PublishDate = new DateTime(2026, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789777955843" },
            new { Id = 59, Name = "ما وراء الاوراق", Price = 240m, Stock = 10, Description = "يقدم هذا الكتاب تجربة المؤلفة في التعامل مع القضايا منذ وصولها إلى مكتبها، وكيفية دراسة كل قضية على حدة، والبحث وراء السطور من أجل التوصل إلى الحقيقة، قبل طرحها أمام القضاء في قاعة المحكمة.\nست عشرة قضية ضمها الكتاب، اختارتها الأستاذة نهاد أبو القمصان من مئات القضايا التي عملت عليها، حاولت المؤلفة في كل حكاية منها أن تضع صوت المظلوم في المقدمة، وأن تقاوم محاولات النفوذ والمال لتأكيد مسار العدالة.\nوتوضح المؤلفة أنها لا تقدم للقارئ مجرد حكايات؛ وإنما تكشف كيف يمكن للمحامي أن يكون شاهدًا على المجتمع، مدافعًا عن المظلوم، وناقلًا لصوت الحقيقة في مواجهة النفوذ والظلم.\nوتسعى إلى أن يكون الكتاب مرشدًا للطلاب والباحثين عن كيفية التعامل مع القضايا عامة، والجنائية تحديدا، وأن يكون- كذلك- مصدر وعي للقراء العاديين، حتى لا يقعوا في أخطاء قد تقودهم إلى ساحات القضاء.\nنهاد أبو القمصان.. محامية مصرية، عضو المجلس القومي لحقوق الإنسان، وأمين عام المجلس القومي للمرأة سابقًا، وخبيرة بالأمم المتحدة والبنك الدولي، ومديرة بيت الخبرة النوعي والقانوني، ورئيسة المركز المصري لحقوق المرأة. مقدمة برامج تلفزيونية.  حاصلة على جوائز وطنية ودولية عديدة آخرها ‎وسام الاستحقاق المدني  عام 2020 والذي تسلمته من ملك إسبانيا.", CategoryId = 7, ImageUrl = "/images/products/9789777955836.webp", Author = "نهاد ابو القمصان", PublishDate = new DateTime(2026, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789777955836" },
            new { Id = 60, Name = "عودة التمائم", Price = 275m, Stock = 10, Description = "في هذه الرواية تأخذنا \"عبد المجيد\" إلى الأرض التي تتصدَّر المشهد الحالي وتتجه إليها الأبصار..\nالأرض التي تحتاج تميمة من الأمل.. الأرض التي كانت يومًا، وستبقى دومًا أيقونة خيرٍ وجمال..\n‏رحلة تمتد منذ عام 1969م وحتى نهاية 2023م ، تكشف فيها عن موروثات وعادات ما كانوا يتحدثون عنها يومًا..\n‏عن صراعات سياسية واجتماعية اضطرت الكثيرين في النهاية إلى مغادرة البلاد قسرًا وجبرًا..\n‏لكن رغم الألم والفساد..\nرغم الموت والدمار.. تبقى القصص حيَّة تُروَى وتُخلَّد على صفحات التاريخ.. وفي النهاية التمائم إلى أرضها لا بد وأن تعود، فمهما تباعدت الخطى.. اللقاء حتمي.. والتاريخ لا يَنسى..\nالظلم دومًا نهايته الزوال!\nنور عبد المجيد. شاعرة وروائية. شغلت منصب مساعد رئيس تحرير مجلة \"روتانا\"، ولها ديوان شعر \"وعادت سندريلا حافية القدمين\". وروايات منها: \"رغم الفراق\"، و\"أريد رجلًا\"، و\"أنا شهيرة\"، و\"أنا الخائن\"، و\"أنتِ مني\" و\"كان\"، وتم تحويل رواياتها إلى أعمال درامية، وتُرجمت بعض أعمالها إلى اللغة السويدية.", CategoryId = 1, ImageUrl = "/images/products/9789777955720.webp", Author = "نور عبد المجيد", PublishDate = new DateTime(2026, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789777955720" },
            new { Id = 61, Name = "خارج الكهف", Price = 200m, Stock = 10, Description = "\"هدأت نفسه قليلًا، ولكنه عاد يشعر بقسوة الوحدة عندما قام الرجل واختفى داخل الكهف. ملأت السعادة قلبه عندما نظر فرأى على مقربة من الكهف مدينة ذات عمائر وقصور وقلاع. ظل ناظرًا إليها مبهورًا.\nلم تكن هذه المدينة هنا، فكيف ظهرت بغتة؟ أنا لم أتحرك من مكاني، فهل كانت المدينة تسير نحوي؟ هذا مستحيل. ماذا حدث إذن؟\".\n***\nتنتمي هذه المجموعة القصصية إلى العالم الأسطوري الحالم، الذي يبدأ بحدث واقعي مدهش، وينتهي بنا إلى نهايات غير متوقعة، فيضفي على كل ما هو واقعي سحرًا خاصًّا ورمزية غاية في التشويق.\nفقصص مثل: \"نور الشفق، القطار، ليلة العاصفة\"، تعبر عن النفس البشرية بكل أحلامها وإخفاقاتها وضآلة الإنسان بالنسبة لأسرار الكون، مهما أوتي من علم. أما \"الجمجمة\" -التي لم تنشر من قبل- فيجمع فيها د. يوسف عز الدين عيسى بين الأمراض النفسية وتأثيرها على الجسد.\nد. يوسف عز الدين عيسى، جمع بين العلم والأدب في أعلى مستوياتهما، فهو أديب له عالمه الخاص، حصل على جائزة الدولة التقديرية في الأدب وغيرها من الأوسمة الرفيعة. تأثر أدبه بروح العصر فعبر عن الإنسان وحلل النفس  البشرية بكل نوازعها وأحلامها وصراعاتها بأسلوب شيق يتأرجح بين الحلم والواقع، الخيال والحقيقة. كسرت رواياته الحاجز التقليدي للرواية العربية، وهو من أول رواد الواقعية السحرية فيها.", CategoryId = 1, ImageUrl = "/images/products/9789777955812.webp", Author = "يوسف عز الدين عيسى", PublishDate = new DateTime(2026, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789777955812" },
            new { Id = 62, Name = "بكوات وباشوات", Price = 330m, Stock = 10, Description = "«فلاح خرسيس».. كانت هذه الجملة الشهيرة تتردَّد على لسان الباشا صاحب العِزبة، وهو يحمل الكُرباج بيده ويهوي به على ظهور الفلاحين المحنية بفعل القهر! صورة رسَّختها الدراما المُسيَّسة في أذهاننا، وهي تصنع في عقولنا ذلك الارتباط الشَّرْطي المعيب بين البكوات والباشوات من جانب، وبين الإقطاع والاستغلال الاقتصادي والسياسي من جانب آخر. صحيح أن ألقاب البكوات والباشوات كانت كالسلعة تُباع وتُشتَرى، لكن هناك رجال حصلوا عليها عن جدارة، ودون سعي منهم أو طلب. رجال قدَّموا لهذا البلد ما ظل كشجرةٍ وارفةِ الظلال، أصلها ثابت وفرعها في السماء.\nإن هذا الكتاب يتناول تاريخ ما أهمله التاريخ: سِيَر رجال كانت إنجازاتهم أعلى من الألقاب، وفي ثنايا حكاياتهم وجبة دسمة من تاريخ مصر جغرافيًّا وسياسيًّا واقتصاديًّا واجتماعيًّا، وجرعة مكثفة من تاريخ الحجر والبشر، الزمان والمكان، وتصحيح لمفاهيم مغلوطة رسَّختها حركة 23 يوليو التي شابها عوار سياسي وإنساني واقتصادي وقانوني. وكان العوار الأكبر - في تقديري - هو محاولتها تزييف الوعي الجمعي عَبْرَ مَن يحلو لي تسميتهم «ترزية التاريخ».\nسهير عبد الحميد، كاتبة صحفية، مدير تحرير «الأهرام»، وباحثة في التاريخ. صدر لها: قصور مصر، إسكندرية من تاني، اغتيال قوت القلوب الدمرداشية، على عتبة المقام، سلسال الباشا، ناحوم أفندي، يهود الظاهر.", CategoryId = 7, ImageUrl = "/images/products/9789777955782.webp", Author = "سهير عبدالحميد", PublishDate = new DateTime(2026, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789777955782" },
            new { Id = 63, Name = "اسرار الكتابة", Price = 300m, Stock = 10, Description = "رحلةٌ عمليةٌ ومُلهِمةٌ في أسرارِ الإبداعِ كما عاشها ودوَّنها سبعة عشر كاتبًا وكاتبةً من مشاهير الأدب العالمي.\nلا تُقَدَّم الكتابةُ هنا بوصفها موهبةً غامضةً حكرًا على قلةٍ مُختارةٍ، بل كمسارٍ يمكنُ تعلُّمُهُ وصقلُه وتطويرُهُ عبر استراتيجياتٍ واضحةٍ ونصائح مجرَّبة. تجمعُ المترجمة والشَّاعرة والأكاديمية سارة حامد حوَّاس خلاصاتِ تجارب هؤلاء الكُتَّاب، وتعيدُ تقديمَها إلى القارئ ، لتضعَ بين يديه مفاتيح للكتابةِ المؤثِّرةِ ..كيف تبدأ؟ كيف تستمرُ؟ كيف تتغلبُ على الخوفِ والتردُّد وحبسة الكتابة؟ وكيف تُحوِّلُ الأفكار المُبعثرة إلى نصٍّ ينبضُ بالمعنى؟\nما يجعل هذا الكتاب مختلفًا هو أنه لا يكتفي بسردِ تجارب الآخرين، بل يُحفِّزُك على النظرِ إلى نفسِكَ ككاتبٍ مُحتملٍ، ويطرحُ أسئلةّ تجعلك تعيدُ التفكيرَ في علاقتكَ بالكتابةِ، ولماذا تكتبُ، ولمَن.\nإنه كتابٌ يشبهُ ورشةَ كتابةٍ مفتُوحةً، ومرشدًا صامتًا يرافقُكَ خُطوةً بخطوةٍ.\nد. سارة حامد حوَّاس، مدرس بقسم اللغة الإنجليزية، بآداب المنصورة، مترجمة وشاعرة. صدر لها في الترجمة والشِّعْر عدة كتب، منها: \"ثُقب المفتاح لا يَرَى.. عشرون شاعرة أمريكية حائزات على جائزتيْ نوبل وبوليتزر\"، الذي وصل إلى القائمة القصيرة لجائزة جابر عصفور للترجمة، و\"ولاؤهم للروح.. عشرون شاعرًا أمريكيًّا حائزًا على جائزة بوليتزر\"، و\"في قلبي قارة.. عشرون شاعرة وشاعرًا أفرو‑أمريكيًّا\"، وترجمة كتاب \"قبلة رُوحي\".. مختارات من شعر أحمد الشهاوي صدرت في كلكتا بالهند، وديوانها الشعري \"جبل على كتفي\".\nتحرير وتقديم :- احمد الشهاوى", CategoryId = 8, ImageUrl = "/images/products/9789777955829.webp", Author = "أحمد الشهاوي", PublishDate = new DateTime(2026, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789777955829" },
            new { Id = 64, Name = "صاحب الصوت الأزرق", Price = 250m, Stock = 10, Description = "ليس كل صوت يُسمع.\nكل ما أراده (جلال) هو معرفة من يخاطبه، ولم يدرِ أن الطريق إليه يمر عبر طقوس دموية، وعوالم افتراضية، وطائفة دينية، وكيانات واعية.. وسط أحوال تذوب فيها الفواصل بين اليقين والوهم، وبين البشر ومن هم غير ذلك.\nرواية تتتبع رحلة عقل إلى حدوده القصوى..\nحيث الجواب موجود.. لكنه ينتظرك في مكان غير موجود.\nد. شريف عرفة\nالكاتب الأكثر مبيعًا في علم النفس الإيجابي.\nحاصل على ماجستير علم النفس الإيجابي التطبيقي، وماجستير\nفي إدارة الأعمال، وبكالوريوس طب وجراحة الأسنان.\nتُرجمت مؤلفاته للإنجليزية وحاز جوائز وتكريمات عديدة.", CategoryId = 1, ImageUrl = "/images/products/9789777955744.webp", Author = "شريف عرفة", PublishDate = new DateTime(2026, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789777955744" },
            new { Id = 65, Name = "ليل القاهرة السرى", Price = 300m, Stock = 10, Description = "في حفل توقيع روايته الجديدة بفندق الماريوت٬ يفاجئ الكاتب الشهير (يوسف سليمان التركي) بزائر خاص من الماضي٬ كيان شيطاني يتخذ شكل (فرانز كافكا). وقبل أن يهرب منه يوسف يحتجزه كافكا في مصعد الفندق ليخبره أن الليلة ليست ليلة عادية٬ وانما ليلة الحساب ودفع الثمن للعقد الذي أبرماه معًا منذ 15 عامًا٬ وأن يوسف سيمضي ليلة خاصة سوداء٬ مُطارد من قِبل كل ذنوبه، لأن هناك عدوًا خفيًّا له حصل على امتياز كتابة ليلة كاملة من حياته، وأن كل ما سيكتبه سيحدث.\nتدور الرواية في ثلاث ليال٬ الليلة الرئيسية في حاضر ٬2025  وليلتان من العام 2010. نرى خلالها كيف بدأت العلاقة بين يوسف وذلك الشيطان، وكيف تخلى الكاتب المغمور عن مبادئه أمام الغواية، وكيف سقط في بئر سحيقة مطاردًا أحلامه، وكيف سينعكس ذلك على ليلة خاصة جدًّا من حاضره، سيهرب فيها من ماضيه وذنوبه، وسيطارد كاتبًا مهووسًا يريد تدميره، في ليلة مليئة بالندم والدماء، والألغاز، والبحث عن الخلاص، والنبش في الماضي.\nميخائيل عماد، صيدلاني وروائي مصري من مواليد 1995، صدرت له أربع روايات حتى الآن٬ من ضمنها (أثر اليعسوب) و(الخريف في بالم تاون) واستطاع لفت الأنظار عن طريق صوت أدبي خاص وأفكار غير معتادة. كما شارك في كتابة عدة مسلسلات وأفلام وبرامج مثل (الدحيح) و(في الحضارة).", CategoryId = 1, ImageUrl = "/images/products/9789777955690.webp", Author = "ميخائيل عماد", PublishDate = new DateTime(2026, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789777955690" },
            new { Id = 66, Name = "حروب فاتنة", Price = 150m, Stock = 10, Description = "باب الأبراج لم يكن مجرد ورقة أسلِّمها لرئيس قسم \"بريد القراء\" في جريدتنا، كنت مقتنعًا أكثر من أي شخص آخر بأن الأبراج لها تأثيراتها الحقيقية علينا، على حياتنا وعلاقاتنا بالآخرين ومصائرنا. أقرأ كثيرًا من المراجع في الأبراج، محاولًا فهم حركتها، وطريقة حساب علاقاتها المتشابكة، كيف ترضى عنا، وكيف تنقلب علينا؟ كيف تكون محايدة، وكيف تتدخل في شؤوننا كعاصفة تقتلعنا من جذورنا؟\n***\n\"حروب فاتنة\" واحدة من أكثر المجموعات القصصية نجاحًا، فقد حظيت بمراجعات ومقالات ودراسات متنوعة، وفازت بجائزة يوسف إدريس للقصة القصيرة، وعدَّها النقاد واحدة من قمم القصة المصرية والعربية، وترجمت مجلة \"بانيبال\" بعض قصصها إلى الإنجليزية والإسبانية، ووصفتها بأنها \"لا تُنسى\".\nحسن عبد الموجود، كاتب مصري، صدرت له روايتان، وخمس مجموعات قصصية، وأربعة كتب في السيرة والصحافة الأدبية. حصل على جائزة دبي للصحافة الثقافية، وجائزة يوسف إدريس للقصة، وجائزة ساويرس للرواية، وجائزة معرض القاهرة الدولي للكتاب لأفضل مجموعة قصصية. تُرجمت أعماله إلى الإنجليزية والإسبانية والفرنسية والألمانية.", CategoryId = 1, ImageUrl = "/images/products/9789777955706.webp", Author = "حسن عبد الموجود", PublishDate = new DateTime(2026, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789777955706" },
            new { Id = 67, Name = "رمل وزبد", Price = 140m, Stock = 10, Description = "يضم الكتاب مجموعة من الحكم والتأملات التي وضعها جبران من أجل محاربة الآفات الاجتماعية كالغش والخداع والنفاق والحسد، وهي الأمراض التي فرضها التنافس غير الأخلاقي بين البشر، في أثناء سعيهم من أجل المادة. ويقدم المؤلف وجبة فلسفية عميقة تغلفها لغة شاعرية رقيقة في تلمسها المعنى من أجل إيصاله إلى القلوب، وفي تصيدها لغة رمزية تحرص على تبسيط الحكمة وتقريب الفلسفة. إن هذا الكتاب على صغر حجمه قد حوى بين دفتيه آراء جبران في موضوعات شتى كالأخلاق والشعر والتصوف ونظرية الجمال، وهي كلها موضوعات لا تزال تشغل حيزا في تفكير الإنسان المعاصر، وقد عالجها جبران هنا بعمق فلسفي يلامس النفس البشرية ويتسلل إلى أعماق وجدانها .", CategoryId = 7, ImageUrl = "/images/products/9789777955485.webp", Author = "جبران خليل جبران", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789777955485" },
            new { Id = 68, Name = "مذكرات صلاح دياب", Price = 470m, Stock = 10, Description = "طالبني بعض الأهل والأصدقاء والمقربين بتوثيق قصة حياتي، وكلما مرَّ الوقت ازداد الإلحاح، ومعه ازدادت حيرتي! وأمام هذه الحيرة تدفقت على الخاطر جملة من الأسئلة، أولها هو: هل سأكتب بنفسي؟ وبالفعل اتخذت قراري بعد تفكيرٍ عميق: نعم، سأكتب بنفسي. تلاه سؤال ثانٍ أصعب: هل أستطيع أن أسرد كل شيءٍ؟\nلا يهم.. المهم أنني سأكتب.. هذا كان القرار.\nلذلك لن تجد في هذه المذكرات شخصًا مثاليًّا. فقد كانت لي أخطاء وحماقات، كما كانت لي أفعال أفخر بها. غامرت حتى الثمالة، ودفعت ثمن مغامراتي كاملًا. مررت بنجاحات وإخفاقات. تحمَّلت اختبارات قاسية. حصلتُ على الكثير من المنح، كما تعرضت للكثير من المِحَن.\nفي رحلتي تعرَّفت على بشر من كل نوع. بعضهم فرحت بدخوله إلى حياتي، وآخرون فرحت بخروجهم من دائرتي، ومنهم مَن ظل في المساحة الرمادية، فأجده بجواري حينًا، وأبحث عنه ولا أجده أحيانًا أخرى.\nقد تكون هذه المرة الأولى التي أتحدث فيها عن نفسي، فأنا لست محترفًا في فن الكلام، لكنني.. وللمرة الأولى - وربما الأخيرة - أجدني بحاجة إلى البوح بما يعرفه بعض المقربين منِّي، وبما لم يعرفه أحد من قبل.", CategoryId = 7, ImageUrl = "/images/products/9789777955324.webp", Author = "صلاح دياب", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789777955324" },
            new { Id = 69, Name = "السماء لا تمطر حكايات", Price = 280m, Stock = 10, Description = "\" بعض الكلمات تظل عالقة في ذهني، وحين أكتب تعليقًا على رواية أعجبت ببطلها يأتي ناقصًا في المعنى، ولا تأتي مشاعري كما أشتهي، ويبقى إحساسي ناقصًا يحتاج إلى أن يخرج بطل الرواية عن النص ويضمني بالمعنى الناقص في واقعي\".\n***\n\"السماء لا تمطر حكايات\".. رواية عن امرأة تكتشف أن الكلمة قد تُسرق، لكن الروح لا تُنتزع.\nفي عالمٍ يُكافأ فيه مَن يتحدث بصوتٍ أعلى، تبقى \"حنان\" مجرد ظل في حياة الأدب. تكتب، وتحلم بنشر روايتها الأولى.. حتى تأتي الخيانة من أقرب الناس إلى روحها: مَن أحبَّته واعتقدت أنه الوحيد الذي يؤمن بأنها كاتبة. تستيقظ على كابوس نشر روايتها الأولى باسمه، وتتحول من \"كاتبة حالمة\" إلى \"ملهمة مجهولة\".\nتقف \"حنان\" أمام قرار مصيري: هل تستعيد أفكارها؟ أم تستعيد نفسها؟ أم تمتهن بيع الأفكار للروائيين المفلسين.\nزينب عفيفي.. كاتبة وروائية، صدر لها ثمانية عشر عملًا ما بين قصص قصيرة وكتب وروايات منها: \"شمس تشرق مرتين\" و\"خمس دقائق\" و\"أهداني حبًّا\" و\"أحلم وأنا بجوارك\" و\"معك تكتمل صورتي\"، و\"عزيزي المستبد\"، و\"عملية تجميل\".. تُرجمت بعض قصصها إلى اللغة الإنجليزية عن دار نشر أسترالية وبعضها تُرجم إلى اللغة الإيطالية. لها العديد من المقالات الأسبوعية في الأدب والثقافة. حازت جائزة أفضل صفحة في مجال الكتب في الصحافة الثقافية المصرية عام 2015م. حصلت على جائزة يوسف إدريس في دراسة بحثية نقدية عن أدبه.", CategoryId = 1, ImageUrl = "/images/products/9789777955799.webp", Author = "زينب عفيفي", PublishDate = new DateTime(2026, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789777955799" },
            new { Id = 70, Name = "ثلاثية الغربة", Price = 285m, Stock = 10, Description = "إننا، ببساطة مدهشة آسرة، أمام موت معلن منذ الصفحات الأولى، ندرك في الآن ذاته أنه مجازات حياة لا تقل احتشادًا بالصخب والكتمان والغرام.\nصبحي حديدي - من كلمته على غلاف \"غرفة ترى النيل\" 2004.\nيقدم لنا القمحاوي في \"البحر خلف الستائر\" تنويعاته المتفردة على ما سميته بتجربة الخروج العربي. وهي تجربة ثرية في الأدب المصري.\nصبري حافظ عن «البحر خلف الستائر» جريدة التحرير 2014.\nبخفة الثعبان الذي يخاف ويخيف ـ يستعير القمحاوي لغة المدينة ليواجهها بأقوالها وأساطيرها نازعًا عنها عباءتها التي لا تستر عورة.\nعبدالرحمن الأبنودي ـ عن «مدينة اللذة» في كتابه النثري «آخر الليل».\n“مدينة اللذة”، عمل فذ، وعلامة فارقة في فن القص العربي. نص بالغ الدقة والإحكام والحساسية.\nفتحي أبو رفيعة ـ من كتابه «تفكيك السرد».\nمن اليأس تأتي هذه الكتابة. كل لذة يجب أن تؤخذ ضمن حدود اللحظة. كل جمال في حقيقته سراب..\nعناية جابر ـ عن مدينة اللذة، جريدة السفير 2009.", CategoryId = 1, ImageUrl = "/images/products/9789777955607.webp", Author = "عزت القمحاوي", PublishDate = new DateTime(2026, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789777955607" },
            new { Id = 71, Name = "محاولات فاشلة للهروب من القدر", Price = 250m, Stock = 10, Description = "هل كان سر نجاح كوكو شانيل هو عمر أفندي؟\nثم ما علاقة مزارع الياسمين في دلتا مصر بسجون هتلر النازية في ألمانيا؟\nولماذا استقل الدكتور سيجموند فرويد قطار الإسكندرية- القاهرة متجهًا إلى جاردن سيتي في مصر؟\nوما العامل المشترك بين الفنان الإسباني سلفادور دالي وأمينة الفلاحة المصرية البسيطة؟\nوهل يمكن تخيل ارتباطٍ وثيقٍ بين الفرنسي چاستون ماسبيرو رئيس مصلحة الآثار المصرية والمقاومة الفلسطينية؟\nفيليب باخ بطل هذه الرواية المثيرة هو الوحيد الذي لديه إجابات عن هذه الأسئلة الغريبة.\nرواية مستوحاة من أحداث حقيقية لرجل عادي ذي أثر مذهل، تحتار في تصنيفه هل هو بطل أم أناني لدرجة تثير الغيظ؟\nكان فيليب باخ يصر على معاندة أقداره وتجاهلها لينتهي به الأمر في رحلة حياة جنونية وخطيرة عكس كل ما يتمناه من الهدوء والحب والسعادة.\nميرنا الهلباوي: كاتبة وإعلامية مصرية. عملت في الصحافة، وترشحت للقائمة النهائية لجائزة الصحافة العربية. عملت مذيعة في راديو NRJ ومراسلة استقصائية مع شبكة BBC للتحقيقات الوثائقية. لديها ثلاثة إصدارات من الأكثر مبيعًا: \"مر مثل القهوة حلو مثل الشوكولا\" و\"كونداليني\" و\"تنذكر ما تنعاد\". وهي مؤسسة حملة Connecting Gaza ومنظمة Connecting Humanity غير الهادفة للربح.", CategoryId = 1, ImageUrl = "/images/products/9789777955577.webp", Author = "ميرنا الهلباوي", PublishDate = new DateTime(2026, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789777955577" },
            new { Id = 72, Name = "بوابات الزمن", Price = 230m, Stock = 10, Description = "يقدم المؤلف في هذا الكتاب قراءة جديدة في دراسة تاريخ مصر القديمة، يتناول خلالها هذا الإرث العظيم من البرديات التي كتبها المصري القديم وتركها على جدران معابده وأهراماته لنعرف منها آدابه وتفاصيل حياته اليومية من دين وزواج وطقوس دفن، إلى جانب ما رصدته هذه البرديات من نشاط الغزاة الذين نهبوا خيرات مصر، ويكشف لنا عن أطوار الصعود والهبوط خلال بوابات الزمن التي مرَّت بها الحضارة المصرية القديمة، وقد نجح في عقد خيط يضم عددًا من الوقائع يجمعها رابط واحد هو الإنسان المصري وحضارته الموغِلة عبر آلاف السنين.\nتثبت هذه \"البوابات\" بما لا يدع مجالًا للشك أن الحضارة المصرية لم تكن مجرد حضارة مادية فقط تمثَّلت في بناء الأهرام وتشييد المعابد، بقدر ما كانت أيضًا حضارة روحية تجلّت فيها قيم المعتقد بالحياة الآخرة ورسَّخت فكرة العدالة (الماعت) التي صارت لبِنة أساسية في البناء الأخلاقي للمصريين القدماء.\nد. شريف شعبان، كاتب وخبير في الآثار المصرية، ومؤرخ فني. حاصل على الدكتوراه في الفنون المصرية القديمة. عمل محاضرًا لمادة تاريخ الفنون بجامعة القاهرة. صدرت له عدة روايات وكتب ومترجمات، منها: الأسقف ومناظرها عبر العصور (2011)، المآدب والولائم في مصر القديمة وحضارة الإغريق (2016)، يهود مصر القديمة (2012)، النبي المفقود أخناتون (2022)، موسوعة رحلة إلى الشرق القديم: مصر وجيرانها في 3 آلاف (2024)، أشهر خرافات الفراعنة (2025)، وروايتين: بنت صهيون (2015)، و 3 نبوءات سوداء (2017).", CategoryId = 7, ImageUrl = "/images/products/9789777955683.webp", Author = "شريف شعبان", PublishDate = new DateTime(2026, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789777955683" },
            new { Id = 73, Name = "الأرانب الحجرية", Price = 375m, Stock = 10, Description = "يضم هذا الكتاب سبعين حكاية خرافية، يتداولها الناس في قرى مصر ومدنها، عمن يستحضرون الجان، أو ما يأتيه السحرة والمشعوذون والعرافون من قارئي الكف والتاروت والفنجان والمَندل وضاربي الودَع والمهتمين بحسابات النجوم والفلك، والساعين خلف الكنوز المطمورة، والمبالغين في تصوير كرامات الأولياء والقديسين، والمعتقدين في التمائم والحروز والطلاسم، ومَن يشغلهم الخوف من الحسد والعفاريت، وتجذبهم حكايات عمَّا بعد الموت، ويصدقون النبوءات القديمة، وأولئك الذين يؤمنون بالفيوضات الروحية التي تجلب الطاقة الإيجابية، ومَن يتمسكون بأرقام وأشياء جالبة للحظ.\nلقد سمعت من أهل قريتي هذه الحكايات العجيبة صغيرًا، وتعاملت معها كمادة خام لعمل أدبي، قاصدًا ألا أتركها في سيلانها وجريانها على الألسنة هائمة عائمة، إنما راسية بين سطور مكتوبة، هي في خاتمة المطاف روايتي لهذه الحكايات العجيبة المدهشة المملوءة بالشغف والرعب والإيهام والإلهام والأمل.\nسبعون حكاية عن عوالم خفية، لعل القارئ يكتشف بها ومعها ثراء مخيلة أهلنا الذين سردوا هذه الحكايات عبر آلاف السنين، ويكتشف في رحابها قدرة جيلنا على الاستفادة منها، وتقديمها سِفرًا من أسفار عجائبيتنا وغرائبيتنا الساحرة.\nعمار علي حسن، أديب ومفكر مصري، أصدر اثنين وستين كتابًا، نصفها أعمال أدبية هي روايات ومجموعات قصصية ودواوين شعرية ومسرحية وسيرة ذاتية ونصوص عابرة للأنواع، ونصفها الآخر كتب في الاجتماع السياسي، والنقد الأدبي والثقافي، والتصوف، والفكر. أُعدت حول رواياته وقصصه عشرون رسالة جامعية داخل مصر وخارجها، وصدرت عنها كتب ودراسات نقدية، وتُرجمت بعض أعماله العلمية والأدبية إلى عدة لغات، ونال عنها جوائز كبرى.", CategoryId = 1, ImageUrl = "/images/products/9789777955676.webp", Author = "عمار على حسن", PublishDate = new DateTime(2026, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789777955676" },
            new { Id = 74, Name = "زوجة أحمد", Price = 200m, Stock = 10, Description = "\"وعاد زوجي من إحدى سهراته «الرجالي» بعد منتصف الليل.. وأيقظني بقبلاته.. وأخذ يروي لي تفاصيل سهراته مع أصدقائه.. ونمنا.\nوفي الصباح، وعندما كنت أضع يدي في جيوبه لأنقل حاجياته من بدلة إلى بدلة تعلقت عيني بمنديله..\nلقد كان في المنديل بقعة كبيرة من آثار أحمر شفاه، تلمع أمام عيني كأنها جذوة من نار..وتصاعدت الدماء إلى رأسي.. أحسست أن الدنيا تدور بي.. وأن كتلًا من الظلام تتجمع أمام عيني حتى لم أعد أرى شيئًا..\".\nولد أول يناير 1919 بالقاهرة، تخرج في كلية الحقوق عام 1942.  بدأ حياته كاتبًا سياسيّا ورئيسًا لتحرير مجلة روزاليوسف التي أسستها والدته فاطمة اليوسف. فجّر قضية الأسلحة الفاسدة التي استخدمت في حرب فلسطين.  تقلد عددًا من المناصب الصحفية كان آخرها رئيسًا لتحرير ولمجلس إدارة مؤسسة الأهرام، وبعدها تفرغ للكتابة حتى وفاته 11 يناير 1990.  أنتج المئات من الروايات والمجموعات القصصية التي تحوّل معظمها إلى أعمال سينمائية وإذاعية وتليفزيونية. حصل على العديد من أرفع الأوسمة والجوائز وشهادات التقدير المحلية والعالمية.", CategoryId = 1, ImageUrl = "/images/products/9789777955645.webp", Author = "احسان عبد القدوس", PublishDate = new DateTime(2026, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789777955645" },
            new { Id = 75, Name = "موسي علية السلام", Price = 190m, Stock = 10, Description = "يتناول هذا الكتاب قصة خروج بني إسرائيل من مصر، وهي واحدة من أبرز الأحداث المثيرة للجدل في السرد الديني والتاريخي والثقافي، خاصة ما يتعلَّق بسؤال من أكثر الأسئلة جدلًا وغموضًا في الدوائر التاريخية والدينية: مَن هو فرعون موسى؟ وهو السؤال الذي تتولَّد منه أسئلة أخرى، منها: هل كان هذا الفرعون ملكًا مصريًّا من الأسرات المحلية، أم إنه كان من سلالة أخرى تمامًا؟ وما هي الظروف الحقيقية التي رافقت خروج بني إسرائيل من مصر؟ هذه الأسئلة وغيرها شغلت الباحثين والمؤرخين والمهتمين، وحتى الأفراد العاديين، على مر العصور، وفي هذا الكتاب محاولة للإجابة عنها، من خلال جهد بحثي قدَّمه المؤلف مُستندًا إلى خبرة أكاديمية رصينة، نابعة من تخصُّصه في مجال الآثار والحضارة المصرية القديمة، وإلمامه العميق بتحليل النصوص القديمة وفهم الدلالات الثقافية والتاريخية المرتبطة بالأحداث، فضلًا عن دراسة ميدانية مُستمدَّة من معرفته الدقيقة باللغتين المصـرية القديمة، والقبطية، وقد ظهر ذلك بوضوح في مقابلاته بين النصوص المختلفة بهدف تقديم رؤية علمية مدعومة بالأدلة التاريخية واللغوية، وهو ما يُثري محتوى الكتاب ويعزِّز مصداقيته العلمية.\nممدوح محمد الدماطي، وزير الآثار الأسبق، أستاذ الآثار المصرية القديمة منذ عام 2006م. شغل عددًا من المناصب الأكاديمية وغير الأكاديمية. نشر 15 كتابًا، و30 بحثًا علميًّا في الدوريات العلمية الدولية والمحلية، ويرأس تحرير سلسة «مصريات» بالهيئة المصرية العامة للكتاب منذ مارس 2021م. فاز بعدد من الجوائز والأوسمة، أبرزها: وسام «فارس» من رئيس جمهورية إيطاليا (2004م)، جائزة الدولة للتفوق في العلوم الاجتماعية (2010م)، جائزة الدولة التقديرية في العلوم الاجتماعية (2024م).", CategoryId = 7, ImageUrl = "/images/products/9789777955669.webp", Author = "ممدوح محمد الدماطي", PublishDate = new DateTime(2026, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789777955669" },
            new { Id = 76, Name = "ذات الوشاح الوردي", Price = 250m, Stock = 10, Description = "ماذا تعرفون عن الحب؟\nهو قرص من عسل أو ورد على سياج بعيد؟\nوماذا إذا التقى الحبيبان بعد فراق طويل؟ فراق لم يقضِ على حبهما بل أججه في قلبيهما كجمرة مشتعلة تحت الرماد.\nيا لروعة اللقاء الثاني.. وأحلامه.. ووعوده.. ووروده.\nولكن هذه رواية جريمة!\nفهل سيكون اللقاء الثاني نورًا وقُبلة حياة لفدوى ووليد؟ أم سينقلب إلى نار تحرق الجميع؟\nرواية تبدأ بقتل وقصة حب.. فأين ستنتهي؟ وكيف يمكن للعدالة العمياء أن تتحقق بين أتون المشاعر المتشابكة وأسرار الماضي القاتمة؟\nنهى داود، كاتبة مصرية ولدت في إنجلترا عام 1975م، تخرجت في قسم الاتصالات بكلية الهندسة جامعة القاهرة. وبعد أن عملت بمجال تخصصها لسنوات غمرها تيار الشغف، لتعكف على كتابة أولى رواياتها البوليسية بعد أن حصلت على دبلومة الكتابة الإبداعية من جامعة ويزليان الأمريكية، ثم تخصصت الكاتبة في أدب الجريمة. صدر لها 9 روايات منها: \"رضا\"،  و\"جثتان والثالثة عند قدمي\"، و\"دماء على السجادة الحمراء\"، و\"ذبابة زرقاء\".", CategoryId = 1, ImageUrl = "/images/products/9789777955652.webp", Author = "نهى داود", PublishDate = new DateTime(2026, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789777955652" },
            new { Id = 77, Name = "زمن سعاد", Price = 275m, Stock = 10, Description = "تعيدنا هذه الرواية إلى «زمن سعاد»، الفراشة التي ظلَّت تحلِّق بأجنحة الجمال والحب فوق أحلامنا المُجهَضة بالخوف والاستبداد والهزيمة، ولأنها لم تكف عن الطيران يومًا حتى وهي تختار طيرتها الأخيرة في تلك العاصمة الباردة، كان عليها الانسحاب مبكرًا لتنزوي في ركن من الذكريات. وبينما هي كذلك، تأتي هذه الرواية لتكون شاهدة على زمن صعود المسوخ البشرية، وأفول «زمن سعاد» الذي غابت شمسه وانطفأ بريقه بعد أن داهمه ليلٌ حالكٌ أفرخ فيه الظلام خفافيش الفتوى وسدنة التديُّن الشكلي وبيزنس توظيف الأموال، فكان لا بد لسعاد من غياب مُوجِع، وانسحاب بلا عودة، فلم يَعُد هذا زمانها، وربما لم يَعُد زماننا نحن أيضًا! ـــــــــــــــــــــــــــــــــــــــــ\nخالد منتصر، تخرَّج في كلية طب قصر العيني، وشغل منصب مدير الخدمات الصحية بهيئة قناة السويس. صدر له أكثر من عشرة كتب ومجموعة قصص قصيرة.اشتغل بالكتابة الصحفية وله عدد من المقالات المنشورة في الصحف والمجلات، وفي مجال العمل الإعلامي قدَّم برامج طبية وثقافية على عدة فضائيات.حصل على جائزة البحرين لأفضل عمود صحفي عربي في عام 2010.", CategoryId = 1, ImageUrl = "/images/products/9789777955614.webp", Author = "خالد منتصر", PublishDate = new DateTime(2026, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789777955614" },
            new { Id = 78, Name = "أعلام التفكير القانوني", Price = 300m, Stock = 10, Description = "هذا الكتاب رحلة لم تبدأ لتصل، بل لتفتح دروبًا جديدة في بحرٍ لا ساحل له. رحلة تجول بين مدارات القانون، تغوص في أعماقه، وتستضيء بمصابيحه، لتقتنص قبسًا من نور يروي عطش العقول، ويوقظ الأرواح التائقة للمعرفة. إنّه دعوة لاكتشاف مذاقات فكرية لم يجرّبها كثيرون، ولقاء مع حقائق لم يُظن يومًا بوجودها.\nوهذا الكتاب ما هو إلا لبنة في مشروع أكبر، وسطر في سلسلة أوسع تنشد تجديد الصناعة القانونية، وبناء عقلٍ قانونيّ متوثّب، جذرُه في أصولنا الشرعية ومصالحنا المرعية، وفرعُه ممتدّ إلى فضاء الفكر الإنساني الرحب. غايته أن يزرع بذور الوعي، ويُقيم جسور الإلهام، ويُرشد الحائر، ويُلهم العاثر.\nومن رحم هذه الرؤية وُلدت مؤسسة رشد المعارف \"رشد\"، لتكون أيقونة تغيير وإلهام في فضاء القانون والمعرفة. لم تُؤسَّس لتُضاف إلى أعداد المؤسسات القائمة، بل لتكون بصمة متفرّدة، ومَعلَمًا يُهتدى به، ومشروعًا يستلهم من تراثنا الأصيل، وينفتح على تجارب الإنسانية العظمى.\nإن الإنتاج المعرفي الذي تبشّر به \"رشد\" ليس غاية مكتفية بذاتها، بل وسيلة لإعادة صياغة العقل القانوني، وبنائه على الفهم الراسخ، والوعي النافذ، والإبداع الخلّاق. هي مشاريع تحمل وعدًا لجيلٍ جديد من القانونيين؛ جيل يعبر حدود المألوف، ليؤسس لآفاقٍ يستطيع أن يكون فيها أثبتَ قَدمًا، وأبعد رؤيةً، وأعمق فهمًا.\nد.فارس بن محمد القرني", CategoryId = 8, ImageUrl = "/images/products/9789777955591.webp", Author = "أحمد حمدان", PublishDate = new DateTime(2026, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789777955591" },
            new { Id = 79, Name = "نكلة فاروق", Price = 185m, Stock = 10, Description = "في عالمٍ يتقاطع فيه الماضي مع ألاعيب الحاضر، خرجت قطعة صغيرة سرًّا من دار سك العملة في فيلادلفيا عام 1913، واختفت بين الأيدي تاركة أثرًا لا يلاحظه إلا القليل.\nتعاود الظهور بخيط يربط بين قصر القبة أيام فاروق وصخب القاهرة المعاصرة.\nخيط يمسك أطرافَه فريقٌ  لا يشبه بعضه بعضا:\nعباقرة، مشكّكون، وهاربون من ماضيهم. يجمعهم فقط هوس بشيء لا يعرفون إن كان حقيقة أم فخًّا متقنًا.\nرحلة أقرب إلى مطاردة بين زمنين وحكاية تغيّر شكلها كلما شارفت علي النهاية.\nويظل السؤال الحائر بلا إجابة.\nمَن يطارد مَن: الحقيقة… أم الأسطورة؟؟؟\nهشام الخشن.. روائي وقاص مصري، يعمل مهندسًا مدنيًّا. له عدد من الروايات منها: «ما وراء الأبواب»، و«تلال الأكاسيا»، و«حدث في برلين»، و«شلة ليبون»، و«ناعومي وأخواتها». تحوَّلت روايته «7 أيام في التحرير» إلى ملسلسل تلفزيوني، ووصلت روايته «جرافيت» إلى القائمة الطويلة لجائزة البوكر العربية عام 2014م. له مجموعتان قصصيتان هما: «حكايات مصرية جدًّا»، و«دويتو».", CategoryId = 1, ImageUrl = "/images/products/9789777955621.webp", Author = "هشام الخشن", PublishDate = new DateTime(2026, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789777955621" },
            new { Id = 80, Name = "كيف تعود الى وطن لم تغادره", Price = 400m, Stock = 10, Description = "هذا كتاب جديد لإبراهيم عبد المجيد يضم مجموعة من المقالات والدراسات الهامة التي نُشرت في صحف شهيرة بين عامي 2025-2024م. تدور حول قضايا الإنسان في العالم، والأوضاع الإنسانية في تجلياتها السياسية والاجتماعية والثقافية، وقضايا فلسفية عابرة للزمن. وكالعادة ضم إليها مراجعات لكتب هامَّة لعدد من أهم الكُتَّاب والأدباء والمفكرين من كل الأعمار. هكذا ستجد نفسك أثناء القراءة مستمتعًا برحلة فكرية وإنسانية دافقة بالمحبة، ستأخذك إلى فضاء من الجمال والأمل.\nإبراهيم عبد المجيد، كاتب وروائي مصري، له أكثر من 25 رواية، منها: ثلاثية الإسكندرية، و\"في كل أسبوع يوم جمعة\"، و\"أداجيو\"، و\"بيت الياسمين\"، و\"البلدة الأخرى\"، عرف بعضها الطريق إلى السينما والتلفزيون. له خمس مجموعات قصصية، وأكثر من خمسة عشر كتابًا بين الدراسات والمقالات والترجمة. تُرجمت بعض أعماله إلى الإنجليزية والفرنسية وغيرهما، وحاز أرقى الجوائز مثل: جائزة الشيخ زايد بالإمارات، وجائزة كتارا بقطر، وجائزة النيل بمصر.", CategoryId = 8, ImageUrl = "/images/products/9789777955638.webp", Author = "إبراهيم عبد المجيد", PublishDate = new DateTime(2026, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789777955638" },
            new { Id = 81, Name = "الرحم الاصطناعي", Price = 350m, Stock = 10, Description = "تزايد الاهتمام الإعلامي والعلمي بالرحم الاصطناعي في السنوات القليلة الماضية على مستوى العالم، ولا سيما مع التقدم السريع الذي تحرزه البحوث، التي تجرى في كثير من الدول، مــن الصين واليابان شرقا، إلى أوروبا وأمريكا الشمالية غرباء لاستكشاف و اختبار إمكانية حدوث حمل كامل خارج الجسد؛ أي خارج الرحم الطبيعي. وعلى الرغم من أن بحوث الرحم الاصطناعي لا تزال في مرحلة باكرة إلى حد ما، وتُجرى على الحيوانات؛ ومقيدة بقواعد أخلاقيات العلم والبحوث المتفق عليها؛ فإن التقدم المتسارع المذهل، الذي يتحقق في تلك البحوث، التي تتضافر فيها حقول معرفية وبحثية عدة خاصة الذكاء الاصطناعي والتقنية، أطلق العنان لخيال البشر للتفكير في لحظة سيتمكن فيها الإنسان من التحكم بعملية الحمل؛ لتتحقق كاملة خارج جسم الإنسان؛ وتبشر بمرحلة للتكاثر ما بعد البشري، خاصة أن تلك البحوث تستفيد من التقدم المتسارع في تقنية المعلومات، والذكاء الاصطناعي وتطبيقاته، والتطور المذهل في تصنيع الروبوتات، والتقنية المتناهية الصغر (النانو تكنولوجي)، والاندماج المتزايد بين علم الأحياء\n(البيولوجي) وعلم الحاسوب. وتكفي إطلالة سريعة على التقارير الصحفية في وسائل الإعلام بشتى اللغات؛ للوقوف على الآفاق التي وصل إليها خيال البشر؛ ومقارنتها بالحالة الفعلية الراهنة للبحوث في مجال الرحم الاصطناعي؛ إذ تنقل تقارير منشورة تقديرات للعلماء، تشير إلى أن إمكانية تطوير رحم اصطناعي، خلال الفترة المقبلة، تسهم في إنقاذ الأطفال الخدج، المولودين قبل إتمام 37 أسبوعًا في رحم الأم وهذا هو السبب الرئيسي للوفاة بين حديثي الولادة في العالم ؛ وهذا التطور المحتمل يثير - برغم محدوديته مقارنة بما يذهب إليه الخيال - تساؤلات أخلاقية بشأن مستقبل ولادة الأطفال .\nجمال سند السويدي\nمفكر وكاتب وخبير استراتيجي إماراتي، شغل منصب مدير عام مركز الإمارات للدراسات والبحوث الاستراتيجية منذ عام 1994 حتى عام 2020. ويشغل حالياً منصب نائب رئيس مجلس أمناء مركز الإمارات للدراسات والبحوث الاستراتيجية.\nشارك في عدد من المجالس الاستشارية والعلمية والتنفيذية المرموقة بصفة عضو أو رئيس، وحصل على العديد من الجوائز المحلية والدولية. تقديراً لإسهاماته وجهوده العلمية، منها جائزة الشيخ زايد للكتاب» في 1 مايو 2016، وجائزة نجيب محفوظ للآداب في 8 إبريل 2016، ولقب سفير السلام من اتحاد السلام العالمي في 21 مارس 2017 تقديراً لجهوده الكبيرة والمتواصلة في العمل على نشر ثقافة التسامح والوسطية.\nألف أكثر من 35 كتاباً من مختلف الأدبيات السياسية والاجتماعية أحدثها كتاب «الهوية الوطنية في دولة الإمارات العربية المتحدة.. بين خصوصية الثوابت والقيم وعالمية المعايير، وكتاب صاحب السمو الشيخ محمد بن زايد آل نهيان.... إضاءات في مسيرة رجل الإنسانية». وأعد وحزر عدداً آخر من الكتب القيمة، أبرزها كتاب حرب اليمن .1994.. الأسباب والنتائج، وكتاب إيران والخليج.. البحث عن الاستقرار» وكتاب أمن الخليج في القرن الحادي والعشرين».", CategoryId = 8, ImageUrl = "/images/products/9789948726050.webp", Author = "جمال سند السويدي", PublishDate = new DateTime(2026, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789948726050" },
            new { Id = 82, Name = "مخبرون ومخبرون", Price = 225m, Stock = 10, Description = "في هذه المغامرة التاريخية يفضُّ المؤلف ملفات مختومة، ويفتح سجلات مُغلقة، ويغزو مناطق محرَّمة، رافضًا كلَّ القيود التي تفرضها كلمات مثل: «ممنوع»، «سري»، و«محظور».\nيصطحب مؤلف الكتاب أدواته التاريخية للتنقيب في ملفات رجال الأمن السياسي السِّري في مصر خلال النصف الأول من القرن العشرين، راصدًا حكايات مُخبرين سريين عُتاة، استثنائيين، غاية في الذكاء والدهاء، كاشفًا عن صراعهم في لعبة الدفاع عن السلطة، ومآلات هذا الصراع. إنها سيرةٌ داميةٌ شارك فيها قتلةٌ، وأشرارٌ، وأبطالٌ، وخونةٌ، وشهدت تحولات وغرائب وفضائح وجرائم تستحق الحكي. فمن جورج فليبيدس، الشامي المتمصر الذي جمع ثروته من العمل الأمني، إلى مكفرسون، صاحب المزاج المتقلب، ومن إنجرام، الداهية الإنجليزي الرهيب، وصولًا إلى نجيب الهلباوي الخائن الغامض، ومن كيون بويد المُتغَطرِس، إلى سليم زكي المُخيف.\nأنت هنا تقرأ تاريخًا آخرَ سريًّا للسلطة في مصر المحتلة، وتتعرّف على ميراث لا يزال مسكوتًا عنه.\nمصطفى عبيد\nروائي وباحث تاريخي، يعمل بالصحافة، صدر له 25 كتابًا متنوعًا في التاريخ والأدب، وفاز بجوائز عديدة عن كتاباته، كما وصل عددٌ من مؤلفاته إلى قوائم الكتب الأكثر مبيعًا.", CategoryId = 7, ImageUrl = "/images/products/9789777955584.webp", Author = "مصطفي عبيد", PublishDate = new DateTime(2026, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789777955584" },
            new { Id = 83, Name = "الموت الرمادي", Price = 325m, Stock = 10, Description = "«أرجوك! لا تأخذ الأمورَ على محمل شخصي.. ما رأيك لو انتظرتُ معك وأنت تقضي ساعاتك الأخيرة؟ اعتبرها تعبيرًا بسيطًا من ناحيتي بالعِرفان للفترة التي قضيتُها معكَ في عقلك..\nتَمَنَّى جلال لو كان هذا كله مجرد كابوس، لكنه كان مدركًا تمام الإدراك بأن هذه المحادثة – بالرغم من غرابة المكان – كانت حقيقية.. موتُه كان حقيقة لا مفر منها...\nمسألةُ وقت..».\nما بدأ كتحقيق سري بشأن حادثة طيران غامضة يتحول إلى مهمة انتحارية، تكشف عن أسرار لن تغير من نظرتنا إلى التاريخ الإنساني فحسب، بل وتكشف اللثام عن خطر كامن..\nخطر يهدد مصير الجنس البشري بأسره.\nكريم سليمان، مواليد القاهرة 1984، تخرَّج في كلية الصيدلة بجامعة عين شمس، وحصل على ماجيستير إدارة الأعمال بالجامعة الأمريكية بالقاهرة. بدأ مشواره الروائي بقصة قصيرة كانت جزءًا من الحملة الدعائية لـ (Sony Pictures) لفيلمهم (The 5th Wave). نشر العديد من روايات الخيال العلمي باللغة الإنجليزية، أبرزها (The Warrior's Path)، التي وصلت إلى قائمة الأكثر مبيعًا على «أمازون». و(Army of the Cursed) والتي تأهلت إلى نصف نهائي مسابقة SPFBO السنوية، التي تُدار تحت إشراف الكاتب العالمي مارك لورنس.", CategoryId = 1, ImageUrl = "/images/products/9789777955553.webp", Author = "كريم سليمان", PublishDate = new DateTime(2026, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789777955553" },
            new { Id = 84, Name = "نادى الفيديو", Price = 200m, Stock = 10, Description = "نادي الفيديو\nفي التسعينيات، تستيقظ مصر على زلزال، اعتقد البعض أنه اليوم العظيم أو يوم القيامة، لكن \"يوسف\" كان مُهددًا بزلزال آخر، وهو إغلاق مشروع عمره \"جو فيديو فيلم\"، والعمل مع أبيه \"نجيب بشارة\" نقيب الزبالين.\nتابع \"جو\" تطور صناعة الأفلام، من السينما والفيديو إلى الدش والإنترنت، إلى أن وقع تحت يديه \"كليب\" لفساد مسئول كبير، وجاءته الفرصة للانتقام لأبيه، فهل سيستخدم التكنولوجيا لـ \"ينظف\" بها البلد كما فعل أبوه؟\n\"نادي الفيديو\" رواية نوستالجيا عن جيل التسعينيات، جيل آمن بحلمه وبنفسه، رأى تطورات تكنولوجية سريعة، كانت أسرع من طموحاته، لكنه استطاع أن يحقق ما يريد في النهاية.\nريم جميل، صحفية ورئيسة تحرير في التلفزيون المصري. ولدت في القاهرة عام 1987، وتخرجت في كلية إعلام قسم صحافة. \"نادي الفيديو\" هي الرواية الثانية لها، أصدرت روايتها الأولى \"اللبان السحري\" عام 2021. تعيش الكاتبة الآن بين مصر والإمارات العربية المتحدة.", CategoryId = 1, ImageUrl = "/images/products/9789777955560.webp", Author = "ريم جميل", PublishDate = new DateTime(2026, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789777955560" },
            new { Id = 85, Name = "موت مع إيقاف التنفيذ", Price = 190m, Stock = 10, Description = "»أُدرك في لحظة صِدْق أنها الدنيا، تلك الحسناء اللعوب التي تُغريك بكل مفاتنها حتى آخر قطرة من الكأس، فتتمسّك بتأثير خمرها للنهاية، عندما يطفئ النادل الأنوار ويهزّك بقليل من القسوة لتنصرف. عندها فقط تُدرك أن الميعاد فات، ومرَّ الليلُ بلا فائدة». *** في عمله الأدبي الثاني يراوغنا طارق بعشر قصص ممتعة. قصص قصيرة ساحرة نعيش بين سطورها حيوات متنوعة مع شخوص متباينة. أجمل ما يميز القصص هو الجمع بين متعة القص وعمق المعنى. مجموعة قصصية تغازل القلب والعقل معًا. ورغم أن الموت هو عنوان المجموعة، ولكن بنظرة متأملة نجد أن الحديث عن الموت هو في جوهره محاولة لفهم الحياة. الروائي/ عمرو حسين الحاصل على جائزة غسان كنفاني للرواية العربية 2023 ـــــــــــــــــــــــــــــــ\nطارق عز .. روائي وقاص ومترجم مصري، صانع محتوى متخصص في الكتابة والقراءة. يعمل بالطيران المدني، نُشرت له قصص قصيرة في مجموعات قصصية مشتركة، مثل \"اعترافات\"، و\"اليوم الأخير\". حاصل على جائزة أفضل قصة قصيرةiRead لعام 2021، والقائمة القصيرة لنفس الجائزة 2022. وقد صدرت له ترجمة رواية \"ينابيع واكولا \" الحاصلة على جائزة أفضل رواية قصيرة 2013، ونالت روايته الطويلة الأولى «أسفار مريم المحرمة» استحسانًا وإقبالًا جماهيريًّا واسعًا، وتصدرت قوائم الأكثر مبيعًا، وتعتبر «موت مع إيقاف التنفيذ» مجموعته القصصية الأولى.", CategoryId = 1, ImageUrl = "/images/products/9789777954556.webp", Author = "طارق عز", PublishDate = new DateTime(2024, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789777954556" },
            new { Id = 86, Name = "السيمفونية الاخيرة", Price = 275m, Stock = 10, Description = "تدور أحداث الرواية في مرحلةٍ بالغة الأهمية من تاريخ مصر المعاصر، من خلال موظف في إدارة المراسم عمل لسنوات بمعيّة الرئيسين السادات ومبارك ، فاقترب بما يكفي ليصبح شاهدًا على كواليس عصرٍ كامل؛ تكشف الرواية في واقعيةٍ مشوّقة عن مرحلة الانتقال من دهاليز المراسم إلى أروقة السلطة.. حيث تُدار الأمور في صمتٍ مُحكم، وتُحاك المؤامرات بدهاء. هذه الرواية عن إنسان عادي حين تفتك به سلطة المناصب، وتمزّقه التناقضات ويظلله الخوف. وبين قسوةٍ تربّى عليها منذ طفولته، ورقّة الموسيقى التي يُجيد عزفها على آلة الكمان، يحاول أن يجد خلاصه؛ لكن كل نغمةٍ يعزفها تغدو مِرآةً لجراحه ومرثية لأحلامه، وكل لحنٍ يؤلفه يتحوّل إلى قناعٍ يخفي وراءه خوفه العميق. \"السيمفونية الأخيرة \" رحلة تأملية جريئة إلى أعماق النفس البشرية، تضع القارىء منذ المفتتح في التجربة بكل تناقضاتها، ثم تتركه معلقًا بين الحقيقة والخيال في سيمفونية لا تنتهي من كشف الأسرار وتبدل المصائر .\nأشرف العشماوي روائي وقاضٍ مصري، نُشرت له اثنتا عشرة رواية طويلة، وكتابٌ وثائقيٌّ عن الآثار المصرية المُهربة للخارج ومحاولات استعادتها بعنوان \"سرقات مشروعة\"، وثلاث نوفيلات بعنوان \"مواليد حديقة الحيوان\". فاز بعدة جوائز محلية وعربية وعالمية، وتُرجمت أعماله إلى إحدى عشرة لغة أجنبية.", CategoryId = 1, ImageUrl = "/images/products/9789777955546.webp", Author = "اشرف العشماوي", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789777955546" },
            new { Id = 87, Name = "مهما كانت الأعذار", Price = 300m, Stock = 10, Description = "أربع بنات وأربع حكايات، ما بين دانة التي تعيش مع أشباح الماضي.\nولولوة التي تغلق نفسها على سرها، ونجلاء التي تجري وراء وهم الثراء، وصبا التي تعيش داخل سجن سلبيتها.\nنعيش حكايتهن، أوجاعهن، وأفراحهن، فهل تستحق السعادة أن نكسر حاجز خوفنا وسجن أفكارنا لتحلق في سمائها ؟\nآمنة الغنيم حاصلة على شهادة علم الاجتماع والخدمة الاجتماعية من جامعة الكويت عملت باحثة اجتماعية في دار الرعاية الأحداث، ومساعد علمي في جامعة الكويت صدر لها كتاب \"الحرملك\"، وتكتب في العديد من الصحف والمجلات الكويتية.", CategoryId = 1, ImageUrl = "/images/products/9789777955508.webp", Author = "آمنة الغنيم", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789777955508" },
            new { Id = 88, Name = "مريم التجلى الأخير", Price = 235m, Stock = 10, Description = "في حقبة التسعينيات، حيث كانت الصحافة تكاد تكون  السلطة الرابعة، و الصراع فيها كاشف عن تشابك دوائر السياسة والسلطة والنفوذ وحيث خيوط شبكتها تصطاد الجميع، يأتي هذا الصحفي الشاب من عالم الريف والجامعة والبراءة غريبًا في وسط ينشب مخالبه في قلبه وشاهدًا على معارك لا ينتصر فيها إلا الألم، يكتشف الحقيقة عن تجلي العذراء في أحد أحياء القاهرة. تلك  الحقيقة التي كان يتمنى ألا يعرفها أبدًا.\n\"مريم التجلي الأخير\" رواية مثيرة للكاتب الكبير إبراهيم عيسى، تدور بين مكاتب الصحافة الصاخبة ودهاليز السياسة الغامضة، حيث لا مكان يصلح للبراءة ولا مدينة ترحب بالأبرياء، حيث يمتزج الواقع بالزيف، والإيمان بالشك، والحقيقة بالأكاذيب.\nرواية عن زمن كان كل شيء فيه قابلًا للانفجار.\nإبراهيم عيسى صحفي وروائي مصري، مواليد نوفمبر 1965. عمل صحفيًّا بمؤسسة روز اليوسف و في عام 1995 تولى رئاسة تحرير جريدة الدستور قبل مصادرتها عام 1998 ثم أعاد تأسيسها ورئاسة تحريرها عام 2004 وحتى 2010، كما تولى رئاسة تحرير جريدة التحرير في عام2011 ثم أسس ورأس تحرير جريدة المقال في 2015. حصل على جائزة جبران تويني التي يمنحها الاتحاد العالمي للصحف 2008، كما حصل على جائزة الصحافة الحرة من منظمة إنديكس العالمية 2010، وجائزة أحسن صحفي في العالم من نقابة الصحافة البريطانية عام2011. له مؤلفات روائية وسينمائية ودرامية عديدة. كسرت رواياته الحاجز التقليدي للرواية العربية فتعدى حدود الزمان و المكان، وكان من أوائل رواد الواقعية السحرية.", CategoryId = 1, ImageUrl = "/images/products/9789777955386.webp", Author = "إبراهيم عيسى", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789777955386" },
            new { Id = 89, Name = "زهرة النار", Price = 195m, Stock = 10, Description = "\"قال لها: اعذريني. أردت أن أكون صادقًا معك إلى أقصى حد، فالصدق توأم الحب. أمسك بيديها الاثنتين وقال: أحبك يا عالية كما لم أحب في حياتي. اغرورقت عيناها بالدمع، وسألته: ألم تفكر في أن تلك قد تكون مجرد رغبة عابرة؟! إنك ما زلت في سن المراهقة تسيرك غريزتك، وقد تتخيل مشاعر لا وجود لها\".\n***\nآمن خالد وعالية بأن قصة حبهما مختلفة، في بدايتها وأحداثها، فكان يجب عليهما أن يتوقعا نهايتها الاستثنائية.\nبينما تسير الرواية في عالمين متوازيين غير متقاطعين، استطاع الكاتب محمد سلماوي تضفير الأزمنة ببراعة، فكأن القارئ في روايتين لكن الأحداث تتوالى في زمن واحد.\n\"زهرة النار\" تجسيد للصراع متعدد المستويات بين الثورة المتأججة في صدور الشباب، وقيود المجتمع الصارمة التي يفرضها على مَن يريدون الحياة.\nمحمد سلماوي. أحد أهم رموز الحياة الثقافية في مصر والوطن العربي، صدر له أكثر من أربعين كتابًا، ما بين رواية ومسرح وقصة قصيرة وأعمال نقدية. تُرجم العديد من أعماله إلى لغات مختلفة، منها الإنجليزية والفرنسية والهندية وغيرها. أُعيد انتخابه عدة مرات رئيسًا لاتحاد كتاب مصر، وأمينًا عامًا للاتحاد العام للأدباء والكتاب العرب. حصل على جائزة النيل في الآداب، وجائزة الدولة التقديرية، وأوسمة وجوائز دولية منها: فرنسا وإيطاليا وفلسطين.", CategoryId = 1, ImageUrl = "/images/products/9789777955379.webp", Author = "محمد سلماوى", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789777955379" },
            new { Id = 90, Name = "في الأربعين", Price = 385m, Stock = 10, Description = "\"لا أعلم لماذا كنت أتصنع الابتسام.. كنت أخشى مواجهته بدون أن أعرف السبب.. هدوؤه وثباته الانفعالي كانا يُحيراني ويُشعراني بأن هناك شيئًا غامضًا لا أعلمه عنه ولا يريد هو الإفصاح عنه\".\n***\nفي الأربعين، دار الصراع بين المثلث: رحيم، وليلى، وهند.. بين القسوة والحنان؛ القوة والضعف؛ الحب والكراهية؛ الفقد والسعادة. اختلطت النوايا بالخطط المُحكمة، ودارت صراعات التنظيم والسُّلطة التي كانت تبحث عن مبرر لخيانة العهد.\nأحيانًا تأتي الزوابع لتعصف بكياننا، وأحيانًا أخرى تُشرق الشمس لتضيء حياتنا.. ونحن ما بين هذا وذاك، نريد أن نُعيد ما فات. ولكن كيف؟ وقد أدرك القلب أنه لا يمكن العودة إلى الوراء، وأن بعض ما فات من المستحيل إعادته، ومعظم الأخطاء لن تندمل جراحها وإن زال ألمها.\nحنان البهي، كاتبة وإعلامية مصرية. تخرجت في قسم الأدب الإنجليزي بكلية الآداب. إخصائية تطوير الذات، ومدربة تحفيزية لطرق التنفس الصحيحة وإدارة الغضب. قدمت عددًا من البرامج التلفزيونية أشهرها: «فيها حاجة حلوة» و«ست الحسن»؛ وتقدم حاليًّا بودكاست على منصات التواصل الاجتماعي، عنوانه: «من النهارده»، تتحدث فيه عن تطوير الذات والتغلب على التحديات الشخصية. نُشرت مقالاتها في مجلتي «7 أيام» و«نصف الدنيا»، ولها ثلاثة أعمال إبداعية منشورة، هي: «أنا والشغالات»، و«العباية»، و«نص حالة خاصة».", CategoryId = 1, ImageUrl = "/images/products/9789777955300.webp", Author = "حنان البهي", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789777955300" },
            new { Id = 91, Name = "مجانين أم كلثوم", Price = 250m, Stock = 10, Description = "\"مرة ثانية التقينا في مقهى الفيشاوي. شربنا الشاي الخفيف بالنعناع. سمحتُ لنفسي أن أحضن يدها الصغيرة بين يديّ. أغمضتْ عينيها. كان في أصابعها بعض العُقل البارزة وعروق مزرقة.\nقالت بخجل:\nـ \"يدي ليست جميلة\".\nـ \"بالعكس. فيها شيء عنيد وطموح\".\nكانت كذبتي الأولى. كيف يكون في اليد شيء عنيد وطموح؟!\".\n\"مجانين أم كلثوم\" لا توثق فقط سيرة أكبر مطربة عربية، وإنما تقدم رؤيةً سرديةً مبتكرة لأغانيها التي أصبحت جزءًا من الوجدان العربي، وتأريخًا ثقافيًا للقرن العشرين في مصر.\nكما يُحسب للرواية أنها لم تتوقف عند أضلاع الأغنية الثلاثة: الشاعر والملحن والمطربة، وإنما أبرزت الضلع الرابع وهو جمهور الست، أولئك الذين صنعوا أسطورتها. وبفضلهم لا تزال موسيقاها تصدح في البيوت والشوارع والمقاهي من المحيط إلى الخليج.\nوإلى الأبد، سيظل صوتها ونسًا للمحبين والناس الطيبين؛ ينتصرون به على الحروب العبثية وبؤس الأيام.\nشريف صالح، كاتب وصحفي مصري. دكتوراه في النقد الأدبي من أكاديمية الفنون. حصل على عديد من الجوائز، منها: \"ساويرس\" عن مجموعة \"مثلث العشق\"، و\"دبي الثقافية\" عن مجموعة \"بيضة على الشاطئ\"، و\"الشارقة\" للإصدار الأول عن مسرحية \"رقصة الديك\". له نحو عشرين كتابًا، منها: رواية \"حارس الفيسبوك\" و\"ابتسامة بوذا\" و\"نجيب محفوظ وتحولات الحكاية\".", CategoryId = 1, ImageUrl = "/images/products/9789777955270.webp", Author = "شريف صالح", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789777955270" },
            new { Id = 92, Name = "سقوط أوراق التين", Price = 240m, Stock = 10, Description = "هذه رواية الخيال الساخر، أو السخرية الخيالية.. تجذب قارئها إلى عوالم غامضة وغير معتادة، ناسفة الحدود بين الحقيقة والوهم، حول شخصية مثيرة للحيرة والارتباك، تجمع كل شيءٍ ونقيضه، فتسقط بينما تسعى إلى الرُّقي والصعود، فتعيش الواقع خيالًا، وتجلب الخيال ليتجسَّد على أرض الواقع!\nتبدأ القصة بعثور المترجم على مخطوطة نادرة مكتوبة باللغة القبطية، تحكي قصة راهب كان يعيش بين القرنين السادس والسابع الميلاديين، خاض رحلة عجائبية من نوع مصري/قبطي شديد الخصوصية والفرادة، مع بعض همسات وجودية وعبثية، ورغم أن الحماقة ربما تغلب فيها القداسة، فهي قصة تستحق أن تُروى؛ لأن قصص السقوط لا تقل أهمية عن قصص الوصول.\nمينا عادل جيِّد، كاتب وروائي ولد في صعيد مصر. تخرَّج في كلية الآداب قسم الإعلام بجامعة المنيا، ثم حصل على دبلوم الدراسات العليا في التنمية الثقافية بجامعة القاهرة. يعمل منذ سنوات في المجتمع المدني، خاصة تنمية المجتمعات الفقيرة في الصعيد. كتب في عدد من الصحف والمجلات والمواقع المصرية، وعمل مقدمًا ومُعدًّا لبرامج تلفزيونية. حصل على جائزة معرض القاهرة الدولي للكتاب عام 2021 عن كتابه «كنت طفلًا قبطيًّا في المنيا». من أعماله القصصية والروائية: «نواحي البطرخانة»، و«بيت المساكين»، و«جزيرة إلخ إلخ»، و«الأستاذ بشير الكُحلي».", CategoryId = 1, ImageUrl = "/images/products/9789777955188.webp", Author = "مينا عادل جيد", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789777955188" },
            new { Id = 93, Name = "رايت ما لا يجوز لك", Price = 220m, Stock = 10, Description = "\"سأقول لك شيئًا لا أعرف هل سيروق لك أم سيقلقك. يمكننا أن نجعلك تستمع لأدقّ أسرار الحياة السابقة وكلِّ ما مرّ حتّى يومنا هذا، لكن متى رغبت في مغادرتنا، فسنعملُ على محو كلّ المعلومات والأسرار التي عرفتها، وإلا...لن تتحمّل التنكيل الذي سيحيق بك\".\n***\nهناك على الناحية الأخرى من جسر الحياة، تقف الأبديَّةُ لتحرس سكونَ الأموات، من الآن لن يصبح العدم مخيفًا ومقبضًا.. هناك لا يلتقي الإنسان بناصره وغريمه فحسب، بل يلتقي أيضًا بنفسه، حيث ساحة \"البوح\" التي يتخفف فيها \"الضمير\" الإنساني مما يثقل روحه، لا أحد هناك يلوم الآخر على ما فعله في الحياة السابقة، فالأرواح تأتي نقيّة... في نهاية هذه الرواية \"ستشعر بعد خروجك أنّك غفوت قليلًا في مكان ما\"!\nطارق الطيب من مواليد القاهرة 1959. انتقل إلى فيينا عام 1984. له 20 كتابًا مترجمًا. حصل على وسام الجمهورية النمساوية في 2008، عُين سفيرًا ثقافيًا للنمسا في العام نفسه. صدر له مؤخرًا (ما يسبق الواو) و(لهو الإله الصغير).\nسنةالنشر :- 2025", CategoryId = 1, ImageUrl = "/images/products/9789777955218.webp", Author = "طارق الطيب", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789777955218" },
            new { Id = 94, Name = "ذبابة زرقاء", Price = 275m, Stock = 10, Description = "فجأة تتحول مدينة دهب الوادعة إلى مدينة يسكن الخوف ربوعها، بعد انتشار شائعات عن وجود قاتل يستهدف النساء، وسرعان ما يكتسب اللقب المخيف \"سفاح دهب\"!\nتبدأ القصة ببلاغ من ندى حول اختفاء صديقتها الأمريكية، وتحاول التعاون مع المقدم عاصم متجاوزة ذكرى علاقة شائكة ومؤرقة للطرفين.. وفي إطار من التشويق والإثارة تتصاعد الأحداث مع اكتشاف اختفاءات سابقة لم ينتبه إليها أحد.. ترتعد فرائص الجميع ويتساءلون مَن ستكون الضحية التالية؟ أم تنقلب الأدوار فيلاحق المجرم رموز العدالة؟\nنهى داود، كاتبة مصرية ولدت في إنجلترا عام 1975، تخرجت في قسم الاتصالات بكلية الهندسة جامعة القاهرة. وبعد أن عملت بمجال تخصصها لسنوات غمرها تيار الشغف، لتعكف على كتابة أولى رواياتها البوليسية بعد أن حصلت على دبلومة الكتابة الإبداعية من جامعة ويزليان الأمريكية، ثم تخصصت في أدب الجريمة. صدر لها 9 روايات منها: \"جريمة السيدة هـ\"، و\"رضا\"، و\"جريمة العقار 47\"، و\"جثتان والثالثة عند قدمي\"، و\"دماء على السجادة الحمراء\".", CategoryId = 1, ImageUrl = "/images/products/9789777955119.webp", Author = "نهى داود", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789777955119" },
            new { Id = 95, Name = "قضية السنوات السبع", Price = 200m, Stock = 10, Description = "ود نوح لو يخبركم عن شهر عسله القصير في بالي، وعن انهيار العالم بسبب حساء الوطواط، وعن حياته مع دليلة في شقتهما الجديدة، وعن رحلة بحث قطز وآسيا عن اسم مناسب لمولودهما المنتظر، ولكن شاءت الظروف أن يضطر إلى وضع هذه الحكايات اللطيفة جانبًا، وأن يركز على تفاصيل حكاية واحدة: حكاية الرأس المقطوع الذي يتدحرج أمامه الآن.\nأي ضابط عادي كان سيقف عاجزًا أمام ملابسات هذه الواقعة الدموية، ولكن نوح الألفي - الذي تعرض لحادث جعله يبصر غوامض لا يراها غيره - وزميله قطز المحمدي، ليسا ضابطين عاديين. معهما تستمر قضايا سلسلة «تحقيقات نوح الألفي» في جزئها السادس.", CategoryId = 3, ImageUrl = "/images/products/9786338594008.webp", Author = "ميرنا المهدي", PublishDate = new DateTime(2026, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338594008", Pages = 352, Size = "12.9×19.8" },
            new { Id = 96, Name = "قضية ست الحسن: تحقيقات نوح الألفي ج1", Price = 170m, Stock = 10, Description = "تُذبح طالبة بطريقة بشعة، وتُترك في سيارتها بميدان التحرير. صحفي شهير يتحول إلى رماد، والعجيب أن النيران لم تمس شيئًا آخر في شقته، ورسالة من مجهول مكتوبة على الحائط وراءه: «الله أكبر». زوجة منتج شهير تُلقى من شرفتها ليلة رأس السنة. وأخيرًا، تسمُّم 15 من أطفال الشوارع في ظروف غامضة.\nضابط عادي كان سيقف عاجزًا أمام ملابسات هذه القضايا، لكن نوح الألفي - الذي تعرَّض لحادث جعله يبصر غوامض لا يراها غيره - وزميله قطز، ليسا ضابطين عاديين. معهما نبدأ الكتاب الأول من سلسلة «تحقيقات نوح الألفي».", CategoryId = 3, ImageUrl = "/images/products/9789776743861.webp", Author = "ميرنا المهدي", PublishDate = new DateTime(2022, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789776743861", Pages = 304, Size = "12.9×19.8" },
            new { Id = 97, Name = "قضية لوز مر: تحقيقات نوح الألفي ج2", Price = 170m, Stock = 10, Description = "لم يُرد الضابط نوح الألفي شيئًا سوى أن يقضي ليلة رومانسية مع دليلة الجارحي في واحد من أفخم فنادق القاهرة، إلا إنه يتعثر في جثة تبدأ معها سلسلة حوادث قتل غامضة سببها نبوءة عجيبة يعجز المنطق عن تصديقها وتفسيرها.\nيحاول نوح الألفي وصديقه الوحيد قطز المحمدي فك طلاسم هذه الجرائم الغريبة، لكن ما لم يكن في حسبانهما هو ظهور شبح يحمل سرًّا قديمًا قد ينهي حياتهما المهنية، شبح قاتلة متسلسلة يطارد نوح ويرهب من حوله، وكأنه أقسم على ألا يتركه إلا جثة هامدة.\nمغامرة جديدة شيقة مليئة بالمفاجآت غير المتوقعة في سلسلة «تحقيقات نوح الألفي».", CategoryId = 3, ImageUrl = "/images/products/9789776743878.webp", Author = "ميرنا المهدي", PublishDate = new DateTime(2022, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789776743878", Pages = 312, Size = "12.9×19.8" },
            new { Id = 98, Name = "قضية عنب الثعلب: تحقيقات نوح الألفي ج3", Price = 170m, Stock = 10, Description = "ما الخيط الذي يربط بين اختفاء رضيع، وجريمة انتحار فظيعة، ولوحة إيفان الرهيب، وروح عالقة تبحث عن النيكوتين؟\nكان الضابط نوح الألفي منشغلًا باستعدادات زواجه من دليلة، ولكن رغبة زميله قطز في تناول الكباب عند كبابجي شهير قادتهما إلى التورط في قضية فتحت عليهما أبواب أسئلة لا تنتهي...\nضابطان عاديان كانا سيقفان عاجزَين أمام ملابسات هذه القضية، ولكن نوح الألفي الذي تعرَّض لحادث جعله يُبصر غوامض لا يراها غيره، وزميله قطز المحمدي، ليسا ضابطين عاديين.\nثم ما عنب الثعلب أصلًا؟\nقضية جديدة مثيرة في سلسلة «تحقيقات نوح الألفي».", CategoryId = 3, ImageUrl = "/images/products/9789778727326.webp", Author = "ميرنا المهدي", PublishDate = new DateTime(2024, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778727326", Pages = 264, Size = "12.9×19.8" },
            new { Id = 99, Name = "قضية ذيل القط: تحقيقات نوح الألفي ج4", Price = 170m, Stock = 10, Description = "هكذا اكتملت لدى نوح الألفي مواصفات قاتل موظفي وردية المساء في الكول سنتر:\nقاتل مأجور نفَّذ عمليته بحِرفية لم يشهد لها مثيلًا منذ عمل بالمباحث الجنائية.\nقاتل لديه من الدقة ما يسمح له باقتناص أرواح ضحاياه برصاصة واحدة تصيب هدفها.\nقاتل سريع إلى درجة أن ضحاياه لم تُتح لهم فرصة للنهوض عن مقاعدهم ومقاومته أو حتى الهرب.\nقاتل مخضرم إلى درجة أنه أصاب ضحية من وراء باب، ونرجسي إلى درجة أنه لم يفتح الباب ليتأكد من إصابة الهدف.\nقاتل طويل، رياضي، بشرته سمراء سمارًا صناعيًّا، شعره كستنائي كثيف، أنفه مميز.\nقاتل يشبه زميل نوح الذي لا يوجد دليل ضده سوى ذيل القط!\nأي ضابط آخر كان سيقف عاجزًا أمام تعقيدات هذه القضية، لكن نوح الألفي - الذي منحه حادث غامض قدرة على رؤية ما لا يراه غيره - وزميله قطز المحمدي، ليسا مجرد ضابطين عاديين.\nمعهما تستمر سلسلة «تحقيقات نوح الألفي» في جزئها الرابع، حيث الحقيقة ليست كما تبدو، والخطر يختبئ خلف التفاصيل.", CategoryId = 3, ImageUrl = "/images/products/9789779603452.webp", Author = "ميرنا المهدي", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789779603452", Pages = 304, Size = "12.9×19.8" },
            new { Id = 100, Name = "قضية مخالب القط: تحقيقات نوح الألفي ج5", Price = 200m, Stock = 10, Description = "لطالما أخبركم نوح بثلاث حقائق عن نفسه: الأولى أنه يُدعى نوح الألفي، والثانية أنه ضابط في المباحث الجنائية في منطقة قصر النيل، والثالثة أنه يرى أرواح الموتى.\nفي هذه القضية يكتشف معكم حقيقة جديدة عن نفسه، فقد انجذب إلى رائحة قوية أجبرته على الاستيقاظ من سباته العميق ليتتبعها، حتى أدرك أن مصدرها نصف ليمونة يعصره ضيف غير متوقع.\nبينما يحاول نوح فك لغز انجذابه إلى رائحة الليمون، يواجه قطز المحمدي أصعب قضية في حياته - وسيضطر إلى حلها وحده - لأن صديق عمره وزميله نوح الألفي هو الضحية هذه المرَّة.", CategoryId = 3, ImageUrl = "/images/products/9789779603599.webp", Author = "ميرنا المهدي", PublishDate = new DateTime(2026, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789779603599", Pages = 352, Size = "12.9×19.8" },
            new { Id = 101, Name = "دليل جدتي لقتل الأوغاد", Price = 150m, Stock = 10, Description = "اكتشفتُ الليلة أن كل فرد من عائلتي قد قَتل مرَّة على الأقل!\nوقفت خلف جدتي وهي تفتح باب الغرفة لأجد جثة هذا الوغد عارية.\nبالطبع لم أشك في قاتل غير جدتي! ليس لأنها الوحيدة في بيتنا التي تملك سلاحًا احترفت استعماله منذ أيام شبابها، وليس لأننا نعلم أنها قتلت زوجها السابق، بل لأنها فور أن رأت الجثة، ربتت على ظهري وقابلت نظراتي المرتاعة بابتسامة حنون وكأنها تقول لي: «جثة هذا الوغد هي هدية تفوقك في الثانوية العامة. اسعَد يا عيسى!».\nلم أسعد، فقد أوصيتهم ألا يقتلوه بدوني، فلا يجوز أن يُطلق غيري الرصاص عليه، لكن يبدو أنهم استغلوا غيابي في قسم قصر النيل ليمارسوا العادة الأقرب إلى قلوبهم؛ تجاهل رغباتي.\nوددتُ أن أعاتب جدتي لأنها خرقت قواعدها لقتل الأوغاد، لكن نظرات هذا الضابط الذي يقف خلفنا وفي يده ليمونة منعتني من الكلام...", CategoryId = 3, ImageUrl = "/images/products/9789778648065.webp", Author = "ميرنا المهدي", PublishDate = new DateTime(2023, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778648065", Pages = 248, Size = "12.9×19.8" },
            new { Id = 102, Name = "صديقي السيكوباتي", Price = 200m, Stock = 10, Description = "«اندفعت الطلقة من فوهة مسدس سالم وقد أخرس دويها كاتم صوت السلاح الذي كان يخبئه بجرابه في سرواله من الخلف - كالعادة - لتستقر الرصاصة بمنتصف جبين الطبيبة التي ظنت نفسها فطِنة حين تركتهما يقصان عليها تفاصيل كل ما عاشاه من مآسٍ، وتظاهرت بالاستيعاب والحكمة والتعاطف والتفاهم، وطلبت منهما صورًا من البطاقة لتسليمهما إلى السلطات.\nانفرجت ملامح هادي حين رأى خط الدماء الرفيع ينزل من جبين وجهها المحقون بالبوتوكس، ثم همس إلى سالم بحماس منقطع النظير:\n- أنا اللي هقتل الممرضة.\nهز سالم رأسه بلامبالاة، ثم أخذ المِرمدة التي دفن بها سجائره طيلة الجلسة، ووضعها في كيس بلاستيكي أخرجه من جيبه، ثم همَّ أن ينهض ليأخذ دفتر الملاحظات الراقد بين يدَي الطبيبة القتيلة ويمزق كل الأوراق التي كتبت فيها سلوان عنهما حتى لا يترك أي دليل ضدهما.\nانتبه هادي لحالة صديقه، فاستوقفه قائلًا:\n- ما تصدقهاش يا سالم. إحنا مش سيكوباتيين، المجتمع هو اللي عايش دور الضحية.»", CategoryId = 3, ImageUrl = "/images/products/9789779603292.webp", Author = "ميرنا المهدي", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789779603292", Pages = 336, Size = "12.9×19.8" },
            new { Id = 103, Name = "قنبلة للاستخدام الشخصي", Price = 200m, Stock = 10, Description = "من أكثر المؤلفين مبيعًا\n«ما يغضب إلياس المقدسي في أثناء جلوسه في المطعم الآن، أن سارقه الجديد لم يكتفِ بوضع يده عليه كما فعل الجنرال الإنجليزي من قبله، بل شوَّه هويته تمامًا. غيَّر تصميم خداديات المقاعد التي كانت يومًا مزينة بتطريزة الجليل الفلاحي المبهجة، واستبدل خشبًا قاتمًا لا روح فيه بالأرائك التي كانت مُطعمة بالصدف العكاوي.\nلم يتوقف التشويه عند الديكور، فقد استبدل أيضًا فرقة جاز عبرية بالتخت الشرقي الذي كان يطرب القلوب ويعطي مساحة للمستمع، ليدندن بالعلياي والأوف والعتابا والميجانا وهو يؤرجل.\nعلى الرغم من نفور إلياس من تغييرات شوَّهت ذكريات عائلته، التي كانت تتغدى كل أحد في هذا المطعم العريق، فإن تدني ذوق المستوطن خدم خطته بمثالية. فلولا أن الأرائك مستطيلة من خشب داكن معتم كالتابوت، لما استطاع أن يزرع فيها قنبلته، ولولا أن الفرقة العبرية تعزف ضوضاء عالية، لما كان نشازها تغطية ممتازة لصوت تكتكة مؤقت القنبلة التي يحيط بها ما لا يقل عن أربعين عضوًا من عصابتَي الإرجون وشتيرن، محتفلين بنجاح مذبحة ارتكبوها في قرية صغيرة منذ بضعة أيام.»", CategoryId = 3, ImageUrl = "/images/products/9789779603339.webp", Author = "ميرنا المهدي", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789779603339", Pages = 432, Size = "12.9×19.8" },
            new { Id = 104, Name = "جاز وروك: سلسلة قائمة أغاني السفاح المثالي", Price = 200m, Stock = 10, Description = "دندنت أغنية إلفيس بريسلي ونزلت إلى المطبخ. تأملت ترتيبه وهي تضع يديها على خصرها بفخر. لا أطباق متسخة في الحوض، والأرض تبرق من فرط النظافة، والحوائط صارت تلمع، ورأس زوجها مدفون في حوض الزرع. أليس هذا حلم كل زوجة عاقلة؟!\nأما هو فوضع سماعتَي الووكمان على أذنيه وقرع الدرامز على إيقاع أغنية فرقة ذا رولينج ستونز، وهو يراقب صديقته تخفي دليل إدانته.\nما الرابط بين زوجة تحب الجاز في الستينيات، ومراهق يعشق الروك في الثمانينيات؟ وهل هناك أغانٍ مشتركة في قائمتيهما الموسيقية؟\nهذا ما ستكتشفه في الجزء الأول من سلسلة قائمة أغاني السفاح المثالي.", CategoryId = 3, ImageUrl = "/images/products/9789779603261.webp", Author = "ميرنا المهدي", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789779603261", Pages = 360, Size = "12.9×19.8" },
            new { Id = 105, Name = "مولانا", Price = 300m, Stock = 10, Description = "رواية جريئة توضح كيف يساء استخدام الدين\nمن أكثر الكتب مبيعًا\nالقائمة القصيرة للجائزة العالمية للرواية العربية 2013\nتحولت إلى فيلم سينمائي ناجح\nمديح\n«من الوجهة الفنية والفكرية، رواية الموسم الإبداعي... شهادة دامغة على العصر» المصري اليوم\n«عمل ملحمي، في مصاف «قصة مدينتين» للإنجليزي «تشارلز ديكنز»، أو «الحرب والسلام» للروسي «تولستوي»، أو رائعة «باسترناك»، «دكتور زيفاجو»... كما أنها استمرار موفق لمدرسة الروائي العظيم، وأمير الرواية العربية، نجيب محفوظ... إنها تحكي تراجيديا مصر المُباركية بتكثيف مُنقطع النظير فى دقته الاجتماعية وتشويقه الروائي. لذلك تستحق جائزة الدولة فى الأدب... فهل هناك من يسمعون أو من يقرأون!؟» الوطن\n«كتاب يأخذك إلى عالم سفلي ترى منه الدنيا على شاشة التلفزيون وما وراءها من أسرار... سخرية حادة على طول. لا ترحم أحدًا» الجمهورية أونلاين\n«تنقل القارئ إلى تفاصيل وعلاقات مثيرة ومدهشة وتنكشف في النهاية عن مفاجآت ووقائع تدخل في دائرة المسكوت عنه وتقتحم الخطوط الحمراء في دهاليز الفساد السياسي والسلطة المستبدة» عُمان\n«يشرِّح إبراهيم عيسى بجرأة شديدة ظواهر بالجملة في المجتمع، يدخل إلى حقول ألغام، و«أعشاش دبابير» قد لا يرضى عنها البعض، وينتقد بواقعية مفرطة ما حدث، وما زال يحدث... يعمد إلى سهام السخرية وخفة الدم، حتى في أحلك اللحظات، وأشدها عتمة» الإمارات اليوم\n««مولانا» التلفزيوني بطل زماننا» الحياة", CategoryId = 1, ImageUrl = "/images/products/9789778507805.webp", Author = "إبراهيم عيسى", PublishDate = new DateTime(2014, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778507805", Pages = 584, Size = "12.9×19.8" },
            new { Id = 106, Name = "رحلة الدم: ثلاثية القتلة الأوائل ج1", Price = 375m, Stock = 10, Description = "يعود إبراهيم عيسى بعد أربع سنوات من صدور «مولانا» (القائمة القصيرة للجائزة العالمية للرواية العربية – البوكر 2013) ليتناول المسكوت عنه في تاريخنا الإسلامي. ففي سرد مبهر وأحداث مشوقة إلى أقصى درجة يربط ببراعة بين صراعات المسلمين الأوائل بعد وفاة الرسول وفتح مصر واغتيال عثمان بن عفان وعلي بن أبي طالب. إن إبراهيم عيسى يخلق لنا – ولأول مرة – صورة أقرب ما تكون للحقيقة عن هذه السنوات المهمة والتي غيرت وجه العالم للأبد.\nسيُذهل القارئ عندما يعرف أن جميع شخصيات هذه الرواية حقيقية، وأن كل أحداثها تستند على وقائع وردت في المراجع التاريخية المعتمدة. وهي الجزء الأول من سلسلة «القتلة الأوائل».", CategoryId = 7, ImageUrl = "/images/products/9789776467569.webp", Author = "إبراهيم عيسى", PublishDate = new DateTime(2016, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789776467569", Pages = 712, Size = "12.9×19.8" },
            new { Id = 107, Name = "حروب الرحماء: ثلاثية القتلة الأوائل ج2", Price = 450m, Stock = 10, Description = "المؤلف من أكثر الكتاب مبيعًا\nالجزء الأول من السلسلة الروائية من أكثر الكتب مبيعًا\nرحلة الدم لم تنتهِ إذن.\nبل إن الدم أكثر وأغزر.\nلم تكن أبدًا فتنة، بل أعمق وأخطر.\nانسَ كل ما كنت تعرفه عن الفتنة الكبرى، فأنت تدنو من الحقيقة الآن في سردٍ أقرب إلى الواقع وأكثر تشويقًا مع هذه الرواية التي يستكمل بها إبراهيم عيسى مسيرة «القتلة الأوائل»، والتي بدأها في «رحلة الدم» (جائزة نجيب محفوظ في الرواية 2018)، ليتناول السنوات اللغز في تاريخنا الإسلامي.\nونؤكد للقارئ مرَّة أخرى أن جميع شخصيات هذه الرواية المبهرة حقيقية، وأن كل أحداثها تستند إلى وقائع وردت في المراجع التاريخية المعتمدة.", CategoryId = 7, ImageUrl = "/images/products/9789776467996.webp", Author = "إبراهيم عيسى", PublishDate = new DateTime(2018, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789776467996", Pages = 688, Size = "12.9×19.8" },
            new { Id = 108, Name = "سيوف الآخرة: ثلاثية القتلة الأوائل ج3", Price = 375m, Stock = 10, Description = "المؤلف من أكثر الكتاب مبيعًا\nالجزءان الأوليان من أكثر الكتب مبيعًا\n«سيوف الآخرة» هي الرواية التي تصل بك إلى المحطة الأخيرة، أو التي تظنها كذلك في «رحلة الدم». يكمل إبراهيم عيسى هنا دائرة «القتلة الأوائل» منذ اللحظة التي قتل فيها عثمان بن عفان حتى مقتل علي بن أبي طالب. العديد من الألغاز التي تكونت وتراكمت في كتب التاريخ تفكها هذه الرواية، تكشفها وتعريها من غموضها ومن كذبها وربما من تلفيقها. والكثير من الثقوب السوداء التي هوت فيها الحقيقة، وردمت فوقها أضاليل الركام تنفضها «سيوف الآخرة»، تنقب عنها وتعثر عليها، حيث تزيح الأوهام والأكاذيب والتخيلات والتوهمات والدعايات من عقل القارئ ليرى مفاجأة وصدمة ودهشة لقائه بالحقيقة كأنه يراها أو يعيشها، أو كأنه عاش أخيرًا كي يراها.\nلعل أهم ما ستضمنه لك قراءة «سيوف الآخرة»، مع التشويق والإثارة وسرعة نبضات القلب وارتفاع طفيف في ضغط الدم، أنك تستحق أن تعرف لماذا تسمع وترى الآن، وبعد مئات السنوات من أحداث «سيوف الآخرة»، دوي الرصاص، وانفجار الدم، وتفجر الكراهية، وبؤس الفتن اليومية، والجميع الذين قلوبهم شتى.\nاقرأها لتكون شاهدًا على الجريمة لو استدعاك المستقبل للإدلاء بشهادتك...\n*\nوصلت رواية «رحلة الدم» (الجزء الأول من ثلاثية القتلة الأوائل) إلى القائمة الطويلة لجائزة الشيخ زايد للكتاب - فرع الآداب عام 2017، ثم فازت بجائزة نجيب محفوظ للرواية عام 2018. ووصلت أيضًا رواية «حروب الرحماء» (الجزء الثاني من الثلاثية) إلى القائمة الطويلة لجائزة الشيخ زايد للكتاب - فرع الآداب عام 2019. وحققتا نجاحًا جماهيريًّا ونقديًّا كبيرًا، وبيعت منهما عشرات الآلاف من النسخ حتى الآن.", CategoryId = 7, ImageUrl = "/images/products/9789779603247.webp", Author = "إبراهيم عيسى", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789779603247", Pages = 640, Size = "12.9×19.8" },
            new { Id = 109, Name = "الباب المفتوح", Price = 180m, Stock = 10, Description = "واحدة من أهم الروايات العربية\nنافدة منذ فترة طويلة ومطلوبة من محبي الأدب\nحوَّلها المخرج هنري بركات إلى فيلم ناجح من بطولة فاتن حمامة وصالح سليم، فاز بجائزتي أفضل فيلم وأفضل ممثلة لفاتن حمامة في مهرجان جاكرتا السينمائي\nليلى فتاة ذكية، ومليئة بالحيوية، تعيش في مجتمع تقليدي لا ينتظر من المرأة إلا الخنوع والطاعة. ولكن ليلى غير مستعدة للتسليم بسهولة، فتناضل من أجل أن تحصل على حريتها كإنسانة، كما تنخرط في الحركة الوطنية من أجل أن تحرر بلادها أيضًا. وبينما تغلي مصر وتثور خلال أربعينيات وخمسينيات القرن العشرين فتواجه العثرات والانتصارات، نعيش مع ليلى آمالها وانهزاماتها وانتصاراتها في حياتها الشخصية في سبيل حب صادق تصبو إليه، فهل ستجد في نفسها القوة لتفتح الباب وتنطلق؟\nرواية رائعة تتحرك ببراعة مذهلة بين الحميمي والعام، بين سيرة الفرد وتاريخ الوطن.\nمديح\n«رواية «الباب المفتوح» علامة فارقة في كتابة المرأة العربية.. لطيفة الزيات كاتبة أصيلة.. لم تصور المسعى إلى الحرية كطريق سهل وواضح، بل جسدته بعثراته وصعوباته ومزالقه، وأيضًا ببهائه وسكينته. كتبت «الباب المفتوح» في كل نصوصها ففتحت الباب لأجيال من الكاتبات ينتسبن إليها ويواصلن الطريق» رضوى عاشور", CategoryId = 1, ImageUrl = "/images/products/9789776467286.webp", Author = "لطيفة الزيات", PublishDate = new DateTime(2015, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789776467286", Pages = 464, Size = "12.9×19.8" },
            new { Id = 110, Name = "الشطار", Price = 250m, Stock = 10, Description = "«لصاحبي تاريخ ذو وجهين، تستطيع أن تختار أيهما لتسبح فيه إلى ما لا نهاية: إن اخترت وجه السوابق وجدت ألف سابقة وسابقة دونتها محاضر البوليس، ووقف بشأنها أمام النيابات والمحاكم، واستأنف فيها واستؤنفت فيه. أما ما لم تدونه المحاضر فحدِّث ولا حرج. وإن اخترت وجه العز وجدت ما لا يصدَّق، فقد جاء حين من الدهر كان صاحبي يمتلك هذا الشارع بأكمله، وهو أهم شارع في المنطقة، إذ تتمركز فيه تجارات لا حصر لها، ويتدفق في هذا الشارع وحده من الأموال ورؤوس الأموال ما يصلح أن يقيم دولة عظيمة، لكن الذين يملكونه أوباش لا يهمهم سوى المكسب فحسب!\n«اللي جه بلاش يروح بلاش»، هكذا يقول المثل الشعبي على لسان صاحبي»\nمديح\n«عندما عرف جيلنا فضل خيري شلبي وضعناه على القمة» - إبراهيم عبد المجيد\n«خيري شلبي أحد الروافد العظيمة في فن الرواية... أسطورة حقيقية» - إبراهيم داود", CategoryId = 1, ImageUrl = "/images/products/9789776743953.webp", Author = "خيري شلبي", PublishDate = new DateTime(2023, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789776743953", Pages = 624, Size = "12.9×19.8" },
            new { Id = 111, Name = "رحلات الطرشجي الحلوجي", Price = 200m, Stock = 10, Description = "رحلات الطرشجي الحلوجي تحتوي على أحداث مدهشة غريبة، وخواطر مسلية وعجيبة، وأخبار مذهلة ووقائع مؤسفة رهيبة، تتحدث عن حياة الأوائل والأواخر، والأماجد والأسافل.\nخطها يراع العبد الفقير إلى ربه تعالى، العالم غير العلَّامة، والحبر غير الفهَّامة، ابن شلبي الحنفي المصري الطرشجي الحلوجي، كفانا الله شر جهله، آمين!\nمديح\n«خيري شلبي أمير الروائيين الصعاليك» - نجيب محفوظ\n«خيري شلبي تجربة إنسانية وإبداعية فريدة» - جابر عصفور", CategoryId = 1, ImageUrl = "/images/products/9789776743946.webp", Author = "خيري شلبي", PublishDate = new DateTime(2023, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789776743946", Pages = 464, Size = "12.9×19.8" },
            new { Id = 112, Name = "نساء الكرنتينا", Price = 300m, Stock = 10, Description = "من أكثر الروايات مبيعًا وترجمت للإنجليزية والفرنسية\n«القصة بدأت منذ وقت طويل، امتدت لأكثر من جيل، وحلَّقت فوق أكثر من مكان، من جنوب مصر إلى شمالها، واحتوت على الكثير من المواعظ والدروس الأخلاقية، والكثير من الفلسفة العميقة بخصوص الإنسان ورغباته وصفاته. القصة هي واحدة من تلك القصص النادرة في تاريخ الإنسانية، التي تربط المتعة بالتشويق بالمعلومة المفيدة والنصائح الغالية...».\nمديح\n«أول ما قرأت «نساء الكرنتينا» جفلت، فما أمامي لم يكن رواية كما أعرف الرواية، ولا أسلوبها كان أسلوب رواية. كان الطوخي يضرب بالأدب عرض الحائط» - عباس بيضون، «السفير»\n«بنفس ملحمي يتهكم من كل شيء، وخفة روح غير عادية، والتعامل بطزاجة مدهشة مع موتيفات قديمة كالعنف أو توالي الأجيال، استطاع نائل أن يبدع عملًا غير مسبوق في تاريخ الرواية العربية، بلغة شديدة الخصوصية ترقص ما بين الفصحى البسيطة والعامية المصرية الأشد سخونة وربما فُحشًا» - محمد عبد النبي\n«عمل مثير وأصيل يمثِّل مساهمة مهمة في الأدب المصري والعربي المعاصر» - «بانيبال»\n«رواية ساخرة بشدة» - «النيويورك تايمز»\n«رواية تشدك» - أنديل، «مدى مصر»\n«نائل الطوخي روائي مخيف... رواية لامعة» - «لو موند»\n«المجرمون هنا أبطال، وأفراد العصابات قديسون» - «شيكاجو تريبيون»", CategoryId = 1, ImageUrl = "/images/products/9789778648034.webp", Author = "نائل الطوخي", PublishDate = new DateTime(2023, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778648034", Pages = 416, Size = "12.9×19.8" },
            new { Id = 113, Name = "في ممر الفئران", Price = 250m, Stock = 10, Description = "كتب د. أحمد خالد توفيق من الأكثر مبيعًا\n\n«دعني أنتحِ بك جانبًا لأخبرك بسر لا يعرفه سوانا. احترس! لا ترفع صوتك.. عندما نحلم، فإن وعينا يسافر لبعد آخر ليمارس حياة أخرى ويلقى أناسًا آخرين، ويعرف وجوهًا أخرى. «فرويد» لم يقل هذا، لكن دعني أخبرك أنها الحقيقة. بل هي الحقيقة الوحيدة...»\n\nوقال الله: «فليكن نور» فكان نور.\n\nكتب د. أحمد خالد توفيق من قبل عن عالم كابوسي، يمتزج فيه معنى الظلام بمعاني الجهل والقهر والتخبط. ولكنه اليوم يقدم لنا رواية ديستوبية مثيرة عن عالم لم يعد النور فيه من حقوق الإنسان الطبي", CategoryId = 9, ImageUrl = "/images/products/9789776467552.webp", Author = "أحمد خالد توفيق", PublishDate = new DateTime(2016, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789776467552", Pages = 384, Size = "12.9×19.8" },
            new { Id = 114, Name = "رفقاء الليل", Price = 150m, Stock = 10, Description = "كتب د. أحمد خالد توفيق من الأكثر مبيعًا\nآخر ما كتب للدكتور أحمد خالد توفيق\n«الآن أنت تعرف القصة يا سامي، وتعرف لماذا اصطحبتك إلى المقبرة ليلًا،\nوتعرف لماذا أنت مقيد ومكمم الفم بجوارها الآن!\nلقد انتهت قصتي، وحان وقت العمل!\nلا تحاول الصراخ، فلن يسمعك أحد!\nسأحاول أن تمر اللحظات القادمة بسرعة!!»\n*&lt;w:t&gt;*&lt;w:t&gt;*\nيحتوي هذا الكتاب 11 قصة مليئة بالتشويق والرعب والإثارة، وهي آخر قصص تركها لنا د. أحمد خالد توفيق.", CategoryId = 9, ImageUrl = "/images/products/karma-1-mw128b58.webp", Author = "أحمد خالد توفيق", PublishDate = new DateTime(2019, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Pages = 320, Size = "12.9×19.8" },
            new { Id = 115, Name = "أفراح المقبرة", Price = 120m, Stock = 10, Description = "كتب د. أحمد خالد توفيق من الأكثر مبيعًا\nآخر كتاب للدكتور أحمد خالد توفيق\n«سأعترف لك بشيء مخيف.. كل ما أقوله هنا سيظل سرًّا.. أليس كذلك؟ في البدء بدأ القط يتوتر ويعوي.. يطلب الزواج.. كانت تحبه لأنه قطها، لكنه أثار أعصابها، وفي يوم خدرته و... واستأصلت رجولته!».\nآخر باقة مُنتقاة من الوحوش، ومصاصي الدماء، والسَّفاحين، وآكلي لحوم البشر، والموتى الأحياء، والكائنات الفضائية، دفع بها د. أحمد خالد توفيق إلى النشر. ندعوك لقراءتها وقضاء ساعات من المتعة الصافية.", CategoryId = 9, ImageUrl = "/images/products/karma-2-mw128bdp.webp", Author = "أحمد خالد توفيق", PublishDate = new DateTime(2018, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Pages = 240, Size = "12.9×19.8" },
            new { Id = 116, Name = "الهول", Price = 130m, Stock = 10, Description = "سوف نفتح هذه المجموعة القصصية ونحن مفعمون بالأسئلة، ونتركها مفعمين بالخوف: ما مهنة ذلك الرجل الغامض في تلك المسابقة التلفزيونية؟ الموقع الغامض الذي يعرض على الناس منظر جثتك الممزقة. شارع المشاط الهادئ المسالم الذي يكتم سكانه سرًّا مرعبًا. العلاج الشنيع الذي يقدمه الطبيب الأرمني والذي يعيد لك الحواس وربما الأطراف المبتورة. «زوزانكا» تحاول معرفة ما يوجد في قبو أسرة زوجها. الكائن القادم من جانب النجوم لينشر الهول في الأرض. إنها رحلة طويلة مرهقة عبر سراديب الرعب وأقبيته، بينما صراخ الموتى يصم أذنيك.", CategoryId = 9, ImageUrl = "/images/products/9789776467064.webp", Author = "أحمد خالد توفيق", PublishDate = new DateTime(2014, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789776467064", Pages = 248, Size = "12.9×19.8" },
            new { Id = 117, Name = "شربة الحاج داود", Price = 100m, Stock = 10, Description = "اشتهرت قديمًا «شَربة الحاج داود اللي بتطرُد الدود» كعلاج سحري يداوي كل شيء تقريبًا، من الديدان حتى الأورام الخبيثة والعقم والصداع.\nهذه النوعية من العلاجات السحرية توجد في كل الحضارات تقريبًا... كما توجد أيضًا مضادات حيوية، وأدوية مناعة، ولقاحات، أفنى عديد من العلماء المحترمين أعمارهم كي يهدوها لنا.\nيأخذنا الدكتور أحمد خالد توفيق في كتابه الجديد في رحلة ممتعة ومثيرة، يتناول فيها العلم وشبه العلم ونصف العلم واللاعلم.\nبعضه انبهار بالعلم، وبعضه دهشة من كراهيتنا له وحساسيتنا المفرطة نحوه، وبعضه محاولة لفضح أساليب النصب في الطب وسواه...\nكتاب يدفعك للتفكير والنظر للدنيا بشكل مختلف.", CategoryId = 8, ImageUrl = "/images/products/9789776467200.webp", Author = "أحمد خالد توفيق", PublishDate = new DateTime(2015, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789776467200", Pages = 240, Size = "12.9×19.8" },
            new { Id = 118, Name = "صمت الحملان", Price = 300m, Stock = 10, Description = "باعت الرواية أكثر من 10 ملايين نسخة\nمن أفضل كتب التشويق والجريمة\nقاتل متسلسل، معروف فقط باسم مستعار غريب (بافالو بيل)، يطارد نساء معينات. لديه هدف، ولكن لا أحد يستطيع فهمه، لأن الجثث تُكتشف في حالات مختلفة. كلاريس متدربة شابة في أكاديمية مكتب التحقيقات الفدرالي، تُفاجأ باستدعاء من مديرها. مهمتها إجراء مقابلة مع الدكتور هانيبال لِكتر، الطبيب النفسي اللامع والقاتل المروع، المحبوس الآن تحت المراقبة الدقيقة في مستشفى للمجرمين المجانين. هل تستطيع خبرة لِكتر مع القتلة أن تساعده في تعقب بافالو بيل والقبض عليه؟\nتضطرب كلاريس عندما تجد نفسها في علاقة غريبة ومكثفة مع لِكتر شديد الملاحظة. أدلته المبهمة - عن بافالو بيل وعنها - تطلق كلاريس في بحث سيجده القارئ مذهلًا ومروعًا ومقنعًا تمامًا.\nتحوَّلت هذه الرواية الأكثر مبيعًا والفائزة بعدة جوائز مهمة إلى فيلم سينمائي شهير فاز بجائزة الأوسكار من بطولة جودي فوستر وأنتوني هوبكنز.\nمديح\n«رواية ممتعة إلى أقصى درجة. حبكة جميلة، مكتوبة ببراعة. روايات الإثارة لا تأتي أفضل من هذا» - كلايف باركر\n«نموذج مثالي لكيفية كتابة رواية تشويق. تحفة فنية من التوتر المطلق الذي ينطلق بسلاسة نحو ذروته... هاريس - بكل بساطة - أفضل روائي تشويق يكتب اليوم» - الواشنطن بوست\n«قصة نفسية مثيرة منسوجة ببراعة» - الأسوشيتد برس\n«رائعة» - النيويورك تايمز\n«ذات وتيرة سريعة... مثيرة للغاية» - شيكاغو تريبيون", CategoryId = 3, ImageUrl = "/images/products/9789779603049.webp", Author = "توماس هاريس", PublishDate = new DateTime(2024, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789779603049", Pages = 440, Size = "14.5×21.5" },
            new { Id = 119, Name = "ريبيكا", Price = 450m, Stock = 10, Description = "باعت أكثر من 3 ملايين نسخة\nأول ترجمة عربية\nفي مونت كارلو، تلتقي بطلتنا الشابة التي تعمل مرافقة لسيدة ثرية بالأرمل المحطم ماكسيم دي وينتر، فيسحرها بشخصيته وثرائه، ويعرض عليها الزواج. ولكن عندما يصلان إلى قصره الريفي المنعزل في بريطانيا، تجد ماكس يتحول إلى رجل مختلف، وتجد شبح ذكرى زوجته المتوفاة ريبيكا يسيطر على كل زاوية وكل غرفة، بل على حياتها بأكملها، وتشعر برعب يجثم عليها رويدًا رويدًا ويهدد زواجهما... فهل ستستسلم؟\nإنها قصة مثيرة عن شابة تدافع عن حبها، وتصارع من أجل العثور على هويتها.\nلا تزال هذه الرواية الشهيرة واحدة من أكثر الكتب مبيعًا، ولا تزال تُطبع باستمرار منذ نشرها عام 1938، وقد فازت بجائزة أنتوني لأفضل رواية في القرن العشرين، وما زالت تُقتبس دوريًّا للتلفزيون والراديو والمسرح والسينما، ومنها فيلم ألفريد هيتشكوك الشهير الذي فاز بجائزة الأوسكار.\nمديح\n«ممتازة» - ستيفن كينج\n«واحدة من أكثر الروايات تأثيرًا في القرن العشرين» - سارة واترز", CategoryId = 3, ImageUrl = "/images/products/9789779603179.webp", Author = "دافني دو مورييه", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789779603179", Pages = 576, Size = "14.5×21.5" },
            new { Id = 120, Name = "نادي القتال", Price = 240m, Stock = 10, Description = "من أكثر الكتب مبيعًا\n\nترجمة رائعة لكاتبنا الكبير د. أحمد خالد توفيق\n\nتحتوي هذه الطبعة على خاتمة جديدة للمؤلف تُنشر لأول مرة باللغة العربية\n\nالقاعدة الأولى لنادي القتال: لا تتكلم عن نادي القتال.\n\nالقاعدة الثانية لنادي القتال: لا تتكلم عن نادي القتال.\n\nالقاعدة الثالثة لنادي القتال: إن صرخ أحدهم أو عجز عن الدفاع عن نفسه، ينتهي القتال.\n\nالقاعدة الرابعة لنادي القتال: رجلان فقط لكل معركة.\n\nالقاعدة الخامسة لنادي القتال: معركة واحدة في كل مرة.\n\nالقاعدة السادسة لنادي القتال: لا قمصان، لا أحذية.\n\nالقاعدة", CategoryId = 1, ImageUrl = "/images/products/9789778648027.webp", Author = "تشاك بولانيك", PublishDate = new DateTime(2023, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778648027", Pages = 272, Size = "12.9×19.8" },
            new { Id = 121, Name = "سدهارتا", Price = 180m, Stock = 10, Description = "ربما تكون رواية هسه الشهيرة والمؤثرة أهم حكاية رمزية أنتجها عصرنا المضطرب، دمج فيها هسه التقاليد الروحية الشرقية والغربية مع التحليل النفسي والفلسفة. هذه الحكاية البسيطة والغريبة، المكتوبة بتعاطف عميق مع الإنسانية، أثرت في حياة الملايين منذ نشرها في عام 1922.\n\n«سدهارتا» هي قصة شاب يبحث عن الحقيقة المطلقة ويقابل بوذا، ويأخذه سعيه من حياة الانحلال إلى الزهد، ومن الشهوة والثروة والشهرة إلى الحكمة والتخلي.\n\nأهم وأجمل رواية لهرمان هسه، الحاصل على جائزة نوبل في الأدب، بترجمة سمير جريس الأمينة والجميلة", CategoryId = 8, ImageUrl = "/images/products/9789778678338.webp", Author = "هرمان هسه", PublishDate = new DateTime(2023, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778678338", Pages = 224, Size = "12.9×19.8" },
            new { Id = 122, Name = "جاتسبي العظيم", Price = 245m, Stock = 10, Description = "تربَّع هذا الكتاب لعدة سنوات على قائمة الكتب الأكثر مبيعًا\n\nأفضل ترجمة لهذه الرواية المهمة\n\nفي قصر فخم في نيويورك، في العشرينيات من القرن الماضي، يعيش المليونير الغامض «جاي جاتسبي» في الترف والرفاهة، ويقيم حفلات أسطورية باذخة يتهافت إليها المدعوون والمتطفلون. ولكن في قلب هذا الصخب، يبقى المضيف وحيدًا، تواقًا إلى حبه الضائع، غير معني إلا بإبهار شخص واحد: «ديزي بوكانان».\n\nرواية اجتماعية مذهلة، تجسد الحلم الأمريكي في «العشرينيات الذهبية»، بلمعانه المفرط وإخفاقه المحتوم، مسلطة الضوء على الصراع بين ا", CategoryId = 1, ImageUrl = "/images/products/9789776467491.webp", Author = "سكوت فيتزجيرالد", PublishDate = new DateTime(2017, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789776467491", Pages = 288, Size = "12.9×19.8" },
            new { Id = 123, Name = "سولاريس", Price = 220m, Stock = 10, Description = "من أهم روايات الخيال العلمي وأكثرها مبيعًا\nهذه الرواية الفلسفية الممتعة، والتي تُعَد من كلاسيكيات أدب الخيال العلمي، تدور حول العالِم «كريس كلفين» الذي يصل إلى محطة فضائية قرب كوكب «سولاريس» لدراسة المحيط الذي يغطي سطحه، فيضطر لمواجهة ذكرى مؤلمة تتجسد في شبيهة لحبيبته التي ماتت منذ زمن طويل. يعاني علماء آخرون في المحطة من العلة نفسها، وتزداد التكهنات بأن محيط «سولاريس» قد يكون عقلًا ضخمًا يخلق ذكريات مجسدة، لكن غرضه من القيام بذلك يظل لغزًا.\nتطرح «سولاريس» سؤالًا شغل الإنسان منذ قرون: هل يمكننا حقًّا فهم الكون من حولنا من دون أن نفهم أولًا ما يكمن في داخلنا؟\nتُرجمت «سولاريس» إلى أكثر من أربعين لغةً، واقتبست مرات عديدة للسينما والراديو والمسرح، ومن أشهرها الفيلم الذي أخرجه «أندريه تاركوفسكي»، وآخر من إخراج «ستيفن سودربرج» وبطولة «جورج كلوني».\nستانيسواف لَمْ (1921-2006) هو مؤلف الخيال العلمي الأكثر شهرة والأكثر ترجمة خارج اللغة الإنجليزية، حيث باعت كتبه أكثر من خمسة وأربعين مليون نسخة، ونال العديد من التكريمات والجوائز. تتميز كتاباته برؤيتها الفلسفية العميقة. ومن أشهر أعماله «سولاريس»، التي نقدِّمها للمرة الأولى - مترجمة من البولندية مباشرة - بترجمة متميزة ودقيقة للأديب والمترجم العراقي هاتف جنابي.\nمديح\n«رواية من الطراز الأول» - جريدة الجارديان\n«رواية تجعلك تعيد التفكير في طبيعة الذكاء نفسه» - الأديبة «آن ماكافري»\n«رواية رائعة» - المخرج «ستيفن سودربرج»", CategoryId = 2, ImageUrl = "/images/products/9789776743540.webp", Author = "ستانيسواف لَمْ", PublishDate = new DateTime(2021, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789776743540", Pages = 280, Size = "14.5×21.5" },
            new { Id = 124, Name = "الأمير الصغير", Price = 120m, Stock = 10, Description = "من أهم الكتب الكلاسيكية العالمية\n\nأكثر الكتب ترجمةً في تاريخ الأدب العالمي\n\nيحتوي على الرسوم الأصلية للمؤلف\n\nترجمة جديدة متميزة\n\nطبعة خاصة تصدر بمناسبة الذكرى الـ75 لوفاة المؤلف\n\nيتعرض طيار لحادث فيسقط مع طائرته في الصحراء، وفي الصباح يستيقظ على طفل جميل يطلب منه: «من فضلك، ارسم لي حَمَلًا!». وبعد هول المفاجأة، يُدرك الطيار أنه عندما يصعب فهم الأحداث فلا خيار يتبقى للمرء سوى الخضوع للحياة وألغازها، فيُخرج من جيبه ورقة وقلمًا... وهكذا تبدأ هذه الحكاية الفاتنة التي تدور حول ما هو مُهم حقًّا في الح", CategoryId = 8, ImageUrl = "/images/products/9789776467811.webp", Author = "أنطوان دو سانت اكزوبيري", PublishDate = new DateTime(2019, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789776467811", Pages = 112, Size = "16×22" },
            new { Id = 125, Name = "حكاية الجارية", Price = 220m, Stock = 10, Description = "رؤية مخيفة للمجتمع وقد تحوّل جذريًّا بسبب ثورة سياسيّة دينيّة متشدّدة. لقد باتت “حكاية الجارية” واحدة من أوسع الروايات قراءة في العالم وأكثرها تعلّقًا بالحاضر وقضاياه المؤثّرة. “أوفرِد” هي جارية في “جمهورية جلعاد”، تخدم في منزل “الرئيس” الغامض وزوجته حادّة الطّباع. تخرج مرة واحدة يوميًّا إلى الأسواق، حيث استُبدلت الصّور بكلّ اللافتات المكتوبة، فالنساء في جلعاد تحرّم عليهن القراءة. يجب عليها أن تصلي من أجل أن يجعلها الرّئيس حاملًا، ففي زمنها انخفضت معدّلات الولادة حتى صار وجود الأطفال في البيوت أ", CategoryId = 2, ImageUrl = "/images/products/9789948352068.webp", Author = "مارغريت آتوود", PublishDate = new DateTime(2020, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789948352068", Pages = 408 },
            new { Id = 126, Name = "سر الأسرار", Price = 490m, Stock = 10, Description = "من أكثر المؤلفين مبيعًا\nمن أكثر الكتب مبيعًا\nيعود كاتب روايات التشويق الأشهر في العالم، دان براون، بروايةٍ جديدة تبهر العقول وتحبس الأنفاس. إنه عمل آسر متّقد الإيقاع، تتشابك فيه الأحداث والأفكار بمهارةٍ لا يجيدها سواه، فيقدم تجربة قراءةٍ تجمع بين المتعة والدهشة والتأمل العميق.\nخلال رحلة برفقة العالِمة المَرموقة كاثرين سولومون- التي دُعيت لإلقاء محاضرة في براغ - يجد روبرت لانغدون نفسه في دوامةٍ تخرج عن السيطرة؛ حين تختفي كاثرين من غرفتهما في الفندق من دون أثر. بعيدًا عن وطنه، وخارج محيطه المُعتاد، يُضطر لانغدون إلى مواجهة قوًى مَجهولة لاستعادة المرأة التي يُحبها.\nلكن براغ مدينة موغلة في القِدَم، تزخر بالأساطير ويكتنفها الغموض. فعلى مدى ألفَي عام، تقاذفتها أمواج التاريخ، فتركت في حجارتها صدى ما مضى من أحداث وتقلبات. ولم يكن لانغدون يُدرك أن طيفًا من ماضي المدينة المُظلم يُراقبه من كثب. غير أنه يجد نفسه مُرغَمًا على الاستعانة بكل ما في جعبته من مَعارف غامِضة لفك رموز ذلك العالم من حوله، قبل أن تبتلعه هو الآخر دوامات الخداع والخيانة التي ابتلعت كاثرين.\nهكذا، يجد لانغدون نفسه في مدينة سرية تختبئ في وضح النهار، مدينةٍ احتفظت بأسرارها قرونًا طويلة، ولن تُفصِح عنها بسهولة.\nإنها ساحة مَعركة لم يشهد لها مثيلًا من قبل، سيتحتم عليه فيها أن يُقاتل؛ ليس من أجل حياته فحسب، بل من أجل مستقبل البشرية نفسها.\nفي رواية «سر الأسرار»، يرجع دان براون إلى عالم الرواية بعد طول غياب، مُعيدًا إلى الواجهة عالِم الرموز في جامعة هارفارد، روبرت لانغدون، في مغامرةٍ جديدة تقوده إلى قلب مُؤامرةٍ ستمتحن عبقريته حتى أقصى حدودها، وتُعرِّض كل ما يعتز به لخطر الضياع.", CategoryId = 3, ImageUrl = "/images/products/9786039233473.webp", Author = "دان براون", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786039233473", Pages = 584, Size = "17×24" },
            new { Id = 127, Name = "بدافع القتل", Price = 390m, Stock = 10, Description = "تنسج هذه الرواية المثيرة لغز جريمة قتل كلاسيكية يليق بأجاثا كريستي بأسلوب عصري مبتكر.\nعندما حصلت المحررة سوزان رايلاند على مخطوطة أحدث روايات مؤلفها آلان كونواي، لم يكن لديها أي سبب للاعتقاد بأنها ستكون مختلفة كثيرًا عن أيٍّ من رواياته السابقة. أثبتت روايات آلان نجاحها الكبير، مما أجبر سوزان على تحمُّل سلوك آلان المزعج إذا أرادت الاحتفاظ بوظيفتها.\nأحدث روايات آلان تدور حول جريمة قتل في قصر بالريف الإنجليزي الهادئ. نعم، هناك جثث ومجموعة مثيرة من المشتبه فيهم، ولكن كلما قرأت سوزان أكثر أيقنت بوجود قصة أخرى مخبأة في صفحات المخطوطة: قصة غيرة مدمرة، وجشع لانهائي، وطموح لا يوقفه شيء، وقتل...\n«بدافع القتل» رواية بارعة وذكية ومشوقة بلا هوادة لأنتوني هورويتز، الكاتب الإنجليزي الذي باعت كتبه أكثر من 21 مليون نسخة حول العالم.\nمديح\n««بدافع القتل»، لغز مزدوج لمحبي الألغاز» - النيويورك تايمز", CategoryId = 3, ImageUrl = "/images/products/9789779603001.webp", Author = "أنتوني هورويتز", PublishDate = new DateTime(2024, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789779603001", Pages = 576, Size = "14.5×21.5" },
            new { Id = 128, Name = "قوة الآن", Price = 280m, Stock = 10, Description = "نحتاج إلى ترك عقلنا التحليلي، وذاته المولدة الزائفة، الأنا، خلفنا، إن نحن أردنا السفر إلى قوة الآن. ننتقل بسرعة، ومنذ الصفحة الأولى لهذا الكتاب الاستثنائي، إلى ارتفاعات أعلى بشكل ملحوظ، نتنفس فيها هواء أقل كثافة. ونتصل بأساس وجودنا الذي لا يوصف، «الحياة الأبدية الواحدة الدائمة الوجود خلف الأشكال المختلفة للحياة الخاضعة للولادة والموت». ورغم صعوبة الرحلة، يستخدم إكهارت تول لغة بسيطة، ونسقا سهلا من سؤال وجواب، لتوجيهنا.\n\n«قوة الآن» من الكتب النادرة التي تتمتع بالقوة لخلق التجربة للقراء، وقد أصبح ع", CategoryId = 6, ImageUrl = "/images/products/9789953978550.webp", Author = "إكهارت تول", PublishDate = new DateTime(2020, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789953978550", Pages = 224, Size = "14.5×21.5" },
            new { Id = 129, Name = "السماح بالرحيل", Price = 200m, Stock = 10, Description = "يشرح كتاب السماح بالرحيل آلية بسيطة وفعالة يمكن من خلالها التخلص من معوقات التنوير، والتحرر من السلبية، حيث كان الهدف الأساسي للمؤلف خلال عدة عقود من الممارسة النفسية السريرية هو إيجاد الوسائل الأكثر فعالية في تخفيف معاناة البشر بجميع أشكالها، وقد وُجدت الآلية الداخلية للتسليم لتكون ذات منفعة عملية عظيمة وقد تم شرحها في هذا الكتاب.\n\nلقد ركزت كتب الدكتور هاوكنز السابقة على حالات الوعي المتقدمة والتنوير، وخلال هذه السنوات، طلب آلاف الطلاب تقنية عملية يمكن من خلالها أن يزيلوا المعوقات الداخلية للسع", CategoryId = 6, ImageUrl = "/images/products/9789953978574.webp", Author = "ديفيد ر. هاوكينز", PublishDate = new DateTime(2020, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789953978574", Pages = 384, Size = "14.5×21.5" },
            new { Id = 130, Name = "جسمك يتذكر كل شيء", Price = 500m, Stock = 10, Description = "من أكثر الكتب مبيعًا في علم النفس\nيُقدِّم بيسيل فان دير كولك، الباحث الرائد وأحد أبرز الخبراء في العالم في مجال الضغط العصبي الناتج عن الصدمة النفسية، نموذجًا جديدًا جسورًا للشفاء من الصدمات.\nالصدمة النفسية حقيقة من حقائق الحياة. أظهرت الدراسات أن واحدًا على الأقل من كل خمسة أشخاص يتعرض للتحرش، وواحدًا من كل أربعة ينشأ مع مدمنين، وزوجًا من كل ثلاثة أزواج يتورط في عنف جسدي. هذه الظروف تترك حتمًا آثارًا في العقول والعواطف، وفي الجسد أيضًا. ومع الأسف، كثيرًا ما يعكس المصابون بالصدمات النفسية ضغطهم العصبي على شركائهم وأطفالهم.\nأمضى د. فان دير كولك أكثر من ثلاثة عقود في العمل مع الناجين من الصدمات، ونجح من خلال هذا الكتاب في تغيير فهمنا للضغط العصبي الناجم عن الصدمة النفسية، وكشف عن كيفية إعادة الضغط العصبي لترتيب أسلاك الدماغ حرفيًّا - تحديدًا المناطق المخصصة للمتعة والتفاعل مع الآخرين والتحكم في النفس والثقة - وأوضح تأثير العلاجات المبتكرة، بما في ذلك الارتجاع العصبي والتأمل والصلاة واللعب واليوجا وغيرها من العلاجات، فضلًا عن تقديمه بدائل مجربة وناجحة للعقاقير والعلاج بالكلام، وطريقة التعافي واستعادة الحياة.\nمديح\n«واضح ورائع ويصعب التوقف عن قراءته، ومليء بدراسات الحالة المهمة... قدَّم هذا الكتاب مجموعة من أهم الإنجازات في مجال الصحة العقلية خلال الأعوام الثلاثين الماضية» - نورمان دويدج، مؤلف كتاب «الدماغ يغير نفسه»", CategoryId = 6, ImageUrl = "/images/products/9789778678321.webp", Author = "بسيل فان دير كولك", PublishDate = new DateTime(2024, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778678321", Pages = 632, Size = "14.5×21.5" },
            new { Id = 131, Name = "أبناء بالغون لوالدين غير ناضجين عاطفيا", Price = 175m, Stock = 10, Description = "من أكثر الكتب مبيعًا في مجال علم النفس\nإذا نشأت مع والد غير ناضج عاطفيًّا أو غير متاح أو أناني، فقد تكون لديك مشاعر دائمة من الغضب أو الوحدة أو الخيانة أو الهجر، قد تتذكر طفولتك على أنها الوقت الذي لم تتم فيه تلبية احتياجاتك العاطفية، أو تم فيه تجاهل مشاعرك، أو توليت فيه مسؤولية أكبر من سنك في محاولة للتعويض عن سلوك والديك. يمكن أن تلتئم هذه الجروح، ويمكنك المُضي قُدمًا في حياتك.\nفي هذا الكتاب الرائع، تكشف عالمة النفس السريري ليندزي س. جيبسون الطبيعة المدمرة للآباء غير الناضجين عاطفيًّا أو الآباء غير المتاحين. سترى كيف يخلق هؤلاء الآباء شعورًا بالإهمال، وتكتشف طرقًا للشفاء من الألم والارتباك اللذين سبَّبتهما طفولتك. من خلال تحرير نفسك من عدم النضج العاطفي لوالديك، يمكنك استعادة طبيعتك الأصلية، والتحكم في طريقة تفاعلك معهما، وتجنب خيبة الأمل. وأخيرًا، ستتعلم كيفية إنشاء علاقات إيجابية وجديدة حتى تتمكن من بناء حياة أفضل.", CategoryId = 6, ImageUrl = "/images/products/9789778721980.webp", Author = "ليندزي س. جيبسون", PublishDate = new DateTime(2024, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778721980", Pages = 272, Size = "14.5×21.5" },
            new { Id = 132, Name = "العلاج بالقراءة", Price = 280m, Stock = 10, Description = "في هذا الدليل الاستثنائي، تُحدثنا المعالِجة النفسية بيجال شاه عن مفهوم «العلاج بالقراءة» أو «الببليوثيرابي»، وكيف يمكن للقراءة أن تكون شكلًا من أشكال العلاج، مقدمةً نصائح عملية مدروسة، وقوائم كتب منتقاة بعناية لكل مزاج وحالة نفسية.\nتأخذنا شاه في رحلة عبر تاريخ هذا الفن العلاجي، مبيِّنة كيف واسى الأدب العظيم أرواحًا أثقلها الفقد والألم والتعقيدات العاطفية. وتشاركنا قصصًا حقيقية لمسترشديها الذين وجدوا في الكتب عزاءً وسط المِحن.\nهذا الكتاب احتفاء كبير بسحر الكتب، وتذكير رقيق بقدرتها الفريدة على مواساتنا وإعادة تشكيل حياتنا. إنه دعوة صادقة إلى إعادة اكتشاف القراءة، ليس كمهرب من الواقع فحسب، بل كأحد أصدق أشكال العناية بالذات.\nمديح\n«كتاب مدهش بكل معنى الكلمة» - بيث كيمبتون، مؤلفة الكتاب الأكثر مبيعًا «وابي سابي: الحكمة اليابانية للعيش المثالي في حياة غير مثالية»\n«من أروع ما قرأت منذ سنوات! مكتوب بأسلوب ساحر زاخر بالرؤى العميقة، يكشف لك عن القوة الشافية للقصص، وكيف يمكن للقراءة أن تغيِّر حياتك» - سايمون ألكسندر أونج، مؤلف الكتاب الأكثر مبيعًا «تنشَّط»", CategoryId = 6, ImageUrl = "/images/products/9789779603605.webp", Author = "بيجال شاه", PublishDate = new DateTime(2026, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789779603605", Pages = 296, Size = "14.5×21.5" },
            new { Id = 133, Name = "كن أروع من أن يتجاهلوك", Price = 200m, Stock = 10, Description = "في هذا الكتاب الرائع يتحدى كال نيوبورت النصيحة الشائعة: «اتبع شغفك». فهو يرى أن هذه المقولة ليست مضللة فحسب - لأن معظم الناس لا يملكون شغفًا واضحًا سابقًا - بل قد تكون ضارة أيضًا، إذ تؤدي إلى القلق والتخبط المهني.\nبدلًا من ذلك، يستعرض نيوبورت كيف يصل الناس فعلًا إلى حب ما يفعلونه. ويكشف من خلال لقاءات مع مزارعين، ومستثمرين، وكُتَّاب سيناريو، ومبرمجين مستقلين، أن الطريق إلى العمل المُرضي يبدأ بإتقان شيء ذي قيمة، فالشغف لا يسبق النجاح، بل يتولد عنه.\nينسف نيوبورت فكرة أن توافُق الوظيفة مع الشغف هو مفتاح السعادة. الأهم هو كيف تؤدي عملك، لا ماهيته. وبأسلوب واضح ومقنع، يقدِّم خريطة طريق عملية لبناء مسيرة مهنية ملهمة.\nسيغيِّر هذا الكتاب نظرتك إلى العمل والسعادة، ويتيح لك صناعة حياة استثنائية.\nمديح\n«يجب على المحترفين الطموحين أن يطوروا ميزة تنافسية من خلال بناء مهارات قيِّمة. هذا الكتاب يقدِّم نصائح تستند إلى البحث والواقع - وليس إلى شعارات جوفاء - حول كيفية الاستثمار في ذاتك لتتميز وسط الزحام. إنه دليل مهم لبدء مسيرة مهنية استثنائية» - ريد هوفمان، المؤسس المشارك ورئيس مجلس إدارة لينكد إن\n«يقدِّم هذا الكتاب نصائح وأمثلة ستدفعك مباشرة نحو بناء المهارات المهمة حقًّا» - دانيال إتش. بينك، المؤلف الأكثر مبيعًا لكتاب «الحافز»\n«هذا الكتاب غيَّر قناعاتي. لقد نقلني من فكرة «ابحث عن شغفك لتكون مفيدًا» إلى «كن مفيدًا لتجد شغفك». إنها نقلة كبيرة، ولكنها أكثر صدقًا، ولهذا السبب أهديت نسخة من هذا الدليل غير التقليدي إلى كلٍّ من أولادي الثلاثة» - كيفن كيلي، كبير المحررين المبتكرين في مجلة «وايرد»\n«أول كتاب أقرأه مرتين منذ سنوات لأتأكد من استيعابه. رؤى مهنية لامعة ومخالفة للتوقعات. أفكار قوية وجديدة غيَّرت بالفعل طريقة تفكيري في مسيرتي المهنية، والنصائح التي أقدِّمها إلى الآخرين» - ديريك سيفرز، مؤسس شركة الموسيقى سي دي بيبي", CategoryId = 5, ImageUrl = "/images/products/9789779603612.webp", Author = "كال نيوبورت", PublishDate = new DateTime(2026, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789779603612", Pages = 248, Size = "14.5×21.5" },
            new { Id = 134, Name = "رجال ريا وسكينة", Price = 600m, Stock = 10, Description = "طبعة جديدة فاخرة لأحد أكثر الكتب التاريخية مبيعًا\nأهم كتاب يتناول هذه العصابة الشهيرة\nالسيرة الوحيدة التي تستند إلى الوثائق والأرشيفات، مسرودة بأسلوب شيق وممتع\nيتضمن الكتاب صور فوتوغرافية كثيرة نادرة للشخصيات والأماكن والوقائع\nتحولت ريا وسكينة منذ القبض عليهما عام 1921 إلى أسطورة في الخيال الشعبي والجمعي للمصريين، وكنموذج مُخيف ومُرعب للشر المجرد. ولم يحاول أي من المؤرخين أو علماء الاجتماع طوال كل هذه الأعوام تقصي حقيقة هذه الجرائم، أو دراسة الدوافع وراء ارتكابها، حتى قدَّم لنا صلاح عيسى هذه السيرة الاجتماعية السياسية غير المسبوقة.\nويستند كاتبنا الكبير إلى الملفات القضائية، والوثائق التاريخية، والأرشيفات الصحفية، وعدد كبير من المراجع المعروفة وغير المعروفة ليرسم لنا - ولأول مرة - صورة حقيقية وحية عن هذه الشخصيات المثيرة وأوضاع مصر السياسية والاجتماعية والاقتصادية في ذلك العصر.\nوبالإضافة لأسلوب صلاح عيسى الشيق والممتع يمتلئ الكتاب أيضًا بعشرات الصور الفوتوغرافية للأشخاص والأماكن والوقائع؛ فيعطي المؤلف التاريخ حقه بإخلاصه للحقائق الموثقة، ويعطي القارئ حقه في الاستمتاع باكتشاف هذا التاريخ، وبمعايشة أجوائه وشخصياته.", CategoryId = 7, ImageUrl = "/images/products/9789776467248.webp", Author = "صلاح عيسى", PublishDate = new DateTime(2018, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789776467248", Pages = 528, Size = "19.5×27.5" },
            new { Id = 135, Name = "حوارات نجيب محفوظ", Price = 300m, Stock = 10, Description = "تجمع هذه الحوارات القصيرة الممتعة خلاصة فكر أديبنا الأكبر نجيب محفوظ وهو في قمة نضجه وحكمته، فنتعرف على آرائه في الثقافة والسياسة والدين، وذكرياته، من خلال اللقاءات الأسبوعية الشهيرة التي كان يجريها معه الكاتب محمد سلماوي لتُنشر كل أسبوع في «الأهرام» لمدة 12 عامًا منذ عام 1994 وحتى وفاته عام 2006.\nويقول الكاتب الكبير محمد سلماوي في مقدمة هذا الكتاب: «في هذه الحوارات تتضح بصيرة نجيب محفوظ وموسوعية معرفته وشمول رؤيته مما يجعلها صالحة لكل العصور، حتى يكاد القارئ يشعر بأنها أجريت اليوم، وأن محفوظ يتحدث فيها عن موضوعات حالية، ويطرح آراء ما أحوجنا إليها فيما نواجهه اليوم من مشاكل... لكنها قبل كل ذلك وبعده، جلسة حميمية تأخذ القارئ إلى مجلس رجل من أعظم وأمتع رجالات مصر في عصرنا الحديث».", CategoryId = 8, ImageUrl = "/images/products/9789779603131.webp", Author = "محمد سلماوي", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789779603131", Pages = 320, Size = "14.5×21.5" },
            new { Id = 136, Name = "الأيام", Price = 105m, Stock = 10, Description = "من أكثر الكتب مبيعًا\n\nطبعة مدققة ومراجعة بدون أخطاء\n\nطبعة جيب أنيقة وجذابة\n\nيقول عميد الأدب العربي في الجزء الأول من سيرته الخلابة والتي تعتبر من أجمل السير الذاتية العربية: «لست أدري لماذا رجعت ذات يوم إلى ذكريات الصبا، أتحدث بها إلى نفسي لأنسى بهذا الحديث أثقال الشباب. ثم لم أكتفِ بالتحدث إلى نفسي فيما بيني وبينها، وإنما تحدثت إليها حديثًا مسموعًا، فأمليت هذا الكلام على صاحبي في رحلة من رحلات الصيف، ثم ألقيته جانبًا ونسيته أو كدت أنساه»\n\nالجزء الأول\n\nالسلسلة: المكتبة التراثية الصغيرة\n\n«المكتبة", CategoryId = 7, ImageUrl = "/images/products/9789779603216.webp", Author = "طه حسين", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789779603216", Pages = 136, Size = "12×17" },
            new { Id = 137, Name = "رجال في الشمس", Price = 70m, Stock = 10, Description = "من أكثر الكتب مبيعًا\n\nمدققة ومراجعة بدون أخطاء\n\nطبعة جيب أنيقة وجذابة\n\n«رجال في الشمس» رواية تزلزل الضمير، وتطرح سؤالًا لا يزال يلاحق كل من عايش النكبة: «لماذا لم يدقوا جدران الخزان؟!».\n\nثلاثة رجال فلسطينيين، من أجيال مختلفة، يسعون لعبور الحدود نحو حلم هش بالكرامة والعمل، لكن الطريق إلى الكويت ليس مجرد رحلة جغرافية، بل اختبار قاسٍ للإنسانية، وتجسيد لمعنى الخذلان، ومؤشر على الصمت الذي يقتل أكثر من الرصاص.\n\nبأسلوبه المكثف والموجع، يكشف غسان كنفاني عن مأساة شعب لم يُهزم بالاحتلال فحسب، بل أيضًا بال", CategoryId = 1, ImageUrl = "/images/products/9789779603735.webp", Author = "غسان كنفاني", PublishDate = new DateTime(2026, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789779603735", Pages = 128, Size = "12×17" },
            new { Id = 138, Name = "عائد إلى حيفا", Price = 60m, Stock = 10, Description = "من أكثر الكتب مبيعًا\n\nمدققة ومراجعة بدون أخطاء\n\nطبعة جيب أنيقة وجذابة\n\n«عائد إلى حيفا» ليست مجرد رواية، بل مواجهة مؤلمة مع سؤال الهوية، والانتماء، والذاكرة التي لا تموت.\n\nفي رحلة العودة إلى المدينة التي سُلبت، يفتح غسان كنفاني جرحًا فلسطينيًّا لم يندمل. زوجان يعودان إلى حيفا بعد عشرين عامًا من النكبة، ليبحثا عن ابنهما الذي تركاه خلفهما في لحظة الهروب، لكن ما ينتظرهما هناك ليس الحقيقة فحسب، بل اختبار قاسٍ لمعنى الوطن، والخسارة، والاختيار.\n\nبأسلوبه الحاد والعاطفي، يكتب كنفاني نصًّا يتجاوز الرواية", CategoryId = 1, ImageUrl = "/images/products/9789779603711.webp", Author = "غسان كنفاني", PublishDate = new DateTime(2026, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789779603711", Pages = 96, Size = "12×17" },
            new { Id = 139, Name = "فن الحرب", Price = 60m, Stock = 10, Description = "أحد أكثر الكتاب مبيعًا في العالم في طبعة مصرية محققة\n\nلقد استطاع \"سون تزو\" أنْ يؤكّد من خلال كتابه: \"فنُّ الحرب\" – وهو الكتاب الذي كان يُعدّ الكتاب المقدّس في الدراسات العسكريَّة - بـأنَّ من الأمور المستحيلة؛ هي التكهّن مُسبقاً بمصير المعركة، وتوقّع ما قد يتخلّلها من أحداث؛ أو ما قد يظهر فيها من مفاجآت؛ وهذا يدعو القائد بالضرورة إلى اعتماد استراتيجيَّات وخطط حربيَّة مرنة. ولذا؛ فقد استطاع \"تزو\" أنْ يقنع جنوده بأنَّ الحرب فكرٌ وفنٌّ؛ وليست قتال ودماء.\n\nكان \"سون تزو\" يؤمن بأنَّ القائد المثالي الذي", CategoryId = 8, ImageUrl = "/images/products/9789779603544.webp", Author = "صون تزو", PublishDate = new DateTime(2020, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789779603544", Pages = 88, Size = "14×21" },
            new { Id = 140, Name = "الأمير", Price = 110m, Stock = 10, Description = "من أكثر الكتب مبيعًا\n\nطبعة جيب أنيقة وجذابة\n\nاتهم الناس ماكيافيلي بأنه سنَّ في كتابه أقسى أساليب الاستغلال وأفظعها، وابتدع أظلم خطة للتحكم في الأعناق. لكن الحقيقة أن ماكيافيلي قضى عمره في خدمة أهل وطنه، والسعي في تأسيس بناء العدل ليعيشوا في ظله، وقد جلب عليه تطرفه للعدل والحق فقدان منصبه في جمهورية فلورنسا.\n\nكتب ماكيافيلي ما كتب ليدل الناس على مواطن الغدر، وليفطنوا إلى صنوف الخداع فيما يُدبَّر ضدهم، وما يُدَس لهم من الدسائس، ولو أن الناس تدبروا كتابه لما تمكن أحد من إيذائهم.\n\nلقد آنَ للقارئ أن ي", CategoryId = 8, ImageUrl = "/images/products/9789776743717.webp", Author = "نيقولا ماكيافيلي", PublishDate = new DateTime(2022, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789776743717", Pages = 240, Size = "12×17" },
            new { Id = 141, Name = "نشوات قديمة", Price = 290m, Stock = 10, Description = "أغنية خيال علمي...\nهذا هو تقريبًا أدق وصف لهذه الأغنية القديمة التي قدمها الثنائي الأمريكي \"زاجر وإيفانز\" عام 1969. لقد حققت نجاحًا هائلًا آنذاك، حتى أنه كان بإمكانك سماعها طوال اليوم على محطات الراديو في مصر. ولوقت طويل، كانت هذه المقطوعة الموسيقية هي الخلفية الصوتية لأي عمل درامي يتعلق بالمستقبلية.\nتتخيل الأغنية حالة الإنسانية في عام 2525، ثم تقفز بزيادات قدرها 1010 سنة مع كل مقطع جديد. تُظهر لنا كيف ستتقدم البشرية، لكن في اتجاه معاكس لليوتوبيا، حيث يتحول البشر إلى كائنات شبيهة بالآلات المبرمجة. تناقش الأغنية ما يناقشه كل كاتب معاصر في مجال الخيال العلمي، مع نفس اللمسة من التشاؤم والقلق على مصير هذا الكوكب الجميل الذي هدّرنا موارده دون حساب.\nاللحن سريع ومبهج، لكنه ينقل أيضًا إحساسًا بالرهبة والغربة؛ تشعر وكأنك في سباق محموم مع آلة زمن مجنونة نحو نهاية مجهولة ومظلمة، دون رجعة؛ فأنت تندفع بلا توقف نحو الثقب الأسود.\n(الكتاب عبارة عن مجموعة من المقالات يكتب فيها الدكتور أحمد خالد توفيق عن الأغاني التي يحبها ويترجمها.)", CategoryId = 8, ImageUrl = "/images/products/9789778202243.webp", Author = "أحمد خالد توفيق", PublishDate = new DateTime(2024, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778202243", Pages = 432, Size = "14×20" },
            new { Id = 142, Name = "سر الغرفة 207", Price = 170m, Stock = 10, Description = "تتألف رواية \"الغرفة 207\" من سلسلة قصص قصيرة وقعت مع أشخاص مختلفين في أوقات متباينة، والربط المشترك بينها هو وقوع جميعها في نفس المكان: الغرفة 207 في فندق بمرسى مطروح، مصر.\nتُلاحظ هذه الأحداث وتُروى على لسان العم جمال، الذي يجمع هذه القصص من خلال خبرته كمستقبل في الفندق، مما يخلق رابطًا خاصًا بينه وبين الغرفة، ومع كل العجائب والطرائف التي تحدث فيها، تأسر العقل وتوقظ الفضول.", CategoryId = 9, ImageUrl = "/images/products/9789778200270.webp", Author = "أحمد خالد توفيق", PublishDate = new DateTime(2017, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778200270", Pages = 220, Size = "14×20" },
            new { Id = 143, Name = "حظك اليوم", Price = 130m, Stock = 10, Description = "يقوم 12 صحفيًا بإعداد تقرير عن ساحر يخدع الناس، خاصة الفقراء، وينتهز كل ما يستطيع منهم بوعده لهم بحياة أفضل أو بحل لمعظم مشاكلهم.\nوبعد أن كشفوا الحقيقة، وُضع الساحر في السجن، ثم انتحر، تاركًا رسالة قصيرة لكل واحد من هؤلاء الـ12 صحفيًا، تتألف من جملة واحدة:\n«برجك (أبراجك الفلكية) سينتقم من أجلي.»\nوكلٌ منهم يواجه الموت بطريقة مختلفة وفقًا لبرجه.", CategoryId = 9, ImageUrl = "/images/products/9789778200164.webp", Author = "أحمد خالد توفيق", PublishDate = new DateTime(2018, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778200164", Pages = 130, Size = "14×20" },
            new { Id = 144, Name = "عقل بلا جسد", Price = 170m, Stock = 10, Description = "مجموعة قصص قصيرة ترتبط بفكرة واحدة: الصداقة بين شخصين.\nإحدى الشخصيات تتميز بجسد مفتول العضلات، بينما يتمتع الآخر بعقل لامع وذكاء خارق يمكنه حل أصعب المشكلات في دقائق معدودة.", CategoryId = 2, ImageUrl = "/images/products/9789778200287.webp", Author = "أحمد خالد توفيق", PublishDate = new DateTime(2018, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778200287", Pages = 224, Size = "14×20" },
            new { Id = 145, Name = "موسوعة الظلام", Price = 150m, Stock = 10, Description = "تتناول كل المقالات هنا الظواهر الأسطورية والأساطير، وهي بمثابة موسوعة للتعابير المخيفة في الأفلام والكتب وغيرها من أعمال الرعب، إلى جانب أبرز الكتاب والممثلين والمخرجين العاملين في هذا المجال.\nكما تُسلّط الضوء على بعض أشهر شخصيات الرعب مثل دراكولا وفرانكشتاين والذئاب المتحولة والزومبي، وأسماء الشياطين مثل بابوميت، ولوسيفر، وأبراكساس، بالإضافة إلى الأساليب السحرية المتعددة وأشهر السحرة، وحتى القتلة المتسلسلين الذين ارتكبوا مذابح مروعة.", CategoryId = 9, ImageUrl = "/images/products/9789778200225.webp", Author = "أحمد خالد توفيق", PublishDate = new DateTime(2018, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778200225", Pages = 191, Size = "14×20" },
            new { Id = 146, Name = "هادم الاساطير", Price = 130m, Stock = 10, Description = "مجموعة من المقالات التي تقوم بتفكيك الأساطير غير المنطقية المنتشرة حول العالم، خاصةً في العالم الغربي مثل مثلث برمودا، والأطباق الطائرة، والعلاج الروحي، ولعنة الفراعنة، وغيرها من الأساطير الشهيرة.\nيفترض الكاتب أن شعبية هذه الأساطير تعود إلى دوافع نفسية لدى البشر، ورغبة أدمغتهم في الإيمان بالأوهام، وقدرة بعض الأشخاص على زرع هذه المعتقدات.", CategoryId = 9, ImageUrl = "/images/products/9789778200249.webp", Author = "أحمد خالد توفيق", PublishDate = new DateTime(2018, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778200249", Pages = 164, Size = "14×20" },
            new { Id = 147, Name = "لست وحدك", Price = 170m, Stock = 10, Description = "قصص رعب قصيرة تتناول كل ما هو غير طبيعي: من الأشباح والشياطين الناطقة والأحلام الغريبة إلى الجنون والسفر عبر الزمن، مع لمسة من الرومانسية وعلم النفس.", CategoryId = 9, ImageUrl = "/images/products/9789778200607.webp", Author = "أحمد خالد توفيق", PublishDate = new DateTime(2019, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778200607", Pages = 234, Size = "14×20" },
            new { Id = 148, Name = "قهوة باليورانيوم", Price = 130m, Stock = 10, Description = "مجموعة من المقالات التي تجمع بين الطابع الساخر والمأساوي، وتقدم نظرة عن العالم المراوغ للفن، دون التطرق إلى السياسة.", CategoryId = 8, ImageUrl = "/images/products/9789778200218.webp", Author = "أحمد خالد توفيق", PublishDate = new DateTime(2017, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778200218", Pages = 142, Size = "14×20" },
            new { Id = 149, Name = "الحافة", Price = 170m, Stock = 10, Description = "مجموعة من المقالات التي تتناول الظواهر الخارقة والغرائبية، القريبة من الأساطير، والظواهر العلمية ذات طابع الخيال العلمي؛ أشياء تقع على حافة الواقع والخيال.", CategoryId = 9, ImageUrl = "/images/products/9789778200324.webp", Author = "أحمد خالد توفيق", PublishDate = new DateTime(2018, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778200324", Pages = 208, Size = "14×20" },
            new { Id = 150, Name = "الأن أفهم", Price = 130m, Stock = 10, Description = "قصص رعب قصيرة كتبها أحمد خالد توفيق بأسلوبه الساخر المميز، والتي تدفع القارئ إلى النهاية وهو يفكر: \"آه، الآن فهمت!\" بطريقة غير متوقعة.", CategoryId = 9, ImageUrl = "/images/products/9789778200263.webp", Author = "أحمد خالد توفيق", PublishDate = new DateTime(2017, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778200263", Pages = 148, Size = "14×20" },
            new { Id = 151, Name = "قصاصات قابلة للحرق", Price = 120m, Stock = 10, Description = "مجموعة قصص قصيرة مليئة بالأفكار؛ بعضها يتضمن أفكارًا فلسفية مبسطة، والبعض الآخر يتسم بالسخرية من كل شيء، حتى من الأفكار نفسها.", CategoryId = 1, ImageUrl = "/images/products/9789778200157.webp", Author = "أحمد خالد توفيق", PublishDate = new DateTime(2018, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778200157", Pages = 112, Size = "14×20" },
            new { Id = 152, Name = "ESP", Price = 170m, Stock = 10, Description = "الشخصية الرئيسية \"هند\" تتمتع بقدرات خارجة عن الحواس (ESP)، ويساعدها محمود الألفي على استغلال هديتها بشكل إيجابي.\nوفي كل مرة يطلب فيها ضابط الشرطة \"سمير الوانا\" مساعدتها، تساهم هند في حل العديد من الجرائم.", CategoryId = 3, ImageUrl = "/images/products/9789778200256.webp", Author = "أحمد خالد توفيق", PublishDate = new DateTime(2017, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778200256", Pages = 216, Size = "14×20" },
            new { Id = 153, Name = "لا مكان للملل", Price = 150m, Stock = 10, Description = "مجموعة من المقالات التي تتناول موضوعات سياسية ومختلف الأحداث الحياتية.", CategoryId = 8, ImageUrl = "/images/products/9789778200638.webp", Author = "أحمد خالد توفيق", PublishDate = new DateTime(2019, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778200638", Pages = 184, Size = "14×20" },
            new { Id = 154, Name = "قوس قزح", Price = 130m, Stock = 10, Description = "\"سبعة ألوان قوس قزح... سبع قصص رعب\"\nكتبها اثنان من أشهر كتّاب الرعب في مصر والعالم العربي.", CategoryId = 9, ImageUrl = "/images/products/9789778200614.webp", Author = "أحمد خالد توفيق", PublishDate = new DateTime(2019, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778200614", Pages = 140, Size = "14×20" },
            new { Id = 155, Name = "ضحكات كئيبة", Price = 170m, Stock = 10, Description = "مجموعة من المقالات الساخرة التي تتناول مواقف الحياة اليومية؛ ففي بعض الأحيان تحدث أشياء لا ندرك مدى تأثيرها الحقيقي، والهدف منها رسم الابتسامة، وإثارة الضحك، وتحفيز السعادة.", CategoryId = 8, ImageUrl = "/images/products/9789778200621.webp", Author = "أحمد خالد توفيق", PublishDate = new DateTime(2019, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778200621", Pages = 250, Size = "14×20" },
            new { Id = 156, Name = "شاي بالنعناع", Price = 140m, Stock = 10, Description = "مجموعة من المقالات التي تجمع بين الفرح والأفكار التي قد تجعلك تتوقف أحيانًا للتفكير في شؤون الحياة؛ كتب بعضها قبل الثورة المصرية والبعض الآخر بعدها.", CategoryId = 8, ImageUrl = "/images/products/9789778200201.webp", Author = "أحمد خالد توفيق", PublishDate = new DateTime(2017, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778200201", Pages = 164, Size = "14×20" },
            new { Id = 157, Name = "الغث من القول", Price = 170m, Stock = 10, Description = "مجموعة من المقالات التي تتناول آراء في السياسة، والفن، والأدب، والأفلام، والشؤون الخاصة.", CategoryId = 8, ImageUrl = "/images/products/9789778200195.webp", Author = "أحمد خالد توفيق", PublishDate = new DateTime(2017, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778200195", Pages = 226, Size = "14×20" },
            new { Id = 158, Name = "وساوس وهلاوس", Price = 170m, Stock = 10, Description = "مجموعة من المقالات الساخرة التي تتناول هلوسات الناس، وهلوسات الكتابة، والسينما، والمرور، والتعليم، والهلاوس الطبية والغذائية.", CategoryId = 8, ImageUrl = "/images/products/9789778200348.webp", Author = "أحمد خالد توفيق", PublishDate = new DateTime(2017, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778200348", Pages = 232, Size = "14×20" },
            new { Id = 159, Name = "افلام الحافظة الزرقاء", Price = 185m, Stock = 10, Description = "كتاب يأخذنا في رحلة شيقة عبر عالم السينما، حيث يناقش 33 فيلمًا مع مقاطع قصيرة عنها، مما يمنح القارئ تجربة فريدة ومميزة.", CategoryId = 8, ImageUrl = "/images/products/9789778200171.webp", Author = "أحمد خالد توفيق", PublishDate = new DateTime(2018, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778200171", Pages = 270, Size = "14×20" },
            new { Id = 160, Name = "زغازيغ", Price = 150m, Stock = 10, Description = "مجموعة أخرى من المقالات الساخرة عن مواقف الحياة اليومية، التي تحدث أحيانًا أشياء لا ندرك عمق تأثيرها، بهدف رسم الابتسامة، وإثارة الضحك، وتحفيز السعادة.", CategoryId = 8, ImageUrl = "/images/products/9789778200232.webp", Author = "أحمد خالد توفيق", PublishDate = new DateTime(2018, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778200232", Pages = 170, Size = "14×20" },
            new { Id = 161, Name = "فقاقيع", Price = 170m, Stock = 10, Description = "مجموعة من المقالات المتنوعة التي تتميز بخفة الظل والفكاهة، وتتناول العديد من الموضوعات التي تُضحك القارئ.", CategoryId = 8, ImageUrl = "/images/products/9789778200331.webp", Author = "أحمد خالد توفيق", PublishDate = new DateTime(2018, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778200331", Pages = 220, Size = "14×20" },
            new { Id = 162, Name = "WWW", Price = 240m, Stock = 10, Description = "مجموعة من خمسة روايات مترابطة تتحدث عن كيان يعيش كفيروس حاسوبي، يتجول بين أجهزة الكمبيوتر في جميع أنحاء العالم، يكتشف الأسرار ويشهد أشياء مرعبة، مما يجعلك تغوص في عالم مختلف تمامًا.", CategoryId = 3, ImageUrl = "/images/products/9789778200188.webp", Author = "أحمد خالد توفيق", PublishDate = new DateTime(2018, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778200188", Pages = 422, Size = "14×20" },
            new { Id = 163, Name = "يوميات اّخر البشر", Price = 170m, Stock = 10, Description = "في زمنٍ ينهار فيه كل شيء، وتقترب البشرية من حافّة الفناء، تبدأ الحكايات الأخيرة في التكوّن.\nحكايات عن مدنٍ سقطت، وأحلامٍ تحوّلت إلى كوابيس، وأسرارٍ تُروى قبل أن يختفي آخر من يتذكرها.\nفي \"يوميات آخر البشر\"، يصحبنا د. نبيل فاروق في رحلة بين عوالم من الخيال العلمي والرعب والغموض، حيث لا يكون الإنسان دائمًا البطل… وأحيانًا لا يكون حتى الناجي الأخير.\nفهل ستكشف هذه اليوميات عن الأمل… أم عن النهاية التي لا مفرّ منها؟", CategoryId = 2, ImageUrl = "/images/products/9789778202816.webp", Author = "نبيل فاروق", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778202816", Pages = 124, Size = "14×20" },
            new { Id = 164, Name = "في قلبي أنثى عبرية", Price = 325m, Stock = 10, Description = "تدور أحداث القصة حول ريما، الفتاة المسلمة من تونس التي فقدت والديها. كانت آخر كلمات والدتها إلى جارتها اليهودية يعقوب أن يربيها على نهج الإسلام. كبرت الفتاة، وأخذت ترتدي الحجاب، فبدأت تعتبر يعقوب غريبًا عنها. حينها، طالبت زوجته تانيا أن يختار بينها وبين ريما التي أحبها كابنته. فقام بإرسالها إلى أخته راشيل في لبنان، لتتعقد الأمور عندما اضطرت إلى التنقل بسبب سوء معاملة زوج راشيل لها. وعاشت بعدها مع صديقة راشيل، سونيا، التي كانت من سكان تونس أيضًا لكنها فرت من زوجها التعسفي برفقة ابنتيها ندى ودانا إلى مدينة قانا في لبنان. وهكذا، تتشابك مصائر الجميع في دوامة من التعقيد.\nقصة عن الإنسانية، والأديان، والحب.", CategoryId = 4, ImageUrl = "/images/products/9789776376441.webp", Author = "خولة حمدي", PublishDate = new DateTime(2013, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789776376441", Pages = 388, Size = "14×20" },
            new { Id = 165, Name = "ياسمين أبيض", Price = 400m, Stock = 10, Description = "في هذا الجزء الأخير، يبرز عمر وياسمين كشخصيات مركزية، حيث ينقل الكاتب مشاعرهما بعبقرية تجعل القارئ يشعر وكأنه يعيش كل لحظة من خلال قلبيهما.\nتتعمق الرواية في تناول قضايا اجتماعية وإنسانية متعددة، مؤكدةً على أهمية الأفراد المبادرين في المجتمع؛ فحتى أرقى الأعمال يمكنها أن تترك أثرًا دائمًا، مما يبرز القوة الهادئة للجهود الخيرية.\nكما تطرق القصة إلى أزمة اللاجئين السوريين والحرب الأهلية، لتأخذ القارئ في رحلة عبر الأردن، خاصةً مخيم الزعتري، إلى جانب تونس، والمغرب، وباريس، وجبال سويسرا الساحرة.\nبأسلوب جذاب ومشوق، تنسج هذه الثلاثية تسلسلاً قويًا من الأحداث، فتشد القارئ بسرد مميز يحافظ على انتباهه من البداية حتى النهاية.", CategoryId = 4, ImageUrl = "/images/products/9789778201338.webp", Author = "خولة حمدي", PublishDate = new DateTime(2023, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778201338", Pages = 560, Size = "14×20" },
            new { Id = 166, Name = "ياسمين العودة", Price = 370m, Stock = 10, Description = "مفتاح العودة.\nلم تكن قصة المفاتيح مجرد أسطورة، بل كانت حقيقية.\nنحتفظ بالمفتاح والصور القديمة، ونعهد أن نرعى تلك الحكايات. نسقي الذكريات بالدموع والحنين حتى لا ننسى من نحن وما هي قضيتنا.", CategoryId = 4, ImageUrl = "/images/products/9789778200935.webp", Author = "خولة حمدي", PublishDate = new DateTime(2021, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778200935", Pages = 544, Size = "14×20" },
            new { Id = 167, Name = "غربة الياسمين", Price = 275m, Stock = 10, Description = "تتناول هذه الرواية وضعًا حساسًا للغاية، حياة اللاجئين العرب والمسلمين في فرنسا، ومدى صعوبة الاندماج في مجتمع متنوع العادات والمعتقدات والأديان.\nتحكي عن ياسمين، الفتاة المسلمة التي ترتدي الحجاب، والمشكلات التي تواجهها بسببه، وبالمقابل عن عمر المغربي، الشاب العالم الذي يبحث في الاندماج النووي البارد لإيجاد مصدر طاقة نظيف، إلا أن الأمور تنقلب عندما يحدث انفجار، فيجد نفسه متهمًا بالإرهاب ومهددًا بالسجن.\nكما نسلط الضوء على رنيم، الفتاة المصرية الليبرالية التي عاشت حياتها مندمجة في مجتمعها، مدافعة عن عمر وموقنة بأنه ليس إرهابيًا.", CategoryId = 4, ImageUrl = "/images/products/9789776376632.webp", Author = "خولة حمدي", PublishDate = new DateTime(2015, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789776376632", Pages = 408, Size = "14×20" },
            new { Id = 168, Name = "أن تبقى", Price = 275m, Stock = 10, Description = "وصل نادر الشاوي، المهاجر غير الشرعي، إلى الأراضي الفرنسية في عام 2004 على متن إحدى \"قوارب الموت\" القادمة من الجزائر. وفي عام 2035، ترشح ابنه خليل، الشاب المحامي، للانضمام إلى مجلس الشيوخ الفرنسي، حيث يكتشف تاريخي والده عندما يتلقى بعض الرسائل مصحوبة بغطاء رصاصة.\nتسلط الرواية الضوء على معاناة اللاجئين العرب في أوروبا، لا سيما في فرنسا، مع تسليط الضوء على أزمة الهوية المزدوجة بين الاندماج والتمسك بالجذور.\nكما تتناول الإرهاب، بدءًا من \"العشرية السوداء\" في الجزائر وصولاً إلى هجمات باريس عام 2015، وتكشف عن الوجه المروع لتجربة الهجرة غير الشرعية والتمييز العنصري الذي يواجهه المهاجرون في أوروبا، والذي بعيد كل البعد عن صورة \"الجنة الأرضية\" التي كانوا يحلمون بها.", CategoryId = 4, ImageUrl = "/images/products/9789776376908.webp", Author = "خولة حمدي", PublishDate = new DateTime(2016, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789776376908", Pages = 384, Size = "14×20" },
            new { Id = 169, Name = "أين المفر", Price = 300m, Stock = 10, Description = "تعود الرواية لتستعرض ما جرى بعد الثورة التونسية، في قصة تحكي خيبة الأمل التي أعقبت الثورات العربية غير المكتملة.\nيقول كل من التونسية ليلى، والمصرية سوسن، والسوري نزار: \"ليست ثورات، بل مجرد شائعات مترددة.\"\nتعود ليلى إلى وطنها من سويسرا لتتأمل في العلاقات المتصدعة، ووطنٍ متمرد، ويبدأ فراس، المتشبث بذكرياته الماضية، رحلة لاكتشاف وطنها الحقيقي الذي كانت تعرفه فقط من خلال حكايات والدها، تلك الحكايات التي كانت تبحر بها في بحر معاني الوطن والثورات.", CategoryId = 4, ImageUrl = "/images/products/9789778200492.webp", Author = "خولة حمدي", PublishDate = new DateTime(2018, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778200492", Pages = 432, Size = "14×20" },
            new { Id = 170, Name = "صدمات", Price = 375m, Stock = 10, Description = "تفقد (ليك) والدها فجأة، فتجد نفسها مضطرة لترك حياتها في تكساس، والانتقال مع والدتها وأخيها الصغير (كيل) إلى مدينة جديدة.\nهناك تلتقي بجارها الجديد (ويل كوبر)، شاب يشاركها شغفها بالموسيقى، فينشأ بينهما انجذاب قوي يبدو وكأنه بداية لقصة حب جميلة.\nلكن سرعان ما يتغير كل شيء، حين تكتشف أن (ويل) هو مدرّسها الجديد في الثانوية، فيتحول الانجذاب البريء إلى موقف معقد، يضعهما في مواجهة تحديات صعبة تتعلق بالمجتمع والقيم.\nفهل يستحق حبهما المخاطرة؟ أم أن بعض الخطوط وُضعت لتظل غير قابلة للتجاوز؟", CategoryId = 4, ImageUrl = "/images/products/9789778201666.webp", Author = "كولين هوڤر", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778201666", Pages = 336, Size = "14×20" },
            new { Id = 171, Name = "هذه الفتاة", Price = 410m, Stock = 10, Description = "‎الآن حان وقت سماع القصة من الجانب الآخر، من منظور (ويل).\n‎مع بداية زواجه من (ليك)، يبدأ في سرد حكايته، كاشفًا عن مشاعره منذ اللحظة الأولى التي وقعت عيناه عليها، وحتى وصولهما إلى هذه المرحلة من حياتهما.\n‎من خلال كلماته نكتشف صراعاته الداخلية، وألمه لفقد والديه، ومسؤوليته تجاه شقيقه الأصغر، وكذلك مخاوفه من خسارة (ليك) في كل مرة حاول فيها كبح مشاعره.\n‎هذه الرواية ليست إعادة للأحداث، بل نافذة تكشف لنا الجانب الخفي من القصة التي عرفناها من قبل.", CategoryId = 4, ImageUrl = "/images/products/9789778202878.webp", Author = "كولين هوڤر", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778202878", Pages = 378, Size = "14×20" },
            new { Id = 172, Name = "بدون ميريت", Price = 440m, Stock = 10, Description = "الكاتبة الحائزة على لقب نيويورك تايمز الأفضل مبيعًا، والتي أبهرت القرّاء بروايتها ميؤوس منه، قصة ما\nحدث عندما التقت الفتاة المضطربة سكاي مع صديق طفولتها الذي فقدته منذ زمن طويل، دين هولدر.\nبمساعدة دين هولدر، كشفت سكاي عن أسرار عائلية صادمة وتصالحت مع ذكريات وعواطف خلّفت\nجروحًا عميقة.\nميئوس منه كانت قصة سكاي. والآن، في رواية فقدان الأمل، نتعرف أخيرًا على حقيقة &quot;دين هولدر&quot;.\nيعيش هولدر حياة مظلمة بسبب الطفلة الصغيرة التي لم يتمكن من إنقاذها من الخطر الوشيك، وتغمره\nمشاعر الذنب والندم. لم يتوقف هولدر عن البحث عنها، يعتقد أن العثور عليها سيجلب له السلام الذي\nيحتاجه للتقدّم في الحياة. ومع ذلك، لم يكن هولدر يتوقع أن يواجه المزيد من الألم في لحظة لقائهما مجددًا.\nفي رواية فقدان الأمل يكشف هولدر طريقة تأثير أحداث طفولة &quot;سكاي&quot; عليه وعلى عائلته، مما دفعه إلى\nالبحث عن الفداء من خلال إنقاذها. ولكنه فقط حب سكاي الذي يمكنه من البدء في شفاء نفسه.", CategoryId = 4, ImageUrl = "/images/products/9789778202229.webp", Author = "كولين هوڤر", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778202229", Pages = 420, Size = "14×20" },
            new { Id = 173, Name = "فقد", Price = 450m, Stock = 10, Description = "الكاتبة الحائزة على لقب نيويورك تايمز الأفضل مبيعًا، والتي أبهرت القرّاء بروايتها ميؤوس منه، قصة ما\nحدث عندما التقت الفتاة المضطربة سكاي مع صديق طفولتها الذي فقدته منذ زمن طويل، دين هولدر.\nبمساعدة دين هولدر، كشفت سكاي عن أسرار عائلية صادمة وتصالحت مع ذكريات وعواطف خلّفت\nجروحًا عميقة.\nميئوس منه كانت قصة سكاي. والآن، في رواية فقدان الأمل، نتعرف أخيرًا على حقيقة &quot;دين هولدر&quot;.\nيعيش هولدر حياة مظلمة بسبب الطفلة الصغيرة التي لم يتمكن من إنقاذها من الخطر الوشيك، وتغمره\nمشاعر الذنب والندم. لم يتوقف هولدر عن البحث عنها، يعتقد أن العثور عليها سيجلب له السلام الذي\nيحتاجه للتقدّم في الحياة. ومع ذلك، لم يكن هولدر يتوقع أن يواجه المزيد من الألم في لحظة لقائهما مجددًا.\nفي رواية فقدان الأمل يكشف هولدر طريقة تأثير أحداث طفولة &quot;سكاي&quot; عليه وعلى عائلته، مما دفعه إلى\nالبحث عن الفداء من خلال إنقاذها. ولكنه فقط حب سكاي الذي يمكنه من البدء في شفاء نفسه.", CategoryId = 4, ImageUrl = "/images/products/9789778201642.webp", Author = "كولين هوڤر", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778201642", Pages = 440, Size = "14×20" },
            new { Id = 174, Name = "حب قبيح", Price = 450m, Stock = 10, Description = "قصة حب لا تُنسى، تكسر كل القواعد، من كولين هوفر، المؤلفة رقم 1 في قائمة الأكثر مبيعًا\n\nلصحيفة نيويورك تايمز.\n\nلم تقع تايت كولينز في الحب من أول نظرة عندما التقت بالمعذَّب سرًّا مايلز أرتشر؛ بل لا\nيمكن عدُّهما في الأصل أصدقاء. الشيء الوحيد المشترك بينهما كان الانجذاب الجسدي الذي\nلا يُمكن إنكاره. فما إن كشفت رغباتهما عن نفسها، حتى أدركا أنهما توصلا لاتفاقٍ مثالي بلا\nأية قيود. فهو لا يبحث عن الحب، وهي لا تملك الوقت لذلك، ومن هنا لا يتبقى لهما سوى\nالعلاقة الجسدية، التي قد تكون مُرضية بشكلٍ مدهش، إذا التزمت تايت بقاعدتين وضعهما\nمايلز: لا أسئلة أبدًا عن الماضي، ولا توقع لأي مستقبل قد يجمعهما على الإطلاق.\nلقد ظنَّا أن بإمكانهما الالتزام بالاتفاق، لكن كل شيء في المعادلة يتغيَّر، ما إن تظهر المشاعر\nالحقيقية على السطح.\n                                                  فالقلوب تُخترَق.\n                                                   والوعود تُكسَر.\n                                                 والقواعد تتحطم.\n                                                والحب يُصبح بشعًا.\n  \n*وحدها كولين هوفر التي تستطيع وضع هذا القدر من التألق في رواية واحدة. - جيمي\nماجواير، المؤلفة الأكثر مبيعًا في قائمة صحيفة نيويورك تايمز، ومؤلفة رواية &quot;كارثة\nجميلة&quot;.", CategoryId = 4, ImageUrl = "/images/products/9789778202717.webp", Author = "كولين هوڤر", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778202717", Pages = 440, Size = "14×20" },
            new { Id = 175, Name = "ميؤوس منه", Price = 400m, Stock = 10, Description = "أحيانًا، قد يترك اكتشاف الحقيقة في داخلك حالة من اليأس أعمق مما يتركه الإيمان بالأكاذيب...\n\nهذا ما تدركه سكاي، الفتاة ذات السابعة عشرة من عمرها، بعد لقائها مع دين هولدر. شاب يتمتع بسمعة تضاهي سمعتها، وبقدرة غير عادية على استحضار مشاعر لم تختبرها من قبل؛ فهو يخيفها ويسحرها في لقاء واحد فقط، بينما يوقظ بها شعورًا عميقًا يحرّض ذكريات مدفونة من ماضٍ كانت تفضل أن يبقى خفيًا.\n\nتكافح سكاي للحفاظ على مسافة منه، مع علمها بأنه لا يجلب سوى المشاكل، لكن هولدر يُصر على معرفة كل شيء عنها. وبعد أن تستسلم أخيرًا لمطاردته الدؤوبة، تكتشف أن هولدر ليس كما كان يدعي. وعندما تنكشف الأسرار التي كان يخفيها، سيتغير كل جانب من جوانب حياة سكاي إلى الأبد.", CategoryId = 4, ImageUrl = "/images/products/9789778201345.webp", Author = "كولين هوڤر", PublishDate = new DateTime(2023, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778201345", Pages = 432, Size = "14×20" },
            new { Id = 176, Name = "نادمة عليك", Price = 400m, Stock = 10, Description = "لا تودُّ مورغان جرانت وابنتها كلارا، البالغة من العمر ستة عشر عامًا، أن يكونا متشابكين بأي شكل من الأشكال.\n\nمورغان مصممة على منع ابنتها من تكرار الأخطاء التي ارتكبتها هي بنفسها؛ ففي شبابها، من خلال حملها والزواج في وقت مبكر جدًا، أجلت تحقيق أحلامها. بينما ترفض كلارا أن تسلك درب والدتها المتوقعة، التي تخلو من أي عفوية.\n\nومع تضارب الشخصيات وتعارض الأهداف، تجد مورغان وكلارا صعوبة متزايدة في التعايش. الشخص الوحيد الذي يستطيع أن يجلب السلام إلى البيت هو كريس—زوج مورغان، ووالد كلارا، والعمود الفقري للعائلة. لكن هذا السلام ينكسر حين يتورط كريس في حادث مأساوي ومثير للشكوك، حيث تمتد عواقبه القاسية وطويلة الأمد إلى ما هو أبعد من مجرد مورغان وكلارا وحدهما.\n\nوأثناء سعيهما لإعادة بناء كل ما تحطم حولهما، تجد مورغان العزاء في آخر شخص كانت تتوقعه، بينما تلجأ كلارا إلى الصبي الذي حُرِمت من رؤيته. ومع مرور الأيام، تتكشف أسرار جديدة، ويتفاقم الاستياء وسوء الفهم، مما يجعل العلاقة بين الأم وابنتها تتباعد أكثر فأكثر، حتى يصبح التقارب بينهما شبه مستحيل.", CategoryId = 4, ImageUrl = "/images/products/9789778201369.webp", Author = "كولين هوڤر", PublishDate = new DateTime(2023, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778201369", Pages = 448, Size = "14×20" },
            new { Id = 177, Name = "بئر العروج", Price = 975m, Stock = 10, Description = "قد هُزِم الشر...\nلكن الحرب لم تبدأ إلا الآن.\nلقد صنعوا المستحيل؛ أطاحوا بالطاغية الذي استمرَّ حكمه الغاشم ألف عام. والآن، بات لزامًا على \"ڤين\"، فتاة الشوارع التي غدت أقوى \"وليدة ضباب\" في البلاد، و\"إليند ڤينتشر\"، الشاب المثالي النبيل الذي يهواها، أن يُشيَّدا مُجتمعًا جديدًا سليمًا على أنقاض إمبراطوريةٍ مُتداعية.\nلكنهما ما كادا يشرعان في مهمتهما، حتى هاجمتهما ثلاثةُ جيوشٍ مُنفصِلة. وبينما يشتدُّ عليهم الحصار، تلوح في الأفق أسطورةٌ قديمةٌ لتبعث بصيصًا من الأمل. ولكن، حتى لو كانت تلك الأسطورة حقيقيةً، فلا أحد يعلم أين يُوجَد بئر العروج ذاك، أو أيّ قوةٍ تلك التي يمنحها.\n\nلرُبَّما كان قتل \"اللورد الحاكم\" هو الجزء الأسهل، فالنجاة من عواقب سقوطه هي التحدّي الحقيقي.", CategoryId = 3, ImageUrl = "/images/products/9789778203042.webp", Author = "براندون ساندرسون", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778203042", Pages = 1132, Size = "14×20" },
            new { Id = 178, Name = "الفيلق", Price = 490m, Stock = 10, Description = "ستيفن ليدز عبقري يتمتع بموهبة لا نظير لها، إذ أنه يستطيع تعلم أي مهارة جديدة أو مهنة أو فن جديد في غضون ساعات فحسب. لكن كي يتمكن عقله من احتواء كل ذلك، فهو يلجأ إلى خلق هلاوس في صورة أشخاص متخيلين، يسميهم ستيفن «جوانبه» المختلفة، للاحتفاظ بكل تلك المعلومات وإظهارها وقت اللزوم. وأينما ذهب ستيفن، يتبعه حشد من الخبراء الخياليين، كي يسدوا إليه النصح والمشورة، ويقدموا له التفسير والشرح الذي يحتاجه منهم. وهو يستعين بفريقه هذا في حل القضايا المختلفة، نظير الحصول على أجر.\n\nاسمي ستيفن ليدز، وأنا عاقل تمامًا. لكنَّ هلاوسي كلها في غاية الجنون...\nأنا لست ما يتوقعه الناس أبدًا. يتخيلني البعض كما لو كنت عالِمًا غريب الأطوار من نوع ما، بينما يتخيلني البعض الآخر كنجم من نجوم افلام الحركة. لكن ما يجدونه بدلًا من ذلك هو رجل هادئ إلى حدٍّ ما في الثلاثينيات من عمره، طبيعي تمامًا. أحيانًا ما أشعر وكأنني أُشبِهُ غرفتي البيضاء، بطريقةٍ ما. سجل فارغ تمامًا. تنفرد جوانبي المختلفة بكل الخصائص المميزة، بينما أحاول أنا جاهدًا ألا أكون بارزًا للعيان. لأنني لست مجنونًا...\nلديَّ جوانب متعددة. سبعة وأربعون، على وجه الدقة... لا أحتاجهم جميعًا في الغالب، وفي الواقع فإن تخيُّل أكثر من  أربعة أو خمسة في نفس الوقت أمر مرهق، ولا يمكنني القيام به لفترة طويلة... في بعض الأحيان، تأتي مهمة تتطلَّب جهدًا إضافيًّا، وأحتاج إلى أن يصغي إلىَّ عدد أكبر من جوانبي. لهذا السبب أنشأتُ الغرفة البيضاء. كانت جدرانها خالية، ومطلية هي والأرض والسقف بنفس اللون الأبيض غير اللامع، وجميع أسطح الغرفة ناعمة وباردة ولا يقطعها شيء سوى الأنوار في السقف. كانت عازلة للصوت وهادئة، ولا يوجد بها ما يشتت الانتباه، ولا شيء أركز عليه سوى عشرات الأشخاص الوهميين الذين تدفقوا عبر الباب المزدوج...\nكانت القائمة تطول. انضموا إليَّ على مهل، في مهمةٍ تلو الأخرى، حينما كنت أحتاج إلى تعلُّم مهارة جديدة، لأحشو عقلي المكتظ بالفعل بمجموعة متنوعة من الكفاءات المتزايدة. تصرفوا مثل الأشخاص الحقيقيين تمامًا، وهم يتحدثون بعدة لغات...\nوعلى الرغم من أن كثيرًا من جوانبي كانوا يتحدثون عن حياتهم، وأسرهم، وأصدقائهم، وهواياتهم، إلا أنني لم أرَ في الواقع أي شيءٍ من هذا. وكان ذلك من الجيد، لأن تتبُّع سبعٍ وأربعين هلوسة أمر شاق بما فيه الكفاية. لو كان عليَّ تخيُّل أقاربهم أيضًا، فقد ينتهي بي الحال إلى الجنون...\nأجل، كلُّ هذا داخل عقلي فحسب، لكن الألم «كلُّه داخل عقلي» أيضًا، والحُب «كلُّه داخل عقلي». كل الأشياء المُهمَّة في الحياة هي تلك التي لا يمكنك قياسها! الأشياء التي تختلِقُها أدمغتنا! كونُها مُختلَقةً لا يعني أنها غير ذات أهمية.", CategoryId = 2, ImageUrl = "/images/products/9789778201727.webp", Author = "براندون ساندرسون", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778201727", Pages = 536, Size = "14×20" },
            new { Id = 179, Name = "حطمني", Price = 300m, Stock = 10, Description = "أنا محملة بلعنة، وأحمل هبةً في آنٍ واحد.\nأنا وحشٌ، ولكني أكثر من مجرد بشر.\nلمستي قاتلة، ولمستي تجسّد القوة.\nأنا سلاحهم، وسأنتقم.\n\nلم يمسّ جوليت أحدًا منذ 264 يومًا بالضبط.\nآخر مرة لمست فيها أحدًا كانت مجرد حادثة، لكن \"إعادة التأسيس\" سجنتها بتهمة القتل. لا أحد يعرف سبب فتك لمسة جوليت؛ وطالما أنها لا تؤذي أحدًا آخر، لا يُعيرها أحد اهتمامًا، فالعالم منشغل بانهيار ذاته إلى شظايا، والأمر لا يشغل بال أحد بفتاة تبلغ من العمر سبعة عشر عامًا.\nتفتك الأمراض بالسكان، ويصبح العثور على الطعام أمرًا نادرًا، والطيور لم تعد تحلّق، والغيوم باتت بلون خاطئ.\nأعلنت \"إعادة التأسيس\" أن طريقتها هي السبيل الوحيد لإصلاح الأمور، فأسَرعوا برمي جوليت في زنزانة. والآن، بعد أن زادت أعداد القتلى حتى بدأ الناجون يهمسون بالحرب، تغيرت وجهات نظرهم؛ فقد تكون جوليت أكثر من مجرد روح معذبة محشوة في جسد سام، وربما هي بالضبط ما يحتاجونه الآن.\nوعليه أن تختار: أن تكون سلاحًا، أو أن تكون محاربة.", CategoryId = 2, ImageUrl = "/images/products/9789778201109.webp", Author = "طاهرة ماڤي", PublishDate = new DateTime(2022, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778201109", Pages = 336, Size = "14×20" },
            new { Id = 180, Name = "فسرني", Price = 415m, Stock = 10, Description = "في الجزء الثاني  من سلسلة \"حطمني\" للمؤلفة الأكثر مبيعًا وفق نيويورك تايمز، طاهره مافي، كان من المفترض أن تكفي لمسة واحدة من جوليت لقتل وارنر، لكن مناعته الغامضة ضد قوتها القاتلة هزّتها وتركتها تتساءل لماذا فشل درعها الأخير أمام الشخص الذي تحتاج إلى حمايته بشدة.\nنجحت هي وآدم في الفرار من مكائد وارنر والانضمام إلى مجموعة من المتمردين، كثيرٌ منهم يمتلك قدرات خارقة. ستتمكن جوليت أخيرًا من محاربة \"إعادة التأسيس\" بنشاط ومحاولة إصلاح عالمها الممزق، وربما يساعدها هؤلاء الحلفاء الجدد في كشف سر مناعة آدم ووارنر ضد بشرتها القاتلة.\nعالم جوليت مليء بالإثارة عالية المخاطر والرومانسية المشوقة، ما يجعله مثاليًا لعشاق سلسلة \"الملكة الحمراء\" لفيكتوريا أفيارد وثلاثية \"أكثر العقول ظلاماً\" لألكسندرا براكن.\nوقد أشاد رانسوم ريجز، المؤلف رقم 1 بحسب نيويورك تايمز، في قوله: \"ملحمة مثيرة ومليئة بالمخاطر لاكتشاف الذات والحب الممنوع؛ سلسلة 'حطمني' قراءة لا بد منها لعشاق أدب الشباب الديستوبي—أو أي أدب!\"", CategoryId = 2, ImageUrl = "/images/products/9789778201536.webp", Author = "طاهرة ماڤي", PublishDate = new DateTime(2023, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778201536", Pages = 464, Size = "14×20" },
            new { Id = 181, Name = "أشعلني", Price = 385m, Stock = 10, Description = "في الجزء الثالث من سلسلة \"حطمني\" الأكثر مبيعًا، والذي وصفه رانسوم ريجز بأنه \"ملحمة مثيرة ومليئة بالمخاطر لاكتشاف الذات والحب الممنوع\"، تجد جوليت نفسها بعد تدمير \"نقطة أوميغا\" غير مدركة لما إذا كان المتمردون أو أصدقاؤها، أو حتى آدم، لا يزالون على قيد الحياة.\nومع ذلك، لن يمنعها ذلك من السعي للقضاء على \"إعادة التأسيس\" مرة وإلى الأبد. الآن، عليها أن تعتمد على وارنر، القائد الوسيم للقطاع 45، الشخص الذي لم تعتقد يومًا أنها تستطيع الوثوق به، والذي أنقذ حياتها يومًا ما. يعد وارنر بمساعدة جوليت على التحكم في قواها وإنقاذ عالمهم المحتضر، لكن رغباته لا تقتصر على ذلك وحده.", CategoryId = 2, ImageUrl = "/images/products/9789778201611.webp", Author = "طاهرة ماڤي", PublishDate = new DateTime(2023, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778201611", Pages = 420, Size = "14×20" },
            new { Id = 182, Name = "أعدني", Price = 400m, Stock = 10, Description = "كانت جوليت فيرارز تظن أنها انتصرت؛ فقد استولت على القطاع 45 وتُعيّنت كالقائدة العليا الجديدة، وأصبح وارنر إلى جانبها. لكنها لا تزال الفتاة التي تملك القدرة على القتل بلمسة واحدة، والآن أصبح العالم بأسره بين يديها.\nفحين تضرب المأساة، من ستكون؟ وهل ستستطيع السيطرة على القوة التي تملكها وتحويلها إلى قوة للخير؟", CategoryId = 2, ImageUrl = "/images/products/9789778202304.webp", Author = "طاهرة ماڤي", PublishDate = new DateTime(2024, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778202304", Pages = 424, Size = "14×20" },
            new { Id = 183, Name = "أعصني", Price = 350m, Stock = 10, Description = "هذه الفتاة لم تكن لك يومًا، هذه الفتاة حُكم عليها بالموت في اللحظة التي أطلقت عليها اسم \"جولييت\".\n\nظنت جولييت فيرارز أنها قادرة على هزيمة \"إعادة التأسيس\"، أنها قادرة أخيرًا على السيطرة على حياتها وقوتها وألمها، ولكن فجأة ينهار كل شيء لتكتشف أن حياتها مجرد حفنة من الأكاذيب، ولكي تظل على قيد الحياة.. لكي تنتصر؛ عليها أن تتذكر ماضيها.", CategoryId = 2, ImageUrl = "/images/products/9789778202540.webp", Author = "طاهرة ماڤي", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778202540", Pages = 334, Size = "14×20" },
            new { Id = 184, Name = "عقول مرتابة", Price = 370m, Stock = 10, Description = "مختبر غامض. عالم شرير. تاريخي سري. إذا كنت تعتقد أنك تعرف الحقيقة وراء والدة إلفن، فاستعد لأن تنقلب مفاهيمك رأسًا على عقب في هذه المقدمة المثيرة للمسلسل الشهير \"أشياء غريبة\".\nفي صيف عام 1969، يتردد صدى الصراع بين شباب أمريكا في كل من الداخل والخارج. كطالبة في حرم جامعي هادئ بعمق ولاية إنديانا، كانت تيري إيفز بعيدة كل البعد عن الخطوط الأمامية لحرب فيتنام أو الاحتجاجات المشتعلة في واشنطن.\nلكن العالم يتغير، ولم تكتفِ تيري بالمشاهدة من على الهامش. حينما بدأ الخبر بالانتشار عن تجربة حكومية مهمة في بلدة هوكينز الصغيرة، انضمت تيري كموضوع تجريبي للمشروع الذي حمل الاسم الرمزي MKUltra. شاحنات غير موسومة، مختبر بعيد في أعماق الغابات، مواد تغير الوعي تُعطى من باحثين متكتمين، وغموض تصر تيري الشابة الثائرة على كشفه.\nوراء جدران مختبر هوكينز الوطني، وتحت نظرة مديره الثاقبة، الدكتور مارتن برينر، تكمن مؤامرة أعظم مما تخيلت. لمواجهتها، ستحتاج تيري إلى مساعدة زملائها في التجربة، بمن فيهم شخص غامض لدرجة أن العالم لا يعرف بوجوده—فتاة شابة تمتلك قوى خارقة لا تُفسر، وتحمل رقمًا بدلاً من اسم: 008.\nوسط تصاعد التوترات في العقد الجديد، بدأ تيري والدكتور برينر حربًا مختلفة، حربًا تصبح فيها العقل البشري ساحة المعركة.", CategoryId = 9, ImageUrl = "/images/products/9789778200997.webp", Author = "جويندا بوند", PublishDate = new DateTime(2022, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778200997", Pages = 392, Size = "14×20" },
            new { Id = 185, Name = "الظلام عند أطراف المدينة", Price = 370m, Stock = 10, Description = "يكشف الرئيس جيم هوبر عن الأسرار التي طال انتظارها لإلفن حول حياته السابقة كمحقق شرطي في مدينة نيويورك، مواجهًا ماضيه قبل أحداث المسلسل الشهير \"أشياء غريبة\".\nفي كريسماس هوكينز عام 1984، كان كل ما يرغب به هوبر هو قضاء عيد ميلاد هادئ مع إلفن، لكن ابنته المتبناة كانت لها خططها الخاصة. رغم اعتراضات هوبر، خرجت من القبو صندوق كرتوني مكتوب عليه \"نيويورك\"، وبدأت الأسئلة الصعبة تتطاير: لماذا غادر هوبر هوكينز منذ كل تلك السنين؟ ماذا تعني كلمة \"فيتنام\"؟ ولماذا ظل صامتًا عن نيويورك؟\nعلى الرغم من أنه يفضل مواجهة جحافل المخلوقات الغريبة على الحديث عن ماضيه، يعلم هوبر أنه لم يعد بإمكانه إنكار الحقيقة. وهكذا تبدأ قصة الحادثة في نيويورك—آخر قضية كبيرة قبل أن يتغير كل شيء.\nفي صيف نيويورك عام 1977، يبدأ هوبر حياةً جديدة بعد عودته من فيتنام؛ فوجود فتاة صغيرة، وزوجة محبة، ودور جديد في شرطة نيويورك يسهل عليه العودة للحياة المدنية. لكن مع ظهور عملاء اتحاديين غامضين واستيلائهم على ملفات سلسلة جرائم وحشية غير محلولة، يتولى هوبر زمام الأمور مخاطراً بكل شيء لاكتشاف الحقيقة.\nوسرعان ما يتسلل هوبر إلى صفوف عصابات شوارع نيويورك الشهيرة، لكن حين يوشك على حل القضية، يحل الظلام فجأة على المدينة، فيغرق هوبر في عتمة لم يشهد مثلها من قبل.", CategoryId = 9, ImageUrl = "/images/products/9789778201093.webp", Author = "آدم كريستوفر", PublishDate = new DateTime(2022, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778201093", Pages = 384, Size = "14×20" },
            new { Id = 186, Name = "شيرلوك هولمز لفافة الموتي", Price = 200m, Stock = 10, Description = "يحضر شيرلوك هولمز جلسة روحانية لكشف المحتال المتنكر في هيئة وسيط، سيباستيان ميلموث، الرجل المهووس بالسعي وراء الخلود بعد اكتشاف بردية مصرية قديمة. وتقع مهمة إيقافه ومنع الكارثة على عاتق هولمز وواتسون.\nفي هذه المغامرة السريعة، تنتقل الأحداث من لندن إلى منطقة البحيرات الخلابة، حيث يخوض هولمز وواتسون معركتهما ضد قوى الشر مرة أخرى.\nيعود الإبداع الخالد للسير آرثر كونان دويل في سلسلة جديدة من قصص التحقيق المصممة بذوق رفيع؛ بدءًا من بدايات هولمز وحتى لقاءاته المذهلة مع غزاة من المريخ، تحتضن سلسلة \"المغامرات الإضافية\" أكثر القضايا تنوعًا وإثارة لأعظم محقق في العالم.", CategoryId = 3, ImageUrl = "/images/products/9789778200911.webp", Author = "ديڤيد ستيوارت ديڤيز", PublishDate = new DateTime(2021, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778200911", Pages = 208, Size = "14×20" },
            new { Id = 187, Name = "شيرلوك هولمز المحقق الملثم", Price = 270m, Stock = 10, Description = "يصل شيرلوك هولمز الشاب إلى لندن لبدء مسيرته كمحقق خاص، فيجذب انتباه المجرم البارع، البروفيسور جيمس مورياتي. يظهر الدكتور واتسون، العائد حديثًا من أفغانستان، الذي سيصنع التاريخي قريبًا كمرافق لهولمز.\nبأسلوب يجمع بين الصدمة والإثارة، يقدم ديفيد ستيوارت ديفيز رؤيته الجريئة لأسطورة هولمز، فيصبح عمله كلاسيكية حديثة في أدب الجريمة تتحدى كل التوقعات.\nوهكذا يعود الإبداع الخالد للسير كونان دويل في سلسلة جديدة من قصص التحقيق المصممة بذوق رفيع؛ من أولى أيام هولمز وحتى لقاءاته المذهلة مع غزاة المريخ، لتحتضن سلسلة \"المغامرات الإضافية\" أكثر القضايا تنوعًا وإثارة لأعظم محقق في العالم.", CategoryId = 3, ImageUrl = "/images/products/9789778200928.webp", Author = "ديڤيد ستيوارت ديڤيز", PublishDate = new DateTime(2021, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778200928", Pages = 302, Size = "14×20" },
            new { Id = 188, Name = "شيرلوك هولمز سجين فوق العادة", Price = 270m, Stock = 10, Description = "رواية جديدة من مؤلف أعمال هولمز الشهيرة مثل \"كنز الأبيض\" و\"المحقق المزور\".\nسُجِنَ ظلماً\nبعد استدعائه لمريض خيالي، يجد الدكتور واتسون نفسه معتقلاً بتهمة القتل المروع لسيدة مسنة. محبوسًا في سجن هولواي، ومع تكدس الأدلة ضده، يكمن أمل واتسون الوحيد في أن يكتشف شيرلوك هولمز هوية القاتل الحقيقي. ولكن عندما يظهر خطاب غامض يربطه بجرائم الابتزاز وعصابة شارع سيئة السمعة، يتوجب على هولمز أن يستخدم كل قدراته العقلية لإنقاذ صديقه من حبل المشنقة.", CategoryId = 3, ImageUrl = "/images/products/9789778201307.webp", Author = "ستيوارت دوجلاس", PublishDate = new DateTime(2023, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778201307", Pages = 342, Size = "14×20" },
            new { Id = 189, Name = "شيرلوك هولمز إرث جاك السفاح", Price = 270m, Stock = 10, Description = "تدفع زيارة رونالد تيمبل المنهارة شيرلوك هولمز والدكتور واتسون إلى الانطلاق في مطاردة طفل مخطوف.\nبدون مذكرة فدية ومع ارتباط غامض بأعلى مراتب المجتمع الفيكتوري، يتبين سريعًا أن الاختطاف ليس أمرًا عاديًا، وسرعان ما تتعرض حياة الرفاق للخطر.\nما هي الأصول الحقيقية لهذا الطفل؟ وما العلاقة التي تربطه بجرائم وايت تشابل التي وقعت قبل عقد من الزمان؟", CategoryId = 3, ImageUrl = "/images/products/9789778201222.webp", Author = "ديڤيد ستيوارت ديڤيز", PublishDate = new DateTime(2023, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778201222", Pages = 328, Size = "14×20" },
            new { Id = 190, Name = "دكستر - الحالم الغامض", Price = 300m, Stock = 10, Description = "تعرف على ديكستر مورغان، ذئب مهذب في ثوب الحملان؛ وسيم وساحر، لكن شيئًا من ماضيه جعله يعيش وفق قواعد مختلفة. إنه قاتل متسلسل يتبع قاعدة ذهبية واحدة تجعله محبوبًا للغاية: فهو يقتل الأشخاص السيئين فقط. كما أن عمله كخبير في تحليل بقع الدم في قسم شرطة ميامي يضعه في موقع مثالي لتحديد ضحاياه.\nلكن عندما تبدأ سلسلة من جرائم القتل الوحشية التي تحمل تشابهًا مذهلًا مع أسلوبه الخاص بالظهور، يجد ديكستر نفسه بين مديح مُبالغ فيه ورعب يغمره—هل هو خائف من نفسه أم من وحش آخر؟", CategoryId = 3, ImageUrl = "/images/products/9789778201086.webp", Author = "چيف ليندسي", PublishDate = new DateTime(2022, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778201086", Pages = 320, Size = "14×20" },
            new { Id = 191, Name = "الملكة الحمراء", Price = 370m, Stock = 10, Description = "هذا عالم مقسوم بالدم—أحمر أو فضي.\nالأحمر هم عامة الناس، يحكمهم نخبة فضية تتمتع بقوى خارقة تشبه قدرات الآلهة. ولدى \"مار بارو\"، الفتاة الحمراء البالغة من العمر سبعة عشر عامًا من منطقة \"ستيلتس\" الفقيرة، يبدو أن شيئًا لن يتغير أبدًا.\nحتى تجد نفسها تعمل في القصر الفضي. هنا، وبينما تحيط بها الأشخاص الذين تكرههم بشدة، تكتشف مار أن لديها قوة قاتلة خاصة بها، رغم دمها الأحمر، قوة تهدد بتدمير توازن السلطة.\nخوفًا من إمكانيات مار، يخفيها الفضيون في العلن، معلنين عنها أميرة فضية ضائعة منذ زمن بعيد، مخطوبة الآن لأمير فضي. ومع علمها أن أي خطأ قد يعني موتها، تعمل مار بصمت لمساعدة \"الحرس الأحمر\"، الجماعة المقاومة المتشددة، للإطاحة بالنظام الفضي.\nلكن هذا عالم من الخيانة والأكاذيب، وقد دخلت مار رقصة خطيرة—الأحمر ضد الفضيين، أمير ضد أمير، ومار ضد قلبها الخاص.", CategoryId = 2, ImageUrl = "/images/products/9789778201574.webp", Author = "ڤيكتوريا أڤيارد", PublishDate = new DateTime(2023, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778201574", Pages = 368, Size = "14×20" },
            new { Id = 192, Name = "السيف الزجاجي", Price = 400m, Stock = 10, Description = "إذا كان هناك ما تعرفه مار بارو جيدًا فهو اختلافها.\nدمها أحمر—لون العامة—لكن قدرتها الفضية، وهي القدرة على التحكم في البرق، حولتها إلى سلاح تحاول البلاط الملكي السيطرة عليه.\nيسميها العرش مستحيلةً، زائفةً، ولكن أثناء هروبها من \"مافن\"، الأمير—الصديق الذي خانها—تكشف مار شيئًا مذهلًا: إنها ليست الوحيدة من نوعها.\nمطاردة من قبل \"مافن\"، الذي تحول إلى ملك انتقامي، تنطلق مار للعثور على مجندين آخرين من المقاتلين ذوي الدم الأحمر والفضي للانضمام إلى النضال ضد ظلام مضطهديها.\nلكن مار تجد نفسها في طريق قاتل، معرضة لأن تصبح بالضبط الوحش الذي تحاول القضاء عليه.\nهل سينكسر قلبها تحت وطأة الأرواح التي يُفدى ثمنها ثمن الثورة؟ أم أن الخيانة والعداء قد قسياها إلى الأبد؟\nالجزء التالي المثير في سلسلة \"الملكة الحمراء\" يصعّد الصراع بين الجيش الثوري المتنامي والعالم المفصول بالدم، ويضع مار في مواجهة الظلام الذي نما في روحها.", CategoryId = 2, ImageUrl = "/images/products/9789778202359.webp", Author = "ڤيكتوريا أڤيارد", PublishDate = new DateTime(2024, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778202359", Pages = 432, Size = "14×20" },
            new { Id = 193, Name = "القاعدة", Price = 300m, Stock = 10, Description = "كانت الإمبراطورية المجرية تحكم بسلطة لا منازع لها لمدة اثني عشر ألف سنة. والآن، هي تحتضر.\nولكن فقط هاري سلداون، مبتكر علم \"السيكوهستوري\" الثوري، يستطيع أن يرى في المستقبل—عصرًا مظلمًا من الجهل، والهمجية، والحروب ستستمر لمدة ثلاثين ألف سنة.\nلحفظ المعرفة وإنقاذ البشرية، يجمع سلداون أفضل العقول في الإمبراطورية—علماء وباحثين—ويجمعهم على كوكب قاتم على أطراف المجرة ليكونوا منارة أمل للأجيال القادمة. ويسمي ملاذه \"القاعدة\".", CategoryId = 3, ImageUrl = "/images/products/9789778201062.webp", Author = "أيزاك أزيموف", PublishDate = new DateTime(2022, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778201062", Pages = 346, Size = "14×20" },
            new { Id = 194, Name = "القاعدة والامبراطورية", Price = 290m, Stock = 10, Description = "ما تزال القاعدة تواجه الأخطار في المستقبل البعيد، فبعد تغلبها على الممالك الأربعة وفرض سيطرتها على قطاع كبير من محيط المجرة الخارجي، يظهر خطر جنرالات الإمبراطورية الساعين إلى المجد وإعادة فرض سيطرة الإمبراطورية المحتضرة. رابطة جديدة من القاعدة تسمى \"رابطة التجار الأحرار\" تسعى لوقف خطر الجنرال بِل ريوز الذي يواجه القاعدة في صراعٍ مرير قرب حافة المجرة، عند الحدود التي تتلقي فيها الحضارة الجديدة بالبربرية القديمة.\nولكن بجانب خطر الجنرالات يظهر خطر جديد، عدو لم تواجه القاعدة مثله من قبل، يبدو وكأنه قادر على تحقيق كل شيء يريده، من مجرد شخص مجهول، إلى خطر يهدد بإنهاء القاعدة، وهذا الرجل يحمل اسمًا غريبًا، البغل، وبجانب اسمه الغريب يحمل سرًا غامضًا، وقد يتوقف على كشف هذا السر مصير القاعدة، إن لم يكن مصير المجرة بأسرها.", CategoryId = 2, ImageUrl = "/images/products/9789778201284.webp", Author = "أيزاك أزيموف", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778201284", Pages = 346, Size = "14×20" },
            new { Id = 195, Name = "جمهورية شارع الميتين", Price = 240m, Stock = 10, Description = "ست روايات في الكتاب تحكي عن أيام موحشة تهدد فيها الوطن بالفوضى وانهيار القواعد والأعراف والقوانين، فانحسرت عن أهله الحماية والطمأنينة والأمان، وأغرقهم الطوفان بمائه الأزرق السام، فلم يجدوا في حياتهم إلا أنفسهم بعجزها وضعفها، بتوحشها وخستها، فيظهر منهم مع بعضهم ومع أنفسهم أبغض وأقسى ما فيهم، لتتبدل معيشتهم إلى ما لم يتصوروه وما لم يجمح له خيالهم، وكأنهم في فيلم رعب مثلوه وأخرجوه جبرًا بلا إرادة وبلا قرار، فكانت هذه الروايات الست التي رسم الألم والدهشة أحداثها وحياة أبطالها، الألم مما يواجهون والدهشة مما يعيشون، وكأنه كابوس عجزوا عن الاستيقاظ منه والنجاة من رعبه.. روايات ست تصف أيامًا موحشة لا نتمنى أن نعيشها أبدًا ..", CategoryId = 1, ImageUrl = "/images/products/9789778598544.webp", Author = "أميره بهي الدين", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778598544", Pages = 342, Size = "14×20" },
            new { Id = 196, Name = "لماذا تخاويني العفاريت", Price = 330m, Stock = 10, Description = "الحب، العشق، الغرام، الوله.. هذا السحر والسر، السعادة والبؤس، الوهم والواقع، الكذب والحقيقة، هذا الإحساس الذي يداعب الأرواح والأفئدة والنفوس ويشاكس الخيال والوجدان، الإحساس الذي يرتقي بالمحبين لأسطع مباهج الفرحة، ويدنو بهم لأحزان البؤس الموحشة، هذا الإحساس المتفرد بكل تناقضاته، التلاقي والفراق، التنافر الاقتراب، الونس الوحشة، الفرحة التعاسة، ما الذي يصنعه الحب في حياة المحبين وكيف يرسم لهم مساراتٍ ودروبًا وكيف يسيرون فيها، وماذا تصنع لهم وفيهم وإلى أين تأخذهم أقدارهم بصحبة الحب وإلى أين تحط بهم..\nلماذا تخاويني العفاريت، كتاب يضم خمس روايات قصيرة عاش أبطالها وبطلاتها الحب بأوجهه المختلفة، وتبدلت أحوالهم وتناقضت؛ فمنهم من حلَّق حتى هوى، ومنهم من أقبل وابتعد، ومنهم من تعذب حتى تاب، ومنهم من ندم حين لا يجدي الندم.. خمس روايات قصيرة رسمت أقدار أبطالها وبطلاتها بفرشاة الحب بكل جموحه وتمرده وعطائه وغضبه، فصارت أقدارهم مثلما سنقرؤها وسارت حياتهم مثلما سنراها ونعيش منها في هذا الكتاب، لماذا تخاويني العفاريت..", CategoryId = 1, ImageUrl = "/images/products/9789778598537.webp", Author = "أميره بهي الدين", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778598537", Pages = 498, Size = "14×20" },
            new { Id = 197, Name = "على بوابة الليمان", Price = 300m, Stock = 10, Description = "لاختيار؛ هذا التحدي والاختبار الشاق والصعب، هو ما جمع بين بطلات الروايات الخمس في هذا الكتاب، وكأن كلَّ ما واجهه هؤلاء النسوة من صعوبات في الحياة ومشقتها لا يكفيهن، بل ويزيد عليه في لحظات فارقة ما ستلاقيه كل منهن من ضرورة الاختيار بين صعوبات وأخرى، بين التمرد والسكون، بين الحياة والموت.. الاختيار وعذاباته ومشقته قدرهن في الحياة التي ظنن يُسرها وسهولتها، لتكشف لهن في لحظات الضعف والانكسار عن ضرورة فتح صفحات جديدة وإغلاق أخرى، السير في دروب جديدة بمشقة اكتشاف المجهول والتعامل معه وهجر الدروب المألوفة بزيف الطمأنينة الهشة ووجعها.. ما الذي صادفته \"حياة\"، وما الذي عاشته \"زهرة\"، ما الذي فُرض علي \"فتنة\"، وما الذي قهر \"مهجة\"، وكيف صنعت \"منورة\" قدرها، ولماذا سكنت \"سميحة\" لمصيرها؟! أسئلة كثيرة تلاحقنا بها الروايات الخمس وبطلاتها لنفهم وندرك كيف كان الاختيار الذي عاشته كلٌّ منهن في رحلتها صعبًا مضنيًا وكيف دفعت كل منهن ثمنه؟!\n\nإنها حكايات النساء، حكايات الحياة، وحكاياتنا جميعًا.", CategoryId = 1, ImageUrl = "/images/products/9789778598575.webp", Author = "أميره بهي الدين", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778598575", Pages = 450, Size = "14×20" },
            new { Id = 198, Name = "لارنج ولوزة", Price = 240m, Stock = 10, Description = "ست روايات، وحضور فاعل طاغٍ لبطلاتهن، ما بين الحب والقهر والانتظار والأمل واليأس والتمني والخذلان.. مشاعر مختلفة متباينة، أحلام ضائعة وأمنيات.. بين كل هذا ومعه نعيش رحلة البطلات اللاتي قصصن علينا في هذا الكتاب ما عشنه وتمنينه وانتظرنه. لكل منهن عالمها المختلف وحلمها المتفرد ووجعها الحزين.. ما الذي يربط بينهن وبيننا، ما الذي يخطفنا لعوالمهن الصاخبة.. مشاعر كثيرة وأسئلة أكثر تنهمر علينا من حكاياتهن، نبتسم ونبكي ونتأمل حياتهن وحياتنا، نبحث عما يجمعنا بهن ويوحدنا معهن طوال الرحلة، إنها حكايات أصيلة ونبيلة ونشوى وصفا ومريم ولوزة.. وربما هي حكاياتنا أيضًا.", CategoryId = 1, ImageUrl = "/images/products/9789778598568.webp", Author = "أميره بهي الدين", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778598568", Pages = 374, Size = "14×20" },
            new { Id = 199, Name = "حيدر بن زرع النيل", Price = 180m, Stock = 10, Description = "أُمر غالب، مثل كثير من العمال، بالانتقال إلى بورسعيد للعمل لدى البريطانيين، استعدادًا لمعاركهم خلال الحرب العالمية الأولى. كافح غالب لتقرير مصير ابنته الوحيدة؛ فأين سيتركها؟ ومع من؟ وفي النهاية، لم يكن أمامه خيار سوى اصطحابها معه! ولكن ذلك حدث فقط بعد أن تحولت منصورة إلى \"منصور\"، ابن غالب النجار.", CategoryId = 7, ImageUrl = "/images/products/9789778201376.webp", Author = "أيمن رجب طاهر", PublishDate = new DateTime(2023, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778201376", Pages = 256, Size = "14×20" },
            new { Id = 200, Name = "أنسباي", Price = 270m, Stock = 10, Description = "تدور أحداث هذه الحكاية في عصر المماليك، وهي قصة رومانسية عن الظلم الاجتماعي والانتقام؛ إذ تهرب شابة مع والدها على متن سفينة، وتلد ولدًا يُدعى \"أنس\". انتزع الأمير المماليك الماكر الصبي من عائلته ورباه كأمير شوارسي، دون أن يعرف أصله، في عالم جديد. هل سيرث الصبي القوة والثروة؟ أم سيثأر لعائلته ولكل المصريين المضطهدين؟", CategoryId = 7, ImageUrl = "/images/products/9789778200959.webp", Author = "أيمن رجب طاهر", PublishDate = new DateTime(2021, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778200959", Pages = 424, Size = "14×20" },
            new { Id = 201, Name = "ليل زوارة", Price = 160m, Stock = 10, Description = "رحلة جديدة وسرد اجتماعي يأخذنا إلى عالم الهجرة غير الشرعية—مقامرة خطيرة تحمل في طياتها دمارًا يفوق الأمل. في هذه المخاطرة، يراهن المهاجر على أغلى ما يملك: حياته. هاربًا من واقع مليء بالمشاكل وفقدان الحقوق، يخوض المخاطرة على أمل الوصول إلى بر الأمان وتحقيق أحلام العمل والثروة. لكن، هل هذا هو الحل حقًا؟\nنعيش خلف الكواليس هذه الرحلة من خلال عيون طارق، الشاب من أبنوب بأسيوط، الذي رغم تخرجه من الجامعة يجد صعوبة في الحصول على عمل مناسب. وفي مواجهة الإخفاقات المتكررة، قرر الهجرة؛ فنسافر معه من الإسكندرية إلى زوارة في ليبيا عبر مراحل متعددة حتى نصل إلى المحطة قبل الأخيرة لهذه المغامرة المليئة بالمخاطر.", CategoryId = 7, ImageUrl = "/images/products/9789778200461.webp", Author = "أيمن رجب طاهر", PublishDate = new DateTime(2018, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778200461", Pages = 222, Size = "14×20" },
            new { Id = 202, Name = "الجيل الثالث", Price = 250m, Stock = 10, Description = "\"من أجلِ هذا المكان الذي نقف فيه الآن، خُضنا حروبًا، ونسجنا مؤامراتٍ، وشوهنا التاريخي والحقيقةِ ذاتها ليختفي صنيعنا، ونعود إلى الظلال التي منها نشأنا، وإليها ننتمي.. دولٌ قامت وسقطت، وملوكٌ تولوا وقُتِلوا، وبلادٌ كاملة احتُلَّت وفَنَت تطلعًا إلى السر الأعظم، وبحثًا عنه.. عن الإجابة الكبرى..\nمن أجل هذه اللحظة، وانتظارًا لها، بدأنا رحلة دامت قرونًا طويلة.. منذ فجر التاريخي، وما قبل المسيح.. منذ ما هو قبل كل شيء.. كل هذا من أجل هذه الأسطورة التي يعمل من أجلها تنظيم المصدقون الحقيقيون منذ بداية الزمان..\nأسطورة المدينة المقدسة، التي يختفي فيها مفتاح الكون، وأعظم أسرار البشر..\"\n____\nما الذي يمكن أن يحدث لو صارت للإنسان قوة الآلهة، وكيف يمكن أن يتغير العالم نتيجةً لذلك؟", CategoryId = 2, ImageUrl = "/images/products/9789778200652.webp", Author = "محمود علام", PublishDate = new DateTime(2020, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778200652", Pages = 398, Size = "14×20" },
            new { Id = 203, Name = "خلف حافة الكون", Price = 150m, Stock = 10, Description = "هو كتاب علمي فلسفي ، وهو يمر من خلال صفحاته على ظواهر غامضة وألغاز علمية ومعضلات وأسرار فلسفية واجهت الجنس البشري طوال وجوده على الأرض، تتعلق كلها بالماهية الحقيقية للكون والعالم الذي نعيش فيه، وكنه الأسرار التي تختفي بعيدًا عن متناولهم خلف ستار الواقع ذاته.. الكتاب ينقسم إلى أحد عشر مقالًا مسلسلًا يتناولون موضوعات متنوعة تنقسم ما بين الفيزياء النظرية والتكنولوجيا والطب والغرائبيات وعلوم الظواهر الخارقة للطبيعة.. مواضيع متنوعة وغريبة فعلًا، لا يربط بينها سوى أن جميعها جديد تمامًا على المجتمع العربي عمومًا، وعن ثقافته التي لا تهتم في المعتاد بأشياء كهذه ..", CategoryId = 8, ImageUrl = "/images/products/9789778201000.webp", Author = "محمود علام", PublishDate = new DateTime(2021, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778201000", Pages = 200, Size = "14×20" },
            new { Id = 204, Name = "الله لا يرمي النرد", Price = 180m, Stock = 10, Description = "كلما تفكرت في تلك الكلمة اكتشفت أنها عبقرية بشكل غير عادى.. عبقرية لدرجة أنها تصلح للرد على أي سؤال لا تجد له إجابة.. أى سؤال في أي زمن، وفي أي مكان.. فأحيانًا، كثرة الأسئلة التي لاتجد لها إجابة في عقلك يمكنها أن تقودك للإلحاد لو كنت ضعيف النفس أو لا تملك الإيمان الكافي للبحث عن الإجابات.. وهذا ما كاد أن يحدث معي أنا نفسي..\nالله لايرمى النرد، وبالمثل؛ لاشئ في الكون خلق عبثًا.. ليس معنى أننا لا نفهم الغرض من وجود الكون وكيفية خلقه أنه قد خلق عبثًا وبلا مغزى.. كلا بالطبع.. عقولنا دومًا ما كانت قاصرة عن فهم كيفية تفكير الإله، ولماذا خلق كل شئ.. لماذا خلق البشر والكون..\nتلك هي القضية العبثية.. كلما تقدم العلم، كلما زادت الأسئلة واكتشفت في قرارة نفسك أنه لا جواب هنالك.. كل ما يمكنك فعله هو التأمل، والتفكير ومحاولة الإستيعاب، فالأدلة موجودة في كل مكان، لكن العقول هي التي تأبى التصديق..\nتلك هي الحقيقة المؤسفة.. قبولها نضج وذكاء، ورفضها حماقة وضيق أفق.. ولكن هؤلاء يفضلون أن يكونوا حمقى على أن يكونوا بشرًا ضعفاء.. يفضلون التسليم بقوانين الإحتمالات والصدفة، وينسون أن تواجدهم في هذه الحياة، وموقعهم في هذا الكون العظيم، لا يمكن أن يكون صدفة أبدًا..\nوأن الله، أبدًا؛ لا يلعب النرد..", CategoryId = 8, ImageUrl = "/images/products/9789778201079.webp", Author = "محمود علام", PublishDate = new DateTime(2022, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778201079", Pages = 246, Size = "14×20" },
            new { Id = 205, Name = "حفيف صندل", Price = 120m, Stock = 10, Description = "مجموعة \"حفيف صندل\" هي عمل أدبي يضم 30 قصة قصيرة للكاتب المصري أحمد الخميسي.\nالمجموعة تتسم بتنوع موضوعاتها وغنى أفكارها، حيث ستجد بين صفحاتها قصصًا عن الحب، وأخرى تمس الواقع السياسي، إلى جانب القصص الساخرة وغيرها من الموضوعات المتعددة.\nمعظم القصص مكتوبة بأسلوب مميز، وتترك أثرًا واضحًا في النفس", CategoryId = 1, ImageUrl = "/images/products/9789778202236.webp", Author = "أحمد الخميسي", PublishDate = new DateTime(2024, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778202236", Pages = 120, Size = "14×20" },
            new { Id = 206, Name = "قلب على ضفاف الدانوب", Price = 240m, Stock = 10, Description = "تسرد الرواية رحلات المترجم والرحّالة سليمان، الذي بدأ مسيرته في أراضي الدولة العثمانية في القرن السادس عشر، مدفوعًا برغبة في الانتقام. قضى أكثر من ثلاثين عامًا يتنقّل بين الأقاليم الأوروبية التابعة للإمبراطورية العثمانية، خلال عهد السلطان سليمان القانوني، تلك الحقبة التي نادرًا ما يتم التطرق إليها في السرد التاريخي، رغم ما حفلت به من أحداث وتحوّلات.", CategoryId = 7, ImageUrl = "/images/products/9789778201178.webp", Author = "محمد آدم", PublishDate = new DateTime(2022, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778201178", Pages = 352, Size = "14×20" },
            new { Id = 207, Name = "قلادة مردوخ", Price = 270m, Stock = 10, Description = "تدور هذه الرواية حول الرحلة التاريخية الطويلة لقلادة بابلية قديمة، يقال إنها ملعونة، تطارد كل من يرتديها، وتفضي به في النهاية إلى حتفه. من الملك البابلي الشهير حمورابي إلى الرئيس الأمريكي جون ف. كينيدي، لم تنجُ روحٌ لبستها من مصيرها المشؤوم.", CategoryId = 7, ImageUrl = "/images/products/9789778200423.webp", Author = "أحمد سعد الدين", PublishDate = new DateTime(2017, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778200423", Pages = 398, Size = "14×20" },
            new { Id = 208, Name = "أرض الغربان", Price = 120m, Stock = 10, Description = "تروي الرواية حكاية شاب يُدعى فارس، يعيش مع والديه في مدينة بحرية تقع خارج حدود الزمن، مدينة لا تشبه أي مدينة حديثة. تعتمد في معيشتها على البحر، وسكانها لا يتعاملون بالنقود، بل يبادلون البحر بأثمن ما يملكون مقابل خيراته. في هذه المدينة، تُقدَّر المعرفة ويُحتفى بالقراءة، ويُعرَف عمر كل فرد من لون قميصه. أما القمر، فيتوسّط سماءهم، لكنه لا يبدو للجميع بالشكل نفسه: يراه البعض ناصع البياض، وآخرون حالك السواد، وغيرهم بلون أحمر متوهّج، وكأن القمر مرآة تعكس باطن كل شخص وتكشف مكنون روحه.\n\nورغم اختلاف أنماط العيش والعادات في هذه المدينة عن المدن الحديثة، تبقى سمة واحدة لا يستطيعون الفكاك منها: ظلّ الفقر الذي يُخيّم على الجميع.\n\nوبجوار هذه المدينة البحرية، تقوم \"مدينة الظلام\"، مكان مغمور في عتمة لا تُخترق، يبعث في نفوس من يدخله رهبة لا توصف. الانتقال إليها قرار صعب، لا يُتخذ إلا مقابل تضحية عظيمة. خريطتها تتغير من شخص إلى آخر، فلا يتفق اثنان على وصفها. هي المدينة التي \"يدفع العقل الإنسان نحوها، لكن الحكيم لا يذهب إليها.\"\n\nأما فارس، ذلك الشاب التائه بين قناعاته وأنانيته، فيحمل في قلبه حنقًا على كل شيء، ولا سيما البحر. يشعر أن البحر يُغدق كنوزه على من لا يستحق، بينما يحرمه هو مما يشتهي، فلا يمنحه سوى أوراق ممزقة وأشياء بالية في شباكه، كلما تطلع إلى رزق أو أمل. ومع كل خيبة، تتعمق مراراته، ويشتد توقه إلى الثروة والسلطة والتحكم، حتى يبدأ بخسارة أشياء ظن يومًا أنها ثابتة في حياته.\n\nتطرح الرواية سؤالًا جوهريًا:\nهل سينتصر رضا فارس على أنانيته؟\nهل سيستفيق قبل فوات الأوان، أم أن الجشع سيكون مصيره الأخير؟", CategoryId = 2, ImageUrl = "/images/products/9789778201116.webp", Author = "أحمد عصام", PublishDate = new DateTime(2022, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778201116", Pages = 168, Size = "14×20" },
            new { Id = 209, Name = "البساط الفيروزي", Price = 215m, Stock = 10, Description = "لفت نظري منمنمةٌ فارسية ضخمة، تشغل مساحة واسعة من الجدار المقابل لمكتبه. كانت عبارة عن بساطٍ منسوجٍ في كاشان، مطرّزٍ بأوراقٍ نباتية وأزهار. بدا البساط بلون فيروزي، كأنه محيطٌ يرتدي فستانًا من الزهور الزرقاء. تتوسطه صورة شيخ كثّ الشعر، أبيضه، يجلس في ظل شجرة عملاقة، وخلفه جدول ماءٍ تحوم حوله طيور ملوّنة.\n\nكان الشيخ شاخص البصر إلى السماء، رافعًا يده اليمنى كما لو كان يتضرع بالدعاء، بينما تمسك يده اليسرى كأسًا.\n\nوقد ذُيِّل البساط بعبارة مكتوبة بخطٍ فارسيٍ واضح:\n\n\"لوّنْ البساطَ بالخمرِ إنْ أمركَ شيخُ المجوس،\nفالشيخُ العارفُ هو الأعلمُ بمسالكِ المنزل.\"", CategoryId = 1, ImageUrl = "/images/products/9789778201147.webp", Author = "أحمد الزناتي", PublishDate = new DateTime(2022, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778201147", Pages = 288, Size = "14×20" },
            new { Id = 210, Name = "إبن الصلصال", Price = 215m, Stock = 10, Description = "يحدث أَنِّي أرغب فِي قول شَيْء مَا لذاتي خصوصًا، تأتي الرياح وتأخذ أفكاري بعيدًا عني وترميها فِي بحر النوتات الشاردة، ها أنا أحمل جسدًا وَهَذَا الجسد بحمل ندوبًا وَهَذِه الندوب تحمل ذكرياتٍ، وَهَذِه الذكريات أليمة، صور من الدم والنار والعبث والقهر والفقر والبراءة، ها أنا أحمل جسدًا أَوْ يحملني جسد مطبع بملصقات لأفلام قديمة كَمَا عَلَى واجهة سينما الصحراء ، أريد أن أعيش ملثما حَتَّى لا تدركني المساءات الحزينة بعد اليوم، أنا من أصفياء المواجع والمراثي، لا أريد أن أموت الآن، مَا زلت أريد اختبار الفرح إن كان يليق بِي. إِنَّهُ يليق بِي. لقد عشت حياة هادئة جدًّا، لا شيء يعكر صفوها غَيْر بعض القلق اليومي والأرق الَّذِي يزعجني كُلّ ليلة. هَذَا الجسد المكابر الَّذِي سنَّ لنفسه طريقًا أخرى وبدأ يأكل بعضه. يَقُول الطبيب إن بعض الخلايا تأكل الأخرى. الأمر غريب. أنا آكل نفسي. رموشي تنغلق عَلَى أَيَّام عشتها وأنا أراهن عَلَى جودتها. صنعت لنفسي عالمًا جميلًا، لا أحد يَسْتَطِيع أن ينكر ذَلِكَ.", CategoryId = 1, ImageUrl = "/images/products/9789778201154.webp", Author = "السعيد الخيز", PublishDate = new DateTime(2022, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778201154", Pages = 288, Size = "14×20" },
            new { Id = 211, Name = "الزيارة", Price = 150m, Stock = 10, Description = "أتذكّر ملامح أمي، ويكفيني أن أستحضر صورتها حتى تهبّ إلى روحي رؤى دافئة، محبّبة، من زمن لم أعشه يومًا — زمن تعرفه الأحلام، لكنه غريب عن حياتي المحدودة، تلك التي لا أستطيع فيها سوى لمس الأشياء والناس. أنادي بأسماء سرعان ما أنساها، كأنها لم تكن، ثم أتيه في ذهولٍ يشبه السكر، لا أدري أين أنا، ولا ما الذي ضاع مني.", CategoryId = 1, ImageUrl = "/images/products/9789778200133.webp", Author = "عمرو العادلي", PublishDate = new DateTime(2020, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778200133", Pages = 208, Size = "14×20" },
            new { Id = 212, Name = "سهم غرب", Price = 120m, Stock = 10, Description = "في هذه الرواية النفسية الاجتماعية، تنسج الكاتبة ضحى صلاح حكاية مؤلمة لفتاة شابة عانت لسنوات من القهر وسوء المعاملة، حتى وجدت نفسها في مواجهة مصير مأساوي يعتصر القلب. ومن خلال عيون \"آروى\" — الفتاة التي تخلى عنها كل من أحبت — نستكشف عوالم الفقد القاسي، والوحدة العميقة التي تخلّفها الخيبات.", CategoryId = 4, ImageUrl = "/images/products/9789776376366.webp", Author = "ضحى صلاح", PublishDate = new DateTime(2016, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789776376366", Pages = 134, Size = "14×20" },
            new { Id = 213, Name = "حائط غاندى", Price = 120m, Stock = 10, Description = "في هذه المجموعة التى تضم 22 قصة تظهر الوجوه المتعددة للحب والغيرة واللوعة والفقدان، مع التركيز على قضايا المرأة ومعاناتها. إضافة إلى وجوه الموت، مع استنطاق التكنولوجيا بداية من التواصل الاجتماعي وحتى أدوات القتل، فتبرز الحاجة لغاندي وحمائمه: «رسالة السلام»، مع اجتراح المسكوت عنه دون فجاجة.", CategoryId = 1, ImageUrl = "/images/products/9789778200096.webp", Author = "عزة رشاد", PublishDate = new DateTime(2017, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778200096", Pages = 158, Size = "14×20" },
            new { Id = 214, Name = "أنا وأنت", Price = 120m, Stock = 10, Description = "بكِ. أناولك الأكواب. لا تأخذينها من يدي. لا تضعينها قرب الحوض. أظل واقفًا خلفكِ أخفق مضطربًا من الشريان الذي فى رقبتك. أطبع قبلاتي على أذنكِ الصغيرة الدقيقة. أرتدي ملابسي لأتجه إلى عملي. أنتِ لن ترافقيني حتى باب الشقة. ستظلين جالسة على المقعد بنظرة شاردة. أرجع متأخرًا في المساء ممتلئا بغرامي بك. نتناول العشاء، أنا وأنتِ بقلق ومحبة وعزلة مؤلمة. نتنشق رائحة الخبز الساخن فوق المنضدة. ذكريات في طريقها إلى النوم تتقلب على السرير. ينتهى يوم طويل جعلنا جزءًا من ذكرياته. يخطر لي أن المخيف في الموت هو الوحدة. مسيرة المرء بمفرده في ذلك الوادي. ذلك لن يخيفنا لأننا معًا. أنا وأنتِ. لأنه كانت لنا لحظات مشبعة بالغرام والعذوبة، بالهواء الذي يتدفق من الشرفة بلون المساء مؤرجحًا أطراف الستارة البيضاء.\nأتملى وجهك بحب وعمق ويأس في حجرة النوم. تمدين بصرك من فوق كتفي إلى صوان الملابس. تهبطين برأسك إلى الوسادة. تطفئين المصباح الصغير. يظل قلبي متيمًا بكِ وفيه أمل لا ينتهي. فقط لو تقولين لي مَن ِمِنا الذي مات ولم يعد يرى الآخر؟", CategoryId = 1, ImageUrl = "/images/products/9789776376830.webp", Author = "أحمد الخميسي", PublishDate = new DateTime(2015, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789776376830", Pages = 168, Size = "14×20" },
            new { Id = 215, Name = "وصارت القاهرة", Price = 290m, Stock = 10, Description = "تدور الأحداث في القرن الرابع الهجري (العاشر الميلادي)، تُسلّط الضوء على مِصر في العصر الفاطمي، في عهد الخليفة \"المُعِزّ لدين الله الفاطمي\"، وتصوّر الحياة الاجتماعية والسياسية وقتئذ، كما تُبرز قوة الدولة داخليًّا وخارجيًّا، وكيف أحكمت السيطرة بقبضة مِن حديد على مقاليد الأمور في ديار مِصر والمغرب والشام، كما تتناول الأحداث معاناة المجتمع المِصري بكل أطيافه بسبب ممارسات أصحاب المذهب الإسماعيلي (مذهب الفاطميين).\nومن الشخصيات المهمة في الأحداث؛ الخليفة الفاطمي \"المُعِزّ لدين الله\"، الأمير \"تميم بن المُعِزّ\" (الشاعر)، القديس \"سمعان الخرّاز\"، الوزير \"جعفر بن الفرات\"، الوزير \"يعقوب بن كِلّس\"، البَطْرَك \"إبرام ابن زرعة السرياني\".", CategoryId = 7, ImageUrl = "/images/products/9789778202700.webp", Author = "محمد أدم", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778202700", Pages = 376, Size = "14×20" },
            new { Id = 216, Name = "برسكال", Price = 245m, Stock = 10, Description = "فى برسكال نحن بصدد \" حدوته كاملة\" نشارك فى إعادة صنعها وفقا لما يراه الراوى العليم فى الغالب الأعم، ومع ذلك يمكن للقارىء المحترف أن يتحمل اختيارات الروائى التى لا توافق رؤيته مقابل الرغبة في معرفة كيف انتهت الحدوتة إلى تحول عربجى شقى إلى ولى من أولياء الله الصالحين، تبدأ الرواية فى مقام \" سيدى عبد العاطى زمش \" القابض على اللجام، الضارب بالكرباج\"، وهى ألقاب تقدم لنا تفسيرا لكيفية \" أسطرة\" الأفعال العادية \" لعربجى مطرود من رحمة أسرته وكيف تتحول أفعاله العادية جدا بل والبائسة إلى كرامات، كل ذلك بفضل \" برسكال\" ابنته من زوجته \"غاية المنى إبليس\" التى اشتهرت بالسحر و بقدرات خارقة", CategoryId = 1, ImageUrl = "/images/products/9789778202830.webp", Author = "أحمد صبري ابوالفتوح", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778202830", Pages = 324, Size = "14×20" },
            new { Id = 217, Name = "ضهر الحوت", Price = 190m, Stock = 10, Description = "بدأ الحكايات على ضهر الحوت.. وتنتهي الحيوات\nوتنكشِف أسرار لا تعرِف الحدود بين الواقِع والخيال.\nلابُد من وجود بعض الأشياء الضروريَّة لكي توجَد جريمة قتل مثل أداة الجريمة، ومسرَح الجريمة، والجُثَّة، والقاتِل، والدافِع.\nحسنًا، الأمور مُعقَّدة هُنا قليلًا، فلدينا جريمة قتل يجِب حلِّها في أسرَع وقت مُمكِن، لكِن هُناك مُشكِلة صغيرة للغاية، لا توجَد أداة جريمة، ولا مسرَح جريمة، ولا جُثَّة طبعًا، وبالتالي لا قاتِل، ناهيك عن جهلنا بالدافِع.\nودورك، هو مُساعدة سعيد، فرد الأمن المسكين، على حل هذه الجريمة، قبل فوات الأوان! وقبل ضرَب القاتِل مرَّة أخرى! أو حدُوث ما هو أسوأ من ذلِك!", CategoryId = 3, ImageUrl = "/images/products/9789778202847.webp", Author = "محمد عصمت", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778202847", Pages = 214, Size = "14×20" },
            new { Id = 218, Name = "الصناديق المظلمة", Price = 220m, Stock = 10, Description = "\"كل ما تخشاه يكمن هناك... في أعماق الدارك ويب، وبداخل تلك الصناديق المشؤومة.\"\n\nعالم الانترنت، عالم مخيف، وأخطر طبقاته هي الانترنت المظلم، حيث كل شيء ممنوع، ومحرم، وخطر، متاح.\nولكن مالا تعرفونه، أن هناك طبقتين إضافيتين، لا يعلم عنهم إلا عدد لا يتجاوز أصابع اليد الواحدة في العالم كله، وتلك الطبقتان تحتويان على ما لا يخطر على بال كائن حي من أسرار وأهوال.\nمعا سنكتشف ما يوجد في (القبو).\nوفي الطابق الشبحي.\nوفي الصناديق المظلمة، التي يحتوي كل منها على لعنة رهيبة، أو سر مغلق، أو ....\nالكثير سنكتشفه معًا.", CategoryId = 9, ImageUrl = "/images/products/9789778202823.webp", Author = "عمرو المنوفي", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778202823", Pages = 272, Size = "14×20" },
            new { Id = 219, Name = "الخريف في بالم تاون", Price = 290m, Stock = 10, Description = "في يومه الأول للسكن في كومپاوند (پالم تاون) يجد ماهر اللص السابق جثة في بانيو الفيلا الخاصة به٬ كما أن تتم سرقة تمثال أثري يُمثل نصف ثروته من المنزل.\n\nفي الوقت نفسه الذي تتعرض فيه (ريم) الشابة الكفيفة من سكان الكومپاوند إلى مواجهة مع القاتل٬ وتتلقي تهديدًا بالقتل كي تتوقف٬ حتى يُقتل قطها وصديقها الوحيد شلبي٬ مما يدفعها إلى مواصلة البحث خلف القاتل.\n\nيبدأ كل من (ماهر) و(ريم) في البحث عن القاتل صاحب رمز (الفيل) كل على حدى في خطوط متوازية٬ وسط الأغنياء والممثلين وصفوة المجتمع٬ وكلما تتبع واحد منهم خيط أو توصل إلى دليل٬ زاد الأمر تعقيدًا.\n\nحتى تتكشف حقيقة القاتل٬ أو الرجل الذي يقع خلف جرائم القتل للدقة٬ والذي يقوم بخطوة ومجنونة ويغلق أبواب الكومپاوند ويقطع الاتصالات٬ آمرًا السكان بقتل بعضهم البعض في محاولة للنجاة.", CategoryId = 3, ImageUrl = "/images/products/9789778202625.webp", Author = "ميخائيل عماد", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778202625", Pages = 410, Size = "14×20" },
            new { Id = 220, Name = "صالون غريب", Price = 190m, Stock = 10, Description = "ما الغريب في صالون حلاقة به كرسي واحد، حلاق واحد وزبون واحد، لكنه بلا مرآة؟ ربما لأنه لم يكن هنا بالأمس، ولن يكون هنا غداً، ربما لأنني أشعر أنه… يطاردني.", CategoryId = 3, ImageUrl = "/images/products/9789778202632.webp", Author = "يحيى صفوت", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778202632", Pages = 240, Size = "14×20" },
            new { Id = 221, Name = "روحي فيك", Price = 200m, Stock = 10, Description = "مهندسة ديكور في منتصف العمر تتورط في جلسة تظنها لتحضير الأرواح لتشاهد فجأة حب عمرها! فتتغير شخصيتها شيئًا فشيًا حتى يناديها قصر في عزبة نيلية لترميمه وهناك تتغير أكثر فأكثر حتى تصبح شخصً أخر أقرب إلى سيدة هذا القصر القديم.\n\nفهل ما شاهدته هو الحقيقة؟\nأما أنها مريضة نفسية كما يدعي زوجها تهرب من حقيقة حادث أليم تحاول أن تتناساه.", CategoryId = 9, ImageUrl = "/images/products/9789778202618.webp", Author = "احمد عثمان", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778202618", Pages = 256, Size = "14×20" },
            new { Id = 222, Name = "معاش مبكر", Price = 190m, Stock = 10, Description = "رواية تغوص في عالم الإسكندرية لتكشف المسكوت عنه من مؤامرات ودسائس ومصائر عديدة لشخوص مأزومة..\nتبدو الشركة التي يعمل فيها الشخوص كأنها عالم مصغر لا يخلو من المفارقات العديدة التي تشكل روح هذا النص، وتقترب بقوة من عالم السطوة وراس المال..\nفي ستينيات القرن الماضي تولد هذه الاحداث، لكنها لا تقترب من الاحداث التي شكلت مفاصل الدولة في ذلك الوقت، إذ أن هم شخوصها الأساسي هو لقمة العيش، بحث مستمر ودؤوب ومصائر مختلفة وحكايات تتشكل وتتوالد من رحم المعاناة..", CategoryId = 1, ImageUrl = "/images/products/9789778202786.webp", Author = "مصطفي نصر", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778202786", Pages = 224, Size = "14×20" },
            new { Id = 223, Name = "اّلة الموتى", Price = 175m, Stock = 10, Description = "يتلقى يُوسُف وزين رسالة من صديقهما القديم آدم، يدعوهما إلى لقائه قريبًا. كانت الرسائل مفاجئة، ولكنها كانت خطافًا يمكنه أن ينشلهما من حياة محاصرة رتيبة. يطلب منهما آدم العمل معه على حلم قديم لهم. اختراع يعد بثورة ستغير مفهوم تحقيق العدالة، العدالة التي لم يجدوها في ماضيهم. آلة ستعطي الموتى فرصة أخيرة لكشف أسرارهم. لكن سيؤدي سعيهم إلى سلسلة من الفوضى حيث يجبرون على مواجهة تداعيات أفعالهم، ومطامع الآخرين، وعدو لم يكن بالحسبان. تتلاشى الحدود بين الصواب والخطأ، والحقيقة والخيال، حتى يتشوه مفهوم العدالة نفسه، ويجدون أنفسهم أمام معضلة أخلاقية.\nكم من التضحيات ستطالب بها الآلة من أجل الوصول للحقيقة وتحقيق العدالة، وهل هناك حدود للثمن الذي سيدفعون من أجلها؟\nسيواجه شخص آخر في زمن آخر المعضلة نفسها، حيث سيقوده لقاؤه بآلة الموتى إلى طريق مظلم محفوف بالمخاطر يهدد حياته، لكنه الوحيد الذي يمكنه تحقيق العدالة لضحية جريمة قتل مريبة.\nزمنان مختلفان، نفس الأسئلة، ولكن هل يصلون لنفس النهاية؟", CategoryId = 3, ImageUrl = "/images/products/9789778202762.webp", Author = "دينا هيكل", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778202762", Pages = 200, Size = "14×20" },
            new { Id = 224, Name = "اللعب مع الجبل", Price = 140m, Stock = 10, Description = "عشية عيد ميلاده تم تكليفه بمهمة عمل ميدانية اضطرته للخروج إلى العالم لأول مرة بعد سنواتٍ طوال قضاها بين جدران المكاتب وقاعات الاجتماعات.\nهناك في أقصى الجنوب سيتعين عليه أن يتسلق جبلًا شاهقًا قديم قِدَم الدهر، يتطير منه الأهالي وبتجنبون الحديث عنه.\nغير أن رحلة العمل التي اعتقد أنها ستحقق أحلامه تحولت إلى كابوس حين اكتشف أنه عاجز عن الهبوط من الجبل والعودة إلى عالمه، وأن من يحتجزه هناك بالأعلى هو الجبل الأسطوري المخيف نفسه (!) والذي كان ينتظره منذ أمدٍ بعيد كي يلعب معه لعبة خطرة خارج حدود أي منطق.\nفي منطقة غائمة بين اليقظة والحلم، الحقيقة والوهم، الوعي واللاوعي، تدور أحداث أخطر وأعظم مغامرة يمكن أن يخوضها الإنسان، حيث سيتعلم أن رحلته إلى العالم الخارجي الفسيح هى في حقيقتها رحلة إلى الداخل، في ظلمات عالمه الداخلي، حيث تكمن أسرار الذات المحجوبة عن الوعي بألف حجابٍ وحجاب", CategoryId = 9, ImageUrl = "/images/products/9789778202731.webp", Author = "شريف ثابت", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778202731", Pages = 138, Size = "14×20" },
            new { Id = 225, Name = "أبناء القيامة", Price = 190m, Stock = 10, Description = "في عالم دمرت الحرب النووية غلافه الجوي، حيث تشكل الشمس تهديدًا قاتلًا لكل الكائنات\nالحية في ظل صيف نووي قاسٍ، يعيش عمر في ملجأ آمن تحت الأرض. مدفوعًا بفضول لا\nيُشبع ورغبة ملحة في استكشاف العالم خارج الملجأ، يخرج إلى أطلال القاهرة ليجد نفسه عالقًا\nفي صراع شرس بين جماعات سرية تسعى للسيطرة على تكنولوجيا يمكنها أن تحدد مصير\nالبشرية. في رحلة محفوفة بالمخاطر، يكتشف عمر أسرارًا مذهلة حول ماضيه، ويواجه\nتحديات هائلة وخيانات محتملة. في قلب هذه الفوضى يدرك عمر أن عليه اتخاذ قرار مصيري\nقد يغير مستقبل البشرية إلى الأبد.", CategoryId = 2, ImageUrl = "/images/products/9789778202649.webp", Author = "احمد صلاح المهدي", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778202649", Pages = 242, Size = "14×20" },
            new { Id = 226, Name = "سرمدي", Price = 245m, Stock = 10, Description = "لوحةٌ مُرعبة ليس لا مثيل، تتحرّك أجزاءُها لتُنبأ باستيقاظ شرٍ قديم من سُباتٍ طويل ليسترجع مكانته على عرش الأرض. وإرثٌ ملعون ينحدر من سلالة تعود لعُمق التاريخ، هو خط الدفاع الأخير للجنس البشري. وبين هذا وذاك يقف (علاء)، لا يفقهُ شيئًا مما يدور من حوله سوى أن على عاتقه يقع الأمر برمته، فقط لأنه الوريث الوحيد لعائلةٍ حافظت على السر لمئات السنين ... والآن قد حان دوره ليُكمل المسيرة، أو يضع كلمة النهاية لهيمنة البشر على هذا الكوكب.", CategoryId = 9, ImageUrl = "/images/products/9789778202663.webp", Author = "محمد عبدالمحسن", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778202663", Pages = 306, Size = "14×20" },
            new { Id = 227, Name = "دوائر الساعي", Price = 130m, Stock = 10, Description = "تروي الرواية أربع قصص مترابطة تمتد عبر ثلاثة فصول، وهي قصص نُوح، ماريا، ليلى، والراوي.\n\nقصة نُوح:\nيعود الراوي إلى طفولة نُوح الساعي، حيث كانت حياته مليئة بالتنافس مع أخيه مراد، الذي كان المفضل لدى والدهما. منح الأب مراد اسمه ومهد له الطريق ليصبح طبيبًا ويرث لقبه وعيادته، بينما تُرك نُوح بعيدًا عن الاهتمام والتقدير.\n\nقصة ماريا:\nتخضع ماريا لثلاث جلسات علاجية مع الطبيبة النفسية نادين، حيث تعترف بمعاناتها من اكتئاب لا تستطيع الأدوية تهدئته. تحكي عن طفولتها التي عاشتها وسط والديها اللذين لم يحبا بعضهما ولم ينفصلا، مما جعلها تعيش في صراع دائم بينهما، وكأنها خيط ضعيف يتأرجح بين طرفين يحاول كل منهما شده وتمزيقه.\n\nقصة ليلى:\nتنتقل ليلى إلى بلدة صغيرة مع والدها جميل وأختها عزة، التي تعاني من متلازمة داون. يستأجر والدها متجرًا صغيرًا بجوار بورصة الساعي وشقة بسيطة بأثاث قديم. سرعان ما يصبح جميل أشهر صانع حلويات في الشارع، بينما تكبر ليلى وتقع في حب جارها مصطفى، الذي يعرّفها على عالم الكتب والقراءة. لكنه يغادر فجأة إلى القاهرة دون أن يودعها أو يشرح سبب رحيله.\n\nقصة الراوي:\nيرسل الراوي ثلاث رسائل إلى ناشره، يعبّر فيها عن اكتئابه ورغبته في التوقف عن الكتابة نهائيًا. يروي كيف كان يحمل حقيبته القديمة في رحلاته إلى القاهرة، بحثًا عن من يقرأ كلماته أو يدعمه، وكيف أصبحت شقته فارغة بعدما تركته زوجته، التي كانت تكره الورق، وابنته، التي لم يمنحها من وقته بقدر ما كان يمنح لشخصيات رواياته.\n\nقصص تتشابك بين الحب والفقد، بين الأحلام والخيبات، في عالم يملؤه الصراع والتحديات.", CategoryId = 1, ImageUrl = "/images/products/9789778202328.webp", Author = "أحمد عصام الدين", PublishDate = new DateTime(2024, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778202328", Pages = 152, Size = "14×20" },
            new { Id = 228, Name = "أثر اليعسوب", Price = 260m, Stock = 10, Description = "علاء مدبولي، الكاتب الشهير، يسافر إلى الإسكندرية هربًا من قصة حب فاشلة، وبحثًا عن فكرة جديدة لروايته القادمة. هناك، يتلقى دعوة غامضة من حارس مبنى الشقق المجهول (ميرتل)، الذي ظهر فجأة وأثار تساؤلات كثيرة بين أهل المدينة. بدافع الفضول، يقبل علاء الدعوة، آملاً أن يجد بين جدران المبنى قصة تستحق أن تُروى.\n\nخلال العشاء الأول، يكشف له مالك المبنى سرًّا مذهلاً: جميع سكانه مسافرون عبر الزمن من عام 1898، وهو عام مفقود من التاريخي. لقد جاءوا إلى الحاضر بناءً على نبوءة تؤكد أن علاء وحده قادر على إيقاف قاتل إنجليزي متسلسل قتل 12 فتاة شابة خلال أربع ليالٍ من ذلك العام المنسي. مهمته هي العودة إلى ذلك الزمن ومنع القاتل من ارتكاب جرائمه وإنقاذ ميرتل، ابنة مالك المبنى وأحد أقارب السكان.\n\nفي المقابل، سيُمنح علاء فرصة نادرة لتغيير حدث تاريخي واحد. يوافق على المهمة، مدفوعًا برغبته في العودة بالزمن ليس فقط لإنقاذ ميرتل، بل أيضًا للهروب من مصيره المحتوم وخيانة خطيبته إيمي، التي تركته.", CategoryId = 3, ImageUrl = "/images/products/9789778202342.webp", Author = "ميخائيل عماد", PublishDate = new DateTime(2024, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778202342", Pages = 368, Size = "14×20" },
            new { Id = 229, Name = "لعنة جانب التل", Price = 270m, Stock = 10, Description = "تدور أحداث الرواية في عالم خيالي يتمحور حول قرية تقع على جانب التل، ولذلك يُطلق عليها سكانها اسم \"جانب التل\". تحيط بها غابة شاسعة من الأشجار العملاقة تُعرف باسم \"غابة الظلال\"، ويؤمن أهل القرية بأنها نهاية العالم، وأنه لا يوجد شيء وراءها. في قلب القرية، توجد أطلال قديمة تحمل نقوشًا غامضة لم يتمكن أحد من فك رموزها.\n\nبطل الرواية شاب يُدعى بارسينو، وُلِد مصابًا بالمهق، فكان له شعر أبيض، وبشرة بيضاء، وعينان زرقاوان. بسبب مظهره المختلف، نبذه أهل القرية وأطلقوا عليه لقب \"طفل اللعنة\"، معتقدين أنه وُلِد دون بركة الشمس. فهم يؤمنون بأن الشمس والقمر والنور هم حُماة القرية من الظلام والمخاطر الكامنة في غابة الظلال.\n\nلا يجرؤ أحد على دخول الغابة سوى حطّاب عجوز يُدعى أوركين، الذي يجلب الحطب للقرية. ومن هنا، يقرر بارسينو، برفقة صديقه أكينو، اكتشاف سر هذا الحطّاب ومعرفة ما يخفيه عن الغابة الغامضة.", CategoryId = 2, ImageUrl = "/images/products/9789778202403.webp", Author = "أحمد صلاح المهدي", PublishDate = new DateTime(2024, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778202403", Pages = 396, Size = "14×20" },
            new { Id = 230, Name = "غواني الإسكندرية", Price = 140m, Stock = 10, Description = "تدور أحداث الرواية خلال فترة الاحتلال الإنجليزي، حيث تركز على أحياء معينة في الإسكندرية وما يجري داخلها، سواء تحت أعين الاحتلال أو بعيدًا عن رقابته، متضمنة أنشطة مشبوهة. تستعرض الرواية دور كل شخصية في تشكيل هذه الأحداث وتأثيرها على مجرى الأحداث داخل هذه الأحياء.\n\nيأخذنا الكاتب مصطفى نصر في رحلة داخل العالم الخفي للبغاء في الإسكندرية، كاشفًا عن الفساد العميق الذي يسري في أوصال المجتمع. يسلط الضوء على تواطؤ الساسة الذين حموا هذا الانحلال، ومعاناة أولئك الذين دفعتهم الأقدار إلى هذا المصير القاسي.\n\nورغم قسوة الأحداث وبؤس تفاصيلها، ينسج الكاتب حبكة مشوقة، تمزج بين شخصيات حقيقية من التاريخ وأخرى من خياله، ليخلق رواية تنبض بالحياة، تجمع بين الواقع والخيال في سردٍ ممتع ومؤثر.", CategoryId = 7, ImageUrl = "/images/products/9789778202380.webp", Author = "مصطفى نصر", PublishDate = new DateTime(2024, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778202380", Pages = 184, Size = "14×20" },
            new { Id = 231, Name = "البيانو الصغير", Price = 120m, Stock = 10, Description = "\"الفتي \"\" محمد \"\" وشهرته \"\"حمامه\"\" في الرابعة عشرة من عمره، موهوب موهبة استثنائية في لعب كرة القدم، ودائمًا ينظر للاعب الشهير \"\" محمد صلاح\"\" بأنه مثله الأعلى، ويتمني أن يصبح مثله لاعبًا شهيرًا وعالميًا، لكن بسبب فقره وفقر أسرته تفشل جميل محاولاته في الالتحاق بنادي شهير، لأن هذا يحتاج إلى نقود وعلاقات وهو لا يمتلكها.\nمن جهة أخري تفاجأ أسرة \"\" حمامة\"\" بقدوم المعلم \"\" أبو أيمن\"\" صاحب السبعين عامًا. وهو تاجر ثري يسكن بالحي وصاحب البيت الذي يسكنون فيه، ويطالب بالزواج من أخت حمامة \"\" وفاء\"\" ذات السبعة عشر عامًا، والتي تذاكر ليل نهار من أجل الحصول على الثانوية العامة ودخول كلية الطب.\nترفض الأسرة طلب المعلم أبو ايمن الغريب، إلا أنها تفاجأ بتهديده بطرد الأسرة من بيته لأنه يريد أن يهدم البيت ويقيم مكانه عمارة سكنية كبيرة، كما يطالب بالنقود – الكثيرة – التي اقترضتها منه الأم، منذ سفر زوجها إلى ليبيا للعمل هناك، واختفائه.\nيمهل المعلم أبو ايمن الأسرة شهرًا لسداد نقوده أو تقديم الكمبيالات للشرطة من أجل القبض على الأم.\nتشعر اسرة حمامة بالضياع، وتصمم الأم على حماية اسرتها مهما كلفها ذلك، فهي تعمل – بائعة خبز – من أجل سداد متطلبات أسرتها.\nيفكر الطفل حمامة كيف يساعد أسرته، ويخبر امه بانه يستطيع العمل على توك توك من أجل مساعدة الأسرة وسداد ديوان المعلم أبو ايمن، وكي يحمي أخته وفاء من هذا الرجل الغاشم الذي يريد ان يتزوجها وهي في عمر احفاده.\"", CategoryId = 1, ImageUrl = "/images/products/9789778201888.webp", Author = "محمد محمد مستجاب", PublishDate = new DateTime(2024, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778201888", Pages = 140, Size = "14×20" },
            new { Id = 232, Name = "تاريخ آخر للحزن", Price = 270m, Stock = 10, Description = "\"فى تلك الرواية «تاريخ آخر للحزن» يستخدم الكاتب العديد من التقنيات السردية المميزة والمبتكرة والشيقة ليصل بالقارئ إلى حالة نفسية معقدة، لا يمكن وصفها بسهولة هل هى المتعة أم الحزن أم الألم، خاصة وهو يتتبع مسار نحو أربعة أجيال فى قرية بسيطة هى نوسا البحر، بادئا بحدث يشابه السير الشعبية والبطولات الفردية النادرة التى يضحى فيها شخص أو شخصان من أجل حياة الجميع. هذا هو الحال بعد هزيمة عرابى وانتشار الإنجليز فى القرى والوسيات والأبعديات المختلفة لتصفية أسر الذين شاركوا فى جيش عرابى، من خلال قائمة يمتلكها القائد الإنجليزى، حرقوا قرى وأبادوا أهلها ودمروا العديد من الوسيات والأبعديات قبل أن يصلوا إلى نوسا البحر، التى كانت تعانى من أزمة حادة فى الغذاء لدرجة اضطرار الأهالى لأكل بقرة يقال إنها كانت ميتة. ثم يحتار الرأى بين الفرار من القرية وبين الاختباء حتى يمر عساكر الإنجليز، ويقرر الشيخ حسنين اللهفة وحلاوية زوجة فتح الله، والتى انتظرت عودة زوجها من جيش عرابى بلا جدوى. يتم التنكيل بهما وسحلهما وتعذيبهما ثم قتلهما بلا رحمة، لتترك حلاوية ابنها رضيعا يحصل على غذائه من كلبة.\nالأسرة الرئيسية فى الرواية هى أسرة إقطاعية «أسرة أرسلان» وعميدها عبد الباسط أرسلان، وهى عائلة تمتلك سرايا كبيرة وأبعديات فى نوسا البحر وما حولها، كما يمتلك أفرادها العديد من المقومات السلطوية والنفوذ، وإن كان هناك خلاف بين عبد الباسط أرسلان وإخوته إلا أن هذا الخلاف غالبا ما ينزوى جانبا ولا يظهر إلا كمبرر درامى لإحباط ابنه منجى أرسلان، المحامى الحقوقى، الذى يهيم عشقا بابنة عمه إلا أن عمه يرفض تزويجه من ابنته نظرا لميول «منجى» الناصرية، وغضب والده وأسرته من تلك الميول بعد أن تسبب عبد الناصر فى خسارة الأسرة الكثير من أملاكها، باعتبارها من كبار العائلات الإقطاعية فى المنصورة. فأصبح منجى بمثابة الابن الضال العاق الذى يفكر عكس اتجاه تفكير الأسرة، إنه الابن المتمرد الذى يدفع ثمن تمرده سنوات فى السجن بتهمة سياسية متنوعة.\n\"", CategoryId = 7, ImageUrl = "/images/products/9789778202373.webp", Author = "أحمد صبري ابوالفتوح", PublishDate = new DateTime(2024, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778202373", Pages = 376, Size = "14×20" },
            new { Id = 233, Name = "الغثاء", Price = 250m, Stock = 10, Description = "تتابع الرواية سلسلة من التفجيرات الإرهابية التي تنفذها جماعة إسلامية متطرفة في بريطانيا، لتقود إلى قرار صادم: نفي جميع المسلمين البريطانيين إلى جزيرة نائية محاطة بأسوار عالية. تُترك هذه الجماعة لتدير شؤونها بنفسها، لكن الجزيرة سرعان ما تغرق في الفوضى. بلا خدمات ولا قوانين، ومع تصاعد العنف، تتحول الجزيرة إلى مكان خطير تسيطر عليه العصابات والمجرمون، حيث يصبح البقاء للأقوى والأشد قسوة.", CategoryId = 2, ImageUrl = "/images/products/9789778201475.webp", Author = "أحمد صلاح سابق", PublishDate = new DateTime(2023, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778201475", Pages = 400, Size = "14×20" },
            new { Id = 234, Name = "وداعًا إرم", Price = 290m, Stock = 10, Description = "تأخذنا الرواية في رحلة تبدأ من قوم عاد ومدينة إرم المفقودة، حيث تعجّ الأرض بالآلهة المتعددة، والجن، والحروب، والظلم. في زمنٍ اختلطت فيه تقاليد البدو والحضر، يمرّ السرد بمنعطفات خطرة، وينتهي عند \"عيسى بن العبّاس\"، ليربط الماضي البعيد بلحظات مفصلية من التاريخ الإسلامي.\n\nنصل إلى \"إرم ذات العماد\" — أسطورة الجمال العربي، \"أتلانتس العرب\" — فنمشي بين جناتها، ونرى قصورها، ونلتقي بشعبها من الإنس والجن.", CategoryId = 7, ImageUrl = "/images/products/9789778201390.webp", Author = "مجيب الرحمن مدحت", PublishDate = new DateTime(2023, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778201390", Pages = 458, Size = "14×20" },
            new { Id = 235, Name = "قلب النصيري", Price = 180m, Stock = 10, Description = "في مزيج ساحر يجمع بين زمن الخلفاء والعصر الحديث، يقدم الكاتب حكاية آسرة ومفعمة بالإثارة.\n\nتبدأ الرواية بجريمة شنيعة يقترفها أحد الخلفاء، لتُشكّل لحظة الانطلاق لأحداث تمتد عبر الأجيال. ينتقل السرد لاحقًا إلى \"آدم النصيري\"، العائد إلى وطنه للمرة الأولى، حيث يغوص في إرث عائلته العريقة، كاشفًا بذلك ذكريات مطمورة طواها النسيان.\n\nبأسلوب سردي محكم، ينسج الكاتب مسارات الشخصيات ضمن دائرة واحدة، ليقدّم رواية مشوّقة تملؤها الغموض والتشويق، وتمسك بالقارئ حتى الصفحة الأخيرة.", CategoryId = 7, ImageUrl = "/images/products/9789776376874.webp", Author = "مجيب الرحمن مدحت", PublishDate = new DateTime(2016, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789776376874", Pages = 290, Size = "14×20" },
            new { Id = 236, Name = "مخطوطة بنيامين", Price = 220m, Stock = 10, Description = "مخطوطة بنيامين هي رواية تاريخية تتقاطع فيها إحداثيات الزمان والمكان، بدءًا من زمن سيدنا يعقوب وابنه بنيامين، الذي تُروى حكايته انطلاقًا من الجد الأكبر إبراهيم، أبو الأنبياء، وصولًا إلى يومنا هذا، حيث يرقد مقام بنيامين في حي الحيدان بمدينة الموصل، على ما يُعرف بـ\"الطريق الأحمر\".\n\nتبدأ الرحلة من مدينة أور، الواقعة على الضفة الغربية لنهر الفرات، في اللحظة التي بلغ فيها الأمر الإلهي ذروته في الكون، ودوّى نداء النبوّة، مرورًا بأطلال قُمران في الأردن عام 1947، حين عثر الراعي مجتبى، في بحثه عن إحدى عنزاته الضائعة، على مخطوطة مدفونة بين الصخور، لتنتهي عند الطريق الأحمر، حيث يسعى خالد الإكيابي إلى فكّ شيفرة مخطوطة بنيامين، سابرًا أغوار التاريخ، ومستكشفًا أسرارًا حُجبتها الرمال وطمستها الأزمنة.", CategoryId = 7, ImageUrl = "/images/products/9789778201383.webp", Author = "هدى أنور", PublishDate = new DateTime(2023, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778201383", Pages = 336, Size = "14×20" },
            new { Id = 237, Name = "أفيزيا", Price = 150m, Stock = 10, Description = "يعتز الفنان دومًا بتلك الرؤية من أعلى نقطة، حيث تنجلي التفاصيل وتتكشف الأسرار. فالوقوف في العلو يمنح فرصة أوسع للحُكم على المشهد بحياد تام. وفي لحظة عابرة، تقرر أن تشتري تذكرة ذهاب وإياب إلى عقول العابرين: ماذا يفعلون؟ من أين جاؤوا؟ وإلى أين يمضون؟\n\nوكانت المفاجأة أنني اكتشفت أننا جميعًا مصابون بحالة من الحُبسة الكلامية، نعجز عن التعبير عمّا يعتمل في داخلنا، كأن اللغة قد خذلتنا، أو أن الكلمات لم تعد تكفي.", CategoryId = 3, ImageUrl = "/images/products/9789778201550.webp", Author = "خالد زيدان", PublishDate = new DateTime(2023, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778201550", Pages = 226, Size = "14×20" },
            new { Id = 238, Name = "بنت صهيون", Price = 150m, Stock = 10, Description = "يروي لنا الدكتور ماكلين، من خلال مذكراته، رحلته عبر الأمة العبرية، وغوصه في أعماق المجتمع الإسرائيلي وأسراره؛ ذلك المزيج الغريب من الشعوب والثقافات، وتأثيره العميق على العرب القاطنين في المناطق القريبة، بل وداخل الأراضي المحتلة نفسها.", CategoryId = 7, ImageUrl = "/images/products/9789776376694.webp", Author = "شريف شعبان", PublishDate = new DateTime(2015, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789776376694", Pages = 238, Size = "14×20" },
            new { Id = 239, Name = "قطف الجمر", Price = 170m, Stock = 10, Description = "4 شبان مغاربة في رحلة بحث عن أنفسهم ! في الممر المظلم الذي يربط ساحة الاندلس بالرحبة القديمة ومسجد سيدي وسيدي بمدينة تارودانت، يقع منزل سي علال. وفي الطابق السفلي الرطب يوجد بيت الطلاب، أبطال الرواية. بيت يتكون من غرف ثلاثة تأوي جدرانها أربعة شباب، تلتقي الأجساد في تلك البقعة وتهيم الأرواح في أفلاكها، كل روح في عالمها الخاص.", CategoryId = 1, ImageUrl = "/images/products/9789778200355.webp", Author = "السعيد الخيز", PublishDate = new DateTime(2017, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778200355", Pages = 240, Size = "14×20" },
            new { Id = 240, Name = "نيتروجلسرين", Price = 215m, Stock = 10, Description = "حسين توفيق صبي صغير يعيش في حي المعادي ويكون فرقة من الصبية لاغتيال جنود الإحتلال البريطاني في مصر قبل أن يلتقي بأنور السادات ضابط الجيش ليعيد تعليمه مبادئ الوطنية، ويدفعه لاغتيال ساسة مصريين.\n ينجح التنظيم الصغير في اغتيال أمين عثمان، ويتم تهريب توفيق إلى سوريا ليؤسس تنظيما آخرا يحاول من خلاله اغتيال رئيس الدولة. ويُحكم عليه بالاعدام وينجو بسبب انقلاب ضد نظام الحكم السوري ويعود لمصر فيحاول اغتيال الرئيس عبد الناصر ويقبض عليه ليحكم عليه بالسجن الأبدي. وهناك يكتشف أنه كان دائما أداة لقوى أخرى استخدمته باسم الوطنية.", CategoryId = 7, ImageUrl = "/images/products/9789778200508.webp", Author = "مصطفي عبيد", PublishDate = new DateTime(2018, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778200508", Pages = 310, Size = "14×20" },
            new { Id = 241, Name = "روزيتا", Price = 120m, Stock = 10, Description = "عرف النيل مع رفاقه، وشق الثوب الذي دثّرته به أمه في نسجها الحكايات عن عروس البحر خانقة الصبية، رآها في أحلامه تصاحبه في جزيرة الذهب وتعرّفه على ملوك البحار، عندما ترك جسده للموج الهادئ وأرخاه في حضن موجة تسلمه لأخرى، سبح إلى البر الشرقي وعاد من دون تعب، بالذات في أيام التحاريق قبل الفيضان، جلو صفحة النيل وهدوؤها يُغري بالسباحة كأنه الهدوء الذي يسبق العاصفة، يأتي الفيضان مجتاحًا الشوارع مغرقًا إياها بالطمي والمياه المحمَرّة، تنحسر من الشوارع شيئًا فشيئًا بعدما غسلها النيل وأطعم السردين.\nعمل بالقفاصة، ينهي يوميته قبل المغرب، تأخذه قدماه إلى النيل، يتأمل الصيادين يفردون الشباك بين المراكب، ينزلون طوايل السردين المفضض، ألحقه أبوه بخياط بلدي عند زاوية العقادين، يتركه ويتجه إلى النيل، ألح على أبيه أن يلحقه صيادًا عند أحد معارفه، اشترط عليه أبوه ألا يسمع شكوى منه بعد ذلك، يستقبل النيل قبل طلوع الشمس، يطرح الشِّباك، يلمه بمساعدة زملائه، يهب الوهّاب البلطي والبوري الصايم صيد الليل.", CategoryId = 1, ImageUrl = "/images/products/9789776376915.webp", Author = "عزة دياب", PublishDate = new DateTime(2016, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789776376915", Pages = 160, Size = "14×20" },
            new { Id = 242, Name = "قلوبنا غلف", Price = 270m, Stock = 10, Description = "أفكر ونحن نعبر تلك الأزقة، كلّ البيوت الحجرية التي تعود لأزمنة مُتأصلّة لجدودنا، بعضُ سكانها أُخرج عُنوة وتمّ احتكارها لليهود الذين أتوا بحماية بريطانيا، صُودِرت بعض الشوارع بأكملها، نحن لسنا ضدّ عيشهم هنا، بل ضدّ طردهم لنا ونهب دورنا... خلف كلّ بابٍ خشبيّ قصة، أرواح مُنهكة من الشوق لأيّامٍ ماضية، يعيشون على الماضي، ساعاتهم ضُبِطت على إيقاع الذكريات، ينتظرون أن يعود نبض الحياة لعقاربها لكنّهم لا يجاهدون بشيء لبلوغ ذلك... الإيمان غلّف قلوبهم جاعلًا الذكريات تعيش بكلّ زوايا بيوتهم، وتحت أضواء شوارعهم، حتى بين حجارة طرق شوارعهم، والتي قد تضمّ زهرةً مُتعطّشةً للحياة، استماتت لترى ضوء القدس، قبل أن تدعسها مركبة عسكرية لليهود، يؤمنون أنّ هذا عابر.", CategoryId = 7, ImageUrl = "/images/products/9789778200140.webp", Author = "إيناس بن مبارك", PublishDate = new DateTime(2020, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778200140", Pages = 392, Size = "14×20" },
            new { Id = 243, Name = "فى بلاط الخليفة", Price = 140m, Stock = 10, Description = "تحرك عمر بآلية تامّة، يتفحّص وجوه المسلمين، وعيناه تركزان على وجه النبي - صلى الله عليه وسلم - الذي قام بفعل لم يتوقعه أحد. فجأة، ودون أي مقدمات، جذبه النبي جذبة عنيفة.\n\nوفي لحظة نادرة، انهار جسد عمر.\n\nكاد حمزة يتحرك.. بل كاد أبو بكر ينطق.. ولقد حاول علي أن يكسر الصمت، إلا أن كل ذلك لم يحدث. وكأن الأفعال والأقوال ذابت في صمت رهيب.\n\nخيم سكون تام على الجميع، كأن الزمن توقف للحظة لا تتكرر إلا نادرًا في كل جيل، قبل أن يقول النبي صلى الله عليه وسلم: «أما آن يا عمر؟»\n\nتأمل عمر وجه الرسول - صلى الله عليه وسلم - وبهدوء غريب انفرجت شفتاه ليقول: «بلى، آن يا رسول الله.. أشهد أن لا إله إلا الله، وأن محمداً رسول الله.»\n\nانساب الصوت العذب إلى الآذان، ولربما عجزت العقول عن استيعابه، فيما ارتفعت أعناق أهل مكة نحو دار الأرقم بن أبي الأرقم، حيث وُلد فجر جديد، وولدت معه أسطورة عربية، هذه المرة، واسمها عمر.\n\nعمر بن الخطاب.", CategoryId = 1, ImageUrl = "/images/products/9789776376717.webp", Author = "محمد ابراهيم", PublishDate = new DateTime(2015, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789776376717", Pages = 198, Size = "14×20" },
            new { Id = 244, Name = "أوديف", Price = 200m, Stock = 10, Description = "أنا (أوديف) أو (عوديف) إن لم تشعر بريبة ما تجاه نطق الأخير.\nأحب أسمائي جميعها. يدعونني (كورفوس) باللاتينية ـ (كوراكوس) باليونانية، الإسبان يدعونني (ماريا) بينما يسميني الإنجليز (كراو).\nأما عني، فمثلما أخبرتك أم لم أخبرك بعد؟ أفضل لو ناديتني أوديف، أكثر أسمائي أصالة وقربا إلى نفسي وتناغما معي.\nحسنا، لن أطيل عليك الحكي. جئت لأقص عليك حكاية مسلية.\nهل تحب الحكايا؟!\nالناس جميعا تحبها –أعتقد-.\nأعدك بأن تكون حكاياي اليوم مختلفة. ستتسلل عبر أطرافك، وتثير في جسدك رعدة.\nربما ستكون سمعتها من قبل، لكن بطريقة مغايرة.\nأرى ألّا بأس بأن تسمعها اليوم من فم أوديف.\nأراك ترتجف! لا تحب أن تطيل النظر إلى وجهي؟ لكن لا تنكر أن صوتي يجتذبك إلى قصتي. رخيم ويتسلل إلى أعماق روحك القلقة المتعبة.\nيقولون إن التاريخ يكتبه المنتصر، لم لا نسمح بأن يكتبه المهزوم مرة؟\nهل سيراودك الشك تجاه صدق حكايتي؟ لا ألومك. لا أسعى لأن تصدقني. أعلم أنني –ربما- لا أوحي بالثقة. لكن لتعلم بأن أوديف العجوز لا يحب الكذب.\nربما لا أخبرك بالحقيقة كلها، ربما أخفي عنك شطرها. ربما لا أخبرك بالحقيقة أصلا! لكن أعدك بأن أطرح أسئلة طازجة ستدفعك للسؤال وإطالة الفكر.\nحسنا. دعنا من الثرثرة. لم لا نتابع الحكي؟", CategoryId = 1, ImageUrl = "/images/products/9789778200676.webp", Author = "محمد إبراهيم", PublishDate = new DateTime(2020, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778200676", Pages = 278, Size = "14×20" },
            new { Id = 245, Name = "سفر التيه", Price = 140m, Stock = 10, Description = "تدور الرواية عن  ثلاثة شباب  قاموابرحلة إلى جنوب سيناء لتلقى دورة\nدورة طبية فى الصيدلة يحاضرفيها واحدمن ألمع الأطباء الشباب فى هذا المجال وختاما\nلتلك الدورة قرورا صعودأحدالجبال لمشاهدة أول ضوء للصباح من أعلى قمته\nإلاأنهم تعرضوا لخديعة ما على يد دليل سيناوى معدوم الضمير،الذى عاد وتركهم\nعرضة للهلاك", CategoryId = 1, ImageUrl = "/images/products/9789778200065.webp", Author = "محمد إبراهيم", PublishDate = new DateTime(2017, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778200065", Pages = 180, Size = "14×20" },
            new { Id = 246, Name = "أنــين", Price = 230m, Stock = 10, Description = "وتدور الرواية حول د.حازم أبو زيد الطبيب النفسى الشهير، الذى يقيم فى مدينة سياحية فاخرة بالإسكندرية وبسرد حالة نفسية غريبة وردت إليه من مهندس أحمد خشبة، ذلك المهندس الثرى الذى تربى على البذخ والترف، درس الهندسة فى بريطانيا على يد اشتراكى عتيق علّمه أنه كمهندس لابد أن يطبِّق ما تعلّمه من دينه وهندسته على الفقراء، ولقد حاول ذلك بالفعل ولكنه اصطدم بالروتين الحكومى العقيم الذى منعه من إكمال حلمه.", CategoryId = 2, ImageUrl = "/images/products/9789776376243.webp", Author = "شريف ثابت", PublishDate = new DateTime(2015, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789776376243", Pages = 332, Size = "14×20" },
            new { Id = 247, Name = "البعث", Price = 300m, Stock = 10, Description = ".فى الجزء الأخير من عالم أفضل يبَلغَ الصراع محطته الأخيرة . الثورة تسرى كالنار فى الهشيم، تُحقِق الانتصارات المظاهرات،والفوضى تضرب المُدُن. العالم مُنهَك  ،مُثخنة بالجراح بعد أن نالَت منها الثورة ما نالَتEgy- Nergyو ولكنها لم تنتهِ بعد. مازال أخطر أسلحتها موجودا ً .وعلى وَشك النزول لحلبة المعركة الليلة، تشتبك أشباح الماضى مع أطياف الحاضر فى جولة أخيرة  .من أجل المُستقبل الليلة، تنتهى الحرب، وتُطوَى صفحة القديم من أجل بَعث  جديد .الليلة، يتحدد مصير العالم.. فإما كابوس جديد، وإما عالم أفضل", CategoryId = 2, ImageUrl = "/images/products/9789778200072.webp", Author = "شريف ثابت", PublishDate = new DateTime(2017, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778200072", Pages = 444, Size = "14×20" },
            new { Id = 248, Name = "إيلات", Price = 300m, Stock = 10, Description = "تتحدث الرواية عن النبوءة النبوية برفع القرآن الكريم من المصاحف، لا تتخذ الحدث ذاته كمحور للرواية بل محاولة الانسان بعد اختفاء النص المقدس للبحث عن طريقة لبث منظومته الاخلاقية وايقاف المد المتطرف المنادي بمعارك نهاية الزمان، تنقسم الرواية على راويتين: كاتب مؤمن بالكتابة، وقاتل حكومي يقدس الاوامر والنصوص، وما بينهما تتردد شخصيات الرواية لتحقق أمل الانسان في ايجاد عالم هاديء بلا حروب ولا تكفير.", CategoryId = 2, ImageUrl = "/images/products/9789778200485.webp", Author = "ماجد شيحة", PublishDate = new DateTime(2018, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778200485", Pages = 434, Size = "14×20" },
            new { Id = 249, Name = "المعبر", Price = 200m, Stock = 10, Description = "تتحدث الرواية عن النبوءة النبوية برفع القرآن الكريم من المصاحف، لا تتخذ الحدث ذاته كمحور للرواية بل محاولة الانسان بعد اختفاء النص المقدس للبحث عن طريقة لبث منظومته الاخلاقية وايقاف المد المتطرف المنادي بمعارك نهاية الزمان، تنقسم الرواية على راويتين: كاتب مؤمن بالكتابة، وقاتل حكومي يقدس الاوامر والنصوص، وما بينهما تتردد شخصيات الرواية لتحقق أمل الانسان في ايجاد عالم هاديء بلا حروب ولا تكفير.", CategoryId = 2, ImageUrl = "/images/products/9789778200591.webp", Author = "ماجد شيحة", PublishDate = new DateTime(2019, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778200591", Pages = 284, Size = "14×20" },
            new { Id = 250, Name = "المختلف", Price = 180m, Stock = 10, Description = "امرأة من حلم وخسارات وعلاقات لا تستقيم. تعاندها الظروف بين الضغط الأسري والغربة والوسواس والقلق والعمل في تدريس الفلسفة. تلتقي ستيفان، رجل غني وعميق ومختلف عن كل الرجال. لانه لا يعرف نفسه بسبب تخبطه في التوحد في صغره. بين المواجهة والهروب من الامكنة التي تستعصي عن الحياة تعيش وهي تكتب في ذهنها عبر استعارات ومجازات واحداث يومية رواية تسميها \"المختلف\" . انتهت بها المسارات في مدينة براغ بعد ان قررت الهجرة والتبخر على الطريقة اليابانية.", CategoryId = 6, ImageUrl = "/images/products/9789778200560.webp", Author = "فاطمة الزهراء الرياض", PublishDate = new DateTime(2019, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778200560", Pages = 258, Size = "14×20" },
            new { Id = 251, Name = "تراجيم", Price = 120m, Stock = 10, Description = "الكتابة ايضاً كانت لها كمشرط الجراحّ ويجب تعقيم شعورك بالصدق كى تفتح جرحا ما  ...\nعليك كذلك أن تكون دقيقاً ومرهفاً بما يكفى  لتحس بالجثة الممدة امام رحمتك ..", CategoryId = 4, ImageUrl = "/images/products/9789776376748.webp", Author = "فاطمة الزهراء الرياض", PublishDate = new DateTime(2015, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789776376748", Pages = 174, Size = "14×20" },
            new { Id = 252, Name = "رجل يكره الأحذية", Price = 120m, Stock = 10, Description = "الشاب السوداني الأسمر النحيل (مفتاح)، وامرأته الروسية البيضاء الضخمة (ناتاشا)، جنبًا إلى جنب مع أكثر رجل في العالم يكره ارتداء الأحذية، ينطلقون في مغامرة مجنونة وغريبة الأطوار: بحثًا عن شيء لا يتسع الغلاف الخلفي لذكره، طبعًا!\n\nهي رحلة عبثية وفانتازية تأخذك إلى عالم لا ندري حقًا إن كان موجودًا، في مطاردة كيان لا نعرف حقًا إن كان حيًا، وسط شخصيات لا ندري إن كان هناك من يشبههم في الواقع!\n\nروايتك كانت مفاجأة حقيقية لي، فقد كتبت بأسلوب جميل وساخر، تحمل في طياتها نفسًا شبابيًا واضحًا، وكتابة حداثية تسعى لتثبت وجودها.\n\n— أمير تاج السر»", CategoryId = 1, ImageUrl = "/images/products/9789776376649.webp", Author = "حسن الحلبى", PublishDate = new DateTime(2015, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789776376649", Pages = 166, Size = "14×20" },
            new { Id = 253, Name = "مستحيلة", Price = 120m, Stock = 10, Description = "تبتسم بهدوء كنجمة ..\nأشهدُ أنِّي منذ زمن مسكونٍ بالبُعد ؛ لم أر مثل هذه الابتسامة !\nلماذا يبدو وجهها الشَّبيه بالسَّحاب هذا ؛ قريباً من وجه (سندس) ؟!\nليست المسألة مسألة تشابه في الوجه أو الملامح أو العينين ؛ هناك شيء أعمق ، وكأنّ روحها تشبه روح ( سندس ) ؛ حقًّا ..\nأسحبُ نفساً عميقاً من السِّيجارة :\n ما اسمكِ ؟!", CategoryId = 4, ImageUrl = "/images/products/9789776376526.webp", Author = "حسن الحلبى", PublishDate = new DateTime(2014, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789776376526", Pages = 168, Size = "14×20" },
            new { Id = 254, Name = "متسع للرقص", Price = 180m, Stock = 10, Description = "تدور في إطار اجتماعي نفسي ورومانسي، من خلال عرض علاقة معقدة لشقيقتين، تتعرضان للفقد في مقتبل العمر من ثم أزمات نفسية وحياتية متتالية. الرواية تتناول اضطراب القلق المزمن والرهاب الاجتماعي، وتتعرض للعلاج النفسي بالرقص والحركة. كما تتبنى أفكار إيجابية كملاحقة الشغف والتحقق، وتجاوز التجارب السيئة وتصحيح المسار والمضي قدما.", CategoryId = 6, ImageUrl = "/images/products/9789778200843.webp", Author = "هدي عبد المنعم", PublishDate = new DateTime(2021, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778200843", Pages = 264, Size = "14×20" },
            new { Id = 255, Name = "هــاجس", Price = 180m, Stock = 10, Description = "تتعرض «هاجس» للأوهام التى تغلب على النفس وتشغل حيز وهمى من الفراغ، فتدع أصحابها فى متاهات بلا بداية أو نهاية.\nحين تنغلق نفسك على هاجس ، تغمس روحك فيه ، وتقصر أفكارك وتمنياتك وتمحور حياتك عليه، ظناً أن غيره ليس له من سبيل إليك، إلى نفسك وحلمك، رغم أنه أبعد ما يكون عنك، لا تنتمى إليه، إنما ينتمى هو إلى توجسك، تخوفك، ضعفك، قصر بصيرتك، استسهالك، استسلامك، احتياج ملح منك، ورغبة مغلوطة أمارة بالسوء.", CategoryId = 6, ImageUrl = "/images/products/9789776376410.webp", Author = "هدى عبد المنعم", PublishDate = new DateTime(2014, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789776376410", Pages = 266, Size = "14×20" },
            new { Id = 256, Name = "أثر الفراشة", Price = 180m, Stock = 10, Description = "الحوادث حين تأتي لا تحجز موعدًا؛ تأتي وحسب.. طوال الوقت، لكن ثمة حدث في لحظة ما قد يغير مسار حياة شخص بأكملها!\nأقرب المقربين مُتَهَم بالأذية، الشخص الذي من شأنه ألا يسمح بشيء سيء يحدث لها؛ جربتْ ما كان بمقدوره حين يصد أحدهم في وجهه؛ ضربها في مقتل، قالبًا عالمها رأسًا على عقب!\nهذا النوع من المشاعر لا يمكن التهاون فيه؛ فإما يشد العضد وإما يهد الحيل؛ فلو فعل غريب فعلته بها لما استغرقت في نسيانها عُشر ثانية، أو لعلها ستحتاج إلى مزيد من الوقت، لكن لن يكون لها أثر الفراشة على حياتها!", CategoryId = 4, ImageUrl = "/images/products/9789778200034.webp", Author = "هدى عبد المنعم", PublishDate = new DateTime(2017, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778200034", Pages = 262, Size = "14×20" },
            new { Id = 257, Name = "صاحبة المولد", Price = 120m, Stock = 10, Description = "بعيدا عن الضجيج، مازالت تغلق على نفسها باب غرفتها.\nتجلس أمام المرآة كما اعتادت دائما أن تفعل منذ أن كانت صغيرة.\nتحدق في عينيها. كثيرا ما انتظرت أن تبعث روح في الانعكاس، وأن تقوم صورتها المنعكسة بمحادثتها.\nانعكاس شخصي له القدرة على فك العقد وإتاحة الفرصة أمام صاحبه ليرمي كل ما أنهكه لسنوات، وكل ما حمله في صدره دون أن يستطيع البوح ولو لمرة واحدة كما ينبغي لمن ينبغي.\nلعل بوح النفس أمام النفس هو ما حلم به الكثير منا. أن تتجسد النفس فجأة فيستطيع المرء التعري وبسط الحقائق دون خوف أو خجل.", CategoryId = 4, ImageUrl = "/images/products/9789778200362.webp", Author = "محمد الحموي", PublishDate = new DateTime(2017, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778200362", Pages = 172, Size = "14×20" },
            new { Id = 258, Name = "الزحف نحو السماء", Price = 140m, Stock = 10, Description = "اد ليسأل هل هذا هو الطريق الذي يبحث عنه ؟ أو الذي أُرسِلَ ليبحث عنه ؟ أهو الطريق الحقيقي المباشر ؟ أقصر الطرق إلى الله ؟ هل فعلاً وصل أبو الحكم إلى الله ؟ كان يريد جواباً لا لينقله للعجوز فقط لكنه يريد جواباً لنفسه التي كُشِفَ عنها غطاء ركودها و اشتعل حراكها و غليانها، و ظهرت تساؤلاتها الواضحة تسعى دون تراجع للحصول على ما يشبعها.\n تحول فجأة إلى مراقب منفصل غير منغمس أبداً فيما ذاب فيه الرجال حين انسابوا مع الكلمات التي يقولها المنشد أيّاً كانت حتى لو كانت كفراً صريحاً دون أن يعوا ما الذي يقوله، كان يستطيع ملاحظة ذوبانهم و ميلان رؤوسهم المتشابه مهما تراوحت معاني الكلمات، لم يكونوا ليعوا شيئاً مما يقرأ على مسامعهم أو هذا ما اعتقده", CategoryId = 1, ImageUrl = "/images/products/9789776376472.webp", Author = "محمد الحموى", PublishDate = new DateTime(2014, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789776376472", Pages = 194, Size = "14×20" },
            new { Id = 259, Name = "أخر لحظات الإزعاج", Price = 120m, Stock = 10, Description = "أكثر ما يزعجني، هو كل ما مررت به في حياتي.\nأكثر ما يزعجني، هو التحدث أمام أشخاصٍ لا أعرفهم.\nأكثر ما يزعجني، أن يطَّلع هؤلاءُ الأشخاصِ على أعماقي بكل ما فيها.\nأكثر ما يزعجني، أن أموت.\nأكثر ما يزعجني، أن يجتمع كل ما سبق في مشهد واحد.\nإذًا.. فلنضع هذا على ذلك ونقلب قليلاً، وأنتحر بعدها، لتكون آخر لحظات الإزعاج.", CategoryId = 2, ImageUrl = "/images/products/9789778200041.webp", Author = "وائل عبد الرحمن", PublishDate = new DateTime(2017, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778200041", Pages = 174, Size = "14×20" },
            new { Id = 260, Name = "راس شيطان", Price = 150m, Stock = 10, Description = "الـنـدم سكّين بارد يسلخك حيا، دون امتلاك مميزات البنج، أو رفاهية الموت هربا..\n\nوالدبّ الملطّخ بدم صاحبه، تبددت ابتسامته، وتدلى فكه، وجحظت عيناه..\n\nوساراماجو حدّثنا أن الفوضى هي نظام، لم تُفك شفرته بعد..\n\nوأفعالك واختياراتك؛ ما بين كش ملك وبين تقهقر، تعزف السيمفونيات بين لحن ونشاز..\n\nوالمكان يرسمه الإنسان، والزمان هو لغز الألغاز..\n\nوترجمة كل ما سبق تجدها هنا بالداخل..\nفي راس شيطان", CategoryId = 1, ImageUrl = "/images/products/9789776376670.webp", Author = "وائل عبد الرحمن", PublishDate = new DateTime(2015, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789776376670", Pages = 224, Size = "14×20" },
            new { Id = 261, Name = "تكاد تضىء", Price = 200m, Stock = 10, Description = "كانت جبينه الذي قبلته باردًا كالثلج، لامعًا كشمعة ناعمة، ثم اجتاحها شوق جعلها تقبل وجهه كله.\n\nمررت شفتيها على جسده كعاشق تاقت روحه إلى الامتلاء بالحب.\n\nكان كل ما فيها يستشعر جسده، تفكّر كم مرة عانق التراب دون أن يذوب فيه حقًا، جسدُه الذي احتضن الزنزانات رغم ما قد تظنه القلوب من أن الزنزانة تحوي ولا تحتوي.\n\nجسده الذي لم يذرف الدموع إلا بالدم، ولم ينطق إلا بلغة الصبر والصمت؛ جسد ذلك العصي الذي فقد ماء طفله، لكنه بقي يحلم أن يكون له... يداها تتحسسان طريق شفتيها قبل أن تمرا على اللَّون الأبيض البارد، يداها المرتجفتان الخائفتان من أن تخدش فيه شيئًا، يداها اللتان كانتا حلمه لو كان حيًا.\n\nظلت تتحدث أمام جثته كما لو كان يقظًا، دون أن تبكي، مدفوعة للحكي لا للبكاء، فلبكاء وقت لم يحن بعد.", CategoryId = 7, ImageUrl = "/images/products/9789776376762.webp", Author = "سامية عياش", PublishDate = new DateTime(2015, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789776376762", Pages = 278, Size = "14×20" },
            new { Id = 262, Name = "بعد النهاية", Price = 140m, Stock = 10, Description = "فى ليلة ممطرة تصاعد الخلاف بين غادة وزوجها بعد تناولها عدة أقراص مهدئة وتتطور الخلاف الى شجار فقتلته دون قصد بسكين..  فلم تجد ما تفعله غير أن تهرول بملابسه المتسخة بدماء زوجها إلى جارها أدهم بعد منتصف الليل\nساعدها أدهم فى التخلص من جثة زوجها...\nوجعلها تقيم مع جارتهالعجوز حتى تهدأ أعصابها لأنها كانت تخاف من العودة لشقتها\nلكن جاره  القاطن فى الشقة العلوية شاهده وهو يضع الجثة فى السيارة  وتتبعه وعرف ما فعله  وظن اانه القاتل بالاتفاق مع زوجة القتيل  وهدده بفضح آمره", CategoryId = 3, ImageUrl = "/images/products/9789778200942.webp", Author = "محمد كامل", PublishDate = new DateTime(2021, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778200942", Pages = 214, Size = "14×20" },
            new { Id = 263, Name = "خريف المحروسة", Price = 230m, Stock = 10, Description = "عن شكل الحياة فى مصر وملامح البلد فى الفترة من أخر  الحملة الفرنسيه مروراً بفترة حكم، محمد على وصعوده للحكم وحتى الطاعون الذى أصاب البلاد عام 1835. من خلال حياة أسرة من الجد للابن والأحفاد. الجد الذى كان مشارك للمقاومة ضد الحملة الفرنسية.ومشاركة بطل الرواية فى الحرب الوهابية، ومعاناته خلالها، ومعاناته من مرض الطاعون الذى اجتاح البلاد والعباد بعد عودته بسنوات، نهاية بوفاة ابنته الصغرى به فى أخر الرواية، مروراً بالتدابير التى اتخذتها الدولة للسيطرة على الوضع.ومعاناة البلاد وعامة الناس من ظروف البلاد فى تلك الفترات.. وطريقة حياتهم.. والقهر الذى مروا به وسط أفراحهم وأحزانهم", CategoryId = 7, ImageUrl = "/images/products/9789778200515.webp", Author = "محمد كامل", PublishDate = new DateTime(2018, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778200515", Pages = 318, Size = "14×20" },
            new { Id = 264, Name = "أفندار", Price = 240m, Stock = 10, Description = "اشتهرت قبل أن أعتاد على اسم الولادة بفاتنة المجالس، حتى ولم أكن قد أكملت العاشرة من عمري، فجمالي الطاغي كما سمّاه جلالة الملك فؤاد الأول في المرة الأولى التي عرضني فيها أبي على بصر معاليه، كان سرًّا من أسرار شعوري المبكر بنشوة غريبة تغزو روحي كلما خلَبت عيون من حولي منحنيات جسدي أو التواءات شعري المنسدل.\nلسنوات ظننت انها نشوة السعادة الابدية.\nغير انها لم تكن الا سكرة من سكرات الموت المحتوم.", CategoryId = 7, ImageUrl = "/images/products/9789778200409.webp", Author = "محمد فوزى عبد الرحيم", PublishDate = new DateTime(2017, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778200409", Pages = 378, Size = "14×20" },
            new { Id = 265, Name = "إذا زاد الود", Price = 150m, Stock = 10, Description = "لا بأس حبيبي.. هذا العالم لا يستحقّ شيئا من دموع أو أسى.\nهذا العالم الذي يرسل بالشمس وأسراب الطيور كلّ صباح ويسترجعها كلّ مساء، ولا كأنّه ينطوي على كلّ هذا الكمّ من المعاناة.. أحكام مؤبّدة بالسواد والسكوت، والصمت والسّكون، والفقر والجنون، وأسقام وشجون، وهذا جميل بلا تعب، وذاك قبيح بلا ذنب، وهذا سعيد وكلّه شرّ، وذاك شقي وجلّه خير، وهذا يعيش حتّى يموت، وذاك يموت قبل الحياة..\nلقد فهمت هذا العالم مذ تفطّنت إلى فوائد الخلّ وأضرار السّكر.. نحن لسنا هنا كي نستمتع بالحلاوة، نحن هنا كي نتجرّع المرارة، فإن أطعنا الحلو وعصينا المرّ، فإنّ العاقبة لن تسرّ.\nلذا ما عاد يمضّني بعد هذا الفهم شيء، ولا حتّى أنّنا افترقنا.. وبخصوص أنّي أمسيتُ على يقين، أنّه اللقاء.. دنا من أن يحين..", CategoryId = 4, ImageUrl = "/images/products/9789778200119.webp", Author = "مريم سبع", PublishDate = new DateTime(2017, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778200119", Pages = 232, Size = "14×20" },
            new { Id = 266, Name = "سجين الوهم", Price = 240m, Stock = 10, Description = "ثورة متأججة ، قينمو فكر فقر ، ويتناسى الفقير والمحتاج الثورة عندما تأتيه الثروة ، فيغض الطرف عما يقترفه هو أو الآخرون من أخطاء ، يرصد وقائع السقوط ولكن لا يبالي ، حتى يقع بين براثن الظلم والقهر ، فيقام عليه الحد على الملأ رغم عدم ارتكابه للخطيئة ، يتذكر بأنه ثائر ، تعود إليه ملامح الثورة القديمة ولكن مشبعة بالخوف ، هل يستطيع أن يصمد ويجاري فكر الثوار أم يتوه في زحام الجماهير المحتشدة ؟ ولا يستطيع أحد أن يعرف موطأ قدمه ، فأين ذهب الثائر ؟", CategoryId = 1, ImageUrl = "/images/products/9789778200584.webp", Author = "طنطاوي عبد الحميد طنطاوي", PublishDate = new DateTime(2019, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778200584", Pages = 352, Size = "14×20" },
            new { Id = 267, Name = "شق الجبل", Price = 215m, Stock = 10, Description = "عندما يداعب الأمل المحرومين ...تنهمر سيول الخير والنعمة في أموال لا حصر لها ، هل يستطيع المال تغيير الصورة القاتمة ؟ هل الثراء نعمة أم نقمة ؟ لا ثقافة ولا فكر ولكن جها متفشِ يستطيع أن يشوه الصور الجميلة التي يمكن للإنسان رسمها عبر مخيلته وإبداعه ، يتباعد الأهل وتثار نزعات طائفية مقيتة ، الكل يتخوف حتى بين من جمعت بينهم أواصر القريى وصلة الرحم ... حكاية قرية أصابها وابل الخير", CategoryId = 1, ImageUrl = "/images/products/9789778200393.webp", Author = "طنطاوي عبد الحميد طنطاوي", PublishDate = new DateTime(2017, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778200393", Pages = 310, Size = "14×20" },
            new { Id = 268, Name = "اتاتورك", Price = 150m, Stock = 10, Description = "حين كان عدنان يتخذ من حديقة أتاتورك في أسطنبول رفيقا دون البشر يلجأ إليه لينسى الألم، الذي لم يبرح قلبه منذ سالت دماء حبيبته على صدره، لم يكن يتخيل أن الحديقة ذاتها سترسل له طوق النجاة من أجل حياة جديدة، ينبت فيها الجمال من بين قسوة الحروب ولوعة الفراق.", CategoryId = 4, ImageUrl = "/images/products/9789778200454.webp", Author = "مى سلام", PublishDate = new DateTime(2018, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778200454", Pages = 244, Size = "14×20" },
            new { Id = 269, Name = "ريسال", Price = 215m, Stock = 10, Description = "سيسألونك كيف تعرفُ أن حبًّا ليس حب، أو كيف تُمتحَنُ القلوبُ قبيل مفترقِ الطريق، قل هل لَهَوتَ بذاتِ بحرٍ بين بعضِ الأصدقاء،هل حين غابَ وجدْتَ روحَكَ بين منتصفِ الحريق، قل هل مشيتَ على الصحاري وفي انتقامٍ للعطش، ثم اكتشفْتَ بذكرك اسمٍ أن قلبَك في الغريق، يا قتلَ روحٍ دون حبٍّ تمضي بالعمرِ القصير، يا دفنَ نفسٍ في الحكايةِ حين ينطفئُ البريق، يا أيها العشاقُ تبًّا سوف تُختطَفُ الحياة، ولسوف نمضي بذاتِ نهرٍ؛ إذ نلاقي جفافَ ريق، قُل مَن سيدفعُ بالمقابلِ حين يندلعُ المشيب، قل من يعوِّضُ حين نكبرُ بعضَ عمرٍ قد أُريق، اليومَ هيَّا انهالوا سبًّا فوق جمجمة الرجوع، الخوفُ يمضي من طريقٍ والمشاعرُ من طريق.", CategoryId = 4, ImageUrl = "/images/products/9789778200478.webp", Author = "سميح فتحي", PublishDate = new DateTime(2018, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778200478", Pages = 310, Size = "14×20" },
            new { Id = 270, Name = "إجتياح", Price = 180m, Stock = 10, Description = "كثيرون يربطون بين الاجتياح والاستعمار والحروب والمآسي، لكن اجتياحى مختلف،الاجتياح العاطفي، تلك العلاقة التي تخترق كل خطوط دفاعنا الفطري وتجتاح قلوبنا، هذه المشاعرالتي تهزنا من الداخل فتزلزل دنيانا وتجعل لبوصلتنا اتجاهًا واحدًا، ألا وهو الشخص الذي اجتاح قلوبنا وأرواحنا، هذا الشخص الذي بوجوده بجانبنا لا نحتاج لأي شيء آخر في الحياة.", CategoryId = 4, ImageUrl = "/images/products/9789776376946.webp", Author = "ريم مراد", PublishDate = new DateTime(2016, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789776376946", Pages = 265, Size = "14×20" },
            new { Id = 271, Name = "آشـــيا", Price = 240m, Stock = 10, Description = "رواية واقعية عن فتاة نصف سورية ونصف أمريكية .. اجواء غربية جمعت بين والدها السورى المسلم وأمها الامريكية المسيحية فى زواج لم يدم .. لفظ ثلاثة اطفال .. هما مازن, فاطمة واخيرا آشيـا ...\nعاشوا طفولة قاسية بائسة بين اب شرس فاسد وام صابرة لاجلهم ..\nحادث سرى يجعل اباهم يعود بيهم إلى سوريا فجأة ليبعدهم عن امهم وتنتهى علاقتهم كلياً بها لسنوات ..\nالطفولة الجافة التى عاشوها فى رعاية اسرة الاب الذى رماهم هناك وعاد إلى حضن امريكا بحجة رغبته بتعليم اولادة الاسلام", CategoryId = 4, ImageUrl = "/images/products/9789776376465.webp", Author = "ياسمين ثابت", PublishDate = new DateTime(2014, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789776376465", Pages = 370, Size = "14×20" },
            new { Id = 272, Name = "مجرد ألم", Price = 130m, Stock = 10, Description = "\"مجرد ألم\" لفائقة قنفالي تناقش قضايا إنسانية واجتماعية عميقة بأسلوب مؤثر، مستعرضةً معاناة الشخصيات من الألم الجسدي والنفسي والاجتماعي في حياتهم اليومية. تتناول المجموعة القصصية تجارب مختلفة، بدءًا من القهر الأسري والاعتداءات الشخصية، وصولًا إلى تجارب الحب والخيانة والتضحية.", CategoryId = 1, ImageUrl = "/images/products/9789778202915.webp", Author = "فائقة قنفالي", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778202915", Pages = 112, Size = "14×20" },
            new { Id = 273, Name = "بائع السخانات", Price = 140m, Stock = 10, Description = "نا لا أجيد الاختصار، ولستُ بارعًا في ربط الأفكار، لا يمكنني التحدث بانتظام عن أي شيء، ولا أعرف كيف نما كل هذا الكُره في نفس حلمي تجاهي، فقد قال لي ذات مشادة كلامية «أنت شخص عبيط وليس لديك أي خبرة بالحياة» كيف يقول ذلك وأنا موظف محترم؟ أرى أن طاعة رؤسائي واجب مقدس، أبتسم دائمًا ولا أنسى نصف انحناءة أمام الزبائن كما أوصاني أبي، أفعل باقتناع ما يجعلهم يعتقدون أنهم أذكى مني، وإلا فلماذا أنحني إن لم يكونوا صنفًا ممتازًا من البشر؟ مؤكد مكتوب أمامك في الأوراق أن أبي هو الذي عيَّنني في هذه الشركة العتيقة، ثلاثون عامًا وأنا أتحدث همسًا إلى الزبائن، أعرض عليهم فضائل شراء السخانات حتى في فصل الصيف.", CategoryId = 1, ImageUrl = "/images/products/9789778201246.webp", Author = "عمرو العادلي", PublishDate = new DateTime(2022, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778201246", Pages = 190, Size = "14×20" },
            new { Id = 274, Name = "تندر", Price = 120m, Stock = 10, Description = "كانت الحياة هادئة تمامًا داخل جدران بيت ثُريا، هادئة كشخصيتهما معًا، غرفتان وصالة في شقةٍ صغيرة بحي المنيل الهادئ، في زاوية بالصالة، تضع الجدة ماكينة الخياطة ماركة \"سنجر\"، على طاولة خشبية لها أربع عجلاتٍ صغيرة، تجرها أمام الكنبة الكبيرة وقتما رغبت في استعمالها، وتعيدها لمكانها بعد تغطيتها بمفرش من تطريزها أيضا، تلك الكنبة التي اشتراها الجد عبد الله في أول زواجهما وتعتز بها إلى الآن، تغير قماشها، ولا تفرط فيها، \"فيها ريحته\". دائما ما تخبر ندى بذلك، وضعتها بالقرب من بلكونة بحري واسعة \"هواها يرد الروح\" يغبطهما عليها الجيران، ويأتي بعضهم يجلسون معها فيها لشرب الشاي بالنعناع الذي تزرعه فيها، مستمتعين معها بنسمات الهواء الرطبة المختلط برائحة زرعها.\n ومع الهواء، فالشمس تحب بيت ثريا أيضا، تزوره ساعات خاطفة في ظهر اليوم، تُطهر لها البيت وتزيده دفئًا على دفء محبتها.", CategoryId = 1, ImageUrl = "/images/products/9789778201130.webp", Author = "سارة سيف", PublishDate = new DateTime(2022, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778201130", Pages = 160, Size = "14×20" },
            new { Id = 275, Name = "وتغير لون السماء", Price = 120m, Stock = 10, Description = "تداعت الصور ورائحة المطار الخانقة وقفزت إلى ذهني صورتي وأنا أمسكها بيدي لتُسرع الخطى بطريقةِ سيرها الطفولية نحو الطائرة بعد أن عرفت أنني لست على قوائم الممنوعين من السفر.. حين علمت أنني سأتمكن من الهروب.. لولاها ما هربت.. لولاها ما تعبت.. ولولاها ما أحببت الحياة.", CategoryId = 1, ImageUrl = "/images/products/9789778200379.webp", Author = "سندس الحسيني", PublishDate = new DateTime(2017, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778200379", Pages = 136, Size = "14×20" },
            new { Id = 276, Name = "من هنا تمر الأحلام", Price = 120m, Stock = 10, Description = "وقف وسط الحقل يحاول فك شفرة الكلمات التي غزت مِسْمَعَيْه من كل اتجاه. بينما هو يحاول فهم حديث الأشجار، دنا منه صاحب الكلمات. وضع يده على كتفه، فقفزت الغيمة فجأة. ربت الصبي عليها فاستكانت. ابتسم صاحب الكلمات للصبي وهو يخاطبه: \"كنت أنتظر حضورك. أرسل إليَّ الغلام صاحب السحاب خبرًا مع سحابة بأنك قادم. تعالَ معي لتشاهد الأشجار قبل أن تتخيَّر كلماتك منها. لديَّ شجرة تتقن لغاتٍ عدة، من يقطفْ منها ويأكل من كلماتها يبدُ ذكيًّا جدًّا للمستمعين، لكن عليه بذل جهد مضاعَف حتى لا تتداخل الكلمات وهو يتحدث فتختلط اللغات. ساعتَها لن يفهم حديثَه أحد، ويصير أضحوكة. قد يدهشك عدد الذين يختارون الأكل من ثمرها رغم مشكلاتها. أعتقد أن رغبتهم في الظهور بمظهر الأذكياء تفوق اهتمامهم بالتواصل والفهم، لكن لا بأس، فنحن بحاجة للضحك من حين إلى آخر! لديَّ شجرة أخرى لا تثمر سوى كلمة واحدة فقط. تختلف الكلمة باختلاف من يقطفها. تعرف الشجرة ما بقلب كل مَنْ يقترب منها، فتثمر الكلمة المناسبة لما يحمل هو بداخله. يفضِّل البعض هذه الشجرة لسهولة حديثها. كلمة واحدة، لا يرددون غيرها، ولا يغيرونها أبدًا، مهما حاولْتَ إقناعهم بأن هناك كلمات ولغات أخرى كثيرة. تتصلب ألسنتهم وأدمغتهم عندها، وكفى! لديَّ شجر مشاغب بعض الشيء، لكنه مُسَلٍّ. يطرح أحاجي من كلمات غير مكتملة، تركِّبها وتصل بعضها ببعض كيفما شئتَ، لتلائم أي موقف تواجهه. معظم من يفضلون ثمارها هم من المغرمين بلعب السياسة أو الفلسفة\"", CategoryId = 1, ImageUrl = "/images/products/9789776376939.webp", Author = "إيناس التركي", PublishDate = new DateTime(2016, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789776376939", Pages = 90, Size = "14×20" },
            new { Id = 277, Name = "الأجيال الثلاثة", Price = 120m, Stock = 10, Description = "نحن إزاء كتاب غريب من نوعه، يضم بعضًا من القصص القصيرة الجميلة، لثلاثة كُتّاب تفصل بين كل منهم نحو ثلاثين عامًا، لكن تجمعهم أواصر أسرة واحدة: الجد، والابن، والحفيدة. الشاعر القاص المعروف عبد الرحمن الخميسي، جذر هذه الشجرة المورقة، والابن أحمد الخميسي، وأخيرًا الحفيدة آنا أحمد الخميسي. وسأترك القصص لتحدّث القارئ بنفسها عن مواطن جمالها وفتنتها. وإذا نحينا جانبًا موضوع العائلات التي تسري فيها الموهبة من جيل إلى جيل، فإن سؤالاً آخر يطرح نفسه: هل يشتمل توريث الموهبة على توريث القضايا ونقاط الانطلاق الفكرية والشعورية ذاتها؟ يبدو ذلك! ففي كل تلك القصص -رغم مساحات الزمن الفاصلة- ثمة اهتمام بأوجاع الناس، في قصة \"النوم\" للخميسي الكبير، وقصة \"بط أبيض صغير\" للخميسي الابن، وقصة \"الأيدي\" لآنا الخميسي. يتصدر الإنسان كل ذلك الإبداع بطرق وأشكال مختلفة ووسائل أدبية متعددة. إنه كتاب فريد تصدره معًا أسرة عرفت بقدراتها ومواهبها وإخلاصها للوطن والفن، ولعلي أتوقف بانتباه خاص أمام قصص آنا ، ليس باعتبارها الأصغر في هذه العائلة ، ولكن لأن لديها خصوصية أراها متفردة، حيث العيش في عالمين يعزز كلاهما لماحية رؤية أخص خصوصيات الآخر ، متزودة بأدوات فنية من تراث أدبي عالمي عريق تنتمي له أصولها ، وضاربة في رهافة العمق حيث تمد جذورا جديده فتية ، في أرضنا .\nمحمد المخزنجي", CategoryId = 1, ImageUrl = "/images/products/9789776376700.webp", Author = "عبدالرحمن الخميسي، أحمد الخميسي", PublishDate = new DateTime(2015, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789776376700", Pages = 152, Size = "14×20" },
            new { Id = 278, Name = "لوح رخام ابيض", Price = 120m, Stock = 10, Description = "أدخل غرفة أمي وأُخْرج أحشاء الدولاب، فلا أجد شيئًا. أعود لغرفتي وألاحظ أن رأس الأباجورة يُشبه القبعات. أنزعها عن هيكلها وأضعها فوق رأسي. أثبّتها في شعري ببعض مشابِك الغسيل. أقف أمام نفسي في المرآة. أثني على مظهري الذي سيجعل «الكل يتجنن عليّ». أذهب مرة أخرى لغرفة أمي بحثا عن المفتاح. أخرج للشارع الذي لم أعد أتذكر ملامحه. أخطو خطواتي الأولى في الحارة. أنتظر أن يراني الكُل ويتجننوا عليّ.", CategoryId = 1, ImageUrl = "/images/products/9789776376427.webp", Author = "تسنيم فهيد", PublishDate = new DateTime(2014, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789776376427", Pages = 160, Size = "14×20" },
            new { Id = 279, Name = "غرفة سرية", Price = 140m, Stock = 10, Description = "شيء غريب يسيطر على العقل والروح الداخلية معًا، شيء يشبه الفوبيا، الفوبيا من اللاشيء. شيء يشبه العدم، أو خمول ما داخلنا تجاه كل شيء في الحياة، نتيجة بُعد كل ما نتعلَّق به، وذلك بعد رسم حياتنا به. حكاياتنا دائمًا تتجدد، لن تسير على نمطٍ واحدٍ، يمكن أن تكون سعيدة، وأيضًا يمكن أن تكون حزينة، لكنها بالنهاية لن تقف أبدًا. والآن في تلك الغرف السرية الكثيرة سنعرف أن الحياة خُلِقت بأشكالها المختلفة، بألوانها المختلفة، منها الفاتح والداكن، ولن تكون بيضاء دائمًا، أو سوداء دائمًا، ستأتي أيامٌ تلاحظ فيها أن هناك مواقفَ واختبارات تميل إلى اللون الرمادي، وذلك هي سنَّة الحياة حتى تنعدل الموازين الحياتية.", CategoryId = 1, ImageUrl = "/images/products/9789778201512.webp", Author = "سارة أبو العز", PublishDate = new DateTime(2023, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778201512", Pages = 224, Size = "14×20" },
            new { Id = 280, Name = "أبو النكد", Price = 150m, Stock = 10, Description = "لحظة.. هي لحظة واحدة فاصلة فارقة في حياتك.. اللي بتواجهي فيها نفسك وبتكسري القيود اللي رسمتيها لنفسك من سنين... اللحظة دي هي اللي بتوصلي فيها للحقيقة.. لإنك تقدري.. تعرفي.. تستحقي.. اللحظة دي هي بداية تقويم.. بداية حياة جديدة.. لشخص جديد.. بداية انقشاع الغيوم.. واكتمال الرؤية.. لحياة أحلى.. حياة بوعي.. من غير نكد", CategoryId = 8, ImageUrl = "/images/products/9789778201499.webp", Author = "ندى ترك", PublishDate = new DateTime(2023, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778201499", Pages = 232, Size = "14×20" },
            new { Id = 281, Name = "مالك ... مفيش", Price = 150m, Stock = 10, Description = "ومن هنا بدأت الكارثة.. عرض الناس حيواتهم على (السوشيال ميديا) كعرض الملابس الداخلية على منشر الغسيل، وفرحوا بلعبة (الرأي والرأي الآخر) فقالوا (الرأي) ولعنوا أعضاء (الرأي الآخر). تعاظمت ذواتهم، وصار كل منهم عالما مفتيا أديبا سياسيا اقتصاديا مدربا لكرة القدم، والملايين غيره من الأنعام بل هم أضل سبيلا. والسؤال هنا: لماذا يقبل الناس مثل هذه التدخلات من الآخرين في حياتهم الشخصية؟ ولماذا لا تكون إجابتهم دائما على مثل هذه التدخلات هي الإجابة العظيمة السحرية.. \"انت مالك؟\"؟", CategoryId = 8, ImageUrl = "/images/products/9789778200836.webp", Author = "تامر أحمد", PublishDate = new DateTime(2021, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778200836", Pages = 232, Size = "14×20" },
            new { Id = 282, Name = "حمار طروادة", Price = 150m, Stock = 10, Description = "من منا لا يعرف الحصان الأكثر شهرة في التاريخ «حصان طروادة » والذي استُخدمَ في الحرب الضروس التي قامت قديمًا بين إسبرطة وطروادة، واستمرّت قرابة الأعوام العشرة .. لكن التاريخ غير المنصِف لا يُبرز لنا دور الحِمار في هذه القصة .. والحق أن القصة بها أكثر من حمار ..\nفي هذه القصة سمح محروس للعديد من الأحصنة المماثلة بالدخول إلى حياته .. وكانت النتيجة الحتمية بتدمير حياته كليًّا .. إلى أن مَلّ من لعِب دور حمار طروادة، وقرر أن يقلب الطاولة على الجميع ويلعب هو دور الحصان ويَجُرُّ الآخرين نحو مصيرهم المحتوم .. فهل سينجح في التحول من حمار إلى حصان؟\n الرأي .", CategoryId = 8, ImageUrl = "/images/products/9789778200553.webp", Author = "تامر أحمد", PublishDate = new DateTime(2019, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778200553", Pages = 224, Size = "14×20" },
            new { Id = 283, Name = "لقمة الفاضى", Price = 120m, Stock = 10, Description = "زمان كان الفيسبوك وسيلة سريعة للتعارف أما الآن فأصبح وسيلة للخناق والتخاصم واللعن والسب...\nويبدو أن اسم الفيسبوك قد سمي بهذا الاسم لأنه يستخدم في نشر الآراء المختلفة مما يخلق مساحة من الاختلاف في الرأي بينك وبين أصدقائك \" فَيَسِبُّوك ويشتموك\"، وفيما يلي نصائح هامة للتعامل مع فيسبوك في زمن الثورة التي أصبحت تغلف كل تفاصيل حياتنا.\nكيف تخسر أصدقاءك وأحبابك في ستة بوستات:\n1-اكتب بوستات كتير .. هاجم كل المعارضين لك .. خليك وقح ولا يهمك .\n2- أدخل علي كل صفحات الآخرين وتابع كل ما يكتبوه علي صفحاتهم .. علق عليه .. هايمسحوه .. علق تاني .. هايمسحوه .. اكتب تاني وتالت لحد ما يزهقوا .\n3-هايردوا عليك ويهاجموك .. عِش في دور الشهيد .. احذفهم من قائمة أصدقاءك .. هايضيفوك تاني .. تجاهل الإضافة .. فالاختلاف في الرأي يفسد للفيسبوك قضية .\n4-اكتب بوست تاني واشتم الأصدقاء اللي حذفتهم من قائمتك .\n5-هايبعتولك رسالة .. ماتردش عليهم .. هايبعتوا تاني .. احلق لهم .. اعمل لهم بلوك حتي لا يزعجوك مرة أخري.\n6-بس خلاص .", CategoryId = 8, ImageUrl = "/images/products/9789776376960.webp", Author = "تامر أحمد", PublishDate = new DateTime(2016, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789776376960", Pages = 148, Size = "14×20" },
            new { Id = 284, Name = "خنتك ليه", Price = 250m, Stock = 10, Description = "الكتاب يناقش مفهوم الخيانة بشكل عام والخيانة الزوجية بشكل خاص من المنظور النفسي والسيكولوجي ... ويستعرض بعض الحالات الحقيقة كنموذج للخيانة الزوجية.\nيشرح الكتاب تعريف الخيانة بمفهومها الواسع وأسبابها وأنواعها ويستعرض بعض الإحصائيات والدراسات. كما يشرح الإجراءات العلاجية للطرفين للوصول إلى التعافي من أثار الخيانة على الشريكين.. من مرحلة إكتشاف الخيانة إلى مرحلة بناء الثقة من جديد والوصول إلى التسامح.\nكما يشرح الكتاب التأثير النفسي للخيانة على الشريكين وعلى الطرف الثالث.", CategoryId = 6, ImageUrl = "/images/products/9786339957512.webp", Author = "تامر حسنين", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786339957512", Pages = 328, Size = "14×20" },
            new { Id = 285, Name = "يورجن كلوب", Price = 350m, Stock = 10, Description = "\"إنه جنون كُرة القدم، وكيف يعيشها الناس في ليفربول، وجميع مُشجِّعي ليفربول حول العالَم. إنه ليس ناديًا عاديًا أبدًا، إنه نادٍ مُميَّز\".\n-يورجِن كلوب\n\nصَدَم قرار يورجِن كلوب بمُغادرة ليفربول بعد تسع سنوات مُذهِلة مُجتمع كُرة القدم. فقد كان لفطنته التكتيكيَّة، ومهاراته التحفيزيَّة، وقُدرته على تطوير المواهِب الشابَّة دور أساسي في عودة ليفربول كفريقٍ كبيرٍ في كُرة القدم الإنجليزيَّة والأوروبيَّة.\n\nقبل أن يُحدِث ثورة في اللعبة في إنجلترا، أطاح المُدرِّب الاستثنائي بمُفرده بالنظام التقليدي في الدوري الألماني، حيث قاد بوروسيا دورتموند من العدم إلى الفوز بلقب الدوري الألماني مرَّتين مُتتاليَتين. ثُم، وفي عام (٢٠١٩)، حفر اسمه في كُتب التاريخ بإعادة ليفربول إلى المجد في دوري أبطال أوروبا، مُنهيًا انتظار النادي الذي دام لأربعة عشر عامًا للفوز بلقبٍ أوروبي كبير. وكان كلوب العقل المُدبِّر وراء تحقيق ليفربول للقب الدوري الإنجليزي المُمتاز في موسِم (٢٠١٩ – ٢٠٢٠)، وهي عودة مُرحَّب بها إلى قمَّة كُرة القدم، مما رسَّخ مكانته كأسطورةٍ في تاريخ النادي.\n\nوحتى بعد رحيله، سيظل كلوب يحظى بالاحترام والتبجيل كمُدرِّبٍ تكتيكي بارِع له فلسفته الفريدة في اللعب. وسيظل إرثه بين لاعبيه هو شغفه ومهارته في إدارة الفريق، وسيظل معشوقًا إلى الأبد بين الجماهير لسحره، وخفَّة ظلّه، وكُرة القدم المُثيرة التي قدَّمها على أرض الملعب.\n\nهذا هو الاحتفاء النهائي بيورجِن كلوب، بطبيعته المتواضِعة، وعبقريَته الكرويَّة.", CategoryId = 7, ImageUrl = "/images/products/9786339957505.webp", Author = "ألمار نيفلينج", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786339957505", Pages = 472, Size = "14×20" },
            new { Id = 286, Name = "الرجل الرمادي", Price = 390m, Stock = 10, Description = "كورتلاند جنتري رجل طيب، لكنه قاتل ماهر.\nفي الظلال، يُعرف باسم \"الرجل الرمادي\". إنه أسطورة في عالم العمليات السرية، يتنقل بصمت من مهمة إلى أخرى، ينجز المستحيل ثم يتلاشى دون أن يُلاحَظ. ودائمًا ما يُصيب هدفه. دائمًا.\nلكن هناك قوى أكثر فتكًا من جنتري في هذا العالم: قوى مثل المال والسلطة. وهناك رجال يرون أن هذه هي العملة الوحيدة التي تستحق النضال. وفي نظرهم، أصبح جنتري لم يعد ذا فائدة.\nلكن كورت جنتري سيبرهن أنه بالنسبة له، لا يوجد مجال بين القتل من أجل الكسب والقتل من أجل البقاء على قيد الحياة…", CategoryId = 3, ImageUrl = "/images/products/9789778201253.webp", Author = "مارك غريني", PublishDate = new DateTime(2024, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778201253", Pages = 416, Size = "14×20" },
            new { Id = 287, Name = "الهدف", Price = 390m, Stock = 10, Description = "ما القتل إلا وظيفة كورت جنتري، لكنه يتحول لمسألة شخصية في الجزء الثاني من رواية الرجل الرمادي لصاحبها مؤلف النيويورك تايمز الأكثر مبيعًا مارك غريني.\nقبل أربع سنوات تعرّض كورت جنتري للخيانة من قِبل رؤسائه في جهاز \"السي آي ايه\" وكي ينجو بحياته لم تكن أمامه سوى التضحية ببعض زملائه. الآن باعتباره قاتلًا محترفًا معروفًا باسم \"الرجل الرمادي\" فهو يكسب عيشه من تصفية آخرين، لكن حين يظهر فجأة زميلٌ قديمٌ له ظنّه ميتًا يطارده ويريد تجنيده لصالحه، تنقلب حياته الدموية لشكل تراجيدي بائس.\nما يريده الزميل القديم من الرجل الرمادي تحويل عملية اغتيال لاختطاف مما يجعلها شبه مستحيلة، لكن المهمة الأصعب هي محاولة إعادة انتمائه لجهاز السي آي ايه بعد انقلابه عليه.\nوهكذا بين مافيا الروس التي لا ترحم وتريد خدماته القتالية من جهة، وبين خطط واستراتيجيات أجهزة الأمن الأمريكية من جهة أخرى، يشعر الرجل الرمادي أنه ينازع فصيلين داخله طوال مهمته، وكي يخرج من هذه المعمعة سليمًا أو حيًّا عليه أن يُريق الكثير من الدماء.", CategoryId = 3, ImageUrl = "/images/products/9789778202656.webp", Author = "مارك غريني", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778202656", Pages = 540, Size = "14×20" },
            new { Id = 288, Name = "كبسولات زوجية", Price = 190m, Stock = 10, Description = "هذا الكتاب سيكون دليلا لك للتعامل مع شريكك .\nستتعلم معه التالى بخطوات بسيطة :\n- كيف تفهم احتياجك وتعبر عنه وكيف تشبع احتياج شريكك.\n- كيف تتحدث إليه.\n-ما يفضل أن تقوله وما يجب أن تتجنب قوله.\n- وإن حدث بينكما خلاف ما هى الاستراتيجيات المتبعة لحل هذا الخلاف.\nوقبل كل شئ سنفتش معك قليلا فى أعماقك لأن مفتاح نجاح علاقتك مع شريكك قد يكون بداخلك أنت.", CategoryId = 5, ImageUrl = "/images/products/9789778200690.webp", Author = "فاطمة المهدي", PublishDate = new DateTime(2020, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778200690", Pages = 288, Size = "14×20" },
            new { Id = 289, Name = "ستي قالتلي", Price = 125m, Stock = 10, Description = "كتاب يجمع معظم الأقوال والمثل الشعبية التي تناقلتها الأجيال، حيث يقوم بوصف معانيها وأصولها مع شرحها، ويربطها بالأحداث اليومية في الحياة.", CategoryId = 1, ImageUrl = "/images/products/9789778202397.webp", Author = "نسمة مدحت", PublishDate = new DateTime(2024, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778202397", Pages = 168, Size = "14×20" },
            new { Id = 290, Name = "Art of fantasy", Price = 150m, Stock = 10, Description = "Dr. Mervat Abou Oaf chronicles the journey of Egypt’s film industry from the days of its commencement to the contemporary era of digitization and streaming platforms, all while painting a better, brighter, and bigger picture of what the future could entail.\n\nThe book maneuvers around significant dates and milestones, highlighting Egyptian cinema's cultural, political, and economic importance.\n\nThrough the lens of expert interviews, Dr. Abou Oaf examines regulatory frameworks operating backstage and maps out what’s required to sustain and develop a thriving industry, proposing a regulatory model that embraces economic prosperity, cultural values, and industry independence.", CategoryId = 1, ImageUrl = "/images/products/9789778201741.webp", Author = "مرفت أبو عوف", PublishDate = new DateTime(2023, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778201741", Pages = 204, Size = "14×20" },
            new { Id = 291, Name = "Wellness", Price = 240m, Stock = 10, Description = "“Curses can turn into blessings, though not always will\nthe timing be so convenient!”\nAlthough this period has been stressful for everyone.\nIt has also given many of us the time to reflect on our lives, relationships, goals, and make new plans for the future.\nMany have learned how to be more thankful and empathetic – In other words, putting aside that many have lost loved ones, this period seems to be a blessing in disguise for many.\nHappiness lies in self love and self care.\nThe challenge lies in building the capability\nto break all the barriers within yourself\nthat prevent you from seeking the love you deserve.", CategoryId = 5, ImageUrl = "/images/products/9789778201055.webp", Author = "Rania Sabry", PublishDate = new DateTime(2021, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778201055", Pages = 258, Size = "14×20" },
            new { Id = 292, Name = "طعم الفراق", Price = 230m, Stock = 10, Description = "يبحث الكاتب والروائي والصحفي الفلسطيني ربعي المدهون عن كيفية استهلال روايته التي يحاول أن يروي فيها حكايته هو وعائلته، تلك العائلة التي عاصرت النكبة، ومنذ ذلك الحين أخذوا يتنقلون من مدينة إلى أخرى، ومن بيت إلى آخر، خائفين من الظلام الذي تخلفه الحروب، متحسرين على وطن ضائع، صابرين على فراق وغربة امتدت أعوامًا وأعوامًا، حتى كاد بعضهم ينسى صوت أقرب الناس إلى قلبه.\n\nيبدأ ربعي روايته بيوم مولده، ويُعرّفنا على شجرة عائلته التي تبدأ بجده سليم، مرورًا بوالده وأعمامه وزوجاتهم، حتى أخيه الصغير راسم.\n\nكيف نشأ ربعي في مدينة حلّت عليها الحرب، وفي عائلة من النازحين؟\nهل وحدها الحرب هي التي فرّقت عائلته، أم أن الفراق حتمي لا بدّ منه؟", CategoryId = 7, ImageUrl = "/images/products/9789778202779.webp", Author = "ربعي المدهون", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778202779", Pages = 300, Size = "14×20" },
            new { Id = 293, Name = "فن الخيال", Price = 175m, Stock = 10, Description = "تؤرخ د. مرفت أبو عوف في هذا الكتاب المرجعي رحلة صناعة السينما في مصر منذ بدايتها وحتى العصر المعاصر، عصر الرقمنة ومنصات البث، كل ذلك مع رسم صورة أوسع وأفضل وأكثر إشراقًا لما يمكن أن ينطوي عليه المستقبل. يناور الكتاب حول التواريخ والمعالم الهامة، ويسلط الضوء على الأهمية الثقافية والسياسية والاقتصادية للسينما المصرية.\nفمن خلال مقابلات مع عدد من أهم خبراء الصناعة والثقافة في مصر، تفحص الدكتورة أبو عوف الأطر التنظيمية التي تعمل وراء الكواليس وترسم خرائط لما هو مطلوب للحفاظ على صناعة مزدهرة وتطويرها، كما تقترح نموذجًا تنظيميًّا يحتضن استقلالية الصناعة وازدهارها التوعوي السياسي والاقتصادي والارتقاء بالقيم الثقافية والأخلاقية.", CategoryId = 1, ImageUrl = "/images/products/9789778202472.webp", Author = "مرفت ابو عوف", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778202472", Pages = 170, Size = "14×20" },
            new { Id = 294, Name = "عطايا الاربعين", Price = 190m, Stock = 10, Description = "هنا ستجد خليطًا من الشجاعة والجُبن، الضحك والبكاء، الذكاء والحُمق، المرونة والجمود، القضايا العامة والحكايات الشخصية جدًا، ستجد العربية الفصحى والعامية المصرية، النصوص الطويلة والعبارات القصيرة، النثر والشِعر، كلامًا عن الحب، الكراهية، الكفاح، اليأس، الأمل، العائلة، الرفاق، الشوارع، الأغنيات.. لأن الإنسان في النهاية هو مجموع كل هذا وثمرته، ربما أكون قد بالغتُ أحيانًا أو تطرّفت، أصبتُ أو أخطأتُ، تناولتُ الموضوع بخفّة مزرية أو عمقٍ أكثر من اللازم، لكن ما أنا على يقين منه أنني في كلٍ كنتُ حقيقيًا جدًا صادقًا وأمينًا ولو كان في ذلك بعضُ الكشف عما يحذر الآخرون عادة من كشفه عن أنفسهم", CategoryId = 8, ImageUrl = "/images/products/9789778202854.webp", Author = "حسام مصطفي ابراهيم", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778202854", Pages = 266, Size = "14×20" },
            new { Id = 295, Name = "روايات لم ترو", Price = 260m, Stock = 10, Description = "أذكر عام ١٩٧٩ وكنت عائدا من العمل لمدة عام في المملكة العربية السعودية، أن وجدت بين شرائط التسجيل رباعيات صلاح جاهين بصوت على الحجار والحان سيد مكاوي، فجعلتها لملا فراغ البيت كل يوم، لا أوقفها إلا قبل أن أنام كانت هذه أول مرة استمع تعلى الحجار فاحبيته جدا، أما سيد مكاوي فعشق قديم لا ينتهي صلاح جاهين كثير من معاني و وتأملات صلاح جاهين تدخل بك في المنطقة الوجودية لفهم العالم أو الإحساس به، وتذكرتي برباعيات الخيام، فهي أيضا تدخل بك في منطقة المعالي الوجودية للعالم والبشر والحياة ورغم أني قاري للفلسفة، وأعرف هذه المعاني ومة باني ومقتنع بها فكريا وروحيا الا أن صياغتها الشعرية تغنيك عن عشرات الكتب الفلسفية، وحين تسمعها غناء تتسع الدنيا حولك رغم أن كثيرا منها يوحي بالعدم كنهاية لكل شده او كفراغ يحيط بنا وإن لم نكن نراه.", CategoryId = 8, ImageUrl = "/images/products/9789778202489.webp", Author = "إبراهيم عبد المجيد", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778202489", Pages = 388, Size = "14×20" },
            new { Id = 296, Name = "فن اللعبة", Price = 140m, Stock = 10, Description = "تتوالي الأحداث الاقتصادية المتوترة في الفترات الحالية مما يشكل ضغط كبير علي متخذ القرار فرد او مؤسسة في ظل تلك الأحداث اصبح فرض علي الجميع تعلم اللغة الاقتصادية والمفاهيم المالية الأساسية لتحقيق توازن في الجانب المالي من الحياة وتعلم سبل النجاة من الازمات الاقتصادية العاصفة , سيدعمك هذا الكتاب في نمو عقليتك الاقتصادية ودعمك في اتخاذ قرارات مالية سليمة بناء علي رؤية واضحة ومفاهيم تم قياسها من قبل , هذا الكتاب هو مفهوم اقتصادي أساسي ما لا يسع الانسان جهلة الآن , فتم اعداد الكتاب ليناسب كل الناس من المتخصصين وغير المتخصصين بلغة سهلة وأنيقة ومفاهيم حياتية يمكن تطبقها في الحياة العملية ...", CategoryId = 1, ImageUrl = "/images/products/9789778202601.webp", Author = "شريف سعيد", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778202601", Pages = 128, Size = "14×20" },
            new { Id = 297, Name = "علاقة منتهية الصلاحية", Price = 140m, Stock = 10, Description = "العلاقات الغير صحية التي تؤثر على الصحة النفسية هي العلاقات التي تسبب ضغوطا نفسية وتأثيرا سلبيا على العافية العقلية والعاطفية للفرد. قد تشمل هذه العلاقات العنف الجسدي أو العاطفي، التنمر الإهمال العاطفي، الاضطهاد، وعدم وجود دعم اجتماعي أو علاقات غير مستدامة تؤثر هذه العلاقات الغير صحية على الشعور بالثقة بالنفس، والسعادة، والاستقرار العاطفي، وقد تزيد من خطر الإصابة بالاضطرابات النفسية مثل الاكتئاب والقلق من المهم التعامل مع هذه العلاقات بشكل صحيح والبحث عن الدعم اللازم للحفاظ على صحة نفسية جيدة.\n\nيتناول الكتاب قصصا حقيقية عن العلاقات السامة\" ويسلط الضوء على العلامات التي تشير إلى وجودك في علاقة غير صحية، بالإضافة إلى كيفية الخروج منها بأقل قدر ممكن من الخسائر..", CategoryId = 5, ImageUrl = "/images/products/9789778202595.webp", Author = "سارة مجدي", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778202595", Pages = 116, Size = "14×20" },
            new { Id = 298, Name = "القيصر", Price = 375m, Stock = 10, Description = "الكتاب يكشف القصة المثيرة وغير المعلنة لرحلة صعود رجل غامض من شوارع لينينغراد القاسية إلى القمة. استعد للغوص في عالم مليء بالمؤامرات السياسية، الصفقات السرية، والمعارك الخفية داخل أروقة الكرملين. يعرض الكتاب قصة بوتين من بداية عمله كضابط مخابرات في جهاز الـ KGB إلى أن أصبح سيد الكرملين بلا منازع، المتحكم في مصير أمة بأكملها. إنها حكاية الصعود إلى السلطة، حيث يلتقي المكر بالذكاء، ويختلط الطموح بالخيانة، لتظهر الصورة الحقيقية لرجل لا يعرف حدودًا لتحقيق أهدافه. رجل قد يكون في نظر البعض أقوي رجل في العالم. الكتاب أيضا يجيب علي أسئلة أخري مثل كيف بدأت الحرب الروسية الأوكرانية؟ ولماذا أسست الولايات المتحدة مع دول أوروبا الغربية حلف الناتو؟ وكيف أصبح ممثل كوميدي مثل زيلينسكي رئيسا لأوكرانيا؟ لماذا تدخلت روسيا في الانتخابات الأمريكية؟ وهل تم اغتيال ياسر عرفات؟ كل ذلك وأكثر تجدوه داخل كتاب القيصر.", CategoryId = 7, ImageUrl = "/images/products/9789778202533.webp", Author = "طاهر المعتز بالله", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778202533", Pages = 590, Size = "14×20" },
            new { Id = 299, Name = "أسطورة أحمد خالد توفيق", Price = 130m, Stock = 10, Description = "ماذا لو ظهر لك أحدهم ليخبرك أنه أنت ولكن من عَالمٍ موازٍ؟ هل تقبل لو عرض عليك تبادل الأدوار والعوالم؟ هل ستجرؤ على إخبار أحدٍ بذلك؟ هل سيصدقك الناس أم سيشُكّون في قواك العقلية؟ والأهم من ذلك، كيف يمكن أن تقرر شخصية روائية مصير كاتبها؟!\n\nفي أحد الأيام، بينما يعاني الدكتور أحمد خالد توفيق من قفلة الكاتب، يتلقى مكالمة هاتفية بعد منتصف الليل من مجهول، ويطلب منه مقابلته في اليوم التالي ليعرض عليه أمرًا ما، وحين يسأل المُتصل عن اسمه، يقول له: «أنا أحمد خالد توفيق»!\n\nإنها كأسطورة رفعت إسماعيل عندما ظهر له قرينه ونغص عليه حياته، فحاول التخلص منه وتدميره. لكن الأمر هذه المرة مُختلف؛ فقد اقترح قرين العراب أن يتبادلا الأدوار لأن كل منهما يعيش حياة مملة، والأغرب أنه أراد الاحتكام في ذلك الأمر إلى دكتور «رفعت إسماعيل» الشخصية الروائية الشهيرة في سلسلة ما وراء الطبيعة! كيف سيتصرف دكتور «أحمد»؟ هل سيوافق على عرضه أو أم سيحتكم إلى رفعت إسماعيل صاحب التصرفات الحمقاء في بعض الأحيان؟ وفي تلك الحالة، من منهما سيختاره رفعت ليعيش في العالم الأرضي؟!\n\nرحلة غرائبية ممزوجة بذكرياتٍ دافئة وتفاصيل مختلفة من حياة دكتور أحمد خالد توفيق. نتتبع فيها طفولته وشبابه وبداياته في الكتابة، وبداية دخوله للمؤسسة العربية الحديثة التي تعد محطة انطلاقه الحقيقي في عالم الأدب ليصبح عراب أدب الرعب. كما نتعرَّف على علاقته الشائكة والملتبسة بـ«رفعت إسماعيل»، وعلاقته بالسينما وأمنيته أن يرى أحد أعماله على شاشة السينما، وكيف أنه تنبأ بحدوث ذلك بعد موته! وكيف كان موته حدثًا مُزلزلًا في حياة كثيرين!", CategoryId = 7, ImageUrl = "/images/products/9789778202298.webp", Author = "خلف جابر", PublishDate = new DateTime(2024, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778202298", Pages = 152, Size = "14×20" },
            new { Id = 300, Name = "تحت ظل الكتابة", Price = 180m, Stock = 10, Description = "الكتاب عبارة عن مقالات متنوعة للكاتب درج على نشرها في بعض الصحف والمواقع وفيها يتعرض لظاهرة الإبداع من نواح شتى، يكتب عن الإبداع نفسه والمبدعين، ويستعرض كتبا قرأها وأفادته في تجربته الخاصة، وكتب لم تمده بشيء، يتعرض لظواهر الكتابة وللكتب التي تنتشر بسرعة ومبررات انتشارها من وجهة نظره.\nالكتاب اشتمل على حوالي 40 مقالا منها مقالات عن ساحر الكتابة بورخيس بحسب شهادة الكاتب الأرجنتيني ألبرتو مانغويل الذي كان يوما يقرأ لبورخيس بعد إصابته بالعمى، بورخيس الكبير لكن المتواضع الذي يستفيد حتى من آراء المبتدئين في كتابته، بعكس كثير من كتابنا العرب الذين يصيبون قليلا من الشهرة، ويتعالون على القراء..تعرض تاج السر في كتابه، للقارئ باعتباره الهدف الأساسي الذي تسعى الكتابة لاسترضائه، وكيف أن بعض القراء قد لا يفهمون جيدا ويعممون عدم فهم للآخرين، ومواقع القراءة التي أضحت مشنقة للكتب التي ربما يكتب عنها من لم يقرأها أصلا، وسمع عنها فقط وسماها الكاتب بحماقات الإنترنت ؛ حيث يتخيل كثير من الناس أن الكتابة نقل مباشر للواقع ولا يعرفون وظيفة الخيال المهمة، في عملية صناعة النص، وقد تعرض الكاتب لشخصيات، ليست واقعية أصلا واشتهرت في بعض النصوص وتم إلباسها لشخصيات موجودة في الواقع في أمكنة ما، وبالتالي، فصلت لها هوية واقعية بلا وجه حق، ومنها شخصية \" سيف الدين \" في رواية \" عرس الزين \" للطيب صالح، وكانت شخصية خيالية، تم رسمها في الواقع في القرية التي يعيش فيها. تعرض الكتاب أيضاً في مقالات لرموز الكتابة الراحلين، ومنهم جمال الغيطاني الذي رحل مؤخرا، وكيف أن تسمية شارع باسمه في منطقة الجمالية، يعد تكريما كبيرا له، ويتمنى لو عممت مثل هذه التكريمات على كل المبدعين.أيضا تعرض الكاتب لمواضيع وقضايا الكتابة الأثيرة لدى معظم كتاب العالم الثالث، مثل قضية التهميش والفقر، وذكر أن أليس مونرو الكندية، بالرغم من حياتها في بلد متحضر، إلا أنها دأبت على الكتابة في مواضيع التهميش، والفقراء . وعن قضية اللاجئين، والهجرات غير المشروعة، وتحطم الأحلام بالغرق، كقضية الطفل السوري إيلان، وكذلك عن كثير من القضايا الإنسانية، وارتباطها بالثقافة والإبداع عموما، تعرض لها الكاتب في: تحت ظل الكتابة.\nلأربعين مقالا", CategoryId = 1, ImageUrl = "/images/products/9789778202410.webp", Author = "أمير تاج السر", PublishDate = new DateTime(2024, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778202410", Pages = 250, Size = "14×20" },
            new { Id = 301, Name = "الكتابة وسنينها", Price = 140m, Stock = 10, Description = "الكتابة وسنينها كتاب يتعرض لرحلة الكتابة بهدف مساعدة كل من يريد وضع قدمه علي طريق الكتابة الإباعية والبدء في الكتابة..\nيحتوي الكتاب علي مجموعة من الفصول يبدأ أولها بالمراحل التمهيدية للكتابة والتجهيز للكتابة وكيف يعرف الكاتب أنه موهوب في الكتابة ثم يتطرق في الفصول اللاحقة إلي كيفية تشكيل عقلية الكاتب ثم إلي تقنيات الكتابة المختلفة ككتابة الرواية وكتابة القصة القصيرة وكتابة الكتاب غير القصصي..\nيتطرق الكتاب بعد ذلك في فصوله الأخيرة إلي تعريف القاريء بعالم النشر وبعض النصائح الخاصة بالنشر وتسويق الكتاب...", CategoryId = 1, ImageUrl = "/images/products/9789778202465.webp", Author = "هدى أنور", PublishDate = new DateTime(2024, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778202465", Pages = 182, Size = "14×20" },
            new { Id = 302, Name = "كيف بدأ الرعب", Price = 160m, Stock = 10, Description = "\"يتتبَّع الكِتاب بشكلٍ أساسيٍّ عدة محاوِر رئيسيَّة في أدب وسينما الرُعب، منذ أن كانَت محض أفكار صغيرة، وحتى وصلت لأن تُصبِح أهم الأفكار التي يلجأ لها كُتَّاب الرُعب ليبنوا عليها رواياتهم وأفلامهم، نبحث في القصص التاريخيَّة عن أول ذكر لهذه الأفكار، ونُتابِع كيف تطوَّرت تلك الأفكار على مر الزمان، كيف نضجَت وكيف تغيَّرَت، وما هي أصولها الحقيقيَّة، وهل من المُمكِن أن نكتشِف أن بعضها ليس مُجرَّد أساطير فقط؟ وإنما حقائِق مُثبَتة؟ أو أمراض موجودة؟\nنبدأ الكتاب بمُناقشة فكرة أو أسطورة الرجل الذئب، أو المذؤوب\nنُبحِر خلال هذا الفصل بين صفحات ملحمة جلجامِش لنرى أول ذِكر للمذؤوبين في التاريخ\nثُم سننتقِل إلى الفصل الثاني الذي يبحَث عن أصل أسطورة الموتى الأحياء أو الزومبي.\nنذهب للفصل الثالِث، الذي يُناقِش الخوف البشري من الدفن حيًا، وكيف تطوَّرت هذه الفكرة عبر الزمن، وكيف طوَّر البشر من آلياتهم وأنفُسهم ليواجِهوا هذا الخوف، والأهم من ذلك.. هل نجحوا في ذلك؟\nثُم سنذهب للفصل الرابِع، الذي يُناقِش الخوف من المرايات، ومن مِنا لا يخشى المرايات، ولا يشُك أنها بوابات لعوالِم أخرى، عوالِم مُرعِبة حقًا..\nبعد ذلك سننتقِل للفصل الخامِس، لنُناقِش وجود الفضائيين، هل هم حقيقيين؟ هل هم محض خيال؟ لكن لو كانوا مُجرَّد خيال.. فلماذا توجَد عشرات الأدِلة الماديَة المُثبَتة علميًا وتاريخيًا التي تُثبِت وجودهم بيننا؟\nوأخيرًا.. ننتقِل للفصل الأخير، حيث سنتحدَّث عن الأرواح والأشباح والمس في الغرب!\n\n\"", CategoryId = 9, ImageUrl = "/images/products/9789778201871.webp", Author = "محمد عصمت", PublishDate = new DateTime(2024, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778201871", Pages = 222, Size = "14×20" },
            new { Id = 303, Name = "كاش", Price = 140m, Stock = 10, Description = "\"إن أكبر نظام اقتصادي هو الحياة ذاتها، فالحياة نظام كريديت (ائتماني) تعطيك الكثير من الموارد وتهيئ لك الظروف الأولى للحياة، فأنت حصلت على جسدك، أهلك، موطنك، عمرك عقلك ... إلخ دون أن تدفع شيئًا، ولكن هل يعني ذلك أن تلك الأشياء مجانية؟\n\nعلى العكس تماما فهي موارد مدفوعة مقدمًا، وتلك الموارد سوف تستخدم وتهلك يوما ما فهي غير متجددة؛ لذلك عليك أن تمتلك الوعي الكامل لتسخير تلك الموارد لتحقيق أكبر مكسب.\n\nهذا الكتاب يصنع جسرًا بين العلم والتطبيق، يحاول تقليل الفجوة بين المعرفة وامتلاك أدوات العمل، لسنوات كنت أحاول فهم لماذا يستطيع بعض البشر تحقيق أكبر مكسب\n\nوالوصول إلى الرفاهية، ويعاني الكثير غيرهم، كنت أحاول\n\nتطوير عقلية تسمح للجميع بامتلاك أدوات اقتصادية فعالة\n\nلتلبية رغباتهم ورفاهيتهم، إنه نظام كاش.\n\nإن امتلاك عقلية الكاش هو استثمار جيد في ذاتك، كذلك امتلاك هذا الكتاب، يعتبر خطوة ناجحة منك في فهم ما يدور حولك، وتطوير عقليتك الاقتصادية لتحقيق حياة أفضل وهذا ما تستحقه.\"", CategoryId = 1, ImageUrl = "/images/products/9789778202458.webp", Author = "شريف سعيد", PublishDate = new DateTime(2024, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778202458", Pages = 142, Size = "14×20" },
            new { Id = 304, Name = "انت مالك", Price = 120m, Stock = 10, Description = "ومن هنا بدأت الكارثة.. عرض الناس حيواتهم على (السوشيال ميديا) كعرض الملابس الداخلية على منشر الغسيل، وفرحوا بلعبة (الرأي والرأي الآخر) فقالوا (الرأي) ولعنوا أعضاء (الرأي الآخر). تعاظمت ذواتهم، وصار كل منهم عالما مفتيا أديبا سياسيا اقتصاديا مدربا لكرة القدم، والملايين غيره من الأنعام بل هم أضل سبيلا. والسؤال هنا: لماذا يقبل الناس مثل هذه التدخلات من الآخرين في حياتهم الشخصية؟ ولماذا لا تكون إجابتهم دائما على مثل هذه التدخلات هي الإجابة العظيمة السحرية.. \"انت مالك؟\"؟", CategoryId = 8, ImageUrl = "/images/products/9789778201406.webp", Author = "أشرف توفيق", PublishDate = new DateTime(2023, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778201406", Pages = 140, Size = "14×20" },
            new { Id = 305, Name = "أوراق روسية", Price = 140m, Stock = 10, Description = "يضم الكتاب تسعة عشر مقالًا ما بين الترجمة والكتابة،كما يضم الكتاب عدة مقالات عن العلاقات المصرية الروسية،يتطرق أيضًا إلى المصير القاسي للأدباء الروس في عهد ستالين، بدءا من منع كتبهم، ومصادرتها، إلى ملاحقة وسجن وتشريد أولائك الكتاب. وأخيرًا يشتمل الكتاب على مهم عن وضع الأدب الروسي الحديث بعد انهيار الدولة السوفيتية.", CategoryId = 1, ImageUrl = "/images/products/9789778200416.webp", Author = "أحمد الخميسي", PublishDate = new DateTime(2017, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778200416", Pages = 204, Size = "14×20" },
            new { Id = 306, Name = "نساء الكرملين", Price = 120m, Stock = 10, Description = "عتبر كتاب \"نساء الكرملين\" الذي أثار اهتماماً واسعاً، دراسة صحفية وفنية ونفسية ـ إن لم يكن أيضا دراسة تاريخية ـ للمصير الصعب، والمأساوي أحيانا، والمجهول للنساء اللواتي قُدر لهنّ أن يصبحن زوجات ل\"زعماء\" الكرملين، وأن يقاسمن أولئك القادة السكن والطعام وتفاصيل الحياة اليومية.", CategoryId = 1, ImageUrl = "/images/products/9789776376991.webp", Author = "أحمد الخميسي", PublishDate = new DateTime(2017, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789776376991", Pages = 162, Size = "14×20" },
            new { Id = 307, Name = "رينسانس أسيوط", Price = 170m, Stock = 10, Description = "وهكذا بدأت عملية تحويل السنيما الشتوي الكلاسيكية الضخمة إلى مُجمَع مُكوَن من ٤ شاشات، وكنت أمر على موقع السنيما في طريق عودتي من الكلية لأتفرج على أعمال البناء والتركيب، حتى جاءت اللحظة المُنتظرة وتم افتتاح السنيما في يناير ٢٠٠٠ بحضور نجيب ساويرس وعددٍ من نجوم ونجمات السنيما المصرية\".\nلو انتي/ انتي من مواليد السبعينات والتمانينات فهتعيشوا هنا حالة من النوستالچيا وتسترجعوا معاها أجمل ذكرياتكم من جديد، أيام القمصان المشجرة والكاروهات وشرايط الكاسيت ونوادي الڨيديو وأفلام عادل إمام ونجمة الجماهير وثورة المضحكين الجدد، وتايتانيك والمهمة المستحيلة وغيرهم..\nأما لو انت/ انتي من جيل التسعينات والألفينات، فهتبقى فرصة تركبوا آلة الزمن، وتعيشوا تاريخ حقيقي حصل فعلاً، وتعرفوا تفاصيل مهمة وممتعة عن قصص إنتاج وعرض الأفلام المصرية والأمريكية اللي شوفتوها بعدين على التليفزيونات واللابات.\nيالا بينا؟", CategoryId = 1, ImageUrl = "/images/products/9789778200706.webp", Author = "شريف ثابت", PublishDate = new DateTime(2020, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778200706", Pages = 240, Size = "14×20" },
            new { Id = 308, Name = "أفلام فترة النقاهة", Price = 140m, Stock = 10, Description = "مسافة واسعة قطعتها فى الزمان والمكان، وداخل الدماغ أيضاً، منذ تلك الليلة من ربيع عام ٢٠٠٤ والتى جلست فيها داخل إحدى قاعات رنيسانس أسيوط، أتابع مأخوذاً الدراما الملحمية \"الساموراى الأخير\".. كان منطقياً، والعود أخضر آنذاك، أن أخرج من قاعة العرض متأثراً ببطولات الساموراى.. ليس فقط بسبب القدرة الاستثنائية لإدوارد زويك، المخرج الأمريكى العظيم، على حشد أدواته لإخراج دراما شاعرية تخاطب عاطفة المُشاهِد مباشرةً.. ولكن أيضاً لأن رسالة الفيلم ملأى بالكثير من الدغدغة للمشاعر القومية وبخاصة مع تشابه المأزق الحضارى ومفترق الطرق الذى تمر به \"الأمة\" (كانت أدبيات الإسلام السياسى حاضرة بقوة مع صعوده كمشروع مناهض للهيمنة الغربية مقابل الانبطاح العام للأنظمة السياسية العربية) مع ما مرت به \"الأمة اليابانية\"!\nفى النصف الثانى من القرن التاسع عشر..\n\"الامبراطور شغوف بكل ما هو غربي والساموراي قلقون بشأن ذلك، يعتقدون أن الأمور تجري بسرعة شديدة.. وكأن القديم والحديث يتصارعان لتحديد هوية اليايان\"..\nوبدا محاربو الساموراى بما اتسموا به من قوة وشجاعة ونبل وأصالة وإصرار على خوض معركتهم حتى آخر قطرة دم دفاعاً عن \"هويتهم\".. بدوا أقرب ما يكونون لحركات المقاومة ذات الأيديولوچية الإسلامية والتى تقاتل الأمريكان فى أفغانستان والعراق، ومن قبلهم أشاوس حماس فى فلسطين، إلخ..\nالآن، بعد كل هذه السنوات، وبعد الحدث الكبير فى الألفين وحداشر وما تبعه من تداعيات لم ولن تنته.. يمكننا إعادة مشاهدة الفيلم فى ضوء المسافة الكبيرة التى قُطِعَت داخل الزمان والمكان والدماغ، فماذا سنرى؟..", CategoryId = 1, ImageUrl = "/images/products/9789776376984.webp", Author = "شريف ثابت", PublishDate = new DateTime(2016, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789776376984", Pages = 195, Size = "14×20" },
            new { Id = 309, Name = "حكايات صاحب الصندوق", Price = 150m, Stock = 10, Description = "\"ما أكثر كتب التاريخ المنسية على أرفف مكتباتنا، التي تم هجرانها خوفًا من الموت ضجرًا، نتيجة لأسلوب السرد الأكاديمي الذي لا يطيبُ إلا لمن يهواه فقط، فبغض النظر عن كم الإثارة والمتعة في تقصي أخبار الماضي وتفنيد أحداثه سواء تلك التي تخص أفراد بعينهم أو مجتمعات كاملة، إلا أن طريقة عرض المعلومات نفسها تقتل أي شغف تجاه محاولة استطلاع تلك الكتب، فتُترك على حالها كما هي حتى تذبُل.\nوهذا ما ابتعدت عنه تمامًا عند سردي لأحداث هذا الكتاب ...\nفتعمدّت أن تكون الأحداث التاريخية المذكورة بين دفتيّ هذا الكتاب في نسيج مختلف عن المُعتاد، حيث تدور الأحداث في إطار أدبي أشبه بالرواية، فيبدأ الحديث بـ (يوسف) المهندس الذي ترك مجال الهندسة من أجل شغفه فيما يُسمى بمهنة الـ Fixer Upper، وهو مَن يقوم بشراء المنازل والشقق القديمة ويقوم بتجديدهم وإضافة لمسات عصرية سواء في البنية التحتية للعقار أو الأثاث وخلافه، وهذا ما يستمتع (يوسف) بالقيام به بمساعدة فريقه الخاص، حتى تأتي إليه فرصة تفقد فيلا قديمة معروضة للبيع عبر سمسار عقارات في منطقة الزمالك.\nوهنا يتمكن من العثور على غرفة أرشيف منسية تحت أرضية غرفة المكتب تضم لوحات وتحف فنية قديمة ومقتنيات كانت لصاحب الفيلا سابقًا، ومن ضمن محتويات الغرفة سيجد جرامافون قديم مع صندوق به عدة أسطوانات ومعنون بـ (سري للغاية)، وهنا سيدب الفضول في نفس (يوسف) وسيجرب إحدى الأسطوانات ليجد شخصًا ما يحكي أن لديه وسيلةٍ ما غامضة مكّنته من حضور أحداث تاريخية بنفسه كشاهد عيان لما حدث وقتها وهذا هو ما يسرده الرجل في حكاياته التي سجلها على الأسطوانات إياها.", CategoryId = 3, ImageUrl = "/images/products/9789778202366.webp", Author = "محمد عبدالمحسن", PublishDate = new DateTime(2024, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778202366", Pages = 214, Size = "14×20" },
            new { Id = 310, Name = "لعبة الأسئلة", Price = 110m, Stock = 10, Description = "إختصار لسنين من التجارب والحوارات والنقاشات والخبرات ..اعرف نفسك بشكل أعمق ..إعرف شريك حياتك بكل تفاصيله ...إتناقش مع نفسم او مع شريك حياتك .. في التفاصيل دى.. قرب من نفسك ومن شريك حياتك بشكل سريع", CategoryId = 5, ImageUrl = "/images/products/9789778200577.webp", Author = "أدهم هلالي", PublishDate = new DateTime(2019, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778200577", Pages = 252, Size = "14×20" },
            new { Id = 311, Name = "مايند ست", Price = 180m, Stock = 10, Description = "الحياة بتعدي علينا زي الهوا، سنين العمر بتفوت بين الحزن والخوف والقلق والمشاكل، بنكرر نفس الأخطاء ونقع في نفس دايرة العلاقات المؤذية..\nبندور علي الناس اللي تتعبنا وتوجعنا.. ونلزق فيهم ونديهم مفاتيحنا يبيعوا ويشتروا فينا ويطفونا ويسرقوا عمرنا\nونقنع نفسنا اننا ماتقدرش نعيش منغيرهم...\nعشان نكسر الدايرة دي ونخرج منها عايزين أفكار جديدة مافكرناش فيها قبل كدة..\nوأفعال جريئة ماعملنهاش قبل كدة..\nعايزين نغير الMindset بتاعتنا عشان نلعبها صح ونفرض احنا قوانينا..\nكتاب “ستMind” لكل ست عايزة تعمل Restart وتبتدي حياتها من أول وجديد..", CategoryId = 5, ImageUrl = "/images/products/9789778200829.webp", Author = "ندى ترك", PublishDate = new DateTime(2021, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778200829", Pages = 248, Size = "14×20" },
            new { Id = 312, Name = "قصائد مختارة", Price = 170m, Stock = 10, Description = "يتبوَّأ كمال شودري مكانة خاصة في عالم الشعر البنغالي المعاصر بفضل تفرُّدِه في الأسلوب وغزارته في الإنتاج في مواضيع مختلفة، فعلى مدى العقود الأربعة الماضية، نشر الشاعر ستة عشر ديوانًا شعريًّا سبر من خلالها غور الشعر بكافة أشكاله، وجاء هذا الكتاب الذي بين أيدينا ليتضمن مجموعة حصرية من أعمال الشاعر تحتوي على 125 قصيدة مختارة من عشرة من دواوينه، ترجمها إلى العربية المترجم محمد دباجة.\nتمثل هذه القصائد بالنسبة للشاعر اكتشافًا للذات بقدر ما هي استكشاف للفرح والحزن والمخاوف والدوافع؛ كما تمثل استكشافًا للحياة والموت  والإنسان والطبيعة، وهي تأخذ القارئ وتطوف به خلال رحلة عبر بنغلادش، حاضرها وماضيها – منازلها العادية، حقول أرُزها وضفاف أنهارها ومدنها وبلداتها – لتصل به إلى أبعد من ذلك، إلى صحاري مصر وإلى سافانا كينيا أو إلى زاوية ما في أوروبا أو في أميركا الشمالية.", CategoryId = 8, ImageUrl = "/images/products/9789778201215.webp", Author = "كمال شودري", PublishDate = new DateTime(2022, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778201215", Pages = 240, Size = "14×20" },
            new { Id = 313, Name = "صدام الملوك (الجزء الثاني من اغنية الجليد والنار) سوفت كڤر (العالمي)", Price = 1020m, Stock = 10, Description = "الرواية اللي أسرت قلوب ملايين حول العالم، بترجمة منقَّحة وغلاف جديد كليًّا!\n\n�في «صِدام الملوك»، يواصل چورچ ر. ر. مارتن نسج خيوط ملحمته العظيمة «أغنيَّة الجليد والنَّار».\nبعد موت الملك روبرت باراثيون واللورد إدارد ستارك، تغرق الممالك السَّبع في فوضى عارمة، ويرفع خمسة ملوك راياتهم في صراع لا يرحم على العرش الحديدي، لتبدأ موجة جديدة من الحروب، والتحالفات الغادرة، والعهود التي تُكسر كما تُسفك الدماء.\nفي أراضي النهر والغرب، يخوض روب ستارك معركة تلو معركة للانتقام لأبيه وتأمين مملكته الجديدة.\nوفي العاصمة، يجد تيريُن لانيستر نفسه وسط شبكة معقدة من المؤامرات فيما تستعد المدينة لهجوم ستانِس باراثيون، وتعيش سانزا في قلعة يزداد خطرها يومًا بعد يوم.\nووراء الجدار، يواجه چون سنو تحديات تهدِّد كل ما يعرفه عن الولاء والواجب.\nوفي الشرق في قارَّة أخرى، تواصل دنيرس تارجاريَن رحلتها بين مدن بعيدة، بحثًا عن القوة التى تمكِّنها من استعادة عرش أبيها الضائع.\nومع تصاعد النزاعات، يبدأ صدام هائل سيُعيد رسم خريطة القوة، ويُثبت أن في هذه اللعبة لا مكان للضعفاء، فإمَّا النصر وإمَّا السقوط.", CategoryId = 2, ImageUrl = "/images/products/9789778202946.webp", Author = "چورچ ر.ر مارتن", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778202946", Pages = 1314, Size = "14×20" },
            new { Id = 314, Name = "عاصفة السيوف اغنية الجليد والنار : سوفت كڤر نسخة الشرق الأوسط", Price = 1250m, Stock = 10, Description = "ما زالت حرب الملوك الخمسة مشتعلةً، تعاني ويلاتها جميع أنحاء الممالك السبع إلا قليلًا. على العرش الحديدي يجلس الملك الصبي الغاشم جوفري، فيما يسعى جدّه اللورد تايوين لانستر، يدُ الملك، لتأمين حكمه، ومن ثم تأمين السلطة لعائلة لانستر، مخططًا للقضاء على الملك ستانيس باراثيون الذي خرج مدحورًا من معركة الماء الأسود، وعلى الذئب الصغير روب ستارك الذي يقود حملةً في غرب البلاد رغم أنه فقد وطنه في الشمال.\n\nوفي تلك الأثناء تشقّ الملكة المنفية دينيرس تارجاريَن طريقها في قارّةٍ أخرى تُغرقها الدماء، بغية تحرير مئات الآلاف من العبيد والحصول على جيشٍ تستعيد به مملكتها، ومعها التنانين الثلاثة الحيّة الوحيدة في العالم.\n\nوفي الشمال يتحرّك جيشٌ جرّار من الهمج استعدادًا للهجوم على الجدار وغزو الممالك السبع، جيشٌ انضمّ إليه رجل حرس الليل جون سنو جاسوسًا، ولو أنّ شيئًا أسوأ منه يتقدّم من أقصى الشمال، العدوّ الحقيقي الذي ينشغل عنه الجميع تقريبًا بقتالهم، وقد لا تقدر جيوش الأرض كلّها على ردعه.", CategoryId = 2, ImageUrl = "/images/products/9789778203165.webp", Author = "چورچ ر.ر مارتن", PublishDate = new DateTime(2026, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778203165", Pages = 1534, Size = "14×20" },
            new { Id = 315, Name = "الجناح الرابع نسخه (السوفت كڤر)", Price = 900m, Stock = 10, Description = "في عالم تسيطر عليه التنانين، لا مكان للضعفاء.\nڤيوليت سورينجيل لم يكن مقدّرًا لها أن تصبح فارسة، فضعف جسدها يجعلها فريسة سهلة في أكاديمية باسجياث القاسية، حيث يتدرّب النخبة على ترويض التنانين وخوض الحروب.\n\nلكن حين تُجبر على دخول الأكاديمية، تجد نفسها وسط صراعٍ مميت، حيث لا ينجو سوى الأقوى، والتنانين لا ترحم من يتعثّر.\nومع كل خطوة، تتشابك الخيانات، وتنكشف أسرار قد تهدم المملكة بأكملها.\n\nفهل ستنجح ڤيوليت في البقاء حيّة… أم تكون مجرد رماد على جناح رابع؟", CategoryId = 2, ImageUrl = "/images/products/9789778202991.webp", Author = "ريبيكاياروس", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778202991", Pages = 818, Size = "14×20" },
            new { Id = 316, Name = "مرحلة الإنسحاب", Price = 375m, Stock = 10, Description = "بعد سلسلة من الفقد والصدمات، تجاهد ليك للتأقلم مع حياتها الجديدة، متحملة مسؤولية شقيقها كيل بعد وفاة والديها.\nفي الوقت ذاته يواجه ويل نفس التحدي، إذ يرعى شقيقه الأصغر كولدر ويسعى للحفاظ على علاقته بليك. لكن ضغوط الحياة لا ترحم، الغيرة والشكوك، وظهور أشخاص جدد يختبرون قوة هذا الحب، أمور تدفع العلاقة إلى حافة الانهيار.\nوحين تتعرض ليك لمحنة تهدد حياتها، يكتشف كلاهما أن الحب ليس مجرد مشاعر جميلة، بل التزام يومي وتضحية، وصبر إزاء كل ما تكشفه الحياة من وجوه قاسية.", CategoryId = 4, ImageUrl = "/images/products/9789778202861.webp", Author = "كولين هوڤر", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778202861", Pages = 304, Size = "14×20" },
            new { Id = 317, Name = "حادثة كلب منتصف الليل المثيرة", Price = 375m, Stock = 10, Description = "(كريستوفر) فتى ذكي يتسم بالتوحّد، يعثر على كلب الجيران (ولنجتون) مقتولًا بطريقة غامضة في حديقة السيدة (شيرز).\nتسيء الشرطة فهم تصرفاته فيجد نفسه متهمًا دون قصد، فيقرر أن يبدأ تحقيقه الخاص مثل أبطال روايات الجريمة التي يعشقها.\nلكن ما يبدأ كلغز بسيط، يتحول تدريجيًا إلى رحلة تكشف أسرارًا كبيرة عن عائلته، وأكاذيب لم يكن يتخيل وجودها.\nوبين والده الذي يحاول حمايته - على طريقته - ووالدته التي تتكشَّف له حقيقتها فجأة، يضطر (كريستوفر) إلى مواجهة عالم مربك، مليء بالفوضى والضوضاء.", CategoryId = 1, ImageUrl = "/images/products/9789778202922.webp", Author = "مارك هادون", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778202922", Pages = 338, Size = "14×20" },
            new { Id = 318, Name = "بستان التفاح المخيف (سلسلة رجفه الخوف)", Price = 150m, Stock = 10, Description = "رحلة عائلية إلى الريف، وطفلان مشاكسان لا ينفكَّان عن مضايقة بعضهما بعضًا، وأب وأم يحاولان السيطرة على كلِّ شيء.\nتبدو البداية مُملّة بعض الشيء… أليس كذلك؟\nلكن انتظر قليلًا، حتى تبدأ يدٌ خفيَّة بمطاردتهم بحبَّات التفَّاح، قبل أن يسمعوا بأسطورة الطفلين العالقين في معصرة التفَّاح، ويُحاصرهم سياجٌ خفيّ، ويكتشفون أن هناك حظيرةً مسكونة، وتظهر كؤوس الدماء!\nوفجأة… سيدرك دانيال وسارة أن هناك أبوابًا إذا فُتحت لن تُغلق بسهولة!\nفهل سيجرؤان على فتح أبواب بستان التفَّاح المخيف؟", CategoryId = 9, ImageUrl = "/images/products/9789778203028.webp", Author = "م.د-سبنسر", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778203028", Pages = 154, Size = "14×20" },
            new { Id = 319, Name = "التعويذة الغامضة (سلسلة رجفه الخوف )", Price = 150m, Stock = 10, Description = "عندما تتحوَّل الأُمنيات إلى فخ!\nيُعاني تيمي من التنمُّر والمُضايقات التي لا تتوقَّف، حتى يمَلَّ ويُقرِّر أن يضع حدًا للأمر. وهكذا تقوده قدماه إلى كوخ العرَّافة في الكرنفال، وهناك.. يطلب أمنية واحدة فقط:أن يُصبِح أقوى من الجميع!\nوتتحقَّق الأمنية، لكنها تأتي بثمنٍ باهظ؛ انتصارات خاطِفة، وصداقات تتصدَّع، وحوادث لا تفسير لها.وهنا يسأل تيمي نفسه سؤالًا مهمًّا: هل تكفي القوَّة للتغلُّب على الخوف؟ أم أن الشجاعة الحقيقيَّة تبدأ حين تُحاول التراجُع قبل فوات الأوان؟", CategoryId = 9, ImageUrl = "/images/products/9789778203035.webp", Author = "م.د-سبنسر", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778203035", Pages = 154, Size = "14×20" },
            new { Id = 320, Name = "ثورة الحيوانات (سلسلة رجفه الخوف)", Price = 150m, Stock = 10, Description = "حين تتحوَّل الإجازة إلى لعنة!\nعندما يذهب بطل روايتنا لقضاء إجازة ريفيّة مع ابن عمّه، تبدأ الحكاية بمقالب ثقيلة وخدع لا تنتهي، قبل أن تُغيِّر لعبة كمبيوتر غامضة تُدعى «قتلة الحيوانات» كلَّ شيء.\nومن تلك اللحظة ينقلب الريف الهادئ، وتثور الحيوانات على البشر، وتتجمع ليلًا كأنها تحيك خططًا للانقلاب عليهم.\nويزداد التوتر حين يرى بطلنا ما لا يراه الآخرون، ويكتشف أن مصدر الفوضى ليس في حظيرة الحيوانات، بل في أمرٍ آخر لم يخطر على بال أحد!\nويقع الأمر كلّه على عاتقه… لمواجهة ثورة الحيوانات!", CategoryId = 9, ImageUrl = "/images/products/9789778202885.webp", Author = "م.د-سبنسر", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778202885", Pages = 136, Size = "14×20" },
            new { Id = 321, Name = "إعصار بلا قرار", Price = 420m, Stock = 10, Description = "رحلة مثيرة تبدأ على متن يخت يملكه رجل لا يرحم يُدعى مايك راسل، حيث يُحتجز أسرى من جزيرة غامضة.\nوسط الضباب والعتمة، يقرر آدم، الغريب القادم من وراء البحار، أن يخاطر بكل شيء لتحريرهم، بمساعدة الطفلة الجريئة ريحان.\nلكن الهروب ليس سوى البداية...\nفالصراع يشتعل بين المحتلّ الطامع في السيطرة وحماة الجزيرة الصامدين، فيما يواصل آدم محاولة التّحكم في قدراته، وتقبّل الدّور المحوريّ الذي بات عليه تحمّله لمواجهة الخطر القادم\nفي الجهة الأخرى تعمل مانويلا، ابنة مايك، على خططها الخاصة بمساعدة من العالِمة كلاوديا، حيث يتشابك السّبق العلمي بلعبة المصالح الخبيثة\nومع تصاعد الأحداث، يقف الجميع على حافة مواجهة حاسمة، حيث لا أحد يعرف من سيبقى، ومن ستجرفه رياح الإعصار..", CategoryId = 2, ImageUrl = "/images/products/9789778203004.webp", Author = "خولة حمدي", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778203004", Pages = 504, Size = "14×20" },
            new { Id = 322, Name = "A storm with no rest", Price = 420m, Stock = 10, Description = "A thrilling journey begins aboard a yacht owned by a ruthless man named Mike Russell, where captives from a mysterious island are being held.\nAmid the fog and darkness, Adam — a stranger from across the seas — decides to risk everything to set them free, aided by the bold young girl, Rayhan.\nBut escape is only the beginning...\nConflict soon erupts between the greedy invader seeking domination and the steadfast guardians of the island, while Adam struggles to master his powers and accept the pivotal role he must play in facing the looming threat.\n\nMeanwhile, Manuela, Mike’s daughter, pursues her own agenda with the help of scientist Claudia, where scientific breakthroughs intertwine with a dangerous game of hidden interests.\nAs events escalate, all find themselves standing at the brink of a decisive confrontation, where no one knows who will survive, and who will be swept away by the storm", CategoryId = 2, ImageUrl = "/images/products/9789778203011.webp", Author = "خولة حمدي", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778203011", Pages = 566, Size = "14×20" },
            new { Id = 323, Name = "jerusalem epitles", Price = 600m, Stock = 10, Description = "Jerusalem is not merely a city—it is a confluence of spiritual, national, and cultural dimensions, interwoven with historical and existential significance. It is not merely a holy city revered through the ages but a divine and universal message, a living testament to history that reaches into the depths of time. Jerusalem is inseparable from Palestine—its land, its people, and its enduring Arab identity.", CategoryId = 7, ImageUrl = "/images/products/9789978203059.webp", Author = "السعيد أبو علي", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789978203059", Pages = 580, Size = "14×20" },
            new { Id = 324, Name = "سماء بلا ضياء", Price = 420m, Stock = 10, Description = "عندما يستيقظ آدم في جزيرة لا تظهر على أي خريطة، مغطاة بسماء لا ترى فيها الشمس، يجد نفسه في قلب لغز قديم وقوة خارقة تختبر أصله ومصيره.\nبين شعب غامض، وحجر يشفي ويدمر، وصراع لا مهرب منه—يكتشف أن ماضي والده مرتبط بمستقبل الجزيرة... وببقائه حيًّا.", CategoryId = 2, ImageUrl = "/images/products/9789778202670.webp", Author = "خولة حمدي", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778202670", Pages = 496, Size = "14×20" },
            new { Id = 325, Name = "أرني أنظر إليك", Price = 300m, Stock = 10, Description = "تُروى قصة شاب تونسي يُدعى مالك، الذي نشأ على التقاليد الإسلامية، ثم اعتُقل.\nاتخذ قرار السفر، ونسيان آلام الاحتجاز، فهاجر بطريقة غير شرعية ليبدأ رحلة جديدة ملؤها النضال، نضال مختلف؛ صراع فكري بين ما عرفه طوال حياته والثقافة السائدة، حتى وجد نفسه على حافة الإلحاد قبل أن يكتشف الطريق الصحيح.", CategoryId = 4, ImageUrl = "/images/products/9789778200645.webp", Author = "خولة حمدي", PublishDate = new DateTime(2020, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778200645", Pages = 430, Size = "14×20" },
            new { Id = 326, Name = "مويرد ألماس", Price = 390m, Stock = 10, Description = "خرج هابيل لانوثا من مركز الأمراض النفسية وهو يأمل أن يستعيد حياته السابقة مع زوجته وابنه وأصدقاءه، لكنه يجد خاله قد توفي وترك له ميراث عبارة عن بيت وأرض في قرية مويردِألماس.. وهي قرية معزولة عن العالم لها قواعدها الخاصة والتي فرضتها عائلة أوسِّت. يقرر هابيل لعيش هناك لفترة هو وعائلته في محاولة منه للتعافي وتذكر الماضي الذي كان بالنسبة له لغز كبير. لكن تحدث الكثير من المشكلات وتتكشف العديد من المفاجآت.", CategoryId = 3, ImageUrl = "/images/products/9789778202724.webp", Author = "سانتياجو آلبارِث", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778202724", Pages = 414, Size = "14×20" },
            new { Id = 327, Name = "لعبة العروش - أغنية الجليد والنار (النسخة العالمية)", Price = 990m, Stock = 10, Description = "«مارتن حكَّاء بالفطرة وخياله واحد في المليون. المسلسل المأخوذ عن سلسلته رائع، لكن الكُتب أفضل كثيرًا». – ستيڤن كينج\n\n«نجحت سلسلة مارتن الخيالية في إشعال خيال الملايين للسَّبب نفسه الذي جعل أعمال هوميروس وسفوكوليس وشيكسپير تدوم عصورًا». – الجارديان\n\n«مارتن الأفضل على الإطلاق بين من يكتبون في مجال الفانتازيا الملحميَّة في العصر الحالي، ولا مبالغة في وصفه بأنه تولكين الأمريكي». – تايم\n\n«موهبة مارتن في الحكي تكاد تكون خارقةً للطَّبيعة». – نيويورك تايمز\n\nفي «لُعبة العروش» يبدأ چورچ ر. ر. مارتن ملحمته الكُبرى «أغنيَّة الجليد والنَّار»، صانعًا تُحفةً أصيلةً تحوي أفضل ما في أدب الفانتازيا من تشويقٍ وغموض ومغامرة على مستوًى يتجاوز الواقع إلى رحاب الخيال الخصب، ومع ذلك لا يقلُّ واقعيَّةً عن أيٍّ من القصص الإنسانيَّة الأخرى، وهو ما أوقعَ ملايين من عُشَّاق الفانتازيا حول العالم في غرام كتابته.\nفي عالمٍ يدوم فيه الصَّيف أعوامًا والشِّتاء عُمرًا بأكمله، تبدأ سُلطة الملك الحاكم في الجنوب تتداعى بعد الظروف الغامضة المحيطة بموت يده اليُمنى الذي خدمه طويلًا بإخلاص، فلا يجد خيارًا إلَّا اللُّجوء إلى أوفى أصدقائه وآخرهم ليعاونه على حُكم البلاد، ويُقرِّر الصَّديق القبول ليَعثُر على حقيقة موت الرَّجل الذي كان بمثابة أبٍ لهما. وفيما تهبُّ الرِّياح الباردة من الشَّمال منذرةً بعودة خطرٍ قديم يُهدِّد بهلاك العالم كلِّه، تدور في قلعة الحُكم عجلة المؤامرات والمكايد بين الحُلفاء والأعداء، ويبدأ صراعٌ جديد على العرش الحديدي. لكن في لُعبة العروش لا تُوجَد منطقةٌ وُسطى، فإمَّا أن تفوز وإمَّا أن تموت.", CategoryId = 2, ImageUrl = "/images/products/9789778202557.webp", Author = "جورج ر . ر مارتن", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778202557", Pages = 1208, Size = "14×20" },
            new { Id = 328, Name = "فارس من الممالك السبع", Price = 450m, Stock = 10, Description = "من أكثر الكتب مبيعًا بحسب نيويورك تايمز • تدور أحداثه قبل قرن تقريبًا من أحداث \"لعبة العروش\"، حيث يجمع \"فارس الممالك السبع\" أول ثلاث روايات قصيرة رسمية مسبقة لعمل جورج ر. ر. مارتن الدائم \"أغنية الجليد والنار\".\n\nوقد تم تسميته كأحد أفضل الكتب لهذا العام من قبل \"لوس أنجلوس تايمز\" و\"باز فيد\".\n\nتروي هذه المغامرات، التي لم تُجمّع من قبل، عصرًا كان فيه خط تارغارين لا يزال يعتلي العرش الحديدي، ولم تزل ذاكرة آخر تنين حيّة في الوعي. قبل تيريون لانيستر وبودريك بين، كان هناك دانك وإيگ. فارس شاب ساذج لكنه شجاع في نهاية المطاف، سير دانكن الطويل يتفوق على خصومه من حيث القامة إن لم يكن الخبرة. يرافقه رفيقه الصغير، ولد يُدعى إيگ—الاسم الحقيقي له مخفي عن كل من يصادفانه. ورغم أن أبطالاً أكثر غرابة قد لا نجدهم في جميع أنحاء ويستروس، فإن مصائر عظيمة تنتظر هذين الاثنين، إلى جانب أعداء أقوياء ومكائد ملكية ومغامرات فذة.\n\nوبفضل أكثر من 160 رسماً جديداً من إبداع جاري جياني، يُعدّ \"فارس الممالك السبع\" مجموعة لا غنى عنها تثبت أن الفروسية لم تمت بعد—على الأقل ليس بعد.\n\nالقراء الذين يعشقون مارتن وقدرته على استخراج الدراما الإنسانية الحسية من أي قصة، سيسرون برؤية هذه الثلاثية مجمعة ومعززة بحياة إضافية.» — Booklist\n«السبب الحقيقي لاستكشاف هذه المجموعة هو أنها ببساطة سرد رائع؛ يصنع مارتن عالمًا حيًا ونابضًا بطريقة لا يستطيعها سوى عدد قليل من الكتاب... [رسومات جياني] تُحيي أحداث الروايات القصيرة بأسلوب بديع.» — Tech Times\n«مثير... كما لدى تولكين ملحمته \"السيلمارليون\"، فإن [جورج ر. ر.مارتن]  يمتلك هذه الثلاثية من القصص التأسيسية؛ فهي تنجح بمفردها، وبالإضافة إلى ذلك، تجعل المعجبين يتوقون للمزيد.» — Kirkus Reviews\n«مغامرة فانتازيا خالصة، مع اثنين من أكثر الشخصيات الرئيسية التي أحبها مارتن على الإطلاق.» — Bustle\n«قراءة لا غنى عنها لعشاق مارتن... مقدمة مثيرة لسلسلة \"أغنية الجليد والنار\" الأكثر مبيعًا، غنية بالدراما الإنسانية وبناء العالم الملون الذي يميز باقي كتب السلسلة.» — Publishers Weekly", CategoryId = 2, ImageUrl = "/images/products/9789778202441.webp", Author = "جورج ر.ر مارتن", PublishDate = new DateTime(2024, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778202441", Pages = 536, Size = "14×20" },
            new { Id = 329, Name = "النار والدم (مجلدين)", Price = 890m, Stock = 10, Description = "بكل النيران والغضب الذي تعود عليه الجماهير من الكاتب الدولي الأكثر مبيعًا، جورج ر. ر. مارتن، يأتي هذا المجلد الأول من التاريخي القطعي ذو الجزأين لعائلة تارجارين في ويستروس.\n\nقبل قرون من أحداث \"لعبة العروش\"، استقر بيت تارجارين—العائلة الوحيدة من أمراء التنانين التي نجت من كارثة فاليريا—في \"دراجونستون\". تبدأ \"النار والدم\" قصتهم مع الأسطورة أيغون الفاتح، مبتكر العرش الحديدي، وتتابع سرد أجيال تارجارين الذين قاتلوا للحفاظ على هذا المقعد الأيقوني، وصولًا إلى الحرب الأهلية التي كادت أن تمزق سلالتهم.\n\nما الذي حدث حقًا خلال \"رقصة التنانين\"؟ ولماذا أصبحت زيارة فاليريا مميتة بعد الكارثة؟ وما أصل بيض التنانين الثلاثة لدى دانيريس؟ هذه بعض الأسئلة التي يُجيب عليها هذا السجل الحيوي، كما يرويها معلم حكيم من \"السيتاديل\"، ويضم أكثر من ثمانين رسماً بالأبيض والأسود من إبداع الفنان دوج ويتلي. لقد أطلّع القراء على لمحات من هذا السرد في مجلدات مثل \"عالم الجليد والنار\"، لكن الآن، ولأول مرة، يُكشف النقاب عن النسيج الكامل لتاريخي تارجارين.\n\nبكل عظمة وشمولية \"تاريخي انهيار وسقوط الإمبراطورية الرومانية\" لجِبون، يُعدّ \"النار والدم\" اللعبة النهائية للعروش، مانحًا القراء تقديرًا جديدًا للتاريخي الديناميكي، غالبًا داميًا ودائم الإثارة لويستروس.", CategoryId = 2, ImageUrl = "/images/products/9789778201321.webp", Author = "چورچ ر.ر مارتن", PublishDate = new DateTime(2022, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778201321", Pages = 968, Size = "14×20" },
            new { Id = 330, Name = "عجله الزمن-الصيد العظيم", Price = 875m, Stock = 10, Description = "الكاتبة الحائزة على لقب نيويورك تايمز الأفضل مبيعًا، والتي أبهرت القرّاء بروايتها ميؤوس منه، قصة ما\nحدث عندما التقت الفتاة المضطربة سكاي مع صديق طفولتها الذي فقدته منذ زمن طويل، دين هولدر.\nبمساعدة دين هولدر، كشفت سكاي عن أسرار عائلية صادمة وتصالحت مع ذكريات وعواطف خلّفت\nجروحًا عميقة.\nميئوس منه كانت قصة سكاي. والآن، في رواية فقدان الأمل، نتعرف أخيرًا على حقيقة &quot;دين هولدر&quot;.\nيعيش هولدر حياة مظلمة بسبب الطفلة الصغيرة التي لم يتمكن من إنقاذها من الخطر الوشيك، وتغمره\nمشاعر الذنب والندم. لم يتوقف هولدر عن البحث عنها، يعتقد أن العثور عليها سيجلب له السلام الذي\nيحتاجه للتقدّم في الحياة. ومع ذلك، لم يكن هولدر يتوقع أن يواجه المزيد من الألم في لحظة لقائهما مجددًا.\nفي رواية فقدان الأمل يكشف هولدر طريقة تأثير أحداث طفولة &quot;سكاي&quot; عليه وعلى عائلته، مما دفعه إلى\nالبحث عن الفداء من خلال إنقاذها. ولكنه فقط حب سكاي الذي يمكنه من البدء في شفاء نفسه.", CategoryId = 2, ImageUrl = "/images/products/9789778202564.webp", Author = "روبرت چوردان", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778202564", Pages = 994, Size = "14×20" },
            new { Id = 331, Name = "عجلة الزمن - عين العالم (مجلدين)", Price = 830m, Stock = 10, Description = "تدور عجلة الزمن وتأتي الأعمار وتذهب، تاركةً وراءها ذكريات تتحول إلى أسطورة. تتلاشى الأسطورة لتصبح خرافة، وحتى الخرافة تُنسى عندما يعود العصر الذي أنبتها. ما كان، وما سيكون، وما هو عليه الآن، قد يقع جميعه تحت ظل الظلام.\n\nتصل مويرين دامودرِد إلى \"حقول إيموند\" في مهمة للعثور على المنبأ عنه الذي سيقف ضد \"الظلام المطلق\"، ذلك الكيان الخبيث الذي يزرع بذور الفوضى والدمار. وعندما يغزو فريق شرير من نصف بشر ونصف وحوش القرية باحثين عن عدو سيدهم، تقنع مويرين راند آل ثور وأصدقائه بترك ديارهم والدخول إلى عالم أكبر لا يُتصوَّر، مليء بالمخاطر التي تكمن في الظلال والنور.", CategoryId = 2, ImageUrl = "/images/products/9789778201604.webp", Author = "روبرت چوردان", PublishDate = new DateTime(2023, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778201604", Pages = 1104, Size = "14×20" },
            new { Id = 332, Name = "ليلى (النسخة العالمية)", Price = 390m, Stock = 10, Description = "من الكاتبة كولين هوفر، تأتي رواية تستكشف الحياة بعد المأساة وروح الحب الدائمة.\n\nعندما يلتقي ليدز بليلى، يقتنع بأنه سيقضي بقية حياته معها—حتى يحدث هجوم غير متوقع يترك ليلى تكافح من أجل بقائها. وبعد أسابيع من العلاج في المستشفى، تتعافى ليلى جسديًا، لكن الندوب العاطفية والعقلية قد غيَّرت المرأة التي أحبها ليدز. ومن أجل إعادة علاقتهما إلى مسارها الصحيح، يأخذ ليدز ليلى إلى النزل الذي التقيا فيه لأول مرة. وما إن يصلان، حتى يأخذ سلوك ليلى منعطفًا غريبًا، وهذا مجرد واحد من العديد من الأحداث الغامضة.\n\nشعر ليدز بأن ليلى باتت بعيدة عنه، فوجد العزاء في \"ويلو\"—ضيف آخر في النزل يتشاركان الهموم. ومع ازدياد فضوله تجاه \"ويلو\"، يضعه رغبته في مساعدتها على إيجاد إجابات في مواجهة مباشرة مع رفاهية ليلى. وسرعان ما يدرك ليدز أنه عليه أن يختار بينهما، إذ لا يستطيع مساعدة كلاهما، وإن اتخذ قرارًا خاطئًا، فقد يكون ذلك مدمّرًا للجميع.", CategoryId = 4, ImageUrl = "/images/products/9789778201635.webp", Author = "كولين هوڤر", PublishDate = new DateTime(2024, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778201635", Pages = 400, Size = "14×20" },
            new { Id = 333, Name = "ينتهي معنا (النسخة العالمية)", Price = 470m, Stock = 10, Description = "في بعض الأحيان، يكون من تحبك هو من يؤذيك أكثر.\n\nلم تكن حياة ليلي مفروشة بالورود دومًا، لكن ذلك لم يمنعها يومًا من الكفاح من أجل الحياة التي تطمح إليها. لقد قطعت شوطًا طويلًا منذ بلدة صغيرة في مين حيث نشأت؛ فقد تخرجت من الجامعة، وانتقلت إلى بوسطن، وأسست مشروعها الخاص. وعندما تشعر بشرارة مع جراح أعصاب وسيم يُدعى رايل كينكيد، يبدو كل شيء في حياتها وكأنه خير يفوق الخيال.\n\nرايل شخص حازم وعنيد وربما متعجرف بعض الشيء، لكنه أيضًا حساس وعبقري ولديه ميول حنونة تجاه ليلي؛ وطريقته في الزي الطبي تزيده جاذبية. لا تستطيع ليلي إخراجه من أفكارها، لكن نفوره المطلق للعلاقات يثير قلقها. وبينما تجد نفسها استثناءً من قاعدته الصارمة، تتساءل دومًا عما الذي جعل رايل هكذا منذ البداية.\n\nوبينما تغمرها التساؤلات حول علاقتها الجديدة، تتسلل إلى ذهنها أيضًا ذكريات أطلس كورريغان—حبها الأول وصلةً بالماضي الذي تود أن يبقى منسيًّا. كان هو روحها التوأم وحاميها، ومع ظهور أطلس فجأة، تتعرض كلُّ ما بنت ليلي مع رايل للخطر.", CategoryId = 4, ImageUrl = "/images/products/9789778202212.webp", Author = "كولين هوڤر", PublishDate = new DateTime(2023, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778202212", Pages = 480, Size = "14×20" },
            new { Id = 334, Name = "ما يذكرني بك", Price = 385m, Stock = 10, Description = "تحلم أم شابة تعاني من الاضطراب بالحصول على فرصة للتكفير عن أخطائها في هذه القصة المؤلمة المفعمة بالأمل، من تأليف كاتبة نيويورك تايمز الأكثر مبيعًا، كولين هوفر. بعد قضائها خمس سنوات في السجن نتيجة خطأ مأساوي، تعود كينا روان إلى المدينة التي ساءت فيها الأمور، على أمل أن تعيد لم شملها مع ابنتها الصغيرة البالغة من العمر أربع سنوات.\n\nلكن الجسور التي حرقتها كينا تبدو مستحيلة الإصلاح؛ فكل من له علاقة بحياة ابنتها مصمم على إغلاق الأبواب أمامها، مهما بذلت من جهد لإثبات جدارتها. والوحيد الذي لم يُغلق الباب أمامها تمامًا هو ليجر وارد، صاحب حانة محلية وواحد من الروابط القليلة المتبقية مع ابنة كينا. لكن إن اكتشف أحد كيف أصبح ليجر تدريجيًا جزءًا مهمًا من حياة كينا، فإنهما كلاهما سيخاطران بفقدان ثقة كل من يهمه أمرهما. تشكل الشخصيتان رابطًا رغم الضغوط المحيطة بهما، ومع نمو علاقتهما الرومانسية، يتزايد الخطر؛ فيجب على كينا أن تجد وسيلة لتكفير أخطاء ماضيها من أجل بناء مستقبل ينبض بالأمل والشفاء.", CategoryId = 4, ImageUrl = "/images/products/9789778201352.webp", Author = "كولين هوڤر", PublishDate = new DateTime(2023, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778201352", Pages = 422, Size = "14×20" },
            new { Id = 335, Name = "الذي اضاءه نور الشمس", Price = 750m, Stock = 10, Description = "منذ سنوات مضت، كان لديه رفاق سلاح، وقضية يؤمِن بها، لكِن الآن، الرجُل الذي يُطلِق على نفسه اسم (نوماد)، لا يعرِف سوى حياة الهروب.\nيُجبَر (نوماد) على القفز من عالمٍ إلى آخرٍ ضمن كون (كوزمير)، وتُطارده (سرية الليل) القاسية للغاية، وتبدأ أحداث روايتنا عندما يهبط على كوكبٍ جديد، وسُرعان ما يجِد نفسه مُحاصرًا على الفور وسط صراع بين طاغية والمُتمرِّدين الذي لا يُريدون سوى الهروب من التحوُّل إلى عبيد لديه. وكُل ذلِك تحت التهديد المُستمِر لشروق الشمس الذي ستؤدي حرارته إلى إذابة الحجارة.\nلكِنه غير قادِر على فهم لُغتهم!\nهل يستطيع مواصلة الصراع، واكتساب القوّة الكافية للقفز خارِج العالم، قبل أن يدفع جسده أو عقله الثمن النهائي؟", CategoryId = 2, ImageUrl = "/images/products/9789778202496.webp", Author = "براندون ساندرسون", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778202496", Pages = 596, Size = "14×20" },
            new { Id = 336, Name = "يومي ورسام الكوابيس - عالم كوزمير", Price = 790m, Stock = 10, Description = "تدور الرواية حول شخصيتين رئيسيتين، يومي والرسام، الذين ينحدران من عالمين\nمختلفين تمامًا، حيث يعيش الرسام في مدينة يكتنفها الظلام والكوابيس لكنها أكثر تطورًا\nمقارنةً ببلدة يومي التي تتميَّز بحدائقها ولكن أهلها يعتمدون كليًا في حياتهم على\nالأرواح. \nتتداخل حياتهما بطرقٍ غامضة عبر تبادلٍ غريبٍ للأجساد عندما ينامان. لذلك يتعيَّن على\nيومي والرسام أن يتعلَّما التكيُّف مع أدوارهما الجديدة في عوالم بعضهما البعض. وبينما\nيحاولان حل أسرار وضعهما المُلتبِس في رحلاتهما العجيبة تلك، يكتشفان الحقائق\nالمخفية حول عالميهما والقوى الشريرة التي تسيطر عليهما؛ فيشرعان معًا في مهمة\nلإنقاذ مجتمعات بعضهما بعضًا من الانزلاق إلى الهاوية. \nوكعادة روايات براندون ساندرسون ذات الطابع الخيالي في عالم كوزمير، تتناول\nالرواية موضوعات الهوية واستكشاف الذات والتحرر فضلًا عن التعاون في سبيل أداء\nالواجب.", CategoryId = 2, ImageUrl = "/images/products/9789778202519.webp", Author = "براندون ساندرسون", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778202519", Pages = 612, Size = "14×20" },
            new { Id = 337, Name = "فتاة بحر الزمرد ( هارد كڤر )", Price = 730m, Stock = 10, Description = "لم تعرف تريس في جزيرتها المحاطة بمحيطٍ بلون الزمرد سوى الحياة البسيطة، حيث كانت تستمتع بتجميع الأكواب التي يجلبها البحارة من أراضٍ بعيدة والاستماع إلى قصص صديقها تشارلي.\nولكن، عندما انطلق والدها في رحلة للعثور على عروس واندلعت الكارثة، اضطرت تريس للاختباء على متن سفينة والسعي للعثور على الساحرة في بحر منتصف الليل المميت.\nوسط محيطات مليئة بالأبواغ يعج بها القراصنة، هل تستطيع تريس أن تودع حياتها البسيطة وتصنع لنفسها مكانًا في بحر قد تُميت قطرة ماء منه في لحظة؟", CategoryId = 3, ImageUrl = "/images/products/9789778201567.webp", Author = "براندون ساندرسون", PublishDate = new DateTime(2023, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778201567", Pages = 578, Size = "14×20" },
            new { Id = 338, Name = "دليل الساحر المقتصد للنجاة في انجلترا في القرون الوسطى", Price = 410m, Stock = 10, Description = "يستفيق رجل في فسحة مفتوحة بما يشبه إنجلترا العصور الوسطى، دون أن يتذكر من هو، أو من أين أتاه، أو لماذا وُضع في هذا المكان.\nيطارُه أعداء من زمنه، وحيد الأمل في نجاته يكمن في استرجاع ذكرياته المفقودة، وكسب حلفاء من السكان المحليين، وربما الثقة بتلك الخرافات التي يرددونها.\nوكانت مساعدته الوحيدة من \"العالم الحقيقي\" في دليل بعنوان \"دليل الساحر الاقتصادي للبقاء في إنجلترا العصور الوسطى\"، لكن نسخته انفجرت أثناء النقل. القليل من الشظايا التي نجاها تكشف له عن معالم وضعه، فهل سيتمكن من فك طلاسمها قبل فوات الأوان؟", CategoryId = 3, ImageUrl = "/images/products/9789778201628.webp", Author = "براندون ساندرسون", PublishDate = new DateTime(2024, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778201628", Pages = 448, Size = "14×20" },
            new { Id = 339, Name = "إينولا هولمز وقضية إختفاء الماركيز", Price = 170m, Stock = 10, Description = "عندما تكتشف إينولا هولمز، الأخت الصغرى لشيرلوك هولمز، اختفاء والدتها في يوم عيد ميلادها الرابع عشر، تعلم أنها الوحيدة القادرة على العثور عليها.\nمتنكرةً في هيئة أرملة مفجوعة، تنطلق إينولا إلى قلب لندن لتكشف عن مصير والدتها، ولكن حتى اسم \"هولمز\" لا يمكن أن يجهزها لما ينتظرها.\nوفجأةً، تتورط في اختطاف ماركيز باسيولويذر الشاب؛ فتعلم أنها عليها الفرار من الأشرار القاتلين، وتحرير الماركيز المدلل، والأهم من ذلك، التملص من أخيها الأكبر الفطن، بينما تجمع الأدلة حول اختفاء والدتها.\nمنسوجةً بصوت وجو شوارع لندن الفيكتورية المليئة بالفئران، تقدم هذه الرواية المثيرة والذكية لعشاق الغموض أفضل ما في هذا النوع الأدبي.", CategoryId = 3, ImageUrl = "/images/products/9789778200737.webp", Author = "نانسي سبرينجر", PublishDate = new DateTime(2020, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778200737", Pages = 268, Size = "10×17" },
            new { Id = 340, Name = "إينولا هولمز وقضية السيدة العسراء", Price = 160m, Stock = 10, Description = "إذا قلبنا اسم إينولا، نحصل على \"وحيدة\"، وهي كذلك؛ وحيدة في أكبر وأظلم وأوسخ مدينة في العالم.\nإنها مطاردة من قبل أشهر محقق عالمي—أخوها شيرلوك هولمز. ومن أجل الحرية، يجب عليها التملص منه، لكن ماذا يمكنها أن تفعل لتخفيف وطأة وحدتها؟\nحينما تكتشف مخبأً سريًا لرسومات فحمية بديعة، تشعر وكأنها رفيقة الروح للفتاة التي رسمتها، لكنها تكتشف أن تلك الفتاة، السيدة الصغيرة سيسيلي، اختفت دون أثر.\nمتجاوزةً شوارع منتصف الليل التي يجوبها القتلة، يتوجب على إينولا فك رموز الأدلة—سلم مائل، وبائع عيان مخادع، وكتيبات سياسية—للعثور على السيدة اليسارية، لكنها تخاطر بكشف أسرارها أكثر مما ينبغي لإنقاذ السيدة سيسيلي من شرير عظيم.\nهل سينقلب عليها قلبها الوحيد في نهاية المطاف؟\nفي هذا الجزء الثاني من سلسلة \"أسرار إينولا هولمز\" الشهيرة، تُقدم لنا نانسي سبرينجر، الحائزة مرتين على جائزة إدغار، كلّ الدهشة والتشويق في لندن الفيكتورية، مستمرةً بمغامرات إحدى أذكى وأروع البطلات في الأدب المعاصر.", CategoryId = 3, ImageUrl = "/images/products/9789778201260.webp", Author = "نانسي سبرينجر", PublishDate = new DateTime(2023, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778201260", Pages = 206, Size = "10×17" },
            new { Id = 341, Name = "مذكرات حمقاء \" حكايات فتاة ليست سعيدة جدًا \"", Price = 300m, Stock = 10, Description = "إنها نسخة من \"Diaries of a wimpy kid\" للفتيات في هذه الرواية الفكاهية!\n\nوصفة الكارثة: 4 حفلات؛ أضف صديقتين وفتاة تُعجبك؛ اقسم على فتاة شريرة عازمة على تدمير نيكي؛ امزج جيدًا، وضع أصابعك على عينيك، واستعد للشعور بالإحراج الشديد.\nكنت أظن أن هذا لن يحدث أبدًا، لكن حياتي بدأت أخيرًا تسير في طريق النجاح.\nأنا أتكيف مع مدرستي الجديدة وأقضي وقتي مع أفضل صديقاتي، كلوي وزوي. وتخيلوا! فقد طلب مني معجبِي، براندون، أن أكون شريكته في المختبر—خطوة رائعة حقًا.\nلكن، عندما أسمع فتاة شريرة تُدعى ماكنزي تتفاخر بأن براندون سيأخذها إلى رقصة الهالوين، يغمرني شعور بالحزن الشديد، فيتوجب عليّ التسجيل لقضاء الهالوين في حفلة أطفال مع أختي الصغيرة المشاكسة، بريانا.\nلحسن حظي، اكتشفت أن ماكنزي تكذب، وقد يتحقق حلمي بالذهاب إلى الحفلة مع براندون! لكن، هل أستطيع التوفيق بين حدثين في نفس الوقت والبقاء سالمة وسط سلسلة من المحن والتجارب والكوارث؟! النجدة!!!", CategoryId = 2, ImageUrl = "/images/products/9789778201437.webp", Author = "ريتشل رينية", PublishDate = new DateTime(2023, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778201437", Pages = 338, Size = "14×20" },
