            new { Id = 345, Name = "مذكرات حمقاء - فتاة تعرف كل شئ ليست ذكية جدا", Price = 300m, Stock = 10, Description = "إنها نسخة من \"Diaries of a wimpy kid\" للفتيات في هذه الرواية الفكاهية!\n\nوصفة الكارثة: 4 حفلات؛ أضف صديقتين وفتاة تُعجبك؛ اقسم على فتاة شريرة عازمة على تدمير نيكي؛ امزج جيدًا، وضع أصابعك على عينيك، واستعد للشعور بالإحراج الشديد.\nكنت أظن أن هذا لن يحدث أبدًا، لكن حياتي بدأت أخيرًا تسير في طريق النجاح.\nأنا أتكيف مع مدرستي الجديدة وأقضي وقتي مع أفضل صديقاتي، كلوي وزوي. وتخيلوا! فقد طلب مني معجبِي، براندون، أن أكون شريكته في المختبر—خطوة رائعة حقًا.\nلكن، عندما أسمع فتاة شريرة تُدعى ماكنزي تتفاخر بأن براندون سيأخذها إلى رقصة الهالوين، يغمرني شعور بالحزن الشديد، فيتوجب عليّ التسجيل لقضاء الهالوين في حفلة أطفال مع أختي الصغيرة المشاكسة، بريانا.\nلحسن حظي، اكتشفت أن ماكنزي تكذب، وقد يتحقق حلمي بالذهاب إلى الحفلة مع براندون! لكن، هل أستطيع التوفيق بين حدثين في نفس الوقت والبقاء سالمة وسط سلسلة من المحن والتجارب والكوارث؟! النجدة!!!", CategoryId = 2, ImageUrl = "/images/products/9789778201451.webp", Author = "ريتشل رينية", PublishDate = new DateTime(2024, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778201451", Pages = 332, Size = "14×20" },
            new { Id = 346, Name = "مذكرات حمقاء - محطمة قلوب ليست سعيدة جدا", Price = 300m, Stock = 10, Description = "إنها نسخة من \"Diaries of a wimpy kid\" للفتيات في هذه الرواية الفكاهية!\n\nوصفة الكارثة: 4 حفلات؛ أضف صديقتين وفتاة تُعجبك؛ اقسم على فتاة شريرة عازمة على تدمير نيكي؛ امزج جيدًا، وضع أصابعك على عينيك، واستعد للشعور بالإحراج الشديد.\nكنت أظن أن هذا لن يحدث أبدًا، لكن حياتي بدأت أخيرًا تسير في طريق النجاح.\nأنا أتكيف مع مدرستي الجديدة وأقضي وقتي مع أفضل صديقاتي، كلوي وزوي. وتخيلوا! فقد طلب مني معجبِي، براندون، أن أكون شريكته في المختبر—خطوة رائعة حقًا.\nلكن، عندما أسمع فتاة شريرة تُدعى ماكنزي تتفاخر بأن براندون سيأخذها إلى رقصة الهالوين، يغمرني شعور بالحزن الشديد، فيتوجب عليّ التسجيل لقضاء الهالوين في حفلة أطفال مع أختي الصغيرة المشاكسة، بريانا.\nلحسن حظي، اكتشفت أن ماكنزي تكذب، وقد يتحقق حلمي بالذهاب إلى الحفلة مع براندون! لكن، هل أستطيع التوفيق بين حدثين في نفس الوقت والبقاء سالمة وسط سلسلة من المحن والتجارب والكوارث؟! النجدة!!!", CategoryId = 2, ImageUrl = "/images/products/9789778201413.webp", Author = "ريتشل رينية", PublishDate = new DateTime(2024, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778201413", Pages = 352, Size = "14×20" },
            new { Id = 347, Name = "سلسة سجلات القمر - سندر", Price = 370m, Stock = 10, Description = "يكتظ شوارع بكين الجديدة الصاخبة بالبشر والآليون معًا، فيما ينهب طاعون قاتل السكان. ومن الفضاء، يراقب شعب قمري لا يرحم، منتظرًا اللحظة المناسبة لشن هجومه. لا أحد يدرك أن مصير الأرض يعتمد على فتاة واحدة…\n\"سيندر\" الميكانيكية الموهوبة، وهي سيبورغ، تحمل بين جنباتها لعنةً وهبةً في آنٍ واحد.\nفهي مواطنة من الدرجة الثانية ذات ماضٍ غامض، محتقرة من قِبل زوجة أبيها وملومة على مرض أختها غير الشقيقة. ولكن عندما تتشابك حياتها مع حياة الأمير الوسيم \"كاي\"، تجد نفسها فجأةً في قلب صراع بين المجرات، وتبدأ قصة جذب محرّم. عالقة بين الواجب والحرية، وبين الولاء والخيانة، عليها أن تكشف أسرار ماضيها لحماية مستقبل عالمها.", CategoryId = 2, ImageUrl = "/images/products/9789778200904.webp", Author = "ماريسا ماير", PublishDate = new DateTime(2021, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778200904", Pages = 424, Size = "14×20" },
            new { Id = 348, Name = "سلسة سجلات القمر - سكارليت", Price = 400m, Stock = 10, Description = "عادَت سيندر وتحاول الفرار من السجن، رغم أنها ستصبح المطلوبة رقم واحد في الكومنولث إذا نجحت في ذلك، وذلك في الجزء الثاني من سلسلة ماريسا ماير.\nفي مكان بعيد عن هنا، تختفي جدة \"سكارليت بينوِت\"، ويتضح أن هناك الكثير من الأمور التي لا تعرفها سكارليت عن جدتها أو عن الخطر الداهم الذي رافقها طوال حياتها. حينما تصادف سكارليت \"وولف\"، المقاتل في الشوارع الذي قد يحمل معلومات عن مكان جدتها، تتردد في الثقة بهذا الغريب، لكنها تجد نفسها مشدودة نحوه، وهو بدوره يشعر بانجذاب نحوها. وبينما يكشف كل من سكارليت ووولف لغزًا، يلتقيان بسيندر، فيجد الجميع أنفسهم مضطرين للبقاء خطوةً أمام الملكة القمرية الشرسة \"ليفانا\".\nتستمر المغامرة في إعادة سرد قصة خيالية جديدة تجمع بين عناصر سندريلا وذات الرداء الأحمر.", CategoryId = 2, ImageUrl = "/images/products/9789778201241.webp", Author = "ماريسا ماير", PublishDate = new DateTime(2023, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778201241", Pages = 480, Size = "14×20" },
            new { Id = 349, Name = "سلسلة سجلات القمر - كريس", Price = 480m, Stock = 10, Description = "حتى في المستقبل.. ثمة فتيات في محنة!\nبعدما خاطرت كريس بكل شيء لتحذير سندر من الخطة الشريرة للملكة لافانا، تواجه مشكلة طفيفة؛ حيث لبثت سجينة على متن قمر صناعي منذ طفولتها، لا تحظى برفقة عدا الشاشات الشبكية؛ كل هذا الوقت أمام الشاشة جعل من كريس قرصانة بارعة، ولسوء الحظ فقد تلقت لتوها أوامر من لافانا بتعقب سندر وشريكها الوسيم! وحين تخفق مجازفة إنقاذ كريس من قِبل سِندر وكابتن ثورن وسكارليت ووولف؛ تفترق المجموعة وتلوذ كريس أخيرًا بالفرار، إنما للحرية مقابل باهظ الثمن! في هذه الأثناء، لن تدع الملكة لافانا شيئًا يمنع زواجها من الإمبراطور كاي.\nربما لم تتطوع كريس وسكارليت وسندر لإنقاذ العالم، لكن عساهن أمله الوحيد!", CategoryId = 2, ImageUrl = "/images/products/9789778202502.webp", Author = "ماريسا ماير", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778202502", Pages = 592, Size = "14×20" },
            new { Id = 350, Name = "دكستر - المتفاني بإخلاص", Price = 290m, Stock = 10, Description = "هو وحش ساحر... بطل مُظلم... قاتل متسلسل يقتل السيئين فقط.\nيعاني ديكستر مورغان من ضغوط هائلة؛ فليس من السهل أن تكون قاتلًا متسلسلاً أخلاقيًا، خاصةً أثناء محاولته تجنب الشكوك التي لا تهتز من قبل الرقيب الخطير \"دوكس\" الذي يعتقد أن ديكستر مختل عقليًا... وهو بالطبع كذلك.\nفي محاولة لإبعاد دوكس عن أثره، اضطر ديكستر للغوص عميقًا في زيه المموه المحكم. وبينما لا يعمل كمحلل لبقع الدم في شرطة ميامي، يقضي معظم وقته مع صديقته المشرقة \"ريتا\" وطفليها، يحتسي بيرة خفيفة ويصبح ببطء أول \"مدمن قطنية\" في العالم.\nلكن إلى متى يستطيع ديكستر أن يلعب لعبة \"ركل العلبة\" بدلًا من \"تقطيع القاتل\"؟ إلى متى ستجبره \"الراكب المظلم\" بداخل نفسه على إسقاط التمثيل وإطلاق وحشه الداخلي؟\nفي أوقات الشدائد، تطرق الفرص الباب؛ إذ يظهر مهووس شرير بشكل خاص يشق طريقه عبر ميامي بأسلوب ملتوي يترك ديكستر عاجزًا عن الكلام. ومع اشتعال شهوته المظلمة من جديد، تنجذب أخته \"ديبورا\" (المحققة الجديدة الشرسة في ميامي) إلى القضية، فيتضح سريعًا أن الإمساك بوحش يتطلب وحشًا آخر—ولكن لن يتمكن ديكستر من الاستغراق في البحث عن هدف جديد حتى تُختطف عدوه اللدود، ما لم يُفاجئه هدفه أولاً…\nبذكاءٍ لا يُضاهى وبطابع جديد أضاف إليه \"جيف ليندسي\" تألقًا مبهرًا، يأخذ ديكستر مورغان إلى مستوى جديد من الجاذبية المُظلمة، مقدّمًا لنا أحد أكثر السرديين ابتكارًا وتلوّنًا منذ سنوات.", CategoryId = 3, ImageUrl = "/images/products/9789778201277.webp", Author = "چيف ليندسي", PublishDate = new DateTime(2023, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778201277", Pages = 360, Size = "14×20" },
            new { Id = 351, Name = "توت عنخ آمون و المقبرة التي غيرت العالم", Price = 400m, Stock = 10, Description = "نظرة جديدة كبرى على كنوز وأسرار قبر توت عنخ آمون في الذكرى المئوية لاكتشافه.\nغالبًا ما يُعتقد أن قصة توت عنخ آمون انتهت حينما نُقلت آلاف القطع التي اكتشفها هوارد كارتر ولورد كارنايفون إلى المتحف المصري في القاهرة وعُرضت. لكن هناك المزيد في قصة توت عنخ آمون.\nفي \"توت عنخ آمون والقبر الذي غيّر العالم\" نتابع مائة عام من البحوث التي جرت منذ اكتشاف القبر: نتعلم أن العديد من القطع في القبر صُنعت من حديد نيزكي جاء من الفضاء الخارجي؛ وتظهر أدلة جديدة أن توت عنخ آمون ربما كان محاربًا دخل ساحة المعركة؛ ويأخذنا المؤلف \"بوب برايَر\" خلف كواليس عمليات الفحص بالأشعة المقطعية لمومياواته لكشف أسرار الفرعون.\nكما يسلط الكتاب الضوء على التأثير الواسع النطاق لاكتشاف قبر توت عنخ آمون على مجالات تتجاوز علم المصريات؛ حيث يتم فحص كيف أثر اكتشاف القبر على السياسة المصرية وساهم في سقوط الاستعمار في مصر. وعلى الصعيد العالمي، بدأت المعارض الضخمة التي ترفع مبالغ هائلة للمتحفّات في جميع أنحاء العالم مع توت عنخ آمون، كما نشأت فكرة توثيق كل قطعة تُكتشف في مكانها قبل نقلها. وإلى حد كبير، ساهمت \"توت مانيا\" التي أحاطت باكتشاف القبر في تعزيز الهوس الحديث بمصر القديمة.", CategoryId = 7, ImageUrl = "/images/products/9789778201482.webp", Author = "بوب براير", PublishDate = new DateTime(2023, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778201482", Pages = 448, Size = "14×20" },
            new { Id = 352, Name = "القتله المتسلسلين الأمريكيين", Price = 490m, Stock = 10, Description = "من خلال كُتب مثل (القتلة المُتسلسلين) و(القاتِلات المُتسلسِلات) و(أبناء قابيل)، رسَّخ بيتر فرونِسكي مكانته كخبيرٍ رائِد في تاريخ القتلة المُتسلسلين. في هذا السرد التاريخي، الأول والأخير، للعصر الذهبي للقتل المُتسلسِل في الولايات المُتحِدة الأمريكيَّة، حينما ارتفعَت أعداد القتلة المُتسلسلين وضحاياهُم بشكلٍ كبير، يروي فرونِسكي قصص أغرب وأبرز جرائِم القتل المُتسلسِل من الخمسينيَّات وحتى أوائِل القرن الحادي والعشرين. من تِد بندي إلى قاتِل الولاية الذهبيَّة، يزداد هوسنا بهؤلاء القتلة المُتسلسلين القدامى يومًا بعد توم. ويُقدِّم هذا الكِتاب لعُشَّاق الجرائِم الحقيقيَّة كُل ما يشتهونه، بدءً من الأسماء الشهيرة (مثل إد كِمبر وجيفري دامر)، وصولًا إلى القضايا الأقل شُهرة (مثل ميلفِن ريس وهارفي جلاتمان).", CategoryId = 3, ImageUrl = "/images/products/9789778202588.webp", Author = "بيترفرونسكي", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778202588", Pages = 614, Size = "14×20" },
            new { Id = 353, Name = "مجموعة دعم الفتيات الناجيات من القتلة المتسلسلين", Price = 390m, Stock = 10, Description = "في أفلام الرعب، تكون \"الفتيات النهائيات\" هن من تبقى واقفة حين تنتهي الأشرطة. لقد نجين من أسوأ ليلة في حياتهن… لكن ماذا يحدث بعد ذلك؟\nمثل روايته الأكثر مبيعًا \"دليل نادي الكتاب الجنوبي لقتل مصاصي الدماء\"، تأتي أحدث أعمال \"جرادي هندريكس\" بإثارة سريعة، ورعب مخيف، وكوميديا سوداء ساخرة.\nمن مناشير السلسلة إلى قاتلات معسكرات الصيف، تُقدم \"مجموعة الدعم للفتيات النهائيات\" تحيةً لسلاسل الرعب الأكثر شهرة—أفلام مثل \"مجزرة منشار تكساس\"، و\"كابوس شارع إيلم\"، و\"صرخة\".\n\"لينيت تاركينغتون\" هي فتاة نهائية حقيقية نجت من مذبحة. وعلى مدار أكثر من عقد من الزمن، اجتمعت مع خمس فتيات نهائيات أخريات ومع معالجات نفسية لدعم من نجا من المستحيل، في محاولة لإعادة بناء حياتهن. ثم تفوت إحداهن اجتماعًا، وتتحقق أسوأ مخاوفهن—فشخصًا ما يعرف عن المجموعة ويصر على تمزيق حياتهن مجزأة قطعة قطعة.\nلكن سر الفتيات النهائيات هو أنه مهما كانت الظروف صعبة، مهما كان الليل مظلمًا، ومهما كانت السكاكين حادة، فلن يستسلمن أبدًا.", CategoryId = 3, ImageUrl = "/images/products/9789778201529.webp", Author = "غريدي هيندريكس", PublishDate = new DateTime(2024, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778201529", Pages = 410, Size = "14×20" },
            new { Id = 354, Name = "الميرانتي أمير البحار", Price = 50m, Stock = 10, Description = "هذه إعادة تقديم جديدة للقصة الشهيرة \"بحّاران\"، التي كانت في الأصل المدخل الثالث والخمسين ضمن سلسلة فانتازيا للدكتور أحمد خالد توفيق. تتضمن هذه النسخة عددًا كبيرًا من التعديلات والتغييرات التي كانت كفيلة بحصولها على جائزة مصطفى عزوز للأدب الطفولي عام 2018. كما تُعدّ بداية لسلسلة جديدة غير مكتملة تشير إلى قصة أخرى عن الحريق العظيم في روما.\nيروي السرد قصة صحفي يمتلك آلة زمن على شكل كشك هاتف، تُمكّنه من السفر بحرية عبر الزمن لمشاهدة وتوثيق الأحداث التاريخية المهمة. في هذه الرواية، يروي قصة اللقاء بين أسد البحر، الإماراتي أحمد بن ماجد، والطاغية البرتغالي فاسكو دا جاما.", CategoryId = 2, ImageUrl = "/images/products/9789778200867.webp", Author = "أحمد خالد توفيق", PublishDate = new DateTime(2022, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778200867", Pages = 128, Size = "10×17" },
            new { Id = 355, Name = "الأن نفتح الصندوق 1", Price = 170m, Stock = 10, Description = "تحكي الرواية قصة الدكتور محفوظ، الرجل العجوز الغريب الذي توفي فقيرًا، مخلفًا وراءه صندوقًا مليئًا بالأسرار والأشياء الغريبة في قبو منزله، يحتوي على ذكرياته ومذكراته وملاحظاته عن القصص العجيبة التي عاشها.", CategoryId = 9, ImageUrl = "/images/products/9789778200294.webp", Author = "أحمد خالد توفيق", PublishDate = new DateTime(2017, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778200294", Pages = 234, Size = "14×20" },
            new { Id = 356, Name = "الأن نفتح الصندوق 2", Price = 150m, Stock = 10, Description = "نستمر في سرد قصة الدكتور محفوظ، ذلك الرجل العجوز الغريب الذي رحل فقيرًا تاركًا خلفه الصندوق ذاته المملوء بالأسرار والأشياء الغريبة، والذي يحوي ذكرياته ومذكراته وملاحظاته عن القصص العجيبة التي عاشها.", CategoryId = 9, ImageUrl = "/images/products/9789778200300.webp", Author = "أحمد خالد توفيق", PublishDate = new DateTime(2017, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778200300", Pages = 196, Size = "14×20" },
            new { Id = 357, Name = "الأن نفتح الصندوق 3", Price = 130m, Stock = 10, Description = "وفي الجزء الأخير، نختتم رحلتنا مع الدكتور محفوظ، الرجل العجوز الغريب الذي توفي فقيرًا، مخلفًا خلفه ذلك الصندوق المليء بالأسرار والأشياء الغريبة في قبو منزله، الذي يحتوي على ذكرياته ومذكراته وملاحظاته عن القصص العجيبة التي عاشها.", CategoryId = 9, ImageUrl = "/images/products/9789778200317.webp", Author = "أحمد خالد توفيق", PublishDate = new DateTime(2017, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778200317", Pages = 146, Size = "14×20" },
            new { Id = 358, Name = "سلسلة فاي - عملية الاستاذ", Price = 140m, Stock = 10, Description = "تبدأ الرواية بازالة القوات المصرية لأحد أبرز عملاء الموساد الإسرائيلي بنجاح. وفي الوقت نفسه، يستعد الرئيس محمد أنور السادات لإلقاء خطاب تاريخي يعلن فيه هذا الاعتقال، مؤكداً للعالم أن المصريين دائمًا ينتصرون في كل الميادين. غير أن الأحداث تأخذ منعطفًا غير متوقع، حيث تنجح المخابرات الإسرائيلية في السيطرة على إحدى الشخصيات المحورية في القيادة المصرية، اللواء رفعت.", CategoryId = 2, ImageUrl = "/images/products/9789778200751.webp", Author = "نبيل فاروق", PublishDate = new DateTime(2022, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778200751", Pages = 162, Size = "14×20" },
            new { Id = 359, Name = "سلسلة فاي - عملية تل ابيب", Price = 170m, Stock = 10, Description = "الرواية هي إثارة جريمة من نسج خيال الكاتب، وتدور حول عملية مُحكمة لاسترجاع فيلم مصغر من تل أبيب. يقوم بتنفيذ المهمة العميل \"فاي\" واستراتيجية فريدة من نوعها تخصه. وتملأ القصة أحداث مشوقة تجعل منها قراءة مثيرة لعشاق الروايات البوليسية، والتجسس، والأدب الاستخباراتي.", CategoryId = 2, ImageUrl = "/images/products/9789778200744.webp", Author = "نبيل فاروق", PublishDate = new DateTime(2022, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778200744", Pages = 224, Size = "14×20" },
            new { Id = 360, Name = "سلسلة فاي - عملية البعث", Price = 120m, Stock = 10, Description = "في الكتاب الثالث من السلسلة، نتتبع الشاب المصري \"فاي\" وهو يقود عمليات حساسة وخطيرة. وبفضل مهاراته الاستثنائية وقدراته الفريدة التي تميّزه عن بقية أعضاء مديرية المخابرات العامة المصرية، يُوكل إليه العديد من المهام شبه المستحيلة، ومن بينها عملية \"النسر الوحيد\".", CategoryId = 2, ImageUrl = "/images/products/9789778200881.webp", Author = "نبيل فاروق", PublishDate = new DateTime(2022, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778200881", Pages = 120, Size = "14×20" },
            new { Id = 361, Name = "سلسلة فاي - عملية النسر المنفرد", Price = 140m, Stock = 10, Description = "تبدأ أحداث الرواية في صحراء سيناء (1973 م / 1393 هـ)، حيث تدور كل الأحداث حول شجاعة الجندي المصري الشاب (سائقة-144) في عملية هجومية ضد الاحتلال الإسرائيلي لتحرير سيناء. وتنتهي المعركة بترك الشاب جريحًا على رمال الصحراء، إلا أنه يواصل الدفاع باسم \"مصر\" وحده.", CategoryId = 2, ImageUrl = "/images/products/9789778200874.webp", Author = "نبيل فاروق", PublishDate = new DateTime(2022, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778200874", Pages = 152, Size = "14×20" },
            new { Id = 362, Name = "سلسلة العقرب - سيف العدالة", Price = 170m, Stock = 10, Description = "في لحظة درامية، يقول أحدهم: «سأحتاج بالتأكيد إلى شريك للمرحلة القادمة، وأنتِ يا من لا يُمكن رفضكِ». ثم رفع العقرب الذهبي أمام عينيه وتابع: «وهذا سيكون شعار المرحلة القادمة...» وتلألأت عيناه قائلاً: «العقرب».\nوفي تلك اللحظة، أعلن القدر عن ميلاد محارب جديد، مقاتل للجريمة؛ ميلادٌ تهتز من أجله قلوب أخطر المجرمين، وترتفع سيف العدالة عاليًا. إنه ميلاد \"العقرب\".", CategoryId = 2, ImageUrl = "/images/products/9789778200782.webp", Author = "نبيل فاروق", PublishDate = new DateTime(2021, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778200782", Pages = 216, Size = "14×20" },
            new { Id = 363, Name = "سلسلة العقرب - ملك الجريمة", Price = 170m, Stock = 10, Description = "لقد صُدمت ما لا يقل عن ثلاثة أرباع مصر عندما أعلنت الأخبار في الفجر عن القبض على صالح عثمان بتهمة الخيانة. تدفّق الناس لشراء الجرائد لمعرفة المزيد من التفاصيل، وزادت دهشتهم عندما لم يجدوا أي أثر لهذه الأخبار في الجرائد، إذ أن القبض تم بعد طباعة الصحف. لم يصدق الناس آذانهم؛ فقد كان صالح عثمان من أقوى رجال البلاد على الرغم من عدم توليه أي منصب رسمي.", CategoryId = 2, ImageUrl = "/images/products/9789778200799.webp", Author = "نبيل فاروق", PublishDate = new DateTime(2021, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778200799", Pages = 210, Size = "14×20" },
            new { Id = 364, Name = "سلسلة العقرب - الامبراطورة", Price = 130m, Stock = 10, Description = "توقف هو متذكرًا أمرًا، ثم عاد إليها ووضع بطاقة العقرب على كرسيها قائلاً: «صدقيني، لقد فقدتِ اللقب إلى الأبد». وتوجه نحو الباب لينهي الحديث قائلاً: «لقب الإمبراطورة»، وأغلق الباب بهدوء خلفه.", CategoryId = 2, ImageUrl = "/images/products/9789778200812.webp", Author = "نبيل فاروق", PublishDate = new DateTime(2021, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778200812", Pages = 148, Size = "14×20" },
            new { Id = 365, Name = "سلسلة العقرب مملكة الشر -العصابة", Price = 180m, Stock = 10, Description = "ولم يكن الأمر سهلاً بالطبع على \"العقرب\" أن يخلع قناعه، فذلك كان يهدد حياته وعمله ومستقبله بسهولة. لكن الوضع لم يكن سهلاً أو خفيفًا؛ فقد كان يواجه عدوه اللدود الذي لا يرغب في شيء سوى كشف هويته، ولم يكن يحمل سلاحًا بينما كان خصمه يشير إليه بسلاح، مما استدعى مناورة ذكية.", CategoryId = 2, ImageUrl = "/images/products/9789778200768.webp", Author = "نبيل فاروق", PublishDate = new DateTime(2021, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778200768", Pages = 272, Size = "14×20" },
            new { Id = 366, Name = "سلسلة العقرب - مهمة رسمية", Price = 120m, Stock = 10, Description = "قال وهو يبتسم بمكر: «هذه المرة، لا يعمل العقرب بمفرده، بل هو في مهمة رسمية». أدركت غادة حينها أن العقرب عاد إلى عالم مكافحة الجريمة بكل قوته.", CategoryId = 2, ImageUrl = "/images/products/9789778200805.webp", Author = "نبيل فاروق", PublishDate = new DateTime(2021, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778200805", Pages = 130, Size = "14×20" },
            new { Id = 367, Name = "سلسلة العقرب - خلف القناع", Price = 120m, Stock = 10, Description = "وعند باب القبو، وبهدوء وسكينة، وقف آخر رجل لم يكن أحد يتوقعه… العقرب. لم يكن يشير بسلاح نحوهم، بل وقف هناك، معقود الذراعين أمام صدره، مستندًا إلى الباب وبابتسامة ساخرة. والأهم من ذلك، كان يرتدي القناع الأسود الشهير... قناع العقرب.", CategoryId = 2, ImageUrl = "/images/products/9789778200775.webp", Author = "نبيل فاروق", PublishDate = new DateTime(2021, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778200775", Pages = 132, Size = "14×20" },
            new { Id = 368, Name = "سلسلة المتخصصون - لعبة الثعالب", Price = 95m, Stock = 10, Description = "تتواصل أحداث هذه القصة بعملية تهدف إلى نقل وليد من إسرائيل إلى مصر. وتغوص في الألعاب العقلية والنفسية التي يمارسها القائد \"العميد\"، وخططه ضد الموساد، متفوقًا عليهم مرة أخرى بذكائه، إذ أنهم عادةً ما يلجؤون إلى العنف بدلاً من الفكر.", CategoryId = 2, ImageUrl = "/images/products/9789778201697.webp", Author = "نبيل فاروق", PublishDate = new DateTime(2024, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778201697", Pages = 150, Size = "10.5×17" },
            new { Id = 369, Name = "سلسلة المتخصصون - عملية الفهد", Price = 85m, Stock = 10, Description = "وتتابع الرواية محاولة العميد إنقاذ العميل رأفت من براثن الموساد، الذين استغلّوه ككبش فداء لاسترجاع وليد إلى الأراضي المصرية. وبمساعدة \"فهد\"، المعروف بمهاراته الفائقة وقدراته الاستثنائية، والذي تنكر بشخصية طالب لجوء سياسي لدى الموساد، تخترق \"فهد\" الموساد لتحرير العميل المصري. ولأول مرة، لجأت مصر إلى استخدام العنف بتوظيفه كعميل لهذه العملية. دخل في قتال مع الموساد خلال فترة وجوده هناك، وانحاصروا في الداخل، وتنتهي القصة باكتشاف العميد أن مهمة \"فهد\" قد فشلت.", CategoryId = 2, ImageUrl = "/images/products/9789778201710.webp", Author = "نبيل فاروق", PublishDate = new DateTime(2024, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778201710", Pages = 132, Size = "10.5×17" },
            new { Id = 370, Name = "سلسلة المتخصصون - معركة العقول", Price = 100m, Stock = 10, Description = "تدور أحداث الرواية حول المناوشات بين أجهزة الاستخبارات المصرية والإسرائيلية خلال الفترة الممتدة بين النكسة (حرب 1967) وحرب أكتوبر (1973). ويصاب أحد الجواسيس الأساسيين، مما يؤدي إلى ولادة فريق \"المتخصصون\"، بقيادة قائد يضم أفراداً مهرة في مجالات متنوعة. هذا القائد، الذي يحمل رتبة عميد، مهووس بلعبة الشطرنج وأسرارها وأهم تحركاتها، فيستخدم هذه الاستراتيجيات لتخطيط عمليات فريقه السرية.\n\nيتخصص كل عضو من أعضاء الفريق في مجال معين مثل القانون، والتجسس، والتخفي، وخلال مهامهم الاستخباراتية يُشار إلى كل متخصص برقم رمزي. وتشمل هذه الجزء من القصة ثلاثة متخصصين وعميل عمليات خاصة يعملون تحت أسماء وجنسيات مختلفة في إسرائيل، يُعرفون بأرقام. ويركز الحبكة على محاولات تحرير المتخصص وليد من قبضة الموساد بجهود باقي المتخصصون. وتنجح العملية في هروب وليد ليجد ملاذًا بين مجموعة من الفلسطينيين، بينما يظل العميد منشغلاً في البحث عن طريقة لنقل كل من وليد ورأفت من إسرائيل.", CategoryId = 2, ImageUrl = "/images/products/9789778201703.webp", Author = "نبيل فاروق", PublishDate = new DateTime(2024, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778201703", Pages = 184, Size = "10.5×17" },
            new { Id = 371, Name = "بنكهه المولوتوف والعشق", Price = 290m, Stock = 10, Description = "يضم هذا الكتاب خمس روايات قصيرة بنكهات متناقضة؛ الانتصار والهزيمة، الأمل والإحباط، العزيمة واليأس.. يتعثر أبطال الروايات الخمس بين حالات وأجواء نفسية وإنسانية متناقضة؛ فنراهم منتصرين مهزومين، فرحين تعساء في نفس اللحظة، لكنهم كانوا وما زالوا أحياء، يعيشون الحياة الصعبة كمن يسيرون على الحبل فوق الهوة البعيدة، وكمن يسيرون حفاة على الزجاج المنثور.. علينا أن نتعلم ونعيش ونواجه، ونتحمل ما سيصادفنا في رحله الحياة، لا نستسلم للهزائم ولا نتباهى بالانتصارات، سنواجه كل المتناقضات والمواقف والمشاعر والتحديات في نفس الوقت وسنعيشها ونتعامل معها، لكن كيف سنخرج من كل هذا، وكيف سنعيش قبله وبعده، أسئلة صعبة تحاول الروايات الخمس أن تعثر لها على إجابات، وربما لم ولن تجد لها إجابات أبدًا..", CategoryId = 1, ImageUrl = "/images/products/9789778598520.webp", Author = "أميره بهي الدين", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778598520", Pages = 396, Size = "14×20" },
            new { Id = 372, Name = "عندما بلغ سليمان العاشرة", Price = 200m, Stock = 10, Description = "لماذا لا نعيش ببساطة؟ سؤال يبدو بسيطًا يطرحه أبطال الروايات الأربع في هذا الكتاب علي أنفسهم وعلينا، فلا يجدون له إجابة ولا نجدها نحن أيضًا.. لماذا لا نحِب ونحَب ونعيش في هناء وفرح لا يستحق حكاية ولا تُكتب عنه رواية؟! لماذا لا تمر الأيام سهلة تبدأ وتنتهي فلا تؤلمنا ولا تسفك دماءنا ولا تلومنا ولا تقهرنا ولا تعصف بنا، فنقضيها ونعيشها كما نحب، وننتهي منها وتنتهي منا بسلام وهدوء؟! من الذي ألقى بنا في عين الإعصار وهو يدور بأقصى بطشه وعنفوانه؟! وما الذي ينتظره منا؟! ولماذا كل هذا والحياة أسهل وأبسط؟ هل الحياة أبسط وأسهل يا إسماعیل؟ ما الذي حدث لك يا ناجي؟ ما الذي اكتشفته يا سليمان بعد كل ما عشته؟ كيف قويت على ما واجهته يا أكرم؟ أسئلة كثيرة حاولت الروايات الأربع الإجابة عنها بمشاعر وأحزان ودموع وغضب وقوة وهشاشة أبطالها الذين عجزوا جميعًا علي العثور علي إجابة السؤال الملح الذي لاحقهم، لماذا لا نعيش ببساطة؟!", CategoryId = 1, ImageUrl = "/images/products/9789778598551.webp", Author = "أميره بهي الدين", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778598551", Pages = 272, Size = "14×20" },
            new { Id = 373, Name = "هلاوس في المخبأ السري", Price = 300m, Stock = 10, Description = "في هذا الكتاب خمس روايات يجمع بين عوالمها المختلفة الشديدة التباين وبين أبطالها الغرباء مشقة رحلتهم التي ظنوها رتيبة عادية ستبدأ وتمر وتنتهي دونما نُدوب ولا وجع، لتفاجئهم أيامهم بأثقالها وحزنها ومشقتها وهم يرزحون تحت وطأتها وذكرياتها ونواهيها وقيودها، هل أيٌّ منا حر يعيش ويختار ويفرح ويمضي رحلته طليقًا إلا من أحلامه وأفكاره وأمنياته، أم ستُظهر لنا الأيام دونما توقع ولا انتظار أننا أسرى المفروض الذي لم نختَره وعلينا ترويضه وترويض أيامنا وأنفسنا لنصل إلى بر السلامة كما نظن ونتمنى؟ الاختيار والقدر والمصير، الحرية والمسئولية، الإخفاق والنجاح، كل هذه المعاني وأكثر وأعمق صادفت أبطال الروايات الخمس، وحفرت بنصالها المشحوذة ملامح وشكل رحلاتهم التي سنعيشها معهم.. سليم ابن الحاج أبو حسن ووجعه، باسل وقصيدته التي لم يعثر عليها، يوسف ونبيل ونفيس وعائلتهم الكبيرة، زين ونبيل وعم وصفي ورفقة الهزيمة والنصر، أسامة وحكايته الحزينة مع ملابسه القديمة، كل هذا وأكثر سنعيش معه في الكتاب ورواياته الخمس", CategoryId = 1, ImageUrl = "/images/products/9789778598582.webp", Author = "أميره بهي الدين", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778598582", Pages = 456, Size = "14×20" },
            new { Id = 374, Name = "ناقة الله", Price = 215m, Stock = 10, Description = "بعد أن وصل إلى القائمة المختصرة لجائزة مان بوكر الدولية في عام 2015، نشر الروائي العربي الشهير إبراهيم الكوني رواية بعنوان ناقة الله عبر دار كيان للنشر في عام 2022. تقع أحداث الرواية في ستينيات القرن الماضي حينما كانت الصحراء الكبرى مقسمة بين الدول، وقد سُجن عدد كبير من الطوارق ونُزِعوا من وطنهم، مما مثل بداية نفيهم وتشتيتهم عن جذورهم.\nتتميز رواية إبراهيم الكوني ببطلة من الإبل تُدعى \"تمالالت\" (جاموس بري)، التي تفيض شوقًا ولهفةً عميقة لوطنها، وتصارع كل العقبات في سبيل العودة إلى أرضها. على الرغم من جهود مالكها وحبيبها \"أسيس\"، لا يوجد دواء يخفف من ألم حنينها. تتكشف أحداث الرواية كأنها لحن مؤثر مفعم بالشعر والحنين، مع إثارة تساؤلات فلسفية وروحية عميقة حول معنى الوطن والحرية والعدالة. يبدو أن الكوني أراد أن ترمز ناقة روايته إلى الحب العميق للوطن.", CategoryId = 7, ImageUrl = "/images/products/9789778201192.webp", Author = "إبراهيم الكوني", PublishDate = new DateTime(2022, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778201192", Pages = 304, Size = "14×20" },
            new { Id = 375, Name = "تنفس من الطلاق إلى التعافي", Price = 220m, Stock = 10, Description = "بعد الطلاق... تنشأ مشاعر مختلطة—قلق وغضب، فرح وحزن، سعادة وإحباط، وإحساس بالحرية والانطلاق. في لحظة، تختنق بك أنينات قلبك حتى تكاد تخنقك، وفي اللحظة التالية ترى العالم من خلال نظارات وردية براقة. قد يكون قراري صحيحًا... أو خاطئًا... وتظل عالقًا في دورة لا نهاية لها.\nبعد الطلاق، ينبثق بريق أمل في نفق من الظلام، يُعيد إشعال الحياة في قلبك من جديد، ولكن فقط عندما تدرك الدرس بالكامل وتفهم أكثر عن نفسك وعن الحياة مما كنت تعرفه من قبل.\nقد تعتقد بعد الطلاق أن النار لا تُطفأ وأن النهاية وشيكة، لكن نعمة الله تعمل في قلبك دون أن تدري. يبدأ فصل جديد مع ذاتك، حيث ترى العالم بعيون مختلفة؛ وتزين ألوان الطيف حياتك التي كانت مغطاة بالسواد.\nوفي الجانب الآخر من العالم، توجد روح عانت مثلك، تبحث عنك في الزوايا الخفية لكل قصة حب، متلهفة للعثور عليك في كل بيت شعري. وأخيرًا، تلتقيان. تعانقان برفق وتبدآن معًا كتابة حروف قصة حب جديدة لم تتذوق حلاوتها من قبل.\nها هو قلبك بين يديك. فهل أنت مستعد للرحلة؟ انطلق—استمتع، وافرح، وتنفس.", CategoryId = 5, ImageUrl = "/images/products/9789778201505.webp", Author = "فاطمة المهدي", PublishDate = new DateTime(2023, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778201505", Pages = 334, Size = "14×20" },
            new { Id = 376, Name = "كبسولات تربوية \"تربية عامة\"", Price = 140m, Stock = 10, Description = "هذا الكتاب لا يتحدث عن نظريات أكاديمية، ولا يعدك بحياة  مثالية، سيشاركك هذا الكتاب عالمك اليومى مع أبنائك، بدايةً من  شروق الشمس وتزامنًا مع ميعاد المدرسة وواجباتها، مرورًا  .بالمواقف اليومية فى التربية، وحتى موعد الخلود للنوم ستحيا معه بعض المواقف التربوية فى شكل حوار حى فى أسرة  صغيرة، تعيش الحياة مع أبنائها كما تعيشها أنت. يعرض  طريقتك فى التربية التى مللت منها وربما سئمتها، ليعطيك حلولاً  .بسيطة فى شكل حوار شيق.", CategoryId = 5, ImageUrl = "/images/products/9789778200010.webp", Author = "فاطمة المهدي", PublishDate = new DateTime(2017, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778200010", Pages = 194, Size = "14×20" },
            new { Id = 377, Name = "كبسولات تربوية \"تربية جنسية\"", Price = 180m, Stock = 10, Description = "أسئلة تتوارد على أذهان الأبناء وتكون إجابة البعض كالتالى :\nعيب .... عندما تكبر سوف أخبرك أو تنتهى بفتح تحقيق حول من أخبرك بهذا.\nتساؤلات حول الحب والجنس وتكون ردود الأفعال دروسا ومواعظ دون أن نفهم طبيعة المرحلة...\nأحكام وتُهم يلقى بها بعض الأهل على أبنائهم بأنهم قد انحرفوا\nالحديث حول التطورات الجسدية..الرغبات..الجنس الآخر..\nتلك الأشياء الغامضة بالنسبة للأبناء كيف تتصرف حيالها فى ظل عالم منفتح\nكيف تريده أن يفهمك ويفهم العالم من حوله وهو لا يزال يجهل نفسه وطبيعة جسده؟\nإجابات على بعض الأسئلة التى تسبب لك حرجا مع أبنائك .\nسيأخذك هذا الكتاب فى رحلة شيقة نتعلم فيها سويا كيف تتفهم ولدك ..تنصت إليه..تتقبله..\nحتى يتسنى لك تجديد العلاقة معه لتصبح صديقًا ومرجعا له بدلا من أن يتخذ الإنترنت أو صديق السوء مرجعًا له .", CategoryId = 5, ImageUrl = "/images/products/9789778200546.webp", Author = "فاطمة المهدي", PublishDate = new DateTime(2019, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778200546", Pages = 252, Size = "14×20" },
            new { Id = 378, Name = "الهجانة", Price = 300m, Stock = 10, Description = "أُمر غالب، مثل كثير من العمال، بالانتقال إلى بورسعيد للعمل لدى البريطانيين، استعدادًا لمعاركهم خلال الحرب العالمية الأولى. كافح غالب لتقرير مصير ابنته الوحيدة؛ فأين سيتركها؟ ومع من؟ وفي النهاية، لم يكن أمامه خيار سوى اصطحابها معه! ولكن ذلك حدث فقط بعد أن تحولت منصورة إلى \"منصور\"، ابن غالب النجار.\n\nتدور أحداث هذه الحكاية في عصر المماليك، وهي قصة رومانسية عن الظلم الاجتماعي والانتقام؛ إذ تهرب شابة مع والدها على متن سفينة، وتلد ولدًا يُدعى \"أنس\". انتزع الأمير المماليك الماكر الصبي من عائلته ورباه كأمير شوارسي، دون أن يعرف أصله، في عالم جديد. هل سيرث الصبي القوة والثروة؟ أم سيثأر لعائلته ولكل المصريين المضطهدين؟", CategoryId = 7, ImageUrl = "/images/products/9789778200669.webp", Author = "أيمن رجب طاهر", PublishDate = new DateTime(2020, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778200669", Pages = 432, Size = "14×20" },
            new { Id = 379, Name = "القحط", Price = 215m, Stock = 10, Description = "الرواية من نوع الخيال التاريخي وتدور أحداثها خلال فترة \"المجاعة الكبرى\" في عهد الخليفة الفاطمي المستنصر بالله، مع شخصيات خيالية. تبدأ القصة بخبر عن تراجع مياه النيل، يُبلغ به نساء درب الريحان على يد ناقله \"ريان\"، الذي يأسف على انتشار الجوع والعطش الذي يجتاح البلاد. تتكشف الأحداث تدريجيًا، مصورةً تفاقم المأساة خطوة بخطوة.", CategoryId = 7, ImageUrl = "/images/products/9789778200539.webp", Author = "أيمن رجب طاهر", PublishDate = new DateTime(2019, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778200539", Pages = 320, Size = "14×20" },
            new { Id = 380, Name = "المشعلجي", Price = 290m, Stock = 10, Description = "ربع المشعلجية، مكان يُفترض وجوده بإحدى الحواري القريبة من ميدان السيدة  زينب، يقطنه العجوز فيض الله مع ابنه تقاوي وحفيدته الشابة منيفة، ويجتر مع رفيق عمره الجد معروف ذكرياتهما أيام حكم الخديو إسماعيل وحفر قناة السويس وحفل افتتاح القناة وأيام الشباب كمجندين بجيش عرابي واشتراكهما في حرب مقاومة الإنجليز وفترة ما بعد الاحتلال الإنجليزي لمصر وتسريحهما من الخدمة وعملهما كمشعلجية لأعمدة النور ثم ذبول تلك المهنة بعد انتشار الكهرباء ومع اقتراب فيض الله من الثمانين إلا أنه يشارك في ثورة الزعيم سعد زعلول 1919م ويرى فيه مقاومة للإنجليز ويتمنى ظهور زعيم في السنوات المقبلة يخلص مصر كلها من حكم الملكية الفاسد والمحتلين الإنجليز المسيطرين على مقدرات الشعوب", CategoryId = 7, ImageUrl = "/images/products/9789778202335.webp", Author = "أيمن رجب طاهر", PublishDate = new DateTime(2024, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778202335", Pages = 408, Size = "14×20" },
            new { Id = 381, Name = "على جناح بن فرناس", Price = 90m, Stock = 10, Description = "فارس، ذلك الشاب الصغير المحب لجمع المعلومات عن علماء ذوي إسهامات علمية غيّرت الحياة على كوكب الأرض للأفضل، يقرأ عن محاولة الإنسان لغزو الفضاء، يقنعه جده بقراءة المزيد من المعلومات عن الفضاء ومحاولة الطيران...\nينهمك فارس في القراءة عن عباس ابن فرناس ويتمنى لو كان قد عاش في عصره، يحلم بذلك؛ كي يرى مبتكرات ابن فرناس، فهل تحقق له ذلك؟!؟", CategoryId = 1, ImageUrl = "/images/products/9789778202687.webp", Author = "أيمن رجب طاهر", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778202687", Pages = 144, Size = "10×17" },
            new { Id = 382, Name = "كسوة جديدة للكعبة", Price = 240m, Stock = 10, Description = "في أرض مكة، رأى الفتى المكي محمد رؤيا غريبة.\nرأى العالم من علٍ — الشرق الأوسط وما حوله.\nرأى ومضات، كشرارات خافتة، تومض وتختفي في نقاط متفرقة من أرضنا.\nلكن عينه ثبتت على نقطة واحدة، شعر أن قلبه ينبض على إيقاع ضوئها، الذي لم يخفت.\n\nاقترب منها، مأخوذًا، كأن نداءً سماويًا يدعوه.\nفإذا بها الكعبة — التي يراها كل يوم بين الحجيج والفنادق الشاهقة — لكنها الآن مختلفة. مكسوّة بالرخام، بيضاء، منقوشة بعهود إلهية خُطّت بدم الإنسان.\n\nلاحظ بئرًا لا يعرفه إلا أهل \"ماريا\".\nوقف مذهولًا، والكعبة خلفه، لكنها لم تعد كما يعرفها.\nتحوّلت، كأن ستارًا جديدًا يتكوّن حولها، يحمل ألوان كعبة ماريا.\nوبكى وهو يرى النقوش الدامية تتحوّل، قطرة فقطرة، إلى رجال ونساء وأطفال، يتحرّكون في إيقاع صامت، كرقصة غامضة، أو كحكاية منقوشة على جدار مقبرة فرعونية.\n\nكان كل رجل حرفًا،\nوكل طفل تكوينًا،\nوالمرأة... زينة حزينة تحيط بالكلمات.", CategoryId = 7, ImageUrl = "/images/products/9789778200683.webp", Author = "مجيب الرحمن مدحت", PublishDate = new DateTime(2020, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778200683", Pages = 352, Size = "14×20" },
            new { Id = 383, Name = "حكايات يوسف إدريس", Price = 120m, Stock = 10, Description = "مجموعة قصصية متنوعة تتخذ من فكرة الكتابة مرسى لها، يحاول الكاتب من خلالها محاورة يوسف إدريس ومناقشة حاسته الإبداعية الاستثنائية، في تجربة اتفق النقاد على أنها فريدة في كتابة القصة القصيرة المعاصرة، فقد تنوعت بين عوالم متعددة قوامها جميعًا الشخصية المصرية، وكيف ترى العالم المحيط بها وكيف تتفاعل معه)", CategoryId = 1, ImageUrl = "/images/products/9789778200850.webp", Author = "عمرو العادلي", PublishDate = new DateTime(2021, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778200850", Pages = 124, Size = "14×20" },
            new { Id = 384, Name = "إليك انتمي", Price = 220m, Stock = 10, Description = "منذ سنوات بعيدة يا بنيتي ، بعد عاصفة شديدة ضربت القرية استيقظ أهل القرية علي أجراس عالية أسرع الجميع نحو الصوت، ليجدوا جرسا عملاقا قابعا فوق الرمال بالقرب من الفنار القديم، كبير الحجم ، فظيع الصوت ،  مهيب الشكل ، لم يعلموا من أين جاء و لا متي و لا كيف أو حتى من أحضره ؟؟ حاولوا نقله من مكانه لكن لم يستطيعوا ، لم يستطع أقوي شباب القرية مجتمعين أن يزحزحوه من مكانه ولا حتى شبر واحد .\n‎بقي مكانه هكذا ،أيام و أيام  تناقلت حوله(أم افضل تناقلته) القصص و الإشاعات ، منهم من قال أن عروس البحر كانت تحب إبراهيم ابن الريس عمارة الذي غرق و هو في رحلة صيد و لم تعرف بموته في وقتها و لذا أحضرت هذا الجرس العملاق في المساء و وضعته في مكانه هذا حتى يدق كلما غرق أحدا من الصيادين فتعرف حبيبته بموته و لا تتعذب مثلها ، و منهم من قال أن نرجس الغجرية العجوز التي كانت تعيش مع مجموعة من الغجر عند أطراف القرية و اجتمع أهل القرية و طردوها بعدما عرفوا أنها تمارس السحر الاسود ،فسحرت إحدى شباب القرية لتتعذب كل نساء القرية كلما دق الجرس كما تعذبت هي بطردها من القرية.\n‎و منهم من قال أنه جرس السفينة العملاقة التي غرقت منذ سنوات بعيدة في عرض البحر و أن أمواج البحر تناقلته حتى قذفت به عندهم، اقاويل و قصص عديدة لم تحسم موضوع هذا الجرس الغريب بل زادته غموض ، وما زاد الموضوع غرابة هي ارتباط دقات الجرس بحوادث غرق مراكب الصيد ،فكلما تعرضت أحد مراكب الصيد لحادثة غرق كان الجرس يطلق دقاته تلقائيا حتى أصبح رمزا للموت في هذه القرية الساحلية الصغيرة ، فكلما دق الجرس كانت كل نساء القرية  يخرجن صارخات مولولات يصرخن لا يعلمن علي من ، و لكن حتما علي أحد ، علي زوج إحداهن أو ابنها أو والدها كن يبدأن البكاء حتى قبل أن يعرفن من أو كيف أو متي ؟؟!! كل دقة من دقات الجرس كانت كلدغات كرباك سوداني على جسد كل من له عزيز في البحر، ولأن يا بنيتي الناس يخافون من أي أمر غامض لا يفهمونه ابتعدوا عن الجرس وتجنبوه.....\".", CategoryId = 4, ImageUrl = "/images/products/9789778201895.webp", Author = "ريم مراد", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778201895", Pages = 246, Size = "14×20" },
            new { Id = 385, Name = "بعد النهاية (الجزء الثاني)", Price = 190m, Stock = 10, Description = "يعود أدهم مضطرا بعد خطف غادة من شخص مجهول وغير متوقع للبحث عن الصندوق الذى يبحث عنه الجميع، يعثر عليه ويتفاجأ بمحتوى الصندوق بمساعدة ناديا جارتة التى لا تعرف ما حدث بين أدهم وزوجها القتيل، يكتشف أدهم من هو هذا الشخص بعد أن تتعرف ناديا على صوته وعلى مساعده الذى يقتله أدهم فى شجار ويتخلص من جثته.. تظهر معاناته مع التخلص من آثر الجريمة بسبب هوسة القهرى\nوينتهى الأمر بلقاء يجمع الكل فى مكان مهجور تحاول آية أن تقتل أدهم لكن ناديا تنقذة وتتخلص من آية، حسن يكاد يصرع أدهم فى شجار لكن ناديا تعاود نجدته باطلاق الرصاص على حسن الذى يفر هاربا.\nيقرروا الإحتفاظ بالصندوق رغم خوف أدهم مما يمكن أن يحدث لاحقا بسببه", CategoryId = 3, ImageUrl = "/images/products/9789778202755.webp", Author = "محمد كامل", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778202755", Pages = 316, Size = "14×20" },
            new { Id = 386, Name = "تشركا تروڤا", Price = 320m, Stock = 10, Description = "(تشركا تروفا) أو من يبحث يجد هي رواية واقعية مبنية على أحداث حقيقية من واقع ملفات إحدى\nالمنظمات الدولية العاملة في مجال البحث والتقصي.\nبطل الرواية &quot;أشرف عبد الفتاح&quot; مسئول التقصّي في إحدى المنظمات الدولية، عمله هو البحث عن\nالمفقودين بسبب الحروب والنزاعات المسلحة وتجميع شتات العائلات التي تفرقت لهذه الأسباب أو\nلغيرها. تأخذنا الرواية المأخوذة عن أحداث حقيقية في ثلاث مغامرات يحقق فيها اشرف في قضايا\nاختفاء اشخاص مفقودين وتلقي الضوء على طريقة عمل المنظمات الإنسانية في هذا المجال. تظهر\nالرواية كيف يجمع أشرف المعلومات والأدلة ويربط بينها ببراعة كي يرى الصورة كاملة.\nأحداث الرواية متلاحقة مثيرة تفوق الخيال رغم أنها حقيقية مئة بالمئة، حيث تدور أحداث القضية\nالأولى في (موريتانيا) في رحلة بحث بطلها الطفل إدريسو الذي تم العثور عليه وحيدا في مدينة\n(باسيكونو) أقصى جنوب غرب (موريتانيا) ، بينما تدور أحداث القضية الثانية بين (البوسنة) و(كرواتيا)\nو(سويسرا) حيث يبحث أشرف مع الشابة إيمينا عن والدها الذي فقد أثره عقب هروبه من أحد معتقلات\nالصرب، أما القضية الثالثة فتدور أحداثها بالأساس في (ليبيا) حيث يقوم أشرف بالبحث عن أربعة\nأشخاص مصريين منهم طفل صغير دخلوا الحدود الليبية في رحلة هجرة غير شرعية ليلاقوا الأهوال\nفي الصحراء الليبية ويفقد أثرهم تماما.", CategoryId = 1, ImageUrl = "/images/products/9789778202748.webp", Author = "تامر احمد", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778202748", Pages = 464, Size = "14×20" },
            new { Id = 387, Name = "لا ربيع في هذة المدينة", Price = 120m, Stock = 10, Description = "تتحدث رواية (لا ربيع في هذه المدينة) عن شخص اسمه (قاسم)، يعيش في مدينة تعاني من صراعات الحرب، حيث يجد نفسه في المستشفى وقد فقد ساقاً كاملة بسبب صاروخ استهدف المنطقة التي يسكن فيها، ليجد أنه مضطر لتلقي العلاج في المستشفى، حيث يجد نفسه في غرفة يتغير زملاؤه فيها كل يوم، لتتغير القصص والحكايات والمواقف الصادمة، التي تتحدث كلها عن الحرب، وحتى الممرضات يتم قتلهن كل يوم بواسطة أحد القناصين المختبئين أمام المستشفى.", CategoryId = 1, ImageUrl = "/images/products/9789778201864.webp", Author = "حسن الحلبي", PublishDate = new DateTime(2024, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778201864", Pages = 128, Size = "14×20" },
            new { Id = 388, Name = "عالم أفضل - القيامة", Price = 215m, Stock = 10, Description = "تدور احداثها في المستقبل القريب و محاولة الثورة الثانية علي شركة ايجى نيرجى فهل ستنجح الثورة ام ستفشل كسابقتها", CategoryId = 2, ImageUrl = "/images/products/9789776376861.webp", Author = "شريف ثابت", PublishDate = new DateTime(2016, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789776376861", Pages = 294, Size = "14×20" },
            new { Id = 389, Name = "عالم افضل - الميلاد", Price = 215m, Stock = 10, Description = "فى مستقبل قريب مظلم، تنضب موارد الطاقة التقليدية من نفط وغاز طبيعى وخلافه، وتعجز الطاقة المتجددة عن سد الحاجة العالمية المتزايدة للطاقة.. تصبح الكرة فى ملعب إيجى- نيرجى.. الشركة العملاقة، عابرة القارات، المتخصصة فى استخلاص الطاقة النفسية من الأجساد البشرية (عن طريق تعذيبها حتى الموت) ثم تحويلها لطاقة كهربية..\n\nبعد ما يقرب من ربع القرن من الاستقرار والسيطرة على سوق الطاقة.. تنفجر الأحداث مجدداً مع هروب أحد ضحايا الشركة من داخل ماكينات التعذيب، وقد اكتسب قدرات غير طبيعية جعلت منه سلاحاً رهيباً، تصارع الشركة من جهة، وخصومها من الجهة الأخرى، للوصول إليه أولاً..\n\nمن أجل عالم أفضل، يتقاتل الجميع لفرض قواعده، كلُ وفقاً لرؤيته.. تراق الدماء بلا حساب، وتشتعل الحرب من جديد..", CategoryId = 2, ImageUrl = "/images/products/9789776376687.webp", Author = "شريف ثابت", PublishDate = new DateTime(2015, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789776376687", Pages = 290, Size = "14×20" },
            new { Id = 390, Name = "لعبة الخيول الخشبية", Price = 140m, Stock = 10, Description = "صحفيّ شاب يتعثّر في كتابة روايته الأولى، فيدوّن شذرات في دفتره. في شاليه على البحر ينام إلى جوار حبيبته، وحينما تنهض الحبيبة، تعثر على الدفتر مفتوحًا، الصفحات اليُمنى مسوّدة، واليُسرى فارغة. تجلس إلى مكتبه، وتعيد كتابة الحكاية، أو بالأحرى ملأ ثغراث الحكاية، لكنها تجهل ما ينتظرها.\nرواية منسوجة بخيوط الحُلم والحقيقة عن صدُفات الحياة، وعن القدر، وعن استحالة معرفة أنفسنا ولا معرفة الآخرين معرفة يقينية.", CategoryId = 3, ImageUrl = "/images/products/9789778200522.webp", Author = "أحمد الزناتي", PublishDate = new DateTime(2019, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778200522", Pages = 192, Size = "14×20" },
            new { Id = 391, Name = "تلاندسيا", Price = 120m, Stock = 10, Description = "آن أوان ارتمائي في أحضان الموت وفيه خلاصي، سأذهب لأقف وجها لوجه مع الحاصد الذي أخلفت موعدي معه، ولهذا أبى أن يقطف روحي، سأتخطى حاجز الردى، لعل أحدهم يطلق عليّ رصاصة الرحمة التي أجّلتها الحياة لمدة طويلة، سأتركهم يطلقون سراح روحي المعذبة لأنه لم تكن لدي الشجاعة الكافية لأنهيها بمجرد موت عائلتي، عساني حينها أنجح في عبور نهر الموت، والصعود على متن أحد قواربه بأقل الأوجاع الممكنة، ليوصلني حارس الموتى إلى الأبدية.", CategoryId = 4, ImageUrl = "/images/products/9789778200003.webp", Author = "سلمى الغزاوى", PublishDate = new DateTime(2017, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778200003", Pages = 156, Size = "14×20" },
            new { Id = 392, Name = "secrets of the pharoahs", Price = 130m, Stock = 10, Description = "For thousands of years and to this day, there have been numerous myths and misconceptions about ancient Egypt in the minds of many around the world. Perhaps it is because of the nature of the ancient Egyptians to keep the secrets of their civilization within the minds of their priests, like the secrets of the ancient Egyptian language and  hieroglyphic writing, magical secrets, miracles of architecture,  astronomy, and other knowledge that  other nations  could not understand, and turned into mysteries.  This book comes as a serious and sincere attempt to reveal  falsehoods and refute the myths surrounding ancient Egyptian  civilization, which unfortunately turned into facts in mind of the public and some specialists both inside and outside Egypt. So, let me take you through an interesting journey to discover the secrets of Ancient Egypt and to reveal its mysteries and myths.", CategoryId = 7, ImageUrl = "/images/products/9789778201314.webp", Author = "شريف شعبان", PublishDate = new DateTime(2023, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778201314", Pages = 164, Size = "14×20" },
            new { Id = 393, Name = "لا احد يتعلم من التاريخ 2 - قيصر جديد", Price = 150m, Stock = 10, Description = "مشروعات تشاوشيسكو المكلفة وحرية الاقتراض من الغرب أغرقت رومانيا في الديون إلى حد اضطرت معه الحكومة إلى تصدير بعض السلع على حساب الاستهلاك المحلي، وتدهور الاقتصاد الروماني إلى حد غير مسبوق، وانهارت مستويات المعيشة للغالبية العظمى من الرومانيين، حتى وصفت رومانيا في ذلك الوقت بإثيوبيا أوربا. ومع بداية الثمانينيات، أصبح سداد هذا الدين عبئًا كبيرًا على مالية الدولة، فقرر تشاوشيسكو سداد ديون رومانيا بالكامل، ونظم استفتاء على إجراء تعديل دستوري يمنع رومانيا من تلقي قروض من الخارج في المستقبل، وبناء على هذا القرار، جرى توجيه معظم الإنتاج الصناعي والزراعي للبلاد من أجل سداد الدين، وكانت نتيجة هذه الإجراءات كارثية على الأغلبية الساحقة من الشعب، حيث تم تعميم نظام الحصص من السلع الغذائية في جميع أنحاء البلاد باستثناء العاصمة، وجرى تقليص هذه الحصص على نحو مستمر، وتراجع استهلاك الطاقة بصورة مروعة، وتوقفت أنظمة التدفئة المركزية، وحتى التلفزيون الرسمي قلصت قنواته لتصبح قناة واحدة تبث لمدة ساعتين فقط يوميا، أما الكهرباء فكان يتم قطعها لساعات طويلة وخاصة في الليل من أجل التوفير، وبلغ الفقر وضيق المعيشة مستويات غير مسبوقة، وتم وقف الاستيراد بصورة شبه كاملة، باستثناء استيراد السلع الفاخرة لتشاوشيسكو والزمرة المحيطة به، حتي تم سداد ديون رومانيا كاملة في صيف 1989.", CategoryId = 7, ImageUrl = "/images/products/9789778200430.webp", Author = "بيشوي القمص", PublishDate = new DateTime(2018, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778200430", Pages = 212, Size = "14×20" },
            new { Id = 394, Name = "لا أحد يتعلم من التاريخ 3 - صراع العروش بين سوريا والعراق", Price = 180m, Stock = 10, Description = "يقول الفيلسوف الألماني الشهير فريدرش هيجل \"نتعلم من التاريخ، أن أحداً لم يتعلم من التاريخ\"..\n على غرار الجزء الأول والثاني، يتناول الجزء الثالث من سلسلة \"لا أحد يتعلم من التاريخ\" صراع العروش في كل من سوريا والعراق، منذ اللحظة الأولى لأنطلاق الثورة العربية الكبرى من مكة على يد الشريف حسين بن علي الهاشمي، مروراً بتأسيس الممالك الأربعة في نجد والأردن وسوريا والعراق، ولعبة الكراسي الموسيقية بين عسكر سوريا حتى قيام الجمهورية العربية المتحدة وسقوطها، وصولاً لحكم الاسد وأبناءه، كما يتناول الكتاب تاريخ الملكية في العراق، والمطامع التاريخية في دولة الكويت، ولعبة الكراسي الموسيقية بين عسكر العراق وصولاً لحكم صدام حسين.", CategoryId = 7, ImageUrl = "/images/products/9789778201239.webp", Author = "بيشوي القمص", PublishDate = new DateTime(2022, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778201239", Pages = 248, Size = "14×20" },
            new { Id = 395, Name = "سجلات الليدر شيت", Price = 160m, Stock = 10, Description = "الكتاب يروي قصصًا حقيقية من ساحات العمل، حيث يسود المدير المتسلط أو الغائب عقليًا، وهو لا يسعى لتشويه أحد بقدر ما يسعى لتحويل هؤلاء إلى أمثلة... لا يُحتذى بها!\n\nقد تتساءل: \"وماذا سأستفيد؟\"\n\nالإجابة: الكثير!\nتشير الدراسات إلى أن 75% من الموظفين يَرَون أن مديرهم هو أسوأ ما في العمل، وأن واحدًا من كل اثنين يترك وظيفته بسبب الإدارة السيئة. والأسوأ من ذلك، أن الإدارة الرديئة لا تفقد الشركات موظفيها فحسب، بل عملاءها وإيراداتها أيضًا.\n\nفي المقابل، تُظهر أبحاث DDI وMcKinsey أن المؤسسات ذات القيادة الفعّالة تحقق أداءً وإيرادات أعلى بنسبة تصل إلى 37%.\n\nالقيادة السيئة سمّ بطيء، تنخر في ثقافة المؤسسة، وتخلق بيئة سامة تخنق الإبداع وتُضعف الإنتاجية.\nوقد أظهرت دراسة لـHBR أن 91% من الموظفين يرون أن ضعف التواصل الإداري يقتل الروح المعنوية.\n\nلكن هذه \"اللعنة\" قد تحمل دروسًا ذهبية، لا تُدرّس في كتب الإدارة التقليدية. هذا الكتاب دعوة للتأمل في تلك اللحظات العبثية التي مررنا بها مع مدراء فقدوا البوصلة.\n\nفي الختام:\n\nاحمل فنجانك مجددًا، خفف من جديتك قليلًا، وانضم إلينا في هذه الرحلة الساخرة – لعلنا نضحك، ونتعلم، ونكفّ عن تكرار الأخطاء نفسها.\n\nوخلاصة القول: قصص لم تُروَ من كواليس الإدارة الفاشلة، ودروس حقيقية من ساحات العمل، نقد ساخر لثقافة قيادية متعفنة، ورسالة إلى كل من اعتقد أن القيادة مجرد منصب، لا مسؤولية.", CategoryId = 8, ImageUrl = "/images/products/9789778598599.webp", Author = "سالي العقاد", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778598599", Pages = 170, Size = "14×20" },
            new { Id = 396, Name = "حاولت ان انظر حولى وامامى", Price = 245m, Stock = 10, Description = "النسيان هو أجمل النعم الالهية. فالجهل مثلا يمكن تعويضه بالعلم والفقر يمكن تعويضه بالعمل والكسب، والفقد يمكن تعويضه بالصبر، لكن الإنسان حتى الآن لم يستطع أن يتغلب على النسيان. إنه يحاول وهناك عشرات العقاقير التي تساعد على التذكر لكن يظل النسيان قائما مهما فعلت ومهما قاومت... وفرويد عالم النفس الشهير قدم تفسيرًا صائبا للنسيان: أن ما تنساه هو ما ليس لك رغبة فيه؛ فاللاشعور يساعدك ويطرد ما لا تحبه من الذاكرة لتتوازن شخصيتك وفرويد هنا لا يتحدث عن النسيان الذي قد يحدث لأسباب فيزيقية تتعلق مثلا بتقدم العمر أو حوادث تصيب المخ بفقدان الذاكرة، فرويد هنا يتحدث عن الشخصية السوية.", CategoryId = 8, ImageUrl = "/images/products/9789778202311.webp", Author = "إبراهيم عبد المجيد", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778202311", Pages = 322, Size = "14×20" },
            new { Id = 397, Name = "لغز الوجود والعقل البدائي", Price = 180m, Stock = 10, Description = "يقدم الكتاب دراسة معمقة عن تساؤلات الوجود ونشأة الحياة كما انعكست في أساطير الحضارات القديمة. يتناول مفهوم البداية في العقل البدائي من خلال نماذج متعددة لأساطير الخلق في مصر القديمة، بلاد الرافدين، والصين، وغيرها. يبرز أهمية الماء كجوهر الحياة ومصدر الكون في أغلب الأساطير، ويستعرض قصصًا مثل البيضة الكونية عند الإغريق، وفلسفة الأشمونين التي تمحورت حول المياه الأزلية.\n\nالكتاب يربط بين تطور الفكر الديني والفلسفي وبين الحاجة لتفسير الظواهر الطبيعية، مثل ظهور النور، والسماء، والأرض، ويبحث في أثر هذا الفكر على تنظيم المجتمعات القديمة وصياغة مفاهيم الأخلاق والدين. كذلك، يناقش النصوص الجنائزية المصرية مثل نصوص التوابيت ومتوني الأهرام، التي تقدم تصورات تفصيلية عن الخلق والحياة بعد الموت.\n\nفي النهاية، الكتاب ليس فقط دراسة عن الماضي، بل هو محاولة لفهم كيف كان الإنسان البدائي يسعى لملء فراغات الوجود بأسئلة لم تتوقف حتى اليوم. يُبرز أهمية الفلسفة والأسطورة في بناء الثقافة الإنسانية، مما يجعله إضافة فكرية مهمة.", CategoryId = 7, ImageUrl = "/images/products/9789778202793.webp", Author = "يسرية عبد العزيز", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778202793", Pages = 166, Size = "14×20" },
            new { Id = 398, Name = "سلسلة الدحيحة - الآخوة الإعداء", Price = 220m, Stock = 10, Description = "تجتمع في هذا الكتاب حكايةُ أكبر إبادة عرقية في التاريخ وقصة أعظم داعية إسلامي في أمريكا وحكاية أعظم شخصية رياضية في القرن العشرين، وعندما تجتمع كل هذه الأشياء معًا فاعلم أنك أمام وجبة دسمة من المعرفة، ستغيِّر منظوركَ للكثير من الأمور.\nفكيف اكتشف «كريستوفر كولومبوس» أمريكا؟ وأي ثمن دفعه السكان الأصليون؟\nوكيف تحوَّل «مالكوم إكس» من حياة الإجرام والضياع وصار خطيبًا مفوَّهًا يحرِّك الجموع بكلماته؟\nوما السر الذي جعل «محمد علي كلاي» الملاكم الأعظم في التاريخ؟\nوما الشَّبه بين ما حدث في أمريكا من إبادة عرقية، وما يقوم به الكيان الصهيوني في فلسطين؟\nوكيف تحوَّل إخوة الأمس لأعداء اليوم؟ ومَن الذي اغتال «مالكوم إكس»؟\nوكيف شاركت عنصرية الرجل الأبيض وأطماعه في جميع حكايات هذا الكتاب؟\n\nمن لا يعرف التاريخ فمحكوم عليه بتكراره، وصدقني لن ترغب في تكرار الكثير من الأشياء في هذه الحكايات.", CategoryId = 7, ImageUrl = "/images/products/9789778202434.webp", Author = "طاهر المعتز بالله", PublishDate = new DateTime(2024, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778202434", Pages = 316, Size = "14×20" },
            new { Id = 399, Name = "سلسلة الدحيحة - ديانا", Price = 200m, Stock = 10, Description = "يقول المثل: فاقد الشيء لا يعطيه، ولكنه أحيانًا يعطيه بغزارة. ديانا افتقدت الحب في حياتِها فمنحته لكل مَن حولها. كانت كالشمس مصدرًا للضوء والدفء، فدار الرجال في فلكِها منجذبين إلى نورِها، ولكن مَن اقترب منها احترق بنارِها؛ فمن قتل ديانا؟ وكيف قُتِلت؟ كيف عاشت؟ وكيف أحبَّت؟ كيف انتصرت؟ وكيف هُزِمت؟ والأهم من كل ذلك، كيف استطاعت الفوز بحب الملايين في حياتها إلى درجة جعلتها من أشهر شخصيات العالم وأكثرهم شعبية رغم مرور أكثر من 25 عامًا على وفاتها؟", CategoryId = 7, ImageUrl = "/images/products/9789778201543.webp", Author = "طاهر المعتز بالله", PublishDate = new DateTime(2023, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778201543", Pages = 312, Size = "14×20" },
            new { Id = 400, Name = "سلسلة الدحيحة - اينشتاين", Price = 215m, Stock = 10, Description = "دراسة اينشتاين تساعد علي فهم ما هي جذور العبقرية. الكتاب مهم للاهالي لمعرفة كيفية التعامل مع اطفالهم بشكل يسمح بتنمية اهتماماتهم بدلا من كبتها او محاولة تغييرها. اينشتاين كان طفل عادي بل اقل من العادي، يعاني من مشاكل في النطق بشكل جعل اهله يظنون ان امكانياته العقلية محدودة. ومع ذلك دعموه، وتحملوا شخصيته المستقلة حتي اصبح ما هو عليه. وفي نفس الوقت الكتاب مهم للطلاب لمعرفة تاريخ العلوم التي يدرسون معادلاتها دون معرفة ظروفها التاريخية. معرفتهم لسير العلماء تجعل منهم بشر مثلهم، وتحول العلم لمادة حية أكثر امتاعا. الكتاب يحمل فصل اضافي عن انفجار مفاعل تشيرنوبل لانه يربط بين حادثين غاية في الاهمية، الاول هو اختراع القنبلة الذرية، والثاني هو الحرب الروسية الاوكرانية، حدثان مرتبطان بشكل حثيث رغم بعد ازمنتهما، وكلاهما لم ليحدثا لولا شخص واحد فقط، وهو البرت اينشتاين.", CategoryId = 7, ImageUrl = "/images/products/9789778201659.webp", Author = "طاهر المعتز بالله", PublishDate = new DateTime(2023, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778201659", Pages = 272, Size = "14×20" },
            new { Id = 401, Name = "السير في طرق هادئة ممتدة وبعيدة", Price = 120m, Stock = 10, Description = "\"مجموعة قصصية في إحدى عشرة قصة، عن أحلام زوجات\nصغيرات بحياة سعيدة... وونس وحب، وتأملات نساء صادف أن مر العمر دون أن يقابلهم الحظ والحب...\nورجال يبحثون عن المجد والمال والسعادة... مجموعة بها خيالات عن مستقبل ربما يجيء، وأشباح قصص حب رغم غرقها في دوامات الماضي إلا أنها تطيل أحيانا من هناك لتربك الحكايات\nالجديدة، وتعم فوضى المشاعر بين ما مر وما جاء بين البشر الذين غادروا والذين طال انتظارهم ولم يمروا أبدا من هنا... طرق طويلة وممتدة يحتاج الجميع المضي فيها ربما يجدون سبيلا للوصول....\"", CategoryId = 1, ImageUrl = "/images/products/9789778201857.webp", Author = "نهى محمود", PublishDate = new DateTime(2024, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778201857", Pages = 136, Size = "14×20" },
            new { Id = 402, Name = "و", Price = 120m, Stock = 10, Description = "مجموعة مكونة من 20 قصة، تتراوح بين الواقعى والفانتازى، وفيهارؤية الكاتب عن فن القصة القصيرة، ليس بشكل تنظيرى لكن بشكل عملى\".", CategoryId = 1, ImageUrl = "/images/products/9789778200126.webp", Author = "عمرو العادلي", PublishDate = new DateTime(2017, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778200126", Pages = 154, Size = "14×20" },
            new { Id = 403, Name = "لقاء يفك ازرار السماء", Price = 120m, Stock = 10, Description = "مجموعة من القصص والنصوص الواقعية، التي تلتقط مواقف وأحداثًا مهملةً تمر أمام أعيننا جميعًا كل يوم حتى لم نعد نراها أو نلتفت إليها، وتتوقف عندها وتغوص في شخوصها لتتأملهم لحظة، وتريك كم هي مدهشة، وكم هو مدهش أننا فقدنا قدرتنا على الاندهاش والتأمل والتعمق إلى هذا الحد.\"", CategoryId = 1, ImageUrl = "/images/products/9789776376342.webp", Author = "فاطمة الزهراء الرياض", PublishDate = new DateTime(2016, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789776376342", Pages = 126, Size = "14×20" },
            new { Id = 404, Name = "أم الولى", Price = 120m, Stock = 10, Description = "تمسّد «أمي» الحائط الذي وضعتني فيه قبل سنوات بعيدة. تطلب مني أن أتحول من «حارث» إلى «حارس». تُعلِّق عينيها بالحائط والسقف. تناجي الرب وتتشفع بعدد من فقدت طيلة سنوات كثيرة. تنظر للحائط بغضب، تطلب مني أن أفعل شيئًا وأن أمنع ملك الموت من أن يجوس الغرفة ويقترب من أُختي. أسمع بكاءها ونجواها وأتطلع معها عاجزًا- نحو السقف.", CategoryId = 1, ImageUrl = "/images/products/9789776376656.webp", Author = "تسنيم فهيد", PublishDate = new DateTime(2015, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789776376656", Pages = 146, Size = "14×20" },
            new { Id = 405, Name = "عند مدام عفاف", Price = 120m, Stock = 10, Description = "كل موظف لديه أداة تعذيب مفضلة لسلخ المواطن المصري وتعجيزه .. منها: فوت علينا بكرة .. السيستيم واقع .. الختم مش واضح .. الخزنة قفلت .. ولكن أشد هذه الوسائل عنفا وتأثيرا هي \" عند مدام عفاف \" التي تقف كالسد العالي أو كمحاربي السومو أمام من تسول له نفسه من المواطنين التقدم بأي طلب .. في هذا الكتاب ثلاث قصص ساخرة لمواطنين تم تعذيبهم بالروتين والبيروقراطية ومدام عفاف .. وفي حين تبدو القصص خيالية الا انها - ويا للعجب - مأخوذة عن قصص حقيقية مائة بالمائة. في نهاية هذا الكتاب مفاجئة لقراء د. أحمد خالد توفيق .. حيث يطل علينا رفعت اسماعيل وماجي في قصة ساخرة بالكامل ( اسطورة الفتوة ) كيف يتحول رفعت اسماعيل من طبيب واستاذ جامعي الي (فتوة) هذا ما يتبين من الأحداث .. وقد نشرت هذه القصة بناء على موافقة سابقة من د. احمد خالد توفيق رحمه الله", CategoryId = 8, ImageUrl = "/images/products/9789778200713.webp", Author = "تامر أحمد", PublishDate = new DateTime(2020, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778200713", Pages = 160, Size = "14×20" },
            new { Id = 406, Name = "قصائد أولي (أمل دُنقل)", Price = 130m, Stock = 10, Description = "كتاب قصائد أولى للشاعر أمل دنقل هو مجموعة من القصائد التي تميزت بعمقها العاطفي والنقدي والاجتماعي، وكتبها الشاعر في مقتبل حياته، ما يظهر فيها بساطة التعبير وأصالة الأحاسيس. يتناول الكتاب مواضيع متعددة من بينها الحب، الألم الإنساني، النقد السياسي والاجتماعي، والصراع الداخلي. ومن أبرز قصائده \"العيون الخضر\"، \"أين المسيح؟\"، \"اعتراف\"، و\"أوجيني\"، والتي تجمع بين الجمالية اللغوية والعمق الفكري.", CategoryId = 8, ImageUrl = "/images/products/9789778202809.webp", Author = "أمل دُنقل (إعداد أنس دنقل)", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778202809", Pages = 160, Size = "14×20" },
            new { Id = 407, Name = "تدبر مقاصد الصوم وأسراره", Price = 100m, Stock = 10, Description = "يُبرِز كتيبُ الدكتور عبد الله منجود أسرارَ الصومِ ومقاصدَه مُستلهِمًا نصوصَ السلفِ، ومُضيفًا إليها بصائرَ تُواكِبُ روحَ العصر.\nإنه مدخل لمن أراد أن يتذوّق تدبر أسرار ومقاصد الصوم بمعناه الكامل: عبادةً، وتسليما وتقوي.\nيمضي المؤلف بالقارئ في رحلة تأملية، تمتد من آيات القرآن وأقوال الرسول صلي الله عليه وسلم والصحابة والتابعين ، إلى تساؤلات الإنسان المعاصر وهمومه الروحية. فلا يتناول المؤلف جفاف الفقه ،أو غموض التصوف المجرد، بل توازن بين المعرفة والحكمة ، لإكتشاف أسراره الدفينة بما يفتح الله علي كل متدبر من عمق المعنى، وتزكية النفس.", CategoryId = 8, ImageUrl = "/images/products/9786339968044.webp", Author = "عبد الله منجود", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786339968044" },
            new { Id = 408, Name = "دليل المؤمنين لتدبر كتاب رب العالمين", Price = 150m, Stock = 10, Description = "يُقدِّم كتاب (دليل المؤمنين لتدبّر كتاب رب العالمين ) للدكتور عبد الله محمد منجود رؤيةً عمليّةً\nفي تدبّر القرآن، مستلهمًا روح الصحابة والتابعين - رضوان الله عليهم - الذين تلقّوا كلام الله من فم رسول الله ﷺ، فتفاعلوا معه واهتدوا بهداه وتقبلوه بقلوبٍ واعيةٍ، وعقولٍ متفتحةٍ، وتطبيق عملي ،\nحتى صار القرآن ملازمهم في القول والعمل.\n\nوالكتاب نتيجة (لأكثر من عشر سنوات من تدريس التدبر كمنهج عملي وقواعد في التعامل مع القرآن\nمبني على أسس علمية مقررة عند أهل التفسير في فهم كلام الله عز وجل وتفهميه للناس وتطبيقه ،\nقد أثبتت التجربةُ فاعليته في تحويل التدبّر إلى عبادة (تثمر) تحوُّلًا جذريًا في حياة الملتزم به.\n\nإنه دعوة صادقة للعودة إلى القرآن كما نزل: هاديًا، مصلحًا، ومغيّرًا، يعتمد على الفهم السليم والتطبيق لهدي القرآن الكريم فى تزكية النفوس.", CategoryId = 8, ImageUrl = "/images/products/9786339969430.webp", Author = "عبد الله منجود", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786339969430" },
            new { Id = 409, Name = "إعدام الياسمين", Price = 200m, Stock = 10, Description = "إعدام الياسمين — هاني الغيتاوي. من إصدارات دار واحة الأدب للنشر والتوزيع.", CategoryId = 1, ImageUrl = "/images/products/9786339969478.webp", Author = "هاني الغيتاوي", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786339969478" },
            new { Id = 410, Name = "جلست بين يدى رسول الله", Price = 200m, Stock = 10, Description = "خذت آمنة نفسًا عميقًا وبدأت لحظة الولادة، وقبل أن يخرج منها الرضيع انبثق منها نور أبيض اخترق جدران البيت فامتد في الأفق حتى طُويت الأرض فأضاء قصور الشام البعيدة، ولمحتُ آمنة تنظر بدهشة إلى هذا الضوء وكأن الحُجبَ قد كُشفت عن بصرها فرأت مشارق الأرض ومغاربها.", CategoryId = 1, ImageUrl = "/images/products/9786339968075.webp", Author = "عبد الله ناصر", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786339968075" },
            new { Id = 411, Name = "روتين النفس المطمئنة", Price = 100m, Stock = 10, Description = "نظرا لكثرة الذنوب والمعاصي والملهيات والمشتتات والبعد عن الله وخراب الذم واستحلال الحرام وتحريم الحلال والعبث في ثوابت الدين، والتشكيك فيما هو معلوم من الدين بالضرورة، والتطاول على سنة نبينا صل الله عليه وسلم، وانتشار البدع\nفذلك يدفعنا لإيجاد روتين لترميم النفس كما يوجد روتين لترميم الجسد", CategoryId = 8, ImageUrl = "/images/products/9786339968051.webp", Author = "فاطمة شيبانى", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786339968051" },
            new { Id = 412, Name = "مملكة إيلداموار", Price = 200m, Stock = 10, Description = "طبيب شاب يجد نفسه فجأة في قلب مملكة سحرية مهددة بالدمار. بينما هناك مخطوطة غامضة يحمل مفتاح إنقاذ إيلدامورا أو سقوطها. ووسط صراع ملحمي بين قوى الخير والشر، ليكتشف كريم أن مصيره مرتبط بهذا العالم أكثر مما يتخيل. هل سيتمكن من فك رموز الكتاب وإنقاذ المملكة قبل فوات الأوان؟", CategoryId = 1, ImageUrl = "/images/products/9786339968068.webp", Author = "عبدالله ناصر", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786339968068" },
            new { Id = 413, Name = "الروهانا وليدة الفجر السابع", Price = 200m, Stock = 10, Description = "لا تخرج عند اكتمال القمر… لا تذكر اسم المندور… واحذر أن تدخل هذه القرية ليلًا، وإن وطئتها نهارًا فاخرج قبل المغيب.\nففيها الجن يتناحرون من أجل الروهانا، والناس يموتون، واللعنة لا ترتوي، ولا تهدأ، ولا تنتظر حتى تفهمك؛ يكفي أن يمر عليك قمرٌ واحد، حتى يُكتب اسمك في سِلْسَال الدماء.", CategoryId = 1, ImageUrl = "/images/products/9786339968082.webp", Author = "عبدالله ناصر", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786339968082" },
            new { Id = 414, Name = "التفرد الإعجازى للقرآن الكريم الجزء الأول", Price = 300m, Stock = 10, Description = "قراءة جديدة للقرآن الكريم كمنظومة معرفية كونية متكاملة، لا ككتاب هداية روحيّة فقط. ينطلق الكتاب من سؤال جوهري: هل يوجد جسر حقيقي بين الوحي الإلهي والعلم التجريبي الحديث؟\nنستكشف الاجابة عبر أربعة محاور كبرى: الإعجاز اللغوي والبياني، الإعجاز العلمي، الإعجاز الرقمي والعددي، ثم الإطار النظري المتقدم المتمثل في أكثر من 160 نظرية علمية مستنبطة من الأنماط الرياضية القرآنية، تمتد من فيزياء الطاقة والمعلومات إلى علوم النانو والفيزياء الكمومية وعلوم الوعي. يربط الكتاب بين الدقة المعجزة في اختيار الألفاظ القرآنية وبين حقائق كونية مكتشفة حديثاً، ويبرهن بالأرقام والمعادلات على وجود نظام عددي محكم في بنية السور والآيات والكلمات، يكشف عن تناغم عجيب بين اللغة والعدد والكون. لا يكتفي هذا العمل بعرض وجوه الإعجاز المعروفة، بل يتقدم خطوة أبعد ليقترح إطاراً نظرياً جديداً لفهم العلاقة بين الطاقة والمعلومات والوعي والزمن، من خلال نظريات مثل: التردد الكوني المتناغم، المجال الزمني غير الخطي، التجانس الكمي المعلوماتي، التنظيم الذاتي النانوي المتناغم، والوعي الكمومي متعدد المستويات. هذه النظريات لا تُطرح كشعارات عامة، بل تُبنى على أنماط رقمية دقيقة في النص القرآني، مع إثباتات رياضية وصيغ ومعادلات وتطبيقات مقترحة في الطاقة المتجددة، والطب، والاتصالات، والبيئة، والحوسبة المتقدمة.\n\nيتكوّن هذا الكتاب من 4 أجزاء: التفرد الإعجازى للقرآن الكريم الجزء الأول، التفرد الإعجازى للقرآن الكريم الجزء الثانى، التفرد الاعجازى للقرآن الكريم الجزء الثالث، التفرد الاعجازى للقرآن الكريم الجزء الرابع.", CategoryId = 8, ImageUrl = "/images/products/9786339969409.webp", Author = "محمد عمرو سامى", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786339969409" },
            new { Id = 415, Name = "همس الفكر و الخطايا", Price = 250m, Stock = 10, Description = "ولكل كتاب رسالة، ورسالتي من هذا الكتاب هي التمرد على القبح وصنع الجمال بعذب الكلمة وسحر معناها، وأنا لا أدعي عذب الكلمة وسحرها وإن كنت أحسبها كذلك، لكن الحكم والتقييم لك عزيزي القارئ، واعلم أن هذه العبارات نتاج قدح فكر، وعناء تجربة، ومواقف لامست الوجدان وأخرى هيجت الانفعالات الحزينة، وأراني أعتقد أنَّ كلَّ ما كُتب في هذا الكتاب، هو دعوة للحب وللجمال، وكما يقول \"رالف أميرسون\" في كتابه \"الجمال مفعّل الحياة\": \"الحب يُعلي من طاقة الموهبة وبه نتغلب على العثرات\"، والحياة كما يقول الدكتور عمار علي حسن: \"مكابدات لا تنتهي وكدح لا يتمهل ومعاناة لا تكف\"", CategoryId = 8, ImageUrl = "/images/products/9786339969423.webp", Author = "هانى الغيتاوى", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786339969423" },
            new { Id = 416, Name = "أنفورجيا", Price = 100m, Stock = 10, Description = "أَنْفُورْجِيَا\n​في مكان ما بين الألم والأمل، تبدأ قصة لا تُكتب فقط لتُروى،\nبل لتُشعر وتُعاش.\nهل هي ضحية؟ أم بطلة تخوض معركة خفية؟\nوراء كل جرح، وكل ابتسامة،\nتكمن حقيقة غائبة عن الأنظار؛\nصوت لم يسمعه أحد، ودمعة لم يرها أحد.\nهل يمكن للروح أن تلتئم بعد كل ما حدث؟\nأم أن هناك جرحاً لا يشفى أبداً؟\nقد تكون الإجابة أعمق مما نتصور،\nوأقرب مما نريد أن نراه،\nمختبئة في الزوايا التي نتهرب منها.", CategoryId = 1, ImageUrl = "/images/products/9786339969447.webp", Author = "مريم محمد الدالى", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786339969447" },
            new { Id = 417, Name = "أهازيج القدر", Price = 250m, Stock = 10, Description = "لقدر أهازيج ربما تكون سالبة للأنفاس عندما يحمل بين ألحانه العشق والشغف فتجده لحنا يداهم قلبك مربتًا على روحك..لكن من منا يتحكم في قدره أو له السلطة عليه..فالقدر مكتوب لكن لا يمكنك قراءته..\nفي لحظة تتغير الأقدار لتجدها أهازيج صاخبة ومؤلمة لقلبك الذي أضحى يبكي الفراق والفقد صارخًا بآلم عندما يخسر من كان له الحياة..\nلذا انتبه يا صديقي فبداخل سطور قصتنا ستجد للقدر ألاعيب تعلمك أن للخطأ عواقب ربما لن تتحملها، لذا كن مخلصًا قبل أن تكون عاشقًا حتى لا تدفع الثمن من روحك وقلبك الذي سيصارع إلى مالا نهاية.", CategoryId = 1, ImageUrl = "/images/products/9786339969454.webp", Author = "شيرى الجرف", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786339969454" },
            new { Id = 418, Name = "أثر على جدار الزمن", Price = 200m, Stock = 10, Description = "ليس التاريخ ما كُتب فقط، بل ما ترك أثرًا وبقي. التاريخ ليس مجرد أسماء تمرّ في الصفحات، بل حكايات ناس عاشوا زمنهم بصدق، وتركوا أثرًا ظلّ ثابتًا رغم تغيّر الوجوه وتعاقب السنين. هذا الكتاب رحلة هادئة للبحث عمّا تبقّى خلف الجدار؛ عن أصوات خفتت، لكن حضورها لم يغب، وعن وجوه صنعت لحظتها ثم انسحبت في صمت، تاركة بصمتها شاهدة على أنها كانت هنا.", CategoryId = 8, ImageUrl = "/images/products/9786339969461.webp", Author = "مروة طلعت", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786339969461" },
            new { Id = 419, Name = "بين أروقة الماضى", Price = 250m, Stock = 10, Description = "أركض بين أروقة الماضي أُلملم بقايا الذكريات.\nأطرق أبوابًا عتيقة، موصدة بأقفالًا قد صدئت بدموع الفراق.\nأين أنا؟\nوكيف تناقضت روحي هكذا بين الماضي والحاضر.\nلقد نفيت من تعقلي وجعلت الفوضى موطني.\nأحلامي أضحت جاثوم خانق.\nروحي تائهة بين غياهب الذكريات.\nقُل لي أيا عشقًا ظلمني لأي عالم كنت أنتمي.\nياعشقًا أحياني وقتلني.\nيا آلم ينبض بين أضلعي.\nيا طيف حبيب غائب ترفق بي، فالجنون يكاد يزورني.", CategoryId = 1, ImageUrl = "/images/products/9786339969485.webp", Author = "شيرى الجرف", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786339969485" },
            new { Id = 420, Name = "آتون الحب و الحقد", Price = 250m, Stock = 10, Description = "هل أهداهم القدر حياة جديدة،\nأم لعنهم بآخرى غيرت حياتهم ودمرت أحلامهم البريئة..بعدما خسروا براءة الطفولة وحصنهم الآمن، تركهم مابين طعنة غدر، وأيدي حاقدة غرست تجتث أوردتهم البريئة حتى نُزفت أخر قطرات النقاء وحل محلها ضراوة الانتقام، وجمود قلب تَعلم ألا يعرف للرفق طريق..وبين آتون الحب والحقد اتحد الأخوه، ليس لتحويل الجبال إلى ذهب، انما لتفتيتها وتحويلها لإعصار ساحق لن يردعه رادع.", CategoryId = 1, ImageUrl = "/images/products/9786339970306.webp", Author = "شيرى الجرف", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786339970306" },
            new { Id = 421, Name = "أوراق المطر", Price = 120m, Stock = 10, Description = "إبان الرحيل بالداخل\nكانت تسافر إلى المجهول\nفي مناطق اللغة\nأبجدية العثور على النظير\nوالظهير المقابل\nكالأفكار التي تتناثر محلقة\nبين أروقة الكتب\nفي عرف الفراشة\nفراسة المرء خفة\nفي لحظات الحب العاصفة\nوالترقب الصارخ كضوضاء\nهامسة بالهدوء\nقبع الوله مملوء بالضجيج\nسائرة بين الدروب\nتلملم المدى كمظلة\nحمراء\nتشع من ثغرها البهجة\nمنبعثة من الأعماق\nمنيرة في محيطها\nانصهري أيتها الشمس\nفي يدها أزهار سائلة\nذهبية اللون تفوح بالأريج\nيتراقص الظل الساطع\n​الشاعر والكاتب حسن الشريف", CategoryId = 8, ImageUrl = "/images/products/9786339970313.webp", Author = "حسن الشريف", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786339970313" },
            new { Id = 422, Name = "دماء الشمس", Price = 300m, Stock = 10, Description = "عد أن خمدت نيران زِيين وانطفأ نسله، لم يكن الانتصار إلا بداية لمعركة أخرى… داخلية.\n\nسيلين، من تحدّت الظلام لأجل من تحب، تواجه قرارًا قلب موازينها.\nداميان، من ظنّ أن قلبه مات قبل قرنين، يعثر على توأم روحه خلف جدران الأسر.\nكايدين، الملك الذي نذر نفسه لحماية شعبه، يجد أن التحدي الحقيقي يبدأ حين يسكن السكون، ويعلو صوت الروح الممزقة.\n\nفي عالمٍ ينهض من رماده، يبدأ الأبطال رحلة البحث عن ذواتهم المبعثرة، وعن خلاص لا يأتي بالسيوف… بل بالمواجهة الصامتة لما تركته الحرب خلفها.\n\n“أحياناً، لا يكون أصعب ما في المعركة هو القتال… بل البقاء بعد انتهائها.”", CategoryId = 1, ImageUrl = "/images/products/9786339970320.webp", Author = "أمل القادرى", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786339970320" },
            new { Id = 423, Name = "أنين الروح", Price = 300m, Stock = 10, Description = "عد أن خمدت نيران زِيين وانطفأ نسله، لم يكن الانتصار إلا بداية لمعركة أخرى… داخلية.\n\nسيلين، من تحدّت الظلام لأجل من تحب، تواجه قرارًا قلب موازينها.\nداميان، من ظنّ أن قلبه مات قبل قرنين، يعثر على توأم روحه خلف جدران الأسر.\nكايدين، الملك الذي نذر نفسه لحماية شعبه، يجد أن التحدي الحقيقي يبدأ حين يسكن السكون، ويعلو صوت الروح الممزقة.\n\nفي عالمٍ ينهض من رماده، يبدأ الأبطال رحلة البحث عن ذواتهم المبعثرة، وعن خلاص لا يأتي بالسيوف… بل بالمواجهة الصامتة لما تركته الحرب خلفها.\n\n“أحياناً، لا يكون أصعب ما في المعركة هو القتال… بل البقاء بعد انتهائها.”", CategoryId = 1, ImageUrl = "/images/products/9786339970337.webp", Author = "أمل القادرى", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786339970337" },
            new { Id = 424, Name = "قلب التنين", Price = 300m, Stock = 10, Description = "ثلاث وعشرون سنة مرّت…\nوها هو القلب الملعون ينبض من جديد.\n\nقلبٌ أُغلق عليه بين الأضلاع منذ آلاف السنين، حين سُجن “لوسيفر” بتعويذة سحرية خنقته في سبات أبدي.\nلكن هناك من لم ينسَ…\nمصاص دماء مرتد، لا يزال يسعى لإحياء سيده، مهما كلّف الأمر.\n\nعودة لوسيفر ليست مجرد نبوءة… إنها كارثة تتسلّل من بين الظلال، معلنة بدء النهاية، وجحيمًا يوشك أن يبتلع الأرض.\n\nوفي مواجهة هذا المصير، يقف التوأم “كايل” و”آرُن”، أبناء كايدين، ليس فقط لحماية العالم، بل لحماية من اختارتهم قلوبهم… في زمنٍ لم يعد فيه الحب كافيًا، ولا الدم كفيلًا بالنجاة.\n\nفهل يكفي النور المتوارث في عروقهم لإخماد الظلام الذي نهض من رماده؟\nأم أنّ قلب التنين… سينبض بالموت؟", CategoryId = 1, ImageUrl = "/images/products/9786339970344.webp", Author = "أمل القادرى", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786339970344" },
            new { Id = 425, Name = "أطياف الجحيم", Price = 300m, Stock = 10, Description = "استيقظت من غياهب العدم، في حفرة على جزيرة تنبض بالأسرار ، بلا اسم… بلا ذاكرة… وكأنّها وُلدت من جديد في أرض المجهول.\nفي مستعمرة خفية، تتوارى عن أنظار الملك كايدين، وجدت نفسها أسيرةً لقوانين صارمة، وأصواتٍ تهمس من الظلال أن ماضيها أخطر مما تتخيّل.\n\nوهناك… التقت به.\nعبدٌ هارب، يحمل جسده وشم العذاب، وروحه موصولة بجحيم لم ينطفئ. فارس بلا مملكة، وطيفٌ من أسطورة منسيّة، لا يثق بأحد… ولا ينتظر النجاة.\n\nبينهما تنبعث شرارة من نور ، كأنها مكتوبة منذ قرون.\nفهل يكون لقاؤهما خلاصاً… أم بوابة إلى لعنة لا عودة منها؟", CategoryId = 1, ImageUrl = "/images/products/9786339970351.webp", Author = "أمل القادرى", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786339970351" },
            new { Id = 426, Name = "غرفة خمس نجوم", Price = 120m, Stock = 10, Description = "هل سبق أن نظرت في المرآة طويلًا… دون أن تعدل شعرك؟ دون أن تضبط هندامك؟\nهل جرّبت أن تحدّق في وجهك دون حُكم، دون نية مسبقة، دون أن تهرب من الملامح التي تفضحك أكثر مما تظهرك؟\nأنا لا أسألك عن ملامحك، بل عن وجهك الحقيقي.\nذاك الوجه الذي يظهر فقط عندما تنفرد بنفسك… وتكفّ عن التمثيل.\nاسأل نفسك الآن:\nمن أنا حين لا يراني أحد؟\nمن هذا الذي يقف خلف نظراتي، ويتكلم داخل رأسي، ويخاف أن يُكشَف؟", CategoryId = 1, ImageUrl = "/images/products/9786339971051.webp", Author = "محمد جاد", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786339971051" },
            new { Id = 427, Name = "جرائم المحتلين في أرض فلسطين من النكبة حتى اليوم", Price = 150m, Stock = 10, Description = "فلسطين ليست خارطة على ورق، بل جرحٌ نابض، وصرخةُ شعبٍ لا تندمل.\nلن تُمحى من الذاكرة، ولا تُدفن في التاريخ.\nهذه الأرض، كل ذرة فيها تصرخ: فلسطين للفلسطينيين، والاحتلال إلى زوال.\nهذا ليس قدَرًا.. بل ظلم عابر، سيزول بإذن الله وقوة الحق", CategoryId = 1, ImageUrl = "/images/products/9786339970368.webp", Author = "محمد رضا إبراهيم", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786339970368" },
            new { Id = 428, Name = "مستعمرة ما بعد الموت", Price = 150m, Stock = 10, Description = "تدور احداث رواية مستعمرة ما بعد الموت عن مدينة تشتعل بها حرب خفية بين الطموح والخداع، ويغدو الدم أثمن من الذهب.تتحول الحياة إلى وباء، والماء إلى سرّ لا يُشرب، فيما ينهض من الرماد عالم لا يرحم.\nيهرب الناجون إلى حصنٍ بُني قبل النهاية بوقتٍ طويل، لكن جدرانه تعرف أكثر مما تُخفي.\nيعود الماضي ليحاكم الحاضر، وتتشابك الأزمنة كأنها تتنفس من جرحٍ واحد.\nوعندما يظهر \"الظل\"، يدرك الجميع أن الموت لم يكن سوى بداية المستعمرة.", CategoryId = 1, ImageUrl = "/images/products/9786339970375.webp", Author = "مديحة ممدوح عارف", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786339970375" },
            new { Id = 429, Name = "عرش النجوم", Price = 200m, Stock = 10, Description = "\"أحيانًا، لا يولد الأبطال من رحم العدالة... بل من شرارات العداء!\"\n\nفي عالم يطفو على حافة الانهيار، وعروش تتصدّع تحت وطأة الجشع والهيمنة، تجتمع نقيضتان: أحمد أيوب، الضابط المنضبط في خدمة النظام، ومورجانا، قائدة قراصنة جامحة ترفض الانصياع لأي قانون. لم يكن من المفترض أن يتحالفا… لكن الخطر الذي يُهدد المجرة بأسرها لا يفرق بين عدو وحليف.\n\n\"عرش النجوم\" ليست مجرد ملحمة فضائية، بل صراع داخلي عن الهوية، الولاء، والحب المولود من رماد المعارك. على مدار رحلتهم، تنقلب القواعد، وتتغير التحالفات، ويواجه كل منهما ماضيه، ليكتشف أن مفتاح النصر ليس في السلاح الأقوى… بل في قوة الروح والتضحية.\n\nحين يُفعّل \"العرش\"، لا يستجيب إلا لنقاء القلوب. وفي لحظة واحدة، تتحول المعركة من أجل السيطرة... إلى معركة من أجل معنى الحياة نفسه.", CategoryId = 1, ImageUrl = "/images/products/9786339970382.webp", Author = "أحمد أيوب", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786339970382" },
            new { Id = 430, Name = "جبرئيل المخلوق الأعظم والملأ الأعلى (الأنبياء و النبيون)", Price = 400m, Stock = 10, Description = "كان اللهُ ولم يكن معهُ شيءٌ فهو اللهُ إن خَلَقَ شيئاً وإن لم يخلق أيَّ شيءٍ، هو العظيمُ في ذاتهِ دائماً وأبداً دونَ بدايةٍ ولا نهاية.\nثم خلقَ المكانَ وهو السمواتُ والأرض، وهو المُنَزّهُ عن الزمانِ وعن المكانِ وهو خالِقُهُما, وهو غيرُ موجودٍ, اِنّهُ خالقُ الاكوان التي هي الوجودُ الحادِثُ لِفِعلِهِ وهو مُنزَّهٌ عنهُ فهو ليس اَعلاه, هو فوقَ كلِّ شيءٍ وليس تحتَهُ شيء, وهو في كلّ شيءٍ وليس كشيءٍ في شيء, هو الواحدُ بلا عدد وقائم بلا عمَد لا يُسالُ عنه بمتىَ كان, فهو خالقُ الزمان ولا يُساَلُ عنه بِاَينَ فهو خالقُ المكان.\nاِنّ اَفعالَ اللهِ حادثةٌ وهو اَزَليٌّ كُلّيُّ العِلمِ والقُدرة, هو الازَليُّ في وجودهِ بلا بدايةٍ والسّرمديُّ بلا نهاية, صَمَدٌ على ما هو عليهِ, فهو خارجُ مَنظومةِ الحادِثِ وما فيها مِن مقاييسٍ ومواصفات فهو خارجٌ عن الزمكان فلا ينطبقُ عليهِ ما ينطبقُ على منظومةِ الكونِ والمخلوقات. لا ينطبقُ عليهِ عروجٌ او صعود, او انتقالٌ او هبوط او ارتفاعٌ او اِنزالٌ او تنزيل وهو ليس فوقٌ وليس تحت.\nفالكونُ في تكوينهِ نسبيٌّ مَحدودٌ بالزمانِ والمكانِ واللهُ مُطلقٌ في ذاتِهِ, وجودُهُ ذاتيٌّ مُستغنٍ عن غيرهِ, ولكنّ وجودَ الاكوانِ حادثٌ يفتقرُ الى اللهِ ويقومُ بقوتِهِ.\nفهوكانَ على ما كان قبلَ خلقِ المكان ولا يتغيرُ عما كانَ, عَلِمَ ما كان وما يكونُ وما لايكونُ ولو كان كيف يكون فهوما وراءَ كل شيءٍ ليسَ كمثلِهِ شيء وهو السميع البصير.", CategoryId = 8, ImageUrl = "/images/products/9786339970399.webp", Author = "طارق عزب", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786339970399" },
            new { Id = 431, Name = "سديم الباروك", Price = 300m, Stock = 10, Description = "في قلب العاصفة، وُلدت سديم… نصف عرّافة، نصف لعنة.\n\nلم تكن تعرف أن دقات قلبها ترتبط بنبض كائن آخر…\nذئبٌ يتربص بروحها، ويشدّها إليه بحبل من دم لا ينقطع.\n\nقُدّر لها أن تكون فريسة ونبوءة،\nعاشقة وغنيمة.\nوبينما العالم ينهار من حولها، كان هو الوحيد القادر على انتشالها… أو دفعها نحو الجنون.\n\nقوةٌ غامضة تنمو في عروقها،\nرغبةٌ لا تعرف الرحمة تنمو في عينيه.\nوسؤال واحد يتردّد في ظلالهما:\nهل يُمكن للحب أن يولد من اللعنة؟\n\nسديم الباروك، عرافة الألفا\nرواية عن رابطٍ أبدي لا يُكسر… وعن صراع يتجاوز السحر والدم، إلى ما هو أعمق: الروح.", CategoryId = 1, ImageUrl = "/images/products/9786339971006.webp", Author = "أمل القادرى", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786339971006" },
            new { Id = 432, Name = "يوم حلت العقد", Price = 250m, Stock = 10, Description = "هواء ثائر يعبث بردائهم السابغ الذي يلامس أحذيتهم، تتأرجح قلنسوة الرداء فوق جباههم بقوة وكأنها تغربل الأفكار وتحسم القرارات.\nكلاهما غافلان عن ميل الشجرة عن يمينهم وقد أوشك الهواء على اقتلاعها، ما تجابهه أفكار هم أقوى وأقسى.\nلنتركه لربما عاد إلى رشده، ونكون قد احتوينا فرداً جديداً وكنا عوناً له على نفسه.\nمن سرق تقطع يده ليكون عبرة لمن بعده، اليوم سرق، وفي الغد يقتل، من استباح شيئاً ليس من حقه عليه عقوبة وإلا سيتمادى بلا رادع.\nاختلاف جذري بين آرائهم التي جُبلوا عليها، وكان أحدهم أخذ من سماحة المياه في انسكابها، والآخر أخذ من تعلق الصوف بالسيخ منهجاً.\nيهدأ الهواء حولهم لتستقر الشجرة وتستقيم عن ميلها\nلنمرر الأمر.\nوماذا عن تلك العين المراقبة، ألن تسأل عن القاتل، ألن تحيك الشباك للقصاص منه.\nستلهيه الحياة بما فيها من مصاعب.\nبل ستكون تلك هي أول المصاعب، وربما تكون الأصل الذي ستدور حوله حياته.\nيتحدثان من خبرتهم على مر العصور، لا يتذكر أحدهم كم عمره، ولماذا يعيشون في تلك المنطقة النائية تُعرض عليهم الأقدار ليخوضوا نقاشاً متكرراً لم يضع أحدهم حتى الآن نهايته", CategoryId = 1, ImageUrl = "/images/products/9786339971037.webp", Author = "هالة حمدى", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786339971037" },
            new { Id = 433, Name = "ندينجي", Price = 250m, Stock = 10, Description = "أنت في( ندينجي) حيث الخطيئة هي الأصل والتوبة منبع الشرور.\nأنت في (ندينجي) فيها يصبح إلهك هواك، دنس روحك هو طريقك إلى القمم، وآثامك هي راحلتك إلى ما تصبو.\nأنت في (ندينجي ) حيث مُحِيّ نور النفوس وشاع ظلامها.\nأنت في( ندينجي) حيث فُرخت الشهوة، عُبدت الرذيلة، وقُدس المال وأصبح كل حرام مباح.\nأنت في (ندينجي) حيث يتوضأ العجائز بالدماء وتغتسل العذارى بالخطايا.\nأنت في (ندينجي)\nفلا أهلًا ولا مرحبًا..", CategoryId = 1, ImageUrl = "/images/products/9786339971099.webp", Author = "بدور عادل", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786339971099" },
            new { Id = 434, Name = "زوشادو", Price = 150m, Stock = 10, Description = "بعد أن وقع العالم تحت وطأة الكورونا انقلبت كل الأمور رأسًا على عقب!\nظهر ابتلاء لا قِبل للبشر بمواجهته، في محاولات لإيجاد مخرج من ذلك الابتلاء تدور الصراعات.\nفهل سينتصر البشر؟!\nأم يندثرون تحت الثُرى مسطرين نهاية الكوكب الذي نعرفه؟!", CategoryId = 1, ImageUrl = "/images/products/9786339971044.webp", Author = "نشوة أبوالوفا", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786339971044" },
            new { Id = 435, Name = "تأملات الفكر و الخاطر", Price = 250m, Stock = 10, Description = "يُداوون أنفسهم من الهموم والأحزان، يفتحون لأنفسهم طرقاً يسلكونها يلتمسون فيها معاني الصبر والسلوان على ما ألمّ بهم من ملمات وأحزان، لذلك عندما تراهم تجدهم باسمين متطلقين، وكأنهم لا يُعانون من شيء، ولو تركوا مساحة لتطلع على حقيقتهم لوليت فراراً ولمُلئت نفسك من أجلهم حزناً وهماً وكمداً.\nهم ولا شك صفوة الناس، فرغم ما يثقلهم من هموم وأحزان، تكلفوا السرور، حتى لا يُسببوا لغيرهم التعاسة، ولا يُصدّرون لهم اليأس والقنوط.\nهؤلاء يُشرفون على الحياة والابتسامة عالقة على ثغرهم لا تفارقهم، يُقبلون على الدنيا متطلقي الوجه، يراهم الرائي فيغبطهم على حالهم، مغتراً بابتسامة ثغرهم وتطلق وجههم، ربما لو أمعن هذا الرائي قليلاً، وكشف عن أنفسهم، ووجوههم الباسمة المتطلقة لاسترد غبطته إلى نفسه، وترشف من القناعة ترشفاً تجعله يرضى عن حاله.", CategoryId = 1, ImageUrl = "/images/products/978633991068.webp", Author = "هانى الغيتاوى", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "978633991068" },
            new { Id = 436, Name = "رقص على الجمر", Price = 150m, Stock = 10, Description = "تدور أحداث الرواية عن الصراع ما بين القلب والعقل وحرب ما بين العادات ومواطن القوة والعزة في النفوس، عادات قديمة من الاعتزاز فقط بالذكر وتهميش واحتقار كامل للأنثى، فهل سيفرض القلب والرحمة سطوتهما أم يندثران تحت وطأة ظلم العادات الموروثة؟", CategoryId = 1, ImageUrl = "/images/products/9786339971075.webp", Author = "نشوة أبوالوفا", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786339971075" },
            new { Id = 437, Name = "ومهما أتعلم فلا أزال جهولا", Price = 250m, Stock = 10, Description = "هكذا هم الدهماء أو السواد الأعظم من الناس، الذين يُسطّرون ملاحم بطولية كل يوم.. هي تجارب إنسانية يزدحم بها وعاء الزمن، لكن لبساطة أصحابها، لا يتوقف عندها التاريخ؛ لأنه يرى فيها تجربة إنسانية لا تستأهل التوقف عندها، فما الذي يغري التاريخ في عامل أو موظف بسيط يُبكر لعمله سعياً على الرزق ليقيم أوده، ويَسُدّ رمق أولاده؛ ليعيشوا حياة كريمة.\n​يتحمل مشاق الحياة ومرارتها، لا يطمع في جاه، ولا يروم منصباً، ولا يأمل في سلطة، غايته الستر له ولأولاده، وكذلك ملايين الأحداث التي تدور رحاها تحت شمس الحياة، كفقير متعفف لا يسأل الناس إلحافاً، أو مسكين لا يستجدي أكف الناس، يربأ بماء وجهه أن يُراق، أو غارمة نكبها الدهر، تسعى في مناكب الأرض ومخارمها، تعمل وتجدُّ، وقد تقرّح ذهنها من همّ التفكير في كيفية سداد ديونها، وما أن يسدل عليها الليل سدوله حتى يُقضّ مضجعها مذلة هذا الدَّيْن، ورغم ذلك كله تجدها بثغر مبتسم، ووجه منطلق حتى تُخفي ما ألمّ بها عن أولادها؛ كي لا تُسبّب لهم ضيقاً أو ألماً.\n​ومهما أتعلم فلا أزال جهولاً\nد. هاني الغيتاوي", CategoryId = 8, ImageUrl = "/images/products/9786339971082.webp", Author = "هانى الغيتاوى", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786339971082" },
            new { Id = 438, Name = "رانشيرو", Price = 150m, Stock = 10, Description = "إنها تنتظر شخصا ما تعتقد أنه سيأتي إليها\nستعرف الألم والخيانة، حتى تتمنى الموت بدلا من النوم", CategoryId = 1, ImageUrl = "/images/products/9786339971709.webp", Author = "روزان إبراهيم", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786339971709" },
            new { Id = 439, Name = "الربح من الإنترنت", Price = 120m, Stock = 10, Description = "العمل بيتناول طرق الربح من الإنترنت وإزاى ممكن تزود دخلك وتخلق لنفسك فرصة عمل عن طريق الإنترنت واستخدام مواقع التواصل الإجتماعي.", CategoryId = 8, ImageUrl = "/images/products/9786339971754.webp", Author = "علاء محمود حسين", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786339971754" },
            new { Id = 440, Name = "أبسط من لهيب الشمس", Price = 150m, Stock = 10, Description = "حين يدرك الإنسان أن كل تصرف يفعله يؤثر في بيئته المحيطة ومجتمعه الكبير ؛ثم يتأثر هو نفسه بهذه السلوكيات بصفته فرد من أفراد المجتمع ؛سيحسن من سلوكه، وبذلك نعيش حياة سعيدة.\n\nلكل مجتمع طباع وعادات تتحكم في سلوك الأفراد وتؤثر في طبيعة العلاقات بينهما ، فمن هذه العادات صفات حميدة يجب دعمها ،ومنها سلوكيات مرفوضة يجب الإنتباه لها وتجنبها.", CategoryId = 8, ImageUrl = "/images/products/9786339971761.webp", Author = "حجازى الرفاعي", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786339971761" },
            new { Id = 441, Name = "حين تهدأ العاصفة", Price = 150m, Stock = 10, Description = "هذا الكتاب ليس وعدًا بزوال العواصف، بل بصيرة تُعلِّمك كيف تقف ثابتًا حين تعصف، كيف تُنصت لنفسك، وتفهم ابتلاءك، وتخرج من الانكسار أكثر وعيًا لا أقل ألمًا.\n«حين تهدأ العاصفة» رحلة هادئة نحو الرضا، وفهم الحكمة الخفية، والقيام من جديد دون أن تفقد إنسانيتك.", CategoryId = 8, ImageUrl = "/images/products/9786339971785.webp", Author = "إلهام محمد عوض", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786339971785" },
            new { Id = 442, Name = "أيام في المنفى", Price = 120m, Stock = 10, Description = "اليوم واليوم فقط أشعر بمذاق الحرية ، لساني\n‏أصبح طليق و ارتاح ظهري و كاهلي من الأحمال التي لا أطيق.\n‏أعلم كم ستتعجب عندما تقرء صفحاتي و ربما\n‏تشمئز من خط يدي المتعرج ولكنها السنين قد\n‏هزت جزعي و ألحقت رعشة بسيطة بيدي.\n‏ستغفر لي تلك الرعشة عندما تعرف ما ألم بي ..\n‏أنا متأكد من أنك ستكون الوحيد الذي يصدقني\n‏أيها الغريب.\n‏\n‏ توقيع : فهمي بك غريب", CategoryId = 1, ImageUrl = "/images/products/9786339971792.webp", Author = "وليد الدسوقى", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786339971792" },
            new { Id = 443, Name = "الدليل العملى لتعديل سلوك الطفل في سن الحضانة", Price = 120m, Stock = 10, Description = "كتاب تربوي إرشادي موجه للأمهات ومقدمي الرعاية – تعديل سلوك الطفل (من 3 إلى 6 سنوات)\nاقتباس / فكرة عامة تجذب الجمهور:\nلأن الطفل لا يسيء التصرّف عنادًا، بل يصرخ طلبًا للفهم…\nهذا الكتاب دليل عملي يساعدكِ على فهم سلوك طفلك في سن الحضانة، ومعرفة أسبابه الحقيقية، والتعامل معه بهدوء ووعي دون صراخ أو عقاب مؤذٍ. خطوات بسيطة، مواقف واقعية، وأدوات تربوية تساعدكِ على بناء شخصية متوازنة لطفلك، وتعيد الهدوء إلى بيتك.", CategoryId = 8, ImageUrl = "/images/products/9786339972102.webp", Author = "رضا عابد", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786339972102" },
            new { Id = 444, Name = "سلسلة فريق المستكشفين", Price = 100m, Stock = 10, Description = "عندما تصل خريطة قديمة وغامضة إلى أيدي فريق المستكشفين، يجد القائد الشجاع \"بدر\"، والفنانة الحالمة \"ليلى\"، والعبقري الصغير \"سامر\" أنفسهم في مواجهة لغز عمره قرون. تقودهم الخريطة إلى قلعة مهجورة على أطراف المدينة، مكان تحوم حوله الأساطير وتتردد في أروقته أصداء الماضي.\n\nبمساعدة الشرطي أحمد وكلبه الوفي \"برق\"، يكتشف الفريق أنهم ليسوا وحدهم من يبحث عن سر القلعة. ففي الظل، يتربص بهم لص غامض يسعى للوصول إلى الكنز قبلهم. بين الممرات السرية، والأفخاخ المنسية، والألغاز المحيرة، هل سينجح فريق المستكشفين في كشف الحقيقة قبل فوات الأوان؟ مغامرة مثيرة عن الشجاعة والصداقة وكشف أسرار الماضي.\n\nداليا محمد محمود", CategoryId = 11, ImageUrl = "/images/products/9786339972119.webp", Author = "داليا محمد محمود", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786339972119" },
            new { Id = 445, Name = "تنفس مجدد", Price = 150m, Stock = 10, Description = "هذا الكتاب مساحة آمنة لمن أثقلهم التعب، وكتمت أرواحهم الزفرات طويلًا.\n«تنفّس مجددًا» ليس دعوة للنسيان، بل للتخفف، لترميم الداخل، ولمنح القلب فرصة أخرى للحياة بعد الانكسار.\nهو رسالة هادئة تقول: لا بأس أن تتعب، المهم ألا تنسى أن لك حقًا في الراحة… وفي البدء من جديد.", CategoryId = 8, ImageUrl = "/images/products/9786339972133.webp", Author = "إلهام محمد عوض", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786339972133" },
            new { Id = 446, Name = "مرافئ الحنين", Price = 120m, Stock = 10, Description = "«كتبت هذه الرواية لأنني أؤمن أن الحنين لا يكون لإنسانٍ وحده،\nولا لوطنٍ وحده…\nبل لذلك الشعور الغامض الذي يشبه الاثنين معًا.\nللحب حين يصير بيتًا،\nوللوطن حين يصير قلبًا نابضًا في الصدر مهما ابتعدنا.\nعن انتظارٍ طال، وعن غربةٍ علّمتنا أن بعض البشر أوطان،\nوأن بعض الأوطان لا تعود أرضًا فقط… بل تعود روحًا.\nحنين حب،\nحنين وطن،\nحنين إنسان وجد نفسه أخيرًا حيث يجب أن يكون.»", CategoryId = 1, ImageUrl = "/images/products/9786339972140.webp", Author = "داليا نور", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786339972140" },
            new { Id = 447, Name = "عقدان من الزمن", Price = 150m, Stock = 10, Description = "“عقدان من الزمن” ليست رواية للقراءة السريعة،\nبل تجربة شعورية لكل من مرّ بسنوات ثقيلة، وخرج منها مختلفًا… لكنه حي\n\n“لم أخرج من عشرين عامًا كما دخلتها… تركت فيها طفولتي، وأخذت معي نفسي.", CategoryId = 1, ImageUrl = "/images/products/9786339972157.webp", Author = "إسراء ساهر", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786339972157" },
            new { Id = 448, Name = "سر جوهرة البحيرة", Price = 100m, Stock = 10, Description = "في مدينة جميلة يحيط بها الشلال من كل جانب، تتميز المدينة ببحيرة لها قوة الشفاء والراحة من كل ما يشغل البال. مدينة تزهو بأنواع نادرة من الورود والأعشاب، يقع في حبها كل من يعبر عتباتها أو يمر بها.\nيحكمها ملك قاسٍ على ابنته، مهمل في حكمه، ويترك أمور الحكم لوزيره الذي أفسد المدينة وجعل الرعايا ينامون ليلهم دون لقمة تسند عليها معدتهم المسكينة وتسد جوعهم.", CategoryId = 11, ImageUrl = "/images/products/9786339972164.webp", Author = "مى خفاجة", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786339972164" },
            new { Id = 449, Name = "عذرا أنى أحببت", Price = 120m, Stock = 10, Description = "عذرًا إني أحببت…\nلأن الحب أحيانًا لا يكون اختيارًا، بل تضحية.\nحكاية عن قلبٍ اختار أن يخسر نفسه كي لا يخسر عائلته،\nوعن مشاعر صادقة وُضعت في مواجهة الواجب،\nفكان الصمت أثقل من الاعتراف،\nوالبعد أرحم من البقاء.\nرواية تناقش حين يصبح الحب اختبارًا للإنسانية،\nلا انتصارًا للعاطفة وحدها.،", CategoryId = 1, ImageUrl = "/images/products/9786339972171.webp", Author = "سارة سامى", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786339972171" },
            new { Id = 450, Name = "الحديث الموضوع وأماراته", Price = 100m, Stock = 10, Description = "لم تكن جهود أئمة الحديث الأوائل في تأسيس قواعد علمي الإسناد والجرح والتعديل ترفا فكريا، بل كانت ضرورة شرعية قصوى الحماية الدين وصيانته. يقدم لك هذا الكتاب\nخلاصة قيمة لهذه الجهود؛ لتكون على بينة من أمرك وتشارك بفعالية في حفظ هذا الدين وتبليغه نقيا كما وصل إلينا من النبي صلى الله عليه وسلم.", CategoryId = 8, ImageUrl = "/images/products/9786339972188.webp", Author = "سليمان محمد أبوليلة", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786339972188" },
            new { Id = 451, Name = "الثعلب والكربون الأسود", Price = 150m, Stock = 10, Description = "اسم الكربون الأسود سيظل محفورًا في ذاكرة التاريخ لهؤلاء الرجال الذين ضحوا بالكثير من أجل مصر، خيرت، عبد القادر، وثروت.\nأقاموا جسرًا من الخفاء إلى الضوء، حيث لا يعرف سوى قلة قليلة الحقيقة الكاملة حول ما جرى.\nلكن التاريخ يذكرهم كرجالٍ شجعان، عملوا دون انتظار مكافآت أو أضواء، من أجل وطنهم، كانوا في قلب المعركة الكبرى، وفي نهاية المطاف، كانت مصر هي المستفيد الوحيد من تضحياتهم.\nهذه القصة تبرز كيف أن هناك رجالًا عاشوا في الظل، وضحوا بكل شيء من أجل أمن وطنهم.\nلقد حملوا على أكتافهم مسؤولية كبيرة، وعندما لزم الأمر، كانوا مستعدين لدفع الثمن، فالتاريخ لا ينسى مثل هؤلاء الرجال الذين عملوا بإخلاص للوطن، بعيدًا عن الأضواء والأنظار.", CategoryId = 1, ImageUrl = "/images/products/9786339972546.webp", Author = "محمد نجيب مطر", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786339972546" },
            new { Id = 452, Name = "مغامرات ياسين ومحمود العلمية", Price = 100m, Stock = 10, Description = "تدريجياً، بدأ الحاج محمد يستعيد اهتمامه بالحياة. أصبح يخرج مع حفيده إلى الحديقة، ويشتري له الحلوى، ويحكي له قصصاً مسلية. بدأت الابتسامة تعود تدريجياً إلى وجهه الشاحب.\nلم يعد الحاج يشعر بالوحدة القاتلة التي كانت تسيطر عليه. وجد في حفيده سلوى وعزاء، وفي زوجة ابنه منى، ابنة بارة وصديقة وفية، أدرك أن الحياة لا تتوقف عند فقدان الأحبة، وأن هناك دائماً بصيص أمل ونور في نهاية النفق.\nصحيح أن جرح فقدان ابنه سيظل غائراً في قلبه، لكن وجود حفيده وزوجة ابنه منحه سبباً جديداً للاستمرار، وذكّره بأن الحب والعائلة هما أقوى من قسوة الفقد والوحدة.\nوهكذا، استطاعت زوجة الابن الوفية أن تعيد الحياة إلى قلب الأب الحزين، وأن تحول شقة الفقيد إلى بيت دافئ يملؤه الحب والأمل من جديد.", CategoryId = 1, ImageUrl = "/images/products/9786339972195.webp", Author = "محمد نجيب مطر", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786339972195" },
            new { Id = 453, Name = "عروض مسرحية للأطفال", Price = 100m, Stock = 10, Description = "بقي مشروع الدكتور نادر حبيس الأدراج، وحقول القمح المستورد تملأ الأسواق. بقي المزارعون يعانون من ملوحة أراضيهم، وبقي الوطن يعتمد على الخارج في غذائه الأساسي. وقف الدكتور نادر أمام نبات القمح المعدل وراثيًا في مختبره، ينظر إليه بحسرة وأمل خافت، متمنيًا أن يأتي يوم يقدر فيه وطنه قيمة العلم والابتكار، ويستفيد من كنوز الأرض حتى لو كانت مروية بماء البحر.", CategoryId = 11, ImageUrl = "/images/products/9786339972508.webp", Author = "محمد نجيب مطر", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786339972508" },
            new { Id = 454, Name = "أسرار أطلانطس", Price = 150m, Stock = 10, Description = "رأى غيث اليأس يتسلل إلى وجوه الجميع، حتى العم زكريا الذي كان صامدًا. في تلك اللحظة، تذكر كل لحظة فشل في حياته، كل يأس، كل كلمة قيلت له بأنه \"لن يفلح\". لكن الآن، بعد أن رأى نور الإيمان ينبعث من داخله، وبعد أن فتح \"ختم الوعي\" بكلمات الله، شعر بقوة غير مسبوقة.\n\"لا تيأسوا!\" صاح غيث فجأة، صوته يصدح في القاعة وكأنه صرخة أمل في وجه الظلام. \"لقد كنتُ هناك! في قاع اليأس، في ظلام الفشل! لم أحقق شيئًا في حياتي! كنتُ أظن أني ضائع إلى الأبد. لكن الله، برحمته، لم يتركني!\"\nنظر إلى سارة، ثم إلى كل منهم، وعيناه تلمعان بالصدق. \"لقد علمنا أن النية الصادقة تفتح الأبواب المغلقة. أن الصبر يهزم الصعاب. أن التوكل على الله يجعل المستحيل ممكنًا!\"\nتذكر قول الله تعالى: ﴿قُلْ يَا عِبَادِيَ الَّذِينَ أَسْرَفُوا عَلَى أَنفُسِهِمْ لَا تَقْنَطُوا مِن رَّحْمَةِ اللَّهِ ۚ إِنَّ اللَّهَ يَغْفِرُ الذُّنُوبَ جَمِيعًا ۚ إِنَّهُ هُوَ الْغَفُورُ الرَّحِيمُ﴾ [الزمر: 53].\n\"يا من شعر بالفشل، يا من لم يحقق شيئًا منذ القدم، يا من ظن أنه لا أمل فيه! الله لا ييأس من عباده! ليست النهاية ما تراه العين، بل ما يقرره القلب. قم! انفض غبار اليأس، واعلم أن كل يوم جديد هو فرصة لميلاد جديد، وأن أعظم النجاح ما يأتي بعد سقوط مُدَوٍّ.\"\nكانت كلماته كالصاعقة، تضرب قلوبهم، وتبث فيهم روحًا جديدة. سارة نظرت إليه بإعجاب عميق، حبها العفيف له يزداد رسوخًا.", CategoryId = 1, ImageUrl = "/images/products/9786339972515.webp", Author = "غادة حاتم مصطفى", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786339972515" },
            new { Id = 455, Name = "المرأة المظلمة", Price = 150m, Stock = 10, Description = "لقد استترت الأوجه خلف أقنعةٍ مزيّفة، لتحجب حقيقتها الماكرة الخادعة التي تنطلي على أذهان المساكين، كمن يلوِّح بأضواءٍ زاهيةٍ ليواري وراءها ظلامًا حالكًا. ترى صورتك القديمة في مرآتك؛ فترى مظلمة سوداء لا تعكس شيئًا! فقط الظلام هو صورتك! هو أنت تُدفن الأفعال الدنيئة الرخيصة في باطن آبار الخيرات والمسرّات، تتخذ من السعي إلى الصلاح ستارًا، لكنها ليست سوى مسرحيةٍ منسوجة بخيوط الشرّ والخداع. فما تراه الناس خيرًا، هو في الحقيقة شرٌّ مستتر، والمسرّات ما هي إلا وجوه زائفة لحزن دفين يقبع في الأعماق، والصلاح لا يعدو كونه طالحًا مغلّفًا بغطاء من الوهم! هذه الحكاية تسلّط ضوءها على ظلال الأكاذيب، تفتّش بين خفاياها عن حقائق تبدو بريئة، ولكنها في جوهرها أوهام دفينة محكمة البناء. إنها الحكاية التي تطيح بعقول البسطاء بلا هوادة! تُخضعهم وتخدعهم لتصديق الكاذب ومنح الأمانة للخائن، دون أن يكون لهم ذنب في ذلك. فكيف للإنسان أن يرى الحقيقة، إذا كانت العيون لا تبصر سوى الأقنعة؟ ليست هذه الكلمات هذرًا، بل إعلان لجديّة حاسمة، تتغلغل في أعماق النفس لتكشف هشاشتها أمام الزيف، وتجعلنا نتساءل: أيمكن أن يكون الخير والشر وجهين لعملة واحدة، أم أن العالم بأسره مسرحٌ يتبادل فيه الأقوياء أدوار الطغيان؟ ولكن هذه الحقيقة التي تظهر من فينةٍ لأخرى، ومنذ بدء الخليقة فقد أودع فيهم الربُّ حبُ الخير والشر، والتناقضات الفكرية، والانحدارات الأخلاقية، وما سيُقال ما هي إلا إسقاطات لحكايات لأشخاص صاروا طعامًا يُستساغ بين أشداق الماضي. والذي تراه ملاكًا بريئًا وديعًا يرفرف بكلتا جناحيه، ما هو إلا شيطان يقبض بيده على صولجان ليدسه في قلبك!", CategoryId = 1, ImageUrl = "/images/products/9786339972522.webp", Author = "أحمد جمال سليمان", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786339972522" },
            new { Id = 456, Name = "عقدان من الزمن (الجزء الثانى)", Price = 150m, Stock = 10, Description = "ماذا لو كانت أقسى سنوات عمرك… هي نفسها التي صنعتك؟\nهذه الرواية لا تحكي عن بطلة خارقة، بل عن فتاة عادية وُضعت في اختبارات أكبر من سنها، فتعلمت أن تنضج قبل أوانها.\nبين ظلمٍ دراسي، وفقدٍ لا يُشفى، وغربةٍ سرقت الطمأنينة، ومسؤولية جاءت مبكرًا… تمشي البطلة في طريق طويل لا يحمل وعودًا واضحة.\n\nلكن حين تتعطل الحياة فجأة، قد تمنحنا أكثر مما سلبته.\nحب يولد من صدفة، وبيت يُبنى من التعب، وقلب يتعلم أن يختار السلام بدل التمسك بالماضي.", CategoryId = 1, ImageUrl = "/images/products/9786339972539.webp", Author = "إسراء ساهر", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786339972539" },
            new { Id = 457, Name = "الجدة تروى", Price = 100m, Stock = 10, Description = "الجدة توتي شيري تعود إلى الحياة لتروي لنا حكايات مفيدة للمصريين\nوتشجعنا على التحلي بتلك الصفات الحميدة، كما تشجعنا على التمسك بالقراءة لما لها من أهمية.", CategoryId = 1, ImageUrl = "/images/products/9786339972553.webp", Author = "على مهران", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786339972553" },
            new { Id = 458, Name = "البوابات النجمية", Price = 150m, Stock = 10, Description = "تتحدث الرواية عن خمسة أبناء خالة وجدوا سلسلة على شكل نجمة خماسية وعلموا أنها وقعت من شخص يدعى يونس ماتت خطيبته وسلك طريق السحر وذهب لعالم القرائن، وهؤلاء الخمسة وجدوا هذه السلسلة ما الذي سيواجهه هؤلاء الأولاد هذا ما ستحكيه لنا الرواية.", CategoryId = 1, ImageUrl = "/images/products/9786339972560.webp", Author = "جنه إسماعيل", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786339972560" },
            new { Id = 459, Name = "كوكب الحيوانات المجنحة", Price = 150m, Stock = 10, Description = "تحكي الرواية عن عالم فضاء اكتشف كوكب جديد فصنع سفينة فضائية وسافر دون معرفة أحد إلى هذا الكوكب الجديد ليكتشف مايوجد فيه، وهلى سبجد عليه احد أم ما الذي سينتظره هذا في هذا الكوكب.", CategoryId = 1, ImageUrl = "/images/products/9786339972577.webp", Author = "جنه إسماعيل", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786339972577" },
            new { Id = 460, Name = "خلف أسوار القلب", Price = 100m, Stock = 10, Description = "يُعد هذا الديوان الذي يضم بين دفتيه قصائد لم تكن سوى لحظات من حياة، خطّتها اليد حين فاض القلب بالحب أو الحزن، بالفرح أو الألم، باليأس أو الأمل فإنه يحمل حروفاً وكلمات في طياتها أصداء تجارب إنسانية عميقة، ولدت من رحم التأمل في الحياة، وفي تفاصيلها الدقيقة. آمل أن تجد في كل قصيدة صدىً يلامس روحك، وأن تضيء لك شمعة في عتمة الطريق، أو تروي عطشاً في صحراء الحياة", CategoryId = 8, ImageUrl = "/images/products/9786339972584.webp", Author = "إيمان محمد", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786339972584" },
            new { Id = 461, Name = "(أحببت هؤلاء) 30 عظيما علمونى فن الحياة", Price = 200m, Stock = 10, Description = "قطار حياة الإنسان بمر بمحطاتٍ كثيرة متلاحقةٍ\nمنها محطاتٌ حلوةٌ عذبةٌ، ومنها محطاتٌ مالحةٌ مرةٌ.\nمنها محطاتٌ يقبل عليك فيها أكثر الناس، ومنها محطاتٌ ينفض عنك فيها كل الناس.\nمنها محطاتٌ ينعم الله فيها عليك بأعظم النعم، ومنها محطاتٌ تلفحك فيها سياط العدم.\nمنها محطاتٌ تنعم فيها بعاطفة الحب والود من الناس، ومنها محطاتٌ تؤلمك فيها مشاعر الجفاء والبعد من أكثر من عرفت منهم.\nمنها محطاتٌ يبتسم لك فيها الكبير والصغير، ومنها محطاتٌ يعبس في وجهك فيها كل قريبٍ وحبيبٍ.\nيمر الواحد منا في حياته بمحطاتٍ كثيرةٍ، أحداثها متلاحقةٌ، ومن كل محطةٍ يتعلم الإنسان درسًا بليغًا قاسيًا ورائعًا، من عظيمٍ من العظماء، تلك هي الحياة المعلمة، كما أشار الله إلى تقلباتها المستمرة في القرآن الكريم فقال فيها: (والله يعلم متقلبكم ومثواكم) في إشارة إلى أن الله عليم بكل أحوال الناس في حركاتهم وسكونهم، في حياتهم الدنيا وفي مصيرهم في الآخرة، وقد أقسم سبحانه على ذلك فقال: (فلا أقسم بالشقق والليل وما وسق والقمر إذا اتسق لتركبن طبقًا عن طبق) أي لتتحولن من حالٍ إلى حالٍ، مما يدل على أن الحياة مليئةٌ بالتغيرات والتقلبات، والإنسان ينتقل فيها من الطفولة إلى الشباب، ومن الشباب إلى الكهولة، ومن الصحة إلى المرض، ومن الغنى إلى الفقر، ومن السعادة إلى الحزن، وتلك محطاتها المتعددة.\nوالعارفون بطبيعتها، والفاهمون لتقلباتها، والراضون بها على كل أحوالها، وهم يسيرون فيها هم أكثر الناس سعادةً بها،\nهذا موضوع كتابي الذي بين أيديكم الآن: (علمني هؤلاء)، أقدمه للقارئ الكريم وأحتسب فيه الأجر من الله تعالى، وأسأل سبحانه أن يكون جهدي فيه خالصًا لوجهه الكريم، إنه ولي ذلك والقادر عليه.\nالفقير إلى عفو ربه", CategoryId = 8, ImageUrl = "/images/products/9786339972591.webp", Author = "كرم الشافعى", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786339972591" },
            new { Id = 462, Name = "أوراق ملعونة", Price = 120m, Stock = 10, Description = "حين ينتشر الظلام ، يبدأ عالم آخر في البزوغ ..\nعالم تمتلئ فيه الأفكار بالتوتر ، وتتحول الأماكن المألوفة إلى مصائد غامضة .\nأصوات مجهولة ، أشياء تتحرك من تلقاء نفسها ، وأبواب لا تؤدي إلا إلى هاوية أعمق .\nليس الرعب فيما تراه عيناك ، بل فيما يتربص بك خلف السكون .\nهذه الصفحات ليست للقراءة فقط ..\nإنها تجربة ستبقى معك طويلًا بعد أن تطويها ..", CategoryId = 9, ImageUrl = "/images/products/9786339974014.webp", Author = "محمد عماد", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786339974014" },
            new { Id = 463, Name = "السيد: ميم", Price = 120m, Stock = 10, Description = "خمس حكايات تتقاطع فيها الطرق بين الضوء والعتمة، بين العقل والجنون، بين الإنسان وظله.\n\nفيها ستسظل بموت الحب وخيانة الموت..\nستتوارى من عشقِ الجن، وتهرولُ من فصامِ النفس، وتفزعُ حين تُبصرُ فتاة الجامع واقفةً عند باب قلبك... لتجد رأسك أخيرًا معلَّقًا في حبل مشنقةٍ داخل سجن الاستئناف.\n\n\"عملٌ يعرّي الإنسان أمام مرآة روحه، لذا إحذر ولا تنفعل مما ترى\"", CategoryId = 1, ImageUrl = "/images/products/9786339974021.webp", Author = "مصطفى الشيشتاوى", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786339974021" },
            new { Id = 464, Name = "وصايا الطريق ومسرحيات أخرى لأطفال", Price = 120m, Stock = 10, Description = "مجموعة مسرحية بعنوان \"وصايا الطريق ومسرحيات أخرى للأطفال\"، وتضم نصوصاً درامية تعليمية وتربوية موجهة للناشئة، تتنوع موضوعاتها بين القصص الرمزية على ألسنة الحيوانات، والدراما التاريخية، والاجتماعية.\nتتميز هذه المجموعة بالتركيز على غرس القيم الأخلاقية، وتعزيز الهوية الوطنية، وتقديم نماذج إيجابية للتحدي والإصرار.", CategoryId = 11, ImageUrl = "/images/products/9786339974045.webp", Author = "بكر صابر على على", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786339974045" },
            new { Id = 465, Name = "خارج عن النص", Price = 120m, Stock = 10, Description = "ما بين السطور… كواليس لا تُروى، وحكايات لا يمكن أن تُفهم كما كُتبت… لأنها لم تُكتب أصلًا لتُفهَم، بل لتُنقذ شيئًا صغيرًا، كان يوشك أن ينطفئ.\nبعض الأرواح تختبئ في القصص، لا لتُكتشف… بل لتبقى حيَّة.", CategoryId = 1, ImageUrl = "/images/products/9786339974052.webp", Author = "حبيبة عماد غريب", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786339974052" },
            new { Id = 466, Name = "القاتلة", Price = 120m, Stock = 10, Description = "\"تعجب حسن لما قاله السائق، وقال محدثًا نفسه: ليس هناك قانون واحد من الآن، فكل فرد وضع لنفسه قانون. ولم تمر أيام كثيرة حتى وجد مدير الشركة يفصل كل من تسبب في حث الموظفين على الإضراب والاعتصام عن العمل، ولم يعرف أحد ما تأثيرات الثورة بعد ذلك.\"", CategoryId = 1, ImageUrl = "/images/products/9786339974069.webp", Author = "حسين أحمد حسين حسن", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786339974069" },
            new { Id = 467, Name = "الطيف", Price = 120m, Stock = 10, Description = "تدور أحداث الرواية حول شهاب الصفدي الذي كان معروف بعلاقاته النسائية هو وصديقه الوحيد مازن الحسيني ، إلى أن ارتبط شهاب عاطفيا بكارما أخت مازن الوحيدة والتي أحبها حبا شديدا وقرر أن يغير كل حياته من أجلها ، إلا أن حدث بينهما موقف جعلها تظن أنه يخونها ، فتقرر أن تتركه وتسافر بعيدا ، ظل شهاب يبحث عنها كثيرا على مدار سنوات ولكن دون جدوى ، ليظل طيفها الذي يأتيه من وقت إلى أخر هو الونيس الوحيد له والذي يشعره بأنها مازالت بجانبه تشعر به ، ظل شهاب على حبه لكارما إلا أن اضطرته الظروف إلى خطبة نيفين ابنة عمه ، الذي قام يخطبتها لينقذها من أمر ما ، ولكنه ظل على حبه المعروف للجميع لكارما ، لتدخل بعدها علياء حياته ويشعر أن قلبه بدأ يميل إليها ، فيقرر مازن الذي أحبها هو الاخر أن يغير مجرى قصتهم ، ليتفاجأ شهاب بعودة كارما وتكون المفاجأة التي زلزلته ووضعته بين امرين محيرين بينها وبين علياء التي تعلقت به بشدة ، خاصة بعد أن علم أن سبب بعد كارما عنه كل هذه الفترة هو دخولها في غيبوبة بعد تعرضها لحادث، وأن ما كان يراه هو روحها وطيفها يناديه ، وفى الوقت الذي قرر شهاب أن ينهى قصته مع علياء ليعود إلى كارما ، تكتشف كارما علاقته بعلياء وخطبته من نيفين وتفاجأه برد فعلها .", CategoryId = 1, ImageUrl = "/images/products/9786339974076.webp", Author = "أمينة الريحانى", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786339974076" },
            new { Id = 468, Name = "الحب في زمن الكورونا", Price = 120m, Stock = 10, Description = "فداعبتها ذات مرة في وجود زميل لها، أن لكل طالب ما يشغله ويعطله عن الدراسة والتحصيل العلمي، فزميلها هذا قد كان يعطله النت والكمبيوتر ، أما هي فأعتقدها مشغولة بأنوثتها المتفتحة كالزهرة النضرة في غضون الربيع", CategoryId = 1, ImageUrl = "/images/products/9786339974090.webp", Author = "سمر إسماعيل دسوقى", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786339974090" },
            new { Id = 469, Name = "صديقى لاكى", Price = 50m, Stock = 10, Description = "حكي القصة عن الطفل أحمد، البالغ من العمر تسع سنوات، الذي يواجه تحدي مرض السكري من النوع الأول، لكنه يتغلب عليه بمساعدة صديقه الوفي لاكي، الكلب المدرَّب على استشعار انخفاض مستوى السكر في الدم. من خلال مغامرات مدرسية ويومية مؤثرة، يظهر لاكي بطولته في إنقاذ أحمد في المواقف الصعبة، سواء في الغابة أو وسط الزحام في السوق. مع مرور الوقت، يتعلم أحمد تقبّل مرضه بثقة، ويشارك تجربته مع أصدقائه، مؤكدًا أن البطولة الحقيقية تكمن في الصداقة، الوفاء، والإيمان بالذات.\n\nالقصة تبرز قيم الشجاعة، الصداقة، المسؤولية، والتعايش مع التحديات الصحية بلغة إنسانية وملهمة للأطفال واليافعين.", CategoryId = 11, ImageUrl = "/images/products/9786338367008.webp", Author = "وئام عادل", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338367008" },
            new { Id = 470, Name = "لا من أجل سلامك النفسى", Price = 250m, Stock = 10, Description = "عزيزي القارئ، كتبت هذا الكتاب من الألم، ونسجت حروفه من خيبات الأمل ، وجمعت الأمل فيه من كثرة التردد، ورتبت أبوابه من كثرة التخبط والإحباط.\nتعلمنا فيه كيف نعرف أنفسنا بشكل صحيح، ونحترم ماضينا، ونستمتع بحاضرنا ، ونحن نخطط للمستقبل، تخطينا فيه كل حاجز يحول بيننا وبني سلامنا النفسي مع أهلنا ومع الله ، حتى وصلنا الي ما يجب فعله مع الاخرين لننعم بسلام نفسي حقيقي.\nولنصل لهذا السلام يجب أن تعرف أن بداية كل تغير هو الألم ، والخروج من منطقة راحتنا،\nوالنهوض من تحت سقف غرفتنا؛ لنعيش حياتنا كما يجب أن تكون.\nولنرتك خلفنا في كل ريع آيًة باسمنا، لا لنعبث، ولكن لتخبر من يأيت بعدنا أننا كنا هنا.", CategoryId = 6, ImageUrl = "/images/products/9786338367015.webp", Author = "عمرو زاهر", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338367015" },
            new { Id = 471, Name = "ؤئام وجذر في أرض الفراشات", Price = 50m, Stock = 10, Description = "تدور أحداث القصة حول الطفلة وئام وأرنبها الأبيض جَزَر، اللذين يعبران من خلال باب سحري خلف شجيرة الياسمين إلى عالم خيالي يسمى أرض الفراشات المضيئة. هناك تكلَّفهما الفراشات بمهمة إنقاذ أرض النور من قوى الظلام بعد اختفاء الفراشة الأم. تخوض وئام وصديقها مغامرات مدهشة بين الكهوف والغابات والجبال والصحارى، ويواجهان مخلوقات عجيبة ويتغلبان على المخاطر بالشجاعة والصدق ونقاء القلب. في النهاية، يحرران الفراشة الأم ويعيدان النور والبهجة إلى المملكة، ثم تعود وئام إلى عالمها حاملة زهرة أمل مضيئة تذكرها دومًا بأن الخيال مفتاح السعادة.\n\nالقصة تمزج بين الخيال الطفولي البهيج والقيم الإنسانية كالطيبة، الصداقة، الأمل، والشجاعة، لتفتح أمام الطفل أبواب الحلم والإبداع.", CategoryId = 11, ImageUrl = "/images/products/9786338367022.webp", Author = "وئام عادل", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338367022" },
            new { Id = 472, Name = "سيرانو عهد منذ الأزل", Price = 150m, Stock = 10, Description = "في زمنٍ قديمٍ ومكانٍ ساحرٍ يُدعى \"سيرانو\"، كان السلامُ يعمُّ فيها بسببِ ملكِها المغوارِ، ولكن بسببِ قانونٍ خُطَّ قلبَ الأمورَ رأسًا على عَقِبٍ.\nولكن لم ينتهِ الأمرُ عند هذا الحدِّ، بل هناك من دفع ثمنَ خطيئتِه.\nولم يعلمْ أنها شرارةُ عودةِ سيرانو إلى عهدِها القديم،\"عهدٍ منذُ الأزل\".", CategoryId = 1, ImageUrl = "/images/products/9786338367039.webp", Author = "إسراء مظلوم", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338367039" },
            new { Id = 473, Name = "تعلم الإعراب بدون معلم", Price = 120m, Stock = 10, Description = "وانطلاقًا من هذا الواقع المرير الذي يشتكيه عشاق النحو وطلابه، ارتأيتُ أن أقدّم بعض الطرق اليسيرة لتقريب الإعراب، فوضعت أهم أساسيات النحو ضمن دروس تطبيقية، بعيدًا عن التنظير الجاف والأسلوب السردي العقيم الذي يجعل الطالب يدور في حلقة مفرغة، ليعود من حيث أتى فارغ اليدين.", CategoryId = 8, ImageUrl = "/images/products/9786338367046.webp", Author = "أم محمد عياطىي", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338367046" },
            new { Id = 474, Name = "سكر زيادة", Price = 1200m, Stock = 10, Description = "كتاب علمي مبسط عن مرض السكري (Diabetes Mellitus) موجه للأمهات، المقربين من الطفل السكري، وللمرضى الكبار أيضًا، مع جزء مخصص للمثقفين السكريين وأخصائي التغذية.", CategoryId = 8, ImageUrl = "/images/products/9786338367053.webp", Author = "إسراء عرفة", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338367053" },
            new { Id = 475, Name = "مسرحيات كليلة ودمنة لأطفال", Price = 100m, Stock = 10, Description = "ارتأيت أن أستوحي من عمق الحبكات التي تتضمنها قصص كليلة ودمنة المتنوعة موضوعات سائغة ندية لأطفالنا وأقدمها في شكل مسرحيات مبسطة في أسلوبها عميقة في إفادتها و مراميها لأجل غرس مبادئ إيمانية وتربوية هادفة، كل ذلك ملفوفا في رداء أدبي ممتع وراق يغذي شغف الطفل ويروي فضوله المتطلع دوما لمعرفة كل ما هو جميل و جديد", CategoryId = 11, ImageUrl = "/images/products/9786338367077.webp", Author = "أم محمد عياطي", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338367077" },
            new { Id = 476, Name = "أساطير من أرض الأندلس", Price = 120m, Stock = 10, Description = "أساطير من أرض الأندلس\nفي أرضٍ غمرها السحر والتاريخ، حيث تتعانق القلاع مع الغيوم وتختبئ الحكايات في صدور الأنهار، تولد الأساطير…\nهنا، ليلى بنت القاضي التي حملت الأندلس على كتفيها لتمنع سقوطها، والقائد عمرو الذي ألقى بسيفه أمام قلبٍ أسيرٍ فاختلط الحب بالدم.\nوهنا أمّ صنعت التاريخ حين غرست البطولة في ابنها، وفارس غامض خرج من رحم الظلال ليقلب موازين الحروب.\nوفي النهاية… تأتي ياسمين، الصحفية القادمة من زمننا هذا، لتجد نفسها عالقة بين أسوار الأندلس، في قلب صراعٍ لا يرحم، وحبٍ يتحدى الزمان والمصير.\nأساطير من أرض الأندلس ليست مجرد قصص… إنها عبور إلى عالم آخر، حيث التاريخ يشتعل، والعاطفة تصرخ، والخيال يفتح أبوابه على مصراعيها.\nكتاب يسرق أنفاسك منذ الصفحة الأولى… ويترك قلبك أسيرًا حتى آخر سطر.", CategoryId = 1, ImageUrl = "/images/products/9786338367084.webp", Author = "وئام عادل", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338367084" },
            new { Id = 477, Name = "مانشوكا", Price = 120m, Stock = 10, Description = "قصة حب بين رجل ستيني عربي وباحثة إيطالية يلتقيان صدفة في رحلة باتجاه شرق آسيا. هو حانق على واقعه وهي سائحة..", CategoryId = 1, ImageUrl = "/images/products/9786338367091.webp", Author = "مروان العلان", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338367091" },
            new { Id = 478, Name = "واعدة", Price = 120m, Stock = 10, Description = "يهرب الأستاذ الجامعي من ضغط الحياة ويلتقي بامرأة يكتشف مدى توافق شخصيتها مع شخصيته فيتفقان على الهروب من المجتمع بإقامة مشروع خارج المدن ما يلبث أن يتحول لمقر للعزلة والحب والابتكار العلمي.\n\nيتكوّن هذا الكتاب من 4 أجزاء: واعدة، واعدة (الجزء الثانى)، واعدة (الجزء الثالث)، واعدة (الجزء الرابع).", CategoryId = 1, ImageUrl = "/images/products/9786338367107.webp", Author = "مروان العلان", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338367107" },
            new { Id = 479, Name = "ندبة العمر", Price = 120m, Stock = 10, Description = "في عالم حيث الحب هو الميزان الذي يحدد مصائر القلوب، تأتي \"ندبة العمر\" لتروي قصة \"تاج\" و\"حيدر\"، قصة حب كُتبت بدموع الشغف ورُسمت على صفحات الألم والخيبة. إنها ليست مجرد حكاية عابرة، بل هي رحلة عميقة في تضاريس المشاعر الإنسانية، تكشف كيف يمكن للحب أن يكون النور الذي يضيء أعتى الظلمات، والندبة التي تحفر في الروح عمقًا لا يُمحى.\nتاج، الفتاة التي لم تتوقع أن يكون قلبها ساحة لحرب تخوضها روحها، وحيدر، الذي اكتشف متأخرًا أن الحب ليس مجرد نظرة أو وعد زائف، بل التزام ينبعث في أحلك اللحظات. يواجه الاثنان قدرًا قاسياً، حيث تنكسر الوعود وتتلاشى الأحلام تحت وطأة الغياب والخذلان، وتُفرض قيود العادات والتقاليد لتُشعل معركة بين الحب والالتزام.\nتتنقل الرواية ببراعة بين أصداء السعادة الغامرة التي يسبقها الحب، وبين وحشية الفراق والخيبة التي تترك ندوبًا لا تندمل. من خلال مونولوجات داخلية مؤثرة ولغة شعرية تلامس الوجدان، تعكس \"ندبة العمر\" صراع البطلة مع الألم والندم، وكفاحها لتحقيق انتصار شخصي حتى وإن جاء الثمن باهظًا. هل يمكن للحب أن يصلح ما كسره الغياب؟ وهل يمكن للحياة أن تمنح فرصة لمن غابت عنها العدالة؟\n\"ندبة العمر\" ليست مجرد رواية، إنها قصيدة ألم وأمل، صرخة قلب مجروح يحكي قصة التضحية، النسيان، والندم الذي يطارده القدر. إنها دعوة للتأمل في قوة المشاعر البشرية، وكيف يمكن لحدث واحد أن يغير مسار العمر ويترك بصمة لا تُمحى.", CategoryId = 1, ImageUrl = "/images/products/9786338367152.webp", Author = "شهد أحمد إبراهيم", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338367152" },
            new { Id = 480, Name = "الحكيم باشا دايت بسلاسة", Price = 200m, Stock = 10, Description = "يتناول الكتاب بأسلوب علمي مبسط العلاقة الوثيقة بين التغذية والصحة، مسلطًا الضوء على عدد من الأمراض الشائعة المرتبطة بالنمط الغذائي الحديث، مع تقديم نصائح عملية لعلاجها أو الوقاية منها بالتغذية العلاجية.", CategoryId = 8, ImageUrl = "/images/products/9786338367169.webp", Author = "حسام الحكيم", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338367169" },
            new { Id = 481, Name = "خلف الأبواب الزرقاء", Price = 120m, Stock = 10, Description = "استيقظ العالم على كارثة مدوية، كان ( بدر ) نائما و قد ضاقت عليه نفسه كالعادة وفجاة سمع صوت صراخ، ظنها في بادئ الأمر أفكاره الخاصة قد تحولت إلى كوابيس، و لكن عقله بدا يفيق رويدا رويدا حتى استيقظ بالكامل على الصراخ فهب مسرعا من فراشه و ركض خارج حجرته فصادف أمه في الردهة الصغيرة مذعورة فاتسعت عيناه وقال في دهشة:\n_ أماه، ماذا حدث؟!\nلم تستطع الأم الإجابة ولكنه رأى أخته تركض صارخة من حجرتها:\n_ جارتنا في البناية المقابلة ظلت تصرخ في وجه زوجها و قد جنت تماما ثم أشعلت النيران في شقتهما و الزوج داخلها\n** قفز ( بدر) نحو الهاتف وهو يطلب رقم رجال الإطفاء قاىلا في صدمة:\n_ هل جُنّت حقا أم ماذا؟!\nو ما كاد يدلي ببلاغه على الهاتف و ينتهي حتى سمع ثلاثتهم أصواتا مختلطة فأسرعوا نحو نافذة حجرة ( بدر) نفسها حيث مصدر الصوت فهالهم ما راو، جارهم الآخر بالأسفل ، ذاك الرجل كبير السن الوادع الطيب يصفع ابنه الشاب على وجهه و يقسم بأغلظ الأيمان ألا يبيت في بيته ليلة بعد هذا وهو يتهمه بأنه قد سرق أموال عمه التي أودعها عندهم أمانة ثم ظنوا أن لصا قد سرقها و قد حدث كل هذا منذ عامين! تعجب ( بدر) جدا، شجار ينشب بين أب و ابنه من أجل كارثة فعلها الابن منذ عامين؟! ما الذي كشف سر الابن الآن؟! ،ظل في حيرته بينما رن جرس هاتف المنزل فأسرعت ( ميار) إلى الإجابة فأتاها صوت خالتها تبكي منتحبة، لقد طلقها زوجها الذي كان يهيم بها حبا !!\nو عندما نادت الفتاة أمها لتجيب خالتها همهمت الأم في ذهول:\n_ هل جُن الجميع اليوم؟!", CategoryId = 1, ImageUrl = "/images/products/9786338367176.webp", Author = "عهد على محمود", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338367176" },
            new { Id = 482, Name = "برائحة الفقد", Price = 120m, Stock = 10, Description = "يتناول العمل قصة حب تنشأ بين اتنين عن طريق وسائل التواصل الاجتماعي، تتطور الأمور بينهما إلي حب.\nلم تتوقف عن هذا الحد تتجاوز ذلك بكثير وتسقط فريسة رجل مزاجي يعاملها حسب حالته المادية قبل النفسية، يلوعها عشقا بالهجر تارة والوصال تارة اخري. تكون فتاة صغيره خبراتها محدودة وهو رجل طاعن العقل والخبرة يستغل ذلك، يسقطها في بئر حبه. ويتمعن في ان يخوض بها ومعها حروبه، تحاول إخفاء الامر عن الجميع. تنساب وتنسجم في القصة معه. فاول اللقاء يجمعهما يكون في المقبرة، كلاهما حزين لموت والدته.\nتتسارع الأحداث وتسقط فريسة لشغفها الشديد به، يصاب في حادثة ويخرج من ازمة لاخري وهي بنفس القوة والعزم معا. تحاول بعدها الابتعاد لا تستطيع فقد سقطت في محيط عشقه غرقاً. يتفقا علي الزواج وامام رفض الجميع يقف الحب مثابراً وينتصر لهما. يوافق الجميع بعد مبارات رفض عنيفة من قبلهم.", CategoryId = 1, ImageUrl = "/images/products/9786338367183.webp", Author = "ريهام الجبالى", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338367183" },
            new { Id = 483, Name = "ليالى زمان", Price = 120m, Stock = 10, Description = "ليالي زمان\n\nوحشتني ليالي زمان واللِّمّة،\nوطاقة أمل جوّه القلب\nتنور أي ضلمة.\n\nوحشتني ضِحكة\nمن القلب طالعة\nتداوي أي جرح\nوتمسح كل دمعة.\n\nوحشتني لمّة على صينية،\nولُقمة على القلب هنيّة،\nوبيت يجمع الحبايب\nويسَع منهم مِيّة.\n\nوقعدة في ليالي البرد\nمع كوباية شاي،\nودفا طالع من القلب،\nولا تسأل ليه وإزاي.\n\nيرجع أجمل ذكريات الروح،\nويرجع قلوبنا تاني حيّة.\n\nوحشوني حبايبنا،\nشغلاهم ليه الدنيا؟", CategoryId = 8, ImageUrl = "/images/products/9786338367190.webp", Author = "مى إبراهيم القاضي", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338367190" },
            new { Id = 484, Name = "اهتداء نفس (عسي أن تهتدى القلوب لساكينها)", Price = 120m, Stock = 10, Description = "يتذكر ذلك اليوم جيدًا عندما عاد من عيادته لم تكن في استقباله كما اعتاد منها، ودلف بحذر يبحث عنها ويناديها دلف لغرفتهما ليجد الرضيع في فراشه نائم وهي وجدها ساكنة تمامًا على مقعد بجانب فراش الصغير وتستند بذراعيها على حائل السرير وتستند بذقنها إلى ذراعيها، لدرجة أنه شك بغفوتها لكن عندما اقترب يميل عليها يقبل رأسها شعر برجف قوي يسري في جسدها فتشنج قبل أن يسرع برفع وجهها له من ذقنها، تفاجئ بدموعها التي تسيل مدرارًا، شعر بقلبه يختلج، منتظرًا تفسير صامت، لكن هي لم تريحه بل وقفت تحتضن خصره وتدفن وجهها في صدره مستكملة بكاءها الحار ذا النشيج الضائعة، وكأنما امرأة خلقت للمعاناة، امرأة قادت حرب ضارية دون درع واحد تحتمي به، وما أوجع قلبه قولها:\n-أنا اعاني من شيء أجهله...", CategoryId = 1, ImageUrl = "/images/products/9786338367213.webp", Author = "هاجر حمدى", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338367213" },
            new { Id = 485, Name = "عزم بدوى و دكان باص", Price = 120m, Stock = 10, Description = "تحكي الرواية رحلة شاب بدوي خرج من صحراء الكبرياء إلى طرقات الحياة المليئة بالدخان والتحدي. بين رمال الماضي وزفت الحاضر، يصارع “عزم” نظرة الناس وسخرية القدر، ليصنع من الألم طموحًا ومن الشبهات طريقًا نحو المجد. إنها حكاية عن الصبر، والكرامة، والإصرار حين يقف الحلم في وجه العُرف والمجتمع.", CategoryId = 1, ImageUrl = "/images/products/9786338367237.webp", Author = "ضيف الله الجهالين", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338367237" },
            new { Id = 486, Name = "وظيفة في مهب الواسطة", Price = 120m, Stock = 10, Description = "رواية تكشف قسوة الواقع حين تتغلّب الواسطة على الطموح، وتحكي صراع شابٍ جنوبي يسعى لوظيفة تحفظ كرامته وسط عالمٍ لا يعترف إلا بالمعارف. قصة واقعية مؤثرة تلامس وجع جيلٍ يطارد أحلامه في وجه الظلم.", CategoryId = 1, ImageUrl = "/images/products/9786338367251.webp", Author = "ضيف الله الجهالين", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338367251" },
            new { Id = 487, Name = "قصة النحل", Price = 50m, Stock = 10, Description = "عالم مثير ومدهش ومجتمع منظم؛ يعمل في تناسق عجيب؛ أحب علاء أن يدخل إلى هذا العالم الجميل المثير ويكتشف أسراره، فماذا فعل.. تعالوا معا نتعرف على هذه القصة الجميلة..\nالمؤلف\nعيد صلاح", CategoryId = 11, ImageUrl = "/images/products/9786338367282.webp", Author = "عيد صلاح", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338367282" },
            new { Id = 488, Name = "هدهد سيدنا سليمان", Price = 50m, Stock = 10, Description = "سلسلة حيوانات ذكرت في القرآن الكريم، يحتوي عشرة قصص موجهة للأطفال للمرحلة السنية من 6-12 سنة بأسلوبٍ بسيط وسهلٍ حتَّى يَستطيعَ الطِّفْلُ أنْ يَسْتَوْعِبها.\n\nقصص القرآن جميلة وتحتوي علي معاني وقيم هادفة للكبار والصِّغارِ علَي حَدٍّ سَواءٍ.\n\nنحن نحتاج أن نعمق معرفة أطفالنا بدينهم ونربطهم أكثرَ بالتُّراثِ الدِّيني بِأُسلوبٍ يَجذِبُ انْتباهَهمْ ويُثيرُ مَشاعِرهُمْ.", CategoryId = 11, ImageUrl = "/images/products/9786338367305.webp", Author = "شاكر صبرى", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338367305" },
            new { Id = 489, Name = "الفتنة", Price = 120m, Stock = 10, Description = "ونستخلص من هذا أن كعبًا قد يكون مشتركًا في المؤامرة أو على الأقل على علم بخيوطها!\nأو ربما كان مشتركًا في مؤامرة العرب وخاصة القريشيين؛ لأن عمر بن الخطاب قد ضيق عليهم بحزمه ومنع كبار الصحابة وأصحاب النفوذ من الانسلاخ في المدن المفتوحة؛ حتى لا يضطرب وضع العرب وينسون تقاليدهم وعادتهم وأن يبقيهم على بيئة العرب، ولكن أنا أستبعد ذلك لأن عمر نفسه قالها وهو على فراش الموت:\n- ما كانت العرب لتقتلني!\nلتبقى قضية اغتيال الخليفة العادل عمر لغزًا كبيرًا رغم معرفة القاتل الفعلي، ولكن لم نستطع معرفة القاتل الحقيقي الذي خطط وأحبك خيوط المؤامرة", CategoryId = 1, ImageUrl = "/images/products/9786338367312.webp", Author = "عبدالفتاح صابر", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338367312" },
            new { Id = 490, Name = "كيف تنقذ نفسك من الجهل", Price = 400m, Stock = 10, Description = "كتاب كيف تنقذ نفسك من الجهل\n\nفي عالم يمتلئ بالمعلومات… ما زال الكثير منا يعيش في متاهة الجهل دون أن يدرك.\n\nليس الجهل مجرد نقص في المعرفة، بل هو قيد خفي يقيّد التفكير، ويشوّه الرؤية، ويجعل الإنسان يعيش حياة أقل بكثير مما يستطيع أن يكونه.\n\nفي كتاب “كيف تنقذ نفسك من الجهل“ يأخذك د. محمد مندور في رحلة فكرية عميقة تكشف لك أخطر أنواع الجهل التي قد تعيشها دون أن تشعر… الجهل الذي يتخفّى خلف العادات، والأفكار الموروثة، واليقين الزائف.\n\nهذا الكتاب ليس مجرد طرح نظري، بل دعوة صادقة للاستيقاظ. دعوة لتعيد النظر في أفكارك، وتكسر القيود التي لم تكن تعلم أنها تحكمك.\n\nستكتشف بين صفحاته:\n\nلماذا يقع كثير من الناس في فخ الجهل رغم التعليم.\nكيف تتسلل الأفكار الخاطئة إلى عقولنا دون مقاومة.\nالطرق العملية لتحرير عقلك وبناء وعي حقيقي يقودك لحياة أكثر فهمًا وقوة.\nكل صفحة في هذا الكتاب قد تكون مفتاحًا يفتح بابًا جديدًا في عقلك… وكل فكرة قد تغيّر الطريقة التي ترى بها العالم… وربما نفسك أيضًا.\n\nإن كنت تبحث عن كتاب يوقظ عقلك، ويهزّ يقينك المريح، ويضعك على طريق الوعي الحقيقي…\n\nفهذا الكتاب لم يُكتب للجميع… بل كُتب لمن يملكون الشجاعة ليعرفوا الحقيقة.\n\nابدأ القراءة… فقد تكون هذه الخطوة الأولى لإنقاذ نفسك من الجهل.", CategoryId = 5, ImageUrl = "/images/products/9786338367336.webp", Author = "محمد مندور", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338367336" },
            new { Id = 491, Name = "صرخة", Price = 150m, Stock = 10, Description = "أغمض حمزة عينيه المثقلتين بالحياة التي تنوء الجبال بثقل حملها فرآها....ترتدي ثوبا فضفاضا أبيضا كعروس يوم زفافها...لم تتغير ملامحها الجميلة....يراها الآن علي الهيئة التي تركها يوم أسروه....أمه الرؤوم ولكن ما بعينيها الآن ليست نظرة حنانها المعتادة....إنها نظرة عتاب منكسرة....ركض نحوها بكل قواه...أُوصِدَت من بينهما قضبان سوداء قاسية....نادي بأعلي صوته::: أمي....\nحاولت هي تحريك القضبان لكن القضبان أدمت يديها فأخذت تنظر إليه نظرة انكسار و نهر دموعها يفيض وهي تهمس:: لماذا وضَعتَ هذه القضبان بيننا يا ولدي؟؟", CategoryId = 1, ImageUrl = "/images/products/9786338367350.webp", Author = "عهد على محمود", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338367350" },
            new { Id = 492, Name = "مدينة الطباشير", Price = 150m, Stock = 10, Description = "في مدينة الطباشير لا يعود الزمن كما كان، ولا المكان كما تظنه.\nبين هند وسماء يتكرر القدر في وجوه متطابقة ومصائر متشابكة عبر القرون.\nرسالة بالدم تُبعث من الماضي، وملك يعود ليُفجر سر الخيانة.\nإلى أرض فلسطين... حيث انعكاس الحقيقة في مرآة الوهم، والنهاية التي كتبت بدايتها.", CategoryId = 1, ImageUrl = "/images/products/9786338367367.webp", Author = "هشام البراوى", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338367367" },
            new { Id = 493, Name = "حياة المرأة المغولية في آسيا الوسطى", Price = 250m, Stock = 10, Description = "يتحدث هذا الكتاب عن المرأة المغولية، من حيث مكانتها ودورها في المجتمع، ويسلط الضوء على حياتها الاجتماعية والثقافية والاقتصادية والسياسية، وعلى مسؤولياتها داخل الأسرة والقبيلة، إضافة إلى دورها في بناء المجتمع المغولي والحفاظ على استقراره. كما يهدف الكتاب إلى إبراز ملامح شخصية المرأة المغولية وما تتميز به من قوة وتأثير في مختلف مجالات الحياة.", CategoryId = 8, ImageUrl = "/images/products/9786338367374.webp", Author = "ميسون عبداللطيف", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338367374" },
            new { Id = 494, Name = "ضفاير الشمس", Price = 120m, Stock = 10, Description = "هتلقى الشوق…\nهتلقى الحب…\nهتلقى الحنين…\nهتلقى الوطن… وفلسطين…\n\nهتلقى ضفاير الفتيات… وحواجب النيل…\nورمش القمر طاير على عين الحبيب… 🌙✨\n\nهتعيش ذكريات الشاي على الفحم وقت العصاري… ☕🔥\nوتسمع صوت الناي يبوح في الليالي…\nوتشم ريحة البيوت القديمة… وطَراحة الروح.\n\nهتسمع حكاوي الجد والجدة…\nوتحس طيبة الأب…\nودفا الأخت…\nوكف الأم وهي تلحق دمعتك قبل ما تنزل…\nوقلب الأخ اللي دايمًا يسند… ❤️\n\nهتلقى القهاوي… والناس بتملي كوبايات الشاي…\nوكلام من القلب… بيقعد على الكرسي اللي جمبك.", CategoryId = 8, ImageUrl = "/images/products/9786338367381.webp", Author = "محمود مصطفى هلال", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338367381" },
            new { Id = 495, Name = "بين الرجل و المرأة", Price = 250m, Stock = 10, Description = "يشملُ هذا الكتابُ كُلَّ ما يَخُصُّ شؤونَ المرأة، وكلَّ ما يشترك بينها وبين الرجل من الحب والعواطف، والزواج من الاختيار حتى الطلاق، وطبيعةِ المرأة وفسيولوجيّتِها، وتطرَّق الكتابُ أيضًا للحديث عن الناحية الفقهية لأمورِ المرأة التي تختلف فيها عن الرجل، وإن تشابها في كل أمور الحياة.\nنريد من خلال هذا الكتاب أن نبعث رسالةً إلى القارئ بأنَّ المرأةَ كائنٌ لطيفٌ جميل، يحتاج إلى رعايةٍ وعناية، يمكن أن يتحوَّل إلى مَلَكٍ أو إلى شيطانٍ، ويمكن أن يُصبح نقمةً على الرجل حين يُسيء معاملتَها أو التصرف معها أو يُهمِلَها حتى يفقدَها.\nالمرأةُ السويّة تستطيع أن تُصلِح الرجل، فالمرأة هي سرُّ الحياة وبدونها لا يمكن أن تستمر، وإصلاحُها وسلامتُها في النهاية هما سلامةُ المجتمع، وهذا ما أردنا أن يشير إليه الكتاب.", CategoryId = 8, ImageUrl = "/images/products/9786338367398.webp", Author = "شاكر صبرى", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338367398" },
            new { Id = 496, Name = "حوت نبى الله يونس (سلسلة حيوانات ذكرت في القرآن الكريم)", Price = 50m, Stock = 10, Description = "\"سلسلة حيوانات ذكرت في القرآن الكريم، يحتوي عشرة قصص موجهة للأطفال للمرحلة السنية من 6-12 سنة بأسلوبٍ بسيط وسهلٍ حتَّى يَستطيعَ الطِّفْلُ أنْ يَسْتَوْعِبها.\n\nقصص القرآن جميلة وتحتوي علي معاني وقيم هادفة للكبار والصِّغارِ علَي حَدٍّ سَواءٍ.\n\nنحن نحتاج أن نعمق معرفة أطفالنا بدينهم ونربطهم أكثرَ بالتُّراثِ الدِّيني بِأُسلوبٍ يَجذِبُ انْتباهَهمْ ويُثيرُ مَشاعِرهُمْ.\"", CategoryId = 11, ImageUrl = "/images/products/9786338367404.webp", Author = "شاكر صبرى", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338367404" },
