            new { Id = 500, Name = "(كلب أصحاب الكهف) سلسلة حيوانات ذكرت في القرآن الكريم", Price = 50m, Stock = 10, Description = "\"سلسلة حيوانات ذكرت في القرآن الكريم، يحتوي عشرة قصص موجهة للأطفال للمرحلة السنية من 6-12 سنة بأسلوبٍ بسيط وسهلٍ حتَّى يَستطيعَ الطِّفْلُ أنْ يَسْتَوْعِبها.\n\nقصص القرآن جميلة وتحتوي علي معاني وقيم هادفة للكبار والصِّغارِ علَي حَدٍّ سَواءٍ.\n\nنحن نحتاج أن نعمق معرفة أطفالنا بدينهم ونربطهم أكثرَ بالتُّراثِ الدِّيني بِأُسلوبٍ يَجذِبُ انْتباهَهمْ ويُثيرُ مَشاعِرهُمْ.\"", CategoryId = 11, ImageUrl = "/images/products/9786338367459.webp", Author = "شاكر صبرى", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338367459" },
            new { Id = 501, Name = "(ناقة نبى الله صالح) سلسلة حيوانات ذكرت في القرآن الكريم", Price = 50m, Stock = 10, Description = "\"سلسلة حيوانات ذكرت في القرآن الكريم، يحتوي عشرة قصص موجهة للأطفال للمرحلة السنية من 6-12 سنة بأسلوبٍ بسيط وسهلٍ حتَّى يَستطيعَ الطِّفْلُ أنْ يَسْتَوْعِبها.\n\nقصص القرآن جميلة وتحتوي علي معاني وقيم هادفة للكبار والصِّغارِ علَي حَدٍّ سَواءٍ.\n\nنحن نحتاج أن نعمق معرفة أطفالنا بدينهم ونربطهم أكثرَ بالتُّراثِ الدِّيني بِأُسلوبٍ يَجذِبُ انْتباهَهمْ ويُثيرُ مَشاعِرهُمْ.\"", CategoryId = 11, ImageUrl = "/images/products/9786338367466.webp", Author = "شاكر صبرى", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338367466" },
            new { Id = 502, Name = "أربعة فصول من قلبى", Price = 120m, Stock = 10, Description = "في الظلام يُخبئ الكثير من الأشياء..\nهناك دمعة لا نراها..\nو شوق لا نشعر به..\nو حنين لا يهز أعماقنا..\nو سرٌ لم يُباح به بعد..", CategoryId = 8, ImageUrl = "/images/products/9786338367473.webp", Author = "قمر سهيل قسطلى", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338367473" },
            new { Id = 503, Name = "سوشيال بيكيا لايفات , ريلزات , تيرندات", Price = 200m, Stock = 10, Description = "هذا الكتاب \"سوشيال بيكيا – لايف، ريلز، تريند\" ليس إلا مرآة تلتقط هذه الصور المتكسرة، محاولة لإنقاذ ما يمكن إنقاذه من سوق صاخبة تلتهم كل شيء، إنه تسجيل للوجوه والأصوات قبل أن تتحول إلى أشباح رقمية بلا أثر", CategoryId = 8, ImageUrl = "/images/products/9786338367480.webp", Author = "هبة عبدالعزيز", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338367480" },
            new { Id = 504, Name = "فيل أبرهة الحبشي سلسلة حيوانات ذكرت في القرآن الكريم", Price = 50m, Stock = 10, Description = "\"\"\"سلسلة حيوانات ذكرت في القرآن الكريم، يحتوي عشرة قصص موجهة للأطفال للمرحلة السنية من 6-12 سنة بأسلوبٍ بسيط وسهلٍ حتَّى يَستطيعَ الطِّفْلُ أنْ يَسْتَوْعِبها.\n\nقصص القرآن جميلة وتحتوي علي معاني وقيم هادفة للكبار والصِّغارِ علَي حَدٍّ سَواءٍ.\n\nنحن نحتاج أن نعمق معرفة أطفالنا بدينهم ونربطهم أكثرَ بالتُّراثِ الدِّيني بِأُسلوبٍ يَجذِبُ انْتباهَهمْ ويُثيرُ مَشاعِرهُمْ.\"\"\"", CategoryId = 11, ImageUrl = "/images/products/9786338367497.webp", Author = "شاكر صبرى", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338367497" },
            new { Id = 505, Name = "جناح واطواط", Price = 150m, Stock = 10, Description = "في دهاليزٍ يختلط فيها العلم بالغموض، تتكشف أسرار الخفافيش التي أخفاها التاريخ عن قصد.\nرواية \"جناح وطواط\" عمل يجمع بين الرعب النفسي والخيال العلمي، يكشف كيف يمكن لخللٍ جيني في مملكة الظلام أن يغير مصير الإنسان بأكمله، من خلال رحلة أنيس في مواجهة المجهول، ينكشف صراعٌ بين العقل والإيمان، بين ما نعرفه وما نخاف اكتشافه.\nلغة الرواية آسرة، مشحونة بالتفاصيل والرموز العلمية، لتقدم رؤية جديدة لعلاقة الإنسان بالمخلوقات التي تحيط به \"حين يفتح جناح الوطواط، يبدأ الضوء في طرح أسئلته الموجعة\"", CategoryId = 1, ImageUrl = "/images/products/9786338367510.webp", Author = "فرحه على", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338367510" },
            new { Id = 506, Name = "عصا نبي الله موسى التي تحولت إلى حية سلسلة حيوانات ذكرت في القرآن الكريم", Price = 50m, Stock = 10, Description = "\"\"\"\"\"\"\"سلسلة حيوانات ذكرت في القرآن الكريم، يحتوي عشرة قصص موجهة للأطفال للمرحلة السنية من 6-12 سنة بأسلوبٍ بسيط وسهلٍ حتَّى يَستطيعَ الطِّفْلُ أنْ يَسْتَوْعِبها.\n\nقصص القرآن جميلة وتحتوي علي معاني وقيم هادفة للكبار والصِّغارِ علَي حَدٍّ سَواءٍ.\n\nنحن نحتاج أن نعمق معرفة أطفالنا بدينهم ونربطهم أكثرَ بالتُّراثِ الدِّيني بِأُسلوبٍ يَجذِبُ انْتباهَهمْ ويُثيرُ مَشاعِرهُمْ.\"\"\"\"\"\"\"", CategoryId = 11, ImageUrl = "/images/products/9786338367534.webp", Author = "شاكر صبرى", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338367534" },
            new { Id = 507, Name = "مغامرات قطقوقة", Price = 50m, Stock = 10, Description = "قطقوطة قطة شقية، بتغلب ماما وبابا، وبتعمل مصايب أكبر منها، وبإبتسامة ماما وبابا بينسوا للمصيبة الجاية، مع نصيحة حلوة جميلة بعد كل مغامرة.", CategoryId = 11, ImageUrl = "/images/products/9786338367541.webp", Author = "إسراء كمال", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338367541" },
            new { Id = 508, Name = "كى لا تبكى", Price = 130m, Stock = 10, Description = "كي لا تبكي ليس وعدًا بالخلاص بقدر ما هو محاولة للتخفف؛ هو دعوة لأن نترك الدمع يجري حين يعجز الصدر عن الاحتمال، ولأن ندرك أن الحزن ليس عيبًا، بل حالة إنسانية تُعيدنا إلى جوهر ضعفنا الجميل. كل قصيدة في هذا الديوان تحمل عزاءً خفيًا، وتُمسك بيد قارئها كي تهمس له: “لستَ وحدك في حزنك، هنا من شاركك الوجع، ونسج لك من دموعه حروفًا تواسيك.”\n\nستجد بين هذه الصفحات لوحات من الانكسار، واعترافات صريحة، وصرخات مكبوتة، ولكنك ستجد أيضًا بصيص نورٍ يتسلل بخجل، وكأن الشاعر يريد أن يقول: “حتى في قاع الحزن، هناك ما يستحق الحياة.”", CategoryId = 1, ImageUrl = "/images/products/9786338367558.webp", Author = "عدنان مشهى", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338367558" },
            new { Id = 509, Name = "ميس عالية (استراحة للتفكير والتأمل فى مهنة التعليم)", Price = 200m, Stock = 10, Description = "هذا الكتاب استراحة للتفكر والتأمل، رحلة مع “ميس عالية” – معلمة بخبرة تزيد عن عشر سنوات، وقفت في الصفوف مرات لا تُحصى، عاشت لحظات الفرح والإرهاق، وواجهت تحديات التدريس اليومية التي تشبه موجات البحر صعودًا وهبوطًا، صخبًا وهدوءًا.\nفي هذه الصفحات، لن تجدي مجرد حكايات تُقرأ… بل ستجدين مساحات لتدوين أفكارك، وكتابة مشاعرك، والتوقف للحظة مع نفسك.", CategoryId = 8, ImageUrl = "/images/products/9786338367565.webp", Author = "أسماء أبو المجد", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338367565" },
            new { Id = 510, Name = "برائحة الياسمين", Price = 130m, Stock = 10, Description = "اتخذت الفرحة طريقها إلي قلبه و وجهه، محدثاً نفسها بسعادة بالغة…\n\nأكيد ياسمينتي هتفرح بيه أوي، شكرا يا رب، اللهم لك الحمد.\n\nأخذ هذا الشيء الذي يراه الكثيرون شيئا هينا، صغيرا، بسيطا، لا يبالون أنه أمر شاق علي غيرهم، كما أنه كبير جدا لهم..", CategoryId = 1, ImageUrl = "/images/products/9786338367572.webp", Author = "سارة سامى", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338367572" },
            new { Id = 511, Name = "من الصمت إلى الشفاء", Price = 130m, Stock = 10, Description = "في أعماق الذاكرة، هناك شيء ما يشبه الغرف المظلمة ، نتجنبها ولا نقترب منها..\n\nهي ليست منسية، ولكننا نخاف من تذكرها.\n\nلقد عاش الكثير من الناس طفولة لم تكن سهلة ، ولا دافئة ،\n\nبمعنى أنه (خسر طفولته)..", CategoryId = 5, ImageUrl = "/images/products/9786338367619.webp", Author = "نهى السعدى", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338367619" },
            new { Id = 512, Name = "كاميرا الأحداث", Price = 130m, Stock = 10, Description = "الحياة أشبه برقعة شطرنج\nيجب عليك أن تحافظ على الملك خاصتك حتى تنتصر في تلك المعركة.\nعليك أن تتعلم كيف تحول كل القطع التي أمامك لوسائل مساعدة لنجاتك حتى قطع العدو، لا تعتقد أن في تلك الحياة مبادئ وأنك تستطيع النجاة دون أن تؤذي أحد، فالحياة تضعك باختبارات إما تنتصر أو تُهزم، ولك مطلق الحرية.", CategoryId = 1, ImageUrl = "/images/products/9786338367626.webp", Author = "ولاء مصطفى", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338367626" },
            new { Id = 513, Name = "إليك يا صديقى", Price = 130m, Stock = 10, Description = "قل خيرًا أو اصمت.\nيا أصدقائي! من الأشياء الفاضلة أن يكون المرء قليل الكلام فمن كثر كلامه كثر خطأه، وفضول الكلام لا يأتي بخير.\nوإذا دعت الحاجة المرء إلى الكلام فليقل خيرًا أو ليصمت وهو علامة من علامات الإيمان فعن أبي هريرة ـــ رضي الله عنه ــــ أن النبي صلى الله عليه وسلم قال: \" ... ومن كان يؤمن بالله واليوم الآخر فليقل خيرًا أو ليصمُت\" متفقٌ عليه.\nوالمرء قليل الكلام يهابه الناس أو الصامت حتى يتحدث والعرب تقول:\nتكلم حتى أراك أي: حتى أعرفك. فالمرء مخبوءٌ، تحت لسانه.", CategoryId = 5, ImageUrl = "/images/products/9786338367633.webp", Author = "إبراهيم عبدالرحمن", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338367633" },
            new { Id = 514, Name = "بطوطة و بطيطة", Price = 50m, Stock = 10, Description = "\"قصة ممتعة وهادفة تأخذ الأطفال في رحلة شيّقة مليئة بالمواقف البسيطة والمعاني العميقة، حيث يتعلّمون من خلالها قيَمًا جميلة مثل الصدق، والتعاون، وتحمل المسؤولية. بأسلوب سهل ومحبّب، تساعد القصة الصغار على تنمية خيالهم وتعزيز سلوكياتهم الإيجابية بطريقة ممتعة وشيّقة.\"", CategoryId = 11, ImageUrl = "/images/products/9786338367640.webp", Author = "غالية يونس محمد", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338367640" },
            new { Id = 515, Name = "أرنوبة و سلة الجزر", Price = 50m, Stock = 10, Description = "\"قصة ممتعة وهادفة تأخذ الأطفال في رحلة شيّقة مليئة بالمواقف البسيطة والمعاني العميقة، حيث يتعلّمون من خلالها قيَمًا جميلة مثل الصدق، والتعاون، وتحمل المسؤولية. بأسلوب سهل ومحبّب، تساعد القصة الصغار على تنمية خيالهم وتعزيز سلوكياتهم الإيجابية بطريقة ممتعة وشيّقة.\"", CategoryId = 11, ImageUrl = "/images/products/9786338367657.webp", Author = "غالية يونس محمد", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338367657" },
            new { Id = 516, Name = "أرنوب الصغير و كذبنة الصغيرة", Price = 50m, Stock = 10, Description = "\"قصة ممتعة وهادفة تأخذ الأطفال في رحلة شيّقة مليئة بالمواقف البسيطة والمعاني العميقة، حيث يتعلّمون من خلالها قيَمًا جميلة مثل الصدق، والتعاون، وتحمل المسؤولية. بأسلوب سهل ومحبّب، تساعد القصة الصغار على تنمية خيالهم وتعزيز سلوكياتهم الإيجابية بطريقة ممتعة وشيّقة.\"", CategoryId = 11, ImageUrl = "/images/products/9786338367664.webp", Author = "غاليه يونس محمد", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338367664" },
            new { Id = 517, Name = "نمولة و قطعة الحلوى", Price = 50m, Stock = 10, Description = "\"قصة ممتعة وهادفة تأخذ الأطفال في رحلة شيّقة مليئة بالمواقف البسيطة والمعاني العميقة، حيث يتعلّمون من خلالها قيَمًا جميلة مثل الصدق، والتعاون، وتحمل المسؤولية. بأسلوب سهل ومحبّب، تساعد القصة الصغار على تنمية خيالهم وتعزيز سلوكياتهم الإيجابية بطريقة ممتعة وشيّقة.\"", CategoryId = 11, ImageUrl = "/images/products/9786338367671.webp", Author = "غاليه يونس محمد", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338367671" },
            new { Id = 518, Name = "من أخذ تاج الملك؟", Price = 50m, Stock = 10, Description = "\"قصة ممتعة وهادفة تأخذ الأطفال في رحلة شيّقة مليئة بالمواقف البسيطة والمعاني العميقة، حيث يتعلّمون من خلالها قيَمًا جميلة مثل الصدق، والتعاون، وتحمل المسؤولية. بأسلوب سهل ومحبّب، تساعد القصة الصغار على تنمية خيالهم وتعزيز سلوكياتهم الإيجابية بطريقة ممتعة وشيّقة.\"", CategoryId = 11, ImageUrl = "/images/products/9786338367688.webp", Author = "غاليه يونس محمد", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338367688" },
            new { Id = 519, Name = "الظل", Price = 130m, Stock = 10, Description = "الرواية …مهداة إلي العائدون من الفقد، من تعلقوا بظلال الماضي و سحبتهم خيوطه لعالم من الخيال فذابوا بين ظلاله و صعب عليهم الخروج من غيابات الأوهام و الذكريات.\nعن الكاتبة.. رشا فاروق طلب مدرسة ماث و خريجة كلية العلوم قسم الفيزياء و الفلك.. أحببت الكتابة منذ طفولتي و لي مشاركات في كثير من المدونات و روايتي الظل هي أول رواية أطلق سراحها لتخرج إلي النور.", CategoryId = 1, ImageUrl = "/images/products/9786338367701.webp", Author = "رشا طلب", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338367701" },
            new { Id = 520, Name = "عمر و الشجرة", Price = 50m, Stock = 10, Description = "في عالمنا الكبير نحتاج إلى هواء نقي وبيئة سليمة دون أن نفسد جمالها أو نظامها الذي خلقه الله لنعيش في صحة أفضل ونرى جمال صنع الخالق في كل شيء.", CategoryId = 11, ImageUrl = "/images/products/9786338367725.webp", Author = "سحر دغيدى", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338367725" },
            new { Id = 521, Name = "الملعونين", Price = 150m, Stock = 10, Description = "” الشمسُ تلوحُ في الأفقِ، تُرسلُ أشعتَها الذهبيةَ على مياهِ الترعة، لتكشفَ عن مشهدٍ تقشعرُّ لهُ الأبدانُ: جثثُ خمسةِ شبابٍ طافيةٌ، بوجوهٍ خاليةٍ من الحياةِ. النساءُ يصرخنَ ويذررنَ الترابَ، والرجالُ يراقبونَ بصمتٍ موجعٍ، وقلوبُهم تعتصرُها الحسرةُ على ضياعِ فلذاتِ أكبادِهم. وسطَ هذا الألمِ، يمدُّ بعضُ الرجالِ أيديهم لينتشلوا الأجسادَ الباردةَ من الماءِ “", CategoryId = 1, ImageUrl = "/images/products/9786338367749.webp", Author = "أحمد الرفاعى", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338367749" },
            new { Id = 522, Name = "همس الكلام", Price = 130m, Stock = 10, Description = "همس الكلام وشوشة\nح أقوله يمكن يشفعلك\nنصيحة مني قلتها\nقبل الزمان ما يوجعك\nهمس الكلام قصور سلام\nصوت ضميرها يسمعك\n\"ارجع وتوب من الذنوب\"\nصوت الأذان ح يرجعك", CategoryId = 8, ImageUrl = "/images/products/9786338367756.webp", Author = "عبدالنبى خطاب", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338367756" },
            new { Id = 523, Name = "الجار الأمين و بستان الفواكه", Price = 50m, Stock = 10, Description = "كان أمين الرجل الفقير جارا لرشيد الذي يمتلك بستانا للفواكه ولكنه يعيش وحيدا مع زوجته بلا أولاد، وقد اعتاد أن يعطي لأمين جزءا من الثمار التي يجنيها كل يوم حتى يبيعها في السوق ويستطيع إعالة أبنائه الصغار، وذات يوم تغيّب رشيد عن عمله واحتار أمين ماذا يفعل؟ ترى ماذا ألمّ برشيد؟ وما سرّ غيابه؟ وكيف تصرّف أمين في تلك الورطة؟", CategoryId = 11, ImageUrl = "/images/products/9786338367770.webp", Author = "إيمان فريد", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338367770" },
            new { Id = 524, Name = "زرو و عشبة الشجاعة", Price = 50m, Stock = 10, Description = "ماذا لو كان الخوف هو أول خطوة نحو الشجاعة؟\nتحكي قصة زرّو وعُشبة الشجاعة عن أرنب صغير يخاف من كل شيء، لكنه يكتشف أن الشجاعة الحقيقية لا تعني غياب الخوف، بل القدرة على المواجهة من أجل من نحب هي رحلة دافئة مليئة بالمغامرة والمعاني الإنسانية، موجهة للأطفال لتعلمهم أن القوة الحقيقية هي التي تسكن القلب.", CategoryId = 11, ImageUrl = "/images/products/9786338367787.webp", Author = "آيات خلف صابر", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338367787" },
            new { Id = 525, Name = "مروان و كرة الشاطئ", Price = 50m, Stock = 10, Description = "\"قصة ممتعة وهادفة تأخذ الأطفال في رحلة شيّقة مليئة بالمواقف البسيطة والمعاني العميقة، حيث يتعلّمون من خلالها قيَمًا جميلة مثل الصدق، والتعاون، وتحمل المسؤولية. بأسلوب سهل ومحبّب، تساعد القصة الصغار على تنمية خيالهم وتعزيز سلوكياتهم الإيجابية بطريقة ممتعة وشيّقة.\"", CategoryId = 11, ImageUrl = "/images/products/9786338367794.webp", Author = "غالية يونس محمد", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338367794" },
            new { Id = 526, Name = "أجنحة بين القيود", Price = 120m, Stock = 10, Description = "ليست مجرد حكاية تُروى، بل صرخة دفينة تسكن صدورًا كثيرة.\nتتقاطع فيها ملامح القهر مع بقايا الأمل،\nوتتوارى الأحلام خلف جدران الصمت الطويل.\nلكن في قلب الظلام تنبت دومًا رغبة في التحليق، رغبة في كسر القيود التي وُلدنا بين أسلاكها.\nربما تجد هنا نفسك، أو ظلّك، أو ما لم تجرؤ أن تبوح به يومًا.", CategoryId = 1, ImageUrl = "/images/products/9786338367817.webp", Author = "عبدالحميد إبراهيم", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338367817" },
            new { Id = 527, Name = "بيت الخير", Price = 50m, Stock = 10, Description = "بين جدرانٍ من طين وسقفٍ من جريد، يرتفعُ صرحٌ من الكرم لا يُغلق بابه ليلاً ولا نهاراً. هي حكايةُ حلمٍ قديم تحول إلى واقعٍ ملموس؛ نخلةٌ شامخة تجودُ بثرائها صيفاً وشتاءً ، وبئرٌ رقراق يرتوي منه الغريبُ قبل القريب.\nيصحبنا الجدُّ في رحلةٍ عبر الزمان ليروي للأحفاد قصة صاحب الدار الذي ذاق مرارة التشرد، فجعل من بيته ملاذاً لكل محتاج ومنارةً لتعليم الأجيال أن يد العطاء هي أصدقُ أثرٍ يتركه الإنسان.\n“بيتُ الخير.. ليس مجرد جدران، بل هو قصةُ إحسانٍ طافت الآفاق لتخبرنا أن العطاء هو نبض الحياة”.", CategoryId = 11, ImageUrl = "/images/products/9786338367848.webp", Author = "جمال بربري", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338367848" },
            new { Id = 528, Name = "ميسون و القطة فوفو", Price = 50m, Stock = 10, Description = "لما عادت ميسون من مدرستها، عند باب منزلها وجدت مفاجأة في انتظارها، تعرفون ما هي ؟!\nكانت قطـة بيضاء جميلـة تموء بلطـف عند قدميّ ميسون فحملتها في الحال بكل فرح.. لكن والدتها لم ترحب بهذه الزائرة الصغيرة .\nومن منا لا يحب صداقة القـطط الظريفة ؟\nأين ستذهب القطـة المسكينة \" فوفو \"؟", CategoryId = 11, ImageUrl = "/images/products/9786338367855.webp", Author = "أحمد المؤذن", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338367855" },
            new { Id = 529, Name = "الدودة المغرورة", Price = 50m, Stock = 10, Description = "قصة الدودة لعلكم تعرفونها، تدور أحداثها في المزرعة.\nالحياة في المزرعة تمضي بالتعاون ولكن الدودة المغرورة لها رأي آخر، فهي أنانية ولا تفكرإلا في نفسها ولا تكترث بطبيعة القرارات التي تتخذها.\nحتى نعرف ماذا حصل لها.. تعالوا جميعًا نقرأ الصفحات التالية ونكتشف بقية الأحداث.", CategoryId = 11, ImageUrl = "/images/products/9786338367862.webp", Author = "احمد المؤذن", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338367862" },
            new { Id = 530, Name = "رحلة صيد", Price = 50m, Stock = 10, Description = "محسن بدأت عـطلته الصيفية، أقترح عليـه والده الذهاب في رحلـة صيد بحريـة. فكر محسن بزرقة البحر الكبير وأشكال القواقـع الغريبة وكيف يسبح السمك في عـمق الماء ولكن هـل سيصطاد تلك السمكة الكبيرة التي زارتـه في حلمــه؟!", CategoryId = 11, ImageUrl = "/images/products/9786338367879.webp", Author = "احمد المؤذن", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338367879" },
            new { Id = 531, Name = "وطار العصفور", Price = 50m, Stock = 10, Description = "أمل أخبرت صديقتها صفاء ، كيف أنها تعبت كثيراً حتى تمكنت من إقناع شقيقها محمود باستعارة العصفور من أجل شرح حصة العلوم ، كما تعهدت رده إلى البيت وأن لا مشكلة في الأمر.\nصفاء تبحلق في العصفور، له ريش ملون فتان ولكنه صامت كما لو كان حزيناً يضيق بسجنه ، تتأمل صفاء العصفور المسكين بشفقة و تتمنى في سرها لو يكسر باب قفصه و يحلق بعيداً .\nأتعرفون يا أحبائي الصغار ماذا حـدث بعدها؟\nصديقتنا أمـل وقعت في ورطـة!\nأثناء حصة العلوم وقـع القفص من على طـرف طاولة المعلمة و...", CategoryId = 11, ImageUrl = "/images/products/9786338367886.webp", Author = "احمد المؤذن", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338367886" },
            new { Id = 532, Name = "فوق الغيوم", Price = 50m, Stock = 10, Description = "إيمان مندهشة من منظر الغيوم السوداء الداكنة التي تسبح في سماء المدينة ولديها تساؤلات كثيرة، تحدق إلى الأعـلى وهي في حافلة المدرسة قبل أن تقصدها غـيمة صغيرة هبطـت إلى الأرض!\nوما أجمل الدعـوة اللطيفة التي تلقتها الطفلة إيمـان ، مرت لحظات قبل أن تطير بها تلك الغيمـة الظريفة إلى السماء العالية لكن ماذا تفعل إيمان هناك في الأعـلى؟\nثمـة دروس مفيدة ستتعلمها إيـمـان من رحلتها إلى السماء، تعالوا معنا أحبائي الصغار نكتشف مغامرة طـريفة وحلوة هنـاك فوق الغيـوم.\nهيا بسرعـة فالغيمـة الصغيرة لن تبقـى في انتظارها طـويلا ، نزلت إلى الأرض لكونها أحبت صداقـة الطفلة إيمان وبدأت تجيب على أسئلتهـا. كذلك أنتـم يا صغـاري لديكم الكثير من الأسئـلة .", CategoryId = 11, ImageUrl = "/images/products/9786338367893.webp", Author = "احمد المؤذن", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338367893" },
            new { Id = 533, Name = "إبتسامة تعلم", Price = 50m, Stock = 10, Description = "\"قصة ممتعة وهادفة تأخذ الأطفال في رحلة شيّقة مليئة بالمواقف البسيطة والمعاني العميقة، حيث يتعلّمون من خلالها قيَمًا جميلة مثل الصدق، والتعاون، وتحمل المسؤولية. بأسلوب سهل ومحبّب، تساعد القصة الصغار على تنمية خيالهم وتعزيز سلوكياتهم الإيجابية بطريقة ممتعة وشيّقة.\"", CategoryId = 11, ImageUrl = "/images/products/9786338367916.webp", Author = "نهاد مانع", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338367916" },
            new { Id = 534, Name = "الجدة تحت البرتقال", Price = 50m, Stock = 10, Description = "\"قصة ممتعة وهادفة تأخذ الأطفال في رحلة شيّقة مليئة بالمواقف البسيطة والمعاني العميقة، حيث يتعلّمون من خلالها قيَمًا جميلة مثل الصدق، والتعاون، وتحمل المسؤولية. بأسلوب سهل ومحبّب، تساعد القصة الصغار على تنمية خيالهم وتعزيز سلوكياتهم الإيجابية بطريقة ممتعة وشيّقة.\"", CategoryId = 11, ImageUrl = "/images/products/9786338367923.webp", Author = "غالية يونس محمد", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338367923" },
            new { Id = 535, Name = "قصة الحذاء الذى يعرف الطريق", Price = 50m, Stock = 10, Description = "\"قصة ممتعة وهادفة تأخذ الأطفال في رحلة شيّقة مليئة بالمواقف البسيطة والمعاني العميقة، حيث يتعلّمون من خلالها قيَمًا جميلة مثل الصدق، والتعاون، وتحمل المسؤولية. بأسلوب سهل ومحبّب، تساعد القصة الصغار على تنمية خيالهم وتعزيز سلوكياتهم الإيجابية بطريقة ممتعة وشيّقة.\"", CategoryId = 11, ImageUrl = "/images/products/9786338367947.webp", Author = "نهاد مانع", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338367947" },
            new { Id = 536, Name = "النور الذى هدم السور", Price = 130m, Stock = 10, Description = "في عالمٍ تحكمه الأسوار، يولد نورٌ صغير يرفض الخضوع.\nبداية رحلة بين الخوف والشجاعة، حيث يكون السؤال الأول:\nهل يكفي النور ليبدأ التغيير؟\n\nللكتاب جزء ثانٍ: الجزء الثاني.", CategoryId = 1, ImageUrl = "/images/products/9786338367954.webp", Author = "ميليا عبدالكريم محسن", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338367954" },
            new { Id = 537, Name = "حائزة فى الافق", Price = 130m, Stock = 10, Description = "رسالةٌ مجهولة، وزجاجةٌ قذفتها الأمواج، وفتاةٌ تقف كل يوم عند الأفق، لا تعلم أن قلبًا يراقبها بصمت.\nحكاية حبّ تبدأ من بعيد، وتنمو في الانتظار، حيث يصبح الصمت لغةً، والأفق وعدًا.", CategoryId = 1, ImageUrl = "/images/products/9786338367961.webp", Author = "ميليا عبدالكريم محسن", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338367961" },
            new { Id = 538, Name = "رحلة إلى ذاتك متاهات القوة والضعف", Price = 450m, Stock = 10, Description = "هل شعرت يومًا أنك تعيش حياتك… لكنك لا تعرف نفسك حقًا؟\nأن هناك شيئًا في داخلك يحاول أن يتكلم، لكن ضجيج العالم يمنعه؟\n\n“رحلة إلى ذاتك – متاهات القوة والضعف“ ليس كتابًا عاديًا عن تطوير الذات، ولا مجموعة نصائح محفوظة يمكن أن تقرأها ثم تنساها. إنه مرآة صادقة ستضعك وجهًا لوجه مع نفسك… مع قوتك التي لم تكتشفها بعد، ومع ضعفك الذي حاولت الهروب منه طويلًا.", CategoryId = 5, ImageUrl = "/images/products/9786338367985.webp", Author = "محمد مندور", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338367985" },
            new { Id = 539, Name = "الدليل السري لكتابه الرواية (متداول جملة فى اخر همسة)", Price = 300m, Stock = 10, Description = "ليست كل الروايات تُكتب… بعضها يُصنع بمهارة.\n\nلماذا تنجح بعض الروايات في أسر القارئ من الصفحة الأولى… بينما تتعثر أخرى رغم الفكرة الجيدة؟\n\nما السر الذي يجعل القارئ يسهر الليل ليكمل رواية؟\nوكيف يخلق الكاتب شخصيات تبدو حقيقية كأنها تعيش بيننا؟\n\nفي هذا الكتاب ستكتشف الأسرار الخفية لصناعة الرواية… الأدوات التي يستخدمها كبار الروائيين دون أن يتحدثوا عنها كثيرًا.", CategoryId = 5, ImageUrl = "/images/products/9786338367992.webp", Author = "محمد مندور", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338367992" },
            new { Id = 540, Name = "قهوة بطعم النبيذ", Price = 250m, Stock = 10, Description = "“حين تمتزج القهوة بالنبيذ… يولد جيل لا يهاب الخيانة.”", CategoryId = 1, ImageUrl = "/images/products/9786338387020.webp", Author = "هدير مجدى العجمى", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338387020" },
            new { Id = 541, Name = "ستاريكس", Price = 200m, Stock = 10, Description = "تسبّبَ الخدرُ والنعاسُ وحركةُ السيّارة وصوتُ عجلاتِها بنومِ الجميعِ. كانَ ضوءُ الفجرِ الرمادي يعلنُ تمدّدَهُ بشكلٍ طبيعي، وتلّوحُ زرقةُ الصباحِ قبلَ أنْ يخرجَ قرصُ الشمسِ الذي سيكونُ أمامَ وجهِ الجالسينِ على جهةِ اليمينِ. لا شيءَ يمكنُ أنْ يحرّكَ الجفونَ المستسلمةَ للذّةِ النعاسِ سوى تعبُ الرقابِ من إيجادِ مكانٍ مريحٍ على مساندِ المقاعدِ، لتتشعّبَ الحركاتُ في البدءِ ثم تلوذُ بالنومِ…كلُّ شيءٍ هادئٌ في بطنِ السيّارةِ التي تتلذّذُ بهواءِ تشرينَ الداخلِ من نوافذَ مفتوحةٍ قليلًا، وكأنَّها تعبّئُ ما ينقصُ العمرَ من هواءٍ منعشٍ لم تحفلْ به الأجسادُ من قبلُ.", CategoryId = 1, ImageUrl = "/images/products/9786338387037.webp", Author = "على لفته سعيد", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338387037" },
            new { Id = 542, Name = "فهم اللعبة الإنتاجية", Price = 200m, Stock = 10, Description = "لقد اعتبر المؤلف طريقة إنتاج النص لعبة، ولكن هل يحمل الملفوظ دلالته المألوفة والمعتادة فقط؟\nإن اللعب بما هو تحرّر من الصرامة والجدية والإلزام إلّا أنه خاضع لقوانين ضابطة، قد يبدو المصطلح غريبًا لأوّل وهلة، لأنه يؤوّل إلى الاستصغار وينحرف نحو دلالة الإهمال والانتقاص ويدل على مالا يلزم، إذ لا جدوى منه ولا فائدة ترتجى منه، لكنه يفيض بالإتّقان ويعوّل على الترجيح وحسن التدبير والدربة حتى يسير إلى ما يفترض به، وهذه القصدية هي التي تأسّست عليها إشكالية الكتاب، لذلك وأنا أقرأ ما ورد فيه، ومع كلّ جزئية تمرّ بي، يزيد اقتناعي بأن الأستاذ علي نفسه يمارس هذه اللعبة على مستوى النقد أيضا، أو ما يمكن اعتباره لعبة تأويلية تتقصّى المضمر، إذ يحاول أن يقود التفكير النقدي ناحيته ويقنعنا بأن الدهشة والخرق هما ما يضمنان إتّقان اللعبة ،وأن الناقد المتمرّس هو الذي يبرز هذه القدرة الإبداعية بعيدا عن الصبغة التبجيلية، وبعيدا كذلك عن الرؤية التي تجد في القراءة فعل محاكمة تتصيد الأخطاء فقط .", CategoryId = 8, ImageUrl = "/images/products/9786338387044.webp", Author = "على لفته سعيد", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338387044" },
            new { Id = 543, Name = "الديك المغرور", Price = 50m, Stock = 10, Description = "لقد مللتُ ذلك الاستغلال، لماذا يتوجب علىّ الاستيقاظ مبكرًأ كل يوم بينما الجميع نائمين في فراشهم؟ ثم لماذا عليّ أن أرهق أحبالي الصوتية في النداء بصوتٍ عالٍ حتى يستيقظ الجميع ؟ أنا أريد أن أنام طويلًا كما ينام الجميع واستيقظ في الموعد الذي يحلو لي.", CategoryId = 11, ImageUrl = "/images/products/9786338387051.webp", Author = "منال جميعي", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338387051" },
            new { Id = 544, Name = "فلفول اللعوب", Price = 50m, Stock = 10, Description = "دائما الحياة تعطينا السعادة\nبيدينا نحن أن نسعد أو نوقع أنفسنا في مرهقات الحياة\nنعم افرح واضحك والعب واسعد، ولكن أترك مسافة آمنة لكي لا تصيب من حولك بالضرر أو تصيب نفسك..\nومن هنا أترك لكم قصتي الخارجة من قلب طفلة لتكون بين يد طفل آخر تخلق داخله نصيحة صغيرة", CategoryId = 11, ImageUrl = "/images/products/9786338387068.webp", Author = "لورين أيمن محمد عبدالمعوض", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338387068" },
            new { Id = 545, Name = "جبل سيما", Price = 150m, Stock = 10, Description = "تبدأ أحداث الرواية بمشهد لأسطورة تتحدث عن تاجر خسر الكثير من أمواله فقرر اصطحاب ابنه الوحيد والبحث عن كنز أخبره عنه أجداده، مكان الكنز هو صخرة عين التنين الموجودة في صحراء سيناء بعد بحث شاق يكتشف الأب أنه حرر الكنز وحرر معه روح سعدة بنت جرهم ساحرة عربية قديمة دفنت في هذا وقد سحرت سبعة من خيرة شباب قبيلة جرهم و جولتهم وحوشا لا يعيشون مع البشر فدعا عليها أحد الصالحين فماتت ودفنت في ذلك الكهف وحولها كنوز كثيرة وذهب لا يعد ولا يحصى.", CategoryId = 1, ImageUrl = "/images/products/9786338387075.webp", Author = "ماجدة مرسي", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338387075" },
            new { Id = 546, Name = "في ثقب الليل", Price = 150m, Stock = 10, Description = "هذا الليل ليس قصيدة ولكنه ربما يكون مواعيدًا للهوى، يمكن صرف متعتها من مصرف الخيانة الصامتة عندما تسأم المرأة زوجها وتقرر استبداله.. القصص التي تجدها من خلف الغلاف مليئة بالثقوب ومغلفة بغموض الليل.\n\nكل ثقب يُعلن عن نفسه بصراحة صادمة تشتعل في اشتهاء الخطيئة التي يوقد نيرانها إبليس، يتخطى محطات انتصاره ويضحك على ضحاياه. لتعذرني أيها القارئ فيما لو وجدت لنفسك هنا محطة توقفت في ليلها ذات يوم وحفرت لنفسك ثقبًا (…………)، فما أنا هنا بوارد التماس العزاء لحضرتك، ولا أنوي أذيّتك، لكن ورطتك في النهاية تخصك، ووقتئذٍ أقلب الصفحة فقط وأهرب من الثقب أو إليه وتتقبل مصيرك كيفما كان. لا تقلق، أترك عنك ثرثرة المقدمة وتعال معي نمشي بهدوء، فالطريق وعرة قليلًا بهذا الليل، وستجده يستبدل في كل مرة جلده مع كل قصة، خُذ الحذر!", CategoryId = 1, ImageUrl = "/images/products/9786338387082.webp", Author = "أحمد المؤذن", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338387082" },
            new { Id = 547, Name = "رجل للبيع", Price = 150m, Stock = 10, Description = "يمكن قراءة مجموعة “رجل للبيع” للكاتب البحريني أحمد المؤذن عبر تفكيك الدلالة السيميائية للعنوان؛ مفتاح النص. فالمفردة الأولى “رجل” من دون إضافتها لما قبلها، اسم نكرة، وهي في الوقت نفسه قوية الدلالة، ولها وقعها الخاص والمقدس في العقلية الشرقية، وعند إضافة الكلمة الثانية لها “للبيع” تتحول هذه النكرة إلى معرفة، وتنجلي عنها قدسيتها إذ “الرجل” موضوعيًا، يصبح سلعة قابلة للتداول.\nإنها لعبة المتناقضات المشغولة بها جلّ قصص المجموعة، والتي تجسد نوعًا من السخرية التي تؤكد وعي الذات تجاه نفسها في لحظات ضعفها وانكسارها وفقدانها مكمن قوتها وبحثها المحموم في ثنايا عالم مختل ومتقلّب، عن فسحة تنفذ منها لتسترد قوتها. والمؤذن هنا يستثمر بوعي هذا الأسلوب ليقدم رؤية مغايـرة للعالم متأتية من نقد الذات الفردية وبالتالي نقد المجتمع المتأسس على مجاميع من الذوات؛ محاكمته وكشف زيفه وتعرية المستور فيه.", CategoryId = 1, ImageUrl = "/images/products/9786338387099.webp", Author = "أحمد المؤذن", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338387099" },
            new { Id = 548, Name = "الفيل جميل ورد الجميل", Price = 50m, Stock = 10, Description = "\"قصة ممتعة وهادفة تأخذ الأطفال في رحلة شيّقة مليئة بالمواقف البسيطة والمعاني العميقة، حيث يتعلّمون من خلالها قيَمًا جميلة مثل الصدق، والتعاون، وتحمل المسؤولية. بأسلوب سهل ومحبّب، تساعد القصة الصغار على تنمية خيالهم وتعزيز سلوكياتهم الإيجابية بطريقة ممتعة وشيّقة.\"", CategoryId = 8, ImageUrl = "/images/products/9786338387105.webp", Author = "ندي إبراهيم", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338387105" },
            new { Id = 549, Name = "مصارعة الاخلاق", Price = 150m, Stock = 10, Description = "ذا كتابي جمعت فيه بعضًا من هموم أمتي وقضاياها المهمة، وتدارست أسبابها وسعيت وراء مقاصدها، وتدبَّرت حلولها ما شاء الله لي القدرة على ذلك، فكتبت عن دينها وثقافتها وآدابها وتاريخها وموروثها، فتباكيت وغضبت وأشفقت، وهو مقالات تتناول أحوال الأمة الإسلامية من نواحيها الدينية والتاريخية والأدبية والفكرية، تناولًا يبيّن الحرب الاستعمارية على هذه الأمة، الحرب التي لا تتخذ جبهة بعينها، فإن قصفت القلم فذا مغنم، وإن ضربت الجباه فذاك الهدف، وكل نتيجة تُوقف هذه الأمة عن غايتها هي مغنم لهم.", CategoryId = 8, ImageUrl = "/images/products/9786338387129.webp", Author = "السيد الشايب", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338387129" },
            new { Id = 550, Name = "بأي بلسم تشفى أعماقي", Price = 150m, Stock = 10, Description = "حِمْلَ صَدْرِي\nوَإِشْرَاقِي،\n\nفُكَّ قَيْدِي\nوَوِثَاقِي..\n\nإِنِّي وَالْجُنُونُ\nفِي سِبَاقٍ\nوَالْحِلْمُ وَالْعَقْلُ\nفِي طِبَاقٍ..\n\nنَجْرِي\nإِلَى لَا مُسْتَقَرٍ\nكَالْبُرَاقِ..\n\nحِمْلَ صَدْرِي\nوَإِشْرَاقِي،\n\nدَعْكَ مِنِّي\nوَمِنْ إِغْرَاقِي..\n\nفَلَا أَنتَ أَرْضَ\nمَقْدِسٍ وَلَا عِرَاقٍ..\n\nلَكِنَّ مَوْتِي فِيكَ..\nشَهَادةٌ،\nوَتَحَرُّرِي مِنْكَ..\nفِيهِ انعِتَاقِي..\nالشاعرة حنان الدومي", CategoryId = 8, ImageUrl = "/images/products/9786338387136.webp", Author = "حنان الدومى", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338387136" },
            new { Id = 551, Name = "مختلفة", Price = 100m, Stock = 10, Description = "قصة إنسانية إجتماعية تخُص فئة مُعينة ، وتصُب الإهتمام نحو شريحة حية في المجتمع .\nنُحلل فيها بعض الطبائع البشرية والسلوكيات المُجتمعية التي تُنافي الدين وتضُر بالمجتمع نفسيًا وتِباعًا لذلك تُعيق نهضة الأمة .\n٠ نُعالجها بالوازع الديني ،الأخلاقي، والنفسي كذا الوازع الفكري لمحاربة السلوم بالأحرى بالوازع الإنساني .\n٠ تمزج بين الواقع والخيال إذا أَطَقْتَ أَدْرِك الواقع من الخيال .", CategoryId = 11, ImageUrl = "/images/products/9786338387150.webp", Author = "إلهام عبدالمعز عبدالتواب", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338387150" },
            new { Id = 552, Name = "سرداب الفطرة الإلهية", Price = 140m, Stock = 10, Description = "٠ ليس كتابًا عابرًا سيمضي عليك، أو ينساب من بين يداك دون أن يُخلِب عيناك ، وتلتهمه حواسك ، بل سيرنو من روحك حتى يأسِر وجدانك .\n\n٠إنه يغوص في أعماق الروح وكينونة الذات المُزينة بالفطرة الإلهية .\n\n٠ مجموعة من الرحلات التي قد تبدو لك واقع، وقد يُبصِرها عقلك خيال .\nلكنه حتمًا سيجد المرسى ويبلُغ الميناء .\n\n٠ أنا معك هنا حتى نربط بين الواقع والخيال، وأُريك أن الخيال ليس خارج حدود الفطرة. بل الواقع والخيال بينهما رابط وثيق أنهما معًا تحت وطأة الإله .\n\n٠ لنرى كيف للفطرة الإلهية أن تُبحِر بك في عوالم الكون، وتصل بك إلى شط النجاة . بشرط أن تكُون مُحكًمة بالإيمان بخالق الأكوان، وتُردِف الأصل وما أنزل الرحمن .\n\n٠ إنها الفطرة صانعة المعجزات، خالقة الإبداع، مُلهِمة الأنام .\n\n٠ إنها الفطرة الربانية من الله ذي السلطان للورى عبيده في سائر الأزمان .", CategoryId = 1, ImageUrl = "/images/products/9786338387174.webp", Author = "إلهام عبدالمعز", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338387174" },
            new { Id = 553, Name = "فرفور بطل السباق", Price = 50m, Stock = 10, Description = "هل السرعة وحدها تصنع البطل؟\nفي فرفور بطل السباق، نعيش مع الأطفال مغامرة ممتعة ومليئة بالضحك، نتعلّم من خلالها أن الفوز ليس أن نصل أولًا، بل أن نعرف الطريق جيدًا.\nقصة ذكية تُظهر أن التفكير، والصبر، والتعاون قد تكون أسرع أثرًا من الجري نفسه، وأن البطل الحقيقي هو من يتعلّم قبل أن يندفع.", CategoryId = 11, ImageUrl = "/images/products/9786338387181.webp", Author = "سماح ماضى", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338387181" },
            new { Id = 554, Name = "لابرادوريت (أرض الحقيقة)", Price = 130m, Stock = 10, Description = "اقتباس ظلَّ يراقب شيئا ما داخل المرآة حتى ظهر انعكاس كائنٍ طويل القامة بشع المنظر، له قرنان ملونان باللون الأحمر، جسده أسود اللون، ولديه أظافر طويلة جدًا مقززة للغاية.\nفجأة اختفى ذلك الكائن من انعكاس المرآة، ليتحول زجاجها إلى اللون الأسود الفحمي، ثم صدر صوتٌ كفحيح الأفاعي يبدو أنه قادمٌ من الجحيم.", CategoryId = 1, ImageUrl = "/images/products/9786338387198.webp", Author = "مروة ابراهيم محمد", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338387198" },
            new { Id = 555, Name = "الشقة 69", Price = 130m, Stock = 10, Description = "ربما صدمة تجعل من الإنسان شخصا آخر\nوربما موقف يجعله يتناسى دوره الحقيقي في الحياة ليتحول 180 درجة\nربما هي، نصف الحقيقة فقط\nمرآة وقد عكست الحقائق أصبحت الأدوار مغيبة\nوما زال للحديث بقية", CategoryId = 1, ImageUrl = "/images/products/9786338387211.webp", Author = "محمد ابراهيم حجاج", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338387211" },
            new { Id = 556, Name = "العنود (الوجه الذى لا ينعكس)", Price = 130m, Stock = 10, Description = "العنود كاتبة لا يهمها سوى الورق والقلم والصمت, عاشت حياتها في أوائل التسعينات بهدوء ظاهري، تقضي نهارها في وظيفة عادية، وقليلًا ما تسألت إن كان هناك من يسمع صمتها الداخلي. في إحدى الليالي، تلقت رسالة بلا اسم مكتوبة فيها:\n\n“لقد شاهدناكِ… لا تنظري في المرآة”", CategoryId = 1, ImageUrl = "/images/products/9786338387228.webp", Author = "عدى عبدالفتاح", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338387228" },
            new { Id = 557, Name = "اتصال واحد", Price = 120m, Stock = 10, Description = "اليوم رقم خمس و أربعون منذ بدء الرحلة , بعد تفجيرات النووي التي ملأت جوانب كوكب الأرض واختفت الحياة –وصلت من مجرة مجاورة لمجرة درب التبانة بعد رصد انفجارات نووية علي الأرض , الشمس لا تصل أشعتها الي ظهر الكوكب ( كوكب معتم ) , الغبار ما زال يمتلئ ببعض المواد المشعة ,. لا رصد لأي حياة حتى الآن.", CategoryId = 1, ImageUrl = "/images/products/9786338387235.webp", Author = "محمد يحيى", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338387235" },
            new { Id = 558, Name = "ملوك الظلام", Price = 160m, Stock = 10, Description = "في زمنٍ اهتزّت فيه عروش الممالك، وخرج من أعماق العدم نسلٌ من الملوك… خُلقوا من الظلام.\nسقطت الممالك أمام قوتهم، ثم سقطوا هم أمام قدرٍ كتبته اللعنة. لكن الأسطورة لم تنتهِ… فدماء ملوك الظلام ما زالت تغلي.\nحين تختلط النبوءة بالقدر، يصبح الولاء خيانة، والحبّ سلاحاً مميتاً.\nتتشابك الأرواح القديمة بالجديدة، وتستيقظ أسرار دفنتها الحروب.\nحيث لا ينجو إلا من يُجيد اللعب بالنار… وفي الظلام.", CategoryId = 1, ImageUrl = "/images/products/9786338387242.webp", Author = "إسراء كمال", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338387242" },
            new { Id = 559, Name = "خارج صندوق الأحلام", Price = 130m, Stock = 10, Description = "كانت تلك الليلة ككل الليالي المنصرمة على سكان ذلك المنزل المتهالك ذي الطابقين في الحارة الضيقة، يلاصقه عدد من البيوت القديمة، لا يغيب عن ساكن فيها ما يدور حوله في الغرف المجاورة، ناهيك عن تحيات الصباح والمساء المتبادلة بينهم عبر النوافذ، كأنهم على وشك المصافحة يوجد بعض الحوانيت، منها دكان صغير لبائع الخردوات عم جابر، له باب خشبي متهالك ذو درفتين، رجل طاعن في السن، أتت الشيخوخة على كل مفاصله، له جسد واهن، في الساعات المبكرة من الصباح يعتريه رجفة من الألم الممض، أصوات طقطقة أسفل ظهره، حتى ليسمعها من يقترب منه و كأن عموده الفقري على وشك الانهيار، ستتناثر عظامه على الأرض.", CategoryId = 1, ImageUrl = "/images/products/9786338387266.webp", Author = "منى منصور السيد", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338387266" },
            new { Id = 560, Name = "باب اللعنات", Price = 130m, Stock = 10, Description = "ذلك العالم لا يخضع لقوانين الطبيعة، ولا يحكمه منطق العقل، تسكنه كيانات لا تعرف الرحمة، ولا تفهم البشر, إلا كما نفهم نحن ظلالنا, نراها، لكنها لا تملك ملامح.\nمنذ قرون، ظل هذا العالم مفصول بستار خفي، لا يراه إلا من ضلّ الطريق أو كُشف له الحجاب, لكن ما لا يعرفه الكثيرون, أن هناك من يتعمد فتح هذه الستائر، ومن يبيع روحه إلى الجانب الآخر.\nلم أكن أؤمن بشيء, حتى بدأت أسمع الأصوات ليلاً، وأشعر بأنفاسٍ لا يراها أحد، وأرى أعينًا تتوهج في الظلام. منذ تلك الليلة، حين استدعيت شيئًا ظننته لن يجيب, لكنه جاء.\nيجب أنك تقرأ هذه الكلمات، لأنك ستعرف قريبًا أن بعض الأبواب لا يجب طرقها، وبعض العوالم, لا يجب أن تُزار أبدًا.\nهذه ليست حكايات من وحي خيال، بل اعترافات متأخرة، ووثائق نجت من حريق الحقيقة, اقرأها إن كنت تملك الجرأة، لكن تذكّر, أن بعض الطرق لا عودة منها، وبعض الأسماء حين تُنطق تُوقظ ما لا ينبغي إيقاظه", CategoryId = 1, ImageUrl = "/images/products/9786338387273.webp", Author = "غدى عبدالفتاح", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338387273" },
            new { Id = 561, Name = "إقتلونا رجاء", Price = 120m, Stock = 10, Description = "أود أن أرحب بجميع المتأهلين إلي تلك المرحلة , لقد قدمتم للجنة المسابقة أسبابا كافية ومقنعة للتقدم خطوة أخري في طريق الثلاث المختارون و طبقا لتعليمات لجنة المسابقة فهناك ثلاث إختبارات يسعدني أن أخبركم بأنها ستكون صعبة للغاية وهي تختبر صبركم وقوتكم وشجاعتكم", CategoryId = 1, ImageUrl = "/images/products/9786338387280.webp", Author = "محمد يحيى", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338387280" },
            new { Id = 562, Name = "مزامير الجحيم", Price = 140m, Stock = 10, Description = "في مكانٍ ما بين العقل والجنون، بين اليقظة والحلم، يتسلّل صوتٌ خافتٌ كأنما يأتي من أعماق الجحيم نفسه… لا يحمل لعنات، بل أناشيد، مزامير تُتلى على أرواحٍ ضلّت طريقها.\n\nكل قصة هنا ليست حكاية رعب تقليدية، بل مرآة سوداء تعكس وجوهنا حين ننظر لأنفسنا دون أقنعة.\n\nفي “مزامير الجحيم” لا وجود لوحوشٍ تُطاردنا من الخارج، بل لأفكارٍ تنهشنا من الداخل، لمخاوف نغذّيها نحن بأيدينا حتى تستيقظ وتبتلعنا.", CategoryId = 1, ImageUrl = "/images/products/9786338387297.webp", Author = "رحمة أحمد السيد", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338387297" },
            new { Id = 563, Name = "الأيدو", Price = 150m, Stock = 10, Description = "هل جرّبت أن ترى وفاة أشخاص لا تعرفهم… ليست رؤية عادية وليست رؤية سابقة… الرؤية هنا رؤية من نوع آخر… رؤية مستقبلية، تستطيع رؤية وفاة الأشخاص فقط من النظر إلى أعينهم، ولن تستطيع أن تفعل شيء لهم، تراهم يموتون عن بعد… احترس…. إذا لديك قلب ضعيف، فلا تأخذ هذه الرواية… فأنت…. مع الأيدو..!", CategoryId = 1, ImageUrl = "/images/products/9786338387303.webp", Author = "أسماء محمد عبدالسلام", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338387303" },
            new { Id = 564, Name = "من دفتر العمر", Price = 130m, Stock = 10, Description = "«من دفتر العمر» هو كتاب شعري يقدّم للقارئ رحلة إنسانية صادقة وممتدة عبر محطات الحياة المختلفة، كأنه دفترٌ مفتوح يسجّل لحظات الفرح والحزن، الانتصارات والانكسارات، الأحلام المؤجلة والذكريات التي لا تُنسى. يأتي الديوان بالعامية المصرية ليكون قريبًا من الناس، قادراً على لمس مشاعرهم دون حواجز لغوية أو تعقيدات. فالكاتب هنا لا يكتب شعراً فقط، بل يكتب نبض القلب وهو يتقلب بين فصول العمر.", CategoryId = 8, ImageUrl = "/images/products/9786338387310.webp", Author = "سوزان الفطيرى", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338387310" },
            new { Id = 565, Name = "لعنة المجلد الأسود", Price = 150m, Stock = 10, Description = "تحت بيتٍ ملعون يرقد مجلد فرعوني غامض… كل من اقترب منه، انفتح له باب إلى ما لا يُرى.\n\nكوابيس متشابكة تكشف وجوه الماضي والحاضر والمستقبل، تقود إلى الحقيقة — أو إلى اللعنة ذاتها.\n\nرواية تُعيد تعريف الرعب، حيث لا يميّز القارئ بين ما يراه نائمًا… وما يعيشه يقظًا.", CategoryId = 1, ImageUrl = "/images/products/9786338387327.webp", Author = "رحمة أحمد، حسين العربى", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338387327" },
            new { Id = 566, Name = "عتمة الظلال حين تنطفئ الظلال", Price = 150m, Stock = 10, Description = "تدور أحداث الرواية في مدينة الإسكندرية مطلع القرن العشرين، في زمنٍ يقف على تخوم التحوّل بين التقاليد الموروثة وبدايات الحداثة، حيث تختلط طموحات الأفراد بمصالح العائلات الكبرى، وتتقاطع الأحلام الرومانسية مع حسابات المال والسلطة.", CategoryId = 1, ImageUrl = "/images/products/9786338387334.webp", Author = "علاء سرحان", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338387334" },
            new { Id = 567, Name = "ذبيحة الظلال حين تتمدد الظلال", Price = 150m, Stock = 10, Description = "تبدأ الحكاية كأنها مجرد قصة عائلة، لكن سرعان ما تنكشف طبقات أعمق تجعل القارئ يكتشف أن العائلة ليست سوى خيط صغير في مسرح كونيّ دمويّ لا ينتهي.", CategoryId = 1, ImageUrl = "/images/products/9786338387341.webp", Author = "علاء سرحان", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338387341" },
            new { Id = 568, Name = "أساسيات المحاسبة المالية", Price = 300m, Stock = 10, Description = "“أساسيات المحاسبة المالية” هو دليلك العملي لفهم المحاسبة من البداية وحتى إعداد القوائم المالية بثقة. يقدم الكتاب محتوى متكاملاً لكل من يسعى إلى بناء أساس راسخ ومنهجي في المحاسبة، بدءًا من مبادئها الأولى ووصولًا إلى التطبيقات العملية المتقدمة.\n\nيعتمد الكتاب على شرح تفصيلي مبسط مدعّم بالأمثلة والتمارين، ليكون مرجعًا موثوقًا للطلاب، وحديثي التخرج، والمحاسبين المبتدئين، وكذلك المهنيين الراغبين في تطوير معرفتهم. ويتميز بأسلوب تطبيقي يغطّي مختلف المعالجات المحاسبية، إلى جانب تبسيط أهم النسب والمؤشرات المالية المستخدمة في التحليل.", CategoryId = 8, ImageUrl = "/images/products/9786338387358.webp", Author = "هالة عبدالله", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338387358" },
            new { Id = 569, Name = "خارج حدود الصمت", Price = 150m, Stock = 10, Description = "كل شيء يبدأ بالصمت…\n\nثم يتحول الصمت إلى صوت،\n\nوالصوت إلى صراعٍ ينهش الداخل حتى لا يبقى سوى الرماد. في هذا العالم، لا فرق بين الصراخ والصمت،\n\nفكلاهما وجهٌ لذات العذاب.\n\nالوجوه تتشقق، الحقيقة تنزف،\n\nوالعقل ينسج خيوطه حول الفقد كبيتٍ للعنكبوت.\n\nهنا، يُمحى الخط الفاصل بين الحلم والجحيم،\n\nوتنقلب المرايا على أصحابها.\n\nلا تبحث عن الضوء… فكل خطوةٍ نحوه\n\nقد تكون بداية للاحتراق.لا قوانين هنا،\n\nولا منطق يحكم ما هو آتٍ، كل شيء يخرج عن السيطرة،\n\nخارج الإدراك ، خارج الحقيقة…\n\nخارج حدود الصمت", CategoryId = 1, ImageUrl = "/images/products/9786338387365.webp", Author = "حسين العربى", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338387365" },
            new { Id = 570, Name = "دم الظلال حين تستيقظ الظلال", Price = 150m, Stock = 10, Description = "رواية حين تستيقظ الظلال هي الجزء الثاني المكمل لرواية حين تنطفئ الظلال، وهي عمل من تقاليد الرعب النفسي والتشويق الغامض، ليدمجها مع حبكة عائلية مأساوية تحوّل البيت القديم وقصر العائلة إلى مسرح للدم، اللعنات، والأسرار المدفونة.", CategoryId = 1, ImageUrl = "/images/products/9786338387372.webp", Author = "علاء سرحان", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338387372" },
            new { Id = 571, Name = "ظلال الروح", Price = 120m, Stock = 10, Description = "«ظلال الروح»\nحكايةُ رجلٍ ظنّ أن الحبَّ وحده يكفي،\nوامرأةٍ خافت أن تُسلّم قلبها قبل أن تطمئن،\nوحكايةُ طريقٍ بين القاهرة وقِنا،\nبين الانفتاح والجذور،\nبين الرغبة في الطيران\nوالخوف من كسر الجناحين.\nهي ليست قصة حبٍ فقط،\nبل شهادةٌ على أن بعض العلاقات\nلا تنهار بسبب الكره،\nبل بسبب الخوف…\nوحين يخاف القلب،\nتظهر ظلالُ الروح.", CategoryId = 1, ImageUrl = "/images/products/9786338387396.webp", Author = "عبدالعاطى إسماعيل", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338387396" },
            new { Id = 572, Name = "وعد لندن", Price = 250m, Stock = 10, Description = "مجموعة شباب وبنات من عائلة واحده ينتقلون لبلدة أخرى غربيه لأستكمال دراستهم ودخول الجامعه حيث أنه تم قبولهم بمنحه مجاني، و بنصف العالم الدراسي تقترح واحده منهم أن يذهبوا لرحله استكشافيه لبلده قريبه منهم والطريقه الوحيده للذهاب إليها هو القطار ليقع بيهم الحال هم ومن معهم بالقطار المرور عبر بوابه خفيه تنقلهم من زمنهم لزمن أخر ومن هنا تبدأ الصعاب وأستكشاف المكان لتقع الكارثه عليهم بعدما علموا أنهم عادوا بالزمن للعصر الفكتوري وكلما حاولوا العوده تذهب محاولاتهم سدى فيقرروا التأقلم على الوضع والتكيف.", CategoryId = 1, ImageUrl = "/images/products/9786338387402.webp", Author = "دنيا صابر", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338387402" },
            new { Id = 573, Name = "نشوة الأعالى", Price = 130m, Stock = 10, Description = "ببساطة ستجد في العمل البسيط هذا ما يلي:\n1. مائة كتاب، كانوا رفاقي في رحلتي، ولو أن جهلي الشديد لن ينتهي.\nربما يقودك أحدهم إلي فكرة، أو يُرشدك إلي رؤية جديدة.\n2. مائة مقطوعة موسيقية، يَكفي أن أُخبرَك أنها كانت إحدي وسائِلي لِبلوغِ ما لم أكن أتَصَوّر وجوده، ولكَ أن تَتَجاوزها إن لم تكن تروق لك.\n3. مائة رسالة قصيرة. لأكونَ صادقًا معك، هي رسائل كنت أتمني لو أرسلها لي أحد، فَكتبتُها بِنفسي، لِنفسي، ووددت مشاركتها معك، ربما نلتقي من خلالها فيها .\n4. ووضعت لك ثلاثمائة سؤال. الأسئلة هي المعبر بين ما نعرف وما نجهل، ربما لا أعرف معظم الإجابات، لكن مجرد وجود السؤال اللائق، بمثابة فرصة للكشف عن الإجابة في الوقت المناسب .( الإجابات الصادقة قد تُعيدُ صِياغةَ حياتِك.", CategoryId = 8, ImageUrl = "/images/products/9786338387426.webp", Author = "أحمد مرجان", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338387426" },
            new { Id = 574, Name = "ساردار", Price = 130m, Stock = 10, Description = "خرج من باطن البحر صوت عميق ينادي باسم حمزة!، التفت حمزة حوله في حيرة يبحث عن مصدر الصوت ظن أنها دعابة سخيفة من أحد أصدقائه لكنه لم يجد أحد سواه هو ونور، عاد الصوت مناديا مرة أخرى بصوت أكثر عمقا جعل كل من حمزة ونور ينتفضان\n– أن أردت معرفة الحقيقة اقرأ هذه الرسالة!", CategoryId = 1, ImageUrl = "/images/products/9786338387433.webp", Author = "سمر سعيد", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338387433" },
            new { Id = 575, Name = "ومن أحياها (بطولات و انسانيات )", Price = 130m, Stock = 10, Description = "حكايات من سيارة إسعاف، الجزء الثاني (و من أحياها، بطولات، وإنسانيات)\nمجموعة من القصص الحقيقية (29 قصة) التي قابلها العديد من زملائي أثناء عملهم بالإسعاف المصري (البطولات).. و قصص أخري كنت شاهد عيان علي تفاصيلها (الإنسانيات).. في الجزء الأخير أروي قصتين لشخصين قريبين مني..", CategoryId = 1, ImageUrl = "/images/products/9786338387440.webp", Author = "أحمد هيبة", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338387440" },
            new { Id = 576, Name = "جيلا", Price = 120m, Stock = 10, Description = "رواية «جيلا» للكاتب عبدالعليم مبارك، والتى تسلط الضوء على قضايا إنسانية واجتماعية معاصرة. وتدور أحداث الرواية حول فتاة تنجرف إلى علاقة عاطفية مع شاب تعرّفت عليه عبر مواقع التواصل الاجتماعى، قبل أن تكتشف لاحقًا أنها وقعت فى أزمة كبيرة قلبت حياتها رأسًا على عقب. كما تتناول الرواية قصة امرأة مسنّة تستعرض سلسلة من الكوارث التى طالت أفرادًا من عائلتها نتيجة هذا النوع من العلاقات، إلى جانب تقديم نماذج وتجارب مختلفة لنساء مررن بظروف مشابهة من خلال إطار جمعية اجتماعية.", CategoryId = 1, ImageUrl = "/images/products/9786338387464.webp", Author = "عبدالعليم مبارك", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338387464" },
            new { Id = 577, Name = "ألم السوسة", Price = 50m, Stock = 10, Description = "تدور أحداث قصة «ألم السوسة» حول طفل يحب الحلويات كثيرًا ويهمل تنظيف أسنانه، غير مدركٍ للخطر الصغير الذي يختبئ بينها. ومع مرور الأيام، تبدأ السوسة في إلحاق الأذى بأسنانه، فيشعر بالألم ويتعلم درسًا مهمًا لن ينساه. تأخذنا القصة في رحلة ممتعة ومفيدة، نكتشف من خلالها أهمية النظافة الشخصية، والالتزام بنصائح الوالدين، والعناية بالأسنان للحفاظ على صحتها وجمالها. قصة تربوية مشوقة، بأسلوب بسيط ورسالة هادفة، تساعد الأطفال على فهم العادات الصحيحة بأسلوب ممتع وقريب إلى قلوبهم.", CategoryId = 11, ImageUrl = "/images/products/9786338387471.webp", Author = "شيماء أبو الجمايل حجازى", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338387471" },
            new { Id = 578, Name = "الأرنب و السلحفاة", Price = 50m, Stock = 10, Description = "تحكي قصة «الأرنب والسلحفاة» حكاية جميلة عن التعاون والاجتهاد، من خلال سلحفاة نشيطة لا تعرف الكسل، وأرنب يفضل الراحة والنوم على العمل. عندما تواجههما أزمة حقيقية، تثبت السلحفاة أن الجدّ والصبر هما طريق النجاح، وأن من يعمل بجد يحصد ثمرة تعبه. تكشف القصة للأطفال خطورة الكسل، وأهمية التعاون واحترام جهد الآخرين، وأن العمل المشترك هو السبيل لتجاوز الصعوبات. قصة ممتعة تحمل في طياتها درسًا أخلاقيًا مهمًا، تُقدَّم بأسلوب بسيط يساعد الطفل على الفهم ويغرس القيم الإيجابية في نفسه.", CategoryId = 11, ImageUrl = "/images/products/9786338387518.webp", Author = "شيماء أبو الجمايل حجازى", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338387518" },
            new { Id = 579, Name = "الضفدع لولو الذكى", Price = 50m, Stock = 10, Description = "تحكي قصة «الضفدع لولو الذكي» حكاية ضفدع محبّ للقراءة والمعرفة، يستخدم علمه وذكاءه لحماية أصدقائه من خطرٍ يهدد حياتهم. حين تشتد حرارة الشمس ويقترب الجفاف، يدرك لولو ما سيحدث قبل الآخرين، فيبادر بجمعهم ويقودهم للتعاون والعمل المشترك. تعلّمنا القصة أن العلم نور، وأن التفكير السليم والتخطيط الجيد قادران على إنقاذ الجميع، وأن التعاون والاتحاد يصنعان المعجزات. قصة شيّقة مليئة بالقيم الإيجابية، تُنمّي لدى الطفل حب القراءة، وروح المسؤولية، وأهمية العمل الجماعي في مواجهة الأزمات.", CategoryId = 11, ImageUrl = "/images/products/9786338387525.webp", Author = "شيماء أبو الجمايل حجازى", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338387525" },
            new { Id = 580, Name = "الكود السرى لجوجل", Price = 550m, Stock = 10, Description = "رحلة إلى قلب جوجل... حيث تُصنع القمم!\n​تخيّل أنك تملك مفتاحًا ذهبيًا يفتح لك أبواب الصفحة الأولى في جوجل...\nمفتاحًا يسمح لك بالظهور أمام آلاف العملاء في اللحظة التي يبحثون فيها عنك...\nمفتاحًا يجمع بين قوة الإعلانات السريعة وذكاء الظهور المجاني الدائم.\n​في هذا الكتاب، ستدخل معنا إلى غرفة التحكم السرية لجوجل...\nحيث سنكشف لك كيف تعمل خوارزمياته، وكيف تستغلها لصالحك قبل أن يفعل منافسوك.\nستتعلم كيف تطلق حملات إعلانية تخطف الانتباه، وكيف تبني أساسًا صلبًا يجعل جوجل يضعك في القمة... ويبقيك هناك.\n​هنا لن تجد نظريات مملة، بل خططًا عملية وأسرارًا مجربة، لتبدأ رحلتك من الصفر وصولاً إلى الهيمنة على نتائج البحث.\n​🔑 هذه ليست مجرد صفحات... إنها بوابتك لعالم جديد من القوة الرقمية.", CategoryId = 5, ImageUrl = "/images/products/9786338387587.webp", Author = "محمد مندور", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338387587" },
            new { Id = 581, Name = "قوانين المسوق الأعظم", Price = 2000m, Stock = 10, Description = "هل تملك الجرأة لتصبح المسوّق الأعظم؟\nداخل هذا الكتاب تكمن الأسرار التي لا يعرفها سوى القليلون...\n100 قانون، كل واحد منها مفتاح لفهم العملاء، صناعة الثقة، وإطلاق الإبداع الذي يجعل رسالتك لا تُنسى.\nكل اقتباس ليس مجرد نص، بل سلاح سري:\n• يقنع قبل أن يُقرأ،\n• يبني ولاءً قبل أن يُطلب،\n• ويحوّل فكرة صغيرة إلى قصة يرويها الجميع.\nهذا الكتاب هو بوابتك لعالم الإقناع الحقيقي، حيث يصبح الذكاء العاطفي والإبداع أدوات قوة لا يُقاوم لها.\nافتحه، وابدأ رحلة لاكتشاف المسوّق الأعظم الذي بداخلك.", CategoryId = 5, ImageUrl = "/images/products/9786338387594.webp", Author = "محمد مندور", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338387594" },
            new { Id = 582, Name = "الذكاء التسويقى دليلك للهيمنة الرقمية", Price = 450m, Stock = 10, Description = "في عالمٍ تتحكم فيه الخوارزميات، وتُقاس فيه القيمة بالبيانات، لم يعد التسويق مجرد أداة دعائية، بل أصبح ذكاءً استراتيجيًا يُحدد من يربح السوق ومن يختفي من المشهد.\nنحن لا نعيش ثورة رقمية فقط؛ نحن نعيش عصر الهيمنة الذكية، حيث لا يكفي أن تصل إلى جمهورك — بل يجب أن تفهمه، وتتنبأ بحركته، وتقدّم له الحل قبل أن يشعر بالحاجة إليه.\nمن هنا وُلد هذا الكتاب:\n\"الذكاء التسويقي: دليلك للهيمنة الرقمية\"،\nليكون أكثر من مجرد مرجع، بل نظام تفكير جديد لمن أراد أن يصعد إلى القمة في عالم لا يرحم المتأخرين.\nستأخذك صفحات هذا الكتاب في رحلة عميقة تبدأ من فهم أساسيات التسويق الرقمي، وتمتد إلى أدوات الذكاء الاصطناعي، واستراتيجيات بناء العلامات التجارية، مرورًا بتحليل السلوك، وتخصيص الرسائل، وحتى قيادة حملات تسويقية تنبؤية قائمة على البيانات.\nإنه ليس كتابًا نظريًا، ولا سردًا أكاديميًا جافًا؛ بل هو خارطة طريق عملية، كُتبت بلغة السوق، وعقليّة من يفكّر كقائد رقمي، لا كمجرّد مسوّق.\nإذا كنت تبحث عن التميز في سوق مزدحم، وعن صوت مسموع في عالم صاخب، وعن سيطرة حقيقية على أدوات العصر،\nفهذا الكتاب ليس مجرد اختيار... بل ضرورة.", CategoryId = 5, ImageUrl = "/images/products/9786338387600.webp", Author = "محمد مندور", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338387600" },
            new { Id = 583, Name = "النسيان", Price = 250m, Stock = 10, Description = "هناك أسرار يجب أن تُدفن… وهناك أسرار يُقتل من يقترب منها.\n\nكل شيء بدأ بمعلومة صغيرة…\nملف قديم لا يجب أن يكون موجودًا.\n\nلكن عندما يفتح ياسين هذا الملف، يكتشف أن الحقيقة التي يبحث عنها لم تختفِ…\n\nبل تم محوها عمدًا.\n\nأسماء اختفت من السجلات. حوادث بلا شهود. وأشخاص يتذكرون أشياء… لم تحدث أبدًا.\n\nكل خيط يقوده إلى شبكة من الأسرار تعمل في الظل منذ سنوات. شبكة قادرة على فعل شيء أخطر من القتل…\n\nقادرة على محو الحقيقة نفسها.", CategoryId = 1, ImageUrl = "/images/products/9786338387617.webp", Author = "محمد مندور", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338387617" },
            new { Id = 584, Name = "OBLivion", Price = 250m, Stock = 10, Description = "What if your entire life... was a sentence written by someone else?\n\nIn a modern Arab city veiled in silence and secrets, former intelligence officer Yassin stumbles upon a manuscript that was never meant to be found.\n\nA forgotten narrative, buried beneath politics and fiction, threatens to unravel not just governments — but reality itself.\n\nAs Yassin digs deeper, he uncovers fragments of a forbidden story: “The First Text” — a mythical document rumored to contain a truth so powerful, it could erase identities, rewrite memory, and dismantle the very concept of history.\n\nWith every chapter, the line between fact and fiction fades.\n\nA mysterious narrator haunts the shadows.\nA woman with eyes full of memory holds the final key.\n\nAnd time begins to collapse... from within the narrative itself.\n\nOblivion is a mind-bending thriller — where espionage meets philosophy, romance dances with danger, and the ultimate conspiracy is not political... but existential.\n\nAre you reading the story?\n\nOr is the story... reading you?", CategoryId = 1, ImageUrl = "/images/products/9786338387624.webp", Author = "mohamed mandour", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338387624" },
            new { Id = 585, Name = "ظل القمر الأسود عهد الدم والرماد", Price = 250m, Stock = 10, Description = "حين يشتبك الحبر بالدم… وتتحول الكلمات إلى معارك لا تقل ضراوة عن الحروب، تبدأ حكاية ظل القمر الأسود.\n\nفي عالمٍ تتداخل فيه الأسرار مع المصير، وتتحرك فيه الخيوط الخفية خلف الأحداث، ينفتح الباب أمام رحلة مشتعلة بالصراع بين الحقيقة والوهم، وبين القوة والقدر. هناك حيث لا تُروى الحكايات فقط… بل تُكتب بدماء أصحابها.\n\n“ظل القمر الأسود – عهد الدم والرماد“ ليست مجرد رواية، بل ملحمة نفسية وإنسانية تكشف عالماً تتصارع فيه النفوس قبل السيوف، وتصبح فيه الكلمة أخطر من الرصاص.\n\nفي كل فصل يزداد الظل عمقاً… وفي كل صفحة يقترب القارئ أكثر من الحقيقة التي قد تغيّر كل شيء.\n\nهل أنت مستعد للدخول إلى العالم الذي لا يخرج منه أحد كما كان؟", CategoryId = 1, ImageUrl = "/images/products/9786338387631.webp", Author = "محمد مندور", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338387631" },
            new { Id = 586, Name = "ملف العميل 17", Price = 200m, Stock = 10, Description = "بعض الملفات لا يجب أن تُفتح…\nوفي عالم الاستخبارات، هناك قاعدة غير مكتوبة:\nإذا اختفى الملف… فهناك من أراد للحقيقة أن تختفي معه.\nعندما يظهر فجأة ملف قديم يحمل الرمز C17، يكتشف بطل الرواية أن الأمر ليس مجرد وثيقة منسية في أرشيف سري.\nبل بداية طريق يقوده إلى شبكة من الأسرار التي دُفنت بعناية… وأشخاص مستعدون لفعل أي شيء حتى تبقى مدفونة.\nكل صفحة من الملف تكشف حقيقة أخطر من السابقة. أسماء لم يكن يجب أن تُذكر. عمليات لم تُسجل رسميًا.\nوأحداث… لم يُسمح للعالم أن يعرف بوقوعها.\nلكن المشكلة الحقيقية ليست في محتوى الملف.\nالمشكلة أن كل من اقترب من الحقيقة قبله… اختفى.\nوالآن أصبح هو التالي في القائمة.\nبين المطاردة، والخداع، والذكريات التي لا يمكن الوثوق بها، يجد نفسه أمام سؤال واحد:\nهل الحقيقة تستحق أن تموت من أجلها؟\n«ملف العميل 17»\nرواية تشويقية استخباراتية مشحونة بالغموض، تكشف عالم الظلال حيث لا شيء كما يبدو… وحيث قد يكون أخطر سلاح في العالم هو المعلومة.", CategoryId = 1, ImageUrl = "/images/products/9786338387655.webp", Author = "محمد مندور", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338387655" },
            new { Id = 587, Name = "فلورا في حديقة الأفكار", Price = 50m, Stock = 10, Description = "ظن عبدول أن الحقيقة واحدة،\nحتى علمته القطة فلورا أن القلوب ترى بعيون مختلفة.\nكان عبدول واثقًا من رأيه،\nلكن فلورا همست له: ليس كل ما نراه، يراه الآخرون كما نراه!\nفي عالم صغير، تعلم كتكوت عجوز\nأن الاختلاف ليس خصومة… بل حكاية أخرى.\nحكاية تروى للصغار،\nتمنحهم كلمات لمشاعرهم،\nوتزرع في قلوبهم بذور التفهم،\nبينما يجد الكبار فيها بداية حوار دافئ معهم.\nقصة بسيطة في شكلها،\nعميقة في أثرها،\nتبقى معانيها أطول مما تبقى الصفحات!", CategoryId = 11, ImageUrl = "/images/products/9786338387662.webp", Author = "نهلة الناقة", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338387662" },
            new { Id = 588, Name = "أنوار", Price = 400m, Stock = 10, Description = "ذكريات الماضي إلى حدٍ ما تشبه فيلمًا قديمًا فقد ألوانه، ورغم ذلك لا نزال نحفظه ونشتاقه.\nنشتاق أنفسنا، بيتنا، ومن كان معنا فيها.\nوفي مقطعٍ آخر مهملٍ منها، نجد أنفسنا نشتاق إحساسًا فقدناه مع الكبر.\nإحساس كان حقًّا مستحقًّا للصغار فقط، ومن ثم\nصفعتنا الحقيقة المُرة للكبر… فلم يعد مباح.", CategoryId = 1, ImageUrl = "/images/products/9786338387679.webp", Author = "بدور السالم", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338387679" },
            new { Id = 589, Name = "خلطبيطة بالصلصة", Price = 150m, Stock = 10, Description = "ترددت كثيرا أن أكتب هذا الكتاب وأضع خواطرى على الورق ولكن ما شجعنى بعض الشيء أننى كتبت على صفحات التواصل الاجتماعى فوجدت استحسان لا بأس به فقررت أن أجمع ما كتبت فى كتاب واحد لعلى أستطيع أن أرى حجم التجربة واضحا أمامى وعلى الله النتائج والنجاح. ويعود الغرض لكتابة هذا الكتاب إلى أسباب عديدة أولا الكتابة فى حد ذاتها تعد متعة لا توصف وتفريغ لكل الطاقات السلبية والإيجابية داخل الإنسان على الورق والغرض الثانى من هذا الكتاب يعتبر أهم وأخطر الأهداف وهو إقامة الحجة على نفسك. فعندما تريد أن تتصف بصفات أو تطبيق أخلاقيات فبلغها للآخرين فهذا يدفعك إلى التمسك بها وإقامة الحجة على نفسك فيدفعك لتطبيقها. لكنى أعترف أيضا أن هذا الأمر قد لا يكون\nصحيحا فى بعض الأحيان لأن هناك أناس غلبها الشيطان فتكره الخير للناس وتبدأ فى إحباطك والتقليل من شأن ما تعمل فيجب عليك أن تكون مستعدا لهذا ولا تلقي له بالا وأن تبدأ بالأشخاص الإيجابيين الذين يدفعونك للأمام بحب صادق ونية صافية كما أن هناك مقوله رائعة تقول : قل لى وسوف أنسى…. أرنى ربما أتذكر ….. أش ركنى ولن أنس ى للأبد. فإذا أردت أن تتعلم شيئا وتجعله طبعا فيك فأخبره للأخرين وطبقه فيصبح جزءا لا يتجزأ منك وأما الغرض الأخير فهو محاولة صغيرة منى للإسهام فى رفعة\nالأمة والوطن والنصح لدين الله وابتغاء مرضاته. والكتاب عبارة عن خواطرى فى كل شيء وفى كل اتجاه بدءا من الدين والثقافة والرياضة والفن … والعياذ بالله السياسة وأهلها ربنا يجعل كلامنا خفيف عليهم. ولأن طبيعة الناس الآن سريعة الملل فسوف أحاول أن أق ول ما أريد فى جمل سريعة وبسيطة وجمل قليلة. ولهذا سميت الكتاب بإسم خلطبيطة بالصلصة لأنه يشمل الحديث فى كل المجالات تقريبا وبعد التأكد من صدق المعلومات من مصادرها. ويجب أن يعلم الجميع أن محور كتابى يتلخص فى جملة واحدة هى الصلاح لى ولأمتى وفقنا الله لما يحب ويرضى.", CategoryId = 8, ImageUrl = "/images/products/9786338387754.webp", Author = "أحمد سلامة", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338387754" },
            new { Id = 590, Name = "ماذا بعد", Price = 130m, Stock = 10, Description = "ماذا بعد\nوماذا بعد أن رحلنا\nورسمنا آمالنا\nوماذا بعد أن سرق\nباردُ الليل نبضَ ليالينا\nحتى توارى الليلُ تساؤلَنا\nلِمَ عادت تسألينا\nيا ليلُ الصمتِ مجازينا\nوقد سكنّا متاهاتِ أرواحِنا\nفلتهمسي برفقٍ كيف تنبضُ\nوكيف الليلُ يهدي الحائرينا", CategoryId = 8, ImageUrl = "/images/products/9786338387761.webp", Author = "عبدالنبى خطاب", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338387761" },
            new { Id = 591, Name = "العقلية تكسب", Price = 400m, Stock = 10, Description = "عارف ال social media news feed ؟\nالمحتوى اللي بيظهرلك كتير ده بيظهر لك ليه؟\nعلشان بتقف عليه بإستمرار .. بتهتم به .. بتتفاعل معاه .. بتتكلم عنه .. بتشاركه\n\nاهو دي دماغك بالظبط .. اللي بتقف عليه .. بتتكلم فيه .. بتشاركه .. بتقوله .. بتديلك منه كتير\n\nوانت اختار .. أي نوع محتوى تحب news feed دماغك تطلع لك منه كتير؟\n\nكلمة mindset بقت تستخد كتير في زماننا وبقينا نقولها كتير, وحتى زعلنا من محمد صلاح لما قال المينتاليتي.", CategoryId = 5, ImageUrl = "/images/products/9786338387778.webp", Author = "أحمد عوارة", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338387778" },
            new { Id = 592, Name = "التخطيط الأستراتيجي والتحول الرقمي", Price = 300m, Stock = 10, Description = "يسعى الكتاب إلى استكشاف كيف يمكن للذكاء الاصطناعي أن يعيد تشكيل فهمنا للنماذج الإدارية، ويمنحها بعدًا جديدًا أكثر مرونة وواقعية من خلال:\n• تقديم منظورًا جديدًا يجمع بين الفكر الإداري الكلاسيكي والتكنولوجيا الحديثة.\n• مناقشة نموذجًا عمليًا للتخطيط الأستراتيجي (نموذج فايفر) ويعيد تحليله في ضوء أدوات الذكاء الاصطناعي.\n• الربط بين النظرية والتطبيق من خلال حالات دراسية واقعية .\n• مخاطبة الباحثين والمهنيين في مجالات الإدارة، والتخطيط، والتحول الرقمي، ويمنحهم أدوات تحليلية جديدة.", CategoryId = 8, ImageUrl = "/images/products/9786338387785.webp", Author = "نرمين سمير بيومي", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338387785" },
            new { Id = 593, Name = "رحلة إيلارا", Price = 150m, Stock = 10, Description = "“منذ مئات السنين، كانت سولارا آخر مدينة للنور. في قلبها، كان يقبع “محراب الشمس”، حيث خُزنت شظية من روح الشمس نفسها.\nلكن الطمع دمر كل شيء… أحد الحراس خاننا وفتح البوابة للظلال. القتال استمر أيامًا، حتى أُطفئ آخر نور، وسقطت الشمس”.", CategoryId = 1, ImageUrl = "/images/products/9786338387792.webp", Author = "علياء احمد", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338387792" },
            new { Id = 594, Name = "خلطبيطة بالصلصة الجزء التاني", Price = 150m, Stock = 10, Description = "\"ترددت كثيرا أن أكتب هذا الكتاب وأضع خواطرى على الورق ولكن ما شجعنى بعض الشيء أننى كتبت على صفحات التواصل الاجتماعى فوجدت استحسان لا بأس به فقررت أن أجمع ما كتبت فى كتاب واحد لعلى أستطيع أن أرى حجم التجربة واضحا أمامى وعلى الله النتائج والنجاح. ويعود الغرض لكتابة هذا الكتاب إلى أسباب عديدة أولا الكتابة فى حد ذاتها تعد متعة لا توصف وتفريغ لكل الطاقات السلبية والإيجابية داخل الإنسان على الورق والغرض الثانى من هذا الكتاب يعتبر أهم وأخطر الأهداف وهو إقامة الحجة على نفسك. فعندما تريد أن تتصف بصفات أو تطبيق أخلاقيات فبلغها للآخرين فهذا يدفعك إلى التمسك بها وإقامة الحجة على نفسك فيدفعك لتطبيقها. لكنى أعترف أيضا أن هذا الأمر قد لا يكون\nصحيحا فى بعض الأحيان لأن هناك أناس غلبها الشيطان فتكره الخير للناس وتبدأ فى إحباطك والتقليل من شأن ما تعمل فيجب عليك أن تكون مستعدا لهذا ولا تلقي له بالا وأن تبدأ بالأشخاص الإيجابيين الذين يدفعونك للأمام بحب صادق ونية صافية كما أن هناك مقوله رائعة تقول : قل لى وسوف أنسى…. أرنى ربما أتذكر ….. أش ركنى ولن أنس ى للأبد. فإذا أردت أن تتعلم شيئا وتجعله طبعا فيك فأخبره للأخرين وطبقه فيصبح جزءا لا يتجزأ منك وأما الغرض الأخير فهو محاولة صغيرة منى للإسهام فى رفعة\nالأمة والوطن والنصح لدين الله وابتغاء مرضاته. والكتاب عبارة عن خواطرى فى كل شيء وفى كل اتجاه بدءا من الدين والثقافة والرياضة والفن … والعياذ بالله السياسة وأهلها ربنا يجعل كلامنا خفيف عليهم. ولأن طبيعة الناس الآن سريعة الملل فسوف أحاول أن أق ول ما أريد فى جمل سريعة وبسيطة وجمل قليلة. ولهذا سميت الكتاب بإسم خلطبيطة بالصلصة لأنه يشمل الحديث فى كل المجالات تقريبا وبعد التأكد من صدق المعلومات من مصادرها. ويجب أن يعلم الجميع أن محور كتابى يتلخص فى جملة واحدة هى الصلاح لى ولأمتى وفقنا الله لما يحب ويرضى.\"", CategoryId = 8, ImageUrl = "/images/products/9786338387815.webp", Author = "أحمد سلامة", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338387815" },
            new { Id = 595, Name = "مستنقع الحرية", Price = 130m, Stock = 10, Description = "حين يصبح الشغف خبزًا،\nوتتحول اللعبة إلى مسرحية هزلية،\nيجد سليم نفسه في عالمٍ أبيض غارق في الطين…\nباحثًا عن حرية قد لا تكون موجودة.", CategoryId = 1, ImageUrl = "/images/products/9786338387822.webp", Author = "أحمد فارس", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338387822" },
            new { Id = 596, Name = "ضوء في نهاية الممر", Price = 150m, Stock = 10, Description = "أربعة فتيان خرجوا ليلاً، ولم يعودوا كما كانوا،\nفي صيف 1936، لم تكن فلسـطين مسرحاً هادئًا، بل أرضاً يُختبر عليها معنى الرجولة قبل أوانها، كانوا يحملون بنادق أقدم بعقود من أعمارهم، وأحلاماً أثقل من أجسادهم، ويعرفون جيداً أن الطريق الذي اختاروه، لا عودة منه.\nرواية عن المعارك و عن الصداقة حين تُختبر بالدم، وعن الحب الذي يلمع في لحظة احتضار.\nوعن الأب الذي يعطي ابنه المال وهو يعرف أنه ربما يشتري به موته، نحكي عن الثورة قبل أن تصبح شعاراً،\nعن الفتى الذي يدخل الممر وهو لا يعرف إن كان سيخرج منه حيّاً، و إن كان الضوء في نهايته خلاصاً، أم وداعاً.\nلا أبطال خارقين هنا، بل بشر يرتجفون، يترددون، يخطئون،\nثم ينهضون لأن السقوط لم يعد خياراً.", CategoryId = 1, ImageUrl = "/images/products/9786338387860.webp", Author = "أشرف سيد قطب", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338387860" },
            new { Id = 597, Name = "حين تصمت الصحراء", Price = 130m, Stock = 10, Description = "بينما استمروا في استكشاف الغرفة، وجدوا قطعة معدنية قديمة منقوشة عليها اسم مدينة قديمة كانت مزدهرة قرب البئر، مدينة ربطت بين القبائل كجسر للتواصل والسلام. قال الشيخ الذي حضر معهم ليشارك في هذا الاكتشاف: “هذه المدينة لم تكن مجرد مدينة. كانت فكرة. كانت تعني أننا كنا أمة واحدة.” توقف للحظة ثم أضاف بحزن: “ولكنها دمرت كما دمرنا نحن.”", CategoryId = 1, ImageUrl = "/images/products/9786338387877.webp", Author = "حسن شوتى", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338387877" },
            new { Id = 598, Name = "قصة الفتاة ذات الشعر النارى", Price = 50m, Stock = 10, Description = "صعدت ريمي المنصة بخطوات ثابتة، شعرها يتلألأ تحت الأضواء، وابتسامتها تخبر الجميع أن الخرافات قد ماتت إلى الأبد.”\nاسم المؤلف: أدهم وليد عبد الرحيم", CategoryId = 11, ImageUrl = "/images/products/9786338387891.webp", Author = "أدهم وليد", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338387891" },
            new { Id = 599, Name = "إلينورا", Price = 150m, Stock = 10, Description = "وأدركت أنني لن أشفى.\n\nليس منها فقط، بل من كل شيء.\n\nمن فقدي الأول من غيابي في كل صور العائلة، من شعور الطفل الذي بحث عن ذراع أمه ولم يجدها.\n\nأريد التعلق.... حتى وإن كان هذا سيحطمني.\n\nأنا لست قويًا، ولا ناضجا، ولا متزنا .... أنا هش، هش جدا ، أكثر مما يسمح لي هذا العالم بأن أكون.\n\nوالتعلق بي ليس حبا ....\n\nبل إنقاذ .... ولا أحد ينقذ أحدًا في هذا الزمن.", CategoryId = 1, ImageUrl = "/images/products/9786338387907.webp", Author = "فوزى سعيد", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338387907" },
            new { Id = 600, Name = "وكز الماضى", Price = 130m, Stock = 10, Description = "ليس الماضي ما يؤلمنا… بل تلك الوكزة الخفيفة التي يرسلها حين نظن أننا تعافينا.\n“وكز الماضي” حكاية عن جروح ظنناها نامت، فإذا بها تستيقظ عند أول ذكرى، وأول اسم، وأول مواجهة مع أنفسنا.\nرواية تغوص في أعماق النفس، حيث لا يكون الألم صاخبًا، بل صامتًا… أقسى، وأصدق.", CategoryId = 1, ImageUrl = "/images/products/9786338387914.webp", Author = "سارة سامى", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338387914" },
            new { Id = 601, Name = "حتى إذا بلغ الأربعين", Price = 150m, Stock = 10, Description = "يرافق كتاب حتى إذا بلغ الأربعين القارئ في لحظة فارقة من حياته. لحظة التوقف للمراجعة وإعادة ترتيب الذات. يفتح الكتاب أسئلة العمر والمعنى والمسؤولية. ويحول سن الأربعين من هاجس أو أزمة إلى بداية نضج وانطلاق جديد. موجها رسالته لكل من بلغ الأربعين. أو يقترب منها. أو مر بها دون أن يدرك قيمتها. ليجعل منها محطة وعي وحكمة لا محطة خوف أو انكسار.", CategoryId = 5, ImageUrl = "/images/products/9786338387921.webp", Author = "فتحى عبدالحميد", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338387921" },
            new { Id = 602, Name = "التغطية المستمرة", Price = 150m, Stock = 10, Description = "التغطية مستمرة ليست حكاية من الماضي، بل تاريخٌ ممتدّ كالجراح المفتوحة في درّة تاج المسلمين.\nهذا العمل لا يروي قصة، بل يكشف حقيقة؛ حقيقة كُتبت بدماء الصغار قبل الكبار، وحاولت قوى الظلام طمسها، لكنها بقيت حيّة.\nمنذ أول صرخة حق، والأرض التي لا تعرف الانكسار تشهد مقاومة لا تهدأ، وذاكرة لا تموت.\nالتغطية مستمرة… لأن الحق لا يُدفن، ولأن التاريخ لا ينسى، ولأن هناك من لا يزال واقفًا ليقول:\nهنا كنّا… وهنا سنبقى.", CategoryId = 7, ImageUrl = "/images/products/9786338387952.webp", Author = "رضا الشريف", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338387952" },
            new { Id = 603, Name = "إلى أمل", Price = 200m, Stock = 10, Description = "إلى أمل .. رواية تدور حول أب يحرم قسراً من أبنته. فيتحول الفقد الى رحلة كشف طويلة. يكتب فيها رسالته كاعتراف ووصية وشهادة. ومن خلال سرده لتفاصيل الحب والزواج والإنجاب ثم الإنهيار. تفضح الرواية كيف يمكن للقوانين القاسية والتخبيب الأسري وفساد الاعلام ان تصنع مأساة إنسانية كاملة. وتشوه الأبوة. وتغتال المعنى. الرواية ليست مجرد حكاية فقد. بل مواجهة مع الحقيقة. وبحث مؤلم عن العدالة. وتمسك بالأمل رغم الغدر والإنكسار.\nإلى أمل .. كتاب يجعلك تعيد النظر فى كل ما كنت تظنه عدلا.\nوتدرك أن بعض القصص لا تنتهى.\nلأن أصحابها ما زالوا ينتظرون الحقيقة.\nإلى أمل .. قد تكون حكاية لم تكتب بعد.\nأو وجعا يشبه وجعك.", CategoryId = 1, ImageUrl = "/images/products/9786338387969.webp", Author = "فتحى عبدالحميد", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338387969" },
            new { Id = 604, Name = "رائحة فكرية", Price = 120m, Stock = 10, Description = "فكرة خرجت عن الصف، فصارت موضع شك.\nصوت حاول أن يفهم قبل أن يُدان، فحُوصِر بالتصنيفات الجاهزة.\nهنا لا تُروى الأحداث بقدر ما تُفكَّك القناعات،\nولا تُقدَّم الحقيقة كاملة، بل تُترك ناقصة عمدًا،\nلأن الاكتمال أحيانًا شكل آخر من أشكال الكذب.\nما بين الخوف من الاختلاف،\nوالجرأة على التفكير،\nتنكشف المسافة الهشة التي يصنعها المجتمع\nحين يقرّر أي الأفكار تستحق الحياة… وأيّها تُقصى بصمت.", CategoryId = 1, ImageUrl = "/images/products/9786338387976.webp", Author = "منه الله مسعود على حسين", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338387976" },
            new { Id = 605, Name = "محاربب لا نتجه الى مكة", Price = 250m, Stock = 10, Description = "شرح هندسي لكيفية تأثير الهندسة القديمة على الإسلام، من تصميم المعابد والابنية على الارض مثل تناظر الاهرامات بالجيزة ونجوم حزام الجبار بالسماء\nوتناظر معبد رمسيس الثاني بالاقصر ونجوم العرش بالسماء\nوتناظر الكعبة المشرفة مع نجوم نعش بالسماء\nلنفهم كيف كان يحدد المسلمون الاوائل اتجاه محاريب مساجدهم اثناء الاتجاه للكعبة، لنجيب اخيرا على السؤال الذي حير علماء المسلمين على مدار 1000 عام وتنازعوا حسب الوثائق في اجابته، وهو: لماذا لا تتجه محاريب مساجد الرسول ومساجد الصحابة ومساجد التابعين إلى مكة؟", CategoryId = 7, ImageUrl = "/images/products/9786338387983.webp", Author = "عمرو عبدالؤوف", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338387983" },
            new { Id = 606, Name = "حروب الصمت", Price = 150m, Stock = 10, Description = "“في حروب الصمت، لا يُقاس الدمار بعدد القذائف،\nبل بعدد الأصوات التي لم تُسمَع،\nوالوجوه التي اختفت،\nوالإنسان الذي تُرك وحيدًا بين الألم واللامبالاة.”\n\nحروب الصمت كتابٌ إنساني يوثّق الحرب لا بوصفها مواجهة عسكرية، بل بوصفها تجربة بشرية يومية قد عشتها ويعيشها كل إنسان في غزّة. يسلّط الضوء على ما يسبق القصف وما يليه: الصمت، الخوف، الفقد، التهجير، الأطفال، الخيام، والجوع، في عالمٍ يراقب بصمت.\nلا يبحث الكتاب عن نصرٍ أو هزيمة، ولا يقدّم خطابًا سياسيًا، بل يحاول إنقاذ الذاكرة من النسيان، وكسر الجدار السميك بين المعاناة واللامبالاة، مؤكدًا أن جوهر الحكاية هو الإنسان.. الإنسان فقط.", CategoryId = 8, ImageUrl = "/images/products/9786338419028.webp", Author = "حسن مقداد", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338419028" },
            new { Id = 607, Name = "شاعر فى الحقيبة", Price = 130m, Stock = 10, Description = "اندفعت لمكائد وإغراءت جعلتنى فريسة سهل الاستحواذ عليها لم اكن جميلة ولم املك ما يؤهلنى حتى اعيش كما أريد العيش ، بل ذبحت عذريتى على معدة خاوية حتى امتلأت ومن هنا هان كل شىء لم أفكر إلا أن يكسا جسدى وتمتلى معدتتى اسكن فى جحر من جحور العشوائيات كما كنت فى حياة القبور", CategoryId = 8, ImageUrl = "/images/products/9786338419035.webp", Author = "الشيماء جمعة", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338419035" },
            new { Id = 608, Name = "الجزء المفقود", Price = 120m, Stock = 10, Description = "تتحدث الرواية عن فتاة فقدت امها، وفتى فقد جدته، والاثنان فقدوا معهم الأمان والحنان، وعند ذهابهم إلى المقبرة لزيارة من فقدوه، ظهر لهم طيفا اخذهم إلى بُعد آخر ، عالم من الإثارة والغموض .", CategoryId = 1, ImageUrl = "/images/products/9786338419042.webp", Author = "جنة اسماعيل", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338419042" },
            new { Id = 609, Name = "بين ليالي الوجع (رحلة مليئة بالأسرار)", Price = 130m, Stock = 10, Description = "\"ثلاثُ حكاياتٍ تتشابكُ كخيوطِ نولٍ واحد، لكلِّ قلبٍ وجعُه الخفيّ، ولكلِّ روحٍ سرٌّ لا يُروى… وبين ماضٍ يأبى الرحيل، وحاضرٍ يفتح أبواب الاحتمالات، تقفُ الأنثى حائرةً: أتحتمي بذاكرتها، أم تُغامرُ بالنجاة؟\"", CategoryId = 1, ImageUrl = "/images/products/9786338419059.webp", Author = "فاتن على راشد طه", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338419059" },
            new { Id = 610, Name = "ثوب عرس وكفن", Price = 130m, Stock = 10, Description = "أنى احتسى الشراب من أجلك.. انا مجروح فى حبك ،أحببتك بصدق من وهلة، وأنت لا تشعرى بى وتستهزئى بمشاعرى، أسافر دائماً حتى لا ارى شبح زوجك بينى وبينك\n-شعورك هذا منك ولا ذنب أنا فيه ، يعلم الله أعيش معك بكل إخلاص.\n- انظرى لم تنطقى كلمة الحب لأنك لا تخبنى سنوات وسنوات وأنا اغتصب حقى منك حتى فى الكلمة ، وأرى جسد ميت ، مشاعر متجمدة كاليل الشتاء الملىء بالثلوج، أشعر ببكاكوأنا اصطنع النوم بجانبك حتى لا تشعرى بى ، وحياتى تحترق.. قلبى يحترق\n- أنت الذى أساءت فى معاملتك وتعاملت معى كجسد مقتول تكثر به من طعناتك وبخناجرك\nالمسمومة لم تمهلنى أن أشفى من جروحي وقد قلت لك من قبل ، قلبى مازال مهموما وحزينا .", CategoryId = 1, ImageUrl = "/images/products/9786338419066.webp", Author = "الشيماء جمعة", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338419066" },
            new { Id = 611, Name = "الحرب الهادئة", Price = 450m, Stock = 10, Description = "ليست كل الحروب تُخاض في ساحات القتال… بعضها يدور في صمتٍ داخل أعماقنا.\nفي \"الحرب الهادئة – كيف تكسب معاركك الداخلية\" يأخذنا الدكتور محمد مندور في رحلة عميقة إلى داخل النفس البشرية، حيث تدور الصراعات الحقيقية: صراع الخوف، والتردد، والشك، وضجيج الأفكار الذي لا يهدأ.\nهذا الكتاب ليس مجرد كلمات تحفيزية، بل دليل عملي لفهم معاركك الداخلية، واكتشاف القوة الكامنة بداخلك، وبناء عقل أكثر هدوءًا ووعيًا وقدرة على اتخاذ القرار.\nستتعلم كيف:\n• تسيطر على أفكارك بدل أن تسيطر عليك\n• تبني صلابة نفسية في مواجهة الضغوط\n• تحول الصراع الداخلي إلى قوة تدفعك للأمام\n\"الحرب الهادئة\" كتاب لكل من يريد أن ينتصر في أهم معركة في حياته… معركة السيطرة على الذات.", CategoryId = 5, ImageUrl = "/images/products/9786338419073.webp", Author = "محمد مندور", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338419073" },
            new { Id = 612, Name = "ممالك القيران", Price = 150m, Stock = 10, Description = "في رأيي أن أشدّ المنتقمين فتكًا هم أولئك الذين حاولوا جاهدين تجنّب خوض المعارك والصدامات، ظنًّا منهم أن ذلك سيمنحهم السلام الذي لطالما سعوا إليه، حتى ولو كان ثمن هذا التجنّب التنازل عن حقوقهم، فقط من أجل أن ينعموا بالسلام ولا شيء غيره. إلا أنهم أدركوا في النهاية أن السلام غاية لا تُدرك ما دمت محاطًا بالبشر؛ فالبشر بارعون جدًا في خلق النزاعات فيما بينهم، وفاشلون جدًا في الحفاظ على السلام، فتحوّلوا إلى منتقمين لا رحمة في قلوبهم، وجعلوا مسعاهم الأول والأخير هو الانتقام ممن سلبهم حقّ السلام.", CategoryId = 1, ImageUrl = "/images/products/9786338419127.webp", Author = "محمد فكرى محمد", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338419127" },
            new { Id = 613, Name = "حين مررت بى", Price = 120m, Stock = 10, Description = "لم تكن مرورًا عابرًا… بل زلزالًا هادئًا أعاد ترتيب القلب.\nهذا ديوانٌ لا يروي قصة حبٍّ مكتملة، بل يفتح دفاتر اللحظة التي يتغيّر فيها الإنسان للأبد: حين يلمس المعنى، ويخسر اليقين، ويولد الشوق في أبسط التفاصيل.\n\nقصائدُه تمشي على حدِّ الشعور؛ بين حضورٍ يُربك، وغيابٍ يُقيم، وبين كلمةٍ قيلت فأنقذت، وأخرى صمتت فكسرت.\nهنا ستجد نفسك قبل أن تجد الشاعر، وستقرأ بعضك وأنت تظن أنك تقرأ عنه.", CategoryId = 8, ImageUrl = "/images/products/9786338419134.webp", Author = "طه عبدالمحسن", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338419134" },
            new { Id = 614, Name = "سعيد فى عملى", Price = 250m, Stock = 10, Description = "تمنيت يومًا أن تستيقظ وأنت متحمس لبدء يوم عملك؟\nهذا الكتاب ليس مجرد دليل نظري، بل رفيقك العملي لإعادة اكتشاف السعادة في بيئة عملك، بخطوات واقعية، سهلة، وفعّالة.\nسنتعلم معًا كيف نخفف الضغوط، ونستعيد الشغف، ونبني توازنًا حقيقيًا بين الإنجاز والراحة، بين الإنتاجية والرضا.\nمن تقنيات الامتنان والتنفس الواعي، إلى طرق التعامل مع الزملاء والبيئات المرهقة… هذا الكتاب كُتب لك، لتمنح نفسك ما تستحق: راحة البال، والتحفيز، وسعادة العمل.\nلا شعارات… لا مثالية زائفة… فقط أدوات حقيقية تمنحك السيطرة على وقتك، طاقتك، ومزاجك.\nاقلب الصفحة، وابدأ رحلتك نحو يوم عمل يليق بك.", CategoryId = 5, ImageUrl = "/images/products/9786338419141.webp", Author = "كريم عبدالعزيز", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338419141" },
            new { Id = 615, Name = "ما تبقى من ادم", Price = 150m, Stock = 10, Description = "ما تبقّى من آدم\nحين يصبح البقاء اختبارًا للإنسانية، لا للجسد.\nقصة تكشف كيف يمكن للعالم أن يسرق منا كل شيء… إلا السؤال الأخير:\nماذا بقي فينا لنُسمّى بشرًا؟\n\nنصٌّ قصير في حجمه، عميق في وجعه،\nتدخل صفحاته وأنت تبحث عن آدم،\nوتخرج منها وأنت تتمنى أن تكون ما تبقّى منه.", CategoryId = 1, ImageUrl = "/images/products/9786338419158.webp", Author = "طه عبد المحسن", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338419158" },
            new { Id = 616, Name = "حلم طنجار", Price = 150m, Stock = 10, Description = "\"سماء صافية، وشمس تسللت خيوطها عبر النافذة الصغيرة لغرفة داليا لتلامس وجهها الملائكي النائم في هدوء، فأصدر المنبه صوتًا عاليًا جعلها تفتح عينيها العسلية الواسعة، ثم قامت بالضغط عليه لتسكته قبل أن تعتدل من نومها وتنهض.\"", CategoryId = 1, ImageUrl = "/images/products/9786338419165.webp", Author = "محمد فكرى محمد", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338419165" },
            new { Id = 617, Name = "من تحت الركام ولد الوعي", Price = 150m, Stock = 10, Description = "ليس هذا الكتاب سيرة ذاتية بالمعنى التقليدي، ولا بحثًا أكاديميًا باردًا، ولا شهادة إنسانية عابرة تُكتب بدافع الألم فقط. إنه محاولة واعية لالتقاط لحظة تاريخية نادرة: لحظة يولد فيها الوعي من قلب الفقد، وتُعاد فيها صياغة المعرفة تحت الركام.\nكُتب هذا الكتاب في زمن لم تعد فيه الأسئلة النظرية منفصلة عن الدم، ولم يعد فيه الكاتب قادرًا على الاحتماء خلف حياد زائف أو لغة محايدة. في زمن الإبادة، يصبح الصمت موقفًا، ويغدو البحث إما فعل مسؤولية أو شريكًا في التواطؤ. من هنا، لا يقدم هذا الكتاب إجابات جاهزة، بل يطرح أسئلة أخلاقية ومعرفية عميقة حول دور الإنسان، والكاتب، والتقنية، والمعرفة في عالم تتآكل فيه القيم أمام آلة العنف.", CategoryId = 7, ImageUrl = "/images/products/9786338419172.webp", Author = "محمود النجار", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338419172" },
            new { Id = 618, Name = "From Beath The Rubble Awareness Was Born", Price = 150m, Stock = 10, Description = "This book is neither an autobiography in the conventional sense, nor a cold academic study, nor a fleeting humanitarian testimony written solely under the weight of pain. Rather, it is a conscious attempt to capture a rare historical moment: a moment in which awareness is born from the heart of loss, and knowledge is reformulated beneath the rubble.\nThis book was written at a time when theoretical questions are no longer separable from blood, and when the writer can no longer take refuge behind false neutrality or detached language. In an era of genocide, silence becomes a position, and research becomes either an act of responsibility or a partner in complicity. Accordingly, this book does not offer ready-made answers; instead, it raises profound ethical and epistemological questions about the role of the human being, the writer, technology, and knowledge in a world where values are eroded by the machinery of violence.", CategoryId = 8, ImageUrl = "/images/products/9786338419189.webp", Author = "Mohmoud ElNaggar", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338419189" },
            new { Id = 619, Name = "أوكتافا", Price = 150m, Stock = 10, Description = "كان بين الركاب إمرأة حامل تدعى “أمل” على وشك الولادة كانت ذاهبة للمتابعة مع المستشفى ولم تتحمل أمل هذه المعناه وبالفعل ولدت “أمل” بمساعدة السيدات المتوجدات بالمترو والمفاجأة التي أذهلت الجميع هو شكل الطفل الغريب فكانت رأسه رأس إنسان مشوه جدًا وهيئة جسمه غريبة يكسوه شعر كثيف عيناه جاحِظتان وفمه وأنفاسه يخرجان منهما حرارة غريبة تُحرق كل من يقترب منه والأغرب من ذلك هو أنه يستطيع أن يحبوا وهو حديث الولادة ! وطريقته تشبه الروبوت مما تسبب فى حالة ذُعر بين ركاب المترو الصراخ هنا وهناك ودخلت أمل فى نوبة هيسترية .", CategoryId = 1, ImageUrl = "/images/products/9786338419196.webp", Author = "محمد بكر مشتهرى", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338419196" },
            new { Id = 620, Name = "قراءة فى كبرياء الأيام", Price = 130m, Stock = 10, Description = "العمل أصلي بالكامل، ولا يتضمن أي اقتباسات حرفية من كتب أخرى، وإنما يعتمد على قراءة نقدية ورؤية فكرية خاصة بالمؤلف، نابعة من التحليل والتجربة الشخصية، دون نقل أو اعتماد مباشر على مصدر بعينه.\n«لم أقترب من طه حسين لأهدمه،\nبل لأنزله من مقام العصمة إلى مساحة الإنسان…\nحيث يخطئ الكبار كما يُلهمون.»", CategoryId = 8, ImageUrl = "/images/products/9786338419202.webp", Author = "شادي محمد", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338419202" },
            new { Id = 621, Name = "رحلة قطرة", Price = 80m, Stock = 10, Description = "قطرة فضولية تريد معرفة المزيد عن رحلتها، كثيرة الأسئلة.. تنتقل مع قطرة خبيرة عبر رحلة مليئة بالمغامرات عبر نهر النيل للتعرف على مصرنا الحبيبة.", CategoryId = 11, ImageUrl = "/images/products/9786338419219.webp", Author = "رحاب مشعل", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338419219" },
            new { Id = 622, Name = "جرس", Price = 120m, Stock = 10, Description = "ماذا لو كان الموت هو الكذبة التي عشتها لثلاثين عامًا؟\n​في لحظة واحدة يتحول عزاء السنين إلى سراب، وتعود أشباح الماضي لتطرق الباب بمفتاحٍ صغير ورسالة مستحيلة من عالم الأموات.\n​بين ذكريات البراءة ودهاليز الجريمة تدور رحلةُ بحثٍ تحبس الأنفاس عن هويةٍ ضائعة وحقٍ مسلوب.\nحين يدق “الجرس” تأكد أن الصدى سيغير كل شيء.\n​هل أنت مستعد لمواجهة الحقيقة؟", CategoryId = 1, ImageUrl = "/images/products/9786338419226.webp", Author = "محمد صبرى", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338419226" },
            new { Id = 623, Name = "رينينا", Price = 200m, Stock = 10, Description = "عندما يتوارى البدر، وتظهر بنات نعش الكبرى، اربط الدليلين، تجد الجدي عند البوابة، وبعد استقرار الشمس بمثواها، تُفتح المقبرة.\nلغز تناقلته الأجيال عن أسطورة\nبقبر غامض رقدت أسرارها.\nمغامرين كثر سعوا لكشف أخبارها،\nأهلكتهم رينينا على عتبات أطلالها.\nحتى… أتى حملة عهدها\nولامس الجعران نقشها\nفاستيقظ الأحمر نهمًا للدماء\nيبحث عن دمًى آدمية\nيبث رعبه بالقلوب عبرها\nوانبعثت شياطين الكندافيت\nتلقي التعاويذ لتشعل شرارة حرب ضد أعدائها.", CategoryId = 1, ImageUrl = "/images/products/9786338419233.webp", Author = "ياسمين اسماعيل", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338419233" },
            new { Id = 624, Name = "رحلة وعى", Price = 100m, Stock = 10, Description = "قد تظن للوهلة الأولى أن هذا الكتاب موجَّه لمرحلة بعينها، لكنه في الحقيقة يخاطب كل قارئ يبحث عن ذاته، ويسعى لفهم نفسه، وبناء طريقه بوعي وثقة، فكل كلمة هنا كُتبت لتكون رفيقًا لك في رحلتك، تختصر عليك الكثير من الطرق المتعرجة، وتفتح أمامك آفاقًا أوسع، فهو خلاصة مسارات متشابكة، ومحطات من التخبط والاكتشاف.", CategoryId = 5, ImageUrl = "/images/products/9786338419240.webp", Author = "مريم محمود الدالى", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338419240" },
            new { Id = 625, Name = "قلب العاصفة المظلمة", Price = 150m, Stock = 10, Description = "ليست كل المعارك تُخاض بالسلاح…\nبعضها يبدأ حين تكتشف أن أكثر ما يطاردك ليس ما تراه، بل ما تحمله داخلك.\nفي قلب العاصفة المظلمة، تتداخل الحقيقة مع الوهم، ويتحوّل الخوف إلى اختبار، والنجاة إلى اختيار له ثمن.\nرواية عن لحظة واحدة قد تغيّر كل شيء، وعن شجاعة الوقوف في وجه الظل حين يصبح الهروب مستحيلًا.\n\n\"حين أدركت أن العاصفة لم تكن حولي بل داخلي، عرفت أن النجاة لن تكون بالهرب… بل بالمواجهة.”", CategoryId = 1, ImageUrl = "/images/products/9786338419257.webp", Author = "إسراء ساهر", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338419257" },
            new { Id = 626, Name = "أبواب", Price = 130m, Stock = 10, Description = "\"رفع رأسه ببطء وهو يتأوه، بصق شيئاً شعر به بفمه ممزوجاً بسائلٍ ظنَه لعابَه حتى رآه على الأرض بجانب جسده المسجيِّ على الرمال البيضاء، كان أحد الضروس مكسوراً ومختلطاً بالرمال والدماء. تحسس بلسانه أسنانَه ليعرف مكانه لعجزه عن تبين مكانه استدلالاً بالألم، فكل وجهه وجسده يؤلمانه بشدة.\n\nاعتدل جالساً ونظر حوله، ففزع حين رأى أنه في مكان مقفر لا يوجد به سواه، فلاة ممتدة علي مرمى بصره، حاول الوقوف ولكن ساقه اليسري لم تُعِنه، بل على العكس زاد توجعُه منها على بقية الجسد بشكلٍ لفت نظره لتخضب بنطاله بالدماء، فرضخ وعاد للجلوس جاهلاً ما يمكن أن يقوم به أو يساعده في الورطة التي وجد نفسه فيها.\"", CategoryId = 1, ImageUrl = "/images/products/9786338419264.webp", Author = "شروق الهامى الحديدى", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338419264" },
            new { Id = 627, Name = "قلب مفطوم على البكا", Price = 130m, Stock = 10, Description = "وطلعت بسرق ياهوى\nالكحل من قلب العيون\nوانا مش بخون\nكل اللي حبوني بفؤادهم\nعمري ليهم ولراحتهم\nاسهر واشيل\nواميل لو مره يحتاجوا\nاكون عُكاز\nانا مش ازاز\nعلشان تحدفوني بطوب\nأنا شخص كله عيوب\nوحاجات كمان حلوه\nواما اجي اقول غنوه\nمبقولش بالتفاصيل", CategoryId = 8, ImageUrl = "/images/products/9786338419288.webp", Author = "شيماء بركات", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338419288" },
            new { Id = 628, Name = "قصة واحدة لا تكفى", Price = 150m, Stock = 10, Description = "وكأني أعرف القراء عن كثب بينهم المازح والعابس والضاحك والباكي والمحب وكل واحدآ منهم له قصته في هذا الكتاب وستتلقى معي أيها القارئ سيلآ متواصلآ من المشاعر و ستجدني أرحل معك من قصة إلى قصة ومن حبكة درامية لحبكى أخرى أكثر تأثيرآ وكان هدفي الأكبر هو محاكاة الواقع ولكن وجدت الخيال يلوح لي من بعيد ليعيد إلى قلمي جمال الخيال مرة أخري .", CategoryId = 1, ImageUrl = "/images/products/9786338419295.webp", Author = "إسراء محمود حلمى", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338419295" },
            new { Id = 629, Name = "تصميماتى", Price = 250m, Stock = 10, Description = "“أُعد هذا الكتاب ليكون مرجعًا عمليًا لتعليم التصميم على الهاتف، وذلك بطريقة مبسطة وسهلة التطبيق.\nالهدف منه تمكين أي شخص من تحويل خياله إلى تصميم جميل دون الحاجة إلى أجهزة متقدمة أو برامج معقدة.\nستجد في صفحاته شرحًا للأدوات، وخطوات التصميم، وأمثلة تطبيقية تساعدك على تطوير مهاراتك تدريجيًا.”", CategoryId = 8, ImageUrl = "/images/products/9786338419301.webp", Author = "فريق عمل تصميماتى / شهيرة المصرى", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338419301" },
            new { Id = 630, Name = "الفرن القديم", Price = 50m, Stock = 10, Description = "والدة الطفـل مازن منزعـجة من تعطـل فرنها القديم عن العمل ولكنها في اليوم التالي حصلت على فرنها الجديد.\nولدها مازن وجد الفرن القديم مـتروكًا في حرارة الشمس، فقام يؤدي بعض حركـات اللعب لكنه دُهـش بمدى استياء فرنهم القديم لما تكلم !\nوهل الأفران تتكلم؟!\nهيا بنا نرافق صديقنا الصغير مـازن كيما نتعرف على تفاصيل الحكاية الشيقـة التي حصلت لـه، أمامه مهمـة حساسة حتى لا ينفـذ الفرن القديم تهديده و...", CategoryId = 11, ImageUrl = "/images/products/9786338419318.webp", Author = "أحمد المؤذن", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338419318" },
            new { Id = 631, Name = "المدينة أجمل من الريف ؟", Price = 50m, Stock = 10, Description = "صغيري أنت تسكـن في المدينة؟ أتعـتـقد بأنها أجمل مكان؛ لا تستعجـل قبل قراءة هذه القصـة لأن الديـك \" صـيّــاح \" حينما قـرر زيـارة صديقـه الديك \" مــســـرور \" في المدينة ، هـل تعرف ماذا حصـل له؟\nهـذه القصـة لك ولهـا، تعـاليا الآن حتى ننـطلق من بدايــة الأحـداث ونكتشف ما الدرس الذي تعلمـه صــيّـاح وقت مـغادرته للـريف ومـزرعـته الخضراء الوادعــة، هـيا بسـرعـة فهنا أحـداث كـثيرة ومشوقـة تنتظـرنــا!", CategoryId = 11, ImageUrl = "/images/products/9786338419325.webp", Author = "أحمد المؤذن", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338419325" },
            new { Id = 632, Name = "الشريحة", Price = 160m, Stock = 10, Description = "تدور أحداث الرواية حول تقنية ثورية تعتمد على شريحة نانو تُزرع في عقل الإنسان بدعوى علاج الأمراض العصبية وتحسين القدرات الذهنية، مثل الذاكرة، وسرعة التعلم، والتحكم في الألم والمشاعر.\nفي البداية تُقدَّم الشريحة على أنها أعظم إنجاز علمي يخدم البشرية، وتُستخدم على نطاق محدود ثم تتوسع تدريجيًا حتى تصبح خيارًا شبه إلزامي.\nمع الوقت، يكتشف أبطال الرواية أن الشريحة لا تكتفي بالمراقبة الطبية، بل تسجّل الأفكار، وتعدّل المشاعر، وتعيد توجيه القرارات دون وعي أصحابها. تتحول الحدود بين الإرادة الحرة والبرمجة إلى خط ضبابي", CategoryId = 1, ImageUrl = "/images/products/9786338419332.webp", Author = "محمود سعد", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338419332" },
            new { Id = 633, Name = "الطاقة المفقودة", Price = 150m, Stock = 10, Description = "استعد لرحلة اكتشاف الطاقة المفقودة بداخلك، وكن جاهزًا للأحداث التي قد تطرق بابك، أوعدك بالإستمتاع بالرحلة طالما نظرت لأمور حياتك بشكل منطقي دون الإرتباط بمشاعرك، بالتأكيد ستكون الرحله صعبة، إنك سَتبحر في أعماق نفسك لتكتشف ماذا يحدث بداخلك، وما هى المتاعب التي تستهلك طاقتك لتقضي عليها تمامًا، ثم تُرمم تلك الندوب التي تركتها؛ لتنقذ نفسك من البؤس القاتل، كن حَذرًا من الإبحار في هذا المكان الخاطيء، ولا تكون مثل الصياد الذي ترك البحر وذهب بشبكته إلى الصحراء؛ ليصطاد منها جميع المتاعب التي تقضي عليه لا محال.", CategoryId = 5, ImageUrl = "/images/products/9786338419349.webp", Author = "طه ثابت", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338419349" },
            new { Id = 634, Name = "الصيدلية", Price = 120m, Stock = 10, Description = "ماذا لو لم يكن الشفاء نعمة… بل صفقة؟\n\nالصيدلية تظهر حين تكون في أضعف حالاتك،\nتدخلها باحثًا عن الخلاص،\nوتخرج منها حاملًا سؤالًا لن يتركك:\n\nإذا كان نجاتك مرهونة بسقوط غيرك… فهل تختار الشفاء؟\n\nهذه ليست رواية رعب،\nبل مواجهة مع ضميرك،\nوإن بدأت القراءة…\n\nتذكر: ليس كل باب يُفتح… يريدك أن تعود.", CategoryId = 1, ImageUrl = "/images/products/9786338419356.webp", Author = "محمد مندور", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338419356" },
            new { Id = 635, Name = "الوعى المختطف", Price = 130m, Stock = 10, Description = "في عالمٍ تتسارع فيه تدفّقات المعلومات، وتتداخل فيه الحقيقة بالوهم، يبرز الاستهواء الفكري بوصفه إحدى أخطر الظواهر التي تهدد وعي الفرد وتماسك المجتمع، لاسيما في أوساط الشباب، يأتي هذا الكتاب ليقدّم معالجة علمية وتحليلًا معمقًا لهذه الظاهرة، كاشفًا عن آلياتها الخفية، ومظاهرها المتعددة، وآثارها السلبية الممتدة على التفكير والسلوك واتخاذ القرار، وينطلق الكتاب من تأصيلٍ مفاهيمي دقيق لظاهرة الاستهواء الفكري، موضحًا أبرز مظاهرها لدى الفرد، وما تخلّفه من نتائج نفسية ومعرفية وسلوكية، مثل تراجع التفكير النقدي، والانقياد غير الواعي للأفكار المتطرفة أو المضللة، وفقدان الاستقلالية الفكرية، كما يستعرض مجموعة من النظريات النفسية والاجتماعية المفسّرة للاستهواء الفكري، ويحلل العوامل المؤثرة فيه، سواء تلك المرتبطة بخصائص الفرد النفسية والمعرفية، أو بالعوامل الاجتماعية والثقافية المحيطة به، كما يولي الكتاب اهتمامًا بدراسة العلاقة بين ظاهرة الاستهواء الفكري والاستخدام المكثف لمواقع التواصل الاجتماعي، مبرزًا دور هذه المنصات في إعادة تشكيل الوعي، وتسريع انتشار الأفكار الموجَّهة، وتعميق دوائر التأثير عبر الخوارزميات والمحتوى العاطفي والمعلومات غير الموثوقة، ولا يقتصر الكتاب على تشخيص الظاهرة وتحليلها، بل ينتقل إلى الجانب التطبيقي، حيث يقدّم مجموعة من الاستراتيجيات العملية التي تمكّن الفرد من التصدي للاستهواء الفكري، في مقدمتها تنمية مهارات التفكير الناقد، بوصفه أداة أساسية للفحص والتحليل والتمييز بين الحقيقة والتضليل، إلى جانب تعزيز المناعة النفسية بما تحمله من قدرة على الصمود، وضبط الانفعالات، ومقاومة الضغوط الفكرية والاجتماعية، كما يوسّع الكتاب دائرة المواجهة لتشمل الأدوار التربوية والمجتمعية، فيناقش دور الأسرة في بناء الوعي المبكر لدى الأبناء، ودور المدرسة في ترسيخ مهارات التفكير الواعي والمسؤول، ودور الجامعة في حماية العقول الشابة من الانجراف الفكري، وتعزيز الاستقلالية الفكرية والانتماء الواعي، وعليه يهدف المؤلف من خلال هذا العمل إلى تمكين القارئ من فهم ظاهرة الاستهواء الفكري بعمق، وتزويده بالأدوات الفكرية والنفسية التي تحمي وعيه من الاختطاف، ليصبح أكثر قدرة على تحليل الأفكار والمعلومات، واتخاذ قراراته باستقلالية، وخوض تجربة معرفية حرة ومستنيرة في زمن تتكاثر فيه محاولات التأثير والسيطرة على العقول.", CategoryId = 1, ImageUrl = "/images/products/9786338419363.webp", Author = "محمد ابو السعود", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9786338419363" },
            new { Id = 636, Name = "درب عقلك كيف يفكر عالم الرياضيات", Price = 170m, Stock = 10, Description = "كيف يفكر عالم الرياضيات\nعَقلُ الإنْسَانِ شَيءٌ مُبهِرٌ.. يَتطوَّرُ العَقلُ بِالتَّعلُّمِ، وَيُمكِنكَ أنْ\nتَجعَلهُ يُفكِّر بِطُرقٍ كَثيْرَةٍ. مَعَ هَذِه السِّلْسِلةِ سَتسْتَكشِفُ مِهنًا ابْتِكارِيَّةً تَستَلهِمُ مِنهَا مُستَقبَلكَ، وَسَوفَ تُساعِدُكَ علَى تَدرِيبِ عَقلِكَ لِيُفكِّرَ مِثلَما يُفكِّر صَاحِبُ كُلِّ مِهنَة.\nهَل تَستَمتِع باللَّعِب بالأرْقامِ وَالأشْكالِ؟ \nهَل تُحبُّ العُثورَ علَى الأنْماطِ في العَالَم مِن حَولكَ؟ في هَذِه الحَالَة قدْ تَرغبُ في أنْ تُصبحَ في مَجالِ الرِّياضيَّات. \nتَستَخدِم الرِّياضيَّاتُ المَنطِق للكشْفِ عنِ الأنْماطِ وَالأشْكالِ الَّتِي تَحكُم الكوْنَ. وَسَواءٌ كانَ الرِّياضيُّونَ مُبتكِرينَ أرْقامًا سِرِّيةً أوْ يَستَكشِفونَ قَواعِد الاحْتمَالَات، فَقدْ دَرَّبوا عُقولَهم علَى التَّفكِير بطَريقَةٍ مُعيَّنة.. وَبُمساعَدةِ هذَا الكِتَاب، يُمكِنكَ أنْ تَبدَأ أنتَ أيضًا \nفي التَّفكِيرِ كعَالِم ريَاضيَّات.\n\nرسوم دافيد برودبنت ترجمة وإعداد أشرف بسيم", CategoryId = 11, ImageUrl = "/images/products/9789777955416.webp", Author = "الكس وولف", PublishDate = new DateTime(2026, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789777955416" },
            new { Id = 637, Name = "درب عقلك كيف يفكر العالم", Price = 170m, Stock = 10, Description = "كيف يفكر العالم\nعَقلُ الإنْسَانِ شَيءٌ مُبهِرٌ.. يَتطوَّرُ العَقلُ بِالتَّعلُّمِ، وَيُمكِنكَ أنْ\nتَجعَلهُ يُفكِّر بِطُرقٍ كَثيْرَةٍ. مَعَ هَذِه السِّلْسِلةِ سَتسْتَكشِفُ مِهنًا ابْتِكارِيَّةً تَستَلهِمُ مِنهَا مُستَقبَلكَ، وَسَوفَ تُساعِدُكَ علَى تَدرِيبِ عَقلِكَ لِيُفكِّرَ مِثلَما يُفكِّر صَاحِبُ كُلِّ مِهنَة.\nهَل أنْتَ فُضولِيٌّ بطَبِيعَتِكَ وَترْغَبُ في التَّعرُّفِ علَى العَالَمِ؟ \nهَل تُريدُ أنْ تَفهَمهُ؟ \nفي هَذِه الحَالةِ قَدْ تَرغَبُ في أنْ تَكونَ عَالِمًا.. يُحقِّقُ العُلمَاءُ تَقدُّمَ المعْرِفَةِ الإنْسَانيَّةِ بوَضْعِ أسْئِلةحَولَ العَالَمِ وَكَيفَ يَسِيرُ؟ \nوَيأتُونَ بنَظرِيَّاتٍ وَيَختَبرونَها بوَاسِطَةِ التَّجارِبِ.. سَوَاء كانُوا يَدرُسونَ النُّجوْمَ أوِ الحَفرِيَّاتِ أوِ العَقلَ الإنْسانِيَّ، فَقدْ درَّبَ العُلماءُ عُقولهُم علَى التَّفكيْرِ بِشكْلٍ مُعيَّنٍ، وَبمُساعَدةِ هَذا الكِتَابِ، \nيُمكنُكَ أنْ تَبدَأ في التَّفكِيرِ مِثلَ العَالِمِ.\n اسم المؤلف :- ألكس وولف \nرسوم :- دافيد برودبنت \nترجمة :- وفاء اشرف \nسنة النشر :- 2026\n\nرسوم دافيد برودبنت ترجمة وإعداد أشرف بسيم", CategoryId = 11, ImageUrl = "/images/products/9789777955447.webp", Author = "الكس وولف", PublishDate = new DateTime(2026, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789777955447" },
