            new { Id = 640, Name = "درب عقلك كيف يفكر رائد الفضاء", Price = 170m, Stock = 10, Description = "كيف يفكر رائد الفضاء\nعَقلُ الإنْسَانِ شَيءٌ مُبهِرٌ.. يَتطوَّرُ العَقلُ بِالتَّعلُّمِ، وَيُمكِنكَ أنْ\nتَجعَلهُ يُفكِّر بِطُرقٍ كَثيْرَةٍ. مَعَ هَذِه السِّلْسِلةِ سَتسْتَكشِفُ مِهنًا ابْتِكارِيَّةً تَستَلهِمُ مِنهَا مُستَقبَلكَ، وَسَوفَ تُساعِدُكَ علَى تَدرِيبِ عَقلِكَ لِيُفكِّرَ مِثلَما يُفكِّر صَاحِبُ كُلِّ مِهنَة.\nهَل حَلمتَ يَومًا بالسَّفرِ إلَى الفَضَاء؟\nهَل يَجعلُكَ الفُضولُ تَتطلَّع للكوَاكِب وَتتَمنَّى اسْتكْشَافَها؟ في هذِه الحَالَة، قَدْ تُعجِبُك مِهنَة رَائدِ الفَضَاء.. يَحتاجُ روَّادُ الفَضَاء إلَى الحزْمِ وَالقُدرَة علَى اتِّخاذِ القرَارَات وَالتَّفكيْرِ العِلمِيِّ، إلَى جَانبِ مَوهبَةِ التَّواصُل وَالعَملِ دَاخِل فَريْقٍ.. وَسوَاء كانَ رَائدُ الفَضاءِ يَزرعُ النَّباتَاتِ في غيَابٍ كَاملٍ للجَاذبيَّة، أوْ كانَ يَسيرُ في الفَضاءِ، فَقدْ تَدرَّب علَى اسْتِخدَام عَقلِه بطَريقَةٍ مُعيَّنة، وَسوفَ يُساعدُك هذَا \nالكِتابُ علَى البَدءِ في التَّفكيْرِ مِثْل رَائدِ الفَضَاء.\nيُمكنُكَ أنْ تَبدَأ في التَّفكِيرِ مِثلَ العَالِمِ.\n اسم المؤلف :- ألكس وولف \nرسوم :- دافيد برودبنت \nترجمة :- وفاء اشرف \nسنة النشر :- 2026\n\nرسوم دافيد برودبنت ترجمة وإعداد أشرف بسيم", CategoryId = 11, ImageUrl = "/images/products/9789777955423.webp", Author = "الكس وولف", PublishDate = new DateTime(2026, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789777955423" },
            new { Id = 641, Name = "قلم احمر", Price = 170m, Stock = 10, Description = "قَلقٌ وَخَيْبَةُ أَمَلٍ تَرْجِعُ بِهَا دَليْلَةٌ مِنَ المَدرَسةِ.. بعدَ يَومٍ وَاجَهَتْ فِيْهِ صُعوبَاتٍ عَدِيدَةً لَا تَرَى لَها حَلَّا .. لَكِنَّها مَعَ مَامَا ، وَبِقَلْمٍ أَحْمَرَ، اكتَشَفَتْ طَرِيقَةً لتتغلب علَى مَا يُرْعِجُها إلى الأبد.\nاسم المؤلف :- علا منجد\nرسوم :- حسين الرباعي  \nسنة النشر :- 2025", CategoryId = 11, ImageUrl = "/images/products/9789777955393.webp", Author = "علا منجد", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789777955393" },
            new { Id = 642, Name = "تاريخ الترجمة فى مصر", Price = 495m, Stock = 10, Description = "إذا كان تاريخ الترجمة من الحقول البحثية المهمة، فإن هذا الكتاب كان – وسيبقى -  \"العُمْدَة\" في موضوعه لأسباب، منها: منهجه، وقيمته العلمية. وهو من الأعمال المهمة التي أبدعها الدكتور جمال الدين الشيَّال (1967-1911م) أحد المؤرِّخين والمحقِّقين المصريين العِظام في القرن العشرين.  وقد طُبع من قبل في كتابين، يتناول الكتاب الأول \"تاريخ الترجمة في مصر في عهد الحملة الفرنسية\" من خلال مقدمة، وتمهيد تناول تزاوج الحضارات ووسائله، وحالة مصر والشرق الأدنى قبيل الحملة الفرنسية، ثم ثلاثة فصول حول: \"اتصال العُلماء المصريين بعُلماء الحملة، وأثر هذا الاتصال\"، و\"الترجمة الرسمية في عهد الحملة\"، و\"الترجمة العِلمية في عهد الحملة\". أما الكتاب الثاني فتناول \"تاريخ الترجمة والحركة الثقافية في عصر محمد علي\"، وذلك من خلال مقدمة وثلاثة أبواب، تدور حول الأدوات المباشرة وغير المباشرة للترجمة في عصر محمد علي، وتقدير عام للترجمة في ذلك العصر. والكتاب يُنشر هنا للمرة الأولى كاملًا، وعلى الصورة التي كان عليها في الأصل باعتباره أول رسالة ماجستير تمنحها جامعة فاروق الأول (الإسكندرية) سنة 1945م بمرتبة الشرف الأولى، وقد نال الكتاب جائزة البحث الأدبي لسنة 1946م من «مَجْمَع فؤاد الأول الملكي للُّغة العربية»، وكان مُقرِّرها الدكتور طه حسين.       \n ـــــــــــــــــــــــــــــــــــــــــ\nمحمد صبري الدالي، أستاذ التاريخ الحديث والمعاصر بآداب حلوان. له تسعة كتب، وعشرات البحوث المنشورة في مصر واليابان وألمانيا وفرنسا وتركيا. ترجم وحقق وراجع ستة كتب. حصل على جائزة الدولة التشجيعية (2009م)، وجائزة جامعة حلوان التقديرية (2023م)، وجائزة أفضل كتاب مترجَم في معرض القاهرة الدولي للكتاب (2024م).\nاسم المؤلف :- جمال الدين الشيال\nمراجعة وتقديم :- محمد صبرى الدالي\nاشراف :- ايمن فؤاد سيد \nسنة النشر :- 2025\n\nمراجعة وتقديم: أ.د محمد صبري الدالي إشراف: أ.د أيمن فؤاد سيد", CategoryId = 7, ImageUrl = "/images/products/9789777955515.webp", Author = "جمال الدين الشال", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789777955515" },
            new { Id = 643, Name = "تغير المناخ", Price = 360m, Stock = 10, Description = "تغير المناخ اليوم، لم يعد هناك شك في أن البشرية تواجه العديد من الأزمات، إحدى الأزمات الرئيسية هي تغيّر المناخ. هناك الآن توافق عام على أن تغيّر المناخ والاحترار العالمي يحدثان نتيجة لأنشطة الإنسان التي تطلق كميات كبيرة من الغازات إلى الغلاف الجوي، مما يخلق تأثير الاحتباس الحراري ويُدفئ الكوكب بما يتجاوز ما كنا نتوقعه بناءً على العمليات الطبيعية التي شهدناها في السجل الجيولوجي السابق للأرض. والتجليات المتوقعة لهذا التغيّر المناخي تُشاهد بالفعل في كل مكان من الأحداث الجوية المتطرفة مثل الأعاصير والزلازل والعواصف الشديدة، إلى فترات ممتدة من الحرارة والبرد القاسيين والحرائق البرية، ودورات الجفاف والفيضانات الشديدة. وما هو أقل وضوحًا ولكن لا يقل أهمية، هو تدمير تنوع الحياة على الأرض، ومع مرور الوقت، يمكننا أيضًا رؤية المخاطر المرتبطة بارتفاع مستوى سطح البحر.\nاسم المؤلف :- اسماعيل سراج الدين \nترجمة :- محمد خالد والي \nسنة النشر :- 2025", CategoryId = 8, ImageUrl = "/images/products/9789777955492.webp", Author = "إسماعيل سراج الدين", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789777955492" },
            new { Id = 644, Name = "السينما والناس", Price = 195m, Stock = 10, Description = "يدور هذا الكتاب حول تطور السينما المصرية، وقدرتها على التعبير عن قضايا المجتمع، وآفاق التطور في أفلام الألفية الثالثة باعتبارها التجلي الأحدث للسينما. وينقسم الكتاب إلى خمسة أبواب تشمل 14 فصلا، تتناول مختلف قضايا الفن السابع، خاصة التزام السينما منذ بداياتها بالتعبير عن مشاكل المرأة في المجتمع، ونجاحها في أن تكون المعبر الأول عن أحوالها، وصوتها المسموع. كما يرصد الكتاب سعي السينما إلى استحداث طرائق تعبير جديدة، وتوظيف الرمز بشكل مختلف مشيرا إلى طريقة تعامل السينما مع الغرابة والطرافة، وقصص الحب في كلاسيكيات السينما المصرية، والأفلام التي عبرت عن شخصيات في المجتمع، مثل: «المعلم»، و«الصحفي»، فضلا عن تناول الأفلام السينمائية لشخصيات مصابة بأمراض نفسية وبحث إشكالية الذين وآفاق التعبير السينمائي.\nطارق إبراهيم حسان، كاتب وناقد، وقاص نشر مقالات و دراسات حول السينما والثقافة والأدب في الصحف والمجلات المصرية والعربية. صدر له كتابان، أحدهما في النقد الفني بعنوان: الشخصية في السينما المصرية (2021م) والآخر في أدب الرحلات بعنوان: «مملكة الصحراء البعيدة (2019م).\nاسم المؤلف :- طارق ابراهيم حسان\nسنة النشر :- 2025", CategoryId = 8, ImageUrl = "/images/products/9789777955409.webp", Author = "طارق إبراهيم حسان", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789777955409" },
            new { Id = 645, Name = "جرائم امن الفضاء السيبرانى", Price = 825m, Stock = 10, Description = "جرائم أمن الفضاء السيبراني\nيتطرّق هذا الكتاب إلى البحث في قضية على قدر كبير من الأهمية لكل مستخدمي الإنترنت ومستثمري تكنولوجيا المعلومات، من حيث الموقف القانوني لمقدمي الخدمات الرقمية، في حال استخدام أنظمتهم التكنولوجية في ارتكاب جريمة سيبرانية. ناقش مؤلف الكتاب النصوص الشكلية والموضوعية المنظمة لقواعد الإسناد الجنائي والمدني، ثم أجرى دراسة تحليلية لنصوص قوانين مكافحة جرائم أمن المعلومات وحماية البيانات المصري، ومقارنتها بقوانين الولايات المتحدة والاتحاد الأوربي، وذلك في ضوء مبادئ محكمة النقض المصرية. وقد تمكّن الكاتب من تحديد أسباب عدم صدور أيّ حكم قضائي جنائي ضد مقدمي الخدمات في مصر، وأرجعها إلى وجود قصور مُعجِز في نصوص القوانين. إنّ هذا الكتاب سيظل مرجعًا يركن إليه كل من أراد البحث في جرائم تكنولوجيا المعلومات وأمن الفضاء السيبراني، لما يتمتع به مؤلفه من سعة قانونية، ورسوخ فقهي في أحكام الإسنادين المدني والجنائي، وقدرة على إجراء المقارنات الدالة بين نصوص القانون المصري من جهة، ونظيره في الولايات المتحدة والاتحاد الأوربي من جهة أخرى.\nــــــــــــــــــــــــــ\nالمستشار عمرو محمد شكري، قاضٍ بمحكمة الجنايات، مستشار أمن المعلومات وحماية البيانات- لندن (إنجلترا). حصل على درجة الماجستير من جامعة برونيل بلندن، وكان موضوعها حول «حماية المحتوى الرقمي»، كما حصل على درجة الدكتوراه من نفس الجامعة، وكان موضوعها حول «المسؤولية الجنائية والمدنية لمقدمي الخدمات».\nاسم المؤلف :- عمرو شكرى القبطان\nسنة النشر  :- 2025", CategoryId = 8, ImageUrl = "/images/products/9789777955195.webp", Author = "عمرو شكري القطان", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789777955195" },
            new { Id = 646, Name = "اوراق الغربة - ايام فى لبنان", Price = 360m, Stock = 10, Description = "أوراق الغربة\nأيًّا كانت أسباب الرحلة، وتفاصيل الغُربة، فقد حمل مودي حكيم معه إرثًا حضاريًّا عريقًا، تشبَّع به من أرض مصـر، وتشرَّبه من نيلها، قبل أن يمزجه بلغةٍ عربيةٍ رصينة؛ ليروي لنا برهافةٍ حكاية غُربته في لبنان، الذي أحبَّه حُبَّه لمصر، ولم يخرج منه إلا مُكرهًا بعد أن اخترق صاروخ الاحتراب الأهلي جدار مسكنه، وهدَّد حياة أغلى ما يملك في الدنيا: ابنه وابنته وزوجته.\nولأن مودي حكيم مخرج صحفي موهوب، فقد رسم بكلماته المفعمة حبًّا لوحة مبهرة رغم شجنها؛ تدفع القارئ/المُشاهد لها إلى الحيرة والارتباك، حين يسأل نفسه بذهولٍ: كيف تحوَّل لبنان من كل هذا الجمال الفاتن، إلى كل هذا الأسى الصادم؟!\nإنها رحلة فنان، كتب بمِدَاد روحه، ورسم بريشة قلبه، لوحة مبهرة حدَّ الوجع، وموجعة حدَّ الإبهار!\nــــــــــــــــــــــــــــــ\nمودي حكيم، كاتب صحفي مصـري، عضو نقابتي الصحفيين في مصر وبريطانيا، والكلية الملكية للفنون البريطانية، ونقابة التشكيليين المصـرية، ورابطة المراسلين الأجانب الدوليين. بدأ رحلته مع الصحافة منذ أكثر من ستين عامًا في مؤسسة روز اليوسف. رأس تحرير مجلة «ستالايت» أول مطبوعة فضائية في العالم، وأسَّس الطبعة الدولية لجريدة «السياسة» الكويتية في المغرب. يرأس مجلس إدارة شركة مودي برودكشن الناشر لمجلة «24Hours».\nاسم المؤلف :- مودى حكيم\nسنة النشر :- 2025", CategoryId = 7, ImageUrl = "/images/products/9789777955287.webp", Author = "مودي حكيم", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789777955287" },
            new { Id = 647, Name = "تاريخ عمرو بن العاص", Price = 275m, Stock = 10, Description = "هذا الكتاب هو نتاج الجامعة المصرية التي أسسها الشعب المصري في بدايات القرن العشرين لتكون إحدى أدوات النهوض والارتقاء بمصر. آمن المصريون حيناها أن الارتقاء بالوطن لا يكون بمقاومة الاحتلال البريطاني بالقوة فحسب ، بل يجب أن يكون الرتقاء بالعلم أيضاً، فكانت الجامعة التي تحمل الآن اسم عاصمة مصر \"القاهرة\"،وصارت عنواناً للصراع من أجل ترسيخ المفاهيم والقيم العلمية، وهذا ما نراه في مقدمة المؤلف في دفاعة عن الجامعة ضد منتقديها. \nوفى هذا الكتاب نرى جغرافيا الفتح الإسلامي لمصر تثير نقاشاً، وتطرح اسئلة مثل: هل فتحت الفيوم قبل أو بعد؟ وكيف تحرك جيش المسلمين على الأرض المصرية؟ فما زال فتح مصر على يد عمرو بن العاص مثيراً بحوادثة، إذ إنه أشبه بلقطات تصور لنا تتابعها أحداثها قد يراها البعض أسطورية نظراً لقلة عدد جند الجيش، أو لصبرهم على الفتح، ولطول المساحة الجغرافية التي تحركوا فيها..\nومازلنا في حاجة إلى مزيد من الداراسات حول هذه الحقبة، لبناء سرديات جديدة، فالسرديةالتي بين أيدينا تأثر بها كل من جاء بعد الدكتور حسن إبراهيم حسن، وعلى رأسهم عباس محمود العقاد في كتابة عن عمرو بن العاص، كما شكلت جانباً من رؤية د. طه حسين حينما قدم كتاب \" الفتنة الكبرى\"\nاسم المؤلف :- حسن ابراهيم حسن\nمراجعة وتحقيق :- خالد عزب\nاشراف :- ايمن فؤاد سيد\nسنة النشر :- 2025", CategoryId = 7, ImageUrl = "/images/products/9789777955348.webp", Author = "حسن إبراهيم حسن - شرح وتعليق د. خالد عزب", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789777955348" },
            new { Id = 648, Name = "وصايا الكتابة", Price = 295m, Stock = 10, Description = "وصايا الكتابة\nلا أحدَ يُولَدُ تامًّا، فهناك دائمًا نقصٌ يحتاجُ إلى إرشادٍ يُنيرُ ،أو توجيهٍ يساعدُ، أو وصيةٍ تقُودُ، أو نصيحةٍ تُمهِّدُ؛ مِمَّن خبَرَ وعرَفَ واحترفَ، والنقصُ يستولي على جُملة البشر، لكنَّ الأهمَّ أن يُدْرِكَ الكاتبُ أو الشَّاعرُ ما ينقصُه ،ويعرف أسرارَ \"مهنة الكتابة\".\nوالشَّاعر والكاتب أحمد الشَّهاوي يُقدِّم تجربةً اشتغلَ عليها سنواتٍ من حياتهِ مع الحَرْف، وقدَّم كتابًا جديدًا ومختلفًا وضافيًا، ضمَّ مئات الوصايا التي تقُود الكاتبَ أو الشَّاعرَ إلى طريقِ الكتابةِ.\nهذا الكتاب يوضِّحُ لك جُزءًا من الطَّريقِ كي تصلَ إلى ما تبتغِي، فالمرء يظلُّ حتَّى آخر العُمرِ يذهبُ إلى الكتابةِ كأنَّهُ يكتبُ للمرَّةِ الأولى، إنَّها رهبةُ الكتابةِ وقداستها.\nأحمد الشَّهاوي يؤكِّد في كتابه \"وصايا الكتابة.. كيف نكتبُ.. ولماذا؟\" أنَّ \"الكتابةَ الجميلةَ الباقيةَ هي كالحُبِّ تطيلُ العُمرَ، بل وتُنْقِذُ من الإحباطِ والاكتئابِ والموتِ، وتُبْقِي عقلَكَ سليمًا، وتَصْرِفُ نظرَ القاتلِ عن استعمالِ مُسدَّسهِ في وجهِ مَن اختطفهُ في الظَّلام. الكتابةُ تُغيِّرُ وتَشفِي الرُّوحَ والجسدَ معًا\".\nولكي يصيرَ المرءُ كاتبًا جيِّدًا ومُتحقِّقًا، عليه أن ينتظمَ في دفعِ ضرائبِ الكتابةِ؛ التي ليست مَهَمَّةً سهلةً، وتتمثَّلُ تلك الضَّرائبُ في القراءةِ، والإتقانِ، والزُّهدِ، والسَّخاءِ، والإخلاصِ، والالتزامِ، والعُزلةِ، والتدقيقِ الدَّائمِ في الذَّات، والترحالِ، وحبِّ الكتاب قبل حُبِّ الكتابة، والتَّرَوِّي، والتخلِّي عمَّا يُعطِّل المسيرةَ، وإعادةِ ما تكتبُ.. ومن ضمن ضرائب الكتابةِ قراءة هذا الكتاب.\nـــــــــــــــــــــــــــــــــ\nأحمد الشَّهاوي، شاعر وكاتب من مصر، حاز على جائزة اليونسكو في الآداب عام 1995م، وجائزة كفافيس الدولية في الشِّعر مايو 1998م. أصدر ما يزيد على خمسة وعشرين كتابًا في الشعر والرواية والتصوف وأدب العشق. صدرت أعماله الشعرية مُترجمةً إلى لغاتٍ عديدة. وقد وصلت أعماله إلى القائمة الطويلة لجائزة زايد للكتاب خمس مَرَّات.\nاسم المؤلف :- احمد الشهاوى\nسنة النشر :- 2025", CategoryId = 8, ImageUrl = "/images/products/9789777955317.webp", Author = "أحمد الشهاوي", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789777955317" },
            new { Id = 649, Name = "الثقافة العربية تحديات ورؤى", Price = 165m, Stock = 10, Description = "تمر المنطقة العربية والعالم بمرحلة مضطربة، شائكة، قد تعقبها تحولات عميقة، وقد جاء هذا الكتاب نتيجة هذه المرحلة، والانشغال بالوضع الراهن.. فهناك حروب مشتعلة، وإبادة في غزة صُنِّفت باعتبارها الأبشع في تاريخ العالم.. كل هذا يجعلنا قلقين، والقلق لا يدعو إلى الاطمئنان للمستقبل، خاصة إذا كان هذا المستقبل في المنظور القريب به ضباب كثيف.. ولأن عليَّ كمفكر أن أقوم بدورٍ ما في ظل هذا كله، فقد كان هذا الكتاب، الذي يحمل تحديات ورؤى للثقافة العربية، آملًا أن يكون مفتاحًا لمناقشات موسَّعة حول ما هو قادم في هذه الثقافة، ولنفكر مليًّا: أين نحن؟ وإلى أين نحن ذاهبون؟\nــــــــــــــــــــــــــــــــــــــ\nإسماعيل سراج الدين، الرئيس المشارك لمجلس أمناء مركز نظامي كنجوي الدولي في آذربيجان. المدير المؤسس لمكتبة الإسكندرية (2017-2001). شغل منصب نائب رئيس البنك الدولي (2000-1993) وكان مسئولًا عن التنمية المستدامة بيئيًّا، ورأس المجموعة الاستشارية الدولية للبحوث الزراعية.  كان عضوًا في المجموعة رفيعة المستوى لتحالف الحضارات التي شكلها الأمين العام للأمم المتحدة. صدر له أكثر من 100 كتاب و500 مقال باللغات العربية والإنجليزية والفرنسية. حصل على أكثر من 40 دكتوراه فخرية من العديد من الجامعات على الصعيد الدولي.\nاسم المؤلف :- اسماعيل سراج الدين\nسنة النشر :- 2025", CategoryId = 8, ImageUrl = "/images/products/9789777955331.webp", Author = "إسماعيل سراج الدين", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789777955331" },
            new { Id = 650, Name = "الصفات الشخصية تبين من نحن", Price = 400m, Stock = 10, Description = "الصفات الشخصية\nهل تعلم أن الصفات الشخصية هي كل الأشياء التي تجعلنا ما نحن عليه؟ وكيف نفكر؟ وكيف نتصرف؟ وهذه الصفات يمكن أن تكون جيدة، مثل أن تكون استباقيًّا، أو مرنًا، أو صادقًا؛ وقد تكون سيئة، مثل أن تكون متسلِّلًا، أو انانيًّا، أو غير صبور.\nدعنا نستكشف مجموعة كاملة من الصفات الشخصية، ونكتشف ما الذي يجعلك \"أنت\"!\nاسم المؤلف :- جينفر مورا لينوس \nترجمة واعداد :- وفاء اشرف \nسنة النشر :- 2025", CategoryId = 11, ImageUrl = "/images/products/9789777955201.webp", Author = "وفاء أشرف", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789777955201" },
            new { Id = 651, Name = "ومضات من الفكر", Price = 360m, Stock = 10, Description = "ومضات من الفكر \nفي السياسة والدين والاخلاق والفن والحياة\n \nقليلة هي الكتب التي تدعو قارئها إلى الاشتباك الفكري معها وتظل تستفز عقله حتى يُعمِل آلته النقدية فيما يقرأ، فتلك الكتب لا ترضى بعقل كسول وذهن خامل، وكتاب «ومضات من الفكر» لمؤلفه الدكتور سعيد توفيق، أستاذ علم الجمال والفلسفة المعاصرة بكلية الآداب، جامعة القاهرة، من ضمن الكتب القليلة التي تشكِّل إضافة إلى وعي المثقف العربي، وبسبب جِدة أرائه ورصانة مادته، فهو يستدعي الحوار الفكري مع ما طرحه من قضايا الدين والسياسة والأخلاق والفنون، بما هو شأن كل فكر جاد يهدف إلى تعزيز ثقافة نقدية ترقى بتفكير ووجدان الإنسان، فهو جدير بأن يكون ضمن الاختيارات التثقيفية لكل مثقف.\nاسم المؤلف :- سعيد توفيق\nسنة النشر :- 2025", CategoryId = 8, ImageUrl = "/images/products/9789777955294.webp", Author = "سعيد توفيق", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789777955294" },
            new { Id = 652, Name = "انت اقوى", Price = 470m, Stock = 10, Description = "أنت أقوى\n \nأخطر ما تُنبِّه إليه مؤلفة هذا الكتاب، هو تحوُّل الإنسان إلى \"زومبي\"، يؤدي دوره المطلوب منه بقلبٍ ميتٍ، وروحٍ خاوية لا تحمل أي مظهر من مظاهر الحياة. هذا التكيف الذي يقع فيه الإنسان قد يكون قاتلًا ومدمرًا.\nوالرائع في هذا الكتاب، أنه لا يتحدث بنبرة إيجابية فارغة عن شخصية سوية واجهت كل الصعوبات بصلابة وقدرة على التحمُّل، بل نرى في ريبيكا الكثير ممَّا نراه في أنفسنا، فهي تتحدث عن معاناة رفضها لجسدها، وفقدانها الثقة في نفسها، ومحاولات إيذاء النفس، وقيامها بإسقاط ألمها على الآخرين، وفقدان الأمل في الحياة. ورغم هذا الكم من الصعوبات التي نواجهها، فإن ريبيكا تقول ببساطة إن هناك دائمًا مَخرجًا من كل هذا. \nعن المؤلفة: ريبيكا سايلنس، مدربة عالمية رائدة في التعافي العاطفي والعلاقات. نجحت في قيادة أعداد لا تُحصى من الأفراد والأزواج والعائلات لمعالجة أشد التجارب ألمًا والتعافي منها. ريبيكا صوت رائد في مجال تطوير الذات، وشخصية تلفزيونية وإذاعية بارعة، تتمتع بخبرة تزيد على عشر سنوات في التحدُّث إلى الملايين حول القيام بالتنمية الذاتية.\nعن المترجم: ولاء كمال، كاتب ومترجم مصري. صدرت له عدة مؤلفات وترجمات عن الدار المصرية اللبنانية. رُشِّحت بعض أعماله الروائية لعدد من الجوائز المحلية والإقليمية، منها: \"كوش كو\"، \"القداس الأخير\"، \"سيد والعصابة\"، \"أيامي مع كايروكي\". \nاسم المؤلف :- ريبيكا سايلانس \nترجمة :- ولاء كمال\nسنة النشر :- 2025\n\nترجمة ولاء كمال", CategoryId = 5, ImageUrl = "/images/products/9789777955232.webp", Author = "ريبيكا سايلانس", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789777955232" },
            new { Id = 653, Name = "مصر البيزنطية", Price = 415m, Stock = 10, Description = "يسعى كثير من الدارسين بلهَ المؤرخين لكشف حقائق العصور التاريخية المصرية، كلٌّ قدر استطاعته وحسب ما أوتي من مصادر وتجلت له من استنتاجات، ويومًا بعد يوم تنجلي الكثير من الحقائق، من هذه العصور التي حظيت باهتمام المؤرخين فترة الحكم البيزنطي، إحدى أثرى وأهم العصور التاريخية لمصر، على جميع المناحي السياسية والاقتصادية والاجتماعية والثقافية، ولا مجال لإغفال الجانب الديني الذي كان هو المؤشر الأعظم والمحرك الأقوى لجميع مناحي الحياة إبان تلك الحقبة، ثورات سياسية واقتصادية وفكرية وأكثرها دينية عمَّت ربوع مصر وكان لها أثرها على عاصمة الحكم في القسطنطينية، منشآت دينية ظهرت لأول مرة في مصر وامتدت إلى سائر الأقطار المجاورة..صورة حية لذلك المجتمع في مصر البيزنطية..\nاسم المؤلف :- السيد الباز العربى\nمراجع :- طارق منصور \nاشراف :- ايمن فؤاد سيد \nسنة النشر :- 2025", CategoryId = 7, ImageUrl = "/images/products/9789777955256.webp", Author = "تأليف أ.د السيد الباز العريني - تحقيق: أ.د طارق منصور - إشراف: أ.د أيمن فؤاد سيد", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789777955256" },
            new { Id = 654, Name = "لا تحطم ابناءك", Price = 220m, Stock = 10, Description = "تجنب 21 سلوكا تربويا مدمراً .. من اجل مراهقين اسوياء \nهل تُعانين من عصبية أبنائك المراهقين؟ هل تشعرين بأنهم لا يثقون بأنفسهم؟ أو يغلب على سلوكهم العنف والعناد؟ هذه بعض المشاكل التي يُعاني منها كثير من المراهقين.. ولكن هل تعلمين، عزيزتي الأم، أن هذه المشاكل وغيرها قد تكون بسبب أساليبنا الخاطئة في التربية؟ فنحن بدون قصد قد نضر أبناءنا ونُحطِّم نفسياتهم ونؤثر سلبيًّا على سلوكياتهم. ومن هنا تنبُع أهمية هذا الكتاب، فهو يحاول تنبيه الأمهات والآباء إلى أهم وأبرز الأخطاء التربوية المدمرة التي يرتكبونها في حق أبنائهم المراهقين! \nويُعتبر هذا الكتاب بمثابة دليل عملي لكل أُم تسعى إلى تجنُّب الأخطاء التربوية المدمرة، حيث تستعرض المؤلفة 21 سلوكًا تربويًّا خاطئًا، من خلال قصص حقيقية يرويها أصحابها، وتُقدِّم حلولًا واقتراحات عملية بهدف خلق بيئة صحية للأبناء، من خلال منهجية واقعية يمكن تنفيذها في بيوتنا.. وتختتم كتابها بالإجابة عن اثني عشر سؤالًا، من أهم الأسئلة الشائعة حول تربية المراهقين.\nـــــــــــــــــ\nنورهان سيد، إخصائية نفسية وسلوكية للمراهقين. انعكس اهتمامها بالتربية ودعم وإرشاد المراهقين وأمهاتهم على دراساتها الأكاديمية والحرة على مدار حياتها، فحصلت على عدة دبلومات وشهادات متخصصة في علم النفس والإرشاد الأُسري والمدرسي، منها: دبلومة الصحة النفسية، والعلاج المعرفي السلوكي، ودبلومة تعديل السلوك، بالإضافة إلى أنها كوتش معتمدة لدعم المراهقين.\nاسم المؤلف :- نورهان سيد \nسنةالنشر :- 2025", CategoryId = 6, ImageUrl = "/images/products/9789777955263.webp", Author = "نورهان سيد", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789777955263" },
            new { Id = 655, Name = "القاهرة مدينة الفن والتجارة", Price = 275m, Stock = 10, Description = "شهدت القرون الثلاثة الأخيرة اهتمامًا ملحوظًا بتاريخ العمارة في العواصم الإسلامية، ورغم أن القاهرة تمتلك وثائق ومصادر مخطوطة ونشرات جزئية لهذه المصادر، وتحوي كذلك آثارًا ذات حجم يفوق ما تملكه المدن الإسلامية الأخرى، فإنه ينقصها الدراسات التفصيلية التاريخية، ولا حرج أن نقول أنه كان للمستشرقين فضل السبق في دراسة تاريخ القاهرة وآثارها العمرانية ابتداء من \"وصف مصر\" وأعمال أخرى ذات قيمة كبيرة، من ضمنها دراسات حرصت على وضع هذه المنشآت في مضمونها التاريخي، ولعل إحدى أهم هذه الدراسات التي تتسم بالجدة والأصالة وعمق البحث وغزارة المادة، هي ما قام به جاستون فيت، تلك التي جمع فيها بين جانبين قد يراهما المرء على طرفي نقيض، لكن حسن العرض وسلاسة الأسلوب جعلتهما وجهان لعملة واحدة: الفن والتجارة!يسري الفخراني، كاتب وصحفي وأديب، له مؤلفات عِدة من القصص الإنسانية التي تحولت إلى أعمال درامية، أحد أبرز صُناع المحتوى الدرامي في العالم العربي، شارك في تأسيس عدد من الصحف والمجلات والقنوات التليفزيونية.\nاسم المؤلف :- جاستون فييت\nترجمة :- مصطفى العبادى\nتقديم :- ايمن فؤاد سيد \nسنة النشر :- 2025", CategoryId = 7, ImageUrl = "/images/products/9789777955171.webp", Author = "جاستون فييت - ترجمة: أ.د مصطفي العبادي - تقديم ومراجعة: أ.د أيمن فؤاد سيد", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789777955171" },
            new { Id = 656, Name = "مدرسة فى حقيبة", Price = 225m, Stock = 10, Description = "مدرسة في حقيبة\n«طارق» طفل فلسطيني، يعيش مع أهله في خيمة بسبب الحرب الدائرة، يستيقظ ليُمارس نشاطه اليومي في حياة المخيَّمات: جمع الحطب لإشعال النار، وحجز مكان في طابور الحمَّام، وتسجيل اسمه في كشف المعونات. يستعيد ذكرياته مع مَدرَسته، وضحكاته مع أصدقائه: «بَهيّ» و«أحمد» و«منصور». يسأل نفسه: متى سيعود إلى فصله وتعليمه؟ وهل سيرى يومًا مَن تبقَّى من أصدقائه؟! وما السبيل إلى مواصلة تعليمه؟ وهل نسي ما تعلَّمه؟! ثم تبرق في رأسه فكرة، عندما يعرضها على والده لمساعدته في تنفيذها يصفها أبوه بالعبقرية، وبعد التنفيذ تشتهر الفكرة ومعها «طارق»، الذي يسعى لنشرها في أرجاء المخيَّمات؛ ليستفيد منها جميع الطلاب في كل الصفوف. ما هذه الفكرة؟ وما سبب انتشارها؟ وكيف تغلَّب «طارق» بفكرته على صعوبات النزوح من مكانٍ إلى ثانٍ، وإلى ثالث؟! هذا ما سنعرفه في هذه القِصَّة الشَّيقةِ: «مَدْرَسَة في حَقيبَة».\nاسم المؤلف :- منى كمال هاشم\nرسوم  :- حسين الرباعى\nسنة النشر :- 2025", CategoryId = 11, ImageUrl = "/images/products/9789772937738.webp", Author = "منى كمال هاشم", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789772937738" },
            new { Id = 657, Name = "تصالح مع نفسك", Price = 495m, Stock = 10, Description = "في بعض الأحيان نصبح أسوأ أعدائنا، ونخرب نجاحنا وفرصتنا للسعادة الدائمة والإنجاز الشخصي والمهني. يساعدك هذا الكتاب على اكتشاف الأسباب اللا واعية التي تـتبعها لتعيق بها نفسك دون أن تدري. غالبًا بدأ هذا الخلل في مرحلة الطفولة كآلية دفاعية تساعدك على التكيف استجابةً للصدمة. يوجهك هذا الكتاب بمحبة لاستكشاف الوسائل التي أثرت بها هذه الأحداث على حياتك، ويمنحك المعرفة اللازمة كي تصل إلى التحول الحقيقي. قد يؤثر ماضيك على حاضرك دون أن تشعر، ولكنك حتمًا ستشعر بالارتياح حين تدرك أن ما يعيقك ليس افتقادك للإرادة، ولكن عدم معرفة ذاتك كما ينبغي.\nعن المؤلفة لورا كونيل كاتبة كندية ومدربة متخصصة في علاج الصدمات، تساعد عملاءها في الكشف عن الأسباب الخفية التي تعيق تقدمهم. تكتب عن الشفاء من تخريب الذات وديناميكيات العائلات المضطربة. وصلت مقالاتها إلى ملايين القراء عبر عشرات المواقع الإلكترونية والإصدارات المتخصصة. ساعدت دوراتها وفعالياتها عبر الإنترنت الآلاف في التغلب على آثار العائلات السامة.\n---------------------------------------------------------------------------\nعن المترجم ولاء كمال كاتب ومترجم مصري، صدرت له عدة مؤلفات وترجمات عن الدار المصرية اللبنانية. رُشِحَت أعماله الروائية لعدد من الجوائز المحلية والإقليمية ومنها: كوش كو، القداس الأخير، سيد والعصابة، وأيامي مع كايروكي.\nاسم المؤلف :- لورا كونيل \nاسم المترجم :- ولاء كمال\nسنة النشر :- 2025\n\nترجمة ولاء كمال", CategoryId = 5, ImageUrl = "/images/products/9789777955126.webp", Author = "لورا كونيل", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789777955126" },
            new { Id = 658, Name = "شفرة الحياة", Price = 360m, Stock = 10, Description = "كيف لإنسان هذا العصر أن يعيش وسط كل هذا الصخب المثير للأعصاب؟ يحاصره نمط الحياة اللاهثة التنافسية من كل جانب، وتخنقه شوائب الخوف بمجرد أن يفكر في \"الغد\"، ويغذِّي القلق قلبه كلما سعى إلى الارتقاء بحياته.\nإن وصفة سيرس نورث عبارة عن صنارة تتوغل بعمق إلى قاع النفس الإنسانية، ليصطاد بها مشاعر الخوف والقلق والإرهاق الناتج عن سعي إنساني محموم وراء سراب اسمه الغد والمكانة والنفوذ.\nمؤلف هذا الكتاب هو سيرس نورث، صانع محتوى لملايين المتابعين على موقع «يوتيوب»، ومن الشخصيات المؤثرة على مواقع التواصل الاجتماعي، والـ \"شفرة\" التي يقدمها في كتابه تسمح لنا بالسيطرة على مشاعر القلق بشأن الأمور الخارجة عن إرادتنا وهموم التفكير فيما لا نملك، ويساعدنا على اكتشاف طريقة لإعادة تنظيم أولوياتنا النفسية في سبيل أن نضمن سلامًا وسكينة لأرواحنا المتعَبة، من أجل تحقيق الهدوء وإعادة الاتزان النفسي في هذا العالم الذي تتخطفنا فيه كل محفزات القلق.\nاسم المؤلف :- سيرس نورث\nترجمة :- نادية شامة \nسنة النشر :- 2025\n\nترجمة نادية شامة", CategoryId = 5, ImageUrl = "/images/products/9789777955157.webp", Author = "سيرس نورث", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789777955157" },
            new { Id = 659, Name = "العودة للحياة", Price = 385m, Stock = 10, Description = "قد يبدو عنوان الكتاب غريبًا وصادمًا، لكن ينتج عنه سؤال أهم: هل تركنا الحياة؟!\nفي جلسة ودية، جمعت المؤلفة والبروفيسور ريشار ليفي -مدير معهد الذاكرة ومرض الألزهايمر وصاحب مقدمة هذا الكتاب- سألها: إذن، ما المزعج في الاعتماد الكليّ على التكنولوجيا، وأن نجبر المرض والموت على التراجع، وأن نبقى متصلين من دون حاجزي الزمان والمكان؟!\nبعد سنوات من ممارسة علم النفس السريري، وإجراء كثيرٍ من التجارب العلمية، وعبر تسعة فصول تصحبنا المؤلفة في رحلة داخل الإنسان للإجابة عن هذه الأسئلة -بعيدًا عن العالم الافتراضي والرقمي- ولنلمس بأنفسنا التأثير السلبي للمبالغة في الاعتماد على التطبيقات الإلكترونية، وأثرها على صلته بنفسه، وأهمية التواصل الاجتماعي المباشر -سواء في المدرسة والعمل والبيت والمناسبات الاجتماعية.\nاسم المؤلف :- صوفى لافو\nترجمة :- اريج جمال \nسنة النشر:- 2025\n\nترجمة أريج جمال", CategoryId = 5, ImageUrl = "/images/products/9789777955133.webp", Author = "صوفي لافو", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789777955133" },
            new { Id = 660, Name = "7 طرق خفية لمواجهة القلق", Price = 470m, Stock = 10, Description = "إن هذا الكتاب له تأثير طويل الأمد على قارئه، وليس من قبيل الثقة المفرطة أن نقول إن اتباع الإرشادات السلوكية والإدراكية التي تضمّنها هذا الكتاب كفيلة بأن تحاصر قلقك وتضعه في موضعه الطبيعي باعتباره شعورًا عارضًا مثله مثل كل شعور إنساني.\nإن السلاح الناجع الذي ستمنحه لك مؤلفة هذا الكتاب هو الوعي المقاوم للقلق، وذلك عن طريق التركيز على آليات عمل القلق نفسه وليس محتواه الشكلي، إلى جانب تنبيهك على مصدرين خطيرين من مصادر تغذية القلق، وهما التفكير الاجتراري الذي يتسبب في استنزافك، والإغراء بالانشغال الزائد الذي يزيد من حدة العزلة، وهي الأمراض التي سيتكفل هذا الكتاب بمعالجتها وغيرها، ومساعدتك على تجاوز أوقات عصيبة أصبح فيها القلق هو سمة هذا العصر.\nاسم المؤلف :- لين ليونز \nترجمة :- احمد سالم\nسنة النشر :- 2025\n\nترجمة أحمد سلام", CategoryId = 5, ImageUrl = "/images/products/9789777955164.webp", Author = "لين ليونز", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789777955164" },
            new { Id = 661, Name = "هؤلاء يتحدثون عن مصر", Price = 220m, Stock = 10, Description = "هذه شهادات لأشخاص فارق بعضهم الحياة منذ آلاف السنين كرمسيس الثالث والمؤرخ الكبير مانيتون، وبعضهم عاش في القرن العشرين كجمال حمدان وفرح أنطون. بعضهم غير مصريين كهوارد كارتر لكنهم مصريون حتى النخاع وينتمون إلى هذا التاريخ العريق الذي حير العلماء في جميع فنون العلوم وفروعها. القاسم المشترك بينهم أنهم يتحدثون عن مصر وأثر علومها الطبيعية والإنسانية في تقدم كل مَن استلهم الحضارة المصرية القديمة وتاريخها.\nبالإضافة إليهم، استنطق د. وسيم السيسي بعض الجمادات التي شهدت وشاهدت هذه الحضارة، كاللغة المصرية القديمة وأثرها على اللغات في حضارات وممالك مجاورة لها، والهرم الأكبر وأسراره الخفية، وكتاب الموتى وإعجازه في الاختصار وتفصيل ما يجب أن يتحلى به الإنسان المصري القديم وما سيُسأل عنه.\nــــــــــــــــــــ\nالدكتور وسيم رشدي السيسي، أستاذ جراحة المسالك البولية وأمراض الذكورة. إلى جانب نشاطه وإسهامه الطبي في مجال تخصصه، اهتم بقضايا وطنه، فتوصَّل بعد تفكيرٍ عميقٍ إلى أن مصر لن يعود لها وجهها الحضاري، وتصبح رائدة من روَّاد العلوم والفنون، إلا بالاطلاع على تاريخها القديم، كما توصَّل إلى أن وحدة مصر وتوحدها لن يتمَّا  إلا بتاريخ موحَّد.. خصوصًا أن التاريخ الوحيد الذي أصبح عِلمًا يدرسه العالم كله هو علم المصريات (Egyptology)، وهو العلم الذي أبحر بين شاطئيه ليُخرج لآلئه، ويثبت من خلاله لمصر ريادتها في شتى مناحي الحياة. صدر له عدد من الكتب منها : \"مصر علمت العالم\" و \" هذه هي مصر\" و\" في البدء كانت مصر\" و\"المسكوت عنه في التاريخ\" و\"إحنا مين\" و\" أنا.. أتحدث إليكم\".\nاسم المؤلف :- وسيم السيسى\nسنة النشر :- 2025", CategoryId = 7, ImageUrl = "/images/products/9789777955225.webp", Author = "وسيم السيسي", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789777955225" },
            new { Id = 662, Name = "شرق المتوسط - تاريخ فى الصراع (1291-1517م)", Price = 330m, Stock = 10, Description = "يعرض هذا الكتاب لفترة مهمة في تاريخ شرق البحر الأبيض المتوسط، وهي فترة مُلتهبة، امتدت لما يزيد عن القرنين، ما بين عام 1291م وعام 1517م، أي في الفترة من أواخر القرن الثالث عشر الميلادي إلى أوائل القرن السادس عشر الميلادي، فقد كانت القوى الكبرى - في ذلك الوقت - تسعى إلى السيطرة على هذه المنطقة؛ لأن من يحكمها يحكم العالم بأسره.\nيلقي كتاب \"شرق المتوسط\" الضوء على القوى المتصارعة في هذه المنطقة، خلال الفترة محل الدراسة، ويبين العلاقات السياسية والاقتصادية التي نشأت بينها. كما يرصد التغيرات الأساسية في خطوط المواجهة السياسية والعسكرية والثقافية، ويبين أثر العوامل الاقتصادية في العلاقات بين الأطراف المتصارعة، سواء في أوقات السلم أو الحروب.\nشهدت المنطقة - في تلك الفترة - صراعات لا تتوقف، ولعب فيها أدوارًا كبرى، كل من: الإمبراطورية البيزنطية، والمغول، ودولة المماليك، والدولة العثمانية. كما شهدت حدثين من الأحداث الكبرى في التاريخ؛ أولهما: اجتياح المغول للعالم الإسلامي، لكن المماليك استطاعوا إيقافهم، وثانيهما: إنهاء الوجود الصليبي فى الشرق، عندما تصدى المماليك لمحاولات الدول الأوروبية الاستيلاء على الشرق، بدعوى حماية الأماكن المقدسة.\nــــــــــــــــــــ\nعلياء المغني، كاتبة إماراتية، ومدربة دولية معتمدة منذ عام 2019م. حصلت على ماجستير التاريخ والحضارة الإسلامية بجامعة الشارقة (2017م). حاصلة على الدكتوراه من جامعة عين شمس (2024م). تعمل مسؤولة محتوى في إحدى الشركات الإعلامية منذ عام 2014م. لها خبرات عريضة في الأنشطة الثقافية والتراثية، وتنظيم المعارض، وإعداد الأفلام الوثائقية، والتخطيط للبرامج وتنفيذ الفعاليات. شاركت في عدد كبير من الدورات التدريبية، وهي عضوة في كثير من الجمعيات الأهلية والتطوعية في دولة الإمارات وخارجها.\nاسم المؤلف :- علياء المغنى \nسنة النشر :- 2025", CategoryId = 7, ImageUrl = "/images/products/9789777955140.webp", Author = "علياء المغني - تقديم أ طارق منصور", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789777955140" },
            new { Id = 663, Name = "حكايتى مع الصحافة", Price = 275m, Stock = 10, Description = "يقف جميل مطر في هذا الكتاب على تخوم الأدب والصحافة والسياسة والعمل الدبلوماسي وكتابة الرحلة، حيث يسرد بأسلوب مشوق ولغة ساحرة رحلته في العمل الدبلوماسي، وكيف نجا من الفخاخ التي نصبها له زملاء ورؤساء عمل، وكيف تعلم فك الرسائل المشفرة، وكيف أبقاه عمله في قراءة وتلخيص الصحف على اطلاع واسع بما يدور في بلاط صاحبة الجلالة، وكيف أعجب بمحمد حسنين هيكل قبل أن يراه بفترة طويلة، وقبل أن يدعوه للعمل بمركز الأهرام للدراسات السياسية والاستراتيجة. لم يصدق مطر نفسه، فقد أصبح جزءا من المؤسسة التي حلم بالعمل فيها، منذ نعومة أظافره، إذ تربى في بيوت تقدس جريدة الأهرام. أصبح بإمكانه مشاهدة اجتماعات الطابق الرابع المهمة ومشاركة الزملاء في المطبخ الصحفي، لكن هيكل يحذره من الظهور المتكرر في ذلك الطابق وينصحه بأن يبتعد عن الصحفيين. يدرك مطر بمرور الوقت لماذا طلب منه هيكل ذلك، وتنمو علاقتهما حتى تصل إلى درجة الندية ثم الصداقة، ويدعوه هيكل إلى حضور جلسات السمر والعمل المهمة في بيته ببرقاش حيث تُطبخ الأحداث وتُكتب الحكايات، ويطلب منه هيكل مرافقته في رحلتين طويلتين، فيصبح بإمكان مطر أن يلمس عن قرب كيف يعامل هيكل الأباطرة والرؤساء والزعماء، ويضيف إلى رصيده في بنك الحكايات والأسرار. \"حكايتي مع الصحافة\" ليس مجرد كتاب سيري، لكنه شهادة مهمة على العمل السياسي والدبلوماسي والصحفي في مصر وعدد من دول العالم. كتاب لا يفتقر إلى الصراحة والصدق ويجمع بين صرامة المعلومة وعمق التحليل وأناقة الوصف وجاذبية القصة، والقدرة على رسم صور مذهلة لكثير من الأسماء الكبرى في عالمي الصحافة والدبلوماسية.\nاسم المؤلف :- جميل مطر \nسنة النشر :- 2025", CategoryId = 7, ImageUrl = "/images/products/9789777955072.webp", Author = "جميل مطر", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789777955072" },
            new { Id = 664, Name = "حلت البركة", Price = 200m, Stock = 10, Description = "\"ومن طاقة الحب وقانون التفاهم.. كان للبيوت طعم الدفء ومعنى البهجة، كان هو المساحة الكافية لكي تناقش فيه العائلة مشاكلها لتصل إلى بر الأمان، وكان هو المسافة الحقيقية بين كل فرد في البيت الواحد، كان هو العيد وهو السعادة وهو بيت العمر!\".\n***\nبـ \"شيش\" شباك موارب وقت ظهيرة، وراديو عتيق يحتل ركنًا من أركان البيت بثقة وشموخ، صنع المؤلف نصًا ناعمًا يواسي به جيل السبعينيات والثمانينيات المحاصرين بثقافة عصر جديد لا ترحم حنينًا ولا تحترم خصوصيةً، في الدين والفن والرياضة والأخلاق. أما الأماكن، فكأنك تتمشى على بحر الإسكندرية ورأس البر، تحاصرك رائحة اليود وأصوات البائعين و\"استلم صورتك على البحر بعد نص ساعة\"، وهدايا \"كروت البوستال\" بعد كل سفرية.\nلم يكن يسري الفخراني -حين كتب هذه المقالات- يسترجع الذكريات فحسب، بل جلس في \"بيت من سبع غرف وصالة\"، \"مع الذين أحبوا الحياة\"، وفعل \"كما كان يفعل أبي\"، فكتب \"رسالة إلى ابنتي\"، وكان \"مع الله\".\nـــــــــــــــــــــــــ\nيسري الفخراني، كاتب وصحفي وأديب، له مؤلفات عِدة من القصص الإنسانية التي تحولت إلى أعمال درامية، أحد أبرز صُناع المحتوى الدرامي في العالم العربي، شارك في تأسيس عدد من الصحف والمجلات والقنوات التليفزيونية.\nاسم المؤلف :- يسرى الفخرانى \nسنة النشر :- 2025", CategoryId = 7, ImageUrl = "/images/products/9789777955102.webp", Author = "يسري الفخراني", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789777955102" },
            new { Id = 665, Name = "ما بين امبراطوريتين مصر فى القرن السادس عشر", Price = 360m, Stock = 10, Description = "ما بين إمبراطورتين\n \nهذا الكتاب محاولة لبناء سردية مغايرة بهدف فهم تاريخ مصر أثناء تحولها من الدولة المملوكية الى الدولة العثمانية، وتتبُّع التطورات التي شهدتها في القرن السادس عشر، من خلال رؤية مَن كانوا يعيشون فيها؛ لذا تستخدم المؤلِّفة المصادر المحلية رغم نُدرة وغيبة الحوليات التي تُغطِّي تلك الفترة، وقد حاولت - كما تقول - إعادة بناء سردية اعتمادًا على مصادر متنوعة مشتتة، وفي الغالب غير تقليدية، مثل الأعمال الأدبية، والرسائل الفقهية، وكتب الرحلات، وكذلك الاعتماد على المصادر الإقليمية وبخاصة للكُتَّاب اليمنيين والشوام، والتي لم تُستخدم لهذا الغرض من قبل. وبالرغم من محدودية هذه المصادر، إلا أنها في غاية الأهمية لفهم تاريخ مصر في القرن السادس عشر، وكذلك فهم تاريخ الإمبراطورية العثمانية برؤية مختلفة، حيث يُفهم تاريخ الإمبراطورية من خلال منظور مختلف عن زاوية عاصمتها، وفي نفس الوقت تسمح لنا هذه الرؤية بإدماج كل من الإقليم والمركز في سردية واحدة.\n \nــــــــــــــــــــــــــــــ\nنللي حنا، مؤرِّخة مصرية مرموقة، وأستاذ مميز بالجامعة الأمريكية بالقاهرة. حصلت على الدكتوراه في التاريخ العثماني من جامعة إكس أون بروفانس بفرنسا، بعد أن درست الأدب الإنجليزي في الجامعة الأمريكية بالقاهرة، وحصلت على الماجستير من الولايات المتحدة. نشرت عددًا من المؤلفات الرصينة، منها: «مصـر أم الدنيا: قصة القاهرة في 1300 عام»، و«تجار القاهرة في العصر العثماني: سيرة أبو طاقية شاهبندر التجار»، و«مصر العثمانية والتحولات العالمية 1500-1800م».\nاسم المؤلف :- نيللى حنا \nسنة النشر:- 2025", CategoryId = 7, ImageUrl = "/images/products/9789777955089.webp", Author = "نللي حنا", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789777955089" },
            new { Id = 666, Name = "بخلاف ما سبق", Price = 330m, Stock = 10, Description = "في شتاء تبدأ هذه الرواية وفي شتاء تنتهي. وبين البداية والنهاية فصول تتوالى، لم يدرك سامي يعقوب ما تخفيه له، رغم ما يتمتع به من قدرة على رؤية المستقبل.\nكان قد أكمل شهرين وعشرة أيام مختبئًا في شقته، لا يفتح بابه لأحد، لكن طرقًا خفيفًا على بابه تكرر عند الفجر يومًا بعد يوم، فاضطر أن يفتح ليجد غلامًا يطلب منه التوجه إلى «تل المساخيط» لكي يتسلم بستانًا منسيًّا لجده. يفاجأ سامي بجمال البستان ويقرر ألا يغادر تلك الجنة، حيث تتناثر، تحت الأشجار المتشابكة، بيوت صغيرة لا يرى ما يجري بداخلها إلا الله.\nابن جاردن سيتي الذي رأينا صداقته مع الكلاب والفراشات في رواية «ما رآه سامي يعقوب»  وجد نفسه في هذه الرواية مسئولًا عن حديقة حيوان، فيها من الجمل إلى الدجاجة، منح لكل منها اسمه، وتفهَّم مشاعره وطباعه، كما علَّمه مساعده الطيب سمعان أبانوب الأسيوطي كيف يستمع إلى الشجر.\n تتجلى وحدة الوجود في الرواية، ويمتزج السحري بالواقعي، والحب بالعنف، وتتردد في صفحاتها أصداء تلاوة القرآن والإنجيل وأغاني النوبة.\n«بخلاف ما سبق» ليست مجرد رواية، بل شهادة عن هُوية مصر وروحها العالقة بين حاضر وماضٍ لم يحسما صراعهما.\nاسم المؤلف :- عزت القمحاوى\nسنة النشر :- 2025", CategoryId = 1, ImageUrl = "/images/products/9789777955096.webp", Author = "عزت القمحاوي", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789777955096" },
            new { Id = 667, Name = "اتعاظ الحنفا بأخبار الأئمة الخلفا 2 مجلد", Price = 1320m, Stock = 10, Description = "اتِّعاظُ الحُنَفَا بِأخَبَارِ الأَئِمَّةِ الخُلَفَا» لِتَقي الدِّين أحمد بن عَليّ بن عَبد القادر المَقرِيزي، وهي الموسوعة الأهم التي تتناول تاريخ الدولة الفاطمية، التي تمثل الخلافة الشيعية الوحيدة في تاريخ الدولة الإسلامية، منذ دور الستر الذي بدأ بعد وفاة الإمام جعفر الصادق، سنة 148هـ/765م، وحتى الانقلاب السلمي الذي قاده سنة 567هـ/1171م صلاح الدين يوسف بن أيوب، آخر وزراء الفاطميين في مصر، والذي وضع نهاية لهذه الدولة بعد أن استمرت بها أكثر من مئتي سنة، وأعاد مصر مرة أخرى إلى قلب العالم الإسلامي السني. والكتاب - الذي صدر في مجلدين بطباعة فاخرة - له خطورته في دراسة تاريخ الدولة الفاطمية؛ إذ إن مؤلفه اعتمد في كتابته على أهم المصادر المعاصرة أو التي كتبت بعد سقوط الدولة بوقتٍ قصير، وعلى الأخص في فترتها المصرية، التي فُقدت أصولها الآن وحفظ لنا منها المقريزي نصوصًا مطولة، هي النصوص الوحيدة التي نستطيع من خلالها أن نعيد قراءة تاريخ هذه الدولة في مصادره الأصلية. ويتناول الكتاب بالمنهج الحولي تاريخ الدولة الفاطمية منذ أصولها الأولى في دور الستر حتى إعلان قيام الخلافة الفاطمية في إفريقية (تونس الحالية)، ثم انتقالها إلى مصر مع القائد جوهر الصقلي والإمام المعز لدين الله حتى سقوط الدولة على يد صلاح الدين يوسف بن أيوب في مطلع سنة 567هـ/1171م. حقق الكتاب د. أيمن فؤاد سيد، أحد كبار المتخصصين في دراسة التاريخ الفاطمي وصاحب كتاب «الدولة الفاطمية في مصر – تفسير جديد»، والذي أخرج العديد من النصوص الأصلية للتاريخ الفاطمي. وقد أثرى الكتاب بالعديد من الهوامش العلمية والإحالات إلى المصادر الرئيسة والدراسات العربية والأجنبية الحديثة، وأصدرته الدار المصرية اللبنانية بالقاهرة في طبعة أنيقة، فاخرة، احتفالًا بمرور أربعين عامًا على تأسيسها، وفي إطار إسهامها بإثراء المكتبة العربية بالعديد من الدراسات المهمة لأعلام المؤلفين والدارسين العرب.\nاسم المؤلف :- تقى الدين احمد بن على بن عبد القادر المقريزى\nاعداد للنشر :- ايمن فؤاد سيد \nسنة النشر :- 2025", CategoryId = 7, ImageUrl = "/images/products/9789777954907.webp", Author = "لتقي الدين أحمد بن علي بن عبدالقادر المقريزي - شرح وتعليق: أ.د أيمن فؤاد سيد", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789777954907" },
            new { Id = 668, Name = "حكايات منسية - سيرة ناس عاشوا خارج الزمن", Price = 220m, Stock = 10, Description = "\"تلك هي الروح التي أبقتني على قيد الحياة، نعم.. أنا بنت اللين والأسى كما يقول أبي، أملك مرونة أخطبوط مجبر على تسلق الجبال، ظهري مرتع للأحمال، الأسى مكتوب على جبيني، قدر حتمي الصيرورة، أهادن الحياة حتى لو بغت، قادرة على التجاوز، أمحو أمس بكل أوجاعه، أستقبل يومي بحلم جديد، بطاقةٍ تملك لمس أهداب السماء، هذه أنا\".\n***\nما بين حكايات الوطن وحكاوي قرية الصوامعة غرب- مركز طحطا، تضفر الكاتبة الأحداث لتسرد تاريخًا منسيًّا: يونس وأولاده، وعودة الأسير، وسطوة لملوم على البلد والعمدة، عادات الصعيد قبل زحف المدنية، ولماذا تكون الإسكندرية الخيار الثاني لفقراء الصعيد بعد القاهرة؟\nحكايات تولد من رحم أخرى، وكأنها لا نهاية لها، لفرط واقعيتها تـكاد لا تُصدَّق.\nـــــــــــــــــــــــــــ\nسعاد سليمان، كاتبة مصرية، حاصلة على جائزة اتحاد كتاب مصر عن رواية «غير المباح»، وجائزة متحف الكلمة العالمية عن قصة «تشابه»، وشهادة تقدير من المجلس الأعلى للثقافة عن المجموعة القصصية «هكذا ببساطة». صدر لها عدد من الروايات والمجموعات القصصية، منها: آخر المحظيات، هبات ساخنة، شال أحمر يحمل خطيئة، الراقص.\nاسم المؤلف :- سعاد سليمان \nسنة النشر :- 2025", CategoryId = 1, ImageUrl = "/images/products/9789777955065.webp", Author = "سعاد سليمان", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789777955065" },
            new { Id = 669, Name = "الطب الروحانى ورسائل فلسفية", Price = 330m, Stock = 10, Description = "إن هذه السلسلة من كلاسيكيات الفلسفة تأليفًا وترجمة هي أبرز ما قامت عليه نهضتنا الحديثة، وهي ما تربت عليه الأجيال السابقة.\n \nوما أحوجنا اليوم لإعادة نشر هذه الكلاسيكيات من مؤلفات ومترجمات رائدة لتستفيد منها أجيالنا الشابة، وخاصة في ظل ندرة ما يكتبه المتخصصون المعاصرون في الفلسفة ومجالاتها المختلفة، وفي ظل غياب المنهج الفلسفي للتفكير في حياتنا المعاصرة، مما كان السبب المباشر لما نراه من تطرف وتعصب وجمود وعدم تقبل الآخر وفقدان القدرة على التحليل ونقد الأفكار.\n \n***\n \nإن النضوج الفكري الذي صاحب القرن الرابع الهجري أنتج لنا العديد من العقليات العلمية والفلسفية التي أنارت الحضارة الإسلامية - بل العالم - بفكرها، كان الفيلسوف أبو بكر محمد بن  زكريا الرازي أحد أعلام تلك الحقبة، وقد شغل العالم بفلسفته وآرائه حتى صار مثار جدل بين فلاسفة الإسلام، وكان لجمعه بين الطب والفلسفة أكبر أثر في منهجه، فعمد إلى طرق مبتكرة في التعامل مع طب الأخلاق والطب النفسي، انطلاقًا من رؤيته للعقل، واعتمادًا على الشك المنهجي المؤقت والتجريب والتأني في إصدار الأحكام، فدوَّن في الطب الروحاني واللذة والعلم الإلهي ما جعل جامعات العالم تتسابق إلى دراسة فكره ومعرفة كُنْه الفيلسوف الفاضل الحق.\nاسم المؤلف :- ابو بكر محمد بن زكرياء الرازى\nتقديم :- خالد عزب \nجمعها وصححها :- بول كرواس \nمراجعة :- مصطفى النشار \nسنة النشر :- 2025", CategoryId = 7, ImageUrl = "/images/products/9789772937721.webp", Author = "ابو بكر محمد بن زكريا الرازى", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789772937721" },
            new { Id = 670, Name = "ملحمة المطاريد 3 جزء", Price = 935m, Stock = 10, Description = "تتناول هذه الملحمة سيرة خمسة قرون، عَبْرَ ستة عشر جيلًا، تتشرَّب روح مصر، تغرف من الواقع، وتنفخ فيه من الخيال، لتُقدِّمه في لغةٍ عذبة، تُناسب ما يجب أن تتهيَّأ له الملاحم الأدبية، ثم تُطلق سردًا متدفقًا يجعل القارئ - رغم طول الحكاية - يلهث وراء السطور، ويطارد تسارع وتصاعد الأحداث.\nوقد صدرت «ملحمة المطاريد» في ثلاثة أجزاء، لترصد ملامح الصراع على الثروة والمكانة، من خلال عائلة أُجبرت على ترك قريتها التي أسَّستها، وساحت في البلاد، دون أن ينسى الأحفاد وصية الأجداد التي تُطالبهم باستعادة ما كان لهم، لتنطلق رحلة مطاردة قاسية في ريف مصر، تصوِّر عراك الفلاحين مع فيضان النيل وجفافه..\nإنها ملحمة مصرية عن الأمل الذي يجب أن يسكن الرؤوس والنفوس، ويلوح دومًا أمام العيون إشارة زاهية تدل على الطريق، مهما اشتدت الأحوال، وتراخت الهمم، وتباعدت المسافات، وتتابعت الأزمنة، وضعفت الذاكرة.\nـــــــــــــــــــــــــــ\nعمَّار علي حسن، أديب ومفكر مصري، أنجز ستين كتابًا، نصفها أعمال أدبية، عبارة عن روايات، ومجموعات قصصية ومسرحية، وديوانَي شعر، ونصوص سردية، فيما تتوزَّع كتبه على النقد الثقافي والاجتماع السياسي والتصوف. أُعدت حول أعماله الأدبية عشرون أطروحة جامعية، وتُرجمت بعض كتاباته الأدبية والفكرية إلى عدة لغات.\nاسم المؤلف :- عمار على حسن \nسنة النشر :- 2025", CategoryId = 1, ImageUrl = "/images/products/9789777955034.webp", Author = "عمار على حسن", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789777955034" },
            new { Id = 671, Name = "بيت امن - حكاية اربع سنوات نقلتنى من الألم للأمل", Price = 240m, Stock = 10, Description = "الحقيقة التي أدركها الإنسان منذ أن وجد: أنه يولد فيكافح ويشقى ويمرض ويفقد الأحباب ويتألم كثيرًا ثم يموت. أما ما ينعم به من لحظات السعادة والرضا والإنجاز فإنه ينتشلها بالإرادة والإصرار.. والحظ أحيانًا. نؤمن أن لهذه الخطة الكونية حكمة كبرى، لكن عقولنا لا تدركها.. ولا يمكن أن تدركها. فما المخرج؟\nوللإجابة عن هذا السؤال.. تأخذنا الكاتبة في رحلة استكشاف لأعماق النفس والمجتمع في آن، ولا تكتفي بالنقد، بل تطرح بالمقابل طريقًا للمواجهة وحلولًا نابعة من التدبر والمعايشة.\nفنحن لا ننقذ من رحلوا، بل نستكمل رسالتهم. والألم لن يذهب، لكن بوسعنا أن نتصالح معه. وهو ما أهدتنا إياه أمل صديق عفيفي.. خارطة رحلتها من الألم إلى الأمل.\nـــــــــــــــــــــــــــ\nكاتبة وفنانة مصرية حاصلة على دكتوراه في إدارة الأعمال من جامعة\"استون\" بإنجلترا، لها روايات عديدة منها: (الميراث)، و(نقطة ومن أول السطر) و(الرقص على الحبال)، بالإضافة إلى سلسلتي كتب الأطفال (رحلة الزمان) و(حكايتنا كلنا). كما شاركت في كتابة سيناريو عديد من الأفلام الروائية، منها (الخروج من القاهرة) الذي حصل على  جائزتي أفضل فيلم غير أوروبي في مهرجان الأفلام المستقلة بباريس، ومهرجان ميونخ بألمانيا، ومن بعده فيلم (التمن) المقتبس من رواية (ديما).كما شاركت الكاتبة في معظم معارض الفن التشكيلي.\nاسم المؤلف :- امل صديق عفيفى \nسنة النشر :- 2025", CategoryId = 1, ImageUrl = "/images/products/9789777955058.webp", Author = "أمل صديق عفيفي", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789777955058" },
            new { Id = 672, Name = "يهود الظاهر", Price = 315m, Stock = 10, Description = "\"إن شاء الله\nفي شارع الضاهر\nفي ساحة المعبد\n تنشر شجرة الجوافة أريجها\"\n أندا هاريل داجان\nمن قصيدة شاعرة يهودية انتمت إلى حركة \"هاشومير هاتسعير\" الصهيونية، وظلت رغم هجرتها إلى إسرائيل تشعر بالحنين لحيّها القديم: حي الظاهر. \n***\n\"ليلة الأحد تتصاعد رائحة طعمية موسى فلفل ويقف الناس زحامًا للشراء، لا فرق بين مسلم ويهودي. كانت طعمية لها شهرتها.. طعمية اليهودي\".\n صافي ناز كاظم\n***\nمن ذكريات يهود الحي وجيرانهم، نغوص في تاريخ العائلات القرائية المنسية مثل: ليشع ومسعودة ومرزوق والسرجاني التي استوطنت حي الظاهر الشهير بوسط القاهرة، الذي ما زال يحتفظ بمعابدهم ومدرستهم الإسرائيلية، وما زال في وجدان سكانه ذكريات عن البقال \"حاييم\" ومطحن \"بيسح\" للبُن والدُّقة، ونتطرق إلى دور السينما التي جعلتها الصهيونية بوقًا لها لتحول الحي إلى ثكنة عسكرية لتجنيد سكانه اليهود في أعمال جاسوسية، ومنهم الطبيب موسى مرزوق الذي تورط في \"عملية سوزانا\" الشهيرة.\nـــــــــــــــــــــــــــ\nسهير عبد الحميد،  كاتبة صحفية - مدير تحرير الأهرام  وباحثة في التاريخ، صدر لها: قصور مصر، إسكندرية من تاني، اغتيال قوت القلوب الدمرداشية، على عتبة المقام، سلسال الباشا، ناحوم أفندي.\nاسم المؤلف :- سهير عبد الحميد \nسنة النشر :- 2025", CategoryId = 7, ImageUrl = "/images/products/9789777955041.webp", Author = "سهير عبد الحميد", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789777955041" },
            new { Id = 673, Name = "بنت السلطان", Price = 200m, Stock = 10, Description = "بنت السلطان\n\"وذهبت إليها..\nوهي تنظر إليّ بعينين مشدوهتين.. لم تكن تصدق أني أنا.. أنا الصحفي المشهور.. المحرر الأول بمجلة الكواكب.. يذهب إليها!\nودعوتها إلى الغداء..\nوكان هذا حدثًا غريبًا آخر في حياتي.. فحتى ذلك اليوم كنت أفضل دائمًا مقعد المدعو، على مقعد الداعي!!\nثم بدأت ألقاها كل يوم..\".\nـــــــــــــــــــــــــــ\nولد أول يناير 1919 بالقاهرة، تخرج في كلية الحقوق عام 1942.  بدأ حياته كاتبًا سياسيّا ورئيسًا لتحرير مجلة روزاليوسف التي أسستها والدته فاطمة اليوسف. فجّر قضية الأسلحة الفاسدة التي استخدمت في حرب فلسطين.  تقلد عددًا من المناصب الصحفية كان آخرها رئيسًا لتحرير ولمجلس إدارة مؤسسة الأهرام، وبعدها تفرغ للكتابة حتى وفاته 11 يناير 1990.  أنتج المئات من الروايات والمجموعات القصصية التي تحوّل معظمها إلى أعمال سينمائية وإذاعية وتليفزيونية. حصل على العديد من أرفع الأوسمة والجوائز وشهادات التقدير المحلية والعالمية.\nاسم المؤلف :- احسان عبد القدوس\nسنة النشر :- 2024", CategoryId = 1, ImageUrl = "/images/products/9789777954983.webp", Author = "إحسان عبد القدوس", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789777954983" },
            new { Id = 674, Name = "شجرة البؤس", Price = 200m, Stock = 10, Description = "شجرة البؤس\n   \"وكذلك كانت حياةُ خالد عذابًا متصلًا بين ابنتيه وزوجه، يدفعه إليهن الحبُّ والبر والعطف،ويصرفه عنهن الشيطانُ بما يتنكَّر من صورٍ، وما يزين في قلبه من شرٍّ، حتى أصبح لا يجد الراحةَ ولا الأمنَ إلا إذا خرج من داره، وتحدث إلى أصدقائه وأترابه. وأي راحة وأي أمن! فقد كان الشيطان يألف أصدقاء خالد وأترابه. وما أكثرَ ما يألف الشيطانُ من الناس! وكان يطلق ألسنتَهم بكثيرٍ من القول، فيه الإغراءُ بالمنكر، وفيه الصّرف عن المعروف، وفيه هذه الأحاديث التي يألفُها الشّبابُ في القرى عما يأتونَ، وما يدعون إذا خلوا إلى أهلِهم، ثم فيه هذه الأحاديثُ التي تمتلئ بالأماني الآثمةِ والأحلام التي نُسجت من الخطايا نسجًا، فيه هذه الأحاديث التي يظهر فيها الخيرُ والطاعةُ، ويستتر فيها الإثمُ والفجور\".\n                                                                                                                                                             طه حسين\n \nمن خلال هذه السلسلة، نستحضر الأعمال الإبداعية والتاريخية والدراسات النقدية لعميد الأدب العربي - الدكتور طه حسين، التي جعلت من صاحبها نموذجًا ننظر إليه بفخر ونستلهم تجربته.\nوما أحوجنا إلى أن تقرأ الأجيال الجديدة هذه الأعمال، التي تقدمها الدار المصرية اللبنانية مع ترجمة وافية عنه، وشروح لبعض الألفاظ، وتعريف بالأعلام والأماكن الواردة فيها، على يد نخبة من الأساتذة؛ كلّ في مجاله.\nاسم المؤلف:- طه حسين\nسنة النشر :- 2024", CategoryId = 8, ImageUrl = "/images/products/9789777954990.webp", Author = "طه حسين", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789777954990" },
            new { Id = 675, Name = "المعذبون فى الارض", Price = 190m, Stock = 10, Description = "المعذبون في الأرض\n   \"لم يوجد صالح قط؛ لأنه يملأ المملكةَ المصرية، وإذا أسرف الشيء في الوجود فهو غيرُ موجودٍ، سواء أَرَضِيتِ الفلسفةُ عن هذا الكلام أم لم ترض، أما أمين فموجودٌ من غير شكٍّ، لأننا نراه ولا نكاد نرى غيره، لأنه عظيمُ الخطر، فهو هذا الصَّبيّ الذي لا ينام جائعًا إذا أقبل الليلُ، ولا يغدو طاويًا على المدرسة أو على الكتّاب، ولا يطولُ انتظارُه للغداءِ إذا آن وقتُ الغداء، ولا يَنبغي أن يطولَ انتظاره للعشاء إذا أقبلَ الليلُ، لأن من حقه أن يتناولَ الطَّعَامَ في إبانه، وأن يأخذ قسطه من النوم حتى لا تتعرض صحتُه الغالية لبعض ما يؤذيها. هذا الصبيُّ أو هذا الفتى الذي اتفقنا على أن اسمَه أمين موجود من غير شكٍّ، لأنه لا يملأ القرى، ولا يملأ المدن\".\n                                                                                                                                                              طه حسين\n \nمن خلال هذه السلسلة، نستحضر الأعمال الإبداعية والتاريخية والدراسات النقدية لعميد الأدب العربي - الدكتور طه حسين، التي جعلت من صاحبها نموذجًا ننظر إليه بفخر ونستلهم تجربته.\nوما أحوجنا إلى أن تقرأ الأجيال الجديدة هذه الأعمال، التي تقدمها الدار المصرية اللبنانية مع ترجمة وافية عنه، وشروح لبعض الألفاظ، وتعريف بالأعلام والأماكن الواردة فيها، على يد نخبة من الأساتذة؛ كلّ في مجاله.\nالمؤلف :- طه حسين\nسنة النشر :- 2024", CategoryId = 8, ImageUrl = "/images/products/9789777955003.webp", Author = "طه حسين", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789777955003" },
            new { Id = 676, Name = "الملكة القانونية", Price = 495m, Stock = 10, Description = "الملكة القانونية\nالملَكَة القانونيّة هي صفات جامعة تقوم على جَعبة من الاستعدادات والقدرات والمهارات والمُمَكِّنات اللازمة للمُمارس القانونيّ في سبيل التعامل مع النصوص القانونيَّة، والوقائع القضائيّة، وأطراف الدعاوى، بكفاءة مهنيَّة، وعُمقٍ إنسانيٍّ، ورُقيٍّ أخلاقي، بما يستلزمه ذلك من قدراتٍ لغويَّة، ومنطقيَّة، ونفسيَّة، واجتماعيَّة ومسلكيّة.\nحتّى تكتمل منظومة الملكة القانونية بحلقاتها الخمسين، عايش المؤلّف لسنوات طويلة، كتابات فنّ القضاء ودراسات صنعة المحاماة، وبحوث مهارات الوساطة والتفاوض والتحكيم، وطروحات علوم النفس والاجتماع، ومجلّدات المنطق ومناهج التفكير، وموسوعات اللغة شعرًا ونثرًا، أدبًا ونقدًا، صرفًا وبديعًا ليخرج منها بهذا الكتاب الذي يصدر عن إيمانٍ عميقٍ بالروح الجامعة المتكاملة للمَلَكة القانونيّة، تحتشد فصولها وحلقاتها، لتدب فيها الحياة، كأنّها رفيق القانوني في رحلته، يسعفه إذا نطق، ويلهمه إذا كتب، ويسدّده إذا بحث أو فكّر أو اجتهد.\n \nإنّ جميع حلقات الكتاب ممّا ينبغي لأيّ مختصٍّ في الحقل القانوني الإلمام به، والتشبُّع بفكرته، وامتلاك ناصيته، قاضيًا كان أم محاميًا مُوَكّلًا، أم حَكَمًا مُعيّنًا، أم وسيطًا مُختارًا، أم مستشارًا مُفتِيًا، أم فقيهًا مُفَسِّرًا، أم صائغًا مُشتَرِعًا، أمَّن هو سواهم من سكّان عالم القانون الزاخر الرحيب، أيًّا كان موقعك في هذا العالم، فإنّا ندعوك إلى تأمّل الحلقات الخمسين التي تشتمل عليها المَلَكَة، ومراجعة مدى إتقانك لكلٍّ منها وحساب ما حصلت عليه من درجات، مانحًا كلّ حلقةٍ درجة، فكم درجةً لديك؟\nـــــــــــــــــــــ\nأحمد حمدان قاض بمحكمة الاستئناف، درس ماجستير العلوم القانونية بجامعة لندن، والدكتوراة في علوم تسوية المنازعات بجامعة ستراثكلايد بجلاسجو، له خبرة في العمل القضائي، والبحث القانوني وصياغة التشريعات، وتأهيل القضاة والمحامين والوسطاء لأكثر من عشرين عامًا. أصدر العديد من الكتب والبحوث والمقالات، و\"المَلَكَة القانونيّة\" هو كتابه الخامس.\nالمؤلف :- احمد حمدان\nسنة النشر :- 2024", CategoryId = 8, ImageUrl = "/images/products/9789777954976.webp", Author = "أحمد حمدان", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789777954976" },
            new { Id = 677, Name = "صيف سويسرى", Price = 200m, Stock = 10, Description = "“تمددنا والنور مضاء. ثم والنور مطفأ. تضحك في العتمة وأنا أهمس أن الضحيّة باتت في أحضان جلّادها. تركنا وراءنا المصطلحات السقيمة وانشغلنا بما نحن فيه. رجل وامرأة فحسب يجتمعان وبينهما ملاك. نركن السنوات جانباً ونجرّب الحب المتأخر. نخفق أو ننجح. مرّت علينا سنوات عجاف وجفاف. نسينا فنون المعاشرة. لكن الحب مثل السباحة وركوب الدراجة. مهارة يتركها المرء ولا ينساها. يغطس في الماء ويحرّك ذراعيه وساقيه ويعوم. يحتويه الحضن الضامئ.  ***  \"صيف سويسري\" هي حكاية أربعة عراقيين يلتقون في بازل لتجربة عقار لعلاج الإدمان العقائدي. أحزابهم أعطبتهم ودمرّت بلدهم. وكانت المدينة السويسرية تقدّم إليهم البونبونات وتعيد وصل حبّ مؤجل.  ــــــــــــــــــــــــ\nإنعام كجه جي: صحافية وروائية عراقية ومخرجة أفلام وثائقية. وُلِدت في بغداد ودرست الصحافة في جامعتها. تُقيم في باريس وتعمل في مجال الصحافة. صدر لها: \"لورنا، سنواتها مع جواد سليم\" - سيرة روائية. \"كلام عراقيات\" - مختارات مترجمة إلى الفرنسية من نصوص الحروب، و\"بلاد الطاخ طاخ\" - مجموعة قصص. ومن الروايات: \"سواقي القلوب\". \"الحفيدة الأميركية\". \"طشّاري\". \"النبيذة\". اختيرت الروايات الثلاث الأخيرة في القوائم القصيرة لجائزة الرواية العربية وترجمت إلى عدة لغات.\nاسم المؤلف:- انعام كجه جى \n سنة النشر:- 2024", CategoryId = 1, ImageUrl = "/images/products/9789777954952.webp", Author = "انعام كجه جي", PublishDate = new DateTime(2024, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789777954952" },
            new { Id = 678, Name = "امبراطورية ميم", Price = 200m, Stock = 10, Description = "\"إنها قصتي مع عائلتي.. لقد تزوجت منذ خمسة وعشرين عامًا.. وكنت موفقًا في اختيار زوجتي.. إنها تمثل الخطوة الأولى والأساسية في طريق النجاح الذي سرت فيه.. زوجة مثالية.. ذكية.. مدبرة.. مطيعة.. تحبني.. وتؤمن بي... وقد أنجبنا ستة أولاد... كل أسمائنا تبدأ بحرف الميم.. من أول أبي حتى آخر أولادي.. إني أتفاءل بحرف الميم.. ولكن.. بجانب التفاؤل كان هناك إحساس آخر يضطرم في داخلي.. إحساس يملؤني زهوًا وغرورًا.. كنت أحس كأني أقيم إمبراطورية شعارها حرف الميم..\"\n اسم المؤلف:- احسان عبد القدوس\nسنة النشر :- 2024", CategoryId = 1, ImageUrl = "/images/products/9789777954761.webp", Author = "إحسان عبد القدوس", PublishDate = new DateTime(2024, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789777954761" },
            new { Id = 679, Name = "اتحدث باسمك ككمان", Price = 275m, Stock = 10, Description = "أتحدث باسمك ككمان\nيعُودُ أحمد الشَّهاوي في كتابه الشِّعْرِي هذا إلى الإيقاع – الذي هو أكبرُ من الوزنِ - مُستخدمًا إيقاعاتٍ شعرية تتناسبُ مع حالِ الحُبِّ..\nإذْ تُؤكِّدُ النصوصُ أنَّ الكتابةَ الأبقى والأنقى والأصفى والمختلفة هي التي يكُونُ كاتبُها عاليًا في مقامِ العِشق، الذي هو أعلى المراتب وأرقاها.\nويستخدمُ الشَّاعر عناصرَ ومفرداتٍ ولغاتٍ وعلاقاتٍ جديدةً في العشقِ، يأتي جميعُها على قَدْر المعشُوق، إذْ يؤمنُ بأنَّ القصيدةَ تعادلُ المرأةَ بوصفها كائنًا تامًّا، ولا تُعبِّرُ فقط عمَّا هو حِسِّيٌّ، بل تذهبُ إلى الرُّوحي وتُعوِّل عليه.\nوقد استخدم الشَّاعرُ آلةَ الكمان جُزْءًا مُهمًّا ورئيسًا في عنوان كتابه لأنه يدركُ أنَّ الكمان كآلةٍ وتريةٍ أساسية لا يمكنُ الاستغناء عنها أو تبديلها، وهي مُعادِلٌ للمحبوب الذي لا يتحوَّلُ ولا يتغيَّرُ بل يزدادُ تعبيرُهُ عن الحُبِّ، بوصفه كالكمانِ الأحنّ والأرَقّ والمُعبِّر، وله السيادةُ والسُّلطةُ الرُّوحيةُ، كما أنَّ جسدَ الكمانِ في انسيابيته مُماثلٌ لجسدِ المحبُوبِ، وكلاهما يفيضُ بموسيقى نادرةٍ إذا أحْسَنَ العاشِقُ/العازِفُ العزْفَ والَّلعِبَ بطريقةٍ مُحِبَّةٍ وعارِفةٍ.\nـــــــــــــــــــــــــــ\nأحمد الشهاوي، شاعر وكاتب من مصر، حاز على جائزة اليونسكو في الآداب عام 1995م، وجائزة كفافيس الدولية في الشّعر مايو 1998م. أصدر ما يزيد على عشرين كتابًا في الشعر والرواية والتصوف وأدب العشق. وصدرت أعماله الشعرية مُترجمةً إلى لغاتٍ عديدة. وقد وصلت أعماله إلى القائمة الطويلة لجائزة زايد للكتاب أربع مَرّات.\nاسم المؤلف :- احمد الشهاوى\nسنة النشر :- 2024", CategoryId = 1, ImageUrl = "/images/products/9789777954877.webp", Author = "احمد الشهاوي", PublishDate = new DateTime(2024, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789777954877" },
            new { Id = 680, Name = "لعنة الخواجة", Price = 440m, Stock = 10, Description = "لعنة الخواجة\nالتهمتني هذه الرواية في ثلاثة أيام.كيف يصبح هذا الكم من المعرفة والمعلومات والوثائق والتاريخ لبنات بناء فني فائق الروعة؟\nهي الرواية الأولى لوائل السمري إلا أني شعرت أنه كتب قبلها عشر روايات، موضوعها جديد اكتشفه بوثائق حقيقية، وتتحرك الرواية بين عالمين في بناء فني لا تمل من ابتكاراته في القص أو المشهدية أو اللغة التي تجعلك لا تترك الرواية من يدك رغم كبر حجمها.\nهذه ليست رواية، هذه سيرة للزمن، يتشابك فيها التاريخ مع الإنسان والوطن؛ فتتجاوز التصنيف الروائي إلى الملحمي في بنائها وفي دراما موضوعها سواء مع البطل المصري اليوناني الحقيقي أو الصحفي المتخيل الذي كتب الرواية.\nسألته بعد أن قرأتها هل أنت الذي كتبتها أم مجموعة مجانين أشرفت عليهم يقفون الآن سعداء؟\nإبراهيم عبد المجيد\nـــــــــــــــــــــــــــ\nوائل السمري، شاعر وكاتب، عضو لجنة الشعر بالمجلس الأعلى للثقافة، عضو مجلس أمناء مؤسسة فاروق حسني للثقافة والفنون، فازت مسرحيته الشعرية \"كما لا ترون\" بجائزة أفضل كتاب من معرض القاهرة الدولي للكتاب عام 2021، كما فاز بالجائزة الأولى بمسابقة كتاب اليوم، والجائزة الأولى بمسابقة قصور الثقافة، وجائزة أفضل قصيدة من المجلس الأعلى للثقافة الشعرية، وحصل على جائزة الصحافة المصرية عامي 2019، و2022. صدر له ديوانان شعريان ومسرحية شعرية وسيرة إنسانية بعنوان \"ابني يعلِّمُني\". يعمل حاليًا رئيس التحرير التنفيذي لجريدة \"اليوم السابع\".\nاسم المؤلف :- وائل السمرى\nسنة النشر  :- 2024", CategoryId = 1, ImageUrl = "/images/products/9789777954921.webp", Author = "وائل السمري", PublishDate = new DateTime(2024, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789777954921" },
            new { Id = 681, Name = "ظننته فيصل", Price = 200m, Stock = 10, Description = "ظننته فيصل\n“هرعتُ نحوه واحتضنته، كان كلانا مغمورًا باللهفة والشوق، نعم، فيصل ذلك الرجل الذي أحب، من ملأ حياتي ونثر فيها الياسمين، كنت بقربه أستريح من الخوف، من القلق، من عناء التفكير، من عشرات المعارك التي أخوضها مع نفسي، كنت أختبئ فيه من حماقات أفكاري”.\n***\nيختلط الواقع بالوهم، ويفقد العقل القدرة على استيعاب الصدمات تلو الصدمات، يخلق عالمًا يشبه الحقائق، فتنجذب ياسمينة إلى فيصل، لكنها ترى الشفقة في عيني زوجته بدلًا من الغيرة.\nرواية تتلاعب بالأفكار، من ذلك النوع الذي تسير فيه مع المؤلف، واثقًا أنك لن تضل الطريق، لكن بعد أن تتضح الصورة تجد نفسك  تستعيد الأحداث برؤية جديدة.\nـــــــــــــــــــــــ\nعبير حامد. كاتبة وروائية حاصلة على درجة البكالوريوس في الآداب، بدأت حياتها العملية في القطاع الثقافي في عالم المكتبات، نُشرت لها مقالات في عدد من الدوريات الثقافية الورقية والإلكترونية، قدمت الكثير من ورش العمل والدورات التدريبية في الكتابة الإبداعية والقراءة التفاعلية، شاركت في إعداد مشاريع معرفية مع العديد من المؤسسات الثقافية العربية والأجنبية، وتواجدت في المحافل الثقافية مع كتّاب وأدباء وناشطين في العمل الثقافي، صدرت لها رواية: ختام برائحة المسك.\nاسم المؤلف :- عبير حامد \nسنة النشر :- 2024", CategoryId = 1, ImageUrl = "/images/products/9789777954938.webp", Author = "عبير حامد", PublishDate = new DateTime(2024, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789777954938" },
            new { Id = 682, Name = "جاسوس رغم انفه", Price = 250m, Stock = 10, Description = "جاسوس رغم أنفه\nإن هذا العمل الأدبي، هو محض خيال المؤلف، منبت الصلة عن الواقع، ولا اتساق لأي أحداث أو تفاعلات أو شخوص مع الحقيقة، فكلها نتاج وإنتاج ضرورات الحبكة...، والعمل في مجمله هو بمثابة رحلة ينتقل فيها القارئ لبرهة من عالمه الى أجواء الإثارة والإرهاب والجاسوسية والحب والمغامرة، في منطقة جنوب آسيا، المغايرة عنا في أشياء والمتماهية في أشياء أخرى.. ولكنه الإنسان... هنا وهناك هو أصل الموضوع وفصل الخطاب وبنيان الرواية...فهو مربط الفرس... بحبه وكرهه ووفائه وغدره وسماحته ونبل مقاصده أو خبث طويته!!.. إنه الإنسان وكفى.\nـــــــــــــــــــــــــــ\nمحمد مصطفى عرفي.. كاتب ومحاضر أكاديمي، حاصل على درجتي الماجستير والدكتوراه في القانون والعلوم السياسية من لندن. صدرت له روايات: حلو مُر، الحب في لندن، ودموع ماتريوشكا، ووردة في حقل الصبار، وظلال الكولوسيوم.\nاسم المؤلف :- محمد مصطفى عرفى\nسنة النشر :- 2024", CategoryId = 1, ImageUrl = "/images/products/9789777954945.webp", Author = "محمد مصطفى عرفي", PublishDate = new DateTime(2024, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789777954945" },
            new { Id = 683, Name = "Politics Power and Principle : Insights from Shakespeare", Price = 240m, Stock = 10, Description = "Author name :- Ismail Serageldin\nPublication year :- 2024", CategoryId = 7, ImageUrl = "/images/products/9789777954891.webp", Author = "ISMAIL SERAGELDIN", PublishDate = new DateTime(2024, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789777954891" },
            new { Id = 684, Name = "The Medical Lectures", Price = 250m, Stock = 10, Description = "Ismail Serageldin is the Co-Chair of the Board of Trustees of the Nizami  Ganjavi International Center (NGIC).  He was the Founding Director of the Bibliotheca Alexandrina, the New Library of Alexandria in Egypt (2001-2017).  Before that he was the Vice-President of the World Bank (1993-2000) in charge of Environmentally Sustainable Development (ESD), and the Chairman of the Consultative Group for International Agricultural Research (CGIAR).  He served on many international committees and commissions, including serving as a member of the High Level group for the Alliance of Civilizations convened by the Secretary General of the United Nations (2006-2007).   He was also a distinguished professor at Wageningen University and the College de France. He is a member of many Academies and serves on many commissions, boards, and advisory committees for academic, research, and NGO institutions. He has lectured widely and published more than 100 books and 500 articles. He has received many awards from many countries and has received more than 40 honorary doctorates from all over the world.\nAuthor name :- Ismail Serageldin\nPublication year :- 2024", CategoryId = 7, ImageUrl = "/images/products/9789777954860.webp", Author = "ISMAIL SERAGELDIN", PublishDate = new DateTime(2024, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789777954860" },
            new { Id = 685, Name = "Human Rights", Price = 155m, Stock = 10, Description = "Ismail Serageldin is the Co-Chair of the Board of Trustees of the Nizami  Ganjavi International Center (NGIC).  He was the Founding Director of the Bibliotheca Alexandrina, the New Library of Alexandria in Egypt (2001-2017).  Before that he was the Vice-President of the World Bank (1993-2000) in charge of Environmentally Sustainable Development (ESD), and the Chairman of the Consultative Group for International Agricultural Research (CGIAR).  He served on many international committees and commissions, including serving as a member of the High Level group for the Alliance of Civilizations convened by the Secretary General of the United Nations (2006-2007).   He was also a distinguished professor at Wageningen University and the College de France. He is a member of many Academies and serves on many commissions, boards, and advisory committees for academic, research, and NGO institutions. He has lectured widely and published more than 100 books and 500 articles. He has received many awards from many countries and has received more than 40 honorary doctorates from all over the world.\nAuthor name :- Ismail Serageldin\nPublication year :- 2024", CategoryId = 7, ImageUrl = "/images/products/9789777954846.webp", Author = "ISMAIL SERAGELDIN", PublishDate = new DateTime(2024, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789777954846" },
            new { Id = 686, Name = "Revolution and Rebirth", Price = 155m, Stock = 10, Description = "Ismail Serageldin is the Co-Chair of the Board of Trustees of the Nizami  Ganjavi International Center (NGIC).  He was the Founding Director of the Bibliotheca Alexandrina, the New Library of Alexandria in Egypt (2001-2017).  Before that he was the Vice-President of the World Bank (1993-2000) in charge of Environmentally Sustainable Development (ESD), and the Chairman of the Consultative Group for International Agricultural Research (CGIAR).  He served on many international committees and commissions, including serving as a member of the High Level group for the Alliance of Civilizations convened by the Secretary General of the United Nations (2006-2007).   He was also a distinguished professor at Wageningen University and the College de France. He is a member of many Academies and serves on many commissions, boards, and advisory committees for academic, research, and NGO institutions. He has lectured widely and published more than 100 books and 500 articles. He has received many awards from many countries and has received more than 40 honorary doctorates from all over the world.\nAuthor name :- Ismail Serageldin\nPublication year :- 2024", CategoryId = 7, ImageUrl = "/images/products/9789777954822.webp", Author = "ISMAIL SERAGELDIN", PublishDate = new DateTime(2024, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789777954822" },
            new { Id = 687, Name = "Climate Change", Price = 290m, Stock = 10, Description = "The Nizami Ganjavi International Center (NGIC) is an institution based in Azerbaijan, that celebrates the legacy of the great Azerbaijani poet and sage, Nizami Ganjavi (1141-1209), and that promotes the participation of high-level eminent figures in the study of possible solutions for the great problems of our time, with a view to promoting knowledge, tolerance, dialogue and understanding between peoples, cultures and nations.\nAuthor name :- Ismail Serageldin\nPublication year :- 2024", CategoryId = 7, ImageUrl = "/images/products/9789777954839.webp", Author = "ISMAIL SERAGELDIN", PublishDate = new DateTime(2024, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789777954839" },
            new { Id = 688, Name = "تغريب", Price = 300m, Stock = 10, Description = "لفح الهواء البارد وجهيهما، لم تَشِ الغيوم بالربيع وبدت إنجلترا قاتمة كعادتها، سألها:\n- ما الذي يجعل الأرض وطنا؟ الولادة؟ المنشأ؟ الأهل؟ الصحبة؟ العمل؟ الشريك؟\n أجابته متسمرة تحت السماء:\n- ذكريات كل ما ذكرت، ذكريات ما عشته وما لم تعشه.\n*\nفي محاولات يائسة للبحث عن الاستقرار، تبني نادين لنفسها حياة في لندن، تـتزوج وتؤسس حياة مهنية تنجيها من العودة إلى بيروت. بينما يهرب نور من الكوابيس التي تلاحقه في القاهرة إلى مدينة الضباب، يحتمي بالعمل والصحبة ويظن أنه الخلاص. يلتقي المغتربان فتأنس وحدتهما، ويُدفع كلاهما إلى العودة إلى الماضي.\nأشواق اللواتي، حاصلة على بكالوريوس في دراسات الإعلام، وماجستير في الكتابة الإبداعية وكتابة السيناريو من جامعة إيست إنجليا بالمملكة المتحدة. عملت في مجالات عديدة منها الإعداد والتحرير وكتابة النصوص والمحتوى، تغريب هي روايتها الأولى.\nاسم المؤلف :- اشواق اللواتى\nسنة النشر :- 2024", CategoryId = 1, ImageUrl = "/images/products/9789777954884.webp", Author = "أشواق اللواتي", PublishDate = new DateTime(2024, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789777954884" },
            new { Id = 689, Name = "ابنة الديكتاتور", Price = 245m, Stock = 10, Description = "\"مصر في منتصف القرن العشرين، ساحة عراك دامٍ، تتبدل فيه الأدوار، وتتغير المواقع حتى لا يبين غالب من مغلوب. منكسرون بالتبعية يرون جلاء المحتل رهانًا مستبعدًا يحسُن تأجيله على الدوام، وجامحون طامحون يحصون خطاهم للتجهز لحكم البلاد والعباد شرقًا وغربًا بعد تحرر يؤمنون أنه صار وشيكًا، وبين الفريقين منتفعون دومًا في النصر والهزيمة، لديهم قدرات معجزة على التلون وتبديل المواقف، وعصر القيم للمواءمة مع كل حال طلبًا للمكسب\".\n   لعب القدر لعبته  العجيبة، فألقى بين يدي المؤلف نصًا ممنوعًا ظل الاقتراب من أحداثه عملًا محرمًا لسنوات طويلة تتحدث فيه شخصية استثنائية، لعبت أدوارًا سرية في تاريخ مصر المعاصر، وكانت شاهدة على أحداث وأسرار سياسية وأدبية خطيرة.\n وقد لجأ المؤلف إلى فن السرد الروائي تجنبًا للمساءلة القانونية.\nاسم المؤلف :- مصطفى عبيد\nسنة النشر :- 2024", CategoryId = 1, ImageUrl = "/images/products/9789777954853.webp", Author = "مصطفي عبيد", PublishDate = new DateTime(2024, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789777954853" },
            new { Id = 690, Name = "سرديات الحروب والنزاعات", Price = 340m, Stock = 10, Description = "سرديات الحروب والنزاعات\n  إن النظر في فنيّات النوع الأدبي - مع ما تتميز به الرواية من فرادة نوعية - يقتضي التحليل السردي تحليلًا دقيقًا، يُبرِز تغيُّر الرؤى وانعطافاتها الفكرية والأيديولوجية، التي تحرِّك الأحداث، وجلاء الحبكة، وتطوُّر الشخصيات، وطبيعة الزمان والمكان، وما هي الحدود الفارقة بين المؤلِّف والبطل؛ ومن ثم استهدفت هذه الدراسة -قراءة وتنظيرًا وتطبيقًا- محاولة الوقوف على الطبيعة الفنية لسرديات الحروب، من خلال عدة فصول ومباحث، تتقصَّى خصوصية رواية الحرب؛ من حيث الرؤية والتقنية وطبيعة السرد، واللغة الفنية التي تشكِّل عوالم النَّص، وتحليل الشخصيات في بُعدها المعرفي والنفسي والاجتماعي والسلوكي... ولقد استهدفت هذه الدراسة محاولة استجلاء أدب الحرب وسردياته، وأهم الظواهر الفنية التي تشكِّل بنيته الفنية، وترسم عوالمه المختلفة.\nـــــــــــــــــــــــــــــــــــــ\nأ.د. أماني فؤاد. أستاذة النقد الأدبي الحديث بأكاديمية الفنون بالقاهرة، من مؤلفاتها: المرأة.. ميراث من القهر- قضايا التنوير الخصوصية المصرية- الرواية وتحرير المجتمع- الإبداع في تراث أبي حيان التوحيدي- المجاوزة في تيار الحداثة في مصر بعد السبعينيات- لأسباب أخرى تعتم النجوم \"مجموعة قصصية\"، بالإضافة إلى مئات من الأبحاث في المجال الأكاديمي والشأن الثقافي.\nعضو بلجان المجلس الأعلى للثقافة بمصر- عضو اللجنة العلمية الأعلى لجائزة الشيخ زايد بالإمارات- عضو لجنة التحكيم ببرنامج أمير الشعراء بأبو ظبي- عضو لجان تحكيم جوائز الدولة التشجيعية والتقديرية وجائزة نجيب محفوظ، وجائزة ساويرس الثقافية بمصر- عضو لجان تحكيم الجوائز العربية والدولية؛ جائزة كاتارا بقطر، جائزة الفجيرة بالإمارات، ‏جائزة محمود درويش.\nاسم المؤلف :- امانى فؤاد \nسنة النشر :- 2024", CategoryId = 8, ImageUrl = "/images/products/9789777954785.webp", Author = "أماني فؤاد", PublishDate = new DateTime(2024, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789777954785" },
            new { Id = 691, Name = "زعفرانة", Price = 250m, Stock = 10, Description = "أخرجت الكتاب الابيض الذي يحتوي على الوردة الجافة، بدأت اكتب مذكرات شهلا، منذ حطت أقدامي على هذه الأرض التي أحببتها، وحتى هوى صرح الخيال، مع خصلات شعري الأسود تسقط على أرض غرفتي، دون أن أشعر بالحزن أو الحسرة بدأت بالسلام على زعفرانة، أمي صاحبة الكتاب، والتي اوصتني به خيراً، دون أن تذكر دون أن تذكر انه كتاب مذكرات، أو كتاب للعودة حين تهوى الصروح الكبيرة، بدأت بالسلام على أمي وكأني أكتب رسالة، تذكرت أنني لم أكتب رسائل الى أمي منذ أكثر من ستة أشهر، ولا أعرف إن كانت رسائلى التي أبعث بها إلى العاصمة في بلدي، ثم تنتقل باليد، من هذا إلى ذاك لا أعرف كم رسالة وصلت إلى أمي، بدأت أكتب مذكرات شهلا، لتصير يوماً إلى يد أمي. \nاسم المؤلف :- هدى النعيمى \nسنة النشر :- 2024", CategoryId = 1, ImageUrl = "/images/products/9789777954778.webp", Author = "هدى النعيمي", PublishDate = new DateTime(2024, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789777954778" },
            new { Id = 692, Name = "مواليد حديقة الحيوان", Price = 220m, Stock = 10, Description = "مواليد حديقة الحيوان\n  “لا ترَ بأُذنيك، ولا تسمع بعينيك، ولا تُصدِّق كل ما يُقال لك.. فبعض الكلمات صور، لو تأملتها لرأيت تفاصيل لم تُدركها من النظرة الأولى، أطياف مهزوزة في خلفيتها، وأشياء صغيرة دالة على زمانها ومكانها، وإذا ما قلبتها لربما صافحت عيناك كلمات دوَّنها صاحبها قد تُغيِّر رؤيتك عنها.. الحقيقة نراها منقوصة دومًا لكننا نشعر بها كاملة، فلا تثق إلا بقلبك”.    ثلاث روايات قصيرة لأشرف العشماوي ببناء سردي يُضفِّر الواقعية باللا معقول عبر حكي مشوق ومشهدية ساحرة، يكشف السُّخرية المتوارية في المسافة بين أحلام أبطال رواياته وواقعهم الأغرب من الخيال.\nـــــــــــــــــــــــــــــــــــــ\nأشرف العشماوي: قاضٍ وروائي مصري، أصدر 11 رواية، وله كتاب توثيقي عن استعادة الآثار المصرية. فاز بعدة جوائز أدبية، أحدثها جائزة كتارا 2023 لأفضل رواية عربية، وتُرجمت بعض رواياته لأكثر من ثماني لغات.\nاسم المؤلف :- اشرف العشماوى \nسنة النشر :- 2024", CategoryId = 1, ImageUrl = "/images/products/9789777954808.webp", Author = "اشرف العشماوي", PublishDate = new DateTime(2024, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789777954808" },
            new { Id = 693, Name = "2070 حرب الزانون", Price = 220m, Stock = 10, Description = "2070حرب الزانون\n  في عام 2070، يصل الاستقطاب البشري إلى ذروته وينقسم الناس إلى طائفتين: الطائفة المميزة جينيًّا؛ أنشأت مجتمعًا مثاليًّا أطلقت عليه اسم “الجنة”. فيها تسقط عنك جميع الالتزامات والمسؤوليات، وتستمتع بشباب ممتد ونعيم لا ينتهي. يمكنك أن تتمنى ما تشتهي، وسيقوم آليُّو الزانون بتحقيقه. لن تحمل همَّ الحصول على المال، ولن تضطر للتعامل مع أشخاص لزجين ينغصون عليك حياتك ويصيبونك بالاكتئاب.لكن السؤال المهم: هل أنت مؤهل للانضمام إلى سكان جنة الزانون، أم ستصبح من المطرودين منها؟ هي قصة صراع في المستقبل بين مجموعتين من البشر، حيث تم استخدام جميع الوسائل والأسلحة، بدءًا من الدهاء والتجسس وصولًا إلى التكنولوجيا المتقدمة، لتكشف عن عقل الإنسان وتركيبه الهش بعد فشله في قبول اختلاف الآخر والتعايش معه.\nـــــــــــــــــــــــــــــــــــــ\nفادي زويل. مهندس مصري تخرج في قسم الحاسب الآلي بجامعة الإسكندرية. حاصل على ماجستير إدارة الأعمال من جامعة Texas A&M. صدر له كتاب \"رحلاتي مع أوبر- 22 رحلة حول العالم\" والمصنف أدب رحلات عن الدار المصرية اللبنانية، كما صدرت له رواية \"ميديوكر\"\nاسم المؤلف :- فادى زويل \nسنة النشر :- 2024", CategoryId = 1, ImageUrl = "/images/products/9789777954792.webp", Author = "فادي زويل", PublishDate = new DateTime(2024, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789777954792" },
            new { Id = 694, Name = "انف وثلاثة عيون ج2", Price = 415m, Stock = 10, Description = "\"وقال هاشم كأنه يرد على خواطري:  متهيألي إن مش كل حب ينفع للجواز.. الجواز يعني هدوء، واستقرار، وأولاد، ومستقبل، ومحتاج لحب يساع ده كله.. إنما فيه حب مجنون ما يستحملش الاستقرار، ما يقدرش عليه.. حب ناقص.. تعرفي أنا ما اتجوزتش الست اللي قُلت لك عليها ليه.. لأني مقدرتش أحترمها.. عمري ما احترمتها.. عمري ما حسيت إن عندها كرامة علشان أحترمها.. والحب اللي ينقصه الاحترام، مش ممكن ينفع للجواز..\".\nاسم المؤلف: - احسان عبد القدوس\nسنة النشر:- 2024", CategoryId = 1, ImageUrl = "/images/products/9789777954723.webp", Author = "إحسان عبد القدوس", PublishDate = new DateTime(2024, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789777954723" },
            new { Id = 695, Name = "كلمة حلوة", Price = 190m, Stock = 10, Description = "كلمة حلوة\nالكَلِمَةُ الحُلْوَة… تَرْسُمُ ابتِسَامَةً، تَجْلب ضِحْكَةً،\nتَنْشُر خَيْرًا ، تُسْعِدُ قَلْبًا. بَدَأَت بِهَا دَلِيلَة وحَسَن\nفَأَثَّرَتْ فِي مَنْ حَوْلَهُما وانعَكَسَت الفَرْحَةُ عَلَيْهِما.\nاسم المؤلف :- علا منجد\nسنة النشر :- 2024\n\nحسين الرباعي", CategoryId = 11, ImageUrl = "/images/products/9789777954730.webp", Author = "علا منجد رسوم", PublishDate = new DateTime(2024, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789777954730" },
            new { Id = 696, Name = "اهلا دليلة", Price = 190m, Stock = 10, Description = "أهلا دليلة\nوُلِدَتْ دَلِيلَة لِتَعِيشَ أَيَّامَهَا فِي جَوِّ العَائِلَةِ فَتَزِيدُهُ حُبًّا،\nتُؤْنِسُ أَحْبَابَهَا وتَأْنَسُ بِهِمْ وتَتَعَلَّمُ كُلَّ يَوْمٍ لِتُصْبِحَ مُمَيَّزَةً\nفَأَهْلاً بِهَا...24\nاسم المؤلف :- علا منجد\nسنة النشر :- 2024\n\nحسين الرباعي", CategoryId = 11, ImageUrl = "/images/products/9789777954747.webp", Author = "علا منجد رسوم", PublishDate = new DateTime(2024, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789777954747" },
            new { Id = 697, Name = "بوكا فى غابة الألحان", Price = 185m, Stock = 10, Description = "بوكا في غابة الألحان\n\"اعْمَلْ وَاجِبَكَ وَأَتْقِنْ عَمَلَكَ، تَهْزِمْ قَلَقَكَ وَتُحَقِّقْ حُلْمَكَ\".\n\"اعْزِفْ مِنْ قَلْبِكَ تَجِدِ الطَّرِيقَ\".\n\"فَكِّرَ بِعَقْلِكَ وَشَاوِرْ قَلْبَكَ. تَذَكَّرْ دَوْمًا أَنَّنَا نَصْعَدُ السُّلَّمَ دَرَجَةً مِنْ بَعْدِ دَرَجَةٍ\".\n\"كُنْ شُجَاعًا تَجِدِ الطَّرِيقَ\".\n                                                                           \n                                                            جدودو من مدينة موسيكان           \nالمؤلف :- هشام الخشن \nسنة النشر :- 2024\n\nآناستازيا كورنوييسكا", CategoryId = 11, ImageUrl = "/images/products/9789777954754.webp", Author = "هشام الخشن رسوم", PublishDate = new DateTime(2024, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789777954754" },
            new { Id = 698, Name = "المسحورة", Price = 330m, Stock = 10, Description = "دخل من الباب الشرقي للواحة، يبحث عن حُلمٍ قديم.. عن مخطوطٍ غير مكتمل.. عن عروس غلبها العشق.\nلاح له في الأفق البعيد تل صغير..\nسأل عنها علها تختبئ خلف هذا التل..\nأجابوه: «احترس منها.. إنها (صخرة العاشق)، صخرة مسحورة تجذب إليها الرجال، إذا لمسْتَها ستدخل في غفوة طويلة لن تستيقظ منها إلا بالموت».\nلم يبالِ وانطلق نحوها باحثًا عن محبوبته \"المسحورة\"، وعن قَدَر عسى أن ينقذه من غفوة العاشق.\nفهل يصل إليها؟! ربما..\nأو.. هكذا تقول الأسطورة.\nـــــــــــــــــــــــــــــــ\nد.رشا سمير\n روائية وكاتبة صحفية وطبيبة أسنان.\nصدر لها عشرة أعمال منها: ”حواديت عرافة“، ”معبد الحب“، ”حب خلف المشربية“، ”يعني إيه راجل؟“، ”جواري العشق“، ”بنات في حكايات“، ”للقلب مرسى أخير“، ”سألقاك هناك“، وتكتب مقالاً أسبوعيًّا بجريدة الفجر المصرية.\nالمؤلف :- رشا سمير \nسنة النشر :- 2024", CategoryId = 1, ImageUrl = "/images/products/9789777954426.webp", Author = "رشا سمير", PublishDate = new DateTime(2024, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789777954426" },
            new { Id = 699, Name = "مذكرات مجدى يعقوب جراح خارج السرب", Price = 575m, Stock = 10, Description = "مذكرات مجدى يعقوب\n“كل مصري داخل الوطن أو خارجه يُكِنّ تقديرًا كبيرًا ومحبة خاصة للسير مجدي يعقوب، ليس فقط لتفوقه المهني الكبير عالميًّا، وإنما أيضًا لإنسانيته، التي فاضت على البشرية في مصر وفي الكثير من  بلاد العالم بالعمل تطوعًا لخدمة القراء وإنقاذ حياتهم”. دكتور محمد أبو الغار\nالمؤلف :- سيمون بيرسن , فيونا جورمان \nتقديم :- ماري ارتشر \nترجمة :- أحمد شافعى \nسنة النشر :- 2024\n\nترجمة أحمد شافعي", CategoryId = 7, ImageUrl = "/images/products/9789777954617.webp", Author = "سيمون بيرسن - فيونا جورمان - تقديم ماري آرتشر", PublishDate = new DateTime(2024, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789777954617" },
            new { Id = 700, Name = "وجهة الاسلام نظرة فى الحركات الحديثة في العالم الاسلامي", Price = 330m, Stock = 10, Description = "لما كان هذا الكتاب من تأليف مجموعة من المستشرقين فإنه يجب بيان أهميته، من حيث الاطلاع على بعض أغراض المستشرقين وأفكارهم وآرائهم حول المسلمين والعالم الإسلامي، وهي ذاتها الأغراض والأفكار والآراء الخادمة للحقل السياسي الغربي، التي يأخذها بعين الاعتبار عند وضعه لسياساته وتعاملاته مع بلدان العالم الإسلامي المختلفة. فالكتاب يقع في موقع خطير بين التاريخ والحاضر من ناحية، والمستقبل من ناحية أخرى، أو تاريخ المستقبل الذي ينطلق من دراسة الماضي والحاضر ليتعرف إلى أي طريق تجري الوقائع السياسية والاجتماعية والفكرية والدينية، أو وجهتها السائرة إليها. وهو اتجاه نادر من الاتجاهات البحثية في الحقل التاريخي، ويقع على التخوم بين عدة علوم بينيَّة. ولعل ذلك ما تجلّى في انطباع محرره المستشرق الإنجليزي هاملتون جب، بعد انتهاء عمله في الكتاب فقال: \"الحق أن الإسلام ليس مجرد نظام من العقائد والعبادات، إنه أعظم من ذلك بكثير، وهو مدنية كاملة\". والكتاب، في ستة فصول، يتحدث عن الإسلام في أربعة أقاليم بأقلام أربعة أساتذة من كبار المستشرقين، هم: إفريقية (ما عدا مصر) بقلم لويس ماسينون، مصر وآسيا الغربية بقلم كامبفماير، الهند بقلم كولونل فرار، أندونيسيا بقلم بِرْج. وجاء الفصل الأخير بعنوان وجهة الإسلام للمشرف على التحرير جب.\nاسم المؤلف :- هاملتون جاب\nسنة النشر :- 2024\n\nترجمة محمد عبد الهادي أبو ريدة", CategoryId = 7, ImageUrl = "/images/products/9789777954693.webp", Author = "هاملتون جب", PublishDate = new DateTime(2024, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789777954693" },
            new { Id = 701, Name = "لا تلوموا الخريف", Price = 300m, Stock = 10, Description = "حلم عجيب، رأيت نفسي وسط حفل ضخم في غرفه فسيحة، وهذا الحفل مقام لشيء غريب لا يخطر على البال. إنهم يحتفلون بتتويجي ملكة، وحضرتك واقف فى يدك تاج، ثم ركعت أمامك، وحضرتك وضعت التاج فوق رأسي والموسيقى تعزف ألحانًا جميلة لم يسبق لي سماعها\". *** \"لا تلوموا الخريف\" قصة حب شيقة وساحرة تدور أحداثها بين 1938 حتى منتصف الستينيات من القرن العشرين، تتناول شخصيات عديدة مختلفة الطباع، بعضها حقيقي وبعضها من الخيال وتتخلل الرواية أحداث تاريخية عن المجتمع والحرب والسلام والكثير من الأفراح والأحزان ، وتعبر عن الإنسان ومعنى الحياة والحب الحقيقي.\nـــــــــــــــــــــــــــــــ\nد. يوسف عز الدين عيسى، جمع بين العلم والأدب في أعلى مستوياتهما، فهو أديب له عالمه الخاص، حصل على جائزة الدولة التقديرية في الأدب وغيرها من الأوسمة الرفيعة. تأثر أدبه بروح العصر فعبر عن الإنسان وحلل النفس البشرية بكل نوازعها وأحلامها وصراعاتها بأسلوب شيق يتأرجح بين الحلم والواقع، الخيال والحفيقة. كسرت رواياته الحاجز التقليدي للرواية العربية، وهو من أول رواد الواقعية السحرية فيها.\nاسم المؤلف :- يوسف عز الدين عيسى\nسنة النشر :- 2024", CategoryId = 1, ImageUrl = "/images/products/9789777954679.webp", Author = "يوسف عز الدين", PublishDate = new DateTime(2024, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789777954679" },
            new { Id = 702, Name = "تاريخ الدولة العربية من ظهور الاسلام الى نهاية الدولة الاموية", Price = 525m, Stock = 10, Description = "هذا كتابٌ لمستشرق ألماني يؤرِّخ فيه لحقبة النشأة والتكوين في التاريخ الإسلامي، ويلقي الضوء على تناول الفكر الغربي الأوروبي لتلك الحقبة ووجهة نظره فيها ووضوح الرؤية الاستشراقية الألمانية. وقد أخرج يوليوس فلهوزن كتابه في كلمة تمهيدية وتسعة فصول؛ عالج فيه دولة الإسلام في عصر النبوة وجزءًا كبيرًا من تاريخ الخلفاء المسلمين في عهدي أبي بكر وعمر، ثم عرض لأحداث الفتنة ومقتل عثمان وكيفية خلافة علي، ثم عرض لأمر الخوارج ومحاربتهم في موقعة النهروان، ثم مقتل علي، ثم تنازل الحسن بن علي عن الخلافة لمعاوية بن أبي سفيان. وسرد تاريخ الدولة الأموية تفصيلًا في عدة فصول متتالية، واختص عمر بن عبد العزيز ببعض التفصيل، ثم أكمل تاريخ الدولة الأموية إلى أن وصل إلى مرحلة ضعفها كدولة ثم سقوطها وظهور نجم الدولة العباسية، مناقشًا أسباب الضعف معتمدًا على مصادر أوروبية وعربية.\nاسم المؤلف :- يوليوس فلهوزن\nسنة النشر :- 2024\n\nترجمة ترجمة محمد عبد الهادي أبو ريدة", CategoryId = 7, ImageUrl = "/images/products/9789777954686.webp", Author = "يوليوس فلهوزن", PublishDate = new DateTime(2024, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789777954686" },
            new { Id = 703, Name = "الدولة العثمانية من السلطان عبد الحميد الثانى الى مصطفى كمال اتاتورك - كلاسيكيات التاريخ", Price = 440m, Stock = 10, Description = "تُعتبر الدولة العثمانية آخر الدول العُظمى المسلمة سقوطًا؛ لذلك ما تزال بتاريخها وحضارتها والاختلاف حول تأثيرها ودورها تُثير الكثير من المتخصصين والباحثين والقُرَّاء على كافَّة مستوياتهم وانتماءاتهم، وقد أحدث سقوطها الكثير من المشكلات التي ما يزال يُعاني منها الشرق الأوسط والعالم العربي حتَّى الآن على عِدَّة أصعدة. وفي هذا الإطار يأتي كتاب «الدولة العثمانية» ضمن سلسلة «كلاسيكيات التاريخ» التي تضطلع الدار المصرية اللبنانية بنشرها ورَفْدِ المكتبة العربية بها؛ والكتاب عبارة عن مقالات مُهمَّة نشرها المفكر والمصلح الإسلامي محمد رشيد رضا في مجلة «المنار»، ترصُد الفترة المُمتدَّة من بدايات حُكم السلطان عبد الحميد الثاني وحتى عهد مصطفى كمال أتاتورك، وتجمع المقالات المُختارة بين الأخبار التاريخية، والآراء والتحليلات الشخصية، والأرقام الإحصائية، والترجمات عن المصادر الأجنبية، ونصوص بعض القوانين واللوائح، ومُذكرات أو تصريحات بعض الزُّعماء وصُنَّاع الأحداث، وكذلك بعض القضايا الحسَّاسة، وقضايا أُخرى مُلتبسة في ذهن القارئ وبعض المراجع التاريخية، بالإضافة إلى حقائق وحوارات خاصَّة أجراها محمد رشيد رضا مع مُتخذي القرار أثناء زيارته لآستانة بعد انقلاب ضباط جمعية الاتحاد والترقي على السلطان عبد الحميد الثاني.\nاسم المؤلف :- محمد رشيد رضا\nسنة النشر :- 2024\n\nشرح وتعليق أحمد عبد الوهاب الشرقاوي / مراجعة وإشراف أ.د. أيمن فؤاد سيد", CategoryId = 7, ImageUrl = "/images/products/9789777952347.webp", Author = "محمد رشيد رضا", PublishDate = new DateTime(2024, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789777952347" },
            new { Id = 704, Name = "تاجر الحكايات", Price = 165m, Stock = 10, Description = "نصوص هذه المجموعة مغايرة لقصص حسن عبد الموجود السابقة التي يطول بعضُها إلى عشرات الصفحات. فالبطولة هنا للكثافة والإيجاز، للصمت لا للكلام. إنها قصص رائعة عن البراءة والموت والفقد والألم والجوع والعثور على الإنسانية حتى في الشَّر. هي فيض من الحنان والقسوة، والسخرية والفكاهة، في كتابة مدهشة صار حسن عبد الموجود يتقنها.  ............................................... في \"تاجر الحكايات\"، يبرع حسن عبد الموجود في توليد الغرابة من أبسط التفاصيل اليومية، وفي إلغاء المسافة بين الأصل والصورة، بين الحقيقة والوهم، وبين المأساة والملهاة. لكن ربما لا تتسق مفردة \"مأساة\" مع عالم هذه الأقاصيص؛ المكتوبة بمكر ومراوغة، حيث تمتزج الآلام والأحزان غالبًا بالهزل أو البراءة الطفولية. منصورة عز الدين آمنت دائما أن الأدب الجميل قد يأتي في آلاف الكلمات على طريقة هوميروس، أو في أقل الكلمات على طريقة باشو، وتعلمت أن قراءة هايكو واحدة قد تقتضي من الجهد ما تقتضيه الإلياذة. وكتاب حسن عبدالموجود هذا أكد لي ما آمنت به وما تعلمته. أحمد شافعي حسن عبد الموجود روائي وقاص، مواليد أكتوبر 1976، صدر له \"ساق وحيدة\"، \"عين القط\"، \"ناصية باتا\"، \"السهو والخطأ\"، \"حروب فاتنة\"، \"البشر والسحالي\". حصل على جائزة يوسف إدريس، وجائزة ساويرس، وجائزة معرض القاهرة للكتاب، وجائزة دبي، وجائزة نقابة الصحفيين، وتُرجمت بعض أعماله إلى الإنجليزية والفرنسية والألمانية والإسبانية.\nاسم المؤلف :- حسن عبد الموجود\nسنة النشر :- 2024", CategoryId = 1, ImageUrl = "/images/products/9789777954662.webp", Author = "حسن عبد الموجود", PublishDate = new DateTime(2024, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789777954662" },
            new { Id = 705, Name = "ايام شبابى", Price = 200m, Stock = 10, Description = "هي كلمات – كما سمَّاها الكاتب الكبير إحسان عبد القدوس – كتبها في أيام شبابه في مجلة روزاليوسف، حول المجتمع والتحليل العاطفي، ترفض الاستسلام للواقع.. متطلعة إلى المستقبل.. ترفض القديم.. وترفض التقيد بالتقاليد.. وترفض الخوف الاجتماعي.. ولذلك.. فمهما طال الأمد عليها فهي لا تزال أفكارا جديدة..  وأجمل ما فيها أنه رفض تنقيحها أو صبغها بخبرة السنين، تركها بما فيها من جموح واندفاع وقناعات لم يتغير كثير منها. ــــــــــــــــــــــــــــــــــ\nولد أول يناير 1919 بالقاهرة، تخرج في كلية الحقوق عام 1942.  بدأ حياته كاتبًا سياسيّا ورئيسًا لتحرير مجلة روزاليوسف التي أسستها والدته فاطمة اليوسف. فجّر قضية الأسلحة الفاسدة التي استخدمت في حرب فلسطين.  تقلد عددًا من المناصب الصحفية كان آخرها رئيسًا لتحرير ولمجلس إدارة مؤسسة الأهرام، وبعدها تفرغ للكتابة حتى وفاته 11 يناير 1990.  أنتج المئات من الروايات والمجموعات القصصية التي تحوّل معظمها إلى أعمال سينمائية وإذاعية وتليفزيونية. حصل على العديد من أرفع الأوسمة والجوائز وشهادات التقدير المحلية والعالمية.\nاسم المؤلف :- احسان عبد القدوس\nسنة النشر :- 2024", CategoryId = 1, ImageUrl = "/images/products/9789777954631.webp", Author = "إحسان عبد القدوس", PublishDate = new DateTime(2024, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789777954631" },
            new { Id = 706, Name = "صلاح فضل سيرة نقدية", Price = 365m, Stock = 10, Description = "\"تتبدى الأهمية البالغة والقيمة الثمينة لسِفر يضم السيرة الحياتية والنقدية لشيخ النقاد العرب الأستاذ الدكتور صلاح فضل رأس الفكر النقدي الحداثي في الثقافة العربية بامتداد نصف قرن، منذ سبعينيات القرن العشرين إلى وقتنا هذا- ليس في كونها شهادة ضافية عن رحلة عطاء ثرية وممتدة لرمز ملأ حياتنا الثقافية ويشغل آفاقنا الفكرية بما بذله من جهود تأسيسية في الحياة الأكاديمية والثقافية العربية وما قدمه من عطاءات معرفية قيِّمة تنامت وتعالت لتقف شاهدًا شامخًا على مسيرة عَلَمٍ استثنائي في منجزه وإسهاماته- وإنَّما أيضًا في كون هذه السيرة بمثابة وثيقة مُهمة وشهادة شديدة الثراء والصدق على العصر، لما مرت به تجربة صاحبها من مواقف وخبرات، وأحداث مهمة وتحولات فارقة في تاريخنا المصري والعربي المعاصر وصِلَتها بالتحولات العالمية الكبرى.\nاسم المؤلف :- رضا عطية\nسنة النشر :- 2024", CategoryId = 7, ImageUrl = "/images/products/9789777954488.webp", Author = "رضا عطية", PublishDate = new DateTime(2024, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789777954488" },
            new { Id = 707, Name = "ام منصور وبستان النور", Price = 175m, Stock = 10, Description = "سَأَلَتْ نُور فِي دَهْشَةٍ: «هَلْ لِلشَّمْسِ زُهُورٌ؟!»\nضَحِكَتْ دِيْمَة وَقَالَتْ: «زُهُورُ دَوَّارِ الشَّمْسِ سُمِّيت بِهَذَا الاسْمِ لأَنَّهَا تَمِيْلُ مَعَ  اِتِّجَاهِ الشَّمْسِ».\nفِي حَيْرَةٍ قَالَتْ نُور: «لأَنِّي وُلِدْتُ هُنَا، لَمْ أَرَ النَّخْلَ وَزَهْرَةَ دَوَّارِ الشَّمْسِ، لَمْ أَرْكُضْ مَعَ الفَرَاشَاتِ المُلَوَّنَةِ، لَمْ أَشُمَّ اليَاسَمِيْن».\nاسم المؤلف :- سماح ابو بكر عزت\nسنة النشر :- 2024", CategoryId = 11, ImageUrl = "/images/products/9789777954327.webp", Author = "سماح ابو بكر عزت", PublishDate = new DateTime(2024, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789777954327" },
            new { Id = 708, Name = "لست أنا - قال الكلب روبين", Price = 200m, Stock = 10, Description = "لِلأطفَال مَنطِقَهم الخَاص للحُكم عَلَى الأشيَاء والأشخَاص.. كَيف يَرَى الأطفَال تَصرفَاتِهم وَيُبررُونها؟ وَهلْ نَستطِيع أنْ نَحكمَ بِالكَذب عَلَى ما يُخبِروننا بِه، حَتَى لو كَان بِالفِعل غَيرَ الحَقيقَة؟\nيَعْتَقِدُ الجَمِيعُ دَائمًا أنَّه خَطَأُ رُوبِن عِندَما يَحْدثُ خَطأٌ ما في الحَضَانَة، لَكِنَّ هَذا لَيْسَ صَحِيحًا، وَلَم يَكُن هُو الذِي سَكَبَ الحَلِيبَ، لَقدَ حَدثَ ما حَدثَ بِهَذه الطَّرِيقَة.\nاسم المؤلف :- اليس ليم ادى فيريا\nاسم المترجم :- شيرين عبد الوهاب\nسنة النشر :- 2024", CategoryId = 11, ImageUrl = "/images/products/9789777954648.webp", Author = "اليس ليم ادى فيريا ترجمة شيرين عبد الوهاب", PublishDate = new DateTime(2024, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789777954648" },
            new { Id = 709, Name = "احذر ياتيكى", Price = 250m, Stock = 10, Description = "«تِيكِي: أنَا شُجاعٌ، لَكِنَّ أبِي وَأُمِّي يَقُولانِ لِي دَائمًا: لا ..لا ..لا..\nلا تَذْهَبْ بَعِيدًا، كُنْ حَذِرًا..\nفَأخَافُ أنْ أفْعَل أيْ شَيْء».\nيُبَالِغ الأبُّ والأمُّ في مُراقَبَة ابْنِهما تِيكِي والخَوف عَليه مِن أيْ فِعل أو حَركَة أو لُعبَة، سَواءً في الحَدِيقَة أو المَطْبَخ أو البَيْت. الأوَامِر كَثيرَة لدَرجَة تَخنُق تِيكِي.. فَهلْ يَنجَح تِيكِي في إقنَاع وَالدَيه بِالتَّوازُن بيْن الخَوف عَليْه وَحَقِّه في تَجربَة الأشْيَاء؟\nاسم المؤلف :- جرو دال\nاسم المترجم :- شيرين عبد الوهاب\nسنة النشر :- 2024\n\nترجمة شيرين عبد الوهاب", CategoryId = 11, ImageUrl = "/images/products/9789777954655.webp", Author = "جرو دال", PublishDate = new DateTime(2024, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789777954655" },
            new { Id = 710, Name = "تكامل المعرفة فى ضوء ادارة المعرفة", Price = 425m, Stock = 10, Description = "يتناول هذا الكتاب موضوع تكامل المعرفة Knowledge Integration في إطار مفهوم إدارة المعرفة وعملياتها وما يقدمه التكامل لمنظومة أصحاب المصلحة في المنظمة الواحدة أو منظمات ترتبط بأعمال وأهداف مشتركة. ويقدم الكتاب في ثمانية فصول تسلسلًا لموضوعات مهمة في إطار تكامل المعرفة، فبدأ بالتقديم لإدارة المعرفة واستراتيجياتها في فصلين كتوطئة نظرية مهمة للموضوع قبل الانتقال إلى تقديم مدخل نظري لتكامل المعرفة، وإطار تكامل المعرفة والعوامل المؤثرة، وعمليات تكامل المعرفة: المناهج والآليات والتحديات. ولم يغفل الكتاب طرح التطبيقات التقنية فطرح في الفصل السادس منصات تكامل المعرفة، وفي الفصل السابع تطبيقات الذكاء الاصطناعي في دعم عمليات وأساليب تكامل المعرفة. وفي الفصل الثامن الختامي للكتاب يقدم تطبيقًا وحالة تتناول نموذجًا مقترحًا لتكامل المعرفة يساهم في حماية الطفل ويوفر للجهات ذات العلاقة رؤية لإمكانية تطبيق هذا المفهوم لمصلحة الطفل وتحسين أداء عمل الجهات.\nـــــــــــــــــــــــــــــــ\nالدكتورة ضحى حسن السريحي. حاصلة على درجة الدكتوراه في إدارة المعرفة بامتياز من جامعة الملك عبد العزيز، كما حصلت على درجة الماجستير في إدارة المعلومات بامتياز. حصلت على جائزة أفضل رسالة دكتوراه عربيًّا لعام 2023م المقدمة من الاتحاد العربي للمكتبات والمعلومات (اعلم). شاركت بأربعة أبحاث في مؤتمرات عربية، خليجية ووطنية، كما قدمت عددًا من المحاضرات المتنوعة وهي محكم معتمد في مجلتين علميتين. شاركت في هاكثون الأسرة الثاني لعام 2021م، تعمل في المجال التطوعي للطفل وعضو في جمعية طفولة آمنة إضافة لعضويتها في اعلم وجمعية المكتبات المتخصصة – فرع الخليج العربي.\nاسم المؤلف :- ضحى حسن السريحى\nسنة النشر :- 2024", CategoryId = 8, ImageUrl = "/images/products/9789777954570.webp", Author = "ضحى بنت حسن السريحي", PublishDate = new DateTime(2024, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789777954570" },
            new { Id = 711, Name = "علم التاريخ", Price = 185m, Stock = 10, Description = "هذا كتابٌ مؤسِّسٌ في موضوعه ، قسَّمه مؤلِّفه إلى ثمانية فصول، تساءل في أوَّلها : هل التَّارِيخ عِلْم؟ وتَوَصَّل أنه عِلْمُ نَقْدٍ وتحقيق يدرس فيه المؤرِّخ الآثار المتخلِّفة عن الماضي ليُفَسِّر بواسطتها وبقدر الإمكان ظاهرة الحاضر ويعتمد في ذلك على الآثار المادِّية والسِّجِلَّات والتقاليد التي سَلِمَت مصادفة واتِّفاقًا من عوادي الزَّمَن. وتناوَل في بقية فصوله التواريخ والمؤرِّخين المشارقة واليونان والرُّومَان ومؤرخي العصور الوسطى الأوروبية مع إشارة إلى مؤرِّخي العرب . ثم درس تَطَوُّر التَّارِيخ ودراسته من القرن الخامس عشر إلى القرن التاسع عشر، مع بداية عصر النهضة الأوروبية وأثر الصراع الدِّينِي في إذكاء البحث التَّارِيخِي ، والطرائق الجديدة المستخدَمة في البحث التَّارِيخِي خاصَّة بعد اختراع الطباعة مما أدّى إلى بداية الاهتمام بالنَّشْر النَّقْدِي للنصوص القديمة. ثم رُوَّاد التَّارِيخ الحديث وتأثير الفلسفة الوضعية عليهم. وفوائد التاريخ في برامج التربية والتعليم وفي الحياة المدنية والحياة العامة وفوائده في إعداد الفرد للحياة المدنية والحياة السياسية وضرر اتخاذه وسيلة لنشر الدعاية السياسية.\nاسم المؤلف :- الاستاذ هرنشو\nسنة النشر :- 2024", CategoryId = 7, ImageUrl = "/images/products/9789777954587.webp", Author = "الاستاذ هرنشو", PublishDate = new DateTime(2024, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789777954587" },
            new { Id = 712, Name = "مقامات الغضب", Price = 245m, Stock = 10, Description = "\"سلوى: ولأنني أعرف هذه الحقيقة.. لم تغرني الصلابة التي غلفتني، ما إن تنجرح القشرة حتى تظهر الحقيقة الرخوة. اللواء يسري صالح: لا شيء أنتظره، وكل ما حدث وما سيحدث نتيجة، والأسباب تم زرعها منذ سنوات، في السر أو في العلن، لا شيء أنتظره، وما أنتظره لا يتصل قبل أن يأتي\". *** هذه رواية اللحظة الراهنة.. عائلة لا يعرف أفرادها الاتزان، فيقفون على طرفي النقيض إما التمرد والغضب أو الخنوع والاستسلام، وكلٌّ يدفع الثمن. يخافون الفشل، لكن الانكسار هو الفخ الذي يقعون فيه. تتقاطع مصائر الشخوص مع مصير الوطن في لحظات سياسية واجتماعية حرجة، حيث يمتزج الحب بالخيانة، الأمومة بالعجز، اليقين بالشك، الإيمان بالإلحاد، ويشكل الغضب الممزوج بالوجع الوعي بالحياة. تتناوب مقامات الغضب بأصوات شخصياتها ما بين المغامرة والحيرة والترقب والترحال. ـــــــــــــــــــــــــــــــــ\nد. صفاء النجار. حاصلة على الدكتوراه من كلية الإعلام جامعة القاهرة. المحرر الأدبي لجريدة الدستور المصرية. مقدمة برنامج \"أطياف\" شبكة تلفزيون \"الحياة\". صدرت لها روايتا: \"استقالة ملك الموت\"، \"حسن الختام\". والمجموعات القصصية: \"البنت التي سرقت طول أخيها\"، \"الحور العين تفصص البسلة\"، \"الدرويشة\".\nاسم المؤلف :- صفاء النجار\nسنة النشر :- 2024", CategoryId = 1, ImageUrl = "/images/products/9789777954600.webp", Author = "صفاء النجار", PublishDate = new DateTime(2024, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789777954600" },
            new { Id = 713, Name = "شطر الايمان الطهارتان الصغرى والكبرى ونائبهما", Price = 275m, Stock = 10, Description = "(1) خطوة في طريق الوعي الفقهي لمسائل الوضوء والغسل والتيمم.\n(2) اختصار في موضوعه لموسوعات فقهية غارقة في التفريعات والاختلافات لمذاهب الحنفية والمالكية والشافعية والحنابلة والظاهرية والإمامية.\n(3) كاشف لسماحة الدّين بقلّة مسائله الإجماعيّة، وكثرة مسائله الخلافية المتّسعة لأوضاع الناس، ومتغيراتهم المتجدّدة.\n(4) انتصار للبسطاء المغلوبين بالإفتئات عليهم، وتمكينهم من استرداد رشدهم الدّيني بحق الاختيار الفقهي، والفتيا للنفس؛ كما أمر الرسول j، وليكون \"كلُّ أحد فقيه نفسه\"؛ كما قال الشاطبي ت 790 هـ.\n(5) إحياء لحق فقه الدِّين للجميع، وأنه طريق القضاء على مخاطر التقليد، وخبائث المتاجرة الدّينية.\nالدكتور. سعد الدين هلالي\nأستاذ الفقه المقارن بجامعة الأزهر\nاسم المؤلف :- سعد الدين الهلالى \nسنة النشر :- 2024", CategoryId = 8, ImageUrl = "/images/products/9789777954563.webp", Author = "الدكتور سعد الدين هلالي", PublishDate = new DateTime(2024, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789777954563" },
            new { Id = 714, Name = "سيادة القاضى", Price = 245m, Stock = 10, Description = "‏سيادة القاضي\nإعتادت \"عبد المجيد\" أن تفاجئ قرائها بإقتحام مناطق قد يُحجم عن اقتحامها الكثير من الُكتاب..\nفي هذه الرواية تقدم قصة واقعية من ملفات القضايا ورغم الصعوبة والمحاذير إلا أنها تؤمن أن رسالة الكاتب الصادق أن يفتح أعين القراء على كثير مما  نحاول إغماض أعيننا عنه..\nفي ثنائيتها \"أنا شهيرة\" \"أنا الخائن\" ناقشت الخيانة الزوجية بشكل غير مسبوق و من وجهة نظر كلا الطرفين ..\nو في رواية \"كان\" ألقت الضوء على عنصرية الغرب و ازدواجيته ايضا في سياق لم يطرح من قبل..\n\"سيادة القاضي\" رواية استثنائية لكاتبة قال عنها الكاتب والناقد الكبير دكتور\" جلال أمين\" يوما أنها جديرة  بمكانة متميزة في الأدب العربي الحديث!\nــــــــــــــــــــ\nنور عبد المجيد. شاعرة وروائية. شغلت منصب مدير تحرير مجلة \"مدى\" وظهر لها في الشعر ديوان \"وعادت سندريلا حافية القدمين\". وفي الرواية \"رغم الفراق\"، و\"أريد رجلاً\"، و\"أحلام ممنوعة\"، و\"صولو\"، و\"أنتِ مني\" و\"كان\" وروايات أخرى.. وتم تحويل رواياتها إلى أعمال درامية.\nاسم المؤلف :- نور عبد المجيد\nسنة النشر :- 2024", CategoryId = 1, ImageUrl = "/images/products/9789777954464.webp", Author = "نور عبد المجيد", PublishDate = new DateTime(2024, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789777954464" },
            new { Id = 715, Name = "وكأنه الحب", Price = 250m, Stock = 10, Description = "وكأنه  الحب\n              غادر أنطونيو الغرفة مندفعًا، دون تردد، تنهار مليكة وتلقي بجسدها على \"الفوتيه\" تبكي بكاءً هيستيريًّا، تشرد في مشاهد من أحلام يقظتها، هي وأنطونيو يركضان معًا في حدائق قصور الحمراء، بين نوافيرها، وأشجار الرمان، يمد يده ويقطف لها ثمرة رمان، يشقها ويفصص الحب، ويطعمها بيده كأنها طفلته الصغيرة، هكذا تحب مليكة أن يدللها أنطونيو. تسأل نفسها: هل انتهى كل شيء؟ هل استيقظت من الحلم الجميل هكذا، بهذه السرعة؟ ـــــــــــــــــــــــــــــــ\nنوال مصطفى، أديبة وكاتبة صحفية بدار أخبار اليوم، شغلت منصب رئيس تحرير كتاب اليوم «2005-2012». صدر لها عشرون كتابًا؛ روايتان وثماني مجموعات قصصية وعشرة كتب سير ذاتية لأعلام الثقافة والفن والصحافة المصرية والعربية. حصلت على جائزة الدولة للتفوق في الأدب عن مجمل أعمالها. كما حصلت على العديد من الجوائز أهمها: جائزة مصطفى وعلي أمين لأفضل قصة إنسانية، وجائزة نقابة الصحفيين المصرية لأفضل حوار صحفي.\nاسم المؤلف :- نوال مصطفى\nسنة النشر :- 2024", CategoryId = 1, ImageUrl = "/images/products/9789777954495.webp", Author = "نوال مصطفي", PublishDate = new DateTime(2024, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789777954495" },
            new { Id = 716, Name = "ثلاث طرق للسعادة", Price = 160m, Stock = 10, Description = "عادة، السعادة في معناها العام حالة عاطفية تتميز بمشاعر الفرح والرضا والقبول بما لديك والكثير من المشاعر الإيجابية تجاه العالم. ومع ذلك يظل المعنى الدقيق والمحدد لها وطرق الوصول إليها يختلف من شخص لآخر حسب تكوينه المعرفي والثقافي. فهل يمكن لامرأة جمعت الفصول الأربعة في جسدها، وجمعت بين ثقافة جداتها المصريات منذ إيزيس وحتحور وماعت وجداتها الإيطاليات، صُنع خلطة سرية للوصول إلى المعنى الحقيقي والعميق للسعادة واقتناصها؟ يمكنك البحث عن طرق لصناعة السعادة مع شخصيات الرواية التي توصل كل واحد منهم إلى طريقته الخاصة والأليفة لصناعة المرح، لصناعة السعادة الكاملة كما ينبغي.\nـــــــــــــــــــــــــــــــــ\nد. هويدا صالح. أكاديمة وروائية، صدرت لها عدة روايات ومجموعات قصصية منها: عمرة الدار،  الحجرة 13، بيوت تسكنها الأرواح، جسد ضيق. وفي النقد الأدبي والفني لها: صورة المثقف في الرواية العربية، الهامش الاجتماعي في الأدب، آليات اشتغال التراث في المدونة الروائية العربية.. وفي مجال الترجمة: الحمى الرومانية، أنطولوجيا القصة الأمريكية، موت الفلسفة، الأمير السعيد. عملت بعدد من الجامعات المصرية والعربية لتدريس النقد الأدبي وعلم الجمال. شاركت في تحكيم عدد من الجوائز المصرية والعربية في مجالات الإبداع والنقد الأدبي والنقد الفني. وشاركت في العديد من الأفلام الوثائقية.\nاسم المؤلف :- هويدا صالح\nسنة النشر :- 2024", CategoryId = 1, ImageUrl = "/images/products/9789777954433.webp", Author = "هويدا صالح", PublishDate = new DateTime(2024, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789777954433" },
            new { Id = 717, Name = "العشيق السرى لفراو ميركل", Price = 185m, Stock = 10, Description = "هل للمستشارة الألمانية الشهيرة السيدة أنجيلا ميركل عشيق سري؟ هذا ما يدّعيه، على الأقل، يونس الخطيب الشاب السوري الذي ولد في ألمانيا في أسرة متدينة مهاجرة. تمثل أنجيلا ميركل ليونس لا فقط القيم الألمانية والأوروبية التي يؤمن بها، وإنما ظل يعتبرها \"حب حياته\" في لحظة انفلات غامضة، والتي سيحقق معها خططًا مستقبلية اتفقا على تحقيقها بعد أن تترك منصبها كمستشارة. رواية مهاجرة تطرح سؤال الهوية في خلطة من المتخيل والحلم والتجاوز كتبتها الروائية المغربية ريم نجمي، وتُنشر بعد روايتها \"تشريح الرغبة\" التي قدمت فيها سؤال الهجرة العربية في المنافي الأوروبية القلقة. ـــــــــــــــــــــــــــــــ\nريم نجمي، شاعرة وكاتبة وإعلامية مغربية، من مواليد الدار البيضاء 1987. خريجة المعهد العالي للإعلام والاتصال بالرباط وحاصلة على ماجستير في الإعلام من جامعة بون. تقيم  في برلين وتعمل في مؤسسة \"دويتشه فيله\" الألمانية محررة ومذيعة برامج حوارية. صدر لها رواية »تشريح الرغبة»، وإلى جانب عملها الصحفي تشتغل بالترجمة الأدبية وصدر لها عدد من الأعمال الألمانية المترجمة إلى العربية.\nاسم المؤلف :- ريم نجمى\nسنة النشر :- 2024", CategoryId = 1, ImageUrl = "/images/products/9789777954549.webp", Author = "ريم نجمي", PublishDate = new DateTime(2024, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789777954549" },
            new { Id = 718, Name = "السيناريو دليل احتراف الدراما", Price = 300m, Stock = 10, Description = "هذا الكتاب هو خلاصة رحلة 15 عامًا قضيتُها بين التعلم والتعامل والعمل والتعليم؛ التعلّم على يد مخرجين كبار كرأفت الميهي، وسمير سيف، والتعامل مع آخرين كخالد يوسف، والعمل على أفلام قصيرة وأفلام تسجيلية، والتعليم في سنوات عشر من خلال تدريس السيناريو لطلبةٍ أفخر بهم لأنهم تخرجوا في ورشتي ومارسوا العمل للسينما في جميع أرجاء الوطن العربي؛ يضاف نجاحهم إلى نجاحي، وأحلِّق عاليًا مع كل نجاح لهم. وقد حوى الكتاب الكثير من الموضوعات كنشأة الدراما، والفارق بين المعالجة الدرامية والمعالجة السينمائية، وكيف نسجل الفكرة، وكيف نرسم الشخصية، ونظريات البناء الدرامي، والتيمات الدرامية العالمية، ومدارس كتابة السيناريو، وتطبيقات عربية وأجنبية، وغيرها الكثير ليكون مرجعًا لعشاق الدراما، وقد يستتبع بسلسلة متخصصة في كل موضوع على حدة، فالسيناريو ومدارسه تتطور يومًا عن يوم.  محمد رفيع ـــــــــــــــــــــــــــــــــ\nمحمد رفيع، قاص وروائي وكاتب سيناريو، بكالوريوس علوم حاسب آلي، ودبلوم عام دراسات عليا نقد ومسرح جامعة عين شمس.عضو نقابة السينمائيين المصرية قسم السيناريو، وخريج أكاديمية تكنولوجيا السينما الحديثة للفنون قسم \"السيناريو\"، كتب العديد من السيناريوهات، منها \"الحاوي خطف الطبق\"، و\"معجزة\"، و\"جافتون\"، و\"مدد يا طاهرة\"، و\"كارما\".\nاسم المؤلف :- محمد رفيع\nسنة النشر :- 2024", CategoryId = 8, ImageUrl = "/images/products/9789777954518.webp", Author = "محمد رفيع", PublishDate = new DateTime(2024, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789777954518" },
            new { Id = 719, Name = "عملية تجميل", Price = 150m, Stock = 10, Description = "\"سأعتني بجسدي الذي عشت به سنوات عمري، بكل أفراحي وأحزاني وإحباطاتي وخيباتي وانتصاراتي، لن أمحو تاريخي بحقنة تجعلني أتوقف عند صورة ثابتة قد تصيبني بالجنون. الجمال الثابت في نظري مهما كانت درجته قاتل، الاعتياد حتما يفقدنا الإحساس بقيمته مع مرور الوقت، لن أنصت لنداء التحول الشبابي الذي أصاب المدينة بالجنون\". *** امرأة واحدة في «عملية تجميل» تقاوم جنون الشباب الدائم الذي أصاب المدينة، بسبب حقنة إكسير الشباب ، التي جاء بها طبيب تجميل فضربت المدينة مثل وباء سعيد أتى على ملامح الناس، ولم تلبث عدوى البحث عن مظهر الشباب أن طالت المباني والأشجار. رواية فنتازية أجادت المؤلفة رسمها، تُفجِّر المفارقات المضحكة والمبكية من التقاء الشباب الحقيقيين والشباب المزيفين من متعاطي الإكسير.\nـــــــــــــــــــــــــــــــ\nزينب عفيفي. كاتبة صحفية وروائية، تخرجت في كلية الإعلام جامعة القاهرة، صدر لها سبعة عشر عملًا ما بين قصص قصيرة وكتب وروايات منها: \"شمس تشرق مرتين\"، \"خمس دقائق\"، \"أهداني حبا \"،\"أحلم وأنا بجوارك\"، \"معك تكتمل صورتي\"،\"عزيزي المستبد\". ترجم بعض قصصها إلى الإنجليزية والإيطالية، لها العديد من المقالات الأسبوعية في الأدب والثقافة. حازت على جائزة أفضل صفحة في مجال الكتب عام 5102، وجائزة نقدية في أدب يوسف إدريس.\nاسم المؤلف :- زينب عفيفى\nسنة النشر :- 2024", CategoryId = 1, ImageUrl = "/images/products/9789777954471.webp", Author = "زينب عفيفي", PublishDate = new DateTime(2024, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789777954471" },
            new { Id = 720, Name = "كوش كو", Price = 330m, Stock = 10, Description = "في عام 1091، يصل «كوش كو» إلى القاهرة قادمًا من النوبة مع خاله ليتعلم أصول الخدمة بفندق شبرد. بين أروقة الفندق العريق، وشوارع العاصمة المفعمة بالصخب والحياة، يلتقي كوش بشخصياتٍ متناقضة ويعيش مغامراتٍ لا تقل عنه ثراءً وغرابة، ليدرك أن العالم ليس بالبساطة التي يتصورها. يبحث كوش كو المحب لقراءة الكتب والمجلات والمهووس بالمعرفة عن مكانه في هذا العالم الذي يخبره دومًا أنه مجرد خادم... ولكنه يشعر في قرارة نفسه أنه أكبر من ذلك بكثير.. ***\nفي روايته الرابعة، يصحبنا ولاء كمال إلى مصر فجر القرن العشرين، لنشاهد الخديوية التابعة للسيادة العثمانية تحت الحماية البريطانية كما لم نَرَها من قبل. عبر سردٍ ساحرٍ لا يسقط في فخ الحنين المخادع، وزخمٍ هائلٍ من الأحداث، نعيش قصة حياة كوش كو العجيبة بما تعج به من مغامراتٍ وشخصياتٍ تاريخية مذهلة، ومعايشة وصفية خلّابة تسلط الضوء على سطوة المستعمر الأبيض الغاشمة، ليتحول التاريخ في هذه الرواية إلى فضاء درامي ثري فلا تتوقف عن خطف أنفاسنا حتى صفحاتها الأخيرة. ـــــــــــــــــــــــــــــــــــــ\nولاء كمال كاتب وروائي مصري ولد بإنجلترا ودرس الأدب العربي، الترجمة، الإعلام، والسينما. صدرت له روايات: «سكون»، «سيد والعصابة»، و«القداس الأخير» التي رُشِّحت بالقائمة القصيرة لجائزة ساويرس الثقافية، والدراسة التاريخية الاجتماعية «أيامي مع كايروكي وحكاية جيل أراد أن يغير العالم»، إلى جانب عدد من الأعمال المترجمة، وجميعها صادرة عن الدار المصرية اللبنانية.\nاسم المؤلف :- ولاء كمال\nسنة النشر :- 2024", CategoryId = 1, ImageUrl = "/images/products/9789777954358.webp", Author = "ولاء كمال", PublishDate = new DateTime(2024, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789777954358" },
            new { Id = 721, Name = "يوم اخر للقتل", Price = 160m, Stock = 10, Description = "\"فوق الكوبري القديم راحت تتحسَّس الخطوات بين الزحام لتشاهد غوَّاصيْن يصعدان من الترعة وقد انتشلا جثَّة غريقة. الجثة لفتاةٍ صغيرة، بطنها منتفخٌ، وشعرها يخفي ملامحها، وبمجرد وضعها على ضِفة الترعة، سَتَرَتْهَا بعض النسوة بملاءات ظهرت فجأة، وطلب شيخ البلد من الجميع الانصراف حتى تصل الشرطة، انصرفَت سارة وهي تسمع همهمات تتناهى إلى مسامعها مفادها أن جُثَّة تلك الفتاة لا تنتمي إلى قريتهم\". *** في هذه الرواية، تكشف هناء متولي بشجاعة عن الوجه المظلم لحياة النساء في مجتمع يقتات على الممارسات  السرية والأكاذيب الرهيبة.\nــــــــــــــــــــــــــــــــــ\nهناء متولي، كاتبة مصرية من مواليد محافظة الدقهلية، تخرجت في كلية التجارة جامعة المنصورة، حصلت على جائزة سعاد الصباح للإبداع العربي 2021 عن مجموعتها القصصية \"التنفس ببطء\". منحة مؤسسة مفردات ببروكسل للكتابة الإبداعية عام 2020، صدرت لها رواية \"أسرار سفلية\" عام 2017.\nاسم المؤلف :- هناء متولى\nسنة النشر :- 2024", CategoryId = 1, ImageUrl = "/images/products/9789777954501.webp", Author = "هناء متولي", PublishDate = new DateTime(2024, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789777954501" },
            new { Id = 722, Name = "رجل اسمه الرغبة", Price = 275m, Stock = 10, Description = "\"..أنا خوان رودريغو أمية، سليل دونجوانات الأدب الإنساني، ذئب بريء. أحاول أن أبني مجدًا بآهات النساء، أبدية صغيرة لذكراي. إن قصدت النساء محاكمتي فأنا بريء من دمهن، لم أقتل امرأة بالهجر والإهمال، أنا فقط رجل مصاب بفقدان الذاكرة. أقتل نسائي بالنسيان...\" \"..إن جل الكتاب الذين اعتمدوا التحليل النفسي، في بناء شخصيتي أدبيًّا، اعتمادًا على طبيب النفس العظيم سيغموند فرويد، حين أجلسوني على أريكة التحليل، لم يجدوا في النهاية، سوى ذواتهم المكبوتة، وشخصياتهم المخفية خلف قوانين اجتماعية ودينية صارمة. لكل هذه الأسباب ارتأيت أن أقدم نفسي…لا أريد تأويلات مغرضة ومشفقة تراني كرجل ضحية لشبقه. وأن يقال إن الدونجوانية مصابة برجولة في موضع الشك..\" ـــــــــــــــــــــــــــــــ\nعائشة البصري شاعرة وروائية وقاصة. ترجمت أعمالها للعديد من اللغات الأجنبية. حازت على جائزة كاتب ياسين للرواية. الجزائر 2016، جائزة سيمونْ لانْدْرايْ للشعر. باريس 2017، جائزة معرض الشارقة الدولي للكتاب 2018.\nاسم المؤلف :- عائشة البصرى\nسنة النشر :- 2024", CategoryId = 1, ImageUrl = "/images/products/9789777954532.webp", Author = "عائشة البصري", PublishDate = new DateTime(2024, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789777954532" },
            new { Id = 723, Name = "دماء على السجادة الحمراء", Price = 235m, Stock = 10, Description = "قبل بدء حفل ختام المهرجان السينمائي بدقائق تسيل دماء المنتج الشهير وتتسرب من جسده الحياة. تبدأ التحقيقات، وما بين ذيلٍ مخضب بالدماء وملابس غريبة ملقاة في القمامة وميكروفونات غارقة وسلاح جريمة غائب وشريط مراقبة ممحو، يفقد المحقق بوصلته. فماذا إذا حامت الشكوك حول المحقق نفسه؟! شخوص كثيرة لكل منهم حكايته وعداوته مع المجني عليه.. ويلتبس علينا المشهد، أهي جريمة شغف وليدة لحظة غضب؟ أم جريمة تم التخطيط لها بعناية لتبدو كذلك؟ ما بين هذا وذاك يتخبط فريق التحقيق لكشف غموض جريمة ضاربة بجذورها في الماضي.\nـــــــــــــــــــــــــــــــــ\nنهى داود كاتبة مصرية ولدت في إنجلترا عام 1975 وتخرجت في قسم الاتصالات بكلية الهندسة جامعة القاهرة. عملت بمجالها لعدة سنوات قبل أن يغمرها تيار الشغف، وتجد نفسها عاكفة على كتابة أولى رواياتها البوليسية!. حصلت على دبلومة الكتابة الإبداعية من جامعة ويزليان الأمريكية، وتخصصت في أدب الجريمة. صدر لها 8 روايات منها: جريمة السيدة هـ، ورضا، وجريمة العقار 47، وجثتان والثالثة عند قدمي. حصلت على جائزة الكاتب الأكثر مبيعًا لعامي 2021 و2022 على التوالي من منصة iRead.\nاسم المؤلف :- نهى داود\nسنة النشر :- 2024", CategoryId = 1, ImageUrl = "/images/products/9789777954457.webp", Author = "نهي دادود", PublishDate = new DateTime(2024, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789777954457" },
            new { Id = 724, Name = "القناع الاخير", Price = 245m, Stock = 10, Description = "«اقتربت منه بحركة غريزية فجأة، وأمسكت بكلتا يديه، فقد رأت لدهشتها الشديدة دموعًا غزيرةً تنهمر من عينيه وتغسل وجهه كله، وهو لا يزال في وقفته مطأطئ الرأس صامتًا لا يتحرك، ضغطت بكلتا يديها متسائلةً في تأثرٍ وجزعٍ شديدين: ما بك؟ أجابها بعد لحظاتٍ في صوتٍ متقطعٍ خافتٍ: - بمَ تريدينني أن أجيبك؟ أقول لك إن أمنيتي الوحيدة أن أصحبك بعيدًا عن الناس وأعيش بك ولك مدى الحياة، رغم أنفهم جميعًا ورغم الظروف، كل الظروف، ورغم المشكلات والعراقيل التي تقف في سبيل ارتباطنا؟ أحست بصدق نبراته، وأحست بمدى حيرته ورغبته وتردده وحبه، كلا إنه لا يخدعها هذا الرجل.. إنه لا يكذب إنه يريدها فعلًا ولا يدري كيف السبيل. استطرد وهو ينظر إليها في تعبيرٍ حزين، وهي لا تزال تمسك بكلتا يديه بين يديها. - أتظنين أنه كان من السهل عليَّ أن أخطو إلى منزلك من دون ارتباط، فأسيء إليك أو أخدش كرامتك أو أخطئ في حقك، اللـه يعلم كم أريد لو يبارك حبنا فلا نقترف إثمًا يأباه، لكن كيف السبيل؟ كيف السبيل؟ نتزوج؟ - نتزوج».\nاسم المؤلف :- لوتس عبد الكريم\nسنة النشر :- 2024", CategoryId = 1, ImageUrl = "/images/products/9789777954440.webp", Author = "لوتس عبد الكريم", PublishDate = new DateTime(2024, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789777954440" },
            new { Id = 725, Name = "قصة اخرى للحياة", Price = 220m, Stock = 10, Description = "\"وقَّعت الحركة الأولى حين مست قدمي مقر المجلس، إذ منع القانون قبلًا حضور النساء. كان نصاب المجلس متقلصًا إلى نصفه، يشكله أولئك الذين تخلفوا عن حمل السلاح بسبب السن. تركت فرقة الحرس على الباب ودخلت محاطةً بفتياتي، نرتدي جميعًا العباءات الحمراء، بدونا فاتنات ومخيفات ومزعجات، لهذا تعمدت النظر في العينين المحتجتين لكل واحد منهم بهدوءٍ وندية، وبعد أن جلست وتأكدت أن أحدًا من الحاضرين ليس لديه ما يقول، أخبرتهن أن ينتظرنني بالخارج حتى الانتهاء من الجلسة. لقد بتنا ـ أنا وكيرون ـ نفعل بالضبط ما كان الطبيب يمارسه أعوامًا في الظل، نلهم القائمين على الحكم ونوجههم، لكن بعلم الجميع هذه المرة\". *** ماذا لو كانت العلوم بدأت بالأنثى لكن لأن الذكور هم من يكتبون التاريخ فكان لا بد من نَسبِ الفضل لفيلسوف أو طبيب؟ رحلة خارج التاريخ الحقيقي والمستقبل المنظور، لكن بها أسئلة واقعية عن الدور الحقيقي للمرأة والأم والزوجة والملكة والعالمة والفيلسوفة في صنع العلوم القديمة ووضع إرهاصات العلوم الحديثة. أسئلة عن القصة الحقيقية لدورها.. أو عن القصة الأخرى للحياة.\nـــــــــــــــــــــــــــــــ\nفيبي صبري. تخرجت في كلية الصيدلة بجامعة طنطا. صدرت لها رواية واحدة في عام 2019 هي \"نذر. حكاية هيلانة ويوسف الأرمني\". لها مقالات عدة عن السينما والأدب في العديد من المجلات والمواقع الثقافية.\nاسم المؤلف :- فيبى صبرى\nسنة النشر :- 2024", CategoryId = 1, ImageUrl = "/images/products/9789777954402.webp", Author = "فيبي صبري", PublishDate = new DateTime(2024, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789777954402" },
            new { Id = 726, Name = "ناحوم افندى", Price = 320m, Stock = 10, Description = "«كان حايم أفندي على علاقة بالملك فاروق وكل رجال القصر الملكي وبعددٍ من الساسة المصريين من كل الأحزاب، وقد كان معارضًا للصهيوينة ومشروعها، لكن الرجل في النهاية كان منحازًا لأهله، فإذا كانت هناك دولة يهودية على وشك أن تقوم في فلسطين فليس أمام الحاخام مفر من تأييدها». محمد حسنين هيكل «كيف يمكن للإنسان أن يكون مواطنًا مخلصًا لبلد مولده في حين يكون مواطنًا مواليًا للوطن القومي اليهودي؟!!» ألبرت موصيري *** ما بين رأي «هيكل» واستنكار «موصيري»، تدور التساؤلات في هذا الكتاب حول حقيقة نوايا ناحوم أفندي الحاخام الأخير لليهود المصريين والذي تولى منصبه «1925 - 1960» في فترة تاريخية حرجة نشبت خلالها الصهيونية أظافرها لتجعل مصر بوابةً لعبور اليهود إلى أرض الميعاد المزعومة. إنها رحلة بحث بين معبد عدلي وحي جاردن سيتي، الذي أقام به الحاخام، ومجمع اللغة العربية الذي كان عضوًا به، وأوراق الصحف اليهودية الصادرة في مصر. ـــــــــــــــــــــــــــــــ\n سهير عبد الحميد كاتبة صحفية - نائب رئيس تحرير الأهرام وباحثة في التاريخ. صدر لها خمسة كتب: قصور مصر، إسكندرية من تاني، اغتيال قوت القلوب الدمرداشية، على عتبة المقام ، سلسال الباشا.\n اسم المؤلف :- سهير عبدالحميد\n سنة النشر :- 2024", CategoryId = 7, ImageUrl = "/images/products/9789777954419.webp", Author = "سهير عبد الحميد", PublishDate = new DateTime(2024, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789777954419" },
            new { Id = 727, Name = "العودة الى المستقبل", Price = 365m, Stock = 10, Description = "يرصد المؤلف –من خلال هذا الكتاب- محاولة لفهم التطور الخُلقي للإنسان، وتقييم تاريخنا، قبل الإسلام وبعده، والإسهام في الإجابة على سؤال متكرر في واقعنا العربي منذ أكثر من قرنين: لماذا تأخرت أمة العرب وتقدمت أمم أخرى؟ كما يرصد ويحلل تداعيات بعض الأحداث والمحطات المفصلية التي ساهمت في التأثير على بعض شرائح المجتمع السعودي ومنظومته القيمية والأخلاقية والسلوكية.\nويستعرض لمحة عن برامج ومُبادرات رؤية 2030 في ضوء مرتكزها القِيَمي والأخلاقي، ويغوص في واقع المجتمع السعودي، حتى لا يكون مخطوطة نظرية إنشائية بعيدة عن الواقع أو منفصلة عنه.\nويخلص إلى عرض مقترح لفكرة مشروع (برنامج وطني لتعزيز القيَم والأخلاق والسلوك الحضاري).\nفي النهاية، الكتاب ليس محاولة للتنظير أو فرض أي شيء، وليس جلدًا للذات، إنما وجهة نظر واجتهاد وأمنية تهدف لمزيد من الارتقاء \"الحضاري\" والريادة للوطن.\nــــــــــــــــــــــــــــــــ\nنبيل بن عبد الله الحصين: ولد عام 1959م بمكة المكرمة. حصل على بكالوريوس إدارة أعمال دولية وماجستير إدارة عامة من كاليفورنيا بالولايات المتحدة الأمريكية. عمل مديرًا للشؤون الإدارية والمالية بالملحقية التعليمية السعودية بكاليفورنيا، ثم رئيسًا لقسم الميزانية والتقارير بمحطات الساحل الغربي بالمؤسسة العامة لتحلية المياه بجدة، ثم مديرًا عامًا إقليميًّا للقطاع الغربي بشركة توكيلات الجزيرة للسيارات. وكان عضوًا لمجلس إدارة مؤسسة عكاظ للصحافة والنشر لدورتين متتاليتين ولايزال عضوًا مساهمًا بالمؤسسة.\nاسم المؤلف :- نبيل عبد الله الحصين\nسنة النشر :- 2024", CategoryId = 8, ImageUrl = "/images/products/9789777954334.webp", Author = "نبيل بن عبدالله الحصين", PublishDate = new DateTime(2024, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789777954334" },
            new { Id = 728, Name = "ابناء محى الدين", Price = 365m, Stock = 10, Description = "يقول الكاتب الإنجليزي توماس كارليل: “إن التاريخ هو سِيَر الرجال العظماء”، وهذا الكتاب يتتبع سيرة ومسيرة واحدة من أهم العائلات المصرية، وهي عائلة محيي الدين بكفْر شُكر. فهذه العائلة تفاعلت مع حوادث كبرى في التاريخ  الحديث، وامتدت تأثيراتها إلى الجوانب كافة، وقدَّمت عبر أجيال عدة أفذاذًا لعبوا أدوارًا عظيمة في بناء مؤسسات مصر الكبرى، وساهموا بإيجابية في تحولات لافتة. ومنذ تاريخ الجد المؤسس، الذي قدَّم تجربة فريدة في الصعود الاجتماعي والتأثير السياسي، مرورًا بساسة ونواب متميزين، ثم جيل ثورة يوليو وأهم رموزه زكريا محيي الدين، وخالد محيي الدين، ثم السياسي المخضرم فؤاد محيي الدين، وصولًا إلى الاقتصادي الدولي محمود محيي الدين؛ فإن بصمات هذه العائلة ظلت جليَّة على مؤسسات الدولة المدنية كافة، وهو ما حاول هذا الكتاب قراءته في سردية جديدة تستقرئ المنسي والمُهمَّش في التاريخ المصري.\nــــــــــــــــــــــــــــــــ\nمصطفى عبيد.. روائي وكاتب ومترجم مصري مُهتم بالتاريخ الحديث، صدر له ثلاثة وعشرون كتابًا متنوعًا ما بين التأليف والترجمة، ودخلت معظم كتبه في قوائم الأكثر مبيعًا.", CategoryId = 7, ImageUrl = "/images/products/9789777954198.webp", Author = "مصطفي عبيد", PublishDate = new DateTime(2024, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789777954198" },
            new { Id = 729, Name = "قاموس الروح - التصوف كما يجب ان نعرفه", Price = 275m, Stock = 10, Description = "توالت كتب تحوي مصطلحات الصوفية ومفاهيمها عبر القرون، وبذل الذين التقطوا مفرداتها وصنَّفوها ورتَّبوها جهدًا في رصدها وعرضها، لكنها لم تكن غالبًا سوى اقتباس مما تركه المتصوفة الأوائل، أو نقل أمين عنهم، معتمدة على ما جادوا به في تأملاتهم، وانفعالاتهم، وجيشان عواطفهم، وإلهاماتهم السخية.\nويختلف كتاب \"قاموس الروح\" عما سبقه في قيامه بتأمل مفاهيم متعلقة بالروح خصوصًا، ثم إقامة حوار حولها بين شيخٍ ومريدٍ متخيَّلَين، في محاولة للاقتراب من الأسرار الكبرى لها. وقد تأمل المؤلف الكثير من  المصطلحات الصوفية، وقدم تذوقه وتفكيره الذاتي، ليجلي الغموض الذي يلتبس بعضها عبر أربع سبل هي: السرد والحوار وحضور الصورة وانسياب اللغة، مبحرًا بنا في الأحوال والمقامات والمراتب والفضائل والقيم والوسائل والمعاني.\nإن هذا الكتاب محاولة لإضافة مدماك جديد في بناء التصوف الإسلامي السامق، الذي توالت عليه النوائب والعواصف والتدابير المثبطة والمحبطة، التي أرادت له أن ينهار، لكنه بقي صامدًا في وجه التطرف والخرافة. \nـــــــــــــــــــــــــــــــــــــ\nعمار علي حسن، أديب ومفكر مصري، له أربعة كتب في التصوف، تحوي دراسات وتراجم وتجليات، وله اثنتا عشرة رواية، وثماني مجموعات قصصية، وديوانا شعر، ومسرحية، وكتاب في السيرة الذاتية، إلى جانب خمسة وعشرين كتابًا في علم الاجتماع السياسي والنقد الثقافي والأدبي.\nتعد حول الأعمال الأدبية للكاتب عشرون أطروحة جامعية داخل مصر وخارجها، وكتبت عنها عشرات الدراسات النقدية، وتُرجمت بعض أعماله العلمية والأدبية إلى عدة لغات، ونال عنها عدة جوائز كبرى.\nاسم المؤلف :- عمار على حسن \nسنة النشر :- 2023", CategoryId = 8, ImageUrl = "/images/products/9789777954297.webp", Author = "عمار على حسن", PublishDate = new DateTime(2023, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789777954297" },
            new { Id = 730, Name = "على فراش فرويد", Price = 235m, Stock = 10, Description = "لم تخبر نورا أحدًا بما حدث لها في طفولتها ومراهقتها، اعتادت أن تخفي كل شيء داخلها ولا تبوح بما تشعر به، لكنها في لحظة لم تستطع الكتمان، فابتكرت لعبتها الخاصة، وصارت تستدعيه كل يوم إلى فراشها قبل النوم، تحكي أشياء وتخفي أخرى، ليلة بعد ليلة انكشف كل شيء داخلها، غيرتها، خوفها مما حدث، شعورها بالذنب وبالغضب، ولم يعد أمامها سوى مواجهة ظلامها.\nفي هذه الرواية تغوص نهلة كرم داخل الذات الإنسانية بكل تناقضاتها، الحب والكراهية، الصدق والكذب، البراءة والإثم، لنكتشف مع كل صفحة أن ما يظهر خارج النفس البشرية لا يعادل شيئًا مما داخلها.\nـــــــــــــــــــــــــــــــــــــ\nنهلة كرم: كاتبة مصرية من مواليد عام 1989، تخرجت في كلية الإعلام جامعة القاهرة، صدر لها مجموعتان قصصيتان: \"أن تكون معلقًا في الهواء\" و\"الموت يريد أن أقبل اعتذاره\"، وروايتان: \"المقاعد الخلفية\"، التي حصلت على جائزة ساويرس عام 2019، و\"خدعة الفلامنجو\"، التي وصلت للقائمة الطويلة لكتارا عام 2023.\nاسم المؤلف :- نهلة كرم \nسنة النشر :- 2023", CategoryId = 1, ImageUrl = "/images/products/9789777954310.webp", Author = "نهلة كرم", PublishDate = new DateTime(2023, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789777954310" },
            new { Id = 731, Name = "الأستاذ بشير الكحلى", Price = 200m, Stock = 10, Description = "رجلٌ مريض بجنون العظمة، يُصدق كل ما يقرأ. عمل مدرسًا للتربية الرياضية، وأدار عمله وحياته بصرامة وانضباط ليعوض نفسه عن ضياع أمله الكبير، يعيش في فقاعة وهمية؛ باعتباره مصلحًا اجتماعيًّا، وسياسيًّا بارعًا، وصاحب رسالة سامية؛ يصعب تنفيذُها على أرض الواقع، لكنها تكتسبُ أهميةً كبيرةً ومصداقيةً في ذهنه. رغم ذلك فبشير الكُحلي إنسانٌ قبل كل شيء؛ له دوافعُه ورغباتُه، وله طرُقُه في إشباعِها، ونظرياتٌ يسعى إلى تطبيقها أيضًا.\nالراوي نفسه يلفُّ ويدور حول الشخصية؛ يتداخل مع دوافعها حينًا، ويتأملها من قريبٍ مرة ومن بعيدٍ أخرى، أو يسخرُ منها في بعض الأحيان.\n اسم المؤلف : مينا عادل جيد \nسنة النشر : 2023", CategoryId = 1, ImageUrl = "/images/products/9789777954303.webp", Author = "مينا عادل جيد", PublishDate = new DateTime(2023, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789777954303" },
            new { Id = 732, Name = "الوعد الحق", Price = 110m, Stock = 10, Description = "\"يقول أبو حذيفة للفتى في طريقهما إلى الدار: ويحك يا عنسي! إني لأرى فيك استخفافًا بآلهتنا وازورارًا عنها. أفتراك لم تنس آلهة عنس بعدُ، ولم ترد أن يخلصَ قلبُك لغيرها؟ فيقول الفتى: بأبي أنتَ يا أبا حذيفة! والله ما ذكرتُ آلهة عنس قط؛ فأنساها اليوم أو أستبقي ذكرها في قلبي، وما أعرف أني غدوتُ عليها مُصبحًا أو رحتُ إليها مُمسيًا، أو آمنتُ لها بسلطانٍ. قال أبو حذيفة: فقد صبوتَ إذن عن آلهة آبائك إلى إله النصارى أو اليهود؟ قال الفتى: لقد لقيتُ أولئك وهؤلاء، وسمعتُ منهم ولم أفهم عنهم، ولم أحاول لأحاديثهم فهمًا. قال أبو حذيفة: فليس لك إله إذن؟\". طه حسين من خلال هذه السلسلة، نستحضر الأعمال الإبداعية والتاريخية والدراسات النقدية لعميد الأدب العربي - الدكتور طه حسين، التي جعلت من صاحبها نموذجًا ننظر إليه بفخر ونستلهم تجربته. وما أحوجنا إلى أن تقرأ الأجيال الجديدة هذه الأعمال، التي تقدمها الدار المصرية اللبنانية مع ترجمة وافية عنه، وشروح لبعض الألفاظ، وتعريف بالأعلام والأماكن الواردة فيها، على يد نخبة من الأساتذة؛ كلٌّ في مجاله.\nاسم المؤلف :- طه حسين سنة النشر :- 2023", CategoryId = 8, ImageUrl = "/images/products/9789777954280.webp", Author = "طه حسين", PublishDate = new DateTime(2023, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789777954280" },
            new { Id = 733, Name = "دعاء الكروان", Price = 135m, Stock = 10, Description = "بدأ الحلم \"منذ ذلك الوقت تمّ العهدُ بينك وبيني أيها الطائر العزيز على أن نذكر هذه المأساة، كلما انتصف الليل، حتى نثأر لهذه الفتاة التي غودرت في هذا الفضاء، ثم نذكر هذه المأساة كلما انتصف الليل بعد أن نظفر بالثأر، ليكون في ذكرنا إياها وفاءٌ لهذه النفس التي أُزهقت، ولهذا الدم الذي سُفك، ورضا عن الانتقام وقد ألمّ بالآثم المجرم وردّ الأمرَ إلى نصابه، وأراح هذه النفسَ التي ما زالت تطلب الريَّ حتى تظفر بالثأر من الذين اعتدوا عليها. لبيك لبيك أيها الطائر العزيز! إنا لنلتقي كلما انتصف الليل منذ أعوام وأعوام، فندير بيننا هذا الحديث، أفتدعني أقصّ أطرافًا منه على الناس لعلهم أن يجدوا فيه عظةً تعصم النفوسَ الزكيةَ من أن تُزهقَ، والدماءَ البريئةَ من أن تُراق؟\". طه حسين من خلال هذه السلسلة، نستحضر الأعمال الإبداعية والتاريخية والدراسات النقدية لعميد الأدب العربي - الدكتور طه حسين، التي جعلت من صاحبها نموذجًا ننظر إليه بفخر ونستلهم تجربته. وما أحوجنا إلى أن تقرأ الأجيال الجديدة هذه الأعمال، التي تقدمها الدار المصرية اللبنانية مع ترجمة وافية عنه، وشروح لبعض الألفاظ، وتعريف بالأعلام والأماكن الواردة فيها، على يد نخبة من الأساتذة؛ كلٌّ في مجاله.\n اسم المؤلف :- طه حسين\nسنة النشر :- 2023", CategoryId = 8, ImageUrl = "/images/products/9789777954273.webp", Author = "طه حسين", PublishDate = new DateTime(2023, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789777954273" },
            new { Id = 734, Name = "الفتنة الكبرى عثمان", Price = 185m, Stock = 10, Description = "\"وأكاد أعتقد أن الخلافة الإسلامية كما فهمها أبو بكر وعمر، إنما كانت تجربةً جريئةً توشك أن تكون مغامرةً، ولكنها لم تنتهِ إلى غايتها، ولم يكن من الممكن أن تنتهي إلى غايتها، لأنها أُجريت في غير العصر الذي كان يمكن أن تُجرَى فيه، سبقا بها هذا العصر سبقًا عظيمًا. وما رأيك في أن الإنسانية لم تستطع إلى الآن، على ما جرّبت من تجارب وبلغت من رُقيّ، وعلى ما بلغت من فنون الحُكم وصوَرِ الحكومات، أن تُنشئ نظامًا سياسيًّا يتحقّق فيه العدلُ السياسيّ والاجتماعيّ بين الناس على النحو الذي كان أبو بكر وعمر يريدان أن يحققاه\". طه حسين من خلال هذه السلسلة، نستحضر الأعمال الإبداعية والتاريخية والدراسات النقدية لعميد الأدب العربي - الدكتور طه حسين، التي جعلت من صاحبها نموذجًا ننظر إليه بفخر ونستلهم تجربته. وما أحوجنا إلى أن تقرأ الأجيال الجديدة هذه الأعمال، التي تقدمها الدار المصرية اللبنانية مع ترجمة وافية عنه، وشروح لبعض الألفاظ، وتعريف بالأعلام والأماكن الواردة فيها، على يد نخبة من الأساتذة؛ كلٌّ في مجاله.\n اسم المؤلف :- طه حسين\n سنة النشر :- 2023", CategoryId = 8, ImageUrl = "/images/products/9789777954211.webp", Author = "طه حسين", PublishDate = new DateTime(2023, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789777954211" },
            new { Id = 735, Name = "الشيخان", Price = 140m, Stock = 10, Description = "والأحداث الكبرى التي كانت أيام الشيخين خطيرة في نفسها، تبهر الذين يسمعون أنباءها أو يقرؤونها، فليست في حاجة إلى أن يتكثّر في روايتها المتكثرون، ولا إلى أن يحيطَها الرواةُ بما أحاطوها به من الغلوّ والإسراف؛ فردُّ العرب إلى الإسلام بعد أن جحدوه، وإخراجُ الروم من الشام والجزيرة ومصر وبرقة، وإخراجُ الفرس من العراق والقضاء على سلطانهم في بلادهم؛ كلّ هذه أحداثٌ لا سبيل إلى الشك فيها ولا في وقوعها في هذا العصر القصير أثناء خلافة الشيخين، وهي أحداثٌ تصفُ نفسَها وتدلّ على خطورتها، وليست محتاجةً إلى المبالغة في وصفها؛ لأنها فوق كل مبالغة\". طه حسين من خلال هذه السلسلة، نستحضر الأعمال الإبداعية والتاريخية والدراسات النقدية لعميد الأدب العربي - الدكتور طه حسين، التي جعلت من صاحبها نموذجًا ننظر إليه بفخر ونستلهم تجربته. وما أحوجنا إلى أن تقرأ الأجيال الجديدة هذه الأعمال، التي تقدمها الدار المصرية اللبنانية مع ترجمة وافية عنه، وشروح لبعض الألفاظ، وتعريف بالأعلام والأماكن الواردة فيها، على يد نخبة من الأساتذة؛ كلٌّ في مجاله.\n اسم المؤلف :- طه حسين\n سنة النشر :- 2023", CategoryId = 8, ImageUrl = "/images/products/9789777954266.webp", Author = "طه حسين", PublishDate = new DateTime(2023, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789777954266" },
            new { Id = 736, Name = "وليمة للغربان (نسخة الخليج)", Price = 990m, Stock = 10, Description = "وليمة للغربان (نسخة الخليج) — چورچ ر.ر مارتن. من إصدارات كيان للنشر.", CategoryId = 2, ImageUrl = "/images/products/9789778203431.webp", Author = "چورچ ر.ر مارتن", PublishDate = new DateTime(2026, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778203431", Pages = 1090, Size = "14x20" },
            new { Id = 737, Name = "صدام الملوك سوفت كڤر (نسخة الشرق الأوسط)", Price = 1020m, Stock = 10, Description = "الرواية اللي أسرت قلوب ملايين حول العالم، بترجمة منقَّحة وغلاف جديد كليًّا!\n\n�في «صِدام الملوك»، يواصل چورچ ر. ر. مارتن نسج خيوط ملحمته العظيمة «أغنيَّة الجليد والنَّار».\nبعد موت الملك روبرت باراثيون واللورد إدارد ستارك، تغرق الممالك السَّبع في فوضى عارمة، ويرفع خمسة ملوك راياتهم في صراع لا يرحم على العرش الحديدي، لتبدأ موجة جديدة من الحروب، والتحالفات الغادرة، والعهود التي تُكسر كما تُسفك الدماء.\nفي أراضي النهر والغرب، يخوض روب ستارك معركة تلو معركة للانتقام لأبيه وتأمين مملكته الجديدة.\nوفي العاصمة، يجد تيريُن لانيستر نفسه وسط شبكة معقدة من المؤامرات فيما تستعد المدينة لهجوم ستانِس باراثيون، وتعيش سانزا في قلعة يزداد خطرها يومًا بعد يوم.\nووراء الجدار، يواجه چون سنو تحديات تهدِّد كل ما يعرفه عن الولاء والواجب.\nوفي الشرق في قارَّة أخرى، تواصل دنيرس تارجاريَن رحلتها بين مدن بعيدة، بحثًا عن القوة التى تمكِّنها من استعادة عرش أبيها الضائع.\nومع تصاعد النزاعات، يبدأ صدام هائل سيُعيد رسم خريطة القوة، ويُثبت أن في هذه اللعبة لا مكان للضعفاء، فإمَّا النصر وإمَّا السقوط.", CategoryId = 2, ImageUrl = "/images/products/9789778202960.webp", Author = "چورچ ر.ر مارتن", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778202960", Pages = 1316, Size = "14x20" },
            new { Id = 738, Name = "لعبة العروش - أغنية الجليد والنار(نسخة الشرق الأوسط) هارد كڤر", Price = 1280m, Stock = 10, Description = "«مارتن حكَّاء بالفطرة وخياله واحد في المليون. المسلسل المأخوذ عن سلسلته رائع، لكن الكُتب أفضل كثيرًا». – ستيڤن كينج\n\n«نجحت سلسلة مارتن الخيالية في إشعال خيال الملايين للسَّبب نفسه الذي جعل أعمال هوميروس وسفوكوليس وشيكسپير تدوم عصورًا». – الجارديان\n\n«مارتن الأفضل على الإطلاق بين من يكتبون في مجال الفانتازيا الملحميَّة في العصر الحالي، ولا مبالغة في وصفه بأنه تولكين الأمريكي». – تايم\n\n«موهبة مارتن في الحكي تكاد تكون خارقةً للطَّبيعة». – نيويورك تايمز\n\nفي «لُعبة العروش» يبدأ چورچ ر. ر. مارتن ملحمته الكُبرى «أغنيَّة الجليد والنَّار»، صانعًا تُحفةً أصيلةً تحوي أفضل ما في أدب الفانتازيا من تشويقٍ وغموض ومغامرة على مستوًى يتجاوز الواقع إلى رحاب الخيال الخصب، ومع ذلك لا يقلُّ واقعيَّةً عن أيٍّ من القصص الإنسانيَّة الأخرى، وهو ما أوقعَ ملايين من عُشَّاق الفانتازيا حول العالم في غرام كتابته.\nفي عالمٍ يدوم فيه الصَّيف أعوامًا والشِّتاء عُمرًا بأكمله، تبدأ سُلطة الملك الحاكم في الجنوب تتداعى بعد الظروف الغامضة المحيطة بموت يده اليُمنى الذي خدمه طويلًا بإخلاص، فلا يجد خيارًا إلَّا اللُّجوء إلى أوفى أصدقائه وآخرهم ليعاونه على حُكم البلاد، ويُقرِّر الصَّديق القبول ليَعثُر على حقيقة موت الرَّجل الذي كان بمثابة أبٍ لهما. وفيما تهبُّ الرِّياح الباردة من الشَّمال منذرةً بعودة خطرٍ قديم يُهدِّد بهلاك العالم كلِّه، تدور في قلعة الحُكم عجلة المؤامرات والمكايد بين الحُلفاء والأعداء، ويبدأ صراعٌ جديد على العرش الحديدي. لكن في لُعبة العروش لا تُوجَد منطقةٌ وُسطى، فإمَّا أن تفوز وإمَّا أن تموت.", CategoryId = 2, ImageUrl = "/images/products/9789778202526.webp", Author = "چورچ ر.ر مارتن", PublishDate = new DateTime(2025, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778202526", Pages = 1206, Size = "14x20" },
            new { Id = 739, Name = "يبدأ بنا (نسخة الخليج)", Price = 470m, Stock = 10, Description = "قبل أن ينتهي كل شيء معنا، بدأت القصة مع أطلس. تُسرد كولين هوفر في هذا الكتاب جانب أطلس، الحبيب الذي يعشقه الجمهور، وتشاركنا ما سيحدث في التكملة التي طال انتظارها لكتاب \"ينتهي كل شيء معنا\"، الأكثر مبيعًا في نيويورك تايمز والمُوصوف بأنه \"مهيب ومؤثر\".\n\nلقد استقرّت ليلي وزوجها السابق، رايل، على نمط من التعاون المدني في تربية الأولاد، حين تلتقي ليلي فجأة بحبها الأول، أطلس، مجددًا. بعد فصل دام ما يقارب العامين، تغمرها الفرحة لأنها تشعر بأن الزمن قد وقف إلى جانبها، فتقبل على الفور موعدًا عندما يدعوها أطلس.\n\nلكن حماسها يتلاشى سريعًا عندما تدرك، رغم أنهما لم يعودا متزوجين، أن رايل لا يزال جزءًا كبيرًا من حياتها، وأن أطلس كورريغان هو الشخص الوحيد الذي يكره وجود رايل في حياة زوجته السابقة وابنته.\n\nيتنقل السرد بين وجهات نظر ليلي وأطلس، ويستأنف \"يبدأ كل شيء معنا\" مباشرة من حيث انتهت خاتمة الكتاب المذهل \"ينتهي كل شيء معنا\" الذي وصف بأنه \"قصة مشوقة تقلب النبض\" (حسب سارة بيكانين، مؤلفة \"الجيران المثاليون\"). من خلال الكشف عن المزيد حول ماضي أطلس ومتابعة رحلة ليلي في احتضان فرصة ثانية للحب الحقيقي وسط مواجهة زوج سابق غيور، يثبت الكتاب أن \"لا أحد يقدم قراءة عاطفية كما تفعل كولين هوفر\" (آنا تود، مؤلفة الكتاب الأكثر مبيعًا في نيويورك تايمز).", CategoryId = 4, ImageUrl = "/images/products/9789778201673.webp", Author = "كولين هوفر", PublishDate = new DateTime(2023, 1, 1, 0, 0, 0, DateTimeKind.Utc), TopRated = false, CreatedAt = SeedDate, Isbn = "9789778201673", Pages = 448, Size = "14x20" },
